#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define SPI_CHIP 0
#define SPI_CHANNEL 0
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 500000

static struct gpiod_chip *chip = NULL;
static int spi_fd = -1;

void cleanup() {
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

void signal_handler(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);
    cleanup();
    exit(signum);
}

int main() {
    struct timespec ts;
    uint16_t adc_value;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Initialize SPI
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        cleanup();
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        cleanup();
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set bits per word");
        cleanup();
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set max speed");
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        // Read ADC value from channel 0
        uint8_t tx[] = {1, (8 + SPI_CHANNEL) << 4, 0};
        uint8_t rx[3];
        if (write(spi_fd, tx, sizeof(tx)) != sizeof(tx)) {
            perror("Failed to write to SPI device");
            cleanup();
            return EXIT_FAILURE;
        }
        if (read(spi_fd, rx, sizeof(rx)) != sizeof(rx)) {
            perror("Failed to read from SPI device");
            cleanup();
            return EXIT_FAILURE;
        }

        adc_value = ((rx[1] & 3) << 8) | rx[2];

        // Get current timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("Failed to get current time");
            cleanup();
            return EXIT_FAILURE;
        }

        // Print timestamp and ADC value
        printf("%ld.%09ld: ADC Value = %d\n", ts.tv_sec, ts.tv_nsec, adc_value);

        // Sleep for 1 second
        sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

