#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define GPIO_FLAME 4
#define GPIO_CE0 8
#define ADC_CHANNEL 0

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int read_flame_sensor(struct gpiod_chip *chip) {
    struct gpiod_line *line;
    int value;

    line = gpiod_chip_get_line(chip, GPIO_FLAME);
    if (!line) {
        perror("Failed to get flame sensor line");
        return -1;
    }

    if (gpiod_line_request_input(line, "flame_sensor") < 0) {
        perror("Failed to request input for flame sensor line");
        gpiod_line_release(line);
        return -1;
    }

    value = gpiod_line_get_value(line);
    gpiod_line_release(line);

    return value;
}

int read_adc_channel(int channel) {
    int value;

    if (gpioRead(channel) < 0) {
        perror("Failed to read ADC channel");
        return -1;
    }

    value = gpioRead(channel);
    return value;
}

void log_data(const char *filename, int flame_detected, int adc_value) {
    FILE *file;
    time_t now;
    struct tm *tm_info;
    char timestamp[20];

    file = fopen(filename, "a");
    if (!file) {
        perror("Failed to open file for logging");
        return;
    }

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(file, "%s,%d,%d\n", timestamp, flame_detected, adc_value);
    fclose(file);
}

int main() {
    struct gpiod_chip *chip;
    int adc_value, flame_detected;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_CE0, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO_CE0 mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(GPIO_CE0, 0);

    if (gpioSetMode(GPIO_FLAME, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO_FLAME mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(GPIO_FLAME, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set GPIO_FLAME pull-up/pull-down\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ADC_CHANNEL, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set ADC channel mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(ADC_CHANNEL, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set ADC channel pull-up/pull-down\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        flame_detected = read_flame_sensor(chip);
        if (flame_detected < 0) {
            fprintf(stderr, "Flame sensor read failed, skipping entry\n");
            continue;
        }

        adc_value = read_adc_channel(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed, skipping entry\n");
            continue;
        }

        log_data("flame_data.csv", flame_detected, adc_value);
        sleep(1);
    }

    gpiod_chip_close(chip);
    gpioTerminate();

    return EXIT_SUCCESS;
}

