#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <sys/ioctl.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 27
#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDRESS 0x48
#define ADS1115_CONFIG 0x4000 | (0 << 12) | (0 << 11) | (0 << 10) | (0 << 9) | (0 << 8) | (0 << 7) | (0 << 6) | (0 << 5) | (0 << 4) | (0 << 3) | (0 << 2) | (0 << 1) | (0 << 0)
#define ADS1115_CONVERSION 0x00
#define LOG_FILE "fire_log.txt"
#define DEBOUNCE_TIME 50
#define POLL_TIME 100
#define FIRE_TEMP 60

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *flame_sensor, *buzzer;
    int i2c_fd;
    uint16_t adc_value;
    float temperature;
    FILE *log_file;
    struct timespec start, end;
    int debounce_count = 0;

    // Initialize GPIO
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    flame_sensor = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!flame_sensor) {
        perror("Failed to get flame sensor line");
        gpiod_chip_close(chip);
        return 1;
    }

    buzzer = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer) {
        perror("Failed to get buzzer line");
        gpiod_line_release(flame_sensor);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_input(flame_sensor, "flame_sensor") < 0) {
        perror("Failed to request flame sensor input");
        gpiod_line_release(flame_sensor);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(buzzer, "buzzer", 0) < 0) {
        perror("Failed to request buzzer output");
        gpiod_line_release(flame_sensor);
        gpiod_chip_close(chip);
        return 1;
    }

    // Initialize I2C
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpiod_line_release(flame_sensor);
        gpiod_chip_close(chip);
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        gpiod_line_release(flame_sensor);
        gpiod_chip_close(chip);
        return 1;
    }

    // Initialize log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        gpiod_line_release(flame_sensor);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    while (running) {
        int flame_state = gpiod_line_get_value(flame_sensor);
        if (flame_state == 1) {
            if (debounce_count < DEBOUNCE_TIME) {
                debounce_count++;
            } else {
                if (gpiod_line_get_value(flame_sensor) == 1) {
                    // Check temperature
                    if (read(i2c_fd, &adc_value, 2) != 2) {
                        perror("Failed to read ADC value");
                        continue;
                    }
                    temperature = (adc_value * 4.096) / 32767.0 * 100.0;
                    if (temperature > FIRE_TEMP) {
                        fprintf(log_file, "%ld: Temperature exceeds %d°C: %.2f°C\n", time(NULL), FIRE_TEMP, temperature);
                    } else {
                        fprintf(log_file, "%ld: Flame detected!\n", time(NULL));
                    }
                }
                debounce_count = 0;
            }
        } else {
            debounce_count = 0;
        }

        // Check for fire condition
        if (gpiod_line_get_value(flame_sensor) == 1 && temperature > FIRE_TEMP) {
            if (gpiod_line_get_value(buzzer) == 0) {
                gpiod_line_set_value(buzzer, 1);
                clock_gettime(CLOCK_MONOTONIC, &start);
                while (running && (clock_gettime(CLOCK_MONOTONIC, &end), (end.tv_sec - start.tv_sec) < 2)) {
                    usleep(10000);
                }
                gpiod_line_set_value(buzzer, 0);
            }
        }

        usleep(POLL_TIME * 1000);
    }

    // Clean up
    gpiod_line_release(flame_sensor);
    gpiod_chip_close(chip);
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

