#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <libgpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip0"
#define GPIO_CHIP_FALLBACK "gpiochip0"
#define GPIO_LINE 18
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SAMPLE_INTERVAL 1
#define CURRENT_THRESHOLD 1000  // Example threshold, adjust as needed
#define LOG_FILE "current_log.txt"

static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;

void log_reading(int adc_value) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(log_file, "%04d-%02d-%02dT%02d:%02d:%02dZ: ADC Value = %d\n",
            tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
            tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec, adc_value);
    fclose(log_file);
}

int read_adc() {
    uint8_t tx[] = {0b11010000, 0b00000000};
    uint8_t rx[3];
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(rx),
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    if (rx[1] == 0 && rx[2] == 0) {
        fprintf(stderr, "Sensor absent or all-zero reading\n");
        return -1;
    }

    if (rx[1] == 0xFF && rx[2] == 0xFF) {
        fprintf(stderr, "Sensor absent or all-one reading\n");
        return -1;
    }

    return ((rx[1] & 0x3F) << 8) | rx[2];
}

void set_fan_state(int state) {
    if (gpiod_line_set_value(gpio_line, state) < 0) {
        perror("Failed to set fan state");
    }
}

void cleanup() {
    if (gpio_line) {
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    set_fan_state(0);
}

void signal_handler(int signum) {
    cleanup();
    exit(signum);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set SIGINT handler");
        return EXIT_FAILURE;
    }

    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set SIGTERM handler");
        return EXIT_FAILURE;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP_FALLBACK);
        if (!gpio_chip) {
            perror("Failed to open GPIO chip");
            close(spi_fd);
            return EXIT_FAILURE;
        }
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_LINE);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(gpio_line, "fan_control", 0) < 0) {
        perror("Failed to request GPIO line for output");
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        int adc_value = read_adc();
        if (adc_value >= 0) {
            log_reading(adc_value);
            set_fan_state(adc_value > CURRENT_THRESHOLD);
        }
        sleep(SAMPLE_INTERVAL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

