    exit(0);
}

void handle_signal(int sig) {
    cleanup();
}

int read_ads1115_raw_value(int fd) {
    uint8_t buffer[3];
    if (read(fd, buffer, sizeof(buffer)) != sizeof(buffer)) {
        perror("Failed to read from ADS1115");
        return -1;
    }
    return (buffer[0] << 16) | (buffer[1] << 8) | buffer[2];
}

float convert_raw_to_ppm(int raw_value) {
    // Placeholder for actual conversion formula
    // Replace with the actual calibration curve
    return (float)raw_value * 0.01; // Example conversion
}

int main() {
    struct timespec ts;
    FILE *log_file;

    // Initialize signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize I2C
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize GPIO chip (if needed)
