    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        int raw_value = read_ads1115_raw_value(i2c_fd);
        if (raw_value >= 0) {
            float ppm = convert_raw_to_ppm(raw_value);
            clock_gettime(CLOCK_REALTIME, &ts);
            fprintf(log_file, "%ld.%09ld, %.2f ppm\n", ts.tv_sec, ts.tv_nsec, ppm);
            fflush(log_file);
        }
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup
    fclose(log_file);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

