#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define MCP3008_CS_PIN 8
#define MCP3008_SPI_CHANNEL 0
#define SPI_SPEED 1000000

static struct gpiod_chip *chip;
static struct gpiod_line *flame_sensor_line;
static int spi_handle;

void cleanup() {
    if (flame_sensor_line) {
        gpiod_line_release(flame_sensor_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (spi_handle >= 0) {
        gpioTerminate();
    }
    exit(EXIT_FAILURE);
}

void signal_handler(int sig) {
    cleanup();
}

int read_flame_sensor() {
    int value = gpiod_line_get_value(flame_sensor_line);
    if (value < 0) {
        fprintf(stderr, "Failed to read flame sensor\n");
        return -1;
    }
    return value;
}

int read_mcp3008_channel(int channel) {
    uint8_t tx[3] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];

    if (gpioSPIDataRW(MCP3008_SPI_CHANNEL, tx, 3, rx) < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 3) << 8) | rx[2];
}

int main() {
    struct timespec ts;
    FILE *csv_file;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to set signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    flame_sensor_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!flame_sensor_line) {
        fprintf(stderr, "Failed to get flame sensor line\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(flame_sensor_line, "flame_sensor") < 0) {
        fprintf(stderr, "Failed to request input for flame sensor\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    spi_handle = gpioOpenSPI(MCP3008_SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI handle\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    csv_file = fopen("flame_data.csv", "w");
    if (!csv_file) {
        fprintf(stderr, "Failed to open CSV file\n");
        gpioCloseSPI(spi_handle);
        gpiod_chip_close(chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(csv_file, "Timestamp,Flame_Presence,Temperature\n");

    while (1) {
        if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
            fprintf(stderr, "Failed to get current time\n");
            continue;
        }

        int flame_presence = read_flame_sensor();
        if (flame_presence < 0) {
            continue;
        }

        int temperature = read_mcp3008_channel(0);
        if (temperature < 0) {
            continue;
        }

        fprintf(csv_file, "%ld.%09ld,%d,%d\n", ts.tv_sec, ts.tv_nsec, flame_presence, temperature);
        fflush(csv_file);

        sleep(1);
    }

    fclose(csv_file);
    gpioCloseSPI(spi_handle);
    gpiod_chip_close(chip);
    gpioTerminate();

    return EXIT_SUCCESS;
}

