#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 500000

#define GPIO_LED 27
#define GPIO_CE0 8
#define GPIO_CE1 9

#define SAMPLE_WINDOW 100
#define SAMPLE_INTERVAL 1
#define HIGH_LEVEL_THRESHOLD 0.5

struct gpiod_chip *chip;
struct gpiod_line *led_line;
struct gpiod_line *ce0_line;
struct gpiod_line *ce1_line;

void cleanup() {
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (ce0_line) {
        gpiod_line_release(ce0_line);
    }
    if (ce1_line) {
        gpiod_line_release(ce1_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    printf("Cleanup complete.\n");
}

void handle_sigint(int sig) {
    cleanup();
    exit(0);
}

uint16_t read_adc(int fd, int channel) {
    uint8_t tx[3] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    if (write(fd, tx, 3) != 3) {
        perror("Failed to write to SPI device");
        exit(EXIT_FAILURE);
    }
    if (read(fd, rx, 3) != 3) {
        perror("Failed to read from SPI device");
        exit(EXIT_FAILURE);
    }
    return ((rx[1] & 3) << 8) | rx[2];
}

double calculate_rms(uint16_t *samples, int count) {
    double sum = 0.0;
    for (int i = 0; i < count; i++) {
        sum += samples[i] * samples[i];
    }
    return sqrt(sum / count);
}

int main() {
    int fd;
    uint16_t mic1_samples[SAMPLE_WINDOW];
    uint16_t mic2_samples[SAMPLE_WINDOW];
    double mic1_rms, mic2_rms;
    time_t start_time = time(NULL);
    FILE *log_file = fopen("audio_events.csv", "w");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    led_line = gpiod_chip_get_line(chip, GPIO_LED);
    if (!led_line) {
        perror("Failed to get LED line");
        cleanup();
        exit(EXIT_FAILURE);
    }

    ce0_line = gpiod_chip_get_line(chip, GPIO_CE0);
    if (!ce0_line) {
        perror("Failed to get CE0 line");
        cleanup();
        exit(EXIT_FAILURE);
    }

    ce1_line = gpiod_chip_get_line(chip, GPIO_CE1);
    if (!ce1_line) {
        perror("Failed to get CE1 line");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(led_line, "audio_led", 0) < 0) {
        perror("Failed to request LED line");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(ce0_line, "audio_ce0", 0) < 0) {
        perror("Failed to request CE0 line");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(ce1_line, "audio_ce1", 0) < 0) {
        perror("Failed to request CE1 line");
        cleanup();
        exit(EXIT_FAILURE);
    }

    // Initialize SPI
    fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set SPI bits per word");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        cleanup();
        exit(EXIT_FAILURE);
    }

    // Set up signal handler
    signal(SIGINT, handle_sigint);

    while (1) {
        for (int i = 0; i < SAMPLE_WINDOW; i++) {
            mic1_samples[i] = read_adc(fd, 0);
            mic2_samples[i] = read_adc(fd, 1);
            usleep(SAMPLE_INTERVAL * 1000);
        }

        mic1_rms = calculate_rms(mic1_samples, SAMPLE_WINDOW);
        mic2_rms = calculate_rms(mic2_samples, SAMPLE_WINDOW);

        time_t current_time = time(NULL);
        fprintf(log_file, "%ld,%f,%f\n", current_time - start_time, mic1_rms, mic2_rms);
        fflush(log_file);

        if (mic1_rms > HIGH_LEVEL_THRESHOLD || mic2_rms > HIGH_LEVEL_THRESHOLD) {
            gpiod_line_set_value(led_line, 1);
            usleep(500 * 1000);
            gpiod_line_set_value(led_line, 0);
        }
    }

    cleanup();
    fclose(log_file);
    return 0;
}

