#define CIRCULAR_BUFFER_SIZE 100
#define CURRENT_THRESHOLD 50.0
#define LED_PIN 17

struct circular_buffer {
    int buffer[CIRCULAR_BUFFER_SIZE];
    int head;
    int count;
};

struct gpiod_chip *chip;
struct gpiod_line *led_line;
int i2c_fd;
struct circular_buffer cb;

void init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void init_led() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(led_line, "current_sensor_led", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
}

void init_circular_buffer() {
    cb.head = 0;
    cb.count = 0;
}

void read_sensor() {
    uint16_t config = ADS1115_CONFIG_MODE_CONTINUOUS | ADS1115_CONFIG_CHANNEL_A0 | ADS1115_CONFIG_GAIN_1 | ADS1115_CONFIG_DATA_RATE_10;
    if (write(i2c_fd, &config, 2) != 2) {
        perror("Failed to write to ADS1115 config register");
        return;
    }

    usleep(ADS1115_CONVERSION_TIME);

    uint16_t conversion;
    if (read(i2c_fd, &conversion, 2) != 2) {
        perror("Failed to read from ADS1115 conversion register");
        return;
    }

    int16_t raw_value = (conversion >> 4) & 0x0FFF;
    int voltage = (raw_value * 4096) / 32767; // 4.096V reference voltage
    double current = (double)voltage / 0.0625; // 0.0625V per A

    if (cb.count == CIRCULAR_BUFFER_SIZE) {
        cb.head = (cb.head + 1) % CIRCULAR_BUFFER_SIZE;
    } else {
        cb.count++;
    }

    cb.buffer[cb.head] = current;
}

void calculate_average(double *average) {
    *average = 0.0;
    for (int i = 0; i < cb.count; i++) {
        *average += cb.buffer[i];
    }
    *average /= cb.count;
}

void check_threshold() {
    double average;
    calculate_average(&average);
    if (average > CURRENT_THRESHOLD) {
        gpiod_line_set_value(led_line, 1);
    } else {
        gpiod_line_set_value(led_line, 0);
    }
}

void cleanup() {
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    close(i2c_fd);
}

void signal_handler(int sig) {
    cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, signal_handler);

    init_i2c();
    init_led();
    init_circular_buffer();

    while (1) {
        read_sensor();
        check_threshold();
        sleep(1);
    }

    cleanup();
    return 0;
}
```

This C program for a Raspberry Pi 4 Model B samples the analog output of a Melexis MLX91204 Hall effect current sensor using an ADS1115 ADC on I2C bus 1. It reads single-ended on channel A0 at a rate of 10 Hz, converts the raw values to current, stores each converted reading in a circular buffer of 100 elements, and triggers a warning LED on GPIO17 BCM whenever the average of the buffered currents exceeds a 50.0 A threshold. The program includes robust error handling for driver initialization, I2C reads, and sensor-absent conditions, and handles SIGINT (Ctrl+C) to perform a graceful shutdown that turns off the LED and releases all resources cleanly on every exit path.

