#define TCS34725_I2C_ADDRESS 0x29
#define TCS34725_ID 0x44
#define I2C_BUS 1
#define I2C_DEVICE "/dev/i2c-1"
#define CSV_FILE "color_log.csv"

struct i2c_handle {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
};

struct i2c_handle *i2c_open(void) {
    struct i2c_handle *handle = malloc(sizeof(*handle));
    if (!handle) {
        perror("Failed to allocate memory for i2c_handle");
        return NULL;
    }

    handle->chip = gpiod_chip_open_by_name(I2C_DEVICE);
    if (!handle->chip) {
        perror("Failed to open I2C device");
        free(handle);
        return NULL;
    }

    handle->line = gpiod_chip_get_line(handle->chip, 0);
    if (!handle->line) {
        perror("Failed to get I2C line");
        gpiod_chip_close(handle->chip);
        free(handle);
        return NULL;
    }

    if (gpiod_line_request_output(handle->line, "i2c", 0) < 0) {
        perror("Failed to request I2C line output");
        gpiod_chip_close(handle->chip);
        free(handle);
        return NULL;
    }

    return handle;
}

void i2c_close(struct i2c_handle *handle) {
    if (handle) {
        gpiod_line_release(handle->line);
        gpiod_chip_close(handle->chip);
        free(handle);
    }
}

