#define GPIO_DEVICE "/dev/gpiochip0"
#define MCP3008_CHANNEL 0
#define MOTOR_SHUTDOWN_PIN 17
#define MAX_SPI_RETRIES 3
#define CURRENT_THRESHOLD 10.0

int spi_fd = -1;
int gpio_fd = -1;
int motor_shutdown_fd = -1;

void close_resources() {
    if (motor_shutdown_fd >= 0) {
        close(motor_shutdown_fd);
    }
    if (gpio_fd >= 0) {
        close(gpio_fd);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
}

void handle_signal(int signum) {
    close_resources();
    exit(signum);
}

int read_adc(int channel) {
    uint8_t tx[3] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    int ret;

    for (int i = 0; i < MAX_SPI_RETRIES; i++) {
        ret = write(spi_fd, tx, 3);
        if (ret < 0) {
            perror("write");
            continue;
        }
        ret = read(spi_fd, rx, 3);
        if (ret < 0) {
            perror("read");
            continue;
        }
        return ((rx[1] & 3) << 8) | rx[2];
    }
    return -1;
}

double adc_to_amperes(int adc_value) {
    // Assuming a 3.3V reference voltage and a gain of 1
    return (adc_value * 3.3 / 1024.0) * 1.0; // Adjust the gain factor as needed
}

void log_current(double current) {
    FILE *file = fopen("current_log.csv", "a");
    if (!file) {
        perror("fopen");
        return;
    }
    if (ftell(file) == 0) {
        fprintf(file, "Timestamp,Current (A)\n");
    }
    time_t now = time(NULL);
    fprintf(file, "%s,%.2f\n", ctime(&now), current);
    fclose(file);
}

void handle_overcurrent(double current) {
    if (current > CURRENT_THRESHOLD) {
        if (motor_shutdown_fd >= 0) {
            write(motor_shutdown_fd, "0", 1);
        }
        log_current(current);
        sleep(1);
        if (motor_shutdown_fd >= 0) {
            write(motor_shutdown_fd, "1", 1);
        }
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open SPI device");
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE_0) < 0) {
        perror("ioctl SPI mode");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &8) < 0) {
        perror("ioctl bits per word");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &500000) < 0) {
        perror("ioctl max speed");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    gpio_fd = open(GPIO_DEVICE, O_RDWR);
    if (gpio_fd < 0) {
        perror("open GPIO device");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(gpio_fd, GPIO_GET_LINEINFO_IOCTL, MOTOR_SHUTDOWN_PIN) < 0) {
        perror("ioctl get line info");
        close(gpio_fd);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(gpio_fd, GPIO_GET_LINEHANDLE_IOCTL, MOTOR_SHUTDOWN_PIN) < 0) {
        perror("ioctl get line handle");
        close(gpio_fd);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    motor_shutdown_fd = open("/sys/class/gpio/gpio17/value", O_WRONLY);
    if (motor_shutdown_fd < 0) {
        perror("open motor shutdown GPIO");
        close(gpio_fd);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    write(motor_shutdown_fd, "1", 1);

    FILE *file = fopen("current_log.csv", "a");
    if (!file) {
        perror("fopen");
        close(motor_shutdown_fd);
        close(gpio_fd);
        close(spi_fd);
        return EXIT_FAILURE;
    }
    fclose(file);

    while (1) {
        int adc_value = read_adc(MCP3008_CHANNEL);
        if (adc_value < 0) {
            perror("read_adc");
            continue;
        }

        double current = adc_to_amperes(adc_value);
        log_current(current);
        handle_overcurrent(current);

        sleep(1);
    }

    close_resources();
    return EXIT_SUCCESS;
}

