#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x50
#define LOG_FILE "pressure_log.csv"

static struct gpiod_chip *chip;
static FILE *log_file;

void cleanup() {
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

void handle_sigint(int sig) {
    cleanup();
    exit(0);
}

int read_pressure() {
    uint8_t buffer[2];
    int ret = gpiod_chip_i2c_read(chip, I2C_ADDRESS, buffer, sizeof(buffer));
    if (ret < 0) {
        fprintf(stderr, "Failed to read from sensor: %s\n", gpiod_error_str(ret));
        return -1;
    }
    uint16_t raw_pressure = (buffer[0] << 8) | buffer[1];
    return (int)(raw_pressure * 0.01); // Convert to kPa
}

int main() {
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", gpiod_error_str(-1));
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    if (fprintf(log_file, "Timestamp,Pressure(kPa)\n") < 0) {
        fprintf(stderr, "Failed to write header to log file: %s\n", strerror(errno));
        fclose(log_file);
        gpiod_chip_close(chip);
        return 1;
    }

    while (1) {
        time_t now = time(NULL);
        struct tm *tm = gmtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

        int pressure = read_pressure();
        if (pressure >= 0) {
            if (fprintf(log_file, "%s,%d\n", timestamp, pressure) < 0) {
                fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
            }
        }

        fflush(log_file);
        sleep(1);
    }

    cleanup();
    return 0;
}

