#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define GPIO_CE 8
#define GPIO_MOSI 10
#define GPIO_MISO 9
#define GPIO_SCLK 11
#define GPIO_SHUTDOWN 27
#define MAX_ADC_VALUE 1023
#define MAX_CURRENT 10.0
#define SAMPLE_INTERVAL 100

static int spi_handle = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *shutdown_line = NULL;

void cleanup() {
    if (shutdown_line) {
        gpiod_line_set_value(shutdown_line, 0);
        gpiod_line_release(shutdown_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    if (spi_handle != -1) {
        spi_close(spi_handle);
    }
    pigpio_stop();
}

void handle_sigint(int sig) {
    cleanup();
    exit(0);
}

void handle_sigterm(int sig) {
    cleanup();
    exit(0);
}

int read_adc_value(int channel) {
    uint8_t tx[3] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    int result = spi_xfer(spi_handle, tx, rx, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }
    return ((rx[1] & 3) << 8) | rx[2];
}

double adc_to_current(int adc_value) {
    return (double)adc_value * MAX_CURRENT / MAX_ADC_VALUE;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (signal(SIGINT, handle_sigint) == SIG_ERR) {
        fprintf(stderr, "Failed to set SIGINT handler\n");
        cleanup();
        return 1;
    }

    if (signal(SIGTERM, handle_sigterm) == SIG_ERR) {
        fprintf(stderr, "Failed to set SIGTERM handler\n");
        cleanup();
        return 1;
    }

    spi_handle = spi_open(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle == -1) {
        fprintf(stderr, "Failed to open SPI channel\n");
        cleanup();
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        cleanup();
        return 1;
    }

    shutdown_line = gpiod_chip_get_line(chip, GPIO_SHUTDOWN);
    if (!shutdown_line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(shutdown_line, "shutdown", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line as output\n");
        cleanup();
        return 1;
    }

    log_file = fopen("current_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    while (1) {
        int adc_value = read_adc_value(0);
        if (adc_value == -1) {
            cleanup();
            return 1;
        }

        double current = adc_to_current(adc_value);
        if (current > MAX_CURRENT) {
            fprintf(stderr, "OVERCURRENT: Current exceeds 10A\n");
            gpiod_line_set_value(shutdown_line, 1);
            cleanup();
            return 1;
        }

        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, Current: %.2fA\n",
                tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
                tm->tm_hour, tm->tm_min, tm->tm_sec, current);
        fflush(log_file);

        usleep(SAMPLE_INTERVAL * 1000);
    }

    cleanup();
    return 0;
}

