#define VOLTAGE_THRESHOLD 2.5

static struct gpiod_chip *chip;
static struct gpiod_line *ce_line;
static struct gpiod_line *alarm_line;
static FILE *log_file;

void log_voltage(double voltage) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s,Voltage: %.2f V\n", timestamp, voltage);
    fflush(log_file);
}

void handle_sigint(int sig) {
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    if (alarm_line) {
        gpiod_line_set_value(alarm_line, 0);
    }
    exit(0);
}

int read_adc_channel(int channel) {
    uint8_t tx[3] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    int ret;

    ret = gpiod_line_set_value(ce_line, 1);
    if (ret < 0) {
        perror("Failed to set CE line high");
        return -1;
    }

    ret = gpiod_chip_transfer(chip, tx, rx, 3);
    if (ret < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    ret = gpiod_line_set_value(ce_line, 0);
    if (ret < 0) {
        perror("Failed to set CE line low");
        return -1;
    }

    return ((rx[1] & 3) << 8) | rx[2];
}

int main() {
    int adc_value, voltage;
    double voltage_value;
    struct sigaction sa;

    // Initialize GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    ce_line = gpiod_chip_get_line(chip, SPI_CE_PIN);
    if (!ce_line) {
        perror("Failed to get CE line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(ce_line, "SPI_CE", 0);
    if (ret < 0) {
        perror("Failed to request CE line as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    alarm_line = gpiod_chip_get_line(chip, ALARM_PIN);
    if (!alarm_line) {
        perror("Failed to get alarm line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(alarm_line, "Alarm", 0);
    if (ret < 0) {
        perror("Failed to request alarm line as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initialize SPI
    ret = gpiod_line_set_value(ce_line, 0);
    if (ret < 0) {
        perror("Failed to set CE line low");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initialize log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up signal handler
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (1) {
        adc_value = read_adc_channel(SPI_CHANNEL);
        if (adc_value < 0) {
            sleep(1);
            continue;
        }

        voltage_value = (adc_value * 3.3) / 1024.0;
        log_voltage(voltage_value);

        if (voltage_value > VOLTAGE_THRESHOLD) {
            gpiod_line_set_value(alarm_line, 1);
        } else {
            gpiod_line_set_value(alarm_line, 0);
        }

        sleep(1);
    }

    return EXIT_SUCCESS;
}

