#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <unistd.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDRESS 0x48
#define MLX90830_ADDRESS 0x5A
#define ADS1115_CHANNEL 0
#define ADS1115_CONVERSION_TIME 1000000 // 1 second
#define MIN_PRESSURE 0.0
#define MAX_PRESSURE 100.0

static int i2c_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *line;

void cleanup() {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

void signal_handler(int sig) {
    cleanup();
    exit(0);
}

int read_ads1115(int channel) {
    uint16_t adc_value;
    uint8_t buffer[2];

    if (write(i2c_fd, &channel, 1) != 1) {
        perror("Failed to write to ADS1115");
        return -1;
    }

    if (read(i2c_fd, buffer, 2) != 2) {
        perror("Failed to read from ADS1115");
        return -1;
    }

    adc_value = (buffer[0] << 8) | buffer[1];
    return adc_value;
}

double convert_to_pressure(uint16_t adc_value) {
    // Assuming a linear relationship between ADC value and pressure
    // This is a simplified example, actual conversion may vary
    return (adc_value / 32767.0) * (MAX_PRESSURE - MIN_PRESSURE) + MIN_PRESSURE;
}

int main() {
    struct timespec ts;
    FILE *log_file;

    signal(SIGINT, signal_handler);

    // Initialize I2C
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDRESS) < 0) {
        perror("Failed to set I2C address for ADS1115");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize GPIO for I2C
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, 2);
    if (!line) {
        perror("Failed to get GPIO line for SDA");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "i2c_sda", 0) < 0) {
        perror("Failed to request GPIO line for SDA");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, 3);
    if (!line) {
        perror("Failed to get GPIO line for SCL");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "i2c_scl", 0) < 0) {
        perror("Failed to request GPIO line for SCL");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("pressure_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        uint16_t adc_value = read_ads1115(ADS1115_CHANNEL);
        if (adc_value < 0) {
            continue;
        }

        double pressure = convert_to_pressure(adc_value);
        if (pressure < MIN_PRESSURE || pressure > MAX_PRESSURE) {
            continue;
        }

        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("Failed to get current time");
            continue;
        }

        fprintf(log_file, "%ld.%09ld, %.2f kPa\n", ts.tv_sec, ts.tv_nsec, pressure);
        fflush(log_file);

        usleep(ADS1115_CONVERSION_TIME);
    }

    fclose(log_file);
    cleanup();
    return EXIT_SUCCESS;
}

