        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("pressure_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        uint16_t adc_value = read_ads1115(ADS1115_CHANNEL);
        if (adc_value < 0) {
            continue;
        }

        double pressure = convert_to_pressure(adc_value);
        if (pressure < MIN_PRESSURE || pressure > MAX_PRESSURE) {
            continue;
        }

        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("Failed to get current time");
            continue;
        }

        fprintf(log_file, "%ld.%09ld, %.2f kPa\n", ts.tv_sec, ts.tv_nsec, pressure);
        fflush(log_file);

        usleep(ADS1115_CONVERSION_TIME);
    }

    fclose(log_file);
    cleanup();
    return EXIT_SUCCESS;
}
