#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip4"
#define GPIO_CE0 8
#define GPIO_SCLK 11
#define GPIO_MOSI 10
#define GPIO_MISO 9
#define TMP36_CHANNEL 0
#define TMP36_REF_VOLTAGE 3.3
#define TMP36_MIN_TEMP -40.0
#define TMP36_MAX_TEMP 125.0
#define LOG_FILE "temperature_log.csv"

static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_ce0 = NULL;
static FILE *log_file = NULL;

void close_resources() {
    if (gpio_ce0) {
        gpiod_line_release(gpio_ce0);
        gpio_ce0 = NULL;
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
        gpio_chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

void handle_signal(int signum) {
    close_resources();
    exit(signum);
}

int read_adc_channel(int channel) {
    uint8_t tx[3] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = 1000000,
        .delay_usecs = 0,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI_IOC_MESSAGE");
        return -1;
    }

    return ((rx[1] & 3) << 8) | rx[2];
}

double adc_to_temperature(int adc_value) {
    double voltage = (adc_value * TMP36_REF_VOLTAGE) / 4095.0;
    double temperature_celsius = (voltage - 0.5) * 100.0;
    return temperature_celsius;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    gpio_ce0 = gpiod_chip_get_line(gpio_chip, GPIO_CE0);
    if (!gpio_ce0) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(gpio_ce0, "CE0", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(gpio_ce0);
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(gpio_ce0);
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (fseek(log_file, 0, SEEK_END) == 0 && ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,temperature_celsius\n");
    }

    while (1) {
        gpiod_line_set_value(gpio_ce0, 1);
        int adc_value = read_adc_channel(TMP36_CHANNEL);
        gpiod_line_set_value(gpio_ce0, 0);

        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC channel\n");
            continue;
        }

        double temperature_celsius = adc_to_temperature(adc_value);

        if (temperature_celsius < TMP36_MIN_TEMP || temperature_celsius > TMP36_MAX_TEMP) {
            fprintf(stderr, "Invalid temperature reading: %.2f°C\n", temperature_celsius);
            continue;
        }

        time_t now = time(NULL);
        fprintf(log_file, "%ld,%.2f\n", now, temperature_celsius);
        fflush(log_file);

        sleep(1);
    }

    close_resources();
    return EXIT_SUCCESS;
}

