    uint8_t rx[3];
    int ret;

    ret = gpiod_line_set_value(ce_line, 0);
    if (ret < 0) {
        perror("Failed to set CE line low");
        cleanup();
        exit(1);
    }

    ret = gpiod_chip_transfer(chip, tx, rx, 3);
    if (ret < 0) {
        perror("Failed to transfer data");
        cleanup();
        exit(1);
    }

    ret = gpiod_line_set_value(ce_line, 1);
    if (ret < 0) {
        perror("Failed to set CE line high");
        cleanup();
        exit(1);
    }

    return ((rx[1] & 3) << 8) | rx[2];
}

int main() {
    struct timespec ts;
    uint16_t x, y, z;
    int ret;

    // Initialize GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Request CE line
    ce_line = gpiod_chip_get_line(chip, SPI_CE_PIN);
    if (!ce_line) {
        perror("Failed to get CE line");
        gpiod_chip_close(chip);
        return 1;
    }

