        fprintf(log_file, "%ld.%09ld,%u,%u,%u\n", ts.tv_sec, ts.tv_nsec, x, y, z);

        // Sleep for 10ms (100Hz)
        usleep(10000);
    }

    cleanup();
    return 0;
}

