    return ((rx[1] & 3) << 8) | rx[2];
}

int main() {
    struct timespec ts;
    uint16_t x, y, z;
    int ret;

    // Initialize GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Request CE line
    ce_line = gpiod_chip_get_line(chip, SPI_CE_PIN);
    if (!ce_line) {
        perror("Failed to get CE line");
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(ce_line, "accelerometer_cs", 0);
    if (ret < 0) {
        perror("Failed to request CE line output");
        gpiod_chip_close(chip);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    while (1) {
        // Read ADC values
        x = read_adc_channel(0);
        y = read_adc_channel(1);
        z = read_adc_channel(2);

        // Check for impact
        if (x > IMPACT_THRESHOLD || y > IMPACT_THRESHOLD || z > IMPACT_THRESHOLD) {
            fprintf(log_file, "IMPACT DETECTED\n");
        }

        // Log values
        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld.%09ld,%u,%u,%u\n", ts.tv_sec, ts.tv_nsec, x, y, z);

        // Sleep for 10ms (100Hz)
        usleep(10000);
    }

    cleanup();
    return 0;
}
