#define SI1172_I2C_ADDRESS 0x60
#define SI1172_REG_COMMAND 0x00
#define SI1172_REG_IRQ_ENABLE 0x02
#define SI1172_REG_IRQ_STATUS 0x03
#define SI1172_REG_MEAS_RATE 0x04
#define SI1172_REG_ALS_VIS_ADC 0x12
#define SI1172_REG_ALS_IR_ADC 0x14
#define SI1172_REG_ALS_RED_ADC 0x16
#define SI1172_CMD_ALS_AUTO 0x10
#define SI1172_CMD_ALS_FORCE 0x08

#define LOG_FILE "biometric_log.csv"

struct si1172 {
    struct gpiod_chip *chip;
    struct gpiod_line *clk;
    struct gpiod_line *data;
    int i2c_fd;
};

static void signal_handler(int signum) {
    exit(signum);
}

static int si1172_init(struct si1172 *sensor) {
    sensor->chip = gpiod_chip_open_by_name("gpiochip0");
    if (!sensor->chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    sensor->clk = gpiod_chip_get_line(sensor->chip, 17);
    if (!sensor->clk) {
        perror("Failed to get GPIO line for CLK");
        gpiod_chip_close(sensor->chip);
        return -1;
    }

    if (gpiod_line_request_output(sensor->clk, "si1172_clk", 0) < 0) {
        perror("Failed to request output for CLK");
        gpiod_chip_close(sensor->chip);
        return -1;
    }

    sensor->data = gpiod_chip_get_line(sensor->chip, 27);
    if (!sensor->data) {
        perror("Failed to get GPIO line for DATA");
        gpiod_line_release(sensor->clk);
        gpiod_chip_close(sensor->chip);
        return -1;
    }

    if (gpiod_line_request_input(sensor->data, "si1172_data") < 0) {
        perror("Failed to request input for DATA");
        gpiod_line_release(sensor->clk);
        gpiod_chip_close(sensor->chip);
        return -1;
    }

    sensor->i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (sensor->i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpiod_line_release(sensor->clk);
        gpiod_chip_close(sensor->chip);
        return -1;
    }

    if (ioctl(sensor->i2c_fd, I2C_SLAVE, SI1172_I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(sensor->i2c_fd);
        gpiod_line_release(sensor->clk);
        gpiod_chip_close(sensor->chip);
        return -1;
    }

    uint8_t cmd[] = {SI1172_REG_COMMAND, SI1172_CMD_ALS_AUTO};
    if (write(sensor->i2c_fd, cmd, sizeof(cmd)) != sizeof(cmd)) {
        perror("Failed to send command to SI1172");
        close(sensor->i2c_fd);
        gpiod_line_release(sensor->clk);
        gpiod_chip_close(sensor->chip);
        return -1;
    }

    return 0;
}

static void si1172_deinit(struct si1172 *sensor) {
    close(sensor->i2c_fd);
    gpiod_line_release(sensor->clk);
    gpiod_chip_close(sensor->chip);
}

static int si1172_read(struct si1172 *sensor, uint16_t *ir, uint16_t *red) {
    uint8_t cmd[] = {SI1172_REG_COMMAND, SI1172_CMD_ALS_FORCE};
    if (write(sensor->i2c_fd, cmd, sizeof(cmd)) != sizeof(cmd)) {
        perror("Failed to send command to SI1172");
        return -1;
    }

    uint8_t status;
    if (read(sensor->i2c_fd, &status, sizeof(status)) != sizeof(status)) {
        perror("Failed to read status from SI1172");
        return -1;
    }

    if (status & 0x01) {
        uint8_t ir_data[2];
        if (read(sensor->i2c_fd, ir_data, sizeof(ir_data)) != sizeof(ir_data)) {
            perror("Failed to read IR data from SI1172");
            return -1;
        }
        *ir = (ir_data[0] << 8) | ir_data[1];

        uint8_t red_data[2];
        if (read(sensor->i2c_fd, red_data, sizeof(red_data)) != sizeof(red_data)) {
            perror("Failed to read RED data from SI1172");
            return -1;
        }
        *red = (red_data[0] << 8) | red_data[1];

        return 0;
    } else {
        return -1;
    }
}

int main() {
    struct si1172 sensor;
    if (si1172_init(&sensor) < 0) {
        fprintf(stderr, "Failed to initialize SI1172 sensor\n");
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        si1172_deinit(&sensor);
        return EXIT_FAILURE;
    }

    fprintf(log_file, "timestamp,HR(bpm),SpO2(%%),error_flag\n");

    signal(SIGINT, signal_handler);

    while (1) {
        uint16_t ir, red;
        int ret = si1172_read(&sensor, &ir, &red);
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);

        if (ret == 0) {
            fprintf(log_file, "%ld,%d,%d,0\n", now, ir, red);
        } else {
            fprintf(log_file, "%ld,0,0,1\n", now);
        }

        fflush(log_file);
        sleep(1);
    }

    fclose(log_file);
    si1172_deinit(&sensor);

    return EXIT_SUCCESS;
}

