#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define SPI_CHANNEL 0
#define ADC_MIN 0
#define ADC_MAX 1023
#define FLOW_MIN 0.0
#define FLOW_MAX 5.0
#define LOG_FILE "flow_log.csv"

static struct gpiod_chip *chip;
static int spi_fd;
static FILE *log_file;

void cleanup(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(signum);
}

uint16_t read_adc(int channel) {
    uint8_t tx[3] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    ssize_t bytes_read;

    bytes_read = gpiod_chip_get_value_bulk(chip, tx, 3, rx);
    if (bytes_read != 3) {
        fprintf(stderr, "Failed to read from SPI device\n");
        return 0;
    }

    return ((rx[1] & 3) << 8) | rx[2];
}

double adc_to_flow(uint16_t adc_value) {
    return (double)adc_value * (FLOW_MAX - FLOW_MIN) / (ADC_MAX - ADC_MIN) + FLOW_MIN;
}

int main() {
    struct timespec ts;
    char timestamp[20];
    uint16_t adc_value;
    double flow_rate;

    // Initialize signal handler
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Initialize libgpiod
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set SPI mode and speed
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        fprintf(stderr, "Failed to set SPI mode\n");
        close(spi_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        fprintf(stderr, "Failed to set SPI speed\n");
        close(spi_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        close(spi_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        // Read ADC value
        adc_value = read_adc(SPI_CHANNEL);
        if (adc_value == 0 || adc_value == ADC_MAX) {
            fprintf(stderr, "Sensor absent or out of range\n");
            continue;
        }

        // Convert ADC value to flow rate
        flow_rate = adc_to_flow(adc_value);

        // Validate flow rate
        if (flow_rate < FLOW_MIN || flow_rate > FLOW_MAX) {
            fprintf(stderr, "Invalid flow rate: %f\n", flow_rate);
            continue;
        }

        // Get current timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
            fprintf(stderr, "Failed to get current time\n");
            continue;
        }

        // Format timestamp
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
        snprintf(timestamp + 19, sizeof(timestamp) - 19, ".%06ld", ts.tv_nsec / 1000);

        // Log measurement
        fprintf(log_file, "%s,%f\n", timestamp, flow_rate);
        fflush(log_file);
    }

    return EXIT_SUCCESS;
}

