#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x76
#define MEASUREMENT_COMMAND 0x2416
#define DATA_LENGTH 6
#define CSV_FILE "environmental_data.csv"

static int i2c_fd = -1;
static FILE *csv_file = NULL;

void close_resources() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
}

void handle_sigint(int sig) {
    close_resources();
    exit(0);
}

void handle_sigterm(int sig) {
    close_resources();
    exit(0);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct timespec ts;
    uint8_t buffer[DATA_LENGTH];
    int16_t pressure_raw, temperature_raw;
    float pressure, temperature;
    char timestamp[20];

    // Register signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Write header to CSV file
