            sleep(5);
            continue;
        }

        // Convert raw values to pressure and temperature
        pressure_raw = (buffer[0] << 8) | buffer[1];
        temperature_raw = (buffer[2] << 8) | buffer[3];
        pressure = (pressure_raw * 0.01f) - 50000.0f;
        temperature = (temperature_raw * 0.01f) - 40.0f;

        // Get current timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("Failed to get current time");
            sleep(5);
            continue;
        }
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        // Log to CSV file
        fprintf(csv_file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
        fflush(csv_file);

        // Display on console
        printf("Timestamp: %s, Pressure: %.2f Pa, Temperature: %.2f C\n", timestamp, pressure, temperature);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Close resources
    close_resources();
    return EXIT_SUCCESS;
