#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <libgpiod.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_CE 8
#define SPI_SPEED 500000
#define SPI_BITS 8
#define SPI_MODE 0

#define MIC1_CHANNEL 0
#define MIC2_CHANNEL 1

#define GAIN_MIN 0
#define GAIN_MAX 100

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int read_adc(int channel) {
    uint8_t tx[3] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    int ret = spi_xfer(SPI_CHANNEL, tx, rx, 3);
    if (ret < 0) {
        perror("SPI transfer failed");
        return -1;
    }
    return ((rx[1] & 3) << 8) | rx[2];
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <gain1> <gain2>\n", argv[0]);
        return 1;
    }

    int gain1 = atoi(argv[1]);
    int gain2 = atoi(argv[2]);

    if (gain1 < GAIN_MIN || gain1 > GAIN_MAX || gain2 < GAIN_MIN || gain2 > GAIN_MAX) {
        fprintf(stderr, "Gain values must be between %d and %d\n", GAIN_MIN, GAIN_MAX);
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        return 1;
    }

    if (spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE) < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (running) {
        int sample1 = read_adc(MIC1_CHANNEL);
        int sample2 = read_adc(MIC2_CHANNEL);

        if (sample1 < 0 || sample2 < 0) {
            fprintf(stderr, "Failed to read ADC samples\n");
            break;
        }

        int noise_cancelled = sample1 - sample2;

        printf("%d,%d,%d\n", sample1, sample2, noise_cancelled);
        fflush(stdout);
    }

    spiClose(SPI_CHANNEL);
    gpioTerminate();

    return 0;
}

