#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <libgpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define SPI_BITS_PER_WORD 8
#define MCP3008_CHANNEL 0
#define BUZZER_PIN 18
#define LOG_FILE "flame_log.txt"
#define AMBIENT_TEMP_FILE "ambient_temp.txt"
#define RETRY_COUNT 3
#define SAMPLE_INTERVAL 500

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

int read_spi(int fd, uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI_IOC_MESSAGE");
        return -1;
    }
    return 0;
}

int read_adc(int fd, int channel) {
    uint8_t tx[3] = {0x01, (0x80 | (channel & 0x07)), 0x00};
    uint8_t rx[3];
    if (read_spi(fd, tx, rx, 3) < 0) {
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

double read_temperature(const char *file) {
    FILE *fp = fopen(file, "r");
    if (!fp) {
        perror("Failed to open ambient_temp.txt");
        return 25.0;
    }
    double temperature;
    if (fscanf(fp, "%lf", &temperature) != 1) {
        perror("Failed to read temperature from ambient_temp.txt");
        temperature = 25.0;
    }
    fclose(fp);
    return temperature;
}

void log_flame(const char *log_file, time_t timestamp, int raw_adc, double voltage, double compensated_voltage, double temperature, int flame_detected) {
    FILE *fp = fopen(log_file, "a");
    if (!fp) {
        perror("Failed to open flame_log.txt");
        return;
    }
    fprintf(fp, "%s,%d,%.2f,%.2f,%.2f,%d\n", ctime(&timestamp), raw_adc, voltage, compensated_voltage, temperature, flame_detected);
    fclose(fp);
}

int main() {
    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_line *buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        perror("Failed to get buzzer line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(buzzer_line, "flame_sensor", 0) < 0) {
        perror("Failed to request buzzer line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    while (!stop_flag) {
        time_t timestamp = time(NULL);
        int raw_adc = -1;
        int retry_count = 0;

        while (retry_count < RETRY_COUNT && raw_adc < 0) {
            raw_adc = read_adc(spi_fd, MCP3008_CHANNEL);
            if (raw_adc < 0) {
                retry_count++;
                sleep(1);
            }
        }

        if (raw_adc < 0) {
            fprintf(stderr, "Failed to read ADC value after %d retries\n", RETRY_COUNT);
            log_flame(LOG_FILE, timestamp, -1, -1.0, -1.0, -1.0, 0);
            continue;
        }

        double voltage = (raw_adc * 3.3) / 1023.0;
        double temperature = read_temperature(AMBIENT_TEMP_FILE);
        double compensated_voltage = voltage * (1.0 + (temperature - 25.0) * 0.002);

        int flame_detected = (compensated_voltage > 0.5);

        if (flame_detected) {
            gpiod_line_set_value(buzzer_line, 1);
        } else {
            gpiod_line_set_value(buzzer_line, 0);
        }

        log_flame(LOG_FILE, timestamp, raw_adc, voltage, compensated_voltage, temperature, flame_detected);

        sleep(SAMPLE_INTERVAL / 1000);
    }

    gpiod_line_release(buzzer_line);
    gpiod_chip_close(chip);
    close(spi_fd);

    return EXIT_SUCCESS;
}

