#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>
#include <libmraa/spi.h>
#include <libmraa/gpio.h>

#define SPI_CHANNEL 0
#define ADC_CHANNEL 0
#define MIN_CALIBRATION 0
#define MAX_CALIBRATION 1023
#define MOISTURE_THRESHOLD 30
#define LOG_INTERVAL 60
#define EMAIL_INTERVAL 300
#define EMAIL_SUBJECT "Plant Moisture Alert"
#define EMAIL_BODY "The moisture level of your plant is below the threshold."

static int spi_fd = -1;
static FILE *log_file = NULL;
static FILE *email_file = NULL;
static struct mraa_spi_context spi = NULL;

void log_moisture(int moisture_percent) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, %d\n",
            tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
            tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec, moisture_percent);
    fflush(log_file);
}

void send_email(int moisture_percent) {
    if (moisture_percent < MOISTURE_THRESHOLD) {
        fprintf(email_file, "To: recipient@example.com\n");
        fprintf(email_file, "From: sender@example.com\n");
        fprintf(email_file, "Subject: %s\n", EMAIL_SUBJECT);
        fprintf(email_file, "\n%s\n", EMAIL_BODY);
        fflush(email_file);
        char *command = "msmtp -c /path/to/msmtp.conf recipient@example.com < email.txt";
        int status = system(command);
        if (status != 0) {
            fprintf(stderr, "Failed to send email: %d\n", status);
        }
    }
}

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        if (spi) {
            mraa_spi_stop(spi);
            mraa_spi_close(spi);
        }
        if (log_file) {
            fclose(log_file);
        }
        if (email_file) {
            fclose(email_file);
        }
        exit(0);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 7) {
        fprintf(stderr, "Usage: %s <SPI channel> <ADC channel> <min calibration> <max calibration> <moisture threshold> <logging interval>\n", argv[0]);
        return 1;
    }

    int spi_channel = atoi(argv[1]);
    int adc_channel = atoi(argv[2]);
    int min_calibration = atoi(argv[3]);
    int max_calibration = atoi(argv[4]);
    int moisture_threshold = atoi(argv[5]);
    int logging_interval = atoi(argv[6]);

    if (min_calibration < 0 || max_calibration > 1023 || min_calibration > max_calibration) {
        fprintf(stderr, "Invalid calibration values\n");
        return 1;
    }

    if (moisture_threshold < 0 || moisture_threshold > 100) {
        fprintf(stderr, "Invalid moisture threshold\n");
        return 1;
    }

    if (logging_interval <= 0) {
        fprintf(stderr, "Invalid logging interval\n");
        return 1;
    }

    spi = mraa_spi_init(spi_channel);
    if (!spi) {
        fprintf(stderr, "Failed to initialize SPI\n");
        return 1;
    }

    mraa_spi_frequency(spi, 500000);
    mraa_spi_mode(spi, MRAA_SPI_MODE0);

    log_file = fopen("plant_data.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        mraa_spi_stop(spi);
        mraa_spi_close(spi);
        return 1;
    }

    email_file = fopen("email.txt", "w");
    if (!email_file) {
        fprintf(stderr, "Failed to open email file\n");
        fclose(log_file);
        mraa_spi_stop(spi);
        mraa_spi_close(spi);
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        uint16_t adc_value = mraa_spi_read_word(spi);
        if (adc_value == -1) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue;
        }

        int moisture_percent = (adc_value - min_calibration) * 100 / (max_calibration - min_calibration);
        log_moisture(moisture_percent);
        send_email(moisture_percent);

        sleep(logging_interval);
    }

    fclose(log_file);
    fclose(email_file);
    mraa_spi_stop(spi);
    mraa_spi_close(spi);

    return 0;
}

