#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define SPI_BITS_PER_WORD 8
#define ADC_CHANNEL 0
#define ADC_MAX_VALUE 1023

static int spi_fd = -1;
static FILE *log_file = NULL;

void cleanup() {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
}

void signal_handler(int signum) {
    cleanup();
    exit(signum);
}

uint16_t read_adc(uint8_t channel) {
    uint8_t tx[3] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI_IOC_MESSAGE");
        return ADC_MAX_VALUE;
    }

    return ((rx[1] & 3) << 8) | rx[2];
}

void log_moisture(uint16_t adc_value) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", tm_info);

    double moisture_percentage = (double)adc_value / ADC_MAX_VALUE * 100;

    if (fprintf(log_file, "%s, %d, %.2f%%\n", timestamp, adc_value, moisture_percentage) < 0) {
        perror("fprintf");
    }
}

int main(int argc, char *argv[]) {
    int interval = 1; // default interval in seconds

    if (argc > 1) {
        interval = atoi(argv[1]);
        if (interval <= 0) {
            fprintf(stderr, "Invalid interval: %s\n", argv[1]);
            return 1;
        }
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open");
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
