#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000
#define SPI_CHANNEL 0
#define SPI_BUFFER_SIZE 3

volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

int read_adc(int fd, int channel) {
    uint8_t tx[SPI_BUFFER_SIZE] = {1, (8 + channel) << 4, 0};
    uint8_t rx[SPI_BUFFER_SIZE];
    int ret;

    ret = write(fd, tx, SPI_BUFFER_SIZE);
    if (ret != SPI_BUFFER_SIZE) {
        perror("write");
        return -1;
    }

    ret = read(fd, rx, SPI_BUFFER_SIZE);
    if (ret != SPI_BUFFER_SIZE) {
        perror("read");
        return -1;
    }

    return ((rx[1] & 3) << 8) | rx[2];
}

int main() {
    int fd;
    struct spi_ioc_transfer tr;
    uint8_t tx[SPI_BUFFER_SIZE] = {1, (8 + SPI_CHANNEL) << 4, 0};
    uint8_t rx[SPI_BUFFER_SIZE];
    int adc_value, moisture_percentage;
    struct sigaction sa;

    // Set up signal handler for graceful termination
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open SPI device
    fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("open");
        return EXIT_FAILURE;
    }

    // Set SPI mode
    if (ioctl(fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("ioctl mode");
        close(fd);
        return EXIT_FAILURE;
    }

    // Set SPI bits per word
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("ioctl bits per word");
        close(fd);
        return EXIT_FAILURE;
    }

    // Set SPI max speed hz
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("ioctl max speed hz");
        close(fd);
        return EXIT_FAILURE;
    }

    while (running) {
        // Read ADC value
        adc_value = read_adc(fd, SPI_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue;
        }

        // Calculate moisture percentage (assuming 0% at 1023 and 100% at 0)
        moisture_percentage = (adc_value * 100) / 1023;

        // Log the raw ADC reading and moisture percentage
        printf("ADC Value: %d, Moisture Percentage: %d%%\n", adc_value, moisture_percentage);

        // Wait for 5 seconds
        sleep(5);
    }

    // Close SPI device
    close(fd);

    return EXIT_SUCCESS;
}

