#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE_CE0 8
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define ADC_CHANNEL 0
#define SAMPLE_INTERVAL 5

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

uint16_t read_adc(struct gpiod_chip *chip, int channel) {
    uint8_t tx[3] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    struct gpiod_line *ce0_line;
    int ret;

    ce0_line = gpiod_chip_get_line(chip, GPIO_LINE_CE0);
    if (!ce0_line) {
        perror("Failed to get CE0 line");
        return 0;
    }

    ret = gpiod_line_request_output(ce0_line, "spi_cs", 0);
    if (ret < 0) {
        perror("Failed to request CE0 line as output");
        gpiod_line_release(ce0_line);
        return 0;
    }

    ret = gpiod_line_set_value(ce0_line, 0);
    if (ret < 0) {
        perror("Failed to set CE0 line to low");
        gpiod_line_release(ce0_line);
        return 0;
    }

    ret = gpiod_line_set_value(ce0_line, 1);
    if (ret < 0) {
        perror("Failed to set CE0 line to high");
        gpiod_line_release(ce0_line);
        return 0;
    }

    ret = gpiod_line_release(ce0_line);
    if (ret < 0) {
        perror("Failed to release CE0 line");
        return 0;
    }

    ret = gpiod_chip_write(chip, tx, 3);
    if (ret < 0) {
        perror("Failed to write to SPI");
        return 0;
    }

    ret = gpiod_chip_read(chip, rx, 3);
    if (ret < 0) {
        perror("Failed to read from SPI");
        return 0;
    }

    return ((rx[1] & 3) << 8) | rx[2];
}

int main() {
    struct gpiod_chip *chip;
    struct timespec ts;
    uint16_t adc_value;
    int ret;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    ret = gpiod_chip_set_option(chip, GPIOD_CHIP_OPTION_CONSUMER);
    if (ret < 0) {
        perror("Failed to set GPIO chip option");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        adc_value = read_adc(chip, ADC_CHANNEL);
        if (adc_value == 0 || adc_value == 1023) {
            fprintf(stderr, "Sensor absent or wiring fault detected\n");
        } else {
            clock_gettime(CLOCK_REALTIME, &ts);
            printf("Timestamp: %ld.%09ld, ADC Value: %u\n", ts.tv_sec, ts.tv_nsec, adc_value);
        }

        sleep(SAMPLE_INTERVAL);
    }

    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

