#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000
#define SPI_CHANNEL 0
#define SPI_START_BIT 0x01
#define SPI_CONFIG_BYTE 0x60
#define SPI_DONTCARE_BYTE 0x00
#define SAMPLE_INTERVAL 5

volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

int main() {
    int fd;
    uint8_t tx[3] = {SPI_START_BIT, SPI_CONFIG_BYTE | (SPI_CHANNEL << 4), SPI_DONTCARE_BYTE};
    uint8_t rx[3];
    int moisture_value;
    double moisture_percentage;

    // Open SPI device
    if ((fd = open(SPI_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    // Set SPI mode
    if (ioctl(fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(fd);
        return EXIT_FAILURE;
    }

    // Set SPI bits per word
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set SPI bits per word");
        close(fd);
        return EXIT_FAILURE;
    }

    // Set SPI speed
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(fd);
        return EXIT_FAILURE;
    }

    // Register signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    while (running) {
        // Transfer data
        struct spi_ioc_transfer tr = {
            .tx_buf = (unsigned long)tx,
            .rx_buf = (unsigned long)rx,
            .len = 3,
            .speed_hz = SPI_SPEED,
            .bits_per_word = SPI_BITS_PER_WORD,
        };

        if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
            perror("Failed to transfer data");
            break;
        }

        // Calculate moisture value
        moisture_value = ((rx[1] & 0x03) << 8) | rx[2];
        moisture_percentage = (double)moisture_value * 100.0 / 1023.0;

        // Clamp to 0-100%
        if (moisture_percentage < 0) {
            moisture_percentage = 0;
        } else if (moisture_percentage > 100) {
            moisture_percentage = 100;
        }

        // Print moisture percentage
        printf("Moisture: %.2f%%\n", moisture_percentage);

        // Wait for next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Close SPI device
    close(fd);

    return EXIT_SUCCESS;
}

