#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <time.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define SPI_BITS_PER_WORD 8
#define NUM_CHANNELS 4
#define SAMPLE_INTERVAL 1

typedef struct {
    int fd;
    FILE *csv_file;
} SPIContext;

SPIContext spi_ctx = {0};

void close_resources() {
    if (spi_ctx.csv_file) {
        fclose(spi_ctx.csv_file);
    }
    if (spi_ctx.fd >= 0) {
        close(spi_ctx.fd);
    }
}

void handle_sigint(int sig) {
    close_resources();
    exit(0);
}

uint16_t read_adc(SPIContext *ctx, uint8_t channel) {
    uint8_t tx[3] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(ctx->fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI_IOC_MESSAGE");
        exit(EXIT_FAILURE);
    }

    return ((rx[1] & 3) << 8) | rx[2];
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    spi_ctx.fd = open(SPI_DEVICE, O_RDWR);
    if (spi_ctx.fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_ctx.fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_ctx.fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_ctx.fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set bits per word");
        close(spi_ctx.fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_ctx.fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set max speed hz");
        close(spi_ctx.fd);
        exit(EXIT_FAILURE);
    }

    spi_ctx.csv_file = fopen("environmental_data.csv", "w");
    if (!spi_ctx.csv_file) {
        perror("Failed to open CSV file");
        close(spi_ctx.fd);
        exit(EXIT_FAILURE);
    }

    fprintf(spi_ctx.csv_file, "Timestamp,Channel0,Channel1,Channel2,Channel3\n");

    while (1) {
        time_t now = time(NULL);
        fprintf(spi_ctx.csv_file, "%ld,", now);

        for (int i = 0; i < NUM_CHANNELS; i++) {
            uint16_t adc_value = read_adc(&spi_ctx, i);
            fprintf(spi_ctx.csv_file, "%d,", adc_value);
        }

        fprintf(spi_ctx.csv_file, "\n");
        fflush(spi_ctx.csv_file);
        sleep(SAMPLE_INTERVAL);
    }

    close_resources();
    return 0;
}

