This C program for a Raspberry Pi 5 continuously samples voltage readings from four analog sensors through an MCP3008 ADC using the SPI0 bus on CE0 (GPIO8, BCM) configured at 1 MHz, mode 0, reading channels 0 through 3 in single-ended mode once per second, logging each timestamped voltage value to a file named `environmental_data.csv`. It includes robust error handling for any SPI communication failures and ensures that on all exit paths triggered by SIGINT or SIGTERM the program cleanly closes the CSV file, the SPI device, and any driver library resources that were opened.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define SPI_BUS 0
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define GPIO_PUMP 17
#define GPIO_MOSI 10
#define GPIO_MISO 9
#define GPIO_SCLK 11
#define BUFFER_SIZE 20
#define LOW_THRESHOLD 300
#define HIGH_THRESHOLD 600

struct MoistureReading {
    time_t timestamp;
    int moisture_level;
    int pump_state;
};

struct MoistureReading buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_full = 0;

void handle_signal(int signum) {
    (void)signum;
    printf("Signal received, stopping...\n");
    exit(0);
}

int read_moisture_level(struct gpiod_chip *chip, struct gpiod_line *mosi, struct gpiod_line *miso, struct gpiod_line *sclk) {
    uint8_t tx[3] = {0b11000001, 0b00000000, 0b00000000};
    uint8_t rx[3];
    int ret;

    ret = gpiod_line_request_bulk(chip, "spi_bulk", tx, rx, 3);
    if (ret < 0) {
        perror("Failed to request SPI bulk lines");
        return -1;
    }

    ret = gpiod_line_set_value_bulk(mosi, tx, 3);
    if (ret < 0) {
        perror("Failed to set SPI MOSI values");
        gpiod_line_release_bulk(chip);
        return -1;
    }

    ret = gpiod_line_get_value_bulk(miso, rx, 3);
    if (ret < 0) {
        perror("Failed to get SPI MISO values");
        gpiod_line_release_bulk(chip);
        return -1;
    }

    gpiod_line_release_bulk(chip);

    return ((rx[1] & 0b00011111) << 8) | (rx[2] & 0b11111111);
}

void log_reading(struct MoistureReading *reading) {
    printf("Timestamp: %ld, Moisture Level: %d, Pump State: %d\n", reading->timestamp, reading->moisture_level, reading->pump_state);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *mosi, *miso, *sclk, *pump;
    struct MoistureReading current_reading;
    int moisture_level, pump_state = 0;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    mosi = gpiod_chip_get_line(chip, GPIO_MOSI);
    if (!mosi) {
        perror("Failed to get MOSI line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    miso = gpiod_chip_get_line(chip, GPIO_MISO);
    if (!miso) {
        perror("Failed to get MISO line");
        gpiod_line_release(mosi);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    sclk = gpiod_chip_get_line(chip, GPIO_SCLK);
    if (!sclk) {
        perror("Failed to get SCLK line");
        gpiod_line_release(mosi);
        gpiod_line_release(miso);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    pump = gpiod_chip_get_line(chip, GPIO_PUMP);
    if (!pump) {
        perror("Failed to get pump line");
        gpiod_line_release(mosi);
        gpiod_line_release(miso);
        gpiod_line_release(sclk);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(pump, "pump", 0) < 0) {
        perror("Failed to request pump line as output");
        gpiod_line_release(mosi);
        gpiod_line_release(miso);
        gpiod_line_release(sclk);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        moisture_level = read_moisture_level(chip, mosi, miso, sclk);
        if (moisture_level < 0) {
            continue;
        }

        current_reading.timestamp = time(NULL);
        current_reading.moisture_level = moisture_level;
        current_reading.pump_state = pump_state;

        if (moisture_level < LOW_THRESHOLD && !pump_state) {
            pump_state = 1;
            gpiod_line_set_value(pump, 1);
        } else if (moisture_level > HIGH_THRESHOLD && pump_state) {
            pump_state = 0;
            gpiod_line_set_value(pump, 0);
        }

        buffer[buffer_index] = current_reading;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        buffer_full = (buffer_index == 0);

        if (buffer_full) {
            printf("Buffer full, printing all entries:\n");
            for (int i = 0; i < BUFFER_SIZE; i++) {
                log_reading(&buffer[i]);
            }
        } else {
            log_reading(&current_reading);
        }

        sleep(5);
    }

    gpiod_line_release(pump);
    gpiod_line_release(mosi);
    gpiod_line_release(miso);
    gpiod_line_release(sclk);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

