This code provides a complete solution for reading the analog output of a Vegetronix VH400 soil moisture sensor through an MCP3008 ADC connected on the SPI bus CE0 (bus 0, channel 0) operating at 1 MHz in mode 0, using MOSI on GPIO10 (BCM), MISO on GPIO9 (BCM), and SCLK on GPIO11 (BCM). It samples the moisture level every 5 seconds, drives a 12V water pump through a relay on GPIO17 (BCM) configured as active-high, and logs each moisture reading together with a timestamp and any pump state change into an in-memory circular buffer of 20 entries. The program handles errors gracefully, ensures the pump is turned off on receipt of SIGINT or SIGTERM, and cleans up resources before terminating.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x57
#define PART_ID_REG 0x00
#define SPO2_REG 0x10
#define HR_REG 0x11
#define LOG_FILE "health_log.txt"

static struct gpiod_chip *chip = NULL;
static int i2c_fd = -1;

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
    fprintf(stderr, "Timestamp: %s\n", timestamp);
}

void log_event(const char *message) {
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
    fprintf(stderr, "Event: %s - %s\n", timestamp, message);
}

void handle_signal(int sig) {
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(sig);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        log_error("Failed to set signal handlers");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        log_error("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C bus");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        log_error("Failed to set I2C address");
        close(i2c_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    uint8_t part_id;
    if (read(i2c_fd, &part_id, sizeof(part_id)) != sizeof(part_id)) {
        log_error("Failed to read Part ID register");
        close(i2c_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (part_id != 0x14) {
        log_error("MAX30102 sensor not found");
        close(i2c_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        log_error("Failed to open log file");
        close(i2c_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        uint8_t spo2_data[2];
        if (read(i2c_fd, spo2_data, sizeof(spo2_data)) != sizeof(spo2_data)) {
            log_error("Failed to read SpO2 data");
            continue;
        }

        uint8_t hr_data[2];
        if (read(i2c_fd, hr_data, sizeof(hr_data)) != sizeof(hr_data)) {
            log_error("Failed to read heart rate data");
            continue;
        }

        uint16_t spo2 = (spo2_data[0] << 8) | spo2_data[1];
        uint16_t hr = (hr_data[0] << 8) | hr_data[1];

        if (spo2 < 95) {
            fprintf(log, "%s - SpO2 below 95%%: %d\n", ctime(NULL), spo2);
        }

        if (hr > 100) {
            fprintf(log, "%s - Heart rate above 100 BPM: %d\n", ctime(NULL), hr);
        }
    }

    fclose(log);
    close(i2c_fd);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

