#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define SPI_BUS 0
#define SPI_CHIP 0
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define SPI_CE 0
#define SPI_CHANNEL_COUNT 3
#define CSV_FILE "analog_log.csv"
#define LOG_INTERVAL 500

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

uint16_t read_mcp3008(struct gpiod_chip *chip, int channel) {
    uint8_t tx[3] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    struct gpiod_line *ce = gpiod_chip_get_line(chip, SPI_CE);
    if (!ce) {
        perror("Failed to get CE line");
        return 0;
    }
    gpiod_line_request_output(ce, "CE", 0);
    gpiod_line_set_value(ce, 1);
    if (gpiod_spi_xfer(chip, tx, rx, 3) != 3) {
        perror("SPI transfer failed");
        gpiod_line_set_value(ce, 0);
        return 0;
    }
    gpiod_line_set_value(ce, 0);
    return ((rx[1] & 3) << 8) | rx[2];
}

void log_voltage(int channel, uint16_t voltage) {
    time_t now = time(NULL);
    struct tm *tm_info = gmtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);
    fprintf(stderr, "Timestamp: %s, Channel: %d, Voltage: %d\n", timestamp, channel, voltage);
    fprintf(stdout, "%s,%d,%d\n", timestamp, channel, voltage);
}

int main() {
    struct gpiod_chip *chip;
    FILE *csv_file;
    int i;

    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    csv_file = fopen(CSV_FILE, "a");
    if (!csv_file) {
        perror("Failed to open CSV file");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    fprintf(csv_file, "Timestamp,Channel,Voltage\n");

    while (running) {
        for (i = 0; i < SPI_CHANNEL_COUNT; i++) {
            uint16_t voltage = read_mcp3008(chip, i);
            if (voltage != 0) {
                log_voltage(i, voltage);
            }
        }
        usleep(LOG_INTERVAL * 1000);
    }

    fclose(csv_file);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

