This C program for a Raspberry Pi Zero W reads the voltage on MCP3008 input channels 0, 1, and 2 via SPI0 using chip-enable CE0 on bus 0, configured for SPI mode 0 at a 1 MHz clock. It logs each reading to a CSV file named `analog_log.csv` every 500 ms, with a header row "Timestamp,Channel,Voltage" and each subsequent line including an ISO 8601 timestamp, the channel number, and the measured voltage. The program detects and handles SPI communication errors by checking return codes and either retrying the read or recording the failure. It cleanly responds to a SIGINT (Ctrl+C) by closing the SPI handle, terminating the driver, and closing the CSV file.

code:
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define SPI_CHIP 0
#define SPI_CHANNEL 0
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 500000

#define GPIO_Buzzer 24
#define ADC_THRESHOLD 500

static struct gpiod_chip *chip;
static struct gpiod_line *buzzer_line;
static int spi_fd;

void cleanup() {
    if (buzzer_line) {
        gpiod_line_release(buzzer_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
}

void handle_sigint(int sig) {
    cleanup();
    exit(0);
}

int read_adc(int channel) {
    uint8_t tx[3] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    ssize_t bytes_read;

    bytes_read = write(spi_fd, tx, sizeof(tx));
    if (bytes_read != sizeof(tx)) {
        perror("Failed to write to SPI");
        return -1;
    }

    bytes_read = read(spi_fd, rx, sizeof(rx));
    if (bytes_read != sizeof(rx)) {
        perror("Failed to read from SPI");
        return -1;
    }

    return ((rx[1] & 3) << 8) | rx[2];
}

int main() {
    struct gpiod_line_request_config config = {
        .consumer = "MQ2_Gas_Sensor",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
    };

    signal(SIGINT, handle_sigint);

    // Initialize SPI
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set bits per word");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set max speed");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    buzzer_line = gpiod_chip_get_line(chip, GPIO_Buzzer);
    if (!buzzer_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(buzzer_line, &config) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        int adc_value = read_adc(SPI_CHANNEL);
        if (adc_value < 0) {
            continue;
        }

        if (adc_value >= ADC_THRESHOLD) {
            gpiod_line_set_value(buzzer_line, 1);
        } else {
            gpiod_line_set_value(buzzer_line, 0);
        }

        usleep(500 * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

