This C program for a Raspberry Pi continuously reads the analog output of an MQ-2 gas sensor through an MCP3008 ADC connected on SPI0 using CE0 (GPIO8, BCM) and channel 0, sampling every 500 ms, and drives an active buzzer attached to GPIO24 (BCM). The program initializes the SPI and GPIO libraries, reads the ADC value, and controls the buzzer based on the threshold. It handles a SIGINT (Ctrl-C) by cleaning up resources and exiting gracefully.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE "/dev/i2c-1"
#define ADS1115_ADDRESS 0x48
#define RELAY_PIN 17
#define DOOR_SENSOR_PIN 27
#define CALIBRATION_SAMPLES 10
#define SAMPLE_INTERVAL 50
#define RELAY_DURATION 3000
#define LOG_FILE "/var/log/door_events.log"

int i2c_fd;
int relay_fd;
int door_sensor_fd;
volatile sig_atomic_t running = 1;

void log_event(const char *message) {
    FILE *log = fopen(LOG_FILE, "a");
    if (log) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log, "%ld.%03ld: %s\n", ts.tv_sec, ts.tv_nsec / 1000000, message);
        fclose(log);
    }
}

void handle_signal(int sig) {
    running = 0;
}

void init_i2c() {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void init_relay() {
    relay_fd = open("/sys/class/gpio/gpio17/value", O_WRONLY);
    if (relay_fd < 0) {
        perror("Failed to open relay GPIO");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (write(relay_fd, "0", 1) != 1) {
        perror("Failed to set relay GPIO to low");
        close(i2c_fd);
        close(relay_fd);
        exit(EXIT_FAILURE);
    }
}

void init_door_sensor() {
    door_sensor_fd = open("/sys/class/gpio/gpio27/value", O_RDONLY);
    if (door_sensor_fd < 0) {
        perror("Failed to open door sensor GPIO");
        close(i2c_fd);
        close(relay_fd);
        exit(EXIT_FAILURE);
    }
}

void read_ads1115() {
    uint16_t config = 0b1101000000000000; // Single-shot, 4.096V, 128SPS, AIN0
    if (write(i2c_fd, &config, 2) != 2) {
        perror("Failed to write to ADS1115");
        return;
    }

    usleep(100000); // Wait for conversion to complete

    uint16_t data[2];
    if (read(i2c_fd, data, 2) != 2) {
        perror("Failed to read from ADS1115");
        return;
    }

    int16_t adc_value = (data[0] << 8) | data[1];
    int voltage = (adc_value * 4096) / 32767; // Convert to millivolts
    int distance = 10000 / voltage; // Convert to centimeters

    return distance;
}

void control_relay(int state) {
    if (write(relay_fd, state ? "1" : "0", 1) != 1) {
        perror("Failed to set relay GPIO");
    }
}

void monitor_door() {
    int baseline_sum = 0;
    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        baseline_sum += read_ads1115();
        usleep(SAMPLE_INTERVAL * 1000);
    }
    int baseline = baseline_sum / CALIBRATION_SAMPLES;

    int threshold = baseline * 0.9; // 10% below baseline

    while (running) {
        int distance = read_ads1115();
        if (distance < threshold) {
            control_relay(1);
            usleep(RELAY_DURATION * 1000);
            control_relay(0);

            int door_state = read(door_sensor_fd, NULL, 0);
            if (door_state < 0) {
                perror("Failed to read door sensor");
            } else {
                log_event(door_state ? "door opened" : "door not opened");
            }
        }
        usleep(200 * 1000);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_i2c();
    init_relay();
    init_door_sensor();

    monitor_door();

    close(i2c_fd);
    close(relay_fd);
    close(door_sensor_fd);

    return 0;
}

