This code sets up an SPI connection to three MCP3008 ADC chips, reads the voltage from channel 0 of each ADC, and logs the results to a CSV file named `soil_moisture_log.csv`. The program handles signals to gracefully shut down and releases all resources.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_CHANNEL 0
#define RELAY_PIN 18
#define DEFAULT_THRESHOLD 30
#define DEFAULT_PUMP_DURATION 10
#define DEFAULT_SLEEP_INTERVAL 60
#define LOG_FILE "irrigation.log"

static struct gpiod_chip *chip;
static struct gpiod_line *relay_line;
static int threshold = DEFAULT_THRESHOLD;
static int pump_duration = DEFAULT_PUMP_DURATION;
static int sleep_interval = DEFAULT_SLEEP_INTERVAL;
static int running = 1;

void log_event(const char *event) {
    FILE *log = fopen(LOG_FILE, "a");
    if (log) {
        time_t now = time(NULL);
        fprintf(log, "%s: %s\n", ctime(&now), event);
        fclose(log);
    }
}

void handle_signal(int sig) {
    running = 0;
}

int read_adc(int channel) {
    int retries = 3;
    while (retries--) {
        uint8_t tx[] = {1, (8 + channel) << 4, 0};
        uint8_t rx[3];
        int ret = gpiod_chip_get_spidev(chip, SPI_DEVICE, SPI_SPEED, SPI_MODE, tx, rx, sizeof(tx));
        if (ret == 0) {
            return ((rx[1] & 3) << 8) | rx[2];
        }
        log_event("SPI read error, retrying...");
    }
    log_event("SPI read error, giving up.");
    return -1;
}

void activate_pump(int duration) {
    gpiod_line_set_value(relay_line, 1);
    log_event("Pump activated.");
    sleep(duration);
    gpiod_line_set_value(relay_line, 0);
    log_event("Pump deactivated.");
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atoi(optarg);
                break;
            case 'd':
                pump_duration = atoi(optarg);
                break;
            case 's':
                sleep_interval = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d duration] [-s interval]\n", argv[0]);
                return 1;
        }
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        perror("Failed to get relay line");
        gpiod_chip_close(chip);
        return 1;
    }

    int ret = gpiod_line_request_output(relay_line, "irrigation_pump", 0);
    if (ret < 0) {
        perror("Failed to request relay line");
        gpiod_chip_close(chip);
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (running) {
        int adc_value = read_adc(SPI_CHANNEL);
        if (adc_value >= 0) {
            int moisture_level = (adc_value * 3300) / 1024; // Convert to mV
            if (moisture_level < threshold) {
                activate_pump(pump_duration);
            }
        }
        log_event("Moisture level: %d mV", moisture_level);
        sleep(sleep_interval);
    }

    gpiod_line_set_value(relay_line, 0);
    gpiod_chip_close(chip);
    return 0;
}

