This C program for a Raspberry Pi 4 Model B reads the analog output of a Vegetronix VH400 soil moisture sensor connected to channel 0 of an MCP3008 ADC on SPI0, compares the reading to a configurable threshold, activates a relay-driven water pump on GPIO 18 when the moisture level falls below the threshold, and logs every event to a file named `irrigation.log`. The program handles SPI communication errors by retrying up to three times per read and ensures the pump is turned off on receipt of SIGINT or SIGTERM.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_CE 8
#define SPI_CLK 11
#define SPI_MOSI 10
#define SPI_MISO 9
#define MCP3008_CHANNEL 0
#define SAMPLE_INTERVAL 10  // 10 ms
#define PEAK_THRESHOLD 500  // Adjust as needed

static int spi_fd;
static FILE *log_file;
static struct gpiod_chip *chip;
static struct gpiod_line *ce_line;

void log_peak(int value) {
    time_t now = time(NULL);
    char *iso_time = ctime(&now);
    iso_time[strlen(iso_time) - 1] = '\0';  // Remove newline

    fprintf(log_file, "%s, %d\n", iso_time, value);
    fflush(log_file);
}

void spi_write_read(uint8_t *tx, uint8_t *rx, size_t len) {
    if (gpio_spi_xfer(spi_fd, tx, rx, len) != len) {
        perror("gpio_spi_xfer");
        exit(EXIT_FAILURE);
    }
}

void read_adc_channel(int channel, uint16_t *value) {
    uint8_t tx[3] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];

    spi_write_read(tx, rx, 3);

    *value = ((rx[1] & 3) << 8) | rx[2];
}

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        if (log_file) fclose(log_file);
        if (chip) gpiod_chip_close(chip);
        if (ce_line) gpiod_line_release(ce_line);
        gpioTerminate();
        exit(EXIT_SUCCESS);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    if ((spi_fd = gpioOpenSPI(SPI_CHANNEL, SPI_CLK, SPI_MOSI, SPI_MISO)) < 0) {
        fprintf(stderr, "Failed to open SPI\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if ((chip = gpiod_chip_open("/dev/gpiochip0")) == NULL) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        gpioCloseSPI(spi_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if ((ce_line = gpiod_chip_get_line(chip, SPI_CE)) == NULL) {
        fprintf(stderr, "Failed to get CE line\n");
        gpiod_chip_close(chip);
        gpioCloseSPI(spi_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(ce_line, "SPI_CE", 0) < 0) {
        fprintf(stderr, "Failed to request CE line\n");
        gpiod_line_release(ce_line);
        gpiod_chip_close(chip);
        gpioCloseSPI(spi_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if ((log_file = fopen("/var/log/sound_events.log", "a")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_line_release(ce_line);
        gpiod_chip_close(chip);
        gpioCloseSPI(spi_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t last_value = 0;
    uint16_t peak_value = 0;

    while (1) {
        uint16_t value;
        read_adc_channel(MCP3008_CHANNEL, &value);

        if (value > peak_value) {
            peak_value = value;
        }

        if (value > last_value && value > PEAK_THRESHOLD) {
            log_peak(value);
        }

        last_value = value;

        gpioDelay(SAMPLE_INTERVAL * 1000);
    }

    return EXIT_SUCCESS;
}

