            close(i2c_fd);
            return 1;
        }

        uint8_t dummy_read;
        if (read(i2c_fd, &dummy_read, 1) != 1) {
            perror("Failed to read from I2C device");
            close(i2c_fd);
            return 1;
        }

        uint8_t sample;
        if (read(i2c_fd, &sample, 1) != 1) {
            perror("Failed to read from I2C device");
            close(i2c_fd);
            return 1;
