        if (adc_value < 0) {
            syslog(LOG_ERR, "Failed to read ADC value");
            continue;
        }

        float voltage = adc_to_voltage(adc_value);
        float magnetic_field = adc_to_magnetic_field(voltage);

        if (magnetic_field < 0 || magnetic_field > 3.3) {
            syslog(LOG_WARNING, "Out-of-range voltage: %f V", voltage);
