        }

        add_to_buffer(magnetic_field);
        float average = get_average();
        syslog(LOG_INFO, "Magnetic field: %f Gauss, Average: %f Gauss", magnetic_field, average);

        handle_threshold_crossing(magnetic_field);

        sleep(SAMPLE_RATE);
    }

    return 0;
}

