#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define SPI_CHANNEL 0
#define SPI_CE 0

struct spi_device {
    struct gpiod_chip *chip;
    struct gpiod_line *ce;
};

struct spi_device *spi_init(const char *device, int mode, int speed, int channel, int ce) {
    struct spi_device *dev = malloc(sizeof(*dev));
    if (!dev) {
        perror("Failed to allocate memory for SPI device");
        return NULL;
    }

    dev->chip = gpiod_chip_open(device);
    if (!dev->chip) {
        perror("Failed to open GPIO chip");
        free(dev);
        return NULL;
    }

    dev->ce = gpiod_chip_get_line(dev->chip, ce);
    if (!dev->ce) {
        perror("Failed to get GPIO line for chip enable");
        gpiod_chip_close(dev->chip);
        free(dev);
        return NULL;
    }

    if (gpiod_line_request_output(dev->ce, "SPI_CE", 0) < 0) {
        perror("Failed to request output for chip enable");
        gpiod_chip_close(dev->chip);
        free(dev);
        return NULL;
    }

    if (gpiod_line_set_value(dev->ce, 0) < 0) {
        perror("Failed to set chip enable to low");
        gpiod_line_release(dev->ce);
        gpiod_chip_close(dev->chip);
        free(dev);
        return NULL;
    }

    return dev;
}

void spi_close(struct spi_device *dev) {
    if (dev->ce) {
        gpiod_line_release(dev->ce);
    }
    if (dev->chip) {
        gpiod_chip_close(dev->chip);
    }
    free(dev);
}

int spi_transfer(struct spi_device *dev, uint8_t *tx, uint8_t *rx, size_t len) {
    if (gpiod_line_set_value(dev->ce, 1) < 0) {
        perror("Failed to set chip enable to high");
        return -1;
    }

    if (gpiod_line_set_value(dev->ce, 0) < 0) {
        perror("Failed to set chip enable to low");
        return -1;
    }

    return 0;
}

int read_adc(struct spi_device *dev, uint8_t channel) {
    uint8_t tx[3] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];

    if (spi_transfer(dev, tx, rx, sizeof(rx)) < 0) {
        return -1;
    }

    return ((rx[1] & 3) << 8) | rx[2];
}

void log_rainfall(int adc_value) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    printf("%04d-%02d-%02d %02d:%02d:%02d: ADC=%d, Intensity=%d\n",
           tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
           tm->tm_hour, tm->tm_min, tm->tm_sec,
           adc_value, adc_value * 100 / 1023);
}

void signal_handler(int sig) {
    exit(0);
}

int main() {
    struct spi_device *dev;
    int adc_value, intensity;

    signal(SIGINT, signal_handler);

    dev = spi_init(SPI_DEVICE, SPI_MODE, SPI_SPEED, SPI_CHANNEL, SPI_CE);
    if (!dev) {
        fprintf(stderr, "Failed to initialize SPI device\n");
        return EXIT_FAILURE;
    }

    while (1) {
        adc_value = read_adc(dev, SPI_CHANNEL);
        if (adc_value >= 0) {
            log_rainfall(adc_value);
        } else {
            fprintf(stderr, "Failed to read ADC value\n");
        }

        sleep(1);
    }

    spi_close(dev);
    return EXIT_SUCCESS;
}

