#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define SPI_CHIP 0
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define PWM_PIN 18
#define PWM_FREQ 1000
#define PWM_RANGE 1023
#define ADC_CHANNEL 0
#define ADC_READ_INTERVAL 100

static struct gpiod_chip *chip;
static struct gpiod_line *pwm_line;
static int running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int main() {
    struct gpiod_line_request req;
    uint8_t tx[3] = {1, (ADC_CHANNEL << 4) | 8, 0};
    uint8_t rx[3];
    int ret;

    // Initialize SPI
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    struct gpiod_line_config config;
    gpiod_line_config_init(&config);
    gpiod_line_config_set_direction(&config, GPIOD_LINE_DIRECTION_INPUT);
    gpiod_line_config_set_consumer(&config, "adc");

    struct gpiod_line *adc_line = gpiod_chip_get_line(chip, SPI_CHANNEL);
    if (!adc_line) {
        perror("Failed to get ADC line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request(adc_line, &req, "adc", GPIOD_LINE_REQUEST_DIRECTION_INPUT);
    if (ret < 0) {
        perror("Failed to request ADC line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initialize PWM
    pwm_line = gpiod_chip_get_line(chip, PWM_PIN);
    if (!pwm_line) {
        perror("Failed to get PWM line");
        gpiod_line_release(adc_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(pwm_line, "pwm", 0);
    if (ret < 0) {
        perror("Failed to request PWM line");
        gpiod_line_release(adc_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set PWM frequency and range
    ret = gpiod_line_set_config(pwm_line, GPIOD_LINE_CONFIG_BIAS_PULL_UP, GPIOD_LINE_CONFIG_DRIVE_PUSH_PULL);
    if (ret < 0) {
        perror("Failed to set PWM line configuration");
        gpiod_line_release(pwm_line);
        gpiod_line_release(adc_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_set_period(pwm_line, 1000000 / PWM_FREQ);
    if (ret < 0) {
        perror("Failed to set PWM period");
        gpiod_line_release(pwm_line);
        gpiod_line_release(adc_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_set_duty_cycle(pwm_line, 0);
