#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <sys/ioctl.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x48
#define ADS1115_CONVERSION_REG 0x00
#define ADS1115_CONFIG_REG 0x01
#define ADS1115_CONFIG_SINGLE_ENDED_AIN0 0x8483
#define ADS1115_CONFIG_PGA_4096 0x0000
#define ADS1115_CONFIG_OS_SINGLE 0x8000
#define ADS1115_CONFIG_MODE_CONTINUOUS 0x0000
#define ADS1115_CONFIG_DATA_RATE_8_SPS 0x0000
#define ADS1115_CONFIG_COMP_QUE_DISABLE 0x0000
#define ADS1115_CONFIG_COMP_POL_LOW 0x0000
#define ADS1115_CONFIG_COMP_LAT_NONLATCHING 0x0000
#define ADS1115_CONFIG_COMP_MODE_TRADITIONAL 0x0000
#define ADS1115_CONFIG_COMP_MODE_WINDOW 0x0000
#define ADS1115_CONFIG_COMP_LOW_THRESHOLD 0x0000
#define ADS1115_CONFIG_COMP_HIGH_THRESHOLD 0xFFFF
#define LED_PIN "gpiochip0"
#define LED_LINE "17"
#define THRESHOLD_DEFAULT 100.0

static int i2c_fd;
static struct gpiod_chip *gpio_chip;
static struct gpiod_line *led_line;
static double threshold = THRESHOLD_DEFAULT;

void handle_sigint(int sig) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(0);
}

int read_adc_value() {
    uint16_t config = ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_SINGLE_ENDED_AIN0 | ADS1115_CONFIG_PGA_4096 | ADS1115_CONFIG_MODE_CONTINUOUS | ADS1115_CONFIG_DATA_RATE_8_SPS | ADS1115_CONFIG_COMP_QUE_DISABLE | ADS1115_CONFIG_COMP_POL_LOW | ADS1115_CONFIG_COMP_LAT_NONLATCHING | ADS1115_CONFIG_COMP_MODE_TRADITIONAL | ADS1115_CONFIG_COMP_MODE_WINDOW | ADS1115_CONFIG_COMP_LOW_THRESHOLD | ADS1115_CONFIG_COMP_HIGH_THRESHOLD;
    if (write(i2c_fd, &config, 2) != 2) {
        perror("Failed to write to ADS1115 config register");
        return -1;
    }
    usleep(100000); // Wait for conversion to complete
    uint16_t data[2];
    if (read(i2c_fd, data, 2) != 2) {
        perror("Failed to read from ADS1115 conversion register");
        return -1;
    }
    return (data[0] << 8) | data[1];
}

double adc_to_gauss(int adc_value) {
    return (adc_value * 4.096) / 32767.0;
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize I2C
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return 1;
    }

    // Initialize GPIO
    gpio_chip = gpiod_chip_open(LED_PIN);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }
    led_line = gpiod_chip_get_line(gpio_chip, atoi(LED_LINE));
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }
    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    while (1) {
        int adc_value = read_adc_value();
        if (adc_value >= 0) {
            double gauss = adc_to_gauss(adc_value);
            printf("Magnetic field: %.2f Gauss\n", gauss);
            if (gauss > threshold) {
                for (int i = 0; i < 20; i++) {
                    gpiod_line_set_value(led_line, 1);
                    usleep(50000);
                    gpiod_line_set_value(led_line, 0);
                    usleep(50000);
                }
            }
        }
        usleep(100000);
    }

    return 0;
}

