#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <libgpiod.h>
#include <pigpio.h>
#include <mosquitto.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_CE0_PIN 8
#define RELAY_PIN 17
#define SOIL_MOISTURE_TOPIC "soil_moisture"
#define PUMP_CONTROL_TOPIC "pump_control"
#define HUMIDITY_THRESHOLD_LOW 30
#define HUMIDITY_THRESHOLD_HIGH 35
#define MQTT_BROKER "localhost"

static int relay_state = 0;
static int moisture_value = 0;
static int moisture_threshold_low = HUMIDITY_THRESHOLD_LOW;
static int moisture_threshold_high = HUMIDITY_THRESHOLD_HIGH;
static int moisture_sensor_present = 1;
static struct mosquitto *mosq = NULL;

static void log_event(const char *message) {
    syslog(LOG_INFO, "%s", message);
}

static void handle_spi_error(int result, const char *message) {
    if (result < 0) {
        log_event(message);
        exit(EXIT_FAILURE);
    }
}

static void handle_gpio_error(int result, const char *message) {
    if (result < 0) {
        log_event(message);
        exit(EXIT_FAILURE);
    }
}

static void handle_mqtt_error(int result, const char *message) {
    if (result != MOSQ_ERR_SUCCESS) {
        log_event(message);
        exit(EXIT_FAILURE);
    }
}

static int read_soil_moisture() {
    uint8_t tx[] = {1, (8 + 0) << 4, 0};
    uint8_t rx[3];
    int result = spi_xfer(SPI_CHANNEL, tx, rx, sizeof(tx));
    handle_spi_error(result, "SPI transfer failed");
    return ((rx[1] & 3) << 8) | rx[2];
}

static void control_relay(int state) {
    if (state != relay_state) {
        gpioWrite(RELAY_PIN, state);
        relay_state = state;
        log_event(state ? "Relay ON" : "Relay OFF");
    }
}

static void on_mqtt_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (strcmp(message->topic, PUMP_CONTROL_TOPIC) == 0) {
        if (strcmp((char *)message->payload, "pump_on") == 0) {
            control_relay(1);
        } else if (strcmp((char *)message->payload, "pump_off") == 0) {
            control_relay(0);
        }
    }
}

static void on_mqtt_connect(struct mosquitto *mosq, void *userdata, int rc) {
    if (rc == 0) {
        log_event("Connected to MQTT broker");
        mosquitto_subscribe(mosq, NULL, PUMP_CONTROL_TOPIC, 0);
    } else {
        log_event("Failed to connect to MQTT broker");
        exit(EXIT_FAILURE);
    }
}

static void on_mqtt_disconnect(struct mosquitto *mosq, void *userdata, int rc) {
    log_event("Disconnected from MQTT broker");
}

static void on_mqtt_log(struct mosquitto *mosq, void *userdata, int level, const char *str) {
    log_event(str);
}

static void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        log_event("Received signal, shutting down");
        control_relay(0);
        spi_close(SPI_CHANNEL);
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        gpioTerminate();
        closelog();
        exit(EXIT_SUCCESS);
    }
}

int main() {
    openlog("soil_moisture_sensor", LOG_PID, LOG_USER);

    if (gpioInitialise() < 0) {
        log_event("GPIO initialization failed");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        handle_gpio_error(-1, "Failed to set relay pin mode");
    }

    if (spiOpen(SPI_CHANNEL, SPI_SPEED, 0) < 0) {
        handle_spi_error(-1, "Failed to open SPI channel");
    }

    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        log_event("Failed to create MQTT client");
        exit(EXIT_FAILURE);
    }

    mosquitto_connect_callback_set(mosq, on_mqtt_connect);
    mosquitto_disconnect_callback_set(mosq, on_mqtt_disconnect);
    mosquitto_message_callback_set(mosq, on_mqtt_message);
    mosquitto_log_callback_set(mosq, on_mqtt_log);

    if (mosquitto_connect(mosq, MQTT_BROKER, 1883, 60) != MOSQ_ERR_SUCCESS) {
        handle_mqtt_error(-1, "Failed to connect to MQTT broker");
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        moisture_value = read_soil_moisture();
        if (moisture_value < 0) {
            log_event("Failed to read soil moisture sensor");
            moisture_sensor_present = 0;
        } else {
            moisture_sensor_present = 1;
        }

        if (moisture_sensor_present) {
            if (moisture_value < moisture_threshold_low) {
                control_relay(1);
            } else if (moisture_value > moisture_threshold_high) {
                control_relay(0);
            }
        }

        char message[10];
        snprintf(message, sizeof(message), "%d", moisture_value);
        mosquitto_publish(mosq, NULL, SOIL_MOISTURE_TOPIC, strlen(message), message, 0, false);

        sleep(60);
    }

    return 0;
}

