#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 500000
#define VREF 3.3
#define NUM_CHANNELS 3
#define SAMPLE_INTERVAL 5

struct spi_device {
    struct gpiod_chip *chip;
    struct gpiod_line *ce;
};

struct spi_device *spi_open(const char *device, int mode, int bits_per_word, int speed) {
    struct spi_device *dev = malloc(sizeof(*dev));
    if (!dev) {
        perror("Failed to allocate memory for SPI device");
        return NULL;
    }

    dev->chip = gpiod_chip_open(device);
    if (!dev->chip) {
        perror("Failed to open SPI device");
        free(dev);
        return NULL;
    }

    dev->ce = gpiod_chip_get_line(dev->chip, 0);
    if (!dev->ce) {
        perror("Failed to get chip enable line");
        gpiod_chip_close(dev->chip);
        free(dev);
        return NULL;
    }

    if (gpiod_line_request_output(dev->ce, "spi_ce", 0) < 0) {
        perror("Failed to request chip enable line");
        gpiod_chip_close(dev->chip);
        free(dev);
        return NULL;
    }

    return dev;
}

void spi_close(struct spi_device *dev) {
    if (dev->ce) {
        gpiod_line_release(dev->ce);
    }
    if (dev->chip) {
        gpiod_chip_close(dev->chip);
    }
    free(dev);
}

int spi_transfer(struct spi_device *dev, uint8_t *tx, uint8_t *rx, size_t len) {
    gpiod_line_set_value(dev->ce, 0);
    int ret = gpiod_chip_transfer(dev->chip, tx, rx, len);
    gpiod_line_set_value(dev->ce, 1);
    return ret;
}

float adc_to_voltage(uint16_t adc_value) {
    return (adc_value * VREF) / 1023.0;
}

void signal_handler(int signum) {
    printf("Received signal %d, exiting...\n", signum);
    exit(signum);
}

int main() {
    struct spi_device *spi = spi_open(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED);
    if (!spi) {
        return EXIT_FAILURE;
    }

    FILE *csv_file = fopen("sensor_data.csv", "a");
    if (!csv_file) {
        perror("Failed to open CSV file");
        spi_close(spi);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint8_t tx[3] = {0x01, 0x80, 0x00};
    uint8_t rx[3];

    while (1) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            tx[1] = (tx[1] & 0x1F) | (i << 4);
            if (spi_transfer(spi, tx, rx, 3) < 0) {
                perror("SPI transfer failed");
                goto cleanup;
            }
            uint16_t adc_value = ((rx[1] & 0x03) << 8) | rx[2];
            float voltage = adc_to_voltage(adc_value);
            fprintf(csv_file, "%.6f,", voltage);
        }
        fprintf(csv_file, "\n");
        fflush(csv_file);
        sleep(SAMPLE_INTERVAL);
    }

cleanup:
    fclose(csv_file);
    spi_close(spi);
    return EXIT_FAILURE;
}

