This C program for a Raspberry Pi Zero W continuously reads the analog voltage on channels 0, 1, and 2 of an MCP3008 connected to SPI0 using chip-enable 0. It converts the 10-bit values to voltages, appends a timestamped line with the three voltage readings to a CSV file named `sensor_data.csv` every 5 seconds. The program initializes the driver library, opens the SPI interface, performs SPI transfers, and handles file operations. It also installs signal handlers for SIGINT and SIGTERM to release resources cleanly on termination.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <libgpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 500000
#define ADC_CHANNEL 0
#define PWM_FREQ 100
#define PWM_DUTY_MIN 0
#define PWM_DUTY_MAX 500
#define THRESHOLD 500
#define LOG_FILE "vibration_log.txt"

static struct gpiod_chip *chip;
static struct gpiod_line *motor1, *motor2;
static int spi_fd;
static FILE *log_file;

void log_event(const char *message) {
    if (log_file) {
        time_t now = time(NULL);
        fprintf(log_file, "%s: %s\n", ctime(&now), message);
        fflush(log_file);
    }
}

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        if (motor1) gpiod_line_set_value(motor1, 0);
        if (motor2) gpiod_line_set_value(motor2, 0);
        if (chip) gpiod_chip_close(chip);
        if (log_file) fclose(log_file);
        if (spi_fd >= 0) close(spi_fd);
        exit(0);
    }
}

int read_adc(int channel) {
    uint8_t tx[3] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    ssize_t bytes_read;

    if (write(spi_fd, tx, 3) != 3) {
        perror("SPI write failed");
        return -1;
    }

    bytes_read = read(spi_fd, rx, 3);
    if (bytes_read != 3) {
        perror("SPI read failed");
        return -1;
    }

    return ((rx[1] & 3) << 8) | rx[2];
}

void set_pwm_duty(struct gpiod_line *line, int duty) {
    if (duty < PWM_DUTY_MIN) duty = PWM_DUTY_MIN;
    if (duty > PWM_DUTY_MAX) duty = PWM_DUTY_MAX;
    gpiod_line_set_value(line, duty);
}

int main() {
    struct sigaction sa;
    struct timespec ts = {0, 10000000}; // 10 ms

    // Initialize GPIO
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    motor1 = gpiod_chip_get_line(chip, 17);
    if (!motor1) {
        perror("Failed to get GPIO line 17");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    motor2 = gpiod_chip_get_line(chip, 27);
    if (!motor2) {
        perror("Failed to get GPIO line 27");
        gpiod_line_release(motor1);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(motor1, "motor1", 0) < 0) {
        perror("Failed to request output for GPIO line 17");
        gpiod_line_release(motor1);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(motor2, "motor2", 0) < 0) {
        perror("Failed to request output for GPIO line 27");
        gpiod_line_release(motor1);
        gpiod_line_release(motor2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initialize SPI
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        gpiod_line_release(motor1);
        gpiod_line_release(motor2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        gpiod_line_release(motor1);
        gpiod_line_release(motor2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        gpiod_line_release(motor1);
        gpiod_line_release(motor2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        gpiod_line_release(motor1);
        gpiod_line_release(motor2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initialize log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(spi_fd);
        gpiod_line_release(motor1);
        gpiod_line_release(motor2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up signal handler
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            log_event("ADC read error");
            continue;
        }

        if (adc_value > THRESHOLD) {
            set_pwm_duty(motor1, adc_value);
            set_pwm_duty(motor2, adc_value);
            log_event("Vibration detected");
        } else {
            set_pwm_duty(motor1, 0);
            set_pwm_duty(motor2, 0);
        }

        nanosleep(&ts, NULL);
    }

    // Cleanup
    fclose(log_file);
    close(spi_fd);
    gpiod_line_release(motor1);
    gpiod_line_release(motor2);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

