void signal_handler(int signum) {
    running = 0;
}

int read_bh1750(int fd) {
    uint8_t data[2];
    if (i2c_write_byte_data(fd, BH1750_ADDRESS, BH1750_CONT_HRES_MODE) < 0) {
        return -1;
    }
    usleep(180000);
    if (i2c_read_i2c_block_data(fd, BH1750_ADDRESS, data, 2) < 0) {
        return -1;
    }
    return (data[0] << 8) | data[1];
}

int read_max9814(int fd) {
    uint8_t data[2];
    if (gpio_spi_xfer2(fd, data, data, 2) < 0) {
        return -1;
    }
    return (data[0] << 8) | data[1];
}

