        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_input(line, "max9814_analog") < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initialize SPI
    if ((spi_fd = gpio_spi_open(SPI_CHANNEL, SPI_SPEED, 0)) < 0) {
        perror("Failed to open SPI device");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initialize I2C
    if ((i2c_fd = i2c_open(I2C_BUS, BH1750_ADDRESS, 0)) < 0) {
        perror("Failed to open I2C device");
        gpio_spi_close(spi_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open CSV file
    if ((csv_file = fopen(CSV_FILE, "w")) == NULL) {
        perror("Failed to open CSV file");
        i2c_close(i2c_fd);
        gpio_spi_close(spi_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    fprintf(csv_file, "timestamp,sound_level_db,light_level_lux,error_code\n");

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        now = time(NULL);
        tm_info = localtime(&now);
        fprintf(csv_file, "%04d-%02d-%02d %02d:%02d:%02d,", tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday, tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec);

        sound_level = read_max9814(spi_fd);
        if (sound_level < 0) {
            error_code = 1;
        } else {
            error_code = 0;
        }
        fprintf(csv_file, "%d,", sound_level);

        light_level = read_bh1750(i2c_fd);
        if (light_level < 0) {
            error_code = 2;
        } else {
            error_code = 0;
        }
        fprintf(csv_file, "%d,", light_level);

        fprintf(csv_file, "%d\n", error_code);

        fflush(csv_file);
        sleep(LOG_INTERVAL);
    }

    // Clean up
    fclose(csv_file);
    i2c_close(i2c_fd);
    gpio_spi_close(spi_fd);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

