#include <libgpiod.h>
#include <gpiod.h>
#include <spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_BITS_PER_WORD 8
#define SPI_CHANNEL 0
#define GPIO_PIN 17
#define MOISTURE_THRESHOLD 30
#define READ_INTERVAL 60

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static int spi_fd;

void cleanup() {
    if (line) {
        gpiod_line_release(line);
        gpiod_chip_close(chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
}

void handle_sigint(int sig) {
    cleanup();
    exit(0);
}

int read_moisture_sensor() {
    uint8_t tx[3] = {0x01, (SPI_CHANNEL << 4) | 0x08, 0x00};
    uint8_t rx[3];
    int ret;

    for (int i = 0; i < 3; i++) {
        ret = write(spi_fd, tx + i, 1);
        if (ret != 1) {
            perror("SPI write failed");
            return -1;
        }
        ret = read(spi_fd, rx + i, 1);
        if (ret != 1) {
            perror("SPI read failed");
            return -1;
        }
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    int moisture_percentage = (adc_value * 100) / 1023;
    return moisture_percentage;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Initialize GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int ret = gpiod_line_request_output(line, "water_pump", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initialize SPI
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        cleanup();
        return EXIT_FAILURE;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_BITS_PER_WORD);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        cleanup();
        return EXIT_FAILURE;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD);
    if (ret < 0) {
        perror("Failed to set SPI bits per word");
        cleanup();
        return EXIT_FAILURE;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret < 0) {
        perror("Failed to set SPI speed");
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        int moisture = read_moisture_sensor();
        if (moisture < 0) {
            continue;
        }

        printf("Timestamp: %ld, Moisture: %d%%\n", time(NULL), moisture);

        if (moisture < MOISTURE_THRESHOLD) {
            ret = gpiod_line_set_value(line, 1);
            if (ret < 0) {
                perror("Failed to turn on water pump");
            }
        } else {
            ret = gpiod_line_set_value(line, 0);
            if (ret < 0) {
                perror("Failed to turn off water pump");
            }
        }

        sleep(READ_INTERVAL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

