#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>
#include <libgpiod/spi.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define SPI_CHANNEL 0
#define FAN_PIN 18
#define FAN_ON 1
#define FAN_OFF 0
#define CO2_THRESHOLD 700
#define LOG_FILE "air_quality.log"

static struct gpiod_chip *chip;
static struct gpiod_line *fan_line;
static int spi_fd;

void log_event(const char *timestamp, int co2_ppm, int fan_state) {
    FILE *log = fopen(LOG_FILE, "a");
    if (log == NULL) {
        perror("Failed to open log file");
        return;
    }
    fprintf(log, "%s,%d,%d\n", timestamp, co2_ppm, fan_state);
    fclose(log);
}

int read_adc_value(int channel) {
    uint8_t tx[3] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    ssize_t bytes_read;

    while ((bytes_read = gpiod_spi_transfer(spi_fd, tx, rx, 3)) != 3) {
        if (bytes_read == -1) {
            perror("SPI transfer failed");
            return -1;
        }
        sleep(1); // Retry after 1 second
    }

    return ((rx[1] & 3) << 8) | rx[2];
}

int calculate_co2_ppm(int adc_value) {
    // MQ-135 sensor voltage range is 0-3.3V
    float voltage = (adc_value * 3.3) / 1023.0;
    // Assuming a linear relationship for simplicity
