#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>
#include <libgpiod/spi.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_CHANNEL 0
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define DEBOUNCE_TIME 1000000 // 1 second in microseconds
#define MIN_DISTANCE 20 // 20 cm
#define LOG_FILE "door_events.log"

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static int running = 1;

void signal_handler(int sig) {
    running = 0;
}

int read_sensor_value(int fd) {
    uint8_t tx[] = {0x12, 0x00}; // MCP3008 command for single-ended channel 0
    uint8_t rx[3];
    ssize_t ret;

    ret = gpiod_spi_transfer(fd, tx, sizeof(tx), rx, sizeof(rx));
    if (ret < 0) {
        perror("gpiod_spi_transfer");
        return -1;
    }

    // Extract the 10-bit value from the response
    int value = ((rx[1] & 0x03) << 8) | rx[2];
    return value;
}

int main() {
    int fd;
    FILE *log_file;
    struct timespec ts;
    time_t now;
    char timestamp[20];

    // Open SPI device
    fd = gpiod_spi_open(SPI_DEVICE, SPI_SPEED, SPI_CHANNEL);
    if (fd < 0) {
        perror("gpiod_spi_open");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        close(fd);
        return EXIT_FAILURE;
    }

    // Request GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        close(fd);
        return EXIT_FAILURE;
    }

    // Configure GPIO line as output
    if (gpiod_line_request_output(line, "relay", 0) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        close(fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(fd);
        return EXIT_FAILURE;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    while (running) {
        int sensor_value = read_sensor_value(fd);
        if (sensor_value < 0) {
            continue;
        }

        // Convert sensor value to distance (assuming a linear relationship)
        int distance = (sensor_value * 3.3 * 100) / 1024 / 10; // Convert to cm

        if (distance < MIN_DISTANCE) {
            // Energize relay
            if (gpiod_line_set_value(line, 1) < 0) {
                perror("gpiod_line_set_value");
                continue;
            }

            // Log event
            clock_gettime(CLOCK_REALTIME, &ts);
            now = ts.tv_sec;
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
            fprintf(log_file, "%s - Door opened (distance: %d cm)\n", timestamp, distance);
            fflush(log_file);

            // Debounce delay
            usleep(DEBOUNCE_TIME);
        } else {
            // De-energize relay
            if (gpiod_line_set_value(line, 0) < 0) {
                perror("gpiod_line_set_value");
                continue;
            }
        }

        // Poll every 100 ms
        usleep(100000);
    }

    // Clean up
    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(fd);

    return EXIT_SUCCESS;
}

