#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define SPI_CHANNEL 0
#define SPI_CE_PIN 8
#define SPI_READ_RETRIES 5
#define SPI_BACKOFF_BASE 100000

#define ADC_START_BIT 1
#define ADC_SINGLE_ENDED 1
#define ADC_CHANNEL_0 0

#define LOG_FILE "soil_data.txt"

static struct gpiod_chip *chip;
static struct gpiod_line *ce_line;
static FILE *log_file;

static void handle_sigint(int sig) {
    fprintf(stderr, "Received signal %d, shutting down...\n", sig);
    if (log_file) fclose(log_file);
    if (ce_line) gpiod_line_release(ce_line);
    if (chip) gpiod_chip_close(chip);
    exit(0);
}

static int read_adc_value() {
    uint8_t tx[3] = {ADC_START_BIT | ADC_SINGLE_ENDED | (ADC_CHANNEL_0 << 4), 0, 0};
    uint8_t rx[3];
    int ret;

    for (int i = 0; i < SPI_READ_RETRIES; i++) {
        ret = gpiod_line_set_value(ce_line, 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to set CE line high: %s\n", gpiod_error_str(ret));
            usleep(SPI_BACKOFF_BASE * (1 << i));
            continue;
        }

        ret = gpiod_chip_transfer(chip, tx, rx, 3);
        if (ret < 0) {
            fprintf(stderr, "Failed to transfer SPI data: %s\n", gpiod_error_str(ret));
            usleep(SPI_BACKOFF_BASE * (1 << i));
            continue;
        }

        ret = gpiod_line_set_value(ce_line, 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to set CE line low: %s\n", gpiod_error_str(ret));
            usleep(SPI_BACKOFF_BASE * (1 << i));
            continue;
        }

        uint16_t adc_value = ((rx[1] & 0x03) << 8) | rx[2];
        if (adc_value >= 0 && adc_value <= 1023) {
            return adc_value;
        } else {
            fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
        }
    }

    fprintf(stderr, "Failed to read valid ADC value after %d retries\n", SPI_READ_RETRIES);
    return -1;
}

static void log_reading(time_t timestamp, int adc_value) {
    if (log_file) {
        fprintf(log_file, "%ld,%d\n", timestamp, adc_value);
        fflush(log_file);
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", gpiod_error_str(-1));
        return 1;
    }

    ce_line = gpiod_chip_get_line(chip, SPI_CE_PIN);
    if (!ce_line) {
        fprintf(stderr, "Failed to get CE line: %s\n", gpiod_error_str(-1));
        gpiod_chip_close(chip);
        return 1;
    }

    int ret = gpiod_line_request_output(ce_line, "soil_moisture_sensor", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request CE line output: %s\n", gpiod_error_str(ret));
        gpiod_chip_close(chip);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpiod_line_release(ce_line);
        gpiod_chip_close(chip);
        return 1;
    }

    while (1) {
        time_t timestamp = time(NULL);
        int adc_value = read_adc_value();
        if (adc_value >= 0) {
            int moisture_percentage = (adc_value * 100) / 1023;
            log_reading(timestamp, moisture_percentage);
        } else {
            log_reading(timestamp, -1);
        }
        sleep(5);
    }

    fclose(log_file);
    gpiod_line_release(ce_line);
    gpiod_chip_close(chip);
    return 0;
}

