#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define SPI_BITS 8
#define SPI_MODE 0

#define LDR_PIN 0
#define TRIG_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18

#define PWM_FREQ 1000
#define PWM_RANGE 100

#define CONFIG_FILE "theremin_config.txt"

volatile int running = 1;
volatile int last_distance = 0;
volatile int last_volume = 0;

void signal_handler(int sig) {
    running = 0;
}

int read_ldr() {
    int adc_value = spi_xfer2(SPI_CHANNEL, &LDR_PIN, 1, SPI_SPEED, SPI_BITS, SPI_MODE);
    if (adc_value < 0) {
        return last_volume;
    }
    last_volume = adc_value;
    return last_volume;
}

int measure_distance() {
    gpioWrite(TRIG_PIN, 0);
    usleep(2);
    gpioWrite(TRIG_PIN, 1);
    usleep(10);
    gpioWrite(TRIG_PIN, 0);

    int start_time = gpioTick();
    int end_time = start_time;

    while (gpioRead(ECHO_PIN) == 0 && end_time - start_time < 1000000) {
        end_time = gpioTick();
    }

    if (end_time - start_time >= 1000000) {
        return last_distance;
    }

    start_time = end_time;
    while (gpioRead(ECHO_PIN) == 1 && end_time - start_time < 1000000) {
        end_time = gpioTick();
    }

    if (end_time - start_time >= 1000000) {
        return last_distance;
    }

    int duration = end_time - start_time;
    int distance = (duration * 0.034) / 2;
    last_distance = distance;
    return last_distance;
}

void save_config() {
    FILE *file = fopen(CONFIG_FILE, "w");
    if (file) {
        fprintf(file, "%d %d\n", last_distance, last_volume);
        fclose(file);
    }
}

void load_config() {
    FILE *file = fopen(CONFIG_FILE, "r");
    if (file) {
        fscanf(file, "%d %d", &last_distance, &last_volume);
        fclose(file);
    }
}

