#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define ADC_CHANNEL 0
#define FAN_PIN 18
#define AQI_THRESHOLD 100
#define SPI_RETRIES 3
#define SPI_RETRY_DELAY 1

static int spi_fd = -1;
static int fan_gpio = -1;
static FILE *log_file = NULL;

void log_aqi(int aqi) {
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline character

    fprintf(log_file, "%s, AQI: %d\n", timestamp, aqi);
    fflush(log_file);
}

int read_adc(int channel) {
    int retries = SPI_RETRIES;
    while (retries > 0) {
        uint8_t tx[3] = {1, (8 + channel) << 4, 0};
        uint8_t rx[3];

        if (gpioSPIDataRW(SPI_CHANNEL, tx, 3, rx) == 3) {
            return ((rx[1] & 3) << 8) + rx[2];
        }

        retries--;
        sleep(SPI_RETRY_DELAY);
    }

    return -1;
}

int compute_aqi(int adc_value) {
    // Simplified AQI calculation for demonstration purposes
    return adc_value * 10; // Example conversion
}

void handle_sigint(int sig) {
    if (fan_gpio != -1) {
        gpioWrite(fan_gpio, PI_OFF);
    }
    if (spi_fd != -1) {
        gpioSPIClose(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if ((fan_gpio = gpioOpen(FAN_PIN, PI_OUTPUT, PI_OFF)) < 0) {
        fprintf(stderr, "Failed to open GPIO pin %d\n", FAN_PIN);
        gpioTerminate();
        return 1;
    }

    if ((spi_fd = gpioSPIClose(SPI_CHANNEL)) < 0) {
        fprintf(stderr, "Failed to open SPI channel %d\n", SPI_CHANNEL);
        gpioTerminate();
        return 1;
    }

    if ((log_file = fopen("air_quality.log", "a")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
