#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define ADC_MIN 0
#define ADC_MAX 1023
#define ALCOHOL_LIMIT 50
#define SOBRIETY_LIMIT 20
#define RETRY_COUNT 3
#define RETRY_DELAY 100000 // 100 ms

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int read_adc(int channel) {
    uint8_t tx[3] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    int ret;

    for (int i = 0; i < RETRY_COUNT; i++) {
        ret = gpiod_spi_xfer(tx, rx, 3);
        if (ret == 3) {
            return ((rx[1] & 3) << 8) | rx[2];
        }
        usleep(RETRY_DELAY);
    }

    fprintf(stderr, "Failed to read ADC after %d retries\n", RETRY_COUNT);
    return -1;
}

void log_measurement(int value) {
    time_t now = time(NULL);
    struct tm *utc_time = gmtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc_time);

    FILE *log_file = fopen("alcohol_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "%s: %d ppm\n", timestamp, value);
    fclose(log_file);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int adc_value;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, 8);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "spi0_ce0", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_spi_configure(line, SPI_SPEED, SPI_MODE, SPI_BITS) < 0) {
        perror("Failed to configure SPI");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        adc_value = read_adc(MCP3008_CHANNEL);
        if (adc_value >= 0) {
            if (adc_value == ADC_MIN || adc_value == ADC_MAX) {
                fprintf(stderr, "Sensor absent or short-circuited\n");
            } else if (adc_value > ALCOHOL_LIMIT) {
                printf("Alcohol detected! Limit exceeded.\n");
            } else if (adc_value < SOBRIETY_LIMIT) {
                printf("Sobriety confirmed.\n");
            } else {
                printf("Alcohol level within acceptable range.\n");
            }
            log_measurement(adc_value);
        }
        sleep(1);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

