#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>
#include <gpiod.h>

#define SPI_CHIP 0
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define RELAY_PIN 18
#define SOIL_MOISTURE_THRESHOLD 300
#define LOG_FILE "irrigation.log"

static struct gpiod_chip *chip;
static struct gpiod_line *relay_line;
static FILE *log_file;

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        if (relay_line) {
            gpiod_line_set_value(relay_line, 0);
        }
        if (log_file) {
            fclose(log_file);
        }
        if (chip) {
            gpiod_chip_close(chip);
        }
        exit(EXIT_SUCCESS);
    }
}

uint16_t read_soil_moisture() {
    uint8_t tx[3] = {1, (8 + SPI_CHANNEL) << 4, 0};
    uint8_t rx[3];
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = 8,
    };

    if (ioctl(chip->fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI_IOC_MESSAGE");
        return 0;
    }

    return ((rx[1] & 3) << 8) | rx[2];
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        perror("Failed to get relay line");
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(relay_line, "irrigation_pump", 0) < 0) {
        perror("Failed to request relay line as output");
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    while (1) {
        uint16_t moisture = read_soil_moisture();
        if (moisture == 0) {
            fprintf(stderr, "Failed to read soil moisture sensor\n");
            continue;
        }

        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        fprintf(log_file, "%s, Moisture: %d, Pump: %s\n", timestamp, moisture, moisture < SOIL_MOISTURE_THRESHOLD ? "ON" : "OFF");
        fflush(log_file);

        if (moisture < SOIL_MOISTURE_THRESHOLD) {
            gpiod_line_set_value(relay_line, 1);
        } else {
            gpiod_line_set_value(relay_line, 0);
        }

        sleep(60);
    }

    return EXIT_SUCCESS;
}

