This C program for a Raspberry Pi 4 Model B continuously reads the DFROBOT Soil Moisture Sensor through an MCP3008 8-channel 10-bit ADC on SPI0, samples the moisture value every 60 seconds, and activates a relay-driven water pump on BCM GPIO18 whenever the reading falls below the threshold of 300. Each reading together with the pump status (ON or OFF) and a timestamp is appended to a file named `irrigation.log`. The program verifies successful initialization of all driver library APIs, opening of the SPI interface, and opening of the log file, handles any sensor read failures by logging an error and continuing, and cleans up resources on receipt of SIGINT or SIGTERM.

code:
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define MCP3008_ADDRESS 0x48
#define MOTOR1_ENABLE 18
#define MOTOR2_ENABLE 24
#define MOTOR1_DIRECTION 23
#define MOTOR2_DIRECTION 25
#define MOTOR_SPEED 1000
#define ACCELERATION_TIME 1
#define DECELERATION_TIME 1
#define CONSTANT_SPEED_TIME 2
#define PAUSE_TIME 5

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int read_potentiometer(int channel) {
    int value = spi_xfer2(SPI_CHANNEL, MCP3008_ADDRESS, (channel << 4) | 0x18, 2);
    if (value < 0) {
        fprintf(stderr, "Failed to read potentiometer on channel %d\n", channel);
        return -1;
    }
    return (value >> 6) & 0x3F;
}

void set_motor_speed(int motor, int direction, int speed) {
    gpioWrite(motor, direction);
    gpioSetPWMRange(motor, 1000);
    gpioSetPWMFrequency(motor, 100);
    gpioSetPWM(motor, speed);
}

void cleanup() {
    gpioTerminate();
    spiClose(SPI_CHANNEL);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    if (spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE) < 0) {
        fprintf(stderr, "Failed to open SPI channel %d\n", SPI_CHANNEL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MOTOR1_ENABLE, PI_OUTPUT) < 0 || gpioSetMode(MOTOR2_ENABLE, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR1_DIRECTION, PI_OUTPUT) < 0 || gpioSetMode(MOTOR2_DIRECTION, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for motor control\n");
        cleanup();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        int pot1_value = read_potentiometer(0);
        int pot2_value = read_potentiometer(1);

        if (pot1_value < 0 || pot2_value < 0) {
            continue;
        }

        int speed1 = pot1_value * MOTOR_SPEED / 63;
        int speed2 = pot2_value * MOTOR_SPEED / 63;

        set_motor_speed(MOTOR1_ENABLE, MOTOR1_DIRECTION, 0);
        set_motor_speed(MOTOR2_ENABLE, MOTOR2_DIRECTION, 0);

        for (int i = 0; i <= speed1; i++) {
            set_motor_speed(MOTOR1_ENABLE, MOTOR1_DIRECTION, i);
            usleep(ACCELERATION_TIME * 1000000 / speed1);
        }

        for (int i = 0; i <= speed2; i++) {
            set_motor_speed(MOTOR2_ENABLE, MOTOR2_DIRECTION, i);
            usleep(ACCELERATION_TIME * 1000000 / speed2);
        }

        sleep(CONSTANT_SPEED_TIME);

        for (int i = speed1; i >= 0; i--) {
            set_motor_speed(MOTOR1_ENABLE, MOTOR1_DIRECTION, i);
            usleep(DECELERATION_TIME * 1000000 / speed1);
        }

        for (int i = speed2; i >= 0; i--) {
            set_motor_speed(MOTOR2_ENABLE, MOTOR2_DIRECTION, i);
            usleep(DECELERATION_TIME * 1000000 / speed2);
        }

        sleep(PAUSE_TIME);

        set_motor_speed(MOTOR1_ENABLE, MOTOR1_DIRECTION, speed1);
        set_motor_speed(MOTOR2_ENABLE, MOTOR2_DIRECTION, speed2);
        sleep(1);
        set_motor_speed(MOTOR1_ENABLE, MOTOR1_DIRECTION, 0);
        set_motor_speed(MOTOR2_ENABLE, MOTOR2_DIRECTION, 0);
        sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

