#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_CE 0
#define SPI_SPEED 1000000
#define SAMPLE_INTERVAL 100
#define LOG_FILE "airflow_log.txt"

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int read_adc(int channel) {
    int value = spi_xfer2(SPI_CHANNEL, &channel, 1, 1);
    if (value < 0) {
        fprintf(stderr, "ERROR: ADC read failed\n");
        return -1;
    }
    return value;
}

void log_reading(int value) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "ERROR: Failed to open log file\n");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s: ADC Value: %d\n", timestamp, value);
    fclose(log_file);
}

void init_spi() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "ERROR: Failed to initialize GPIO\n");
        exit(EXIT_FAILURE);
    }

    if (spiOpen(SPI_CHANNEL, SPI_SPEED, 0) < 0) {
        fprintf(stderr, "ERROR: Failed to open SPI channel\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void cleanup() {
    gpioTerminate();
}

int main() {
    signal(SIGINT, signal_handler);

    init_spi();

    while (running) {
        int adc_value = read_adc(SPI_CE);
        if (adc_value >= 0) {
            log_reading(adc_value);
        }

        usleep(SAMPLE_INTERVAL * 1000);
    }

    cleanup();
    return 0;
}

