#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <sys/time.h>
#include <signal.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_DEVICE "/sys/class/gpio/gpio8/value"
#define LOG_FILE "audio_log.txt"
#define SAMPLE_RATE 1000
#define SAMPLE_INTERVAL_NS (1000000000 / SAMPLE_RATE)

static int spi_fd = -1;
static int gpio_fd = -1;
static FILE *log_file = NULL;

static void close_resources() {
    if (gpio_fd != -1) {
        close(gpio_fd);
        gpio_fd = -1;
    }
    if (spi_fd != -1) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

static void signal_handler(int signum) {
    close_resources();
    exit(signum);
}

int main() {
    struct spi_ioc_transfer tr;
    uint8_t tx[3] = {0x01, 0x80, 0x00};
    uint8_t rx[3];
    struct timespec ts, now, next;
    uint32_t timestamp_ns;
    int ret;

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    // Set SPI mode
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &mode);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Set SPI bits per word
    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits_per_word);
    if (ret < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Set SPI max speed
    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &max_speed_hz);
    if (ret < 0) {
        perror("Failed to set SPI max speed");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Open GPIO device
    gpio_fd = open(GPIO_DEVICE, O_WRONLY);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO device");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Set GPIO direction to output
    ret = write(gpio_fd, "1", 1);
    if (ret < 0) {
        perror("Failed to set GPIO direction");
        close(gpio_fd);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(gpio_fd);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize next sample time
    clock_gettime(CLOCK_MONOTONIC_RAW, &next);

    while (1) {
        // Toggle chip select
        ret = write(gpio_fd, "0", 1);
        if (ret < 0) {
            perror("Failed to toggle chip select");
            close_resources();
            return EXIT_FAILURE;
        }

        // Transfer data
        memset(&tr, 0, sizeof(tr));
        tr.tx_buf = (unsigned long)tx;
        tr.rx_buf = (unsigned long)rx;
        tr.len = sizeof(rx);
        tr.speed_hz = max_speed_hz;
        tr.delay_usecs = 0;
        tr.bits_per_word = bits_per_word;

        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
        if (ret < 0) {
            perror("Failed to transfer data");
            close_resources();
            return EXIT_FAILURE;
        }

        // Read ADC value
        uint16_t adc_value = ((rx[1] & 0x03) << 8) | rx[2];

        // Get timestamp
        clock_gettime(CLOCK_MONOTONIC_RAW, &now);
        timestamp_ns = (now.tv_sec - next.tv_sec) * 1000000000 + (now.tv_nsec - next.tv_nsec);

        // Write to log file
        fprintf(log_file, "%lu|%u\n", timestamp_ns, adc_value);
        fflush(log_file);

        // Calculate next sample time
        next.tv_sec += SAMPLE_INTERVAL_NS / 1000000000;
        next.tv_nsec += SAMPLE_INTERVAL_NS % 1000000000;
        if (next.tv_nsec >= 1000000000) {
            next.tv_sec++;
            next.tv_nsec -= 1000000000;
        }

        // Sleep until next sample time
        ret = clock_nanosleep(CLOCK_MONOTONIC_RAW, TIMER_ABSTIME, &next, NULL);
        if (ret < 0) {
            perror("Failed to sleep");
            close_resources();
            return EXIT_FAILURE;
        }
    }

    return EXIT_SUCCESS;
}

