#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000
#define SPI_CHANNEL 0
#define SPI_CE 0
#define ADC_CHANNEL 0
#define ADC_REF_VOLTAGE 3.3
#define ADC_MAX_VALUE 1023
#define LOG_FILE "gas_log.txt"
#define RETRY_DELAY 100000 // 100 ms in microseconds

volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

uint16_t read_adc(struct gpiod_chip *chip, int channel) {
    uint8_t tx[3] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    struct gpiod_line *ce_line = gpiod_chip_get_line(chip, SPI_CE);
    if (!ce_line) {
        perror("Failed to get CE line");
        return 0;
    }
    if (gpiod_line_request_output(ce_line, "SPI_CE", 0) < 0) {
        perror("Failed to request CE line");
        return 0;
    }
    while (gpiod_line_set_value(ce_line, 1) < 0) {
        usleep(100);
    }
    if (gpiod_chip_write(chip, tx, 3) < 0) {
        perror("Failed to write to SPI");
        return 0;
    }
    if (gpiod_chip_read(chip, rx, 3) < 0) {
        perror("Failed to read from SPI");
        return 0;
    }
    while (gpiod_line_set_value(ce_line, 0) < 0) {
        usleep(100);
    }
    gpiod_line_release(ce_line);
    return ((rx[1] & 3) << 8) | rx[2];
}

int main() {
    struct gpiod_chip *chip;
    FILE *log_file;
    struct timespec ts;
    uint16_t adc_value;
    float voltage, ppm;

    signal(SIGINT, sigint_handler);

    chip = gpiod_chip_open(SPI_DEVICE);
    if (!chip) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        adc_value = read_adc(chip, ADC_CHANNEL);
        if (adc_value == 0) {
            usleep(RETRY_DELAY);
            continue;
        }
        voltage = (adc_value * ADC_REF_VOLTAGE) / ADC_MAX_VALUE;
        ppm = 0.0; // Placeholder PPM value

        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld.%09ld, %.2f, %.2f\n", ts.tv_sec, ts.tv_nsec, voltage, ppm);
        fflush(log_file);

        printf("Voltage: %.2f V, PPM: %.2f\n", voltage, ppm);

        sleep(1);
    }

    fclose(log_file);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

