uint16_t read_mcp3008_channel(int channel) {
    uint8_t tx[3] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    int ret;

    ret = gpiod_spi_xfer(spi_dev, tx, rx, 3);
    if (ret < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(-ret));
        return 0;
