#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_SENSOR1 4
#define GPIO_SENSOR2 17
#define GPIO_SENSOR3 27
#define LOG_FILE "magnetic_log.txt"
#define SAMPLE_INTERVAL 100000  // 100 milliseconds in microseconds
#define MIN_FIELD -100
#define MAX_FIELD 100

struct gpiod_chip *chip;
struct gpiod_line *line1, *line2, *line3;
FILE *log_file;

void handle_sigint(int sig) {
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(0);
}

int read_sensor(int gpio) {
    struct gpiod_line_event event;
    int ret;

    ret = gpiod_line_event_wait(line1, SAMPLE_INTERVAL);
    if (ret < 0) {
        perror("gpiod_line_event_wait");
        return -1;
    }

    ret = gpiod_line_event_read(line1, &event);
    if (ret < 0) {
        perror("gpiod_line_event_read");
        return -1;
    }

    return gpiod_line_get_value(line1);
}

double sensor_to_field(int state) {
    // Assuming a linear relationship between sensor state and magnetic field
    // This is a simplified model and may need calibration
    return (double)state * 10.0;  // Example conversion factor
}

int main() {
    int ret;
    int sensor1_state, sensor2_state, sensor3_state;
    double sensor1_field, sensor2_field, sensor3_field;
    char log_entry[128];

    signal(SIGINT, handle_sigint);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, GPIO_SENSOR1);
    if (!line1) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_SENSOR2);
    if (!line2) {
        perror("gpiod_chip_get_line");
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line3 = gpiod_chip_get_line(chip, GPIO_SENSOR3);
    if (!line3) {
        perror("gpiod_chip_get_line");
        gpiod_line_release(line2);
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(line1, "sensor1");
    if (ret < 0) {
        perror("gpiod_line_request_input");
        gpiod_line_release(line3);
        gpiod_line_release(line2);
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(line2, "sensor2");
    if (ret < 0) {
        perror("gpiod_line_request_input");
        gpiod_line_release(line3);
        gpiod_line_release(line2);
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(line3, "sensor3");
    if (ret < 0) {
        perror("gpiod_line_request_input");
        gpiod_line_release(line3);
        gpiod_line_release(line2);
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        gpiod_line_release(line3);
        gpiod_line_release(line2);
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        sensor1_state = read_sensor(GPIO_SENSOR1);
        sensor2_state = read_sensor(GPIO_SENSOR2);
        sensor3_state = read_sensor(GPIO_SENSOR3);

        if (sensor1_state < 0 || sensor2_state < 0 || sensor3_state < 0) {
            fprintf(stderr, "GPIO read failed, skipping log entry\n");
            continue;
        }

        sensor1_field = sensor_to_field(sensor1_state);
        sensor2_field = sensor_to_field(sensor2_state);
        sensor3_field = sensor_to_field(sensor3_state);

        if (sensor1_field < MIN_FIELD || sensor1_field > MAX_FIELD ||
            sensor2_field < MIN_FIELD || sensor2_field > MAX_FIELD ||
            sensor3_field < MIN_FIELD || sensor3_field > MAX_FIELD) {
            fprintf(stderr, "Computed magnetic field out of range, skipping log entry\n");
            continue;
        }

        snprintf(log_entry, sizeof(log_entry), "sensor1_%.2f,sensor2_%.2f,sensor3_%.2f\n",
                 sensor1_field, sensor2_field, sensor3_field);
        if (fwrite(log_entry, 1, strlen(log_entry), log_file) != strlen(log_entry)) {
            perror("fwrite");
        }
        fflush(log_file);
    }

    gpiod_line_release(line3);
    gpiod_line_release(line2);
    gpiod_line_release(line1);
    gpiod_chip_close(chip);
    fclose(log_file);

    return EXIT_SUCCESS;
}

