#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>
#include <gpiod.h>
#include <spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 500000
#define SPI_MODE 0
#define MCP3008_CHANNEL 0
#define PUMP_PIN 17
#define LOG_FILE "watering.log"

static struct gpiod_chip *chip;
static struct gpiod_line *pump_line;
static int spi_fd;

void log_event(const char *event) {
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
    fprintf(stderr, "%s: %s\n", timestamp, event);
    FILE *log = fopen(LOG_FILE, "a");
    if (log) {
        fprintf(log, "%s: %s\n", timestamp, event);
        fclose(log);
    }
}

void handle_signal(int signum) {
    log_event("Program terminated by signal");
    if (pump_line) {
        gpiod_line_set_value(pump_line, 0);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    exit(signum);
}

int read_adc_channel(int channel) {
    uint8_t tx[3] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    if (write(spi_fd, tx, 3) != 3) {
        log_event("Failed to write to SPI");
        return -1;
    }
    if (read(spi_fd, rx, 3) != 3) {
        log_event("Failed to read from SPI");
        return -1;
    }
    return ((rx[1] & 3) << 8) | rx[2];
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    log_event("Program started");

    // Initialize SPI
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        log_event("Failed to open SPI device");
        return EXIT_FAILURE;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        log_event("Failed to set SPI mode");
        close(spi_fd);
        return EXIT_FAILURE;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &8) < 0) {
        log_event("Failed to set SPI bits per word");
        close(spi_fd);
        return EXIT_FAILURE;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        log_event("Failed to set SPI speed");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        log_event("Failed to open GPIO chip");
        close(spi_fd);
        return EXIT_FAILURE;
    }
    pump_line = gpiod_chip_get_line(chip, PUMP_PIN);
    if (!pump_line) {
        log_event("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(pump_line, "pump", 0) < 0) {
        log_event("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    int last_moisture = -1;
    while (1) {
        int moisture = read_adc_channel(MCP3008_CHANNEL);
        if (moisture >= 0) {
            if (last_moisture < 0 || last_moisture >= 30 && moisture < 30) {
                log_event("Pump turned on");
                gpiod_line_set_value(pump_line, 1);
            } else if (last_moisture >= 30 && moisture < 30) {
                log_event("Pump turned off");
                gpiod_line_set_value(pump_line, 0);
            }
            last_moisture = moisture;
        }
        sleep(60);
    }

    // Clean up
    gpiod_line_release(pump_line);
    gpiod_chip_close(chip);
    close(spi_fd);
    return EXIT_SUCCESS;
}

