        return EXIT_FAILURE;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &8) < 0) {
        log_event("Failed to set SPI bits per word");
        close(spi_fd);
        return EXIT_FAILURE;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        log_event("Failed to set SPI speed");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        log_event("Failed to open GPIO chip");
        close(spi_fd);
        return EXIT_FAILURE;
    }
    pump_line = gpiod_chip_get_line(chip, PUMP_PIN);
    if (!pump_line) {
        log_event("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(pump_line, "pump", 0) < 0) {
        log_event("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    int last_moisture = -1;
    while (1) {
        int moisture = read_adc_channel(MCP3008_CHANNEL);
        if (moisture >= 0) {
            if (last_moisture < 0 || last_moisture >= 30 && moisture < 30) {
                log_event("Pump turned on");
                gpiod_line_set_value(pump_line, 1);
            } else if (last_moisture >= 30 && moisture < 30) {
                log_event("Pump turned off");
                gpiod_line_set_value(pump_line, 0);
            }
            last_moisture = moisture;
        }
        sleep(60);
    }

    // Clean up
    gpiod_line_release(pump_line);
    gpiod_chip_close(chip);
    close(spi_fd);
    return EXIT_SUCCESS;
}
