#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000
#define CSV_FILE "sensor_data.csv"
#define NUM_CHANNELS 3
#define DELAY 1000000 // 1 second in microseconds

int fd;
FILE *csv_file;

void close_resources() {
    if (csv_file) {
        fclose(csv_file);
    }
    if (fd >= 0) {
        close(fd);
    }
}

void sigint_handler(int signum) {
    printf("Caught signal %d, exiting gracefully...\n", signum);
    close_resources();
    exit(EXIT_SUCCESS);
}

uint16_t read_mcp3008_channel(int channel) {
    uint8_t tx[3] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI_IOC_MESSAGE");
        exit(EXIT_FAILURE);
    }

    return ((rx[1] & 3) << 8) | rx[2];
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set bits per word");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set max speed HZ");
        close(fd);
        exit(EXIT_FAILURE);
    }

    csv_file = fopen(CSV_FILE, "w");
    if (!csv_file) {
        perror("Failed to open CSV file");
        close(fd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        uint16_t values[NUM_CHANNELS];
        for (int i = 0; i < NUM_CHANNELS; i++) {
            values[i] = read_mcp3008_channel(i);
        }

        fprintf(csv_file, "%d,%d,%d\n", values[0], values[1], values[2]);
        fflush(csv_file);

        usleep(DELAY);
    }

    close_resources();
    return 0;
}

