#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>
#include <mosquitto.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define MQTT_BROKER "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/led_control"
#define MQTT_CLIENT_ID "rpi_led_control"
#define MAX_RECONNECT_DELAY 60

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static struct mosquitto *mosq;
static int reconnect_delay = 1;

static void gpio_init(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", gpiod_strerror(errno));
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", gpiod_strerror(errno));
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(line, "rpi_led_control", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line: %s\n", gpiod_strerror(errno));
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
}

static void gpio_cleanup(void) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

static void mosquitto_init(void) {
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Failed to create MQTT client\n");
        exit(EXIT_FAILURE);
    }

    if (mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60) != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker\n");
        mosquitto_destroy(mosq);
        exit(EXIT_FAILURE);
    }

    if (mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0) != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Failed to subscribe to MQTT topic\n");
        mosquitto_destroy(mosq);
        exit(EXIT_FAILURE);
    }
}

static void mosquitto_cleanup(void) {
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
    }
}

static void on_connect(struct mosquitto *mosq, void *userdata, int rc) {
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Connection failed with error %d\n", rc);
    }
}

static void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *msg) {
    if (msg->topic && !strcmp(msg->topic, MQTT_TOPIC)) {
        if (msg->payloadlen > 0) {
            char *json = (char *)msg->payload;
            // Simple JSON parsing for "led_state": true/false
            if (strstr(json, "\"led_state\": true") != NULL) {
                gpiod_line_set_value(line, 1);
            } else if (strstr(json, "\"led_state\": false") != NULL) {
                gpiod_line_set_value(line, 0);
            } else {
                fprintf(stderr, "Invalid JSON payload\n");
            }
        }
    }
}

static void on_error(struct mosquitto *mosq, void *userdata, int rc) {
    fprintf(stderr, "Error: %s\n", mosquitto_strerror(rc));
}

static void on_log(struct mosquitto *mosq, void *userdata, int level, const char *str) {
    if (level == MOSQ_LOG_ERR) {
        fprintf(stderr, "Error: %s\n", str);
    }
}

static void signal_handler(int signum) {
    gpio_cleanup();
    mosquitto_cleanup();
    exit(EXIT_SUCCESS);
}

int main(void) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gpio_init();
    mosquitto_init();

    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_message_callback_set(mosq, on_message);
    mosquitto_error_callback_set(mosq, on_error);
    mosquitto_log_callback_set(mosq, on_log);

    while (1) {
        if (mosquitto_loop(mosq, -1, 1) != MOSQ_ERR_SUCCESS) {
            fprintf(stderr, "MQTT loop error\n");
            sleep(reconnect_delay);
            reconnect_delay = reconnect_delay * 2;
            if (reconnect_delay > MAX_RECONNECT_DELAY) {
                reconnect_delay = MAX_RECONNECT_DELAY;
            }
        } else {
            reconnect_delay = 1;
        }
    }

    gpio_cleanup();
    mosquitto_cleanup();
    return 0;
}

