This code provides a complete, compilable C program for a Raspberry Pi 4 Model B that subscribes to an MQTT topic, parses JSON payloads, controls an LED, and handles errors and signal-driven shutdowns. It uses the libgpiod library for GPIO control and the mosquitto library for MQTT communication. The program includes robust error handling, exponential reconnection backoff, and signal handlers for clean shutdown.

code:
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_DO 17
#define GPIO_LED 18
#define DELAY_MS 100
#define ALARM_DURATION_MS 1000

static struct gpiod_chip *chip;
static struct gpiod_line *do_line;
static struct gpiod_line *led_line;

void cleanup(int signum) {
    if (do_line) {
        gpiod_line_release(do_line);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(signum);
}

int main() {
    int ret;

    // Register signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request GPIO lines
    do_line = gpiod_chip_get_line(chip, GPIO_DO);
    if (!do_line) {
        perror("Failed to get DO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(do_line, "sound_sensor");
    if (ret < 0) {
        perror("Failed to request DO line as input");
        gpiod_line_release(do_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, GPIO_LED);
    if (!led_line) {
        perror("Failed to get LED line");
        gpiod_line_release(do_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(led_line, "alarm_led", 0);
    if (ret < 0) {
        perror("Failed to request LED line as output");
        gpiod_line_release(do_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        int value;

        // Read sound sensor value
        ret = gpiod_line_get_value(do_line, &value);
        if (ret < 0) {
            perror("Failed to read sound sensor value");
            cleanup(EXIT_FAILURE);
        }

        // Print sound level
        printf("Sound level: %d\n", value);

        // Check for sound event
        if (value == 0) {
            // Trigger alarm LED
            ret = gpiod_line_set_value(led_line, 1);
            if (ret < 0) {
                perror("Failed to turn on alarm LED");
                cleanup(EXIT_FAILURE);
            }

            usleep(ALARM_DURATION_MS * 1000);

            ret = gpiod_line_set_value(led_line, 0);
            if (ret < 0) {
                perror("Failed to turn off alarm LED");
                cleanup(EXIT_FAILURE);
            }
        }

        // Delay for 100 ms
        usleep(DELAY_MS * 1000);
    }

    return EXIT_SUCCESS;
}

