#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 17
#define CONSUMER_LABEL "vibration-monitor"
#define LOG_FILE "/var/log/vibration_shutdown.log"

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_request_config req_config;
    struct gpiod_line_event event;
    FILE *log_file;
    char timestamp[20];
    time_t now;

    // Open the GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request the GPIO line
    memset(&req_config, 0, sizeof(req_config));
    req_config.consumer = CONSUMER_LABEL;
    req_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request(line, &req_config)) {
        perror("Failed to request GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!stop_flag) {
        // Wait for a falling edge event
        if (gpiod_line_event_wait(line, NULL)) {
            perror("Failed to wait for event");
            continue;
        }

        // Read the event
        if (gpiod_line_event_read(line, &event)) {
            perror("Failed to read event");
            continue;
        }

        // Get the current time
        time(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        // Log the event
        fprintf(log_file, "%s: Vibration detected\n", timestamp);
        fflush(log_file);
        printf("Vibration detected at %s\n", timestamp);

        // Shutdown the system
        if (system("sudo shutdown -h now")) {
            perror("Failed to shutdown system");
        }
    }

    // Clean up
    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

