#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x76
#define BMP280_CHIP_ID 0x58
#define BMP280_REG_CHIP_ID 0xD0
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_TEMP_LSB 0xFB
#define BMP280_REG_TEMP_XLSB 0xFC
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_PRESS_LSB 0xF8
#define BMP280_REG_PRESS_XLSB 0xF9

#define LOG_FILE "altitude_log.txt"

struct bmp280_data {
    int16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
};

static struct bmp280_data bmp280;
static struct gpiod_chip *chip;
static FILE *log_file;

static void read_bmp280_coefficients(void) {
    uint8_t buf[24];
    if (gpiod_line_bulk_read(chip, (struct gpiod_line_bulk *)buf, 24) < 0) {
        perror("Failed to read BMP280 coefficients");
        exit(EXIT_FAILURE);
    }
    bmp280.dig_T1 = (buf[1] << 8) | buf[0];
    bmp280.dig_T2 = (buf[3] << 8) | buf[2];
    bmp280.dig_T3 = (buf[5] << 8) | buf[4];
    bmp280.dig_P1 = (buf[7] << 8) | buf[6];
    bmp280.dig_P2 = (buf[9] << 8) | buf[8];
    bmp280.dig_P3 = (buf[11] << 8) | buf[10];
    bmp280.dig_P4 = (buf[13] << 8) | buf[12];
    bmp280.dig_P5 = (buf[15] << 8) | buf[14];
    bmp280.dig_P6 = (buf[17] << 8) | buf[16];
    bmp280.dig_P7 = (buf[19] << 8) | buf[18];
    bmp280.dig_P8 = (buf[21] << 8) | buf[20];
    bmp280.dig_P9 = (buf[23] << 8) | buf[22];
}

static int read_bmp280_temperature(void) {
    uint8_t buf[3];
    if (gpiod_line_bulk_read(chip, (struct gpiod_line_bulk *)buf, 3) < 0) {
        perror("Failed to read BMP280 temperature");
        return -1;
    }
    int32_t adc_T = ((int32_t)buf[0] << 16) | ((int32_t)buf[1] << 8) | buf[2];
    return adc_T;
}

static int read_bmp280_pressure(void) {
    uint8_t buf[3];
    if (gpiod_line_bulk_read(chip, (struct gpiod_line_bulk *)buf, 3) < 0) {
        perror("Failed to read BMP280 pressure");
        return -1;
    }
    int32_t adc_P = ((int32_t)buf[0] << 16) | ((int32_t)buf[1] << 8) | buf[2];
    return adc_P;
}

static float compensate_temperature(int32_t adc_T) {
    int32_t var1, var2, t_fine;
    var1 = ((((adc_T >> 3) - ((int32_t)bmp280.dig_T1 << 1))) * ((int32_t)bmp280.dig_T2)) >> 11;
    var2 = (((((adc_T >> 4) - ((int32_t)bmp280.dig_T1)) * ((adc_T >> 4) - ((int32_t)bmp280.dig_T1))) >> 12) * ((int32_t)bmp280.dig_T3)) >> 14;
    t_fine = var1 + var2;
    return (t_fine * 5 + 128) >> 8;
}

static float compensate_pressure(int32_t adc_P, int32_t t_fine) {
    int64_t var1, var2, var3, p;
    var1 = ((int64_t)t_fine) - 128000;
    var2 = var1 * var1 * (int64_t)bmp280.dig_P6;
    var2 += 2 * (int64_t)bmp280.dig_P5 * var1;
    var2 += (int64_t)bmp280.dig_P4 * 65536;
    var3 = var1 * var1 * var1 * (int64_t)bmp280.dig_P3 / 2097152;
    var3 += 3 * (int64_t)bmp280.dig_P2 * var1 * 65536;
    var3 += (int64_t)bmp280.dig_P1 * 67108864;
    if (var3 == 0) {
        return 0;
    }
    p = 1048576 - adc_P;
    p = (((p << 31) - var2) * 3125) / var3;
    var1 = (int64_t)bmp280.dig_P9 * (p >> 13) * (p >> 13);
    var2 = var1 * 2;
    p = (p + (var1 + var2) >> 1) >> 8;
    p = p + (int64_t)bmp280.dig_P8 * (p >> 19);
    return (float)p / 100;
}

static float calculate_altitude(float pressure) {
    return 44330.0 * (1.0 - pow(pressure / 1013.25, 0.1903));
}

static void log_altitude(float altitude) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
    fprintf(log_file, "%s,%.2f\n", timestamp, altitude);
    fflush(log_file);
}

static void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        if (log_file) {
            fclose(log_file);
        }
        if (chip) {
            gpiod_chip_close(chip);
        }
        exit(EXIT_SUCCESS);
    }
}

int main(void) {
    struct gpiod_line_bulk lines;
    struct gpiod_line *line;
    int ret;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    ret = gpiod_chip_get_lines(chip, "i2c-1", 2, &lines);
    if (ret < 0) {
        perror("Failed to get I2C lines");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line = gpiod_line_bulk_get(&lines, 0);
    if (!line) {
        perror("Failed to get SDA line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line, "i2c-1-sda", 0);
    if (ret < 0) {
        perror("Failed to request SDA line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line = gpiod_line_bulk_get(&lines, 1);
    if (!line) {
        perror("Failed to get SCL line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line, "i2c-1-scl", 0);
    if (ret < 0) {
        perror("Failed to request SCL line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    uint8_t chip_id;
    ret = gpiod_line_bulk_read(chip, (struct gpiod_line_bulk *)&chip_id, 1);
    if (ret < 0) {
        perror("Failed to read BMP280 chip ID");
        fclose(log_file);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "BMP280 chip ID mismatch\n");
        fclose(log_file);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    read_bmp280_coefficients();

    while (1) {
        int32_t adc_T = read_bmp280_temperature();
        if (adc_T < 0) {
            continue;
        }

        int32_t adc_P = read_bmp280_pressure();
        if (adc_P < 0) {
            continue;
        }

        float temperature = compensate_temperature(adc_T);
        float pressure = compensate_pressure(adc_P, t_fine);
        float altitude = calculate_altitude(pressure);

        log_altitude(altitude);

        sleep(5);
    }

    fclose(log_file);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

