#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>
#include <libgpiod/spi.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define BUFFER_SIZE 120
#define SAMPLE_INTERVAL 5

struct circular_buffer {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
};

struct spi_device *spi;
struct circular_buffer cb;

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        if (spi) {
            gpiod_spi_close(spi);
        }
        exit(signum);
    }
}

uint16_t read_adc(uint8_t channel) {
    uint8_t tx[3] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    int ret = gpiod_spi_xfer(spi, tx, rx, 3);
    if (ret < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(-ret));
        return 0;
    }
    return ((rx[1] & 3) << 8) | rx[2];
}

float adc_to_temperature(uint16_t adc_value) {
    return (adc_value * 0.0625); // LM35 resolution is 0.0625°C per bit
}

void log_temperature(float temperature) {
    FILE *file = fopen("temp_log.dat", "wb+");
    if (!file) {
        fprintf(stderr, "Failed to open file for logging: %s\n", strerror(errno));
        return;
    }
    if (fwrite(cb.buffer, sizeof(float), BUFFER_SIZE, file) != BUFFER_SIZE) {
        fprintf(stderr, "Failed to write to file: %s\n", strerror(errno));
    }
    fclose(file);
}

void add_to_buffer(float temperature) {
    cb.buffer[cb.head] = temperature;
    cb.head = (cb.head + 1) % BUFFER_SIZE;
    if (cb.count < BUFFER_SIZE) {
        cb.count++;
    }
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *ce0;
    int ret;

    // Initialize GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Request CE0 line
    ce0 = gpiod_chip_get_line(chip, 8);
    if (!ce0) {
        fprintf(stderr, "Failed to get CE0 line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set CE0 line as output and set to low
    ret = gpiod_line_request_output(ce0, "CE0", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request CE0 line as output: %s\n", strerror(-ret));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initialize SPI device
    spi = gpiod_spi_open(chip, 0);
    if (!spi) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        gpiod_line_release(ce0);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize circular buffer
    memset(&cb, 0, sizeof(cb));

    while (1) {
        // Set CE0 high
        ret = gpiod_line_set_value(ce0, 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to set CE0 high: %s\n", strerror(-ret));
            continue;
        }

        // Read ADC value
        uint16_t adc_value = read_adc(0);

        // Convert ADC value to temperature
        float temperature = adc_to_temperature(adc_value);

        // Add temperature to buffer
        add_to_buffer(temperature);

        // Log temperature to file
        log_temperature(temperature);

        // Set CE0 low
        ret = gpiod_line_set_value(ce0, 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to set CE0 low: %s\n", strerror(-ret));
            continue;
        }

        // Print temperature to console
        printf("Temperature: %.2f°C\n", temperature);

        // Wait for next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Clean up
    gpiod_spi_close(spi);
    gpiod_line_release(ce0);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

