#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define BH1750_I2C_ADDRESS 0x23
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define MCP3008_SPI_DEVICE "/dev/spidev0.0"
#define MCP3008_SPI_MODE 0
#define MCP3008_SPI_BITS_PER_WORD 8
#define MCP3008_SPI_SPEED 500000
#define LOG_FILE "environmental_log.txt"

int i2c_fd;
int spi_fd;

void init_i2c() {
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void init_spi() {
    if ((spi_fd = open(MCP3008_SPI_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &MCP3008_SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &MCP3008_SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &MCP3008_SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }
}

uint16_t read_bh1750() {
    uint8_t data[2];
    if (write(i2c_fd, BH1750_CONTINUOUS_HIGH_RES_MODE, 1) != 1) {
        perror("Failed to write to BH1750");
        return 0;
    }
    usleep(100000); // Wait for measurement to complete
    if (read(i2c_fd, data, 2) != 2) {
        perror("Failed to read from BH1750");
        return 0;
    }
    return (data[0] << 8) | data[1];
}

uint16_t read_mcp3008(uint8_t channel) {
    uint8_t tx[3] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = MCP3008_SPI_SPEED,
        .bits_per_word = MCP3008_SPI_BITS_PER_WORD,
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Failed to read from MCP3008");
        return 0;
    }
    return ((rx[1] & 3) << 8) | rx[2];
}

void log_reading(uint16_t light, uint16_t sound) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }
    fprintf(log_file, "%s, Light: %d, Sound: %d\n", timestamp, light, sound);
    fclose(log_file);
}

void cleanup() {
    close(i2c_fd);
    close(spi_fd);
}

void signal_handler(int signum) {
    cleanup();
    exit(signum);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    init_i2c();
    init_spi();

    while (1) {
        uint16_t light = read_bh1750();
        uint16_t sound = read_mcp3008(0);
        if (light != 0 && sound != 0) {
            log_reading(light, sound);
        }
        sleep(1);
    }

    cleanup();
    return 0;
}

