#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define CSV_FILE "flame_events.log"

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static FILE *csv_file;

void cleanup(int signum) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (csv_file) {
        fclose(csv_file);
    }
    exit(signum ? signum : 0);
}

int main() {
    struct timespec ts;
    int state;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Request the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        cleanup(EXIT_FAILURE);
    }

    // Configure the line as input with a pull-down resistor
    if (gpiod_line_request_input_flags(line, "flame_sensor", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN)) {
        fprintf(stderr, "Failed to request GPIO line as input: %s\n", strerror(errno));
        cleanup(EXIT_FAILURE);
    }

    // Open the CSV file for logging
    csv_file = fopen(CSV_FILE, "a");
    if (!csv_file) {
        fprintf(stderr, "Failed to open CSV file: %s\n", strerror(errno));
        cleanup(EXIT_FAILURE);
    }

    // Register signal handlers for cleanup
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Poll the GPIO line every second
    while (1) {
        if (gpiod_line_get_value(line, &state)) {
            fprintf(stderr, "Failed to read GPIO line: %s\n", strerror(errno));
            cleanup(EXIT_FAILURE);
        }

        // Get the current time
        if (clock_gettime(CLOCK_REALTIME, &ts)) {
            fprintf(stderr, "Failed to get current time: %s\n", strerror(errno));
            cleanup(EXIT_FAILURE);
        }

        // Log the reading to the CSV file
        fprintf(csv_file, "%ld,%ld,%d\n", ts.tv_sec, ts.tv_nsec, state);
        fflush(csv_file);

        // Print an alarm message if the sensor reports a HIGH
        if (state) {
            printf("Flame detected!\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // This line should never be reached
    cleanup(EXIT_SUCCESS);
    return EXIT_SUCCESS;
}

