    if (i2c_fd < 0) {
        close(spi_fd);
        return EXIT_FAILURE;
    }

    log_fd = open("temperature_log.txt", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        close(spi_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        retries = 0;
        while (retries < MAX_RETRIES) {
            adc_value = read_adc(spi_fd, MCP3008_CHANNEL);
            if (adc_value >= 0) {
                temperature = (adc_value * 3.3 / 1024.0) * 100.0;
                dac_voltage = (adc_value * 3.3 / 1024.0);
