            }
            retries++;
            sleep(1);
        }
        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read ADC after %d retries\n", MAX_RETRIES);
        }
        sleep(SAMPLE_INTERVAL / 1000000);
    }

    close(log_fd);
    close(i2c_fd);
    close(spi_fd);

    return EXIT_SUCCESS;
}

