#include <libgpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define SPI_CHANNEL 0
#define NUM_SENSORS 3
#define LOG_FILE "soil_data.txt"

struct gpiod_chip *chip;
struct gpiod_line *cs_line;
int fd;
FILE *log_file;

void close_resources() {
    if (log_file) fclose(log_file);
    if (cs_line) gpiod_line_release(cs_line);
    if (chip) gpiod_chip_close(chip);
    if (fd) close(fd);
}

void handle_sigint(int sig) {
    close_resources();
    printf("Goodbye!\n");
    exit(0);
}

int read_adc_value(int channel) {
    uint8_t tx[3] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    int ret;

    ret = ioctl(fd, SPI_IOC_MESSAGE(1), &tx);
    if (ret < 0) {
        perror("SPI_IOC_MESSAGE");
        return -1;
    }

    ret = read(fd, rx, 3);
    if (ret < 0) {
        perror("read");
        return -1;
    }

    return ((rx[1] & 3) << 8) | rx[2];
}

int main() {
    struct timespec ts;
    char timestamp[20];
    int adc_values[NUM_SENSORS];
    int i, ret;

    // Initialize SPI
    fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    ret = ioctl(fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        perror("SPI_IOC_WR_MODE");
        close(fd);
        return 1;
    }

    ret = ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, (void *)&SPI_BITS_PER_WORD);
    if (ret < 0) {
        perror("SPI_IOC_WR_BITS_PER_WORD");
        close(fd);
        return 1;
    }

    ret = ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        close(fd);
        return 1;
    }

    // Initialize GPIO for chip select
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        close(fd);
        return 1;
    }

    cs_line = gpiod_chip_get_line(chip, 8); // Assuming CS is connected to GPIO 8
    if (!cs_line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        close(fd);
        return 1;
    }

    ret = gpiod_line_request_output(cs_line, "soil_moisture_cs", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        close(fd);
        return 1;
    }

    // Initialize log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        close(fd);
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, handle_sigint);

    while (1) {
        // Read ADC values
        for (i = 0; i < NUM_SENSORS; i++) {
            adc_values[i] = read_adc_value(i);
            if (adc_values[i] < 0) {
                fprintf(stderr, "Invalid ADC value for sensor %d\n", i);
                continue;
            }
        }

        // Get current timestamp
        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts->tv_sec));

        // Write to log file
        for (i = 0; i < NUM_SENSORS; i++) {
            fprintf(log_file, "%s Sensor %d: %d\n", timestamp, i, adc_values[i]);
        }

        // Flush log file
        fflush(log_file);

        // Sleep for 60 seconds
        sleep(60);
    }

    close_resources();
    return 0;
}

