#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define RELAY_COUNT 4
#define RELAY_PINS[17, 22, 23, 24]

struct gpiod_chip *chip;
struct gpiod_line *lines[RELAY_COUNT];

void signal_handler(int signum) {
    for (int i = 0; i < RELAY_COUNT; i++) {
        gpiod_line_set_value(lines[i], 0);
    }
    for (int i = 0; i < RELAY_COUNT; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);
    exit(signum);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request GPIO lines
    for (int i = 0; i < RELAY_COUNT; i++) {
        lines[i] = gpiod_chip_get_line(chip, RELAY_PINS[i]);
        if (!lines[i]) {
            perror("Failed to get GPIO line");
            goto cleanup;
        }
        if (gpiod_line_request_output(lines[i], "relay_seq", 0)) {
            perror("Failed to request GPIO line as output");
            goto cleanup;
        }
    }

    // Main loop
    while (1) {
        for (int i = 0; i < RELAY_COUNT; i++) {
            if (gpiod_line_set_value(lines[i], 1)) {
                perror("Failed to set GPIO line high");
                goto cleanup;
            }
            sleep(1);
            if (gpiod_line_set_value(lines[i], 0)) {
                perror("Failed to set GPIO line low");
                goto cleanup;
            }
            sleep(1);
        }
    }

cleanup:
    for (int i = 0; i < RELAY_COUNT; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    gpiod_chip_close(chip);
    return EXIT_FAILURE;
}

