#define SPI_SPEED 1000000
#define SPI_CHANNEL 0
#define LED_PIN 16
#define THRESHOLD 500
#define DEBOUNCE_DELAY 500000

static struct gpiod_chip *chip;
static struct gpiod_line *led_line;
static int spi_fd;

void log_event(const char *message) {
    FILE *log_file = fopen("sound_events.log", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d %s\n",
            tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
            tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec, message);
    fclose(log_file);
}

void handle_sigint(int sig) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    exit(0);
}

int read_adc_value(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel\n");
        return -1;
    }

    uint8_t tx[3] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];

    if (write(spi_fd, tx, 3) != 3) {
        perror("Failed to write to SPI");
        return -1;
    }

    if (read(spi_fd, rx, 3) != 3) {
        perror("Failed to read from SPI");
        return -1;
    }

    return ((rx[1] & 3) << 8) | rx[2];
}

int main() {
    signal(SIGINT, handle_sigint);

    // Initialize SPI
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
