#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define RAIN_SENSOR_PIN 0
#define MOTOR_IN1_PIN 17
#define MOTOR_IN2_PIN 18
#define MOTOR_ENA_PIN 27
#define RAIN_THRESHOLD 5
#define PWM_RANGE 255
#define PWM_DUTY 150
#define LOG_FILE "rain_log.txt"

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *motor_in1, *motor_in2, *motor_ena;
    int spi_fd;
    FILE *log_file;
    time_t now;
    struct tm *tm_info;
    uint16_t adc_value;
    int rain_level;
    int motor_direction = 1; // 1 for forward, -1 for reverse

    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize libgpiod
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Initialize motor control pins
    motor_in1 = gpiod_chip_get_line(chip, MOTOR_IN1_PIN);
    if (!motor_in1) {
        perror("Failed to get motor IN1 line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(motor_in1, "motor_in1", 0) < 0) {
        perror("Failed to request motor IN1 line");
        gpiod_line_release(motor_in1);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    motor_in2 = gpiod_chip_get_line(chip, MOTOR_IN2_PIN);
    if (!motor_in2) {
        perror("Failed to get motor IN2 line");
        gpiod_line_release(motor_in1);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(motor_in2, "motor_in2", 0) < 0) {
        perror("Failed to request motor IN2 line");
        gpiod_line_release(motor_in1);
        gpiod_line_release(motor_in2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    motor_ena = gpiod_chip_get_line(chip, MOTOR_ENA_PIN);
    if (!motor_ena) {
        perror("Failed to get motor ENA line");
        gpiod_line_release(motor_in1);
        gpiod_line_release(motor_in2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(motor_ena, "motor_ena", 0) < 0) {
        perror("Failed to request motor ENA line");
        gpiod_line_release(motor_in1);
        gpiod_line_release(motor_in2);
        gpiod_line_release(motor_ena);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initialize SPI
    spi_fd = spi_open(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        gpiod_line_release(motor_in1);
        gpiod_line_release(motor_in2);
        gpiod_line_release(motor_ena);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        spi_close(spi_fd);
        gpiod_line_release(motor_in1);
        gpiod_line_release(motor_in2);
        gpiod_line_release(motor_ena);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (!stop_flag) {
        // Read analog value from rain sensor
        uint8_t tx[] = {1, (8 + RAIN_SENSOR_PIN) << 4, 0};
        uint8_t rx[3];
        if (spi_xfer(spi_fd, tx, rx, sizeof(tx)) < 0) {
            perror("Failed to transfer SPI data");
            continue;
        }
        adc_value = ((rx[1] & 3) << 8) | rx[2];
        rain_level = adc_value * 3.3 / 1024;

        // Log rain level with timestamp
        now = time(NULL);
        tm_info = localtime(&now);
        fprintf(log_file, "%s, Rain level: %d\n", asctime(tm_info), rain_level);
        fflush(log_file);

        // Control motor based on rain level
        if (rain_level > RAIN_THRESHOLD) {
            motor_direction = 1;
        } else {
            motor_direction = -1;
        }

        gpiod_line_set_value(motor_in1, motor_direction > 0);
        gpiod_line_set_value(motor_in2, motor_direction < 0);
        gpioSetPWMRange(MOTOR_ENA_PIN, PWM_RANGE);
        gpioSetPWMFrequency(MOTOR_ENA_PIN, 100);
        gpioSetPWM duty_cycle = motor_direction * PWM_DUTY;
        gpioWrite(MOTOR_ENA_PIN, duty_cycle);

        // Run motor for 3 seconds
        sleep(3);

        // Stop motor
        gpioWrite(MOTOR_ENA_PIN, 0);
    }

    // Clean up
    gpioWrite(MOTOR_ENA_PIN, 0);
    gpiod_line_set_value(motor_in1, 0);
    gpiod_line_set_value(motor_in2, 0);
    spi_close(spi_fd);
    fclose(log_file);
    gpiod_line_release(motor_in1);
    gpiod_line_release(motor_in2);
    gpiod_line_release(motor_ena);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

