#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define ADC_PIN 26
#define LED_PIN 16
#define DEBOUNCE_TIME 50
#define CLAP_THRESHOLD 1000
#define CLAP_DURATION 500

static struct gpiod_chip *chip;
static struct gpiod_line *adc_line, *led_line;
static int clap_detected = 0;
static int clap_count = 0;
static time_t last_clap_time = 0;

void signal_handler(int sig) {
    if (sig == SIGINT) {
        if (led_line) {
            gpiod_line_set_value(led_line, 0);
        }
        if (chip) {
            gpiod_chip_close(chip);
        }
        exit(0);
    }
}

int read_adc() {
    int adc_value = 0;
    for (int i = 0; i < 10; i++) {
        gpiod_line_set_value(adc_line, 1);
        usleep(1);
        gpiod_line_set_value(adc_line, 0);
        usleep(10);
        adc_value += gpiod_line_get_value(adc_line);
    }
    return adc_value / 10;
}

int main() {
    struct timespec ts;
    time_t current_time;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Initialize ADC line
    adc_line = gpiod_chip_get_line(chip, ADC_PIN);
    if (!adc_line) {
        perror("Failed to get ADC line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_input(adc_line, "adc_input")) {
        perror("Failed to request ADC line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initialize LED line
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get LED line");
        gpiod_line_release(adc_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(led_line, "led_output", 0)) {
        perror("Failed to request LED line");
        gpiod_line_release(adc_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        int adc_value = read_adc();
        if (adc_value > CLAP_THRESHOLD) {
            clock_gettime(CLOCK_REALTIME, &ts);
            current_time = ts.tv_sec;
            if (current_time - last_clap_time > DEBOUNCE_TIME / 1000.0) {
                clap_count++;
                if (clap_count >= 2) {
                    clap_detected = 1;
                    last_clap_time = current_time;
                    clap_count = 0;
                }
            }
        } else {
            clap_count = 0;
        }

        if (clap_detected) {
            gpiod_line_set_value(led_line, 1);
            printf("Clap detected at %ld.%03ld\n", ts.tv_sec, ts.tv_nsec / 1000000);
            usleep(CLAP_DURATION * 1000);
            gpiod_line_set_value(led_line, 0);
            clap_detected = 0;
        }

        usleep(10000);
    }

    gpiod_line_release(adc_line);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

