#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define LOG_FILE "distance_log.txt"
#define RETRY_DELAY 1

volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    // Register signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    while (running) {
        // Open GPIO chip
        chip = gpiod_chip_open_by_name(GPIO_CHIP);
        if (!chip) {
            perror("Failed to open GPIO chip");
            sleep(RETRY_DELAY);
            continue;
        }

        // Request GPIO line
        line = gpiod_chip_get_line(chip, GPIO_LINE);
        if (!line) {
            perror("Failed to get GPIO line");
            gpiod_chip_close(chip);
            sleep(RETRY_DELAY);
            continue;
        }

        // Configure GPIO line as input
        ret = gpiod_line_request_input(line, "distance_sensor");
        if (ret < 0) {
            perror("Failed to request GPIO line as input");
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            sleep(RETRY_DELAY);
            continue;
        }

        // Read GPIO line
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("Failed to read GPIO line");
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            sleep(RETRY_DELAY);
            continue;
        }

        // Log distance to file
        FILE *log_file = fopen(LOG_FILE, "a");
        if (!log_file) {
            perror("Failed to open log file");
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            sleep(RETRY_DELAY);
            continue;
        }

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, %d\n",
                tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
                tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec, value);
        fclose(log_file);

        // Print status to console
        if (value == 0) {
            printf("Feeder Activated\n");
        } else {
            printf("Feeder Idle\n");
        }

        // Release GPIO line and close chip
        gpiod_line_release(line);
        gpiod_chip_close(chip);

        // Sleep for a short period before the next read
        sleep(RETRY_DELAY);
    }

    return 0;
}

