#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <time.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 8
#define MCP3008_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SAMPLE_INTERVAL 500000
#define LOG_FILE "magnetic_log.txt"

static int spi_fd = -1;
static int gpio_fd = -1;
static FILE *log_file = NULL;

static void close_resources() {
    if (log_file) {
        fclose(log_file);
    }
    if (gpio_fd != -1) {
        close(gpio_fd);
    }
    if (spi_fd != -1) {
        close(spi_fd);
    }
}

static void handle_signal(int signum) {
    close_resources();
    exit(signum);
}

static uint16_t read_mcp3008_channel(int fd, uint8_t channel) {
    uint8_t tx[3] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI_IOC_MESSAGE");
        return 0;
    }

    return ((rx[1] & 3) << 8) | rx[2];
}

static float convert_to_magnetic_field(uint16_t adc_value) {
    // Assuming VDD = 3.3V and VREF = 3.3V, and 10-bit resolution
    float voltage = (adc_value * 3.3) / 1023.0;
    // Assuming a linear relationship between voltage and magnetic field strength
    // This is a placeholder value, adjust based on your sensor's datasheet
    float magnetic_field = voltage * 1000.0; // Example conversion
    return magnetic_field;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open SPI device");
        return EXIT_FAILURE;
    }

    gpio_fd = open(GPIO_CHIP, O_RDWR);
    if (gpio_fd < 0) {
        perror("open GPIO chip");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(gpio_fd, GPIO_GET_LINEINFO_IOCTL, GPIO_LINE) < 0) {
        perror("ioctl GPIO_GET_LINEINFO_IOCTL");
        close(spi_fd);
        close(gpio_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(gpio_fd, GPIO_GET_LINEHANDLE_IOCTL, GPIO_LINE) < 0) {
        perror("ioctl GPIO_GET_LINEHANDLE_IOCTL");
        close(spi_fd);
        close(gpio_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen log file");
        close(spi_fd);
        close(gpio_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        uint16_t adc_value = read_mcp3008_channel(spi_fd, MCP3008_CHANNEL);
        if (adc_value == 0) {
            fprintf(stderr, "ADC read failed\n");
            continue;
        }

        float magnetic_field = convert_to_magnetic_field(adc_value);
        time_t now = time(NULL);
        fprintf(log_file, "%ld,%.2f\n", now, magnetic_field);
        fflush(log_file);

        usleep(SAMPLE_INTERVAL);
    }

    close_resources();
    return EXIT_SUCCESS;
}

