This code provides a complete solution for reading the DRV5055-A1 Hall-effect sensor through an external MCP3008 ADC over the SPI bus on a Raspberry Pi Zero W. It includes error handling, resource management, and signal handling to ensure proper cleanup on exit. The magnetic field strength is calculated using integer arithmetic and logged to a CSV file with the current Unix epoch timestamp.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define SPI_CHIP 0
#define SPI_CHANNEL 0
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 500000
#define ADC_CHANNEL 0
#define LED_PIN 21
#define THRESHOLD 10000  // 10.0 mT converted to ADC units

static struct gpiod_chip *chip;
static struct gpiod_line *led_line;
static int spi_fd;

void cleanup(int signum) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    exit(signum);
}

int read_adc(int channel) {
    uint8_t tx[3] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];
    ssize_t bytes_read;

    bytes_read = write(spi_fd, tx, sizeof(tx));
    if (bytes_read != sizeof(tx)) {
        perror("Failed to write to SPI");
        return -1;
    }

    bytes_read = read(spi_fd, rx, sizeof(rx));
    if (bytes_read != sizeof(rx)) {
        perror("Failed to read from SPI");
        return -1;
    }

    return ((rx[1] & 3) << 8) | rx[2];
}

int main() {
    struct timespec ts;
    FILE *log_file;
    int adc_value, magnetic_field;

    // Initialize SPI
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set bits per word");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set max speed");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Initialize GPIO for LED
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, "magnetic_led", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Initialize log file
    log_file = fopen("magnetic_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Set up signal handler
    signal(SIGINT, cleanup);

    while (1) {
        adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            continue;
        }

        magnetic_field = adc_value * 10000 / 1023;  // Convert to mT

        if (magnetic_field > THRESHOLD) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld.%09ld, %d\n", ts.tv_sec, ts.tv_nsec, magnetic_field);
        fflush(log_file);

        usleep(100000);  // 100 ms
    }

    // Cleanup
    fclose(log_file);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    close(spi_fd);

    return EXIT_SUCCESS;
}

