#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define SPI_CHIP 0
#define SPI_CHANNEL 0
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define SPI_CS 0
#define ADC_CHANNEL 0
#define LOG_FILE "moisture_log.txt"
#define READ_INTERVAL 60

struct gpiod_chip *chip;
struct gpiod_line *cs_line;
int spi_fd;

void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(stderr, "%04d-%02d-%02d %02d:%02d:%02d ERROR: %s\n",
            tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
            tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec, message);
}

void log_reading(int value) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(stdout, "%04d-%02d-%02d %02d:%02d:%02d %d\n",
            tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
            tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec, value);
}

void handle_sigint(int sig) {
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (cs_line) {
        gpiod_line_release(cs_line);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    exit(0);
}

int main() {
    signal(SIGINT, handle_sigint);

    // Initialize GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        log_error("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request chip select line
    cs_line = gpiod_chip_get_line(chip, SPI_CS);
    if (!cs_line) {
        log_error("Failed to get chip select line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request and set chip select line to high
    if (gpiod_line_request_output(cs_line, "moisture_sensor_cs", 1) < 0) {
        log_error("Failed to request chip select line");
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open SPI device
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        log_error("Failed to open SPI device");
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set SPI parameters
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        log_error("Failed to set SPI mode");
        close(spi_fd);
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &8) < 0) {
        log_error("Failed to set SPI bits per word");
        close(spi_fd);
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        log_error("Failed to set SPI speed");
        close(spi_fd);
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        log_error("Failed to open log file");
        close(spi_fd);
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        // Set chip select line to low
        if (gpiod_line_set_value(cs_line, 0) < 0) {
            log_error("Failed to set chip select line to low");
            continue;
        }

        // Send command to MCP3008 to read channel 0
        uint8_t tx[3] = {1, (8 + ADC_CHANNEL) << 4, 0};
        uint8_t rx[3];
        if (write(spi_fd, tx, 3) != 3 || read(spi_fd, rx, 3) != 3) {
            log_error("Failed to read from SPI device");
            // Set chip select line to high
            if (gpiod_line_set_value(cs_line, 1) < 0) {
                log_error("Failed to set chip select line to high");
            }
            continue;
        }

        // Calculate raw ADC value
        int adc_value = ((rx[1] & 3) << 8) | rx[2];

        // Set chip select line to high
        if (gpiod_line_set_value(cs_line, 1) < 0) {
            log_error("Failed to set chip select line to high");
            continue;
        }

        // Log the reading
        log_reading(adc_value);
        fprintf(log_file, "%d\n", adc_value);
        fflush(log_file);

        // Wait for the next read
        sleep(READ_INTERVAL);
