        perror("Failed to set SPI mode");
        close(fd_spi);
        return EXIT_FAILURE;
    }

    // Set SPI bits per word
    if (ioctl(fd_spi, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set SPI bits per word");
        close(fd_spi);
        return EXIT_FAILURE;
    }

    // Set SPI speed
    if (ioctl(fd_spi, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(fd_spi);
        return EXIT_FAILURE;
    }

    // Open GPIO device
    fd_gpio = open("/sys/class/gpio/export", O_WRONLY);
    if (fd_gpio < 0) {
        perror("Failed to open GPIO export");
        close(fd_spi);
        return EXIT_FAILURE;
    }

    if (write(fd_gpio, "17", 2) != 2) {
        perror("Failed to export GPIO 17");
        close(fd_gpio);
        close(fd_spi);
        return EXIT_FAILURE;
    }

    close(fd_gpio);

    // Set GPIO direction to output
    fd_gpio = open("/sys/class/gpio/gpio17/direction", O_WRONLY);
    if (fd_gpio < 0) {
        perror("Failed to open GPIO direction");
        close(fd_spi);
        return EXIT_FAILURE;
    }

    if (write(fd_gpio, "out", 3) != 3) {
        perror("Failed to set GPIO 17 direction to out");
        close(fd_gpio);
        close(fd_spi);
        return EXIT_FAILURE;
    }

    close(fd_gpio);

    // Set GPIO value to high to enable sensor power
    fd_gpio = open("/sys/class/gpio/gpio17/value", O_WRONLY);
    if (fd_gpio < 0) {
        perror("Failed to open GPIO value");
        close(fd_spi);
        return EXIT_FAILURE;
    }

    if (write(fd_gpio, "1", 1) != 1) {
        perror("Failed to set GPIO 17 value to 1");
        close(fd_gpio);
        close(fd_spi);
        return EXIT_FAILURE;
    }

    close(fd_gpio);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(fd_spi);
        return EXIT_FAILURE;
    }

    while (1) {
        int adc_value = read_adc(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue;
        }

        double current_A = adc_to_current(adc_value);
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        fprintf(log_file, "%s,%.2f\n", timestamp, current_A);
        fflush(log_file);

        sleep(1);
    }

    close_resources();
    return EXIT_SUCCESS;
}

