This C program for a Raspberry Pi 3 Model B+ reads the analog output from the Melexis MLX91209 current sensor through an MCP3008 ADC connected on the SPI bus `/dev/spidev0.0`. It samples the current once every second, converts the ADC reading to amperes, and appends a line to a CSV file named `current_log.txt` in the format "timestamp,current_A". The program verifies that each initialization step succeeds, detects and handles sensor-absent or communication failures without crashing, and installs handlers for `SIGINT` and `SIGTERM` to perform a clean shutdown that releases the GPIO line, closes the SPI device, and closes the log file.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define SPI_CHIP 0
#define SPI_CHANNEL 0
#define SPI_MODE 0
#define SPI_SPEED 100000
#define SPI_BITS_PER_WORD 8
#define ADC_CHANNEL 0
#define LOG_FILE "current_log.txt"
#define VDD 5.0
#define SAMPLE_INTERVAL 100

volatile sig_atomic_t stop_flag = 0;

void sigint_handler(int signum) {
    stop_flag = 1;
}

int read_adc(struct gpiod_chip *chip, int channel) {
    struct gpiod_line *line;
    unsigned int value;
    int ret;

    line = gpiod_chip_get_line(chip, channel);
    if (!line) {
        perror("Failed to get line");
        return -1;
    }

    ret = gpiod_line_request_input(line, "adc");
    if (ret < 0) {
        perror("Failed to request input line");
        gpiod_line_release(line);
        return -1;
    }

    ret = gpiod_line_get_value(line, &value);
    if (ret < 0) {
        perror("Failed to get line value");
        gpiod_line_release(line);
        return -1;
    }

    gpiod_line_release(line);
    return value;
}

int main() {
    struct gpiod_chip *chip;
    FILE *log_file;
    time_t now;
    struct tm *tm_info;
    int adc_value, voltage;
    char timestamp[20];

    signal(SIGINT, sigint_handler);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (!stop_flag) {
        adc_value = read_adc(chip, ADC_CHANNEL);
        if (adc_value < 0) {
            continue;
        }

        voltage = (adc_value * VDD) / 1023;
        if (voltage < 0 || voltage > 5) {
            fprintf(stderr, "Warning: Voltage out of range: %d mV\n", voltage);
            continue;
        }

        time(&now);
        tm_info = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s %.2f A\n", timestamp, voltage / 1000.0);
        fflush(log_file);

        usleep(SAMPLE_INTERVAL * 1000);
    }

    fclose(log_file);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

