#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define SENSOR1_LINE "gpiochip0:0"
#define SENSOR2_LINE "gpiochip0:17"
#define DEBOUNCE_DELAY 2000
#define SAMPLE_COUNT 5
#define LOG_INTERVAL 1000000

static struct gpiod_chip *chip;
static struct gpiod_line *line1, *line2;
static int running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int read_sensor(struct gpiod_line *line) {
    int value = 0;
    for (int i = 0; i < SAMPLE_COUNT; i++) {
        int sample = gpiod_line_get_value(line);
        if (sample < 0) {
            perror("Failed to read sensor value");
            return -1;
        }
        value += sample;
        usleep(DEBOUNCE_DELAY);
    }
    return value >= SAMPLE_COUNT / 2;
}

void log_state(int sensor1, int sensor2) {
    if (sensor1 && sensor2) {
        printf("ALERT: Both sensors detect object\n");
    } else {
        printf("%d\n", sensor1 ? 0 : 1);
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to set SIGINT handler");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, 4);
