#include <driver_library.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define READ_DELAY 60
#define MIN_ADC 300
#define MAX_ADC 800
#define LOG_FILE "soil_moisture_log.csv"

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signal) {
    stop_flag = 1;
}

int read_mcp3008(int channel) {
    spi_config_t config = {
        .channel = SPI_CHANNEL,
        .baud = SPI_BAUD,
        .mode = SPI_MODE_0,
        .bits_per_word = 8
    };
    spi_handle_t spi_handle = spi_setup(config);
    if (!spi_handle) {
        perror("Failed to setup SPI");
        return -1;
    }

    uint8_t tx_data[3] = {1, (8 + channel) << 4, 0};
    uint8_t rx_data[3];
    if (spi_transfer(spi_handle, tx_data, rx_data, 3) != 3) {
        perror("Failed to transfer data");
        spi_close(spi_handle);
        return -1;
    }

    spi_close(spi_handle);
    return ((rx_data[1] & 3) << 8) | rx_data[2];
}

double calculate_moisture_level(int adc_value) {
    if (adc_value < MIN_ADC) adc_value = MIN_ADC;
    if (adc_value > MAX_ADC) adc_value = MAX_ADC;
    return 100.0 * (adc_value - MIN_ADC) / (MAX_ADC - MIN_ADC);
}

void log_data(double moisture_level) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, moisture_level);
    fprintf(stdout, "%s,%.2f\n", timestamp, moisture_level);

    fclose(log_file);
}

int main() {
    signal(SIGINT, signal_handler);

    while (!stop_flag) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value == -1) {
            sleep(READ_DELAY);
            continue;
        }

        double moisture_level = calculate_moisture_level(adc_value);
        log_data(moisture_level);

        sleep(READ_DELAY);
    }

    return 0;
}

