#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <time.h>
#include <libgpiod.h>
#include <syslog.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define DEBOUNCE_TIME 200
#define POLL_INTERVAL 50
#define PHOTO_DIR "/home/pi/security_cam/"
#define PHOTO_PREFIX "motion_"
#define PHOTO_EXT ".jpg"

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int line_value = 0;
    int last_line_value = 0;
    struct timespec start_time, current_time;
    char photo_path[256];
    pid_t pid;
    int status;

    // Initialize syslog
    openlog("security_cam", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize GPIO
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        closelog();
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        syslog(LOG_ERR, "Failed to get GPIO line");
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line, "security_cam") < 0) {
        syslog(LOG_ERR, "Failed to request GPIO line as input");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Ensure photo directory exists
    if (mkdir(PHOTO_DIR, 0755) != 0 && errno != EEXIST) {
        syslog(LOG_ERR, "Failed to create photo directory");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    while (!stop_flag) {
        // Read GPIO line
        line_value = gpiod_line_get_value(line);
        if (line_value < 0) {
            syslog(LOG_ERR, "Failed to read GPIO line");
            continue;
        }

        // Check for state change
        if (line_value != last_line_value) {
            last_line_value = line_value;

            // Apply debounce delay
            clock_gettime(CLOCK_MONOTONIC, &start_time);
            while (1) {
                clock_gettime(CLOCK_MONOTONIC, &current_time);
                if ((current_time.tv_sec - start_time.tv_sec) * 1000 + (current_time.tv_nsec - start_time.tv_nsec) / 1000000 >= DEBOUNCE_TIME) {
                    break;
                }
            }

            // Re-read GPIO line to confirm motion
            line_value = gpiod_line_get_value(line);
            if (line_value < 0) {
                syslog(LOG_ERR, "Failed to re-read GPIO line");
                continue;
            }

            if (line_value == 1) {
                // Motion detected
                syslog(LOG_INFO, "Motion detected");

                // Construct photo path
                time_t now = time(NULL);
                struct tm *tm_info = localtime(&now);
                snprintf(photo_path, sizeof(photo_path), "%s%s%04d%02d%02d%02d%02d%02d.jpg",
                         PHOTO_DIR, PHOTO_PREFIX, tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
                         tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec);

                // Launch libcamera-still
                pid = fork();
                if (pid == 0) {
                    char *args[] = {"libcamera-still", "-o", photo_path, NULL};
                    execvp("libcamera-still", args);
                    syslog(LOG_ERR, "Failed to execute libcamera-still");
                    exit(EXIT_FAILURE);
                } else if (pid < 0) {
                    syslog(LOG_ERR, "Failed to fork");
                    continue;
                }

                // Wait for child process
                if (waitpid(pid, &status, 0) < 0) {
                    syslog(LOG_ERR, "Failed to wait for child process");
                    continue;
                }

                if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
                    syslog(LOG_INFO, "Photo captured successfully: %s", photo_path);
                } else {
                    syslog(LOG_ERR, "Photo capture failed with status: %d", WEXITSTATUS(status));
                }
            }
        }

        // Poll every 50ms
        usleep(POLL_INTERVAL * 1000);
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    closelog();

    syslog(LOG_INFO, "Shutdown complete");
    return EXIT_SUCCESS;
}

