#include <sys/mman.h>
#include <signal.h>
#include <linux/videodev2.h>

#define DEVICE "/dev/video0"
#define WIDTH 192
#define HEIGHT 144
#define NUM_BUFFERS 4
#define FILENAME "image.jpg"

int fd = -1;
struct v4l2_buffer buf[NUM_BUFFERS];
struct v4l2_requestbuffers req;
struct v4l2_format fmt;
struct v4l2_capability cap;
FILE *file = NULL;

void cleanup() {
    if (file) {
        fclose(file);
    }
    if (fd != -1) {
        for (int i = 0; i < NUM_BUFFERS; i++) {
            if (buf[i].m.offset) {
                munmap((void *)buf[i].m.offset, buf[i].length);
            }
        }
        ioctl(fd, VIDIOC_STREAMOFF, V4L2_BUF_TYPE_VIDEO_CAPTURE);
        ioctl(fd, VIDIOC_QBUF, &req);
        close(fd);
    }
}

void signal_handler(int signum) {
    cleanup();
    exit(signum);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    fd = open(DEVICE, O_RDWR);
    if (fd == -1) {
        perror("Failed to open device");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("Failed to query device capabilities");
        cleanup();
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE) || !(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support video capture or streaming\n");
        cleanup();
        return EXIT_FAILURE;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("Failed to set pixel format");
        cleanup();
        return EXIT_FAILURE;
    }

    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("Failed to request buffers");
        cleanup();
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_BUFFERS; i++) {
        memset(&buf[i], 0, sizeof(buf[i]));
        buf[i].type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf[i].memory = V4L2_MEMORY_MMAP;
        buf[i].index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf[i]) == -1) {
            perror("Failed to query buffer");
            cleanup();
            return EXIT_FAILURE;
        }

        void *addr = mmap(NULL, buf[i].length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf[i].m.offset);
        if (addr == MAP_FAILED) {
            perror("Failed to mmap buffer");
            cleanup();
            return EXIT_FAILURE;
        }
        buf[i].m.offset = (unsigned long)addr;
    }

    if (ioctl(fd, VIDIOC_STREAMON, &req.type) == -1) {
        perror("Failed to start streaming");
        cleanup();
        return EXIT_FAILURE;
    }

    memset(&buf[0], 0, sizeof(buf[0]));
    buf[0].type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf[0].memory = V4L2_MEMORY_MMAP;
    buf[0].index = 0;

    if (ioctl(fd, VIDIOC_DQBUF, &buf[0]) == -1) {
        perror("Failed to dequeue buffer");
        cleanup();
        return EXIT_FAILURE;
    }

    if (buf[0].bytesused <= 0) {
        fprintf(stderr, "Dequeued buffer has no data\n");
        cleanup();
        return EXIT_FAILURE;
    }

    file = fopen(FILENAME, "wb");
    if (!file) {
        perror("Failed to open file");
        cleanup();
        return EXIT_FAILURE;
    }

    if (fwrite((void *)buf[0].m.offset, 1, buf[0].bytesused, file) != buf[0].bytesused) {
        perror("Failed to write to file");
        fclose(file);
        cleanup();
        return EXIT_FAILURE;
    }

    fclose(file);
    cleanup();
    return EXIT_SUCCESS;
}

