#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/time.h>
#include <signal.h>
#include <linux/videodev2.h>
#include <jpeglib.h>

#define WIDTH 640
#define HEIGHT 480
#define BUFFER_COUNT 4
#define JPEG_QUALITY 75

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    int fd = open("/dev/video0", O_RDWR);
    if (fd < 0) {
        perror("Failed to open /dev/video0");
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Failed to query capabilities");
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Failed to set format");
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = BUFFER_COUNT;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Failed to request buffers");
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_buffer buf[BUFFER_COUNT];
    for (int i = 0; i < BUFFER_COUNT; i++) {
        memset(&buf[i], 0, sizeof(buf[i]));
        buf[i].type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf[i].memory = V4L2_MEMORY_MMAP;
        buf[i].index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf[i]) < 0) {
            perror("Failed to query buffer");
            close(fd);
            return EXIT_FAILURE;
        }

        void *addr = mmap(NULL, buf[i].length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf[i].m.offset);
        if (addr == MAP_FAILED) {
            perror("Failed to mmap buffer");
            close(fd);
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < BUFFER_COUNT; i++) {
        if (ioctl(fd, VIDIOC_QBUF, &buf[i]) < 0) {
            perror("Failed to queue buffer");
            close(fd);
            return EXIT_FAILURE;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Failed to start streaming");
        close(fd);
        return EXIT_FAILURE;
    }

    struct timeval timeout;
    timeout.tv_sec = 2;
    timeout.tv_usec = 0;

    fd_set fds;
    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    if (select(fd + 1, &fds, NULL, NULL, &timeout) < 0) {
        perror("Failed to select");
        close(fd);
        return EXIT_FAILURE;
    }

    if (FD_ISSET(fd, &fds)) {
        if (ioctl(fd, VIDIOC_DQBUF, &buf[0]) < 0) {
            perror("Failed to dequeue buffer");
            close(fd);
            return EXIT_FAILURE;
        }

        // Convert YUYV to RGB24
        unsigned char *rgb = malloc(WIDTH * HEIGHT * 3);
        if (!rgb) {
            perror("Failed to allocate RGB buffer");
            close(fd);
            return EXIT_FAILURE;
        }

        // Dummy conversion (replace with actual conversion)
        for (int i = 0; i < WIDTH * HEIGHT; i++) {
            rgb[i * 3] = buf[0].m.planes[0][i * 2];
            rgb[i * 3 + 1] = buf[0].m.planes[0][i * 2 + 1];
            rgb[i * 3 + 2] = buf[0].m.planes[0][i * 2 + 1];
        }

        // Apply blur filter (replace with actual filter)
        for (int i = 0; i < WIDTH * HEIGHT; i++) {
            rgb[i * 3] = (rgb[i * 3] + rgb[(i - 1) * 3] + rgb[(i + 1) * 3]) / 3;
            rgb[i * 3 + 1] = (rgb[i * 3 + 1] + rgb[(i - 1) * 3 + 1] + rgb[(i + 1) * 3 + 1]) / 3;
            rgb[i * 3 + 2] = (rgb[i * 3 + 2] + rgb[(i - 1) * 3 + 2] + rgb[(i + 1) * 3 + 2]) / 3;
        }

        // Encode as JPEG
        struct jpeg_compress_struct cinfo;
        struct jpeg_error_mgr jerr;
        cinfo.err = jpeg_std_error(&jerr);
        jpeg_create_compress(&cinfo);
        jpeg_stdio_dest(&cinfo, stdout);

        cinfo.image_width = WIDTH;
        cinfo.image_height = HEIGHT;
        cinfo.input_components = 3;
        cinfo.in_color_space = JCS_RGB;

        jpeg_set_defaults(&cinfo);
        jpeg_set_quality(&cinfo, JPEG_QUALITY, TRUE);

        jpeg_start_compress(&cinfo, TRUE);
        JSAMPROW row_pointer[1];
        while (cinfo.next_scanline < cinfo.image_height) {
            row_pointer[0] = &rgb[cinfo.next_scanline * WIDTH * 3];
            jpeg_write_scanlines(&cinfo, row_pointer, 1);
        }
        jpeg_finish_compress(&cinfo);
        jpeg_destroy_compress(&cinfo);

        free(rgb);
    }

    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Failed to stop streaming");
        close(fd);
        return EXIT_FAILURE;
    }

    for (int i = 0; i < BUFFER_COUNT; i++) {
        if (ioctl(fd, VIDIOC_QBUF, &buf[i]) < 0) {
            perror("Failed to queue buffer");
            close(fd);
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < BUFFER_COUNT; i++) {
        munmap(buf[i].m.planes[0], buf[i].length);
    }

    close(fd);
    return EXIT_SUCCESS;
}

