        close(fd);
        return EXIT_FAILURE;
    }

    if (FD_ISSET(fd, &fds)) {
        if (ioctl(fd, VIDIOC_DQBUF, &buf[0]) < 0) {
            perror("Failed to dequeue buffer");
            close(fd);
            return EXIT_FAILURE;
        }

        // Convert YUYV to RGB24
        unsigned char *rgb = malloc(WIDTH * HEIGHT * 3);
        if (!rgb) {
            perror("Failed to allocate RGB buffer");
            close(fd);
            return EXIT_FAILURE;
        }

