            rgb[i * 3] = buf[0].m.planes[0][i * 2];
            rgb[i * 3 + 1] = buf[0].m.planes[0][i * 2 + 1];
            rgb[i * 3 + 2] = buf[0].m.planes[0][i * 2 + 1];
        }

        // Apply blur filter (replace with actual filter)
