    }

    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Failed to stop streaming");
        close(fd);
        return EXIT_FAILURE;
    }

    for (int i = 0; i < BUFFER_COUNT; i++) {
        if (ioctl(fd, VIDIOC_QBUF, &buf[i]) < 0) {
            perror("Failed to queue buffer");
            close(fd);
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < BUFFER_COUNT; i++) {
        munmap(buf[i].m.planes[0], buf[i].length);
    }

    close(fd);
    return EXIT_SUCCESS;
