#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

void print_error(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

void print_capabilities(struct v4l2_capability *cap) {
    printf("Driver: %s\n", cap->driver);
    printf("Card: %s\n", cap->card);
    printf("Bus info: %s\n", cap->bus_info);
    printf("Version: %u.%u.%u.%u\n", (cap->version >> 16) & 0xFF, (cap->version >> 8) & 0xFF, (cap->version >> 0) & 0xFF, (cap->version >> 24) & 0xFF);
    printf("Capabilities: %08x\n", cap->capabilities);
}

void print_frame_sizes(struct v4l2_frmsizeenum *fsize) {
    printf("Frame sizes:\n");
    while (fsize->type == V4L2_FRMSIZE_TYPE_DISCRETE) {
        printf("  %ux%u\n", fsize->discrete.width, fsize->discrete.height);
        if (ioctl(fsize->fd, VIDIOC_ENUM_FRAMESIZES, fsize) < 0) {
            print_error("VIDIOC_ENUM_FRAMESIZES");
        }
    }
}

void print_frame_intervals(struct v4l2_frmivalenum *fival) {
    printf("  Frame intervals for %ux%u:\n", fival->width, fival->height);
    while (fival->type == V4L2_FRMIVAL_TYPE_DISCRETE) {
        printf("    %u/%u\n", fival->discrete.numerator, fival->discrete.denominator);
        if (ioctl(fival->fd, VIDIOC_ENUM_FRAMEINTERVALS, fival) < 0) {
            print_error("VIDIOC_ENUM_FRAMEINTERVALS");
        }
    }
}

void print_focus_control(struct v4l2_queryctrl *ctrl) {
    printf("Focus control:\n");
    printf("  ID: %u\n", ctrl->id);
    printf("  Name: %s\n", ctrl->name);
    printf("  Type: %u\n", ctrl->type);
    printf("  Minimum: %d\n", ctrl->minimum);
    printf("  Maximum: %d\n", ctrl->maximum);
    printf("  Step: %d\n", ctrl->step);
    printf("  Default: %d\n", ctrl->default_value);
    printf("  Flags: %08x\n", ctrl->flags);
}

int main() {
    int fd = open("/dev/video0", O_RDWR);
    if (fd < 0) {
        print_error("Failed to open /dev/video0");
    }

    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        print_error("VIDIOC_QUERYCAP");
    }
    print_capabilities(&cap);

    struct v4l2_frmsizeenum fsize = { .fd = fd, .index = 0, .type = V4L2_FRMSIZE_TYPE_DISCRETE };
    while (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &fsize) >= 0) {
        print_frame_sizes(&fsize);
        fsize.index++;
    }

    struct v4l2_queryctrl ctrl = { .id = V4L2_CID_FOCUS_AUTO };
    if (ioctl(fd, VIDIOC_QUERYCTRL, &ctrl) >= 0) {
        print_focus_control(&ctrl);
    } else {
        printf("Focus control not supported\n");
    }

    close(fd);
    return 0;
}

