#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <libgpiod.h>

#define SERVO_PAN_PIN 4
#define SERVO_TILT_PIN 5
#define BUTTON_UP_PIN 6
#define BUTTON_DOWN_PIN 7
#define BUTTON_LEFT_PIN 8
#define BUTTON_RIGHT_PIN 9
#define PWM_FREQ 50
#define PWM_MIN 1000
#define PWM_MAX 2000
#define PWM_CENTER 1500
#define PWM_INCREMENT 10
#define DELAY_MS 50

static struct gpiod_chip *chip;
static struct gpiod_line *pan_servo, *tilt_servo;
static struct gpiod_line *button_up, *button_down, *button_left, *button_right;

void cleanup(int signum) {
    if (pan_servo) {
        gpiod_line_set_value(pan_servo, 0);
        gpiod_line_release(pan_servo);
    }
    if (tilt_servo) {
        gpiod_line_set_value(tilt_servo, 0);
        gpiod_line_release(tilt_servo);
    }
    if (button_up) {
        gpiod_line_release(button_up);
    }
    if (button_down) {
        gpiod_line_release(button_down);
    }
    if (button_left) {
        gpiod_line_release(button_left);
    }
    if (button_right) {
        gpiod_line_release(button_right);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(signum);
}

int main() {
    struct gpiod_line_request_config pan_config = {
        .consumer = "pan_servo",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT,
        .default_val = 0,
    };
    struct gpiod_line_request_config tilt_config = {
        .consumer = "tilt_servo",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT,
        .default_val = 0,
    };
    struct gpiod_line_request_config button_config = {
        .consumer = "button",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
        .default_val = 1,
    };

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    pan_servo = gpiod_chip_get_line(chip, SERVO_PAN_PIN);
    if (!pan_servo) {
        perror("Failed to get pan servo line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    tilt_servo = gpiod_chip_get_line(chip, SERVO_TILT_PIN);
    if (!tilt_servo) {
        perror("Failed to get tilt servo line");
        gpiod_line_release(pan_servo);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    button_up = gpiod_chip_get_line(chip, BUTTON_UP_PIN);
    if (!button_up) {
        perror("Failed to get button up line");
        gpiod_line_release(pan_servo);
        gpiod_line_release(tilt_servo);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    button_down = gpiod_chip_get_line(chip, BUTTON_DOWN_PIN);
    if (!button_down) {
        perror("Failed to get button down line");
        gpiod_line_release(pan_servo);
        gpiod_line_release(tilt_servo);
        gpiod_line_release(button_up);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    button_left = gpiod_chip_get_line(chip, BUTTON_LEFT_PIN);
    if (!button_left) {
        perror("Failed to get button left line");
        gpiod_line_release(pan_servo);
        gpiod_line_release(tilt_servo);
        gpiod_line_release(button_up);
        gpiod_line_release(button_down);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    button_right = gpiod_chip_get_line(chip, BUTTON_RIGHT_PIN);
    if (!button_right) {
        perror("Failed to get button right line");
        gpiod_line_release(pan_servo);
        gpiod_line_release(tilt_servo);
        gpiod_line_release(button_up);
        gpiod_line_release(button_down);
        gpiod_line_release(button_left);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(pan_servo, &pan_config) < 0) {
        perror("Failed to request pan servo line");
        cleanup(EXIT_FAILURE);
    }

    if (gpiod_line_request(tilt_servo, &tilt_config) < 0) {
        perror("Failed to request tilt servo line");
        cleanup(EXIT_FAILURE);
    }

    if (gpiod_line_request(button_up, &button_config) < 0) {
        perror("Failed to request button up line");
        cleanup(EXIT_FAILURE);
    }

    if (gpiod_line_request(button_down, &button_config) < 0) {
        perror("Failed to request button down line");
        cleanup(EXIT_FAILURE);
    }

    if (gpiod_line_request(button_left, &button_config) < 0) {
        perror("Failed to request button left line");
        cleanup(EXIT_FAILURE);
    }

    if (gpiod_line_request(button_right, &button_config) < 0) {
        perror("Failed to request button right line");
        cleanup(EXIT_FAILURE);
    }

    printf("Startup message: Pin assignments - Pan: %d, Tilt: %d, Up: %d, Down: %d, Left: %d, Right: %d\n", SERVO_PAN_PIN, SERVO_TILT_PIN, BUTTON_UP_PIN, BUTTON_DOWN_PIN, BUTTON_LEFT_PIN, BUTTON_RIGHT_PIN);
    printf("Center position: %d\n", PWM_CENTER);

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    int pan_width = PWM_CENTER;
    int tilt_width = PWM_CENTER;

    while (1) {
        if (gpiod_line_get_value(button_up) == 0) {
            pan_width += PWM_INCREMENT;
            if (pan_width > PWM_MAX) {
                pan_width = PWM_MAX;
            }
            gpiod_line_set_value(pan_servo, 1);
            gpiod_line_set_pulse_width(pan_servo, pan_width);
            gpiod_line_set_value(pan_servo, 0);
            usleep(DELAY_MS * 1000);
        }

        if (gpiod_line_get_value(button_down) == 0) {
            pan_width -= PWM_INCREMENT;
            if (pan_width < PWM_MIN) {
                pan_width = PWM_MIN;
            }
            gpiod_line_set_value(pan_servo, 1);
            gpiod_line_set_pulse_width(pan_servo, pan_width);
            gpiod_line_set_value(pan_servo, 0);
            usleep(DELAY_MS * 1000);
        }

        if (gpiod_line_get_value(button_left) == 0) {
            tilt_width -= PWM_INCREMENT;
            if (tilt_width < PWM_MIN) {
                tilt_width = PWM_MIN;
            }
            gpiod_line_set_value(tilt_servo, 1);
            gpiod_line_set_pulse_width(tilt_servo, tilt_width);
            gpiod_line_set_value(tilt_servo, 0);
            usleep(DELAY_MS * 1000);
        }

        if (gpiod_line_get_value(button_right) == 0) {
            tilt_width += PWM_INCREMENT;
            if (tilt_width > PWM_MAX) {
                tilt_width = PWM_MAX;
            }
            gpiod_line_set_value(tilt_servo, 1);
            gpiod_line_set_pulse_width(tilt_servo, tilt_width);
            gpiod_line_set_value(tilt_servo, 0);
            usleep(DELAY_MS * 1000);
        }
    }

    cleanup(EXIT_SUCCESS);
    return EXIT_SUCCESS;
}

