#include <libcurl/curl.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define DEBOUNCE_TIME 2000000 // 2 seconds in microseconds
#define POLL_INTERVAL 100000  // 100 ms in microseconds
#define CAMERA_QUALITY 85
#define MOTION_CAPTURE_DIR "motion_captures"
#define HTTP_ENDPOINT "http://<IP>:<port>/upload"

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static CURL *curl;
static CURLcode res;

void cleanup() {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (curl) {
        curl_easy_cleanup(curl);
    }
    if (res != CURLE_OK) {
        fprintf(stderr, "libcurl error: %s\n", curl_easy_strerror(res));
    }
    exit(EXIT_FAILURE);
}

void signal_handler(int sig) {
    cleanup();
}

int capture_image(const char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "raspistill -o %s -q %d", filename, CAMERA_QUALITY);
    return system(command) == 0;
}

void post_data(const char *filename, const char *timestamp, int motion_status, int gpio_pin) {
    CURL *curl;
    CURLcode res;
    struct curl_httppost *formpost = NULL;
    struct curl_httppost *lastptr = NULL;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if(curl) {
        curl_formadd(&formpost, &lastptr,
                     CURLFORM_COPYNAME, "file",
                     CURLFORM_FILE, filename,
                     CURLFORM_END);
        curl_formadd(&formpost, &lastptr,
                     CURLFORM_COPYNAME, "timestamp",
                     CURLFORM_COPYCONTENTS, timestamp,
                     CURLFORM_END);
        curl_formadd(&formpost, &lastptr,
                     CURLFORM_COPYNAME, "motion_status",
                     CURLFORM_COPYCONTENTS, motion_status ? "true" : "false",
                     CURLFORM_END);
        curl_formadd(&formpost, &lastptr,
                     CURLFORM_COPYNAME, "gpio_pin",
                     CURLFORM_COPYCONTENTS, gpio_pin,
                     CURLFORM_END);
        curl_easy_setopt(curl, CURLOPT_URL, HTTP_ENDPOINT);
        curl_easy_setopt(curl, CURLOPT_HTTPPOST, formpost);
        res = curl_easy_perform(curl);
        if(res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }
        curl_easy_cleanup(curl);
        curl_formfree(formpost);
    }
    curl_global_cleanup();
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <IP> <port>\n", argv[0]);
        return EXIT_FAILURE;
    }

    struct gpiod_line_request_config config = {
        .consumer = "pir_sensor",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
        .default_val = 0,
        .flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN,
    };

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(line, &config) < 0) {
        fprintf(stderr, "Failed to request GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Failed to initialize libcurl\n");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        curl_global_cleanup();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (mkdir(MOTION_CAPTURE_DIR, 0755) != 0 && errno != EEXIST) {
        fprintf(stderr, "Failed to create motion capture directory\n");
        cleanup();
    }

    struct timespec last_motion_time = {0, 0};
    int motion_detected = 0;

    while (1) {
        int value = gpiod_line_get_value(line);
        if (value == 1) {
            if (!motion_detected) {
                motion_detected = 1;
                last_motion_time = (struct timespec){0, 0};
            }
        } else {
            if (motion_detected) {
                struct timespec now;
                clock_gettime(CLOCK_MONOTONIC, &now);
                if (now.tv_sec - last_motion_time.tv_sec > DEBOUNCE_TIME / 1000000) {
                    char filename[256];
                    char timestamp[64];
                    time_t rawtime;
                    struct tm *timeinfo;

                    time(&rawtime);
                    timeinfo = localtime(&rawtime);
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.%06ldZ", &rawtime);

                    snprintf(filename, sizeof(filename), "%s/motion_%s.jpg", MOTION_CAPTURE_DIR, timestamp);
                    if (capture_image(filename)) {
                        post_data(filename, timestamp, 1, GPIO_LINE);
                    } else {
                        fprintf(stderr, "Failed to capture image\n");
                    }
                }
                motion_detected = 0;
            }
        }

        if (!motion_detected) {
            usleep(POLL_INTERVAL);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

