#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define DEBOUNCE_TIME 50
#define IMAGE_DIR "/home/pi/images"
#define LOG_FILE "/home/pi/motion_capture.log"
#define CAPTURE_CMD "raspistill -o %s -w 640 -h 480 -q 85 -t 2000 -n"

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static FILE *log_file;

void log_event(const char *message) {
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

void capture_image(const char *filename) {
    char cmd[256];
    snprintf(cmd, sizeof(cmd), CAPTURE_CMD, filename);
    int status = system(cmd);
    if (status != 0) {
        log_event("Capture command failed with status: %d", status);
    } else {
        log_event("Image captured: %s", filename);
    }
}

void handle_signal(int signum) {
    log_event("Received signal %d, cleaning up...", signum);
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(signum);
}

int main() {
    struct gpiod_line_request_config config = {
        .consumer = "pir_sensor",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
        .default_val = 0,
        .flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP,
    };

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        log_event("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        log_event("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(line, &config) < 0) {
        log_event("Failed to request GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        log_event("Failed to open log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        int value = gpiod_line_get_value(line);
        if (value == 0) {
            struct timespec start, end;
            clock_gettime(CLOCK_MONOTONIC, &start);
            while (gpiod_line_get_value(line) == 0) {
                clock_gettime(CLOCK_MONOTONIC, &end);
                if (timespec_diff(&end, &start) > DEBOUNCE_TIME) {
                    break;
                }
                usleep(1000);
            }
            if (gpiod_line_get_value(line) == 0) {
                continue;
            }
            char filename[256];
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            snprintf(filename, sizeof(filename), "%s/%04d%02d%02d_%02d%02d%02d_%03d.jpg",
                     IMAGE_DIR, tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
                     tm->tm_hour, tm->tm_min, tm->tm_sec, (int)(now % 1000));
            capture_image(filename);
        }
        usleep(1000);
    }

    return EXIT_SUCCESS;
}

int timespec_diff(struct timespec *a, struct timespec *b) {
    return (a->tv_sec - b->tv_sec) * 1000 + (a->tv_nsec - b->tv_nsec) / 1000000;
}

