        if (buf.fmt.pix.width != WIDTH || buf.fmt.pix.height != HEIGHT || buf.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
            fprintf(stderr, "Frame format mismatch\n");
            break;
        }

        // Crop and write frame
        unsigned char *src = buffer;
        unsigned char *dst = malloc(CROP_WIDTH * CROP_HEIGHT * 2);
        if (!dst) {
            perror("Failed to allocate memory for cropped frame");
            break;
        }

        for (int y = 0; y < CROP_HEIGHT; y++) {
            for (int x = 0; x < CROP_WIDTH; x++) {
                int src_index = (y * WIDTH + x) * 2;
                int dst_index = (y * CROP_WIDTH + x) * 2;
                dst[dst_index] = src[src_index];
                dst[dst_index + 1] = src[src_index + 1];
            }
        }

        ret = fwrite(dst, 1, CROP_WIDTH * CROP_HEIGHT * 2, output_file);
        if (ret != CROP_WIDTH * CROP_HEIGHT * 2) {
            perror("Failed to write cropped frame");
            free(dst);
            break;
        }

        free(dst);

        // Queue buffer again
        ret = ioctl(fd, VIDIOC_QBUF, &buf);
        if (ret < 0) {
            perror("Failed to queue buffer");
            break;
        }
    }

    // Stop streaming
    ret = ioctl(fd, VIDIOC_STREAMOFF, &type);
    if (ret < 0) {
        perror("Failed to stop streaming");
    }

    // Unmap buffer
    munmap(buffer, buf.length);

    // Close output file
    fclose(output_file);

    // Close device
    close(fd);

    return EXIT_SUCCESS;
}

