#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define SERVO_FREQ 50
#define SERVO_NEUTRAL 90
#define SERVO_MIN 0
#define SERVO_MAX 180
#define SERVO_RANGE (SERVO_MAX - SERVO_MIN)
#define SERVO_STEPS 5
#define SERVO_DELAY 100

#define GPIO_PAN 17
#define GPIO_TILT 18

static struct gpiod_chip *chip;
static struct gpiod_line *pan_line, *tilt_line;

void cleanup(int sig) {
    if (pan_line) {
        gpiod_line_set_value(pan_line, SERVO_NEUTRAL);
        gpiod_line_release(pan_line);
    }
    if (tilt_line) {
        gpiod_line_set_value(tilt_line, SERVO_NEUTRAL);
        gpiod_line_release(tilt_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(1);
}

int set_servo_angle(struct gpiod_line *line, int angle) {
    if (angle < SERVO_MIN || angle > SERVO_MAX) {
        fprintf(stderr, "Angle out of range: %d\n", angle);
        return -1;
    }
    int duty_cycle = (angle - SERVO_MIN) * (1000000 / SERVO_FREQ / SERVO_RANGE) + 1500000 / SERVO_FREQ;
    if (gpiod_line_set_value(line, duty_cycle) < 0) {
        perror("Failed to set servo angle");
        return -1;
    }
    return 0;
}

int main() {
    signal(SIGINT, cleanup);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    pan_line = gpiod_chip_get_line(chip, GPIO_PAN);
    if (!pan_line) {
        perror("Failed to get pan GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    tilt_line = gpiod_chip_get_line(chip, GPIO_TILT);
    if (!tilt_line) {
        perror("Failed to get tilt GPIO line");
        gpiod_line_release(pan_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(pan_line, "pan_servo", SERVO_NEUTRAL) < 0) {
        perror("Failed to request pan GPIO line");
        gpiod_line_release(tilt_line);
        gpiod_line_release(pan_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(tilt_line, "tilt_servo", SERVO_NEUTRAL) < 0) {
        perror("Failed to request tilt GPIO line");
        gpiod_line_release(pan_line);
        gpiod_chip_close(chip);
        return 1;
    }

    int pan_angle = SERVO_NEUTRAL;
    int tilt_angle = SERVO_NEUTRAL;

    while (1) {
        int ch = getchar();
        if (ch == EOF) {
            break;
        }

        switch (ch) {
            case 'q':
                cleanup(0);
                break;
            case 'w':
                if (tilt_angle > SERVO_MIN) {
                    tilt_angle -= SERVO_STEPS;
                }
                if (set_servo_angle(tilt_line, tilt_angle) < 0) {
                    cleanup(0);
                }
                break;
            case 's':
                if (tilt_angle < SERVO_MAX) {
                    tilt_angle += SERVO_STEPS;
                }
                if (set_servo_angle(tilt_line, tilt_angle) < 0) {
                    cleanup(0);
                }
                break;
            case 'a':
                if (pan_angle > SERVO_MIN) {
                    pan_angle -= SERVO_STEPS;
                }
                if (set_servo_angle(pan_line, pan_angle) < 0) {
                    cleanup(0);
                }
                break;
            case 'd':
                if (pan_angle < SERVO_MAX) {
                    pan_angle += SERVO_STEPS;
                }
                if (set_servo_angle(pan_line, pan_angle) < 0) {
                    cleanup(0);
                }
                break;
            default:
                fprintf(stderr, "Unknown command: %c\n", ch);
                break;
        }

        usleep(SERVO_DELAY * 1000);
    }

    cleanup(0);
    return 0;
}

