#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x3C
#define OLED_WIDTH 128
#define OLED_HEIGHT 64
#define CPU_TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define CPU_STAT_FILE "/proc/stat"

struct gpiod_chip *chip;
struct gpiod_line *line;
int i2c_fd;

void cleanup() {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(EXIT_FAILURE);
}

void signal_handler(int sig) {
    cleanup();
}

void i2c_write(uint8_t *data, size_t len) {
    ssize_t bytes_written = write(i2c_fd, data, len);
    if (bytes_written != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        cleanup();
    }
}

void render_text(const char *text, int x, int y) {
    uint8_t buffer[OLED_WIDTH * OLED_HEIGHT / 8];
    memset(buffer, 0, sizeof(buffer));

    // Simple 5x7 bitmap font
    const uint8_t font[] = {
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    };

    // Render text using the font
    for (int i = 0; i < strlen(text); i++) {
        int char_code = text[i] - '0';
        if (char_code >= 0 && char_code <= 9) {
            for (int j = 0; j < 8; j++) {
                buffer[y + j * OLED_WIDTH + x + i * 8] = font[char_code * 8 + j];
            }
        }
    }

    // Send buffer to OLED
    uint8_t command[] = {0x00, 0x10, 0x00}; // Set page address
    i2c_write(command, sizeof(command));
    for (int i = 0; i < OLED_HEIGHT / 8; i++) {
        uint8_t data[] = {0x40}; // Set data mode
        i2c_write(data, sizeof(data));
        i2c_write(buffer + i * OLED_WIDTH, OLED_WIDTH);
    }
}

int main() {
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C address: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize OLED display
    uint8_t init_commands[] = {
        0xAE, 0xD5, 0x80, 0xA8, 0x3F, 0xD3, 0x00, 0x40, 0x8D, 0x14, 0xA4, 0xA6, 0xAF
    };
    i2c_write(init_commands, sizeof(init_commands));

    while (1) {
        // Read CPU temperature
        FILE *temp_file = fopen(CPU_TEMP_FILE, "r");
        if (!temp_file) {
            render_text("Temp Err", 0, 0);
            sleep(1);
            continue;
        }
        int temp;
        fscanf(temp_file, "%d", &temp);
        fclose(temp_file);
        temp /= 1000;

        // Read CPU usage
        FILE *stat_file = fopen(CPU_STAT_FILE, "r");
        if (!stat_file) {
            render_text("CPU Err", 0, 0);
            sleep(1);
            continue;
        }
        char line[256];
        if (fgets(line, sizeof(line), stat_file) == NULL) {
            fclose(stat_file);
            render_text("CPU Err", 0, 0);
            sleep(1);
            continue;
        }
        fclose(stat_file);

        // Parse CPU usage
        unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
        sscanf(line, "cpu %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice);

        unsigned long long total = user + nice + system + idle + iowait + irq + softirq + steal + guest + guest_nice;
        unsigned long long prev_total = user + nice + system + idle;
        static unsigned long long prev_total_prev = 0;
        static unsigned long long prev_total_total = 0;

        unsigned long long total_diff = total - prev_total_prev;
        unsigned long long idle_diff = idle - prev_total_total;

        unsigned long long cpu_usage = (total_diff - idle_diff) * 100 / total_diff;

        prev_total_prev = prev_total_total;
        prev_total_total = total;

        // Render values on OLED
        char buffer[64];
        snprintf(buffer, sizeof(buffer), "Temp: %d C\nCPU: %lu%%", temp, cpu_usage);
        render_text(buffer, 0, 0);

        sleep(1);
    }

    return EXIT_SUCCESS;
}

