#include <libgpiod.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define I2C_BUS 1
#define I2C_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_HEIGHT 2

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int flow_count = 0;
    unsigned long long start_time = 0;
    unsigned long long current_time = 0;
    double flow_rate = 0.0;
    double total_volume = 0.0;
    int i2c_handle;

    // Initialize GPIO
    if (gpiod_library_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod library\n");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line, "flow_sensor") < 0) {
        fprintf(stderr, "Failed to request GPIO line as input\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initialize I2C
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    start_time = current_time = gpioTick();

    while (running) {
        current_time = gpioTick();
        if (gpiod_line_get_value(line) == 1) {
            flow_count++;
        }

        if (current_time - start_time >= 1000000) {
            flow_rate = (double)flow_count * 60.0 / 7.5; // 7.5 pulses per liter
            total_volume += flow_rate / 60.0;
            printf("Flow Rate: %.2f L/min, Total Volume: %.2f L\n", flow_rate, total_volume);
            start_time = current_time;
            flow_count = 0;
        }

        if (current_time - start_time >= 10000000) {
            char buffer[LCD_WIDTH * LCD_HEIGHT * 2];
            snprintf(buffer, sizeof(buffer), "Flow: %.2f L/min\nTotal: %.2f L", flow_rate, total_volume);
            i2cWriteString(i2c_handle, buffer);
            start_time = current_time;
        }

        usleep(10000);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

