#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <sys/ioctl.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_HEIGHT 2

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static int i2c_fd;
static volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

void init_gpio() {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(line, "flow_sensor")) {
        perror("Failed to request GPIO line as input");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
}

void init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void write_lcd(const char *line1, const char *line2) {
    char buffer[LCD_WIDTH * LCD_HEIGHT + 1];
    snprintf(buffer, sizeof(buffer), "%-16s%-16s", line1, line2);
    write(i2c_fd, buffer, sizeof(buffer));
}

void cleanup() {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

int main() {
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    init_gpio();
    init_i2c();

    write_lcd("Flow Rate:", "0.00 L/min");

    while (running) {
        struct timespec start, end;
        clock_gettime(CLOCK_MONOTONIC, &start);

        int pulses = 0;
        while (gpiod_line_get_value(line) == 1) {
            usleep(1000);
            pulses++;
        }

        clock_gettime(CLOCK_MONOTONIC, &end);
        double elapsed_time = (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1e9;

        if (elapsed_time > 0) {
            double flow_rate = (pulses / 7.5) / elapsed_time * 60; // 7.5 pulses per liter per minute
            char buffer[17];
            snprintf(buffer, sizeof(buffer), "X.XX L/min", flow_rate);
            write_lcd("Flow Rate:", buffer);
        } else {
            write_lcd("Flow Rate:", "0.00 L/min");
        }

        sleep(1);
    }

    cleanup();
    return 0;
}

