#include <libgpiod.h>

#define ROWS 8
#define COLS 8
#define ROW_PINS {2, 3, 4, 17, 27, 22, 10, 9}
#define COL_PINS {14, 15, 18, 23, 24, 25, 8, 7}
#define DELAY_MS 150

struct gpiod_chip *chip;
struct gpiod_line *row_lines[ROWS];
struct gpiod_line *col_lines[COLS];

void signal_handler(int signum) {
    for (int i = 0; i < ROWS; i++) {
        gpiod_line_release(row_lines[i]);
    }
    for (int i = 0; i < COLS; i++) {
        gpiod_line_release(col_lines[i]);
    }
    gpiod_chip_close(chip);
    exit(signum);
}

int main() {
    struct gpiod_line_request_config row_config = {
        .consumer = "LED_Matrix_Row",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT,
        .default_val = 0,
    };
    struct gpiod_line_request_config col_config = {
        .consumer = "LED_Matrix_Col",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT,
        .default_val = 1,
    };

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request row lines
    for (int i = 0; i < ROWS; i++) {
        row_lines[i] = gpiod_chip_get_line(chip, ROW_PINS[i]);
        if (!row_lines[i]) {
            perror("Failed to get row line");
            goto cleanup;
        }
        if (gpiod_line_request(row_lines[i], &row_config)) {
            perror("Failed to request row line");
            goto cleanup;
        }
    }

    // Request column lines
    for (int i = 0; i < COLS; i++) {
        col_lines[i] = gpiod_chip_get_line(chip, COL_PINS[i]);
        if (!col_lines[i]) {
            perror("Failed to get column line");
            goto cleanup;
        }
        if (gpiod_line_request(col_lines[i], &col_config)) {
            perror("Failed to request column line");
            goto cleanup;
        }
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        for (int col = 0; col < COLS; col++) {
            // Clear the matrix
            for (int row = 0; row < ROWS; row++) {
                gpiod_line_set_value(row_lines[row], 0);
            }

            // Light the LEDs in the current column
            for (int row = 0; row < ROWS; row++) {
                gpiod_line_set_value(row_lines[row], 1);
                usleep(DELAY_MS * 1000);
                gpiod_line_set_value(row_lines[row], 0);
            }

            // Set the current column cathode LOW
            gpiod_line_set_value(col_lines[col], 0);
            usleep(DELAY_MS * 1000);
            gpiod_line_set_value(col_lines[col], 1);
        }
    }

cleanup:
    for (int i = 0; i < ROWS; i++) {
        if (row_lines[i]) {
            gpiod_line_release(row_lines[i]);
        }
    }
    for (int i = 0; i < COLS; i++) {
        if (col_lines[i]) {
            gpiod_line_release(col_lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return EXIT_FAILURE;
}

