#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x60
#define SI1145_PROXIMITY_REG 0x24
#define SI1145_ALS_REG 0x25
#define LOG_FILE "biometric_log.txt"

struct gpiod_chip *chip;
struct gpiod_line *line;
FILE *log_file;

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

void log_timestamped_data(int proximity, int ambient_light) {
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

    fprintf(log_file, "%s, Proximity: %d, Ambient Light: %d\n", timestamp, proximity, ambient_light);
    fflush(log_file);
}

void handle_sigint(int sig) {
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    struct gpiod_line_request_config config = {
        .consumer = "i2c-sensor",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
    };

    // Initialize I2C
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        log_error("Failed to open GPIO chip");
        return 1;
    }

    line = gpiod_chip_get_line(chip, 2); // Assuming SDA is on GPIO2
    if (!line) {
        log_error("Failed to get SDA line");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request(line, &config)) {
        log_error("Failed to request SDA line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Initialize log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        log_error("Failed to open log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Install SIGINT handler
    signal(SIGINT, handle_sigint);

    while (1) {
        uint8_t proximity_data[2], ambient_light_data[2];
        int ret;

        // Read proximity data
        ret = gpiod_line_get_value(line);
        if (ret < 0) {
            log_error("Failed to read proximity data");
        } else {
            proximity_data[0] = ret;
            proximity_data[1] = 0;
        }

        // Read ambient light data
        ret = gpiod_line_get_value(line);
        if (ret < 0) {
            log_error("Failed to read ambient light data");
        } else {
            ambient_light_data[0] = ret;
            ambient_light_data[1] = 0;
        }

        // Log data
        log_timestamped_data(proximity_data[0], ambient_light_data[0]);

        // Sleep for 500ms
        usleep(500 * 1000);
    }

    return 0;
}

