#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define GPIO_CHIP_DEFAULT "gpiochip0"
#define GPIO_CHIP_FALLBACK "the library's API call"
#define GPIO_LINE_PROXIMITY 4
#define GPIO_LINE_LED 17
#define POLL_INTERVAL 100  // 100 ms
#define LED_BLINK_DURATION 100  // 100 ms

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *proximity_line = NULL;
static struct gpiod_line *led_line = NULL;
static int log_fd = -1;

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        if (chip) {
            gpiod_chip_close(chip);
        }
        if (proximity_line) {
            gpiod_line_release(proximity_line);
        }
        if (led_line) {
            gpiod_line_release(led_line);
        }
        if (log_fd != -1) {
            close(log_fd);
        }
        exit(EXIT_SUCCESS);
    }
}

int main() {
    struct timespec ts;
    struct tm *tm;
    char timestamp[20];
    int proximity_state = 0;
    int previous_state = 0;

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP_DEFAULT);
    if (!chip) {
        chip = gpiod_chip_open_by_name(GPIO_CHIP_FALLBACK);
        if (!chip) {
            perror("Failed to open GPIO chip");
            return EXIT_FAILURE;
        }
    }

    // Request the proximity sensor line
    proximity_line = gpiod_chip_get_line(chip, GPIO_LINE_PROXIMITY);
    if (!proximity_line) {
        perror("Failed to get proximity sensor line");
        goto cleanup;
    }

    // Request the LED line
    led_line = gpiod_chip_get_line(chip, GPIO_LINE_LED);
    if (!led_line) {
        perror("Failed to get LED line");
        goto cleanup;
    }

    // Configure the proximity sensor line as input
    if (gpiod_line_request_input(proximity_line, "proximity_sensor") < 0) {
        perror("Failed to request proximity sensor line as input");
        goto cleanup;
    }

    // Configure the LED line as output
    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        perror("Failed to request LED line as output");
        goto cleanup;
    }

    // Open the log file
    log_fd = open("proximity.log", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd == -1) {
        perror("Failed to open log file");
        goto cleanup;
    }

    while (1) {
        // Read the proximity sensor state
        proximity_state = gpiod_line_get_value(proximity_line);
        if (proximity_state < 0) {
            perror("Failed to read proximity sensor state");
            goto cleanup;
        }

        // Check for falling edge
        if (proximity_state == 0 && previous_state == 1) {
            // Get current timestamp
            if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
                perror("Failed to get current timestamp");
                goto cleanup;
            }
            tm = gmtime(&ts.tv_sec);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

            // Write timestamped entry to log file
            if (dprintf(log_fd, "%s Object detected\n", timestamp) < 0) {
                perror("Failed to write to log file");
                goto cleanup;
            }

            // Blink the LED
            if (gpiod_line_set_value(led_line, 1) < 0) {
                perror("Failed to turn on LED");
                goto cleanup;
            }
            usleep(LED_BLINK_DURATION * 1000);
            if (gpiod_line_set_value(led_line, 0) < 0) {
                perror("Failed to turn off LED");
                goto cleanup;
            }
        }

        // Update previous state
        previous_state = proximity_state;

        // Sleep for the poll interval
        usleep(POLL_INTERVAL * 1000);
    }

cleanup:
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (proximity_line) {
        gpiod_line_release(proximity_line);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (log_fd != -1) {
        close(log_fd);
    }
    return EXIT_FAILURE;
}

