This C program for a Raspberry Pi 5 continuously polls an E18-D50NK IR proximity sensor connected to GPIO line 4 (BCM, physical pin 7) every 100 ms. It reads the sensor which drives the line LOW when an object is within the calibrated range and HIGH otherwise. The program detects the falling edge from HIGH to LOW, writes a timestamped entry to a file named `proximity.log` using an ISO 8601 UTC format, and blinks an LED attached to GPIO line 17 (BCM, physical pin 11) by turning it on for 100 ms and then off. The program handles errors, checks the return status of every driver call, and releases the GPIO lines and closes the chip on any exit path, including receipt of SIGINT or SIGTERM.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x60
#define PART_ID_REG 0x00
#define PROXIMITY_REG 0x20
#define AMBIENT_LIGHT_REG 0x21
#define PART_ID 0x45

struct gpiod_chip *chip;
struct gpiod_line *i2c_line;
FILE *log_file;

void cleanup(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_line) {
        gpiod_line_release(i2c_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(signum);
}

int read_sensor_data(uint8_t reg, uint8_t *data, size_t len) {
    struct i2c_msg msg[2];
    struct i2c_rdwr_ioctl_data packets;
    uint8_t buf[1];

    buf[0] = reg;

    msg[0].addr = I2C_ADDRESS;
    msg[0].flags = 0;
    msg[0].len = 1;
    msg[0].buf = buf;

    msg[1].addr = I2C_ADDRESS;
    msg[1].flags = I2C_M_RD;
    msg[1].len = len;
    msg[1].buf = data;

    packets.nmsgs = 2;
    packets.msgs = msg;

    if (ioctl(gpiod_line_get_fd(i2c_line), I2C_RDWR, &packets) < 0) {
        perror("I2C_RDWR");
        return -1;
    }

    return 0;
}

int main() {
    struct timespec ts;
    uint8_t part_id, proximity, ambient_light;
    char timestamp[20];

    if (signal(SIGINT, cleanup) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    i2c_line = gpiod_chip_get_line(chip, 2); // Assuming I2C is on GPIO2
    if (!i2c_line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(i2c_line, "i2c", 0) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_file = fopen("biometric_data.log", "a");
    if (!log_file) {
        perror("fopen");
        gpiod_line_release(i2c_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (read_sensor_data(PART_ID_REG, &part_id, 1) < 0) {
        fprintf(stderr, "Failed to read PART_ID\n");
        cleanup(EXIT_FAILURE);
    }

    if (part_id != PART_ID) {
        fprintf(stderr, "Invalid PART_ID: 0x%02X\n", part_id);
        cleanup(EXIT_FAILURE);
    }

    while (1) {
        if (read_sensor_data(PROXIMITY_REG, &proximity, 1) < 0) {
            fprintf(stderr, "Failed to read proximity data\n");
            continue;
        }

        if (read_sensor_data(AMBIENT_LIGHT_REG, &ambient_light, 1) < 0) {
            fprintf(stderr, "Failed to read ambient light data\n");
            continue;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", &ts);

        fprintf(log_file, "%s,%d,%d\n", timestamp, proximity, ambient_light);
        fflush(log_file);
    }

    cleanup(EXIT_SUCCESS);
    return EXIT_SUCCESS;
}

