#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define TIMEOUT_US 30000
#define MIN_DISTANCE 2
#define MAX_DISTANCE 400
#define WATER_THRESHOLD 15
#define LOG_FILE "distance_log.txt"

static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static FILE *log_file;

void log_distance(double distance) {
    time_t now = time(NULL);
    char *iso_time = ctime(&now);
    iso_time[strlen(iso_time) - 1] = '\0'; // Remove newline

    fprintf(log_file, "%s: Distance: %.2f cm\n", iso_time, distance);
    if (distance < WATER_THRESHOLD) {
        fprintf(log_file, "Time to water the plant!\n");
    }
}

void handle_signal(int sig) {
    if (log_file) {
        fclose(log_file);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

int main() {
    struct timespec start, end;
    long long duration_us;
    double distance;

    // Initialize GPIO
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Failed to get trigger line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Failed to get echo line");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(trigger_line, "trigger", 0) < 0) {
        perror("Failed to request trigger line as output");
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(echo_line, "echo") < 0) {
        perror("Failed to request echo line as input");
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        // Trigger the sensor
        gpiod_line_set_value(trigger_line, 1);
        usleep(10);
        gpiod_line_set_value(trigger_line, 0);

        // Wait for echo to rise
        if (gpiod_line_event_wait(echo_line, &start, TIMEOUT_US / 1000) < 0) {
            perror("Failed to wait for echo rise");
            continue;
        }

        // Wait for echo to fall
        if (gpiod_line_event_wait(echo_line, &end, TIMEOUT_US / 1000) < 0) {
            perror("Failed to wait for echo fall");
            continue;
        }

        // Calculate duration
        duration_us = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;

        // Calculate distance
        distance = duration_us * 0.034 / 2;

        // Check distance range
        if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
            log_distance(distance);
        } else {
            log_distance(-1); // Log timeout or invalid distance
        }

        // Wait for 60 seconds
        sleep(60);
    }

    // Clean up
    fclose(log_file);
    gpiod_line_release(echo_line);
    gpiod_line_release(trigger_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

