This C program for a Raspberry Pi Zero W uses the libgpiod library to drive an HC-SR04 ultrasonic sensor. It issues a 10 µs trigger pulse, waits for the echo to rise and fall, calculates the distance, and logs the result to a file named `distance_log.txt` with an ISO-8601 timestamp. It handles sensor-absent and timeout cases, and catches SIGINT and SIGTERM to perform a graceful shutdown.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x39
#define PROXIMITY_THRESHOLD 200
#define CSV_FILE "color_proximity_log.csv"

static struct gpiod_chip *chip;
static FILE *csv_file;

void handle_signal(int signum) {
    if (csv_file) {
        fclose(csv_file);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(signum);
}

int main() {
    struct gpiod_line *line;
    struct timespec ts;
    uint16_t proximity, red, green, blue;
    int ret;

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (!csv_file) {
        perror("Failed to open CSV file");
        return EXIT_FAILURE;
    }

    // Initialize I2C bus
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        fclose(csv_file);
        return EXIT_FAILURE;
    }

    // Initialize APDS9960 sensor
    line = gpiod_chip_get_line(chip, 23); // Assuming INT line is connected to GPIO23
    if (!line) {
        perror("Failed to get INT line");
        gpiod_chip_close(chip);
        fclose(csv_file);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(line, "apds9960_int");
    if (ret < 0) {
        perror("Failed to request INT line");
        gpiod_chip_close(chip);
        fclose(csv_file);
        return EXIT_FAILURE;
    }

    // Poll sensor every 100ms
    while (1) {
        // Check for proximity event
        ret = gpiod_line_get_value(line);
        if (ret < 0) {
            perror("Failed to read INT line");
            gpiod_chip_close(chip);
            fclose(csv_file);
            return EXIT_FAILURE;
        }

        if (ret == 1) {
            // Read proximity value
            ret = apds9960_read_proximity(&proximity);
            if (ret < 0) {
                perror("Failed to read proximity value");
                gpiod_chip_close(chip);
                fclose(csv_file);
                return EXIT_FAILURE;
            }

            // Read RGB values
            ret = apds9960_read_rgb(&red, &green, &blue);
            if (ret < 0) {
                perror("Failed to read RGB values");
                gpiod_chip_close(chip);
                fclose(csv_file);
                return EXIT_FAILURE;
            }

            // Check proximity threshold
            if (proximity > PROXIMITY_THRESHOLD) {
                // Get current timestamp
                clock_gettime(CLOCK_REALTIME, &ts);

                // Write to CSV file
                fprintf(csv_file, "%ld,%ld,%ld,%d,%d,%d,%d\n",
                        ts.tv_sec, ts.tv_nsec, proximity, red, green, blue);
                fflush(csv_file);
            }
        }

        // Wait for 100ms
        usleep(100000);
    }

    // Close CSV file
    fclose(csv_file);

    // Close I2C handle
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

