        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Verify sensor presence
    uint8_t whoami;
    if (read(i2c_fd, &whoami, 1) != 1) {
        perror("Failed to read WHOAMI register");
        close(i2c_fd);
        return EXIT_FAILURE;
    }
