    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line, "vl53l0x_trigger") < 0) {
        perror("Failed to request GPIO line as input");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_set_direction_input(line) < 0) {
        perror("Failed to set GPIO line direction to input");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "vl53l0x_trigger", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_set_value(line, 0) < 0) {
        perror("Failed to set GPIO line value to 0");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        if (gpiod_line_event_wait(line, TIMEOUT_US) < 0) {
            perror("Failed to wait for GPIO event");
            continue;
        }

        struct gpiod_line_event event;
        if (gpiod_line_event_read(line, &event) < 0) {
            perror("Failed to read GPIO event");
            continue;
        }

        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            // Trigger distance measurement
            if (write(i2c_fd, "\x01\x86\x00\x00\x00\x00\x00\x00", 8) != 8) {
                perror("Failed to trigger distance measurement");
                continue;
            }

            // Poll RESULT_INTERRUPT_STATUS
            uint8_t status;
            if (read(i2c_fd, &status, 1) != 1) {
                perror("Failed to read RESULT_INTERRUPT_STATUS");
                continue;
            }

            if (status & 0x01) {
                // Read distance
                uint16_t distance;
                if (read(i2c_fd, &distance, 2) != 2) {
                    perror("Failed to read distance");
                    continue;
                }

                // Log distance
                log_distance(distance);
            }
        }
    }

    return EXIT_SUCCESS;
}

