#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x20
#define TRIGGER_PIN 17
#define MAX_LOG_SIZE 256

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *trigger_line;
    int i2c_fd;
    uint8_t write_buf[1] = {0x00};
    uint8_t read_buf[2];
    time_t now;
    struct tm *tm_info;
    char timestamp[MAX_LOG_SIZE];

    // Initialize GPIO
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(trigger_line, "ultrasonic_trigger", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open log file
    FILE *log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        // Trigger the sensor
        if (gpiod_line_set_value(trigger_line, 1) < 0) {
            perror("Failed to trigger sensor");
        } else {
            usleep(50000); // Wait 50 ms
            if (gpiod_line_set_value(trigger_line, 0) < 0) {
                perror("Failed to stop sensor trigger");
            } else {
                // Read the distance
                if (read(i2c_fd, read_buf, 2) != 2) {
                    perror("Failed to read distance");
                } else {
                    // Calculate distance
                    int distance = (read_buf[0] << 8) | read_buf[1];
                    distance = distance * 0.016; // Convert to mm

                    // Get current time
                    now = time(NULL);
                    tm_info = localtime(&now);
                    strftime(timestamp, MAX_LOG_SIZE, "%Y-%m-%d %H:%M:%S", tm_info);

                    // Log and print the result
                    fprintf(log_file, "%s, %d\n", timestamp, distance);
                    printf("%s, %d\n", timestamp, distance);
                }
            }
        }

        // Wait 200 ms before next sample
        usleep(200000);
    }

    // Clean up
    fclose(log_file);
    close(i2c_fd);
    gpiod_line_release(trigger_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

