#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define SENSOR1_PIN 17
#define SENSOR2_PIN 18
#define LOG_FILE "obstacle_log.txt"
#define SAMPLE_INTERVAL 100000  // 100 milliseconds in microseconds

struct gpiod_chip *chip;
struct gpiod_line *line1, *line2;
FILE *log_file;

void cleanup() {
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip) gpiod_chip_close(chip);
    if (log_file) fclose(log_file);
}

void handle_sigint(int sig) {
    cleanup();
    exit(0);
}

int main() {
    struct timespec ts;
    char timestamp[20];
    int sensor1_value, sensor2_value;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request the GPIO lines
    line1 = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (!line1) {
        perror("Failed to get GPIO line 1");
        cleanup();
        return EXIT_FAILURE;
    }

    line2 = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (!line2) {
        perror("Failed to get GPIO line 2");
        cleanup();
        return EXIT_FAILURE;
    }

    // Configure the GPIO lines as input
    if (gpiod_line_request_input(line1, "sensor1")) {
        perror("Failed to request input for GPIO line 1");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line2, "sensor2")) {
        perror("Failed to request input for GPIO line 2");
        cleanup();
        return EXIT_FAILURE;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    // Register signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    while (1) {
        // Read sensor values
        sensor1_value = gpiod_line_get_value(line1);
        if (sensor1_value == -1) {
            fprintf(stderr, "Failed to read sensor 1\n");
        }

        sensor2_value = gpiod_line_get_value(line2);
        if (sensor2_value == -1) {
            fprintf(stderr, "Failed to read sensor 2\n");
        }

        // Get current timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("Failed to get current time");
            cleanup();
            return EXIT_FAILURE;
        }

        // Format timestamp
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        // Log the readings
        fprintf(log_file, "%s.%06ld %d %d\n", timestamp, ts.tv_nsec / 1000, sensor1_value, sensor2_value);
        fflush(log_file);

        // Sleep for the specified interval
        if (nanosleep(&(struct timespec){0, SAMPLE_INTERVAL}, NULL) == -1) {
            perror("Failed to sleep");
            cleanup();
            return EXIT_FAILURE;
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

