#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <gpiod.h>
#include <time.h>
#include <sys/time.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x52
#define WHO_AM_I_REG 0x00
#define THRESHOLD 100
#define LED_PIN 17
#define LOG_FILE "tof_log.txt"

static struct gpiod_chip *chip;
static struct gpiod_line *led_line;
static int i2c_fd;

void cleanup() {
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

void handle_sigint(int sig) {
    cleanup();
    exit(0);
}

int read_i2c_register(int fd, uint8_t address, uint8_t *value) {
    uint8_t buffer[2] = {address, 0};
    if (write(fd, buffer, 1) != 1) {
        perror("I2C write");
        return -1;
    }
    if (read(fd, buffer, 1) != 1) {
        perror("I2C read");
        return -1;
    }
    *value = buffer[0];
    return 0;
}

int main(int argc, char *argv[]) {
    int threshold = THRESHOLD;
    if (argc > 1) {
        threshold = atoi(argv[1]);
    }

    signal(SIGINT, handle_sigint);

    // Initialize I2C
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return 1;
    }

    // Initialize GPIO
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    if (gpiod_line_request_output(led_line, "tof_led", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    // Verify sensor WHO_AM_I register
    uint8_t who_am_i;
    if (read_i2c_register(i2c_fd, WHO_AM_I_REG, &who_am_i) < 0) {
        perror("Failed to read WHO_AM_I register");
        cleanup();
        return 1;
    }
    if (who_am_i != 0x20) {
        fprintf(stderr, "Sensor WHO_AM_I register mismatch: 0x%02X\n", who_am_i);
        cleanup();
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    struct timeval tv;
    while (1) {
        uint16_t distance;
        if (read_i2c_register(i2c_fd, 0x02, (uint8_t *)&distance) < 0) {
            perror("Failed to read distance");
            continue;
        }

        if (distance < threshold) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }

        gettimeofday(&tv, NULL);
        fprintf(log_file, "%ld.%06ld: Distance: %d mm\n", tv.tv_sec, tv.tv_usec, distance);
        fflush(log_file);

        usleep(50000);
    }

    fclose(log_file);
    cleanup();
    return 0;
}

