This C program for a Raspberry Pi 4 Model B continuously reads distance measurements from a TDK InvenSense ICU-20201 ultrasonic Time-of-Flight sensor on I2C bus 1 at a 50 ms polling interval. It lights an LED connected to GPIO 17 (BCM) whenever the measured distance falls below a configurable threshold (default 100 mm, supplied as the first command-line argument), logs each reading with a timestamp to a file named "tof_log.txt", verifies the sensor's WHO_AM_I register during initialization, checks all I2C read/write return codes, gracefully handles sensor-absent or bus-error conditions without crashing, and ensures that on any exit path—including receipt of SIGINT—the program releases the I2C handle, resets the GPIO, and performs any required driver cleanup.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SENSOR_ADDRESS 0x29
#define COMMAND_FRAME {0x01, 0x00, 0x00, 0x00}
#define HEADER_VALUE 0x01
#define DISTANCE_OFFSET 11
#define DISTANCE_LENGTH 2
#define SAMPLE_COUNT 10
#define MIN_DISTANCE 1000
#define LOG_FILE "intrusion_log.txt"

static int i2c_fd = -1;
static FILE *log_file = NULL;

void close_resources() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

void sigint_handler(int signum) {
    close_resources();
    exit(signum);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    uint64_t timestamp;
    uint16_t distances[SAMPLE_COUNT];
    uint16_t total_distance = 0;
    uint16_t average_distance;
    int i;

    // Install SIGINT handler
    signal(SIGINT, sigint_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        close_resources();
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        close_resources();
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        close_resources();
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Send command frame
        if (write(i2c_fd, COMMAND_FRAME, sizeof(COMMAND_FRAME)) != sizeof(COMMAND_FRAME)) {
            perror("Failed to send command frame");
            close(i2c_fd);
            fclose(log_file);
            close_resources();
            return EXIT_FAILURE;
        }

        // Wait for response
        usleep(10000);

        // Read response
        uint8_t response[15];
        if (read(i2c_fd, response, sizeof(response)) != sizeof(response)) {
            perror("Failed to read response");
            close(i2c_fd);
            fclose(log_file);
            close_resources();
            return EXIT_FAILURE;
        }

        // Verify header
        if (response[0] != HEADER_VALUE) {
            fprintf(stderr, "Invalid response header\n");
            continue;
        }

        // Extract distance
        uint16_t distance = (response[DISTANCE_OFFSET] << 8) | response[DISTANCE_OFFSET + 1];

        // Sample sensor
        for (i = 1; i < SAMPLE_COUNT; i++) {
            if (write(i2c_fd, COMMAND_FRAME, sizeof(COMMAND_FRAME)) != sizeof(COMMAND_FRAME)) {
                perror("Failed to send command frame");
                close(i2c_fd);
                fclose(log_file);
                close_resources();
                return EXIT_FAILURE;
            }

            usleep(100000);

            if (read(i2c_fd, response, sizeof(response)) != sizeof(response)) {
                perror("Failed to read response");
                close(i2c_fd);
                fclose(log_file);
                close_resources();
                return EXIT_FAILURE;
            }

            if (response[0] != HEADER_VALUE) {
                fprintf(stderr, "Invalid response header\n");
                continue;
            }

            distance = (response[DISTANCE_OFFSET] << 8) | response[DISTANCE_OFFSET + 1];
            distances[i] = distance;
            total_distance += distance;
        }

        // Compute average distance
        average_distance = total_distance / SAMPLE_COUNT;

        // Log intrusion if average distance is less than 1000 mm
        if (average_distance < MIN_DISTANCE) {
            timestamp = time(NULL);
            fprintf(log_file, "%ld %u\n", timestamp, average_distance);
            fflush(log_file);
        }
    }

    // Close resources
    close_resources();
    return EXIT_SUCCESS;
}

