#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define SI1182_I2C_ADDRESS 0x60
#define SI1182_PROXIMITY_DATA_REG 0x20

static struct gpiod_chip *chip;
static struct gpiod_line *sda, *scl;
static int i2c_fd;

void cleanup_and_exit(int sig) {
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(0);
}

int main() {
    struct sigaction sa;
    uint8_t data[2];
    int ret;

    // Initialize signal handler for SIGINT
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to set SIGINT handler");
        return EXIT_FAILURE;
    }

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SI1182_I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize GPIO lines for I2C
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    sda = gpiod_chip_get_line(chip, 2);
    if (!sda) {
        perror("Failed to get SDA line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    scl = gpiod_chip_get_line(chip, 3);
    if (!scl) {
        perror("Failed to get SCL line");
        gpiod_line_release(sda);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Set SDA and SCL lines to input mode
    ret = gpiod_line_request_input(sda, "i2c-sda");
    if (ret < 0) {
        perror("Failed to request SDA line as input");
        gpiod_line_release(scl);
        gpiod_line_release(sda);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(scl, "i2c-scl");
    if (ret < 0) {
        perror("Failed to request SCL line as input");
        gpiod_line_release(sda);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        // Write to the command register to start proximity measurement
        data[0] = 0x18; // Command to start proximity measurement
        if (write(i2c_fd, data, 1) != 1) {
            perror("Failed to write to SI1182");
            cleanup_and_exit(0);
        }

        // Wait for the measurement to complete
        usleep(10000); // 10ms delay

        // Read the proximity data
        if (read(i2c_fd, data, 2) != 2) {
            perror("Failed to read from SI1182");
            cleanup_and_exit(0);
        }

        // Convert the 16-bit data to an integer
        int proximity = (data[0] << 8) | data[1];

        // Print the proximity data
        printf("Proximity: %d\n", proximity);

        // Wait for 500ms before the next reading
        usleep(500000);
    }

    // Cleanup and exit
    cleanup_and_exit(0);
}

