    if (ioctl(fd, I2C_SLAVE, I2C_SLAVE_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    // Check if sensor is present
    if (write(fd, cmd, 1) != 1) {
        fprintf(stderr, "Sensor not present\n");
        close(fd);
        return 1;
    }

    // Install signal handler
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to install SIGINT handler");
        close(fd);
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to install SIGTERM handler");
        close(fd);
        return 1;
    }

    // Main loop
    while (running) {
        // Read distance measurement
        if (write(fd, cmd, 1) != 1) {
            fprintf(stderr, "I2C write failed\n");
            continue;
        }
        if (read(fd, data, MELEXIS_DATA_LEN) != MELEXIS_DATA_LEN) {
            fprintf(stderr, "I2C read failed\n");
            continue;
        }

        // Convert data to distance
        uint16_t distance = (data[0] << 8) | data[1];
        printf("Distance: %u mm\n", distance);

        // Sleep for 500 ms
        ts.tv_sec = 0;
        ts.tv_nsec = 500 * 1000 * 1000;
        if (nanosleep(&ts, NULL) < 0) {
            perror("nanosleep failed");
            running = 0;
        }
    }

    // Close I2C bus
    close(fd);
    return 0;
