#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define OPT3101_REG_DISTANCE 0x00
#define OPT3101_REG_AMBIENT_LIGHT 0x01
#define OPT3101_REG_ERROR_FLAGS 0x02

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

void cleanup() {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    printf("Cleanup complete.\n");
    exit(0);
}

void signal_handler(int sig) {
    cleanup();
}

int main() {
    struct gpiod_line_request req = {
        .consumer = "opt3101",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
    };

    signal(SIGINT, signal_handler);

    // Open the I2C bus
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request the I2C line
    line = gpiod_chip_get_line(chip, 2); // Assuming I2C is on GPIO2
    if (!line) {
        perror("Failed to get I2C line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_one(line, &req)) {
        perror("Failed to request I2C line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        uint8_t distance[2], ambient_light[2], error_flags[1];
        ssize_t ret;

        // Read distance
        ret = gpiod_line_request_bulk(chip, &req, 1);
        if (ret < 0) {
            perror("Failed to request I2C line for distance");
            cleanup();
        }
        ret = gpiod_line_get_value_bulk(line, distance);
        if (ret < 0) {
            perror("Failed to read distance");
            cleanup();
        }
        gpiod_line_release_bulk(line);

        // Read ambient light
        ret = gpiod_line_request_bulk(chip, &req, 1);
        if (ret < 0) {
            perror("Failed to request I2C line for ambient light");
            cleanup();
        }
        ret = gpiod_line_get_value_bulk(line, ambient_light);
        if (ret < 0) {
            perror("Failed to read ambient light");
            cleanup();
        }
        gpiod_line_release_bulk(line);

        // Read error flags
        ret = gpiod_line_request_bulk(chip, &req, 1);
        if (ret < 0) {
            perror("Failed to request I2C line for error flags");
            cleanup();
        }
        ret = gpiod_line_get_value_bulk(line, error_flags);
        if (ret < 0) {
            perror("Failed to read error flags");
            cleanup();
        }
        gpiod_line_release_bulk(line);

        // Print the results
        printf("Distance: %d mm, Ambient Light: %d lux, Error Flags: 0x%02X\n",
               (distance[0] << 8) | distance[1],
               (ambient_light[0] << 8) | ambient_light[1],
               error_flags[0]);

        // Sleep for 500 ms
        usleep(500 * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

