#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define MAX_DISTANCE 38000 // 38 ms * 10000 µs/ms = 380000 µs
#define TIMEOUT_US 200000 // 200 ms * 1000 µs/ms
#define TRIGGER_PULSE_US 10 // 10 µs

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *trigger_line, *echo_line;
    struct timespec start, end;
    long long duration_us;
    time_t now;
    struct tm *tm_info;

    // Initialize signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request trigger line
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Failed to get trigger line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request echo line
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Failed to get echo line");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set trigger line as output
    if (gpiod_line_request_output(trigger_line, "trigger", 0) < 0) {
        perror("Failed to request trigger line as output");
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set echo line as input with pull-down resistor
    if (gpiod_line_request_input(echo_line, "echo") < 0) {
        perror("Failed to request echo line as input");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        // Trigger pulse
        if (gpiod_line_set_value(trigger_line, 1) < 0) {
            perror("Failed to set trigger line high");
            continue;
        }
        usleep(TRIGGER_PULSE_US);
        if (gpiod_line_set_value(trigger_line, 0) < 0) {
            perror("Failed to set trigger line low");
            continue;
        }

        // Wait for echo rising edge
        if (gpiod_line_event_wait(echo_line, &start, TIMEOUT_US) < 0) {
            perror("Failed to wait for echo rising edge");
            continue;
        }

        // Wait for echo falling edge
        if (gpiod_line_event_wait(echo_line, &end, TIMEOUT_US) < 0) {
            perror("Failed to wait for echo falling edge");
            continue;
        }

        // Calculate duration
        duration_us = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;

        // Check for valid duration
        if (duration_us <= 0 || duration_us > MAX_DISTANCE) {
            printf("Invalid pulse duration: %lld µs\n", duration_us);
            continue;
        }

        // Calculate distance
        double distance = duration_us * 0.034 / 2;

        // Get current time
        time(&now);
        tm_info = localtime(&now);

        // Log measurement
        printf("%02d:%02d:%02d.%03d: Distance: %.2f cm\n",
               tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec,
               (int)(tm_info->tm_sec * 1000 + (tm_info->tm_nsec / 1000000)),
               distance);
    }

    // Release resources
    gpiod_line_release(echo_line);
    gpiod_line_release(trigger_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

