#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define UART_DEVICE "/dev/serial0"
#define MAGIC_WORD "\x00\x00\x00\x00\x00\x00\x00\x00"
#define DISTANCE_THRESHOLD 1000  // 1 meter in millimeters
#define LED_PIN 17
#define LED_CHIP "gpiochip0"
#define LED_LINE "17"
#define LOG_FILE "intrusion_log.csv"

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    int uart_fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    FILE *log_file = NULL;

    // Initialize UART
    uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (uart_fd == -1) {
        perror("Failed to open UART device");
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    chip = gpiod_chip_open(LED_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(uart_fd);
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, LED_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(uart_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "intrusion_alert", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(uart_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(uart_fd);
        return EXIT_FAILURE;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        char buffer[136];
        ssize_t bytes_read = read(uart_fd, buffer, sizeof(buffer));
        if (bytes_read == -1) {
            perror("Failed to read from UART");
            break;
        }

        if (bytes_read < 136) {
            continue;
        }

        if (memcmp(buffer, MAGIC_WORD, 8) != 0) {
            continue;
        }

        uint16_t *distance_bins = (uint16_t *)(buffer + 8);
        for (int i = 0; i < 64; i++) {
            if (distance_bins[i] < DISTANCE_THRESHOLD) {
                time_t now = time(NULL);
                struct tm *tm_info = localtime(&now);
                fprintf(log_file, "%04d-%02d-%02dT%02d:%02d:%02d,%f\n",
                        tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
                        tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec,
                        (double)distance_bins[i] / 1000.0);
                fflush(log_file);

                // Activate alert LED
                gpiod_line_set_value(line, 1);
                usleep(2000000);  // 2 seconds
                gpiod_line_set_value(line, 0);
            }
        }
    }

    // Clean up
    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(uart_fd);

    return EXIT_SUCCESS;
}

