        close(uart_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "intrusion_alert", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(uart_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(uart_fd);
        return EXIT_FAILURE;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        char buffer[136];
        ssize_t bytes_read = read(uart_fd, buffer, sizeof(buffer));
        if (bytes_read == -1) {
            perror("Failed to read from UART");
            break;
        }

        if (bytes_read < 136) {
            continue;
        }

        if (memcmp(buffer, MAGIC_WORD, 8) != 0) {
            continue;
        }

        uint16_t *distance_bins = (uint16_t *)(buffer + 8);
        for (int i = 0; i < 64; i++) {
            if (distance_bins[i] < DISTANCE_THRESHOLD) {
                time_t now = time(NULL);
                struct tm *tm_info = localtime(&now);
                fprintf(log_file, "%04d-%02d-%02dT%02d:%02d:%02d,%f\n",
                        tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
                        tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec,
                        (double)distance_bins[i] / 1000.0);
                fflush(log_file);

                // Activate alert LED
                gpiod_line_set_value(line, 1);
                usleep(2000000);  // 2 seconds
                gpiod_line_set_value(line, 0);
            }
        }
    }

    // Clean up
    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(uart_fd);

    return EXIT_SUCCESS;
}
