        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set the buzzer line as output
    if (gpiod_line_request_output(buzzer_line, "obstacle_buzzer", 0)) {
        perror("Failed to request buzzer line as output");
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
