        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        // Read the sensor state
        sensor_state = gpiod_line_get_value(sensor_line);
        if (sensor_state < 0) {
            perror("Failed to read sensor state");
            break;
        }

        // Check for state transition
        if (sensor_state != previous_state) {
            log_state_transition(sensor_state);
            if (sensor_state) {
                // Activate buzzer
                if (gpiod_line_set_value(buzzer_line, 1)) {
                    perror("Failed to activate buzzer");
                    break;
                }
            } else {
                // Deactivate buzzer
                if (gpiod_line_set_value(buzzer_line, 0)) {
                    perror("Failed to deactivate buzzer");
                    break;
                }
            }
            previous_state = sensor_state;
        }

        // Wait for the next poll interval
        usleep(POLL_INTERVAL * 1000);
    }

    // Clean up
    if (sensor_line) gpiod_line_release(sensor_line);
    if (buzzer_line) gpiod_line_release(buzzer_line);
    if (chip) gpiod_chip_close(chip);
    if (log_file) fclose(log_file);

    return EXIT_SUCCESS;
}

