This C program for a Raspberry Pi 4 Model B continuously reads obstacle detection data from an E18-D80NK IR sensor connected to GPIO 17 and drives a buzzer on GPIO 18 based on the sensor's state. It logs each state transition with an ISO 8601 timestamp to a file named `obstacle_log.txt`. The program handles errors, installs signal handlers for graceful shutdown, and releases all GPIO lines and closes the chip on exit.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <unistd.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x52
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define LOG_FILE "distance_log.txt"
#define MIN_DISTANCE 10.0
#define SAMPLE_INTERVAL 100  // in milliseconds

static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;

void log_distance(double distance) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", tm_info);

    fprintf(log_file, "%s, Distance: %.2f cm\n", timestamp, distance);
    fclose(log_file);
}

void handle_signal(int signum) {
    if (gpio_line) {
        gpiod_line_release(gpio_line);
        gpio_line = NULL;
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
        gpio_chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    exit(signum);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize I2C
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_LINE);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(gpio_line, "distance_alert", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        uint8_t buffer[2];
        if (read(i2c_fd, buffer, sizeof(buffer)) != sizeof(buffer)) {
            perror("Failed to read from I2C device");
            handle_signal(EXIT_FAILURE);
        }

        double distance = (buffer[0] << 8) | buffer[1];
        distance = distance * 0.01;  // Convert to cm

        log_distance(distance);

        if (distance < MIN_DISTANCE) {
            if (gpiod_line_set_value(gpio_line, 1) < 0) {
                perror("Failed to set GPIO line high");
                handle_signal(EXIT_FAILURE);
            }
        } else {
            if (gpiod_line_set_value(gpio_line, 0) < 0) {
                perror("Failed to set GPIO line low");
                handle_signal(EXIT_FAILURE);
            }
        }

        usleep(SAMPLE_INTERVAL * 1000);
    }

    return EXIT_SUCCESS;
}

