#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x29
#define LOG_FILE "distance_log.csv"
#define HEADER "timestamp,distance_mm\n"

struct gpiod_chip *chip;
struct gpiod_line *line;
FILE *log_file;

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        if (log_file) {
            fclose(log_file);
        }
        if (chip) {
            gpiod_chip_close(chip);
        }
        exit(signum);
    }
}

int main() {
    struct timespec ts;
    struct tm *tm_info;
    char timestamp[20];
    uint16_t distance;
    int ret;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Open I2C line
    line = gpiod_chip_get_line(chip, 23); // Assuming SDA is connected to GPIO23
    if (!line) {
        perror("Failed to get I2C line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure I2C line as output
    ret = gpiod_line_request_output(line, "i2c");
    if (ret < 0) {
        perror("Failed to request I2C line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Write header if file is empty
    if (ftell(log_file) == 0) {
        fputs(HEADER, log_file);
    }

    while (1) {
        // Get current time
        clock_gettime(CLOCK_REALTIME, &ts);
        tm_info = localtime(&ts.tv_sec);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        // Poll sensor
        ret = gpiod_line_get_value(line);
        if (ret < 0) {
            perror("Failed to get I2C line value");
            continue;
        }

        // Simulate distance reading (replace with actual sensor reading)
        distance = 500; // Example distance in mm

        // Log distance
        fprintf(log_file, "%s,%d\n", timestamp, distance);
        fflush(log_file);

        // Print parking guidance message
        if (distance < 300) {
            printf("STOP\n");
        } else if (distance < 600) {
            printf("APPROACH\n");
        } else if (distance < 1200) {
            printf("SLOW\n");
        } else {
            printf("CLEAR\n");
        }

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up
    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

