#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x52
#define LED_PIN 18
#define LED_FREQ 1000  // 1 kHz
#define LED_HALF_CYCLE 500  // 500 us
#define I2C_RETRIES 3
#define I2C_DELAY 10  // 10 ms

static struct gpiod_chip *chip;
static struct gpiod_line *led_line;
static int i2c_fd = -1;

void close_resources() {
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

void handle_sigint(int sig) {
    close_resources();
    exit(0);
}

void handle_sigterm(int sig) {
    close_resources();
    exit(0);
}

int i2c_retry(int fd, const void *buf, size_t len, int (*func)(int, const void *, size_t)) {
    int retries = I2C_RETRIES;
    while (retries--) {
        if (func(fd, buf, len) == 0) {
            return 0;
        }
        usleep(I2C_DELAY * 1000);
    }
    return -1;
}

int read_distance(int fd) {
    uint8_t cmd = 0x00;
    if (i2c_retry(fd, &cmd, 1, i2c_smbus_write_byte_data) < 0) {
        return -1;
    }

    uint8_t data[2];
    if (i2c_retry(fd, data, 2, i2c_smbus_read_i2c_block_data) < 0) {
        return -1;
    }

    return (data[0] << 8) | data[1];
}

int main() {
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    // Initialize I2C
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return 1;
    }

    // Initialize GPIO
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    while (1) {
        int distance = read_distance(i2c_fd);
        if (distance < 0) {
            fprintf(stderr, "Failed to read distance\n");
            continue;
        }

        // Calculate LED blink frequency based on distance
        int freq = LED_FREQ - (distance * LED_FREQ / 1000);
        if (freq < 0) {
            freq = 0;
        }

        // Blink LED
        for (int i = 0; i < freq; i++) {
            gpiod_line_set_value(led_line, 1);
            usleep(LED_HALF_CYCLE);
            gpiod_line_set_value(led_line, 0);
            usleep(LED_HALF_CYCLE);
        }

        // Log distance and LED frequency
        printf("Distance: %d mm, LED Frequency: %d Hz\n", distance, freq);
        fflush(stdout);

        usleep(100 * 1000);  // 100 ms
    }

    close_resources();
    return 0;
}

