#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x50
#define MEASURE_COMMAND 0x01
#define DISTANCE_REG 0x00
#define RETRY_COUNT 5
#define RETRY_DELAY 100

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buffer[2] = {reg, value};
    if (write(fd, buffer, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write failed");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int i2c_fd;
    FILE *log_file;
    uint8_t distance;
    time_t now;
    struct tm *tm_info;
    char timestamp[20];

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("distance_log.csv", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        // Trigger measurement
        if (i2c_write(i2c_fd, MEASURE_COMMAND, 0x00) < 0) {
            fprintf(stderr, "Failed to trigger measurement\n");
            continue;
        }

        // Wait for measurement to complete
        usleep(100000); // 100 ms

        // Read distance
        if (i2c_read(i2c_fd, DISTANCE_REG, &distance) < 0) {
            fprintf(stderr, "Failed to read distance\n");
            continue;
        }

        // Get current time
        time(&now);
        tm_info = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        // Log distance
        fprintf(log_file, "%s,%d\n", timestamp, distance);
        fflush(log_file);
    }

    // Clean up
    fclose(log_file);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

