#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define SENSOR1_PIN 17
#define SENSOR2_PIN 27
#define DEBOUNCE_TIME 50
#define POLL_INTERVAL 10

struct sensor {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int last_state;
};

void log_event(int sensor_id, const char *event_type) {
    time_t now = time(NULL);
    struct tm *utc_time = gmtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc_time);

    FILE *log_file = fopen("proximity_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "%s, Sensor %d, %s\n", timestamp, sensor_id, event_type);
    fclose(log_file);
}

void sensor_event_handler(struct sensor *sensor) {
    int current_state = gpiod_line_get_value(sensor->line);
    if (current_state != sensor->last_state) {
        if (current_state == 0) {
            log_event(sensor->line->offset + 1, "DETECTED");
        } else {
            log_event(sensor->line->offset + 1, "CLEARED");
        }
        sensor->last_state = current_state;
    }
}

void handle_signal(int sig) {
    static int signal_received = 0;
    if (signal_received) {
        exit(1);
    }
    signal_received = 1;
    printf("Received signal %d, shutting down gracefully...\n", sig);
}

int main() {
    struct sensor sensors[2];
    struct gpiod_chip *chip;
    struct gpiod_line_request_config config = {
        .consumer = "proximity_sensor",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
    };

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 2; i++) {
        sensors[i].chip = chip;
        sensors[i].line = gpiod_chip_get_line(chip, SENSOR1_PIN + i);
        if (!sensors[i].line) {
            perror("Failed to get GPIO line");
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        if (gpiod_line_request(sensors[i].line, &config) < 0) {
            perror("Failed to request GPIO line");
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        sensors[i].last_state = gpiod_line_get_value(sensors[i].line);
    }

    while (!handle_signal) {
        for (int i = 0; i < 2; i++) {
            sensor_event_handler(&sensors[i]);
            usleep(DEBOUNCE_TIME * 1000);
        }
        usleep(POLL_INTERVAL * 1000);
    }

    for (int i = 0; i < 2; i++) {
        gpiod_line_release(sensors[i].line);
    }
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

