#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_SLAVE_ADDR 0x52
#define MEAS_STATUS_REG 0x00
#define DISTANCE_REG 0x01
#define TIMEOUT_US 50000
#define SAMPLE_INTERVAL_MS 500
#define CSV_FILE "distance_log.csv"

int i2c_fd = -1;
FILE *csv_fd = NULL;

void close_resources() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (csv_fd != NULL) {
        fflush(csv_fd);
        fclose(csv_fd);
    }
}

void handle_signal(int sig) {
    close_resources();
    exit(0);
}

int read_distance() {
    uint8_t buf[2];
    struct timespec start, end;
    int ret;

    clock_gettime(CLOCK_MONOTONIC, &start);

    while (1) {
        ret = ioctl(i2c_fd, I2C_SLAVE, I2C_SLAVE_ADDR);
        if (ret < 0) {
            perror("ioctl(I2C_SLAVE)");
            return -1;
        }

        buf[0] = MEAS_STATUS_REG;
        ret = write(i2c_fd, buf, 1);
        if (ret < 0) {
            perror("write");
            return -1;
        }

        ret = read(i2c_fd, buf, 1);
        if (ret < 0) {
            perror("read");
            return -1;
        }

        if (buf[0] & 0x01) {
            break;
        }

        clock_gettime(CLOCK_MONOTONIC, &end);
        if (timespec_sub(&end, &start) >= TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for measurement\n");
            return -1;
        }

        usleep(1000);
    }

    buf[0] = DISTANCE_REG;
    ret = write(i2c_fd, buf, 1);
    if (ret < 0) {
        perror("write");
        return -1;
    }

    ret = read(i2c_fd, buf, 2);
    if (ret < 0) {
        perror("read");
        return -1;
    }

    return (buf[0] << 8) | buf[1];
}

int main() {
    struct sigaction sa;
    time_t now;
    struct tm *tm_info;
    char timestamp[20];
    int distance;

    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
