int read_distance() {
    uint8_t buf[2];
    struct timespec start, end;
    int ret;

    clock_gettime(CLOCK_MONOTONIC, &start);

    while (1) {
        ret = ioctl(i2c_fd, I2C_SLAVE, I2C_SLAVE_ADDR);
        if (ret < 0) {
            perror("ioctl(I2C_SLAVE)");
            return -1;
        }

        buf[0] = MEAS_STATUS_REG;
        ret = write(i2c_fd, buf, 1);
        if (ret < 0) {
            perror("write");
            return -1;
        }

        ret = read(i2c_fd, buf, 1);
        if (ret < 0) {
            perror("read");
            return -1;
        }

        if (buf[0] & 0x01) {
            break;
