#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>

#define I2C_DEVICE "/dev/i2c-1"
#define VL53L5CX_I2C_ADDRESS 0x52
#define ZONE_COUNT 64
#define ZONE_SIZE 8
#define I2C_READ_SIZE 2
#define I2C_WRITE_SIZE 1
#define I2C_DELAY 500

static int i2c_fd = -1;

void close_i2c() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

void handle_sigint(int sig) {
    close_i2c();
    exit(0);
}

int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buffer[I2C_WRITE_SIZE] = {reg, value};
    if (write(fd, buffer, I2C_WRITE_SIZE) != I2C_WRITE_SIZE) {
        perror("i2c_write_byte");
        return -1;
    }
    return 0;
}

int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buffer, size_t size) {
    if (write(fd, &reg, 1) != 1) {
        perror("i2c_read_bytes: write");
        return -1;
    }
    if (read(fd, buffer, size) != size) {
        perror("i2c_read_bytes: read");
        return -1;
    }
    return 0;
}

int vl53l5cx_init() {
    if (i2c_write_byte(i2c_fd, 0x00, 0x01) != 0) return -1; // Reset
    usleep(100000);
    if (i2c_write_byte(i2c_fd, 0x00, 0x00) != 0) return -1; // Normal operation
    if (i2c_write_byte(i2c_fd, 0x01, 0x01) != 0) return -1; // Enable ranging
    if (i2c_write_byte(i2c_fd, 0x02, 0x01) != 0) return -1; // Enable measurement
    return 0;
}

void vl53l5cx_read_zones(uint8_t *zones) {
    for (int i = 0; i < ZONE_COUNT; i++) {
        uint8_t buffer[I2C_READ_SIZE];
        if (i2c_read_bytes(i2c_fd, 0x10 + (i * 2), buffer, I2C_READ_SIZE) != 0) continue;
        zones[i] = (buffer[0] << 8) | buffer[1];
    }
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_sigint;
    sigaction(SIGINT, &sa, NULL);

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VL53L5CX_I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close_i2c();
        return EXIT_FAILURE;
    }

    if (vl53l5cx_init() != 0) {
        fprintf(stderr, "Failed to initialize VL53L5CX sensor\n");
        close_i2c();
        return EXIT_FAILURE;
    }

    uint8_t zones[ZONE_COUNT];
    while (1) {
        vl53l5cx_read_zones(zones);
        for (int i = 0; i < ZONE_COUNT; i++) {
            printf("Zone %d: %d mm\n", i, zones[i]);
        }
        usleep(I2C_DELAY * 1000);
    }

    close_i2c();
    return EXIT_SUCCESS;
}

