This C program for a Raspberry Pi Zero W reads distance data from a VL53L5CX Time-of-Flight (ToF) sensor connected via the I2C bus. It initializes the sensor, reads 64 zones (8x8 grid), and logs the distances to the console every 500ms. The program handles I2C communication manually using standard Linux file I/O and includes robust error handling. It also ensures clean resource release on all exit paths, including handling of SIGINT.

code:
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x50
#define MLX75030_REG_DISTANCE 0x00
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define SAMPLE_INTERVAL_MS 100

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int read_distance(struct gpiod_chip *chip, uint8_t address) {
    uint8_t reg = MLX75030_REG_DISTANCE;
    uint8_t data[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        int ret = gpiod_chip_i2c_read(chip, address, &reg, 1, data, 2);
        if (ret == 2) {
            return (data[0] << 8) | data[1];
        } else if (ret < 0) {
            usleep(RETRY_DELAY_MS * 1000);
            retries++;
        } else {
            break;
        }
    }

    return -1;
}

int main() {
    struct gpiod_chip *chip;
    int ret;

    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    ret = gpiod_chip_i2c_claim_bus(chip, I2C_BUS);
    if (ret < 0) {
        perror("Failed to claim I2C bus");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        uint64_t timestamp = gpiod_chip_i2c_get_timestamp(chip);
        int distance = read_distance(chip, I2C_ADDRESS);

        if (distance >= 0) {
            printf("Timestamp: %llu, Distance: %d mm\n", timestamp, distance);
        } else {
            printf("Failed to read distance\n");
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    gpiod_chip_i2c_release_bus(chip);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

