This C program for a Raspberry Pi Zero W uses the `libgpiod` library to interact with the I2C bus and the Melexis MLX75030 Time-of-Flight sensor. It reads distance measurements every 100 ms, logs each measurement with a millisecond timestamp, and handles graceful shutdowns triggered by SIGINT (Ctrl-C). The program includes error handling for I2C transactions and ensures that the I2C handle is closed and the driver library is properly terminated on all exit paths.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x29
#define INT_STATUS_REG 0x01
#define RESULT_REG 0x14
#define MEASUREMENT_VALID_BIT 0x01

struct i2c_handle {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
};

static struct i2c_handle i2c;

static void cleanup_and_exit(int status) {
    if (i2c.line) {
        gpiod_line_release(i2c.line);
    }
    if (i2c.chip) {
        gpiod_chip_close(i2c.chip);
    }
    exit(status);
}

static void signal_handler(int signum) {
    cleanup_and_exit(0);
}

static int read_i2c_register(uint8_t reg, uint8_t *value) {
    struct i2c_msg msg[2];
    struct i2c_rdwr_ioctl_data packets;
    uint8_t buf[1];

    buf[0] = reg;

    msg[0].addr = I2C_ADDRESS;
    msg[0].flags = 0;
    msg[0].len = 1;
    msg[0].buf = buf;

    msg[1].addr = I2C_ADDRESS;
    msg[1].flags = I2C_M_RD;
    msg[1].len = 1;
    msg[1].buf = value;

    packets.msgs = msg;
    packets.nmsgs = 2;

    if (ioctl(i2c.chip->fd, I2C_RDWR, &packets) < 0) {
        perror("I2C_RDWR");
        return -1;
    }

    return 0;
}

static int write_i2c_register(uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (i2c_write(i2c.chip, buf, 2) != 2) {
        perror("I2C write");
        return -1;
    }

    return 0;
}

int main() {
    struct timespec ts;
    uint8_t int_status, distance;

    if (signal(SIGINT, signal_handler) == SIG_ERR ||
        signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("signal");
        return 1;
    }

    i2c.chip = gpiod_chip_open_by_name("gpiochip0");
    if (!i2c.chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    i2c.line = gpiod_chip_get_line(i2c.chip, 17); // Assuming interrupt line is GPIO17
    if (!i2c.line) {
        perror("gpiod_chip_get_line");
        cleanup_and_exit(1);
    }

    if (gpiod_line_request_input(i2c.line, "vl53l4cx_int") < 0) {
        perror("gpiod_line_request_input");
        cleanup_and_exit(1);
    }

    if (write_i2c_register(0x02, 0x01) < 0) { // Enable measurement
        cleanup_and_exit(1);
    }

    while (1) {
        if (gpiod_line_get_value(i2c.line) == 0) {
            continue;
        }

        if (read_i2c_register(INT_STATUS_REG, &int_status) < 0) {
            fprintf(stderr, "Failed to read interrupt status\n");
            continue;
        }

        if (!(int_status & MEASUREMENT_VALID_BIT)) {
            continue;
        }

        if (read_i2c_register(RESULT_REG, &distance) < 0) {
            fprintf(stderr, "Failed to read distance\n");
            continue;
        }

        if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
            perror("clock_gettime");
            cleanup_and_exit(1);
        }

        printf("Timestamp: %04ld-%02ld-%02ld %02ld:%02ld:%02ld.%06ld, Distance: %d mm\n",
               ts.tv_sec / 31536000 + 1970, (ts.tv_sec % 31536000) / 2628000 + 1,
               (ts.tv_sec % 2628000) / 86400 + 1, ts.tv_sec % 86400 / 3600,
               (ts.tv_sec % 3600) / 60, ts.tv_sec % 60, ts.tv_nsec / 1000,
               distance);

        if (write_i2c_register(INT_STATUS_REG, 0x00) < 0) { // Clear interrupt
            fprintf(stderr, "Failed to clear interrupt status\n");
            continue;
        }
    }

    cleanup_and_exit(0);
}

