#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 17
#define MIN_DISTANCE 2
#define MAX_DISTANCE 400
#define MIN_ANGLE -90
#define MAX_ANGLE 90
#define TIMEOUT_US 50000
#define LOOP_INTERVAL_MS 200

static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static struct gpiod_line *servo_line;
static FILE *log_file;

void cleanup_and_exit(int sig) {
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(sig);
}

void set_servo_angle(int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Invalid servo angle: %d\n", angle);
        return;
    }
    int duty_cycle = (angle - MIN_ANGLE) * (20000 - 5000) / (MAX_ANGLE - MIN_ANGLE) + 5000;
    char command[50];
    snprintf(command, sizeof(command), "echo %d > /sys/class/pwm/pwmchip0/pwm0/duty_cycle", duty_cycle);
    system(command);
}

int measure_distance() {
    int distance = -1;
    struct timespec start, end;
    long duration_us;

    if (gpiod_line_set_value(trigger_line, 1) < 0) {
        perror("Failed to set trigger line high");
        return -1;
    }
    usleep(10);
    if (gpiod_line_set_value(trigger_line, 0) < 0) {
        perror("Failed to set trigger line low");
        return -1;
    }

    if (clock_gettime(CLOCK_MONOTONIC, &start) < 0) {
        perror("Failed to get start time");
        return -1;
    }

    while (gpiod_line_get_value(echo_line) == 0) {
        if (clock_gettime(CLOCK_MONOTONIC, &end) < 0) {
            perror("Failed to get end time");
            return -1;
        }
        duration_us = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
        if (duration_us > TIMEOUT_US) {
            fprintf(stderr, "Sensor timeout\n");
            return -1;
        }
    }

    start = end;
    while (gpiod_line_get_value(echo_line) == 1) {
        if (clock_gettime(CLOCK_MONOTONIC, &end) < 0) {
            perror("Failed to get end time");
            return -1;
        }
        duration_us = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
        if (duration_us > TIMEOUT_US) {
            fprintf(stderr, "Sensor timeout\n");
            return -1;
        }
    }

    distance = duration_us * 0.034 / 2;
    return distance;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set SIGINT handler");
        return EXIT_FAILURE;
    }

    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set SIGTERM handler");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Failed to get trigger line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Failed to get echo line");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    servo_line = gpiod_chip_get_line(chip, SERVO_PIN);
    if (!servo_line) {
        perror("Failed to get servo line");
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(trigger_line, "trigger") < 0) {
        perror("Failed to request trigger line");
        gpiod_line_release(servo_line);
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(echo_line, "echo") < 0) {
        perror("Failed to request echo line");
        gpiod_line_release(servo_line);
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(servo_line, "servo") < 0) {
        perror("Failed to request servo line");
        gpiod_line_release(servo_line);
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_file = fopen("sensor_data.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(servo_line);
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        int distance = measure_distance();
        if (distance >= 0) {
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, Distance: %d cm\n",
                    tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
                    tm->tm_hour, tm->tm_min, tm->tm_sec, distance);
            fflush(log_file);
            int angle = (distance - MIN_DISTANCE) * (MAX_ANGLE - MIN_ANGLE) / (MAX_DISTANCE - MIN_DISTANCE) + MIN_ANGLE;
            set_servo_angle(angle);
        }
        usleep(LOOP_INTERVAL_MS * 1000);
    }

    cleanup_and_exit(0);
    return EXIT_SUCCESS;
