#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <mqueue.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x29
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 23
#define MQ_NAME "/distance_queue"
#define MQ_MAX_SIZE 1024
#define MQ_MSG_SIZE sizeof(uint32_t)
#define TIMING_BUDGET 50

static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static mqd_t mq = -1;

void cleanup() {
    if (gpio_line) {
        gpiod_line_release(gpio_line);
        gpio_line = NULL;
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
        gpio_chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (mq >= 0) {
        mq_close(mq);
        mq = -1;
    }
}

void handle_sigint(int sig) {
    cleanup();
    exit(0);
}

int main() {
    struct i2c_msg msg;
    struct i2c_rdwr_ioctl_data msgs;
    uint8_t write_buf[1] = {0x01};
    uint8_t read_buf[2];
    uint16_t distance;
    uint32_t msg_data;

    // Set up signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    // Open I2C bus
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open message queue
    struct mq_attr attr = {
        .mq_flags = 0,
        .mq_maxmsg = 10,
        .mq_msgsize = MQ_MSG_SIZE,
        .mq_curmsgs = 0
    };
    mq = mq_open(MQ_NAME, O_CREAT | O_RDWR, 0666, &attr);
    if (mq == (mqd_t)-1) {
        perror("Failed to open message queue");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        mq_close(mq);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Request GPIO line
    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_LINE);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        mq_close(mq);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Configure GPIO line as output
    if (gpiod_line_request_output(gpio_line, "buzzer", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        mq_close(mq);
        close(i2c_fd);
        return EXIT_FAILURE;
