static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static struct gpiod_line *buzzer_line;
static int running = 1;

void handle_sigint(int sig) {
    running = 0;
}

void init_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(EXIT_FAILURE);
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        fprintf(stderr, "Failed to get trigger line\n");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Failed to get echo line\n");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Failed to get buzzer line\n");
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(trigger_line, "trigger", 0) < 0) {
        fprintf(stderr, "Failed to request trigger line as output\n");
        gpiod_line_release(buzzer_line);
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(echo_line, "echo") < 0) {
        fprintf(stderr, "Failed to request echo line as input\n");
        gpiod_line_release(buzzer_line);
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        fprintf(stderr, "Failed to request buzzer line as output\n");
        gpiod_line_release(buzzer_line);
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
}

void cleanup_gpio() {
    gpiod_line_release(buzzer_line);
    gpiod_line_release(echo_line);
    gpiod_line_release(trigger_line);
    gpiod_chip_close(chip);
}

void measure_distance() {
    struct timespec start, end;
    long long duration_ns;
    int distance_cm;

    gpiod_line_set_value(trigger_line, 1);
    nanosleep((struct timespec){0, 10}, NULL);
    gpiod_line_set_value(trigger_line, 0);

    if (clock_gettime(CLOCK_MONOTONIC, &start) < 0) {
        fprintf(stderr, "Failed to get start time\n");
        return;
    }

    while (gpiod_line_get_value(echo_line) == 0) {
        if (clock_gettime(CLOCK_MONOTONIC, &start) < 0) {
            fprintf(stderr, "Failed to get start time\n");
            return;
        }
    }

    while (gpiod_line_get_value(echo_line) == 1) {
        if (clock_gettime(CLOCK_MONOTONIC, &end) < 0) {
            fprintf(stderr, "Failed to get end time\n");
            return;
        }
    }

    duration_ns = (end.tv_sec - start.tv_sec) * 1000000000LL + (end.tv_nsec - start.tv_nsec);
    distance_cm = (duration_ns / 58) / 1000;

    if (distance_cm < MIN_DISTANCE || distance_cm > MAX_DISTANCE) {
        printf("Invalid reading: %d cm\n", distance_cm);
    } else {
        printf("Distance: %d cm\n", distance_cm);
        if (distance_cm < 30) {
            gpiod_line_set_value(buzzer_line, 1);
        } else {
            gpiod_line_set_value(buzzer_line, 0);
        }
    }
}

int main() {
    signal(SIGINT, handle_sigint);

    init_gpio();

    while (running) {
        measure_distance();
        nanosleep((struct timespec){0, SAMPLE_INTERVAL_MS * 1000000}, NULL);
    }

    cleanup_gpio();
    return 0;
}

