#define I2C_ADDRESS 0x29
#define SERVO_PIN 18
#define SERVO_FREQ 50
#define SERVO_OPEN 120
#define SERVO_CLOSE 0
#define DISTANCE_THRESHOLD 20
#define RETRY_DELAY 1000000
#define MAX_RETRIES 5

struct gpiod_chip *chip;
