    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char buffer[80];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", tm_info);
    dprintf(log_fd, "%s: %s\n", buffer, event);
}

void force_open(void) {
    gpioServo(SERVO_PIN, SERVO_OPEN);
    log_event("Gate opened");
}

void force_close(void) {
    gpioServo(SERVO_PIN, SERVO_CLOSE);
    log_event("Gate closed");
}

void status_request(void) {
    int distance = read_distance();
    if (distance < 0) {
        log_event("Sensor absent or communication error");
    } else {
        log_event(distance < DISTANCE_THRESHOLD ? "Object detected" : "Path clear");
    }
}

int read_distance() {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        int distance = vl53l1x_read_distance();
        if (distance >= 0) {
