    gpioTerminate();
    gpiod_line_release(servo_line);
    gpiod_chip_close(chip);
    close(log_fd);
    exit(0);
}

void signal_handler(int signum) {
    cleanup();
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for servo\n");
        gpioTerminate();
        return 1;
    }

    gpioSetPWMfrequency(SERVO_PIN, SERVO_FREQ);
    gpioSetPWMrange(SERVO_PIN, 1000);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        gpioTerminate();
        return 1;
    }

    servo_line = gpiod_chip_get_line(chip, SERVO_PIN);
    if (!servo_line) {
        fprintf(stderr, "Failed to get GPIO line for servo\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    if (gpiod_line_request_output(servo_line, "servo", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line for servo\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    log_fd = open("gate_log.txt", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_line_release(servo_line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        int distance = read_distance();
        if (distance >= 0) {
            if (distance < DISTANCE_THRESHOLD) {
                force_open();
            } else {
                force_close();
            }
        } else {
            force_close();
        }
        sleep(1);
    }

    return 0;
}

