#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define TRIGGER_INTERVAL 200000  // 200 ms in microseconds
#define MIN_PULSE_WIDTH 100       // 100 µs
#define MAX_PULSE_WIDTH 30000     // 30000 µs
#define TIMEOUT 60000000          // 60 ms in microseconds

static struct gpiod_chip *chip;
static struct gpiod_line *trig_line, *echo_line;
static FILE *log_file;
static int running = 1;

void log_distance(double distance) {
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", localtime(&now));
    fprintf(stdout, "%s: Distance: %.2f cm\n", timestamp, distance);
    fprintf(log_file, "%s: Distance: %.2f cm\n", timestamp, distance);
    fflush(log_file);
}

void handle_interrupt(int line_offset, unsigned long long timestamp_ns) {
    static unsigned long long last_rising_tick = 0;
    static unsigned long long last_falling_tick = 0;
    static int rising_edge = 0;

    unsigned long long timestamp_us = timestamp_ns / 1000;

    if (line_offset == ECHO_PIN) {
        if (rising_edge) {
            last_falling_tick = timestamp_us;
            if (last_falling_tick < last_rising_tick) {
                last_falling_tick += 0xFFFFFFFF;  // Handle 32-bit tick wraparound
            }
            unsigned long long pulse_width = last_falling_tick - last_rising_tick;
            if (pulse_width >= MIN_PULSE_WIDTH && pulse_width <= MAX_PULSE_WIDTH) {
                double distance = (pulse_width * 0.034 / 2.0) * 100.0;
                log_distance(distance);
            } else {
                fprintf(stderr, "Warning: Invalid pulse width: %llu µs\n", pulse_width);
            }
            rising_edge = 0;
        } else {
            last_rising_tick = timestamp_us;
            rising_edge = 1;
        }
    }
}

void signal_handler(int sig) {
    running = 0;
}

int main() {
    struct gpiod_line_request_config trig_config = {
        .consumer = "trig",
        .request_type = GPIOD_LINE_REQUEST_OUTPUT,
        .default_val = 0,
    };

    struct gpiod_line_request_config echo_config = {
        .consumer = "echo",
        .request_type = GPIOD_LINE_REQUEST_INPUT,
        .default_val = 0,
        .flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN,
    };

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    if (!trig_line) {
        perror("Failed to get TRIG line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Failed to get ECHO line");
        gpiod_line_release(trig_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(trig_line, &trig_config) < 0) {
        perror("Failed to request TRIG line");
        gpiod_line_release(echo_line);
        gpiod_line_release(trig_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(echo_line, &echo_config) < 0) {
        perror("Failed to request ECHO line");
        gpiod_line_release(trig_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(echo_line);
        gpiod_line_release(trig_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        gpiod_line_set_value(trig_line, 1);
        usleep(10);  // 10 µs trigger pulse
        gpiod_line_set_value(trig_line, 0);

        struct gpiod_line_event event;
        while (gpiod_line_event_wait(echo_line, 200000) > 0) {
            if (gpiod_line_event_read(echo_line, &event) > 0) {
                handle_interrupt(event.event_type, event.timestamp_ns);
            }
        }

        if (gpiod_line_get_value(echo_line) == 0) {
            fprintf(stderr, "Warning: Echo timeout\n");
        }
    }

    fclose(log_file);
    gpiod_line_release(echo_line);
    gpiod_line_release(trig_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

