#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define SHUTDOWN_PIN 23
#define INT_PIN 24
#define SERVO_PIN 18
#define MIN_DISTANCE 50
#define MAX_DISTANCE 60
#define LOG_FILE "parking_log.txt"

static struct gpiod_chip *chip;
static struct gpiod_line *shutdown_line, *int_line, *servo_line;
static FILE *log_file;

void log_event(const char *state, int distance) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(log_file, "%s: %s, Distance: %d cm\n", asctime(tm_info), state, distance);
    fflush(log_file);
}

void close_resources() {
    if (log_file) fclose(log_file);
    if (servo_line) gpiod_line_release(servo_line);
    if (int_line) gpiod_line_release(int_line);
    if (shutdown_line) gpiod_line_release(shutdown_line);
    if (chip) gpiod_chip_close(chip);
}

void handle_signal(int sig) {
    close_resources();
    exit(0);
}

int main() {
    struct gpiod_line_request_config config = {
        .consumer = "parking_gate",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT,
        .default_val = 0,
    };

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open_by_number(I2C_BUS);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    shutdown_line = gpiod_chip_get_line(chip, SHUTDOWN_PIN);
    if (!shutdown_line) {
        perror("Failed to get shutdown line");
        close_resources();
        return EXIT_FAILURE;
    }

    int_line = gpiod_chip_get_line(chip, INT_PIN);
    if (!int_line) {
        perror("Failed to get interrupt line");
        close_resources();
        return EXIT_FAILURE;
    }

    servo_line = gpiod_chip_get_line(chip, SERVO_PIN);
    if (!servo_line) {
        perror("Failed to get servo line");
        close_resources();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(shutdown_line, &config) < 0) {
        perror("Failed to request shutdown line");
        close_resources();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(int_line, &config) < 0) {
        perror("Failed to request interrupt line");
        close_resources();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(servo_line, &config) < 0) {
        perror("Failed to request servo line");
        close_resources();
        return EXIT_FAILURE;
    }

    if (gpiod_line_set_value(shutdown_line, 0) < 0) {
        perror("Failed to set shutdown line");
        close_resources();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close_resources();
        return EXIT_FAILURE;
    }

    int state = 0; // 0: closed, 1: open
    int distance = 0;

    while (1) {
        // Simulate reading distance from VL53L1X (replace with actual I2C read)
        distance = rand() % 100;

        if (distance < MIN_DISTANCE) {
            if (!state) {
                state = 1;
                gpiod_line_set_value(servo_line, 1); // Open gate
                log_event("Gate Opened", distance);
            }
        } else if (distance > MAX_DISTANCE) {
            if (state) {
                state = 0;
                gpiod_line_set_value(servo_line, 0); // Close gate
                log_event("Gate Closed", distance);
            }
        }

        sleep(1);
    }

    close_resources();
    return EXIT_SUCCESS;
}

