#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x29
#define GPIO_CHIP "gpiochip0"
#define GPIO_18 18
#define GPIO_19 19
#define DISTANCE_THRESHOLD 200
#define LOG_FILE "gate_events.log"
#define POLL_INTERVAL 500

static struct gpiod_chip *chip;
static struct gpiod_line *line18, *line19;
static int i2c_fd;
static FILE *log_file;

void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *tm_info = gmtime(&now);
    fprintf(log_file, "%04d-%02d-%02dT%02d:%02d:%02dZ %s\n",
            tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
            tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec, event);
    fflush(log_file);
}

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        if (i2c_fd >= 0) {
            close(i2c_fd);
        }
        if (chip) {
            gpiod_chip_close(chip);
        }
        if (log_file) {
            fclose(log_file);
        }
        exit(0);
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    line18 = gpiod_chip_get_line(chip, GPIO_18);
    if (!line18) {
        perror("Failed to get GPIO 18 line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    line19 = gpiod_chip_get_line(chip, GPIO_19);
    if (!line19) {
        perror("Failed to get GPIO 19 line");
        gpiod_line_release(line18);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line18, "gate_18", 0) < 0) {
        perror("Failed to request GPIO 18 as output");
        gpiod_line_release(line19);
        gpiod_line_release(line18);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line19, "gate_19", 1) < 0) {
        perror("Failed to request GPIO 19 as output");
        gpiod_line_release(line18);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(line18);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize VL53L1X sensor (soft reset, configure timing budget, start ranging)
    // This part is sensor-specific and not provided here

    while (1) {
        // Read distance measurement from VL53L1X sensor
        // This part is sensor-specific and not provided here

        int distance;
        // Assuming distance is read into the variable 'distance'

        if (distance < DISTANCE_THRESHOLD) {
            gpiod_line_set_value(line18, 1);
            gpiod_line_set_value(line19, 0);
            log_event("Gate opened");
        } else {
            gpiod_line_set_value(line18, 0);
            gpiod_line_set_value(line19, 1);
            log_event("Gate closed");
        }

        usleep(POLL_INTERVAL * 1000);
    }

    // Cleanup
    gpiod_line_release(line18);
    gpiod_line_release(line19);
    gpiod_chip_close(chip);
    close(i2c_fd);
    fclose(log_file);

    return EXIT_SUCCESS;
}

