#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define GPIO_MOTOR_FORWARD 17
#define GPIO_MOTOR_BACKWARD 18
#define GPIO_TRIGGER 24
#define DISTANCE_THRESHOLD_1 100
#define DISTANCE_THRESHOLD_2 300
#define RETRY_DELAY 100000 // 100ms
#define MAX_RETRIES 10

volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
}

int i2c_retry(int fd, const void *tx_buf, size_t tx_len, void *rx_buf, size_t rx_len) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        int rc = i2c_write_read_device(fd, tx_buf, tx_len, rx_buf, rx_len);
        if (rc == 0) {
            return 0;
        }
        retries++;
        usleep(RETRY_DELAY * (1 << retries));
    }
    return -1;
}

void motor_stop() {
    gpioWrite(GPIO_MOTOR_FORWARD, PI_OFF);
    gpioWrite(GPIO_MOTOR_BACKWARD, PI_OFF);
}

void motor_forward() {
    gpioWrite(GPIO_MOTOR_FORWARD, PI_ON);
    gpioWrite(GPIO_MOTOR_BACKWARD, PI_OFF);
}

void motor_backward() {
    gpioWrite(GPIO_MOTOR_FORWARD, PI_OFF);
    gpioWrite(GPIO_MOTOR_BACKWARD, PI_ON);
}

void vl53l1x_soft_reset(int fd) {
    uint8_t reset_cmd[] = {0x00, 0x00};
    if (i2c_retry(fd, reset_cmd, sizeof(reset_cmd), NULL, 0) != 0) {
        fprintf(stderr, "Failed to perform soft reset on VL53L1X\n");
        exit(EXIT_FAILURE);
    }
    usleep(100000); // 1ms delay
}

uint16_t vl53l1x_read_distance(int fd) {
    uint8_t cmd[] = {0x14, 0x01};
    uint8_t status;
    uint16_t distance;

    if (i2c_retry(fd, cmd, sizeof(cmd), &status, sizeof(status)) != 0) {
        fprintf(stderr, "Failed to start measurement on VL53L1X\n");
        return 0;
    }

    while (1) {
        uint8_t status;
        if (i2c_retry(fd, NULL, 0, &status, sizeof(status)) != 0) {
            fprintf(stderr, "Failed to read status from VL53L1X\n");
            return 0;
        }
        if (status & 0x04) {
            break;
        }
        usleep(1000); // 1ms delay
    }

    if (i2c_retry(fd, NULL, 0, &distance, sizeof(distance)) != 0) {
        fprintf(stderr, "Failed to read distance from VL53L1X\n");
        return 0;
    }

    return distance;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_MOTOR_FORWARD, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_MOTOR_FORWARD);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_MOTOR_BACKWARD, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_MOTOR_BACKWARD);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_TRIGGER, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_TRIGGER);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(GPIO_TRIGGER, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", GPIO_TRIGGER);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(GPIO_TRIGGER, [](unsigned gpio, unsigned level, uint32_t tick) {
        if (level == PI_TIMEOUT) {
            return;
        }

        int fd = i2cOpen(I2C_BUS, I2C_ADDR, 0);
        if (fd < 0) {
            fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
            return;
        }

        vl53l1x_soft_reset(fd);

        uint16_t distance = vl53l1x_read_distance(fd);
        if (distance == 0) {
            fprintf(stderr, "Failed to read distance from VL53L1X\n");
            i2cClose(fd);
            return;
        }

        printf("Distance: %d mm\n", distance);

        if (distance < DISTANCE_THRESHOLD_1) {
            motor_forward();
            printf("Motor: Forward\n");
        } else if (distance > DISTANCE_THRESHOLD_2) {
            motor_backward();
            printf("Motor: Backward\n");
        } else {
            motor_stop();
            printf("Motor: Stop\n");
        }

        i2cClose(fd);
    }) != 0) {
        fprintf(stderr, "Failed to set alert function on GPIO %d\n", GPIO_TRIGGER);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        sleep(1);
    }

    motor_stop();
    gpioTerminate();
    return EXIT_SUCCESS;
}

