#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define MPR121_I2C_ADDR 0x5A
#define MPR121_SOFT_RESET 0x80
#define MPR121_TOUCH_STATUS 0x00
#define MPR121_ELECTRODE_COUNT 12
#define LED_GPIO_CHIP "gpiochip0"
#define LED_GPIO_OFFSETS {17, 18, 27, 22}
#define LOG_FILE "proximity_log.txt"

static struct gpiod_chip *gpio_chip;
static int log_fd;

void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char buffer[80];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", tm_info);
    dprintf(log_fd, "%s: %s\n", buffer, event);
}

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        log_event("Received signal, shutting down...");
        gpiod_chip_close(gpio_chip);
        close(log_fd);
        exit(signum);
    }
}

int main() {
    struct gpiod_line *led_lines[4];
    uint8_t touch_status;
    int ret;

    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd == -1) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    // Initialize GPIO chip
    gpio_chip = gpiod_chip_open_by_name(LED_GPIO_CHIP);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        close(log_fd);
        return EXIT_FAILURE;
    }

    // Request LED lines
    for (int i = 0; i < 4; i++) {
        led_lines[i] = gpiod_chip_get_line(gpio_chip, LED_GPIO_OFFSETS[i]);
        if (!led_lines[i]) {
            perror("Failed to get LED line");
            gpiod_chip_close(gpio_chip);
            close(log_fd);
            return EXIT_FAILURE;
        }
        ret = gpiod_line_request_output(led_lines[i], "proximity_led", 0);
        if (ret < 0) {
            perror("Failed to request LED line output");
            gpiod_chip_close(gpio_chip);
            close(log_fd);
            return EXIT_FAILURE;
        }
    }

    // Soft reset MPR121
    uint8_t reset_cmd = MPR121_SOFT_RESET;
    ret = write(1, &reset_cmd, 1);
    if (ret != 1) {
        perror("Failed to write reset command to MPR121");
        for (int i = 0; i < 4; i++) {
            gpiod_line_release(led_lines[i]);
        }
        gpiod_chip_close(gpio_chip);
        close(log_fd);
        return EXIT_FAILURE;
    }

    // Verify sensor presence
    uint8_t status;
    ret = read(1, &status, 1);
    if (ret != 1) {
        perror("Failed to read status from MPR121");
        for (int i = 0; i < 4; i++) {
            gpiod_line_release(led_lines[i]);
        }
        gpiod_chip_close(gpio_chip);
        close(log_fd);
        return EXIT_FAILURE;
    }
    if (status != 0x00) {
        log_event("MPR121 sensor not present");
        for (int i = 0; i < 4; i++) {
            gpiod_line_release(led_lines[i]);
        }
        gpiod_chip_close(gpio_chip);
        close(log_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Read touch status
        ret = read(1, &touch_status, 1);
        if (ret != 1) {
            perror("Failed to read touch status from MPR121");
            for (int i = 0; i < 4; i++) {
                gpiod_line_release(led_lines[i]);
            }
            gpiod_chip_close(gpio_chip);
            close(log_fd);
            return EXIT_FAILURE;
        }

        // Check for proximity
        for (int i = 0; i < MPR121_ELECTRODE_COUNT; i++) {
            if (touch_status & (1 << i)) {
                log_event("Proximity detected on electrode ELE");
                for (int j = 0; j < 4; j++) {
                    gpiod_line_set_value(led_lines[j], (i & (1 << j)) ? 1 : 0);
                }
            } else {
                for (int j = 0; j < 4; j++) {
                    gpiod_line_set_value(led_lines[j], 0);
                }
            }
        }

        // Sleep for 50ms
        usleep(50000);
    }

    // Clean up
    for (int i = 0; i < 4; i++) {
        gpiod_line_release(led_lines[i]);
    }
    gpiod_chip_close(gpio_chip);
    close(log_fd);

    return EXIT_SUCCESS;
}

