This code measures distance using an HC-SR04 ultrasonic sensor connected to GPIO17 (trigger) and GPIO18 (echo) on a Raspberry Pi Zero W. It logs valid distance readings to a file named `distance_log.txt` with ISO 8601 UTC timestamps. The program handles errors, sensor-absent conditions, and timeouts. It also installs a SIGINT handler to clean up resources and exit gracefully when interrupted.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define TRIG_PIN 17
#define ECHO_PIN 18
#define LOG_FILE "distance_log.txt"
#define MIN_PULSE_WIDTH 58
#define MAX_PULSE_WIDTH 25000
#define TRIGGER_INTERVAL 1000000 // 1 second in microseconds

static struct gpiod_chip *chip;
static struct gpiod_line *trig_line, *echo_line;
static FILE *log_file;
static int running = 1;

void handle_sigint(int sig) {
    running = 0;
}

void echo_isr(const struct gpiod_line_event *event) {
    static struct timespec start_time = {0, 0};
    static int start = 0;

    if (event->event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
        if (clock_gettime(CLOCK_MONOTONIC, &start_time) == -1) {
            perror("clock_gettime");
            return;
        }
        start = 1;
    } else if (event->event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
        if (start) {
            struct timespec end_time;
            if (clock_gettime(CLOCK_MONOTONIC, &end_time) == -1) {
                perror("clock_gettime");
                return;
            }
            long long pulse_width = (end_time.tv_sec - start_time.tv_sec) * 1000000000LL +
                                   (end_time.tv_nsec - start_time.tv_nsec);
            if (pulse_width > MIN_PULSE_WIDTH && pulse_width < MAX_PULSE_WIDTH) {
                double distance = pulse_width * 0.034 / 2.0;
                time_t now = time(NULL);
                struct tm *tm_info = localtime(&now);
                char timestamp[20];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
                fprintf(log_file, "%s: Distance = %.2f meters\n", timestamp, distance);
                fflush(log_file);
            }
            start = 0;
        }
    }
}

int main() {
    struct gpiod_line_request_config config = {
        .consumer = "HC-SR04",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT,
        .default_val = 0,
    };

    if (signal(SIGINT, handle_sigint) == SIG_ERR ||
        signal(SIGTERM, handle_sigint) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    if (!trig_line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(trig_line, &config) < 0) {
        perror("gpiod_line_request");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    config.event_request_type = GPIOD_LINE_REQUEST_EVENT_BOTH_EDGES;

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("gpiod_chip_get_line");
        gpiod_line_release(trig_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(echo_line, &config) < 0) {
        perror("gpiod_line_request");
        gpiod_line_release(trig_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        gpiod_line_release(echo_line);
        gpiod_line_release(trig_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        if (gpiod_line_set_value(trig_line, 1) < 0) {
            perror("gpiod_line_set_value");
            break;
        }
        usleep(TRIGGER_INTERVAL);
        if (gpiod_line_set_value(trig_line, 0) < 0) {
            perror("gpiod_line_set_value");
            break;
        }
    }

    fclose(log_file);
    gpiod_line_release(echo_line);
    gpiod_line_release(trig_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

