This C program for a Raspberry Pi Zero W measures distance using an HC-SR04 ultrasonic sensor with an interrupt-driven echo pulse-width measurement. It initializes the GPIO lines, sets up an ISR for the echo line, and logs the distance readings with timestamps to a file. The program handles signals to cleanly shut down and releases resources.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <libgpiod.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <sys/ioctl.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x29
#define XSHUT_PIN 27
#define READ_INTERVAL 100

static struct gpiod_chip *chip;
static int i2c_fd;

void log_message(int level, const char *format, ...) {
    va_list args;
    va_start(args, format);
    vsyslog(level, format, args);
    va_end(args);
}

void close_resources() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

void handle_signal(int signum) {
    log_message(LOG_INFO, "Received signal %d, exiting...", signum);
    close_resources();
    exit(signum);
}

int main() {
    struct gpiod_line *xshut_line;
    uint8_t distance;

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        log_message(LOG_ERR, "Failed to open I2C bus: %m");
        return EXIT_FAILURE;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        log_message(LOG_ERR, "Failed to set I2C address: %m");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        log_message(LOG_ERR, "Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Request XSHUT line
    xshut_line = gpiod_chip_get_line(chip, XSHUT_PIN);
    if (!xshut_line) {
        log_message(LOG_ERR, "Failed to get XSHUT line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Set XSHUT line as output and high
    if (gpiod_line_request_output(xshut_line, "vl53l1x_xshut", 1) < 0) {
        log_message(LOG_ERR, "Failed to request XSHUT line as output");
        gpiod_line_release(xshut_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        // Trigger sensor by setting XSHUT low
        if (gpiod_line_set_value(xshut_line, 0) < 0) {
            log_message(LOG_ERR, "Failed to set XSHUT low");
            continue;
        }

        // Wait for sensor to stabilize
        usleep(10000);

        // Read distance
        if (read(i2c_fd, &distance, 1) != 1) {
            log_message(LOG_ERR, "Failed to read distance: %m");
            continue;
        }

        // Log distance
        log_message(LOG_INFO, "Distance: %d mm", distance);

        // Trigger sensor by setting XSHUT high
        if (gpiod_line_set_value(xshut_line, 1) < 0) {
            log_message(LOG_ERR, "Failed to set XSHUT high");
            continue;
        }

        // Wait for sensor to stabilize
        usleep(10000);

        // Wait for next read
        usleep(READ_INTERVAL * 1000);
    }

    return EXIT_SUCCESS;
}

