This program will continuously read the distance from the VL53L1X sensor and log the results to the systemd journal. It handles errors gracefully and ensures that resources are properly released on exit.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <sys/ioctl.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x29
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 24
#define LOG_FILE "gate_log.txt"
#define POLL_INTERVAL 100

struct gpiod_chip *chip;
struct gpiod_line *line;
int i2c_fd;
FILE *log_file;

void log_event(const char *event) {
    time_t now = time(NULL);
    fprintf(log_file, "%s: %s\n", ctime(&now), event);
    fflush(log_file);
}

void handle_sigint(int sig) {
    log_event("Received SIGINT/SIGTERM, shutting down...");
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(i2c_fd);
    fclose(log_file);
    exit(0);
}

int main() {
    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = POLL_INTERVAL * 1000 * 1000;

    // Open I2C bus
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize GPIO chip
    if ((chip = gpiod_chip_open_by_name(GPIO_CHIP)) == NULL) {
        perror("Failed to open GPIO chip");
        fclose(log_file);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Request GPIO line
    if ((line = gpiod_chip_get_line(chip, GPIO_LINE)) == NULL) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        fclose(log_file);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Configure GPIO line as output
    if (gpiod_line_request_output(line, "gate_control", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        fclose(log_file);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Set up signal handler
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    log_event("Gate control initialized, starting polling...");

    while (1) {
        uint16_t distance_mm;
        uint8_t buffer[2];

        // Read distance from sensor
        if (read(i2c_fd, buffer, 2) != 2) {
            perror("Failed to read distance from sensor");
            log_event("Sensor read error");
            continue;
        }

        distance_mm = (buffer[0] << 8) | buffer[1];
        float distance_cm = distance_mm / 10.0;

        // Log distance reading
        log_event(fprintf(log_file, "Distance: %.1f cm\n", distance_cm) < 0 ? "Log write error" : NULL);

        // Control gate actuator
        if (distance_cm < 20.0) {
            if (gpiod_line_set_value(line, 1) < 0) {
                perror("Failed to open gate");
                log_event("Gate open error");
            } else {
                log_event("Gate opened");
            }
        } else {
            if (gpiod_line_set_value(line, 0) < 0) {
                perror("Failed to close gate");
                log_event("Gate close error");
            } else {
                log_event("Gate closed");
            }
        }

        // Sleep for the specified interval
        nanosleep(&ts, NULL);
    }

    return EXIT_SUCCESS;
}

