#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18
#define SAMPLES 5
#define TIMEOUT_US 30000
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 400.0
#define PWM_FREQ 50

volatile sig_atomic_t stop_flag = 0;
volatile uint32_t pulse_width = 0;
volatile int new_pulse = 0;
FILE *log_file = NULL;

void signal_handler(int signum) {
    stop_flag = 1;
}

void distance_callback(struct gpiod_chip *chip, unsigned int offset, unsigned int event_type, void *user_data) {
    if (event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
        uint64_t start_time = gpiod_line_event_timestamp(chip, offset);
        while (gpiod_line_event_wait(chip, offset, TIMEOUT_US) == 0) {
            uint64_t end_time = gpiod_line_event_timestamp(chip, offset);
            pulse_width = (end_time - start_time) / 2;
            new_pulse = 1;
            break;
        }
    }
}

double calculate_distance(uint32_t pulse_width) {
    return pulse_width * 0.034 / 2;
}

void log_data(double distance, int angle) {
    if (log_file == NULL) {
        log_file = fopen("distance_log.csv", "w");
        if (log_file == NULL) {
            perror("Failed to open log file");
            return;
        }
        fprintf(log_file, "Timestamp,Distance (cm),Servo Angle (deg)\n");
    }
    fprintf(log_file, "%ld,%f,%d\n", time(NULL), distance, angle);
    fflush(log_file);
}

