#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <sys/ioctl.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x29
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define BUFFER_SIZE 10
#define MIN_DISTANCE 200

struct circular_buffer {
    int values[BUFFER_SIZE];
    int head;
    int count;
};

struct vl53l1x {
    int fd;
    struct circular_buffer buffer;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
};

void init_circular_buffer(struct circular_buffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

void circular_buffer_add(struct circular_buffer *cb, int value) {
    cb->values[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

int circular_buffer_get(struct circular_buffer *cb, int *values, int count) {
    if (count > cb->count) {
        count = cb->count;
    }
    for (int i = 0; i < count; i++) {
        values[i] = cb->values[(cb->head - i + BUFFER_SIZE) % BUFFER_SIZE];
    }
    return count;
}

void init_vl53l1x(struct vl53l1x *vl53) {
    vl53->fd = open("/dev/i2c-1", O_RDWR);
    if (vl53->fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(vl53->fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(vl53->fd);
        exit(EXIT_FAILURE);
    }

    // Initialize VL53L1X (STMicroelectronics sequence)
    // This is a placeholder for the actual initialization sequence
    // Refer to the VL53L1X datasheet for the correct sequence

    init_circular_buffer(&vl53->buffer);

    vl53->chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!vl53->chip) {
        perror("Failed to open GPIO chip");
        close(vl53->fd);
        exit(EXIT_FAILURE);
    }

    vl53->line = gpiod_chip_get_line(vl53->chip, GPIO_LINE);
    if (!vl53->line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(vl53->chip);
        close(vl53->fd);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(vl53->line, "vl53l1x_led", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(vl53->chip);
        close(vl53->fd);
        exit(EXIT_FAILURE);
    }
}

void read_distance(struct vl53l1x *vl53) {
    uint8_t data[10];
    if (read(vl53->fd, data, sizeof(data)) != sizeof(data)) {
        perror("Failed to read distance from VL53L1X");
        return;
    }

    // Parse the distance data (placeholder)
    int distance = (data[0] << 8) | data[1];

    circular_buffer_add(&vl53->buffer, distance);

    int values[BUFFER_SIZE];
    int count = circular_buffer_get(&vl53->buffer, values, BUFFER_SIZE);

    int sum = 0;
    for (int i = 0; i < count; i++) {
        sum += values[i];
    }

    int average = sum / count;

    if (average < MIN_DISTANCE) {
        gpiod_line_set_value(vl53->line, 1);
    } else {
        gpiod_line_set_value(vl53->line, 0);
    }
}

void cleanup(struct vl53l1x *vl53) {
    gpiod_line_release(vl53->line);
    gpiod_chip_close(vl53->chip);
    close(vl53->fd);
}

void sigint_handler(int signum) {
    struct vl53l1x vl53;
    cleanup(&vl53);
    exit(EXIT_SUCCESS);
}

int main() {
    struct vl53l1x vl53;
    init_vl53l1x(&vl53);

    signal(SIGINT, sigint_handler);

    while (1) {
        read_distance(&vl53);
        usleep(50000); // 50 ms
    }

    cleanup(&vl53);
    return 0;
}

