#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <libgpiod.h>
#include <pigpio.h>

#define SI1102_I2C_ADDRESS 0x29
#define SI1102_PROXIMITY_REG 0x24
#define SI1102_IRQ_REG 0x20
#define SI1102_IRQ_ENABLE_REG 0x21
#define SI1102_IRQ_MODE_REG 0x22
#define SI1102_IRQ_POLARITY_REG 0x23
#define SI1102_IRQ_ENABLE_BIT 0x01
#define SI1102_IRQ_MODE_BIT 0x01
#define SI1102_IRQ_POLARITY_BIT 0x01
#define SI1102_DEFAULT_THRESHOLD 1000
#define SI1102_I2C_BUS 1
#define SI1102_GPIO_PIN 27

static int i2c_fd = -1;
static FILE *log_file = NULL;
static int threshold = SI1102_DEFAULT_THRESHOLD;
static int running = 1;
static pthread_t gpio_thread;

static void log_proximity(int value) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s %d %s\n", timestamp, value, value <= threshold ? "SAFE" : "ALERT");
    fflush(log_file);
}

static void *gpio_thread_func(void *arg) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return NULL;
    }

    line = gpiod_chip_get_line(chip, SI1102_GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return NULL;
    }

    ret = gpiod_line_request_input(line, "proximity_sensor");
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line as input\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return NULL;
    }

    while (running) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Failed to read GPIO line\n");
            continue;
        }

        if (value) {
            int proximity_value;
            ret = i2c_read_word_data(i2c_fd, SI1102_PROXIMITY_REG, &proximity_value);
            if (ret < 0) {
                fprintf(stderr, "Failed to read proximity value from sensor\n");
                continue;
            }

            log_proximity(proximity_value);
        }

        usleep(100000); // Check every 100ms
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return NULL;
}

static void sigint_handler(int signum) {
    running = 0;
}

int main(int argc, char *argv[]) {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int i2c_address = SI1102_I2C_ADDRESS;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-t") == 0 && i + 1 < argc) {
            threshold = atoi(argv[i + 1]);
            i++;
        } else if (strcmp(argv[i], "-a") == 0 && i + 1 < argc) {
            i2c_address = strtol(argv[i + 1], NULL, 0);
            i++;
        } else {
            fprintf(stderr, "Usage: %s [-t <threshold>] [-a <i2c_address>]\n", argv[0]);
            return 1;
        }
    }

    i2c_fd = i2c_open(SI1102_I2C_BUS, i2c_address, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        return 1;
    }

    log_file = fopen("proximity.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2c_close(i2c_fd);
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        fclose(log_file);
        i2c_close(i2c_fd);
        return 1;
    }

    line = gpiod_chip_get_line(chip, SI1102_GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        fclose(log_file);
        i2c_close(i2c_fd);
        return 1;
    }

    ret = gpiod_line_request_output(line, "proximity_sensor", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line as output\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        fclose(log_file);
        i2c_close(i2c_fd);
        return 1;
    }

    ret = i2c_write_byte_data(i2c_fd, SI1102_IRQ_ENABLE_REG, SI1102_IRQ_ENABLE_BIT);
    if (ret < 0) {
        fprintf(stderr, "Failed to enable proximity interrupt\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        fclose(log_file);
        i2c_close(i2c_fd);
        return 1;
    }

    ret = i2c_write_byte_data(i2c_fd, SI1102_IRQ_MODE_REG, SI1102_IRQ_MODE_BIT);
    if (ret < 0) {
        fprintf(stderr, "Failed to set proximity interrupt mode\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        fclose(log_file);
        i2c_close(i2c_fd);
        return 1;
    }

    ret = i2c_write_byte_data(i2c_fd, SI1102_IRQ_POLARITY_REG, SI1102_IRQ_POLARITY_BIT);
    if (ret < 0) {
        fprintf(stderr, "Failed to set proximity interrupt polarity\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        fclose(log_file);
        i2c_close(i2c_fd);
        return 1;
    }

    ret = pthread_create(&gpio_thread, NULL, gpio_thread_func, NULL);
    if (ret != 0) {
        fprintf(stderr, "Failed to create GPIO thread\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        fclose(log_file);
        i2c_close(i2c_fd);
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (running) {
        sleep(1);
    }

    pthread_join(gpio_thread, NULL);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(log_file);
    i2c_close(i2c_fd);

    return 0;
}
