    gpiod_line_release(echo_line);
    gpiod_line_release(trigger_line);
    gpiod_chip_close(chip);
    exit(0);
}

static void init_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Failed to get trigger line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(trigger_line, "trigger", 0)) {
        perror("Failed to request trigger line");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Failed to get echo line");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(echo_line, "echo")) {
        perror("Failed to request echo line");
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    pwm_line = gpiod_chip_get_line(chip, PWM_PIN);
    if (!pwm_line) {
        perror("Failed to get PWM line");
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(pwm_line, "pwm", 0)) {
        perror("Failed to request PWM line");
        gpiod_line_release(pwm_line);
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
}

static void set_pwm_frequency(int frequency) {
    if (gpiod_line_set_value(pwm_line, 0)) {
        perror("Failed to set PWM line to low");
        return;
    }

    if (gpiod_line_request_pwm_output(pwm_line, "pwm", frequency, 50)) {
        perror("Failed to request PWM output");
        return;
    }

    current_frequency = frequency;
}

static int measure_distance() {
    if (gpiod_line_set_value(trigger_line, 1)) {
        perror("Failed to set trigger line to high");
        return -1;
    }

    usleep(10);

    if (gpiod_line_set_value(trigger_line, 0)) {
        perror("Failed to set trigger line to low");
        return -1;
    }

    struct timespec start, end;
    if (clock_gettime(CLOCK_MONOTONIC, &start)) {
        perror("Failed to get start time");
        return -1;
    }

    while (gpiod_line_get_value(echo_line) == 0) {
        if (clock_gettime(CLOCK_MONOTONIC, &end)) {
            perror("Failed to get end time");
            return -1;
        }

        if (timespec_sub(&end, &start) > TIMEOUT_US) {
            return -1;
        }
    }

    if (clock_gettime(CLOCK_MONOTONIC, &start)) {
        perror("Failed to get start time");
        return -1;
    }

    while (gpiod_line_get_value(echo_line) == 1) {
        if (clock_gettime(CLOCK_MONOTONIC, &end)) {
            perror("Failed to get end time");
            return -1;
        }

        if (timespec_sub(&end, &start) > TIMEOUT_US) {
            return -1;
        }
    }

    return timespec_sub(&end, &start) * 170 / 2;
}

static int timespec_sub(struct timespec *a, struct timespec *b) {
    return (a->tv_sec - b->tv_sec) * 1000000 + (a->tv_nsec - b->tv_nsec) / 1000;
}

int main() {
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    init_gpio();

    while (1) {
        int distance = measure_distance();
        if (distance < 0) {
            continue;
        }

        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            continue;
        }

        int frequency = MIN_FREQUENCY + (distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE);
        set_pwm_frequency(frequency);
    }

    return 0;
}

