#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define BUZZER_PIN 18
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define ECHO_TIMEOUT_US 100000
#define MIN_DISTANCE_CM 5
#define MAX_DISTANCE_CM 50
#define MIN_FREQUENCY_HZ 200
#define MAX_FREQUENCY_HZ 2000

static struct gpiod_chip *chip;
static struct gpiod_line *buzzer_line;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static int running = 1;

static void sigint_handler(int signum) {
    running = 0;
}

static void init_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        perror("Failed to get buzzer line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Failed to get trigger line");
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Failed to get echo line");
        gpiod_line_release(buzzer_line);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        perror("Failed to request buzzer line as output");
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(trigger_line, "trigger", 0) < 0) {
        perror("Failed to request trigger line as output");
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(echo_line, "echo") < 0) {
        perror("Failed to request echo line as input");
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
}

static void deinit_gpio() {
    gpiod_line_release(echo_line);
    gpiod_line_release(trigger_line);
    gpiod_line_release(buzzer_line);
    gpiod_chip_close(chip);
}

static void trigger_sensor() {
    if (gpiod_line_set_value(trigger_line, 0) < 0) {
        perror("Failed to set trigger line to low");
    }
    usleep(10);
    if (gpiod_line_set_value(trigger_line, 1) < 0) {
        perror("Failed to set trigger line to high");
    }
    usleep(10);
    if (gpiod_line_set_value(trigger_line, 0) < 0) {
        perror("Failed to set trigger line to low");
    }
}

static int read_echo() {
    struct timespec start, end;
    int echo_state = 0;
    int duration_us = 0;

    if (gpiod_line_get_value(echo_line, &echo_state) < 0) {
        perror("Failed to read echo line");
        return -1;
    }

    if (echo_state == 0) {
        if (clock_gettime(CLOCK_MONOTONIC, &start) < 0) {
            perror("Failed to get start time");
            return -1;
        }
        while (echo_state == 0) {
            if (gpiod_line_get_value(echo_line, &echo_state) < 0) {
                perror("Failed to read echo line");
                return -1;
            }
            if (clock_gettime(CLOCK_MONOTONIC, &end) < 0) {
                perror("Failed to get end time");
                return -1;
            }
            if (timespec_sub(&end, &start, &end) < 0) {
                perror("Failed to subtract times");
                return -1;
            }
            duration_us = (end.tv_sec * 1000000) + (end.tv_nsec / 1000);
            if (duration_us > ECHO_TIMEOUT_US) {
                return -1;
            }
        }
        if (clock_gettime(CLOCK_MONOTONIC, &start) < 0) {
            perror("Failed to get start time");
            return -1;
        }
        while (echo_state == 1) {
            if (gpiod_line_get_value(echo_line, &echo_state) < 0) {
                perror("Failed to read echo line");
                return -1;
            }
            if (clock_gettime(CLOCK_MONOTONIC, &end) < 0) {
                perror("Failed to get end time");
                return -1;
            }
            if (timespec_sub(&end, &start, &end) < 0) {
                perror("Failed to subtract times");
                return -1;
            }
            duration_us = (end.tv_sec * 1000000) + (end.tv_nsec / 1000);
            if (duration_us > ECHO_TIMEOUT_US) {
                return -1;
            }
        }
    }

    return duration_us;
}

static void generate_tone(int frequency) {
    if (gpiod_line_set_value(buzzer_line, 1) < 0) {
        perror("Failed to set buzzer line to high");
    }
    usleep(1000000 / frequency);
    if (gpiod_line_set_value(buzzer_line, 0) < 0) {
        perror("Failed to set buzzer line to low");
    }
}

int main() {
    int distance_cm = 0;
    int frequency_hz = 0;

    signal(SIGINT, sigint_handler);

    init_gpio();

    while (running) {
        trigger_sensor();
        int duration_us = read_echo();
        if (duration_us >= 0) {
            distance_cm = (duration_us * 0.034 / 2) * 100;
            if (distance_cm < MIN_DISTANCE_CM) {
                distance_cm = MIN_DISTANCE_CM;
            } else if (distance_cm > MAX_DISTANCE_CM) {
                distance_cm = MAX_DISTANCE_CM;
            }
            frequency_hz = (int)((MAX_FREQUENCY_HZ - MIN_FREQUENCY_HZ) * (distance_cm - MIN_DISTANCE_CM) / (MAX_DISTANCE_CM - MIN_DISTANCE_CM) + MIN_FREQUENCY_HZ);
            generate_tone(frequency_hz);
        } else {
            printf("Echo timeout or read error, using last valid distance\n");
        }
        printf("Distance: %d cm, Frequency: %d Hz\n", distance_cm, frequency_hz);
        usleep(10000);
