#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define TRIGGER_PIN "gpiochip0:line17"
#define ECHO_PIN "gpiochip0:line18"
#define TIMEOUT_US 50000
#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0
#define MIN_WARNING_DISTANCE_CM 10.0

volatile sig_atomic_t stop_flag = 0;

void sigint_handler(int signum) {
    stop_flag = 1;
}

double measure_distance(struct gpiod_chip *chip, struct gpiod_line *trigger, struct gpiod_line *echo) {
    struct timespec start, end;
    long long duration_us;

    // Trigger the sensor
    gpiod_line_set_value(trigger, 1);
    nanosleep((struct timespec){0, 10}, NULL); // 10 µs pulse
    gpiod_line_set_value(trigger, 0);

    // Wait for the echo to start
    if (gpiod_line_event_wait(echo, &start, TIMEOUT_US) <= 0) {
        return -1; // Timeout
    }

    // Wait for the echo to end
    if (gpiod_line_event_wait(echo, &end, TIMEOUT_US) <= 0) {
        return -1; // Timeout
    }

    // Calculate the duration
    duration_us = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;

    // Convert to distance (speed of sound is approximately 343 m/s)
    return duration_us * 0.0343 / 2.0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *trigger, *echo;
    int ret;

    // Initialize the GPIO library
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Get the trigger line
    trigger = gpiod_chip_get_line(chip, 17);
    if (!trigger) {
        perror("Failed to get trigger line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Get the echo line
    echo = gpiod_chip_get_line(chip, 18);
    if (!echo) {
        perror("Failed to get echo line");
        gpiod_line_release(trigger);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure the trigger line as output
    ret = gpiod_line_request_output(trigger, "distance_sensor_trigger", 0);
    if (ret < 0) {
        perror("Failed to request trigger line as output");
        gpiod_line_release(echo);
        gpiod_line_release(trigger);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure the echo line as input
    ret = gpiod_line_request_input(echo, "distance_sensor_echo");
    if (ret < 0) {
        perror("Failed to request echo line as input");
        gpiod_line_release(trigger);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Install the SIGINT handler
    signal(SIGINT, sigint_handler);

    while (!stop_flag) {
        double distance = measure_distance(chip, trigger, echo);

        if (distance == -1) {
            printf("Timeout\n");
        } else if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
            printf("Invalid reading\n");
        } else {
            printf("Distance: %.2f cm", distance);
            if (distance < MIN_WARNING_DISTANCE_CM) {
                printf(" Too close!\n");
            } else {
                printf("\n");
            }
        }

        nanosleep((struct timespec){0, 500000000}, NULL); // 500 ms delay
    }

    // Release resources
    gpiod_line_release(echo);
    gpiod_line_release(trigger);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

