#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 8
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define MIN_DISTANCE 200
#define MAX_DISTANCE 5000
#define LOG_FILE "distance_log.csv"

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static int spi_fd;
static FILE *log_file;

void close_resources() {
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
}

void handle_sigint(int sig) {
    close_resources();
    exit(0);
}

int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = 8,
        .cs_change = 0,
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI_IOC_MESSAGE");
        return -1;
    }
    return 0;
}

int read_distance() {
    uint8_t tx[2] = {0x00, 0x00};
    uint8_t rx[2];
    if (spi_transfer(tx, rx, sizeof(rx)) < 0) {
        return -1;
    }
    int distance = (rx[0] << 8) | rx[1];
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        return -1;
    }
    return distance;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(line, "cs", 0) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open");
        gpiod_chip_close(chip);
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("SPI_IOC_WR_MODE");
        close(spi_fd);
        gpiod_chip_close(chip);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        close(spi_fd);
        gpiod_chip_close(chip);
        return 1;
    }

    while (1) {
        gpiod_line_set_value(line, 0);
        int distance = read_distance();
        gpiod_line_set_value(line, 1);
        if (distance >= 0) {
            time_t now = time(NULL);
            fprintf(log_file, "%ld,%d\n", now, distance);
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }
        fflush(log_file);
        sleep(1);
    }

    close_resources();
    return 0;
}

