#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SI1182_I2C_ADDRESS 0x60
#define SI1182_PART_ID_REG 0x00
#define SI1182_MEAS_RATE_REG 0x01
#define SI1182_ALS_DATA_REG 0x12
#define SI1182_PROX_DATA_REG 0x26

#define SI1182_PART_ID 0x42

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    int i2c_fd, log_fd;
    struct timespec ts;
    FILE *log_file = NULL;
    uint8_t part_id, meas_rate[2];
    uint16_t lux, proximity;

    // Open I2C device
    if ((i2c_fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SI1182_I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    if ((log_fd = open("biometric_log.txt", O_WRONLY | O_CREAT | O_APPEND, 0644)) < 0) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open log file stream
    if ((log_file = fdopen(log_fd, "a")) == NULL) {
        perror("Failed to open log file stream");
        close(i2c_fd);
        close(log_fd);
        return EXIT_FAILURE;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Verify sensor by reading part ID
    if (read(i2c_fd, &part_id, 1) != 1) {
        perror("Failed to read part ID");
        goto cleanup;
    }

    if (part_id != SI1182_PART_ID) {
        fprintf(stderr, "Sensor part ID mismatch: 0x%02X (expected 0x%02X)\n", part_id, SI1182_PART_ID);
        goto cleanup;
    }

    // Configure measurement rate
    meas_rate[0] = 0x00; // ALS integration time
    meas_rate[1] = 0x00; // Proximity integration time
    if (write(i2c_fd, meas_rate, 2) != 2) {
        perror("Failed to write measurement rate");
        goto cleanup;
    }

    // Main loop
    while (running) {
        // Read ambient light (lux)
        if (read(i2c_fd, &lux, 2) != 2) {
            perror("Failed to read lux");
            goto cleanup;
        }

        // Read proximity data
        if (read(i2c_fd, &proximity, 2) != 2) {
            perror("Failed to read proximity");
            goto cleanup;
        }

        // Get current timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
            perror("Failed to get current time");
            goto cleanup;
        }

        // Log and print the reading
        fprintf(log_file, "%ld.%03ld,%u,%u\n", ts.tv_sec, ts.tv_nsec / 1000000, lux, proximity);
        fprintf(stdout, "%ld.%03ld,%u,%u\n", ts.tv_sec, ts.tv_nsec / 1000000, lux, proximity);

        // Sleep for 100 ms
        usleep(100000);
    }

cleanup:
    // Close log file stream
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Close log file descriptor
    if (log_fd >= 0) {
        close(log_fd);
    }

    // Close I2C file descriptor
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    return EXIT_SUCCESS;
}

