        if (read(i2c_fd, &proximity, 2) != 2) {
            perror("Failed to read proximity");
            goto cleanup;
        }

        // Get current timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
            perror("Failed to get current time");
            goto cleanup;
        }

        // Log and print the reading
        fprintf(log_file, "%ld.%03ld,%u,%u\n", ts.tv_sec, ts.tv_nsec / 1000000, lux, proximity);
        fprintf(stdout, "%ld.%03ld,%u,%u\n", ts.tv_sec, ts.tv_nsec / 1000000, lux, proximity);

        // Sleep for 100 ms
        usleep(100000);
    }

cleanup:
    // Close log file stream
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Close log file descriptor
    if (log_fd >= 0) {
        close(log_fd);
    }

    // Close I2C file descriptor
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    return EXIT_SUCCESS;
}
```

This C program interfaces with a Silicon Labs Si1182-A-GM optical sensor over I2C using the `/dev/i2c-1` device on a Raspberry Pi 3 Model B+. It verifies the sensor by reading its part ID register and configuring the measurement rate register to the documented values. The program continuously reads ambient light (lux) and proximity data every 100 ms, logging each timestamped reading to a CSV file named `biometric_log.txt` and printing the same line to stdout. It checks every I2C read and write for errors, handles sensor absence when the part ID read fails, reports I2C bus errors such as NACK with appropriate messages, and includes SIGINT and SIGTERM handlers that close the I2C file descriptor and the log file so that all resources are released on normal and error exits.

