#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define TRIGGER_PIN "gpiochip0:offset=17"
#define ECHO_PIN "gpiochip0:offset=18"
#define BUZZER_PIN "gpiochip0:offset=27"
#define TRIGGER_PULSE_US 10
#define MIN_DISTANCE_CM 20

static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line, *echo_line, *buzzer_line;
static int running = 1;

static void sigint_handler(int signum) {
    running = 0;
}

static void echo_callback(struct gpiod_line_event *event) {
    static struct timespec start_time = {0, 0};
    static int edge = 0;

    if (event->event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
        if (clock_gettime(CLOCK_MONOTONIC, &start_time) == -1) {
            perror("clock_gettime");
            exit(EXIT_FAILURE);
        }
        edge = 1;
    } else if (event->event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
        struct timespec end_time;
        if (clock_gettime(CLOCK_MONOTONIC, &end_time) == -1) {
            perror("clock_gettime");
            exit(EXIT_FAILURE);
        }
        long long duration_ns = (end_time.tv_sec - start_time.tv_sec) * 1000000000LL +
                               (end_time.tv_nsec - start_time.tv_nsec);
        double distance_cm = (duration_ns * 0.034 / 2) / 1000000.0;
        printf("Distance: %.2f cm\n", distance_cm);

        if (distance_cm < MIN_DISTANCE_CM) {
            gpiod_line_set_value(buzzer_line, 1);
        } else {
            gpiod_line_set_value(buzzer_line, 0);
        }
    }
}

int main() {
    struct gpiod_line_request_config trigger_config = {
        .consumer = "trigger",
        .request_type = GPIOD_LINE_REQUEST_OUTPUT,
        .default_val = 0,
    };

    struct gpiod_line_request_config echo_config = {
        .consumer = "echo",
        .request_type = GPIOD_LINE_REQUEST_INPUT,
        .default_val = 0,
    };

    struct gpiod_line_request_config buzzer_config = {
        .consumer = "buzzer",
        .request_type = GPIOD_LINE_REQUEST_OUTPUT,
        .default_val = 0,
    };

    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trigger_line = gpiod_chip_get_line(chip, 17);
    if (!trigger_line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(trigger_line, &trigger_config) < 0) {
        perror("gpiod_line_request");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    echo_line = gpiod_chip_get_line(chip, 18);
    if (!echo_line) {
        perror("gpiod_chip_get_line");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(echo_line, &echo_config) < 0) {
        perror("gpiod_line_request");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    buzzer_line = gpiod_chip_get_line(chip, 27);
    if (!buzzer_line) {
        perror("gpiod_chip_get_line");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(buzzer_line, &buzzer_config) < 0) {
        perror("gpiod_line_request");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_event_wait(echo_line, 1000000) < 0) {
        perror("gpiod_line_event_wait");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_event_read(echo_line, &echo_callback) < 0) {
        perror("gpiod_line_event_read");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        struct timespec trigger_time;
        if (clock_gettime(CLOCK_MONOTONIC, &trigger_time) == -1) {
            perror("clock_gettime");
            break;
        }

        trigger_time.tv_nsec += TRIGGER_PULSE_US * 1000;
        if (trigger_time.tv_nsec >= 1000000000) {
            trigger_time.tv_sec++;
            trigger_time.tv_nsec -= 1000000000;
        }

        if (gpiod_line_set_value(trigger_line, 1) < 0) {
            perror("gpiod_line_set_value");
            break;
        }

        if (gpiod_line_set_value(trigger_line, 0) < 0) {
            perror("gpiod_line_set_value");
            break;
        }

        sleep(1);
    }

    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    gpiod_line_release(buzzer_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

