#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18
#define MIN_DISTANCE 20
#define MAX_DISTANCE 200
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define SERVO_RANGE 180

volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

double measure_distance(struct gpiod_chip *chip, int trigger_pin, int echo_pin) {
    struct gpiod_line *trigger_line = gpiod_chip_get_line(chip, trigger_pin);
    struct gpiod_line *echo_line = gpiod_chip_get_line(chip, echo_pin);

    if (!trigger_line || !echo_line) {
        perror("Failed to get GPIO line");
        return -1.0;
    }

    if (gpiod_line_request_output(trigger_line, "trigger", 0) < 0) {
        perror("Failed to request trigger line");
        return -1.0;
    }

    if (gpiod_line_request_input(echo_line, "echo") < 0) {
        perror("Failed to request echo line");
        gpiod_line_release(trigger_line);
        return -1.0;
    }

    gpiod_line_set_value(trigger_line, 0);
    usleep(10);
    gpiod_line_set_value(trigger_line, 1);
    usleep(10);
    gpiod_line_set_value(trigger_line, 0);

    struct gpiod_line_event event;
    if (gpiod_line_event_wait(echo_line, &event, 100000) < 0) {
        perror("Failed to wait for echo event");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        return -1.0;
    }

    if (event.event_type != GPIOD_LINE_EVENT_RISING_EDGE) {
        perror("Unexpected event type");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        return -1.0;
    }

    uint64_t start_time = event.timestamp.tv_sec * 1000000 + event.timestamp.tv_nsec / 1000;

    if (gpiod_line_event_wait(echo_line, &event, 100000) < 0) {
        perror("Failed to wait for echo event");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        return -1.0;
    }

    if (event.event_type != GPIOD_LINE_EVENT_FALLING_EDGE) {
        perror("Unexpected event type");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        return -1.0;
    }

    uint64_t end_time = event.timestamp.tv_sec * 1000000 + event.timestamp.tv_nsec / 1000;

    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);

    double duration = (end_time - start_time) / 1000.0;
    return duration * 0.034 / 2.0;
}

void set_servo_angle(struct gpiod_chip *chip, int servo_pin, int angle) {
    struct gpiod_line *servo_line = gpiod_chip_get_line(chip, servo_pin);

    if (!servo_line) {
        perror("Failed to get GPIO line");
        return;
    }

    if (gpiod_line_request_output(servo_line, "servo", 0) < 0) {
        perror("Failed to request servo line");
        return;
    }

    int pulse_width = MIN_PULSE_WIDTH + (angle * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH)) / SERVO_RANGE;
    gpiod_line_set_value(servo_line, 1);
    usleep(pulse_width);
    gpiod_line_set_value(servo_line, 0);
    usleep(20000 - pulse_width);

    gpiod_line_release(servo_line);
}

int main() {
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    while (running) {
        double distance = measure_distance(chip, TRIGGER_PIN, ECHO_PIN);
        if (distance < 0) {
            printf("Distance measurement failed\n");
            continue;
        }

        int angle = (distance - MIN_DISTANCE) * (SERVO_RANGE / (MAX_DISTANCE - MIN_DISTANCE));
        if (angle < 0) {
            angle = 0;
        } else if (angle > SERVO_RANGE) {
            angle = SERVO_RANGE;
        }

        set_servo_angle(chip, SERVO_PIN, angle);

        printf("Distance: %.2f cm, Servo Angle: %d°\n", distance, angle);
        usleep(100000);
    }

    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

