#include <libgpiod.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define MODEL_ID_REG 0x00
#define MODEL_ID 0xE5
#define TIMING_BUDGET_REG 0x04
#define TIMING_BUDGET 10000
#define DISTANCE_REG 0x14
#define SERVO_PIN 18
#define SERVO_MIN 1000
#define SERVO_MAX 2000
#define Hysteresis 50
#define LOG_FILE "gate_log.txt"

static int i2c_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

void handle_sigint(int sig) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    if (line != NULL) {
        gpiod_line_release(line);
    }
    exit(0);
}

void log_event(const char *event) {
    if (log_file != NULL) {
        time_t now = time(NULL);
        fprintf(log_file, "%s: %s\n", ctime(&now), event);
        fflush(log_file);
    }
}

int main() {
    signal(SIGINT, handle_sigint);

    // Initialize I2C
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return 1;
    }

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        close(i2c_fd);
        return 1;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        close(i2c_fd);
        return 1;
    }

    // Initialize PWM
    if (gpioSetPWMfrequency(SERVO_PIN, 50) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        close(i2c_fd);
        return 1;
    }

    // Initialize log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        close(i2c_fd);
        return 1;
    }

    // Verify model ID
    uint8_t model_id;
    if (read(i2c_fd, &model_id, sizeof(model_id)) != sizeof(model_id)) {
        perror("Failed to read model ID");
        gpioTerminate();
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    if (model_id != MODEL_ID) {
        fprintf(stderr, "Incorrect model ID: 0x%02X\n", model_id);
