#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 400.0
#define MIN_ANGLE 0.0
#define MAX_ANGLE 180.0
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define TIMEOUT_US 50000
#define TRIGGER_PULSE_US 10
#define MEASUREMENT_INTERVAL_MS 100

static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static struct gpiod_line *servo_line;

void cleanup_and_exit(int status) {
    if (servo_line) {
        gpiod_line_set_value(servo_line, 0);
        gpiod_line_release(servo_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(status);
}

void sigint_handler(int signum) {
    cleanup_and_exit(0);
}

double measure_distance() {
    struct timespec start, end;
    long long duration_us;

    if (gpiod_line_set_value(trigger_line, 1) < 0) {
        perror("Failed to set trigger line high");
        return -1.0;
    }
    if (nanosleep(&(struct timespec){0, TRIGGER_PULSE_US * 1000}, NULL) < 0) {
        perror("Failed to sleep for trigger pulse");
        return -1.0;
    }
    if (gpiod_line_set_value(trigger_line, 0) < 0) {
        perror("Failed to set trigger line low");
        return -1.0;
    }

    if (gpiod_line_request_rising_edge_events(echo_line, "echo_rising") < 0) {
        perror("Failed to request rising edge events on echo line");
        return -1.0;
    }
    if (gpiod_line_request_falling_edge_events(echo_line, "echo_falling") < 0) {
        perror("Failed to request falling edge events on echo line");
        return -1.0;
    }

    if (clock_gettime(CLOCK_MONOTONIC, &start) < 0) {
        perror("Failed to get start time");
        return -1.0;
    }

    while (1) {
        struct gpiod_line_event event;
        if (gpiod_line_event_wait(echo_line, &event, TIMEOUT_US) < 0) {
            perror("Failed to wait for echo event");
            return -1.0;
        }
        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            if (clock_gettime(CLOCK_MONOTONIC, &start) < 0) {
                perror("Failed to get start time");
                return -1.0;
            }
        } else if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            if (clock_gettime(CLOCK_MONOTONIC, &end) < 0) {
                perror("Failed to get end time");
                return -1.0;
            }
            break;
        }
    }

    if (gpiod_line_release(echo_line) < 0) {
        perror("Failed to release echo line");
        return -1.0;
    }

    duration_us = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
    return duration_us * 0.034 / 2.0;
}

double map_distance_to_angle(double distance) {
    if (distance < MIN_DISTANCE) {
        return MIN_ANGLE;
    } else if (distance > MAX_DISTANCE) {
        return MAX_ANGLE;
    } else {
        return MIN_ANGLE + (distance - MIN_DISTANCE) * (MAX_ANGLE - MIN_ANGLE) / (MAX_DISTANCE - MIN_DISTANCE);
    }
}

void set_servo_angle(double angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Invalid angle: %.2f\n", angle);
        return;
    }

    int pulse_width = MIN_PULSE_WIDTH + (angle - MIN_ANGLE) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) / (MAX_ANGLE - MIN_ANGLE);
    if (gpiod_line_set_value(servo_line, 1) < 0) {
        perror("Failed to set servo line high");
        return;
    }
    if (nanosleep(&(struct timespec){0, pulse_width * 1000}, NULL) < 0) {
        perror("Failed to sleep for pulse width");
        return;
    }
    if (gpiod_line_set_value(servo_line, 0) < 0) {
        perror("Failed to set servo line low");
        return;
    }
}

int main() {
    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        perror("Failed to set SIGINT handler");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Failed to get trigger line");
        cleanup_and_exit(EXIT_FAILURE);
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Failed to get echo line");
        cleanup_and_exit(EXIT_FAILURE);
    }

    servo_line = gpiod_chip_get_line(chip, SERVO_PIN);
    if (!servo_line) {
        perror("Failed to get servo line");
        cleanup_and_exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(servo_line, "servo", 0) < 0) {
        perror("Failed to request output on servo line");
        cleanup_and_exit(EXIT_FAILURE);
    }

    while (1) {
        double distance = measure_distance();
        if (distance < 0) {
            printf("Distance measurement failed\n");
        } else {
            double angle = map_distance_to_angle(distance);
            set_servo_angle(angle);
            printf("Distance: %.2f cm, Angle: %.2f degrees\n", distance, angle);
        }

        if (nanosleep(&(struct timespec){MEASUREMENT_INTERVAL_MS / 1000, (MEASUREMENT_INTERVAL_MS % 1000) * 1000000}, NULL) < 0) {
            perror("Failed to sleep for measurement interval");
            cleanup_and_exit(EXIT_FAILURE);
        }
    }

    cleanup_and_exit(EXIT_SUCCESS);
}

