    if (gpiod_line_release(echo_line) < 0) {
        perror("Failed to release echo line");
        return -1.0;
    }

    duration_us = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
    return duration_us * 0.034 / 2.0;
}

double map_distance_to_angle(double distance) {
    if (distance < MIN_DISTANCE) {
        return MIN_ANGLE;
    } else if (distance > MAX_DISTANCE) {
        return MAX_ANGLE;
    } else {
        return MIN_ANGLE + (distance - MIN_DISTANCE) * (MAX_ANGLE - MIN_ANGLE) / (MAX_DISTANCE - MIN_DISTANCE);
    }
}

void set_servo_angle(double angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Invalid angle: %.2f\n", angle);
        return;
    }

    int pulse_width = MIN_PULSE_WIDTH + (angle - MIN_ANGLE) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) / (MAX_ANGLE - MIN_ANGLE);
    if (gpiod_line_set_value(servo_line, 1) < 0) {
        perror("Failed to set servo line high");
        return;
    }
    if (nanosleep(&(struct timespec){0, pulse_width * 1000}, NULL) < 0) {
        perror("Failed to sleep for pulse width");
        return;
    }
    if (gpiod_line_set_value(servo_line, 0) < 0) {
        perror("Failed to set servo line low");
        return;
    }
}

int main() {
    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        perror("Failed to set SIGINT handler");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Failed to get trigger line");
        cleanup_and_exit(EXIT_FAILURE);
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Failed to get echo line");
        cleanup_and_exit(EXIT_FAILURE);
    }

    servo_line = gpiod_chip_get_line(chip, SERVO_PIN);
    if (!servo_line) {
        perror("Failed to get servo line");
        cleanup_and_exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(servo_line, "servo", 0) < 0) {
        perror("Failed to request output on servo line");
        cleanup_and_exit(EXIT_FAILURE);
    }

    while (1) {
        double distance = measure_distance();
        if (distance < 0) {
            printf("Distance measurement failed\n");
        } else {
            double angle = map_distance_to_angle(distance);
            set_servo_angle(angle);
            printf("Distance: %.2f cm, Angle: %.2f degrees\n", distance, angle);
        }

        if (nanosleep(&(struct timespec){MEASUREMENT_INTERVAL_MS / 1000, (MEASUREMENT_INTERVAL_MS % 1000) * 1000000}, NULL) < 0) {
            perror("Failed to sleep for measurement interval");
            cleanup_and_exit(EXIT_FAILURE);
        }
    }

    cleanup_and_exit(EXIT_SUCCESS);
}
