#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define SI7005_I2C_BUS 1
#define SI7005_I2C_ADDR 0x40
#define SI7005_CONFIG_REG 0xF3
#define SI7005_TEMP_REG 0xF5
#define SI7005_READ_DELAY 10000  // 10 ms in microseconds
#define LOG_INTERVAL 2000000     // 2 seconds in microseconds

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static int i2c_fd;

void handle_sigint(int sig) {
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(0);
}

int main() {
    struct gpiod_line_request config;
    struct gpiod_line_request read;
    uint8_t config_data[1] = {SI7005_CONFIG_REG};
    uint8_t read_data[2];
    int ret;

    // Register signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    // Initialize libgpiod
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request control of the I2C line
    ret = gpiod_chip_get_line(chip, 0);  // Assuming line 0 is used for I2C
    if (ret < 0) {
        perror("Failed to get I2C line");
        close(i2c_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    line = (struct gpiod_line *)ret;

    // Configure the I2C line for output
    ret = gpiod_line_request_output(line, "si7005_i2c", 0);
    if (ret < 0) {
        perror("Failed to request I2C line as output");
        gpiod_line_release(line);
        close(i2c_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        // Write CONFIG register
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("Failed to set I2C line high");
            gpiod_line_release(line);
            close(i2c_fd);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
        usleep(SI7005_READ_DELAY);

        // Write register address to be read
        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("Failed to set I2C line low");
            gpiod_line_release(line);
            close(i2c_fd);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
        ret = write(i2c_fd, SI7005_TEMP_REG, 1);
        if (ret < 0) {
            perror("Failed to write register address");
            gpiod_line_release(line);
            close(i2c_fd);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
        usleep(SI7005_READ_DELAY);

        // Read temperature data
        ret = read(i2c_fd, read_data, 2);
        if (ret < 0) {
            perror("Failed to read temperature data");
            gpiod_line_release(line);
            close(i2c_fd);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        // Convert temperature data to float
        float temperature = (read_data[0] << 8) | read_data[1];
        temperature = -46.85 + 175.72 * (temperature / 65536.0);

        // Log temperature to console
        printf("Temperature: %.2f°C\n", temperature);

        // Wait for 2 seconds before next read
        usleep(LOG_INTERVAL);
    }

    // Clean up
    gpiod_line_release(line);
    close(i2c_fd);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

