#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x68
#define WHO_AM_I_REG 0x75
#define ACCEL_XOUT_H_REG 0x3B
#define GYRO_XOUT_H_REG 0x43
#define TEMP_OUT_H_REG 0x41

struct gpiod_chip *chip;
struct gpiod_line *sda, *scl;
int i2c_fd;

void cleanup(int signum) {
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    printf("Program terminated.\n");
    exit(signum);
}

int read_i2c_register(int fd, uint8_t reg, uint8_t *value) {
    uint8_t buf[1] = {reg};
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

int read_i2c_data(int fd, uint8_t start_reg, uint8_t *data, size_t len) {
    uint8_t buf[1] = {start_reg};
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

int main() {
    uint8_t who_am_i;
    uint8_t data[14];
    int16_t accel_x, accel_y, accel_z, temp, gyro_x, gyro_y, gyro_z;

    // Initialize GPIO for I2C
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    sda = gpiod_chip_get_line(chip, 2);
    if (!sda) {
        perror("Failed to get SDA line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    scl = gpiod_chip_get_line(chip, 3);
    if (!scl) {
        perror("Failed to get SCL line");
        gpiod_line_release(sda);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(sda, "i2c_sda", 0) < 0) {
        perror("Failed to request SDA line as output");
        gpiod_line_release(sda);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(scl, "i2c_scl", 0) < 0) {
        perror("Failed to request SCL line as output");
        gpiod_line_release(sda);
        gpiod_line_release(scl);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initialize I2C
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        gpiod_line_release(sda);
        gpiod_line_release(scl);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        gpiod_line_release(sda);
        gpiod_line_release(scl);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Verify sensor is present
    if (read_i2c_register(i2c_fd, WHO_AM_I_REG, &who_am_i) < 0) {
        close(i2c_fd);
        gpiod_line_release(sda);
        gpiod_line_release(scl);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (who_am_i != 0x68) {
        fprintf(stderr, "Sensor not found, WHO_AM_I = 0x%02X\n", who_am_i);
        close(i2c_fd);
        gpiod_line_release(sda);
        gpiod_line_release(scl);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("MPU-6050 sensor detected.\n");

    // Register signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Main loop
    while (1) {
        if (read_i2c_data(i2c_fd, ACCEL_XOUT_H_REG, data, 14) < 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            continue;
        }

        accel_x = (data[0] << 8) | data[1];
        accel_y = (data[2] << 8) | data[3];
        accel_z = (data[4] << 8) | data[5];
        temp = (data[6] << 8) | data[7];
        gyro_x = (data[8] << 8) | data[9];
        gyro_y = (data[10] << 8) | data[11];
        gyro_z = (data[12] << 8) | data[13];

        printf("Accel: X=%d, Y=%d, Z=%d, Temp=%d, Gyro: X=%d, Y=%d, Z=%d\n",
               accel_x, accel_y, accel_z, temp, gyro_x, gyro_y, gyro_z);

        usleep(100000); // 100 ms
    }

    return EXIT_SUCCESS;
}

