#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define SHT40_I2C_ADDRESS 0x60
#define SHT40_MEAS_HIGH_REP_STRETCH_CMD 0x2416
#define SHT40_CRC8_POLYNOMIAL 0x31
#define SHT40_CRC8_INITIAL 0xFF

static struct gpiod_chip *chip;
static struct gpiod_line *i2c_line;
static int i2c_fd;

static void handle_sigint(int sig) {
    printf("Received signal %d, shutting down...\n", sig);
    gpiod_chip_close(chip);
    exit(0);
}

static uint8_t crc8(const uint8_t *data, size_t length) {
    uint8_t crc = SHT40_CRC8_INITIAL;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SHT40_CRC8_POLYNOMIAL;
            } else {
                crc = crc << 1;
            }
        }
    }
    return crc;
}

static int read_sht40_temperature_humidity() {
    uint8_t cmd[2] = {SHT40_MEAS_HIGH_REP_STRETCH_CMD >> 8, SHT40_MEAS_HIGH_REP_STRETCH_CMD & 0xFF};
    if (write(i2c_fd, cmd, sizeof(cmd)) != sizeof(cmd)) {
        perror("Failed to write to SHT40");
        return -1;
    }

    usleep(10000); // Wait at least 10 ms

    uint8_t response[6];
    if (read(i2c_fd, response, sizeof(response)) != sizeof(response)) {
