#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SENSOR_ADDRESS 0x5A
#define LOG_FILE "temperature_log.csv"

static int i2c_fd = -1;
static FILE *log_file = NULL;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

void handle_sigint(int sig) {
    cleanup();
    exit(0);
}

int read_sensor_temperature(int fd, float *temperature) {
    uint8_t buffer[3];
    if (read(fd, buffer, sizeof(buffer)) != sizeof(buffer)) {
        perror("Failed to read from sensor");
        return -1;
    }
    *temperature = (buffer[0] << 8 | buffer[1]) * 0.02;
    return 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct timespec ts;
    char timestamp[20];
    float ambient_temp, object_temp;

    // Initialize I2C
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Register signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    while (1) {
        // Read ambient temperature
        if (read_sensor_temperature(i2c_fd, &ambient_temp) < 0) {
            fprintf(stderr, "Failed to read ambient temperature\n");
            continue;
        }

        // Read object temperature
        if (read_sensor_temperature(i2c_fd, &object_temp) < 0) {
            fprintf(stderr, "Failed to read object temperature\n");
            continue;
        }

        // Get current timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
            perror("Failed to get current time");
            continue;
        }
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        // Write to log file
        fprintf(log_file, "%s,%f,%f\n", timestamp, ambient_temp, object_temp);
        fflush(log_file);

        // Sleep for 5 seconds
        sleep(5);
    }

    cleanup();
    return EXIT_SUCCESS;
}

