#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x44
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"
#define SAMPLE_INTERVAL 5

static struct gpiod_chip *chip;
static FILE *log_file;
static FILE *error_log_file;

void cleanup() {
    if (log_file) fclose(log_file);
    if (error_log_file) fclose(error_log_file);
    if (chip) gpiod_chip_close(chip);
    exit(0);
}

void handle_signal(int sig) {
    cleanup();
}

int main() {
    struct gpiod_line *line;
    struct timespec ts;
    uint8_t buffer[6];
    int ret;

    // Open the I2C bus
    chip = gpiod_chip_open_by_name("gpiochip1");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open the error log file
    error_log_file = fopen(ERROR_LOG_FILE, "a");
    if (!error_log_file) {
        perror("Failed to open error log file");
        fclose(log_file);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Register signal handler
    signal(SIGINT, handle_signal);

    while (1) {
        // Read temperature from STS30-DIS sensor
        ret = gpiod_chip_i2c_read(chip, I2C_ADDRESS, buffer, sizeof(buffer));
        if (ret != sizeof(buffer)) {
            fprintf(error_log_file, "I2C read failed: %s\n", strerror(errno));
            continue;
        }

        // Parse temperature from buffer
        uint16_t temp_msb = buffer[0];
        uint16_t temp_lsb = buffer[1];
        float temperature = (temp_msb << 8 | temp_lsb) * 0.0025;

        // Get current timestamp
        clock_gettime(CLOCK_REALTIME, &ts);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        // Write timestamp and temperature to log file
        fprintf(log_file, "%s, %.2f\n", timestamp, temperature);
        fflush(log_file);

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

