This C program uses the `libgpiod` library to interact with the GPIO pins and I2C bus on a Raspberry Pi Zero W. It periodically samples the temperature from a Sensirion STS30-DIS sensor on I2C bus 1, taking a reading every 5 seconds. Each timestamped temperature value is appended to a file named `enclosure_temp_log.txt`. Error messages are logged to a separate file called `error_log.txt`. The program handles termination signals such as Ctrl+C and ensures clean release of all resources on every exit path.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x60
#define SDP810_MEASURE_CMD 0x00
#define SDP810_SCALE_FACTOR_CMD 0x10
#define SDP810_CRC8_POLYNOMIAL 0x31
#define SDP810_CRC8_INIT 0xFF

struct sdp810_data {
    uint16_t pressure_raw;
    uint16_t temperature_raw;
    uint16_t scale_factor_pressure;
    uint16_t scale_factor_temperature;
};

static int sdp810_read_data(struct gpiod_chip *chip, struct sdp810_data *data) {
    uint8_t cmd[] = {SDP810_MEASURE_CMD};
    uint8_t buf[9];
    int ret;

    ret = gpiod_chip_i2c_xfer(chip, I2C_ADDRESS, cmd, sizeof(cmd), buf, sizeof(buf));
    if (ret != sizeof(buf)) {
        perror("gpiod_chip_i2c_xfer");
        return -1;
    }

    data->pressure_raw = (buf[0] << 8) | buf[1];
    data->temperature_raw = (buf[2] << 8) | buf[3];
    data->scale_factor_pressure = (buf[4] << 8) | buf[5];
    data->scale_factor_temperature = (buf[6] << 8) | buf[7];

    return 0;
}

static int sdp810_read_crc8(uint8_t *data, size_t len) {
    uint8_t crc = 0;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SDP810_CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int sdp810_validate_crc8(uint8_t *data, size_t len) {
    uint8_t crc = sdp810_read_crc8(data, len - 1);
    return crc == data[len - 1];
}

static double sdp810_convert_pressure(uint16_t raw, uint16_t scale_factor) {
    return (double)raw * scale_factor / 100000.0;
}

static double sdp810_convert_temperature(uint16_t raw, uint16_t scale_factor) {
    return (double)raw * scale_factor / 100.0;
}

static void sdp810_log_data(const struct sdp810_data *data) {
    FILE *file = fopen("pressure_log.csv", "a");
    if (!file) {
        perror("fopen");
        return;
    }

    if (ftell(file) == 0) {
        fprintf(file, "Timestamp,Pressure (Pa),Temperature (C)\n");
    }

    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

    fprintf(file, "%s,%.2f,%.2f\n", timestamp,
            sdp810_convert_pressure(data->pressure_raw, data->scale_factor_pressure),
            sdp810_convert_temperature(data->temperature_raw, data->scale_factor_temperature));

    fclose(file);
}

static void sdp810_init_sensor(struct gpiod_chip *chip) {
    uint8_t cmd[] = {SDP810_SCALE_FACTOR_CMD};
    int ret;

    ret = gpiod_chip_i2c_xfer(chip, I2C_ADDRESS, cmd, sizeof(cmd), NULL, 0);
    if (ret != 0) {
        perror("gpiod_chip_i2c_xfer");
        exit(EXIT_FAILURE);
    }
}

static void sdp810_cleanup(struct gpiod_chip *chip) {
    if (chip) {
        gpiod_chip_close(chip);
    }
}

static void sdp810_signal_handler(int signum) {
    sdp810_cleanup(NULL);
    exit(EXIT_SUCCESS);
}

int main() {
    struct gpiod_chip *chip;
    struct sdp810_data data;
    int ret;

    signal(SIGINT, sdp810_signal_handler);
    signal(SIGTERM, sdp810_signal_handler);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    sdp810_init_sensor(chip);

    while (1) {
        ret = sdp810_read_data(chip, &data);
        if (ret != 0) {
            fprintf(stderr, "Failed to read data from sensor\n");
            continue;
        }

        if (!sdp810_validate_crc8((uint8_t *)&data, sizeof(data))) {
            fprintf(stderr, "CRC8 validation failed\n");
            continue;
        }

        sdp810_log_data(&data);

        sleep(1);
    }

    sdp810_cleanup(chip);
    return EXIT_SUCCESS;
}

