#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define SHT40_I2C_ADDRESS 0x44
#define SHT40_MEAS_HIGH_REP 0x2400
#define SHT40_CRC8_POLYNOMIAL 0x31
#define SHT40_CRC8_INITIAL 0xFF

int i2c_fd = -1;
FILE *log_file = NULL;

void handle_sigint(int sig) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = SHT40_CRC8_INITIAL;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SHT40_CRC8_POLYNOMIAL;
            } else {
                crc = crc << 1;
            }
        }
    }
    return crc;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SHT40_I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen("sht40_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    uint8_t command[2] = {SHT40_MEAS_HIGH_REP >> 8, SHT40_MEAS_HIGH_REP & 0xFF};
    while (1) {
        if (write(i2c_fd, command, sizeof(command)) != sizeof(command)) {
            perror("Failed to write to I2C device");
            continue;
        }

        usleep(10000); // Wait at least 10 ms

        uint8_t data[6];
        if (read(i2c_fd, data, sizeof(data)) != sizeof(data)) {
            perror("Failed to read from I2C device");
            continue;
        }

        uint8_t crc8_temp = calculate_crc8(data, 2);
        uint8_t crc8_humidity = calculate_crc8(data + 3, 2);

        if (crc8_temp != data[2] || crc8_humidity != data[5]) {
            fprintf(stderr, "CRC error in data\n");
            continue;
        }

        int16_t temp_raw = (data[0] << 8) | data[1];
        int16_t humidity_raw = (data[3] << 8) | data[4];

        float temperature = -45.0 + 175.0 * temp_raw / 65535.0;
        float humidity = -6.0 + 125.0 * humidity_raw / 65535.0;

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s Temperature: %.2f°C, Humidity: %.2f%%\n", timestamp, temperature, humidity);
        fflush(log_file);

        sleep(5);
    }

    close(i2c_fd);
    fclose(log_file);
    return 0;
}

