This C program interfaces with a Sensirion SHT40 humidity and temperature sensor over the I2C bus 1 on a Raspberry Pi 3 Model B+. It issues the high-repeatability measurement command, waits for the measurement to complete, reads the 6-byte result, validates the data using the CRC-8 algorithm, and logs the timestamped temperature and humidity values to a file named `sht40_log.txt` every 5 seconds. The program handles errors from opening the I2C device, ioctl calls, writes, and reads by logging an error and retrying on the next cycle. It also cleans up resources when receiving SIGINT or SIGTERM.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x60
#define SDP31_TRIGGER_CMD 0x21
#define SDP31_READ_CMD 0x22
#define SDP31_DATA_SIZE 6
#define SAMPLE_INTERVAL_MS 100
#define MAX_RETRIES 3
#define BACKOFF_FACTOR 2

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

int i2c_write_retry(int fd, const uint8_t *data, size_t len) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (gpiod_line_set_value(fd, data, len) == 0) {
            return 0;
        }
        retries++;
        usleep(retries * BACKOFF_FACTOR * 1000);
    }
    return -1;
}

int i2c_read_retry(int fd, uint8_t *data, size_t len) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (gpiod_line_get_value(fd, data, len) == 0) {
            return 0;
        }
        retries++;
        usleep(retries * BACKOFF_FACTOR * 1000);
    }
    return -1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int i2c_fd;
    FILE *log_file;
    uint8_t write_data[1] = {SDP31_TRIGGER_CMD};
    uint8_t read_data[SDP31_DATA_SIZE];
    uint32_t pressure_raw, temperature_raw;
    double pressure_pa, temperature_c;
    struct timespec ts;

    // Initialize signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, 2); // Assuming I2C bus 1 is connected to GPIO2
    if (!line) {
        perror("Failed to get I2C line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "i2c_bus_1", 0) < 0) {
        perror("Failed to request I2C line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    i2c_fd = gpiod_line_get_value(line);
    if (i2c_fd < 0) {
        perror("Failed to get I2C file descriptor");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("airflow.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (!stop_flag) {
        // Trigger measurement
        if (i2c_write_retry(i2c_fd, write_data, sizeof(write_data)) < 0) {
            perror("Failed to trigger measurement");
            continue;
        }

        // Wait at least 1 ms
        usleep(1000);

        // Read data
        if (i2c_read_retry(i2c_fd, read_data, sizeof(read_data)) < 0) {
            perror("Failed to read data");
            continue;
        }

        // Convert data to pressure and temperature
        pressure_raw = (read_data[0] << 16) | (read_data[1] << 8) | read_data[2];
        temperature_raw = (read_data[3] << 8) | read_data[4];
        pressure_pa = (double)pressure_raw * 0.01;
        temperature_c = (double)temperature_raw * 0.01;

        // Get current timestamp
        clock_gettime(CLOCK_REALTIME, &ts);

        // Write to log file
        fprintf(log_file, "%ld.%09ld,%f,%f\n", ts.tv_sec, ts.tv_nsec, pressure_pa, temperature_c);
        fflush(log_file);
    }

    // Cleanup
    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

