#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SDP800_ADDRESS 0x28
#define TRIGGER_CMD 0x00
#define READ_CMD 0x01
#define CRC8_POLYNOMIAL 0x31

volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = 0;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    int fd;
    if ((fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SDP800_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(fd);
        return EXIT_FAILURE;
    }

    if (write(fd, &TRIGGER_CMD, 1) != 1) {
        perror("Failed to trigger measurement");
        close(fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    FILE *log_file = fopen("airflow_data.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        close(fd);
        return EXIT_FAILURE;
    }

    fprintf(log_file, "Timestamp,Pressure (Pa),Temperature (C)\n");

    while (running) {
        uint8_t buffer[9];
        if (write(fd, &READ_CMD, 1) != 1) {
            perror("Failed to read data");
            break;
        }

        if (read(fd, buffer, 9) != 9) {
            perror("Failed to read data");
            break;
        }

        uint8_t crc8 = calculate_crc8(buffer, 8);
        if (crc8 != buffer[8]) {
            fprintf(stderr, "CRC error\n");
            continue;
        }

        uint32_t pressure_raw = (buffer[0] << 16) | (buffer[1] << 8) | buffer[2];
        uint32_t temperature_raw = (buffer[3] << 16) | (buffer[4] << 8) | buffer[5];
        uint32_t scale_factor_raw = (buffer[6] << 16) | (buffer[7] << 8) | buffer[8];

        double pressure = pressure_raw * 0.01;
        double temperature = temperature_raw * 0.01;

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);

        usleep(100000); // 100 ms
    }

    fclose(log_file);
    close(fd);
    return EXIT_SUCCESS;
}

