#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x44
#define MEASUREMENT_COMMAND 0x21
#define MEASUREMENT_DELAY 15
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL 0xFF

#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"

static struct gpiod_chip *chip;
static FILE *log_file;
static FILE *error_log_file;

void log_error(const char *message) {
    time_t now = time(NULL);
    fprintf(error_log_file, "%s: %s\n", ctime(&now), message);
    fflush(error_log_file);
}

void log_temperature(double temperature) {
    time_t now = time(NULL);
    fprintf(log_file, "%s: %.2f\n", ctime(&now), temperature);
    fflush(log_file);
}

void handle_sigint(int sig) {
    if (log_file) fclose(log_file);
    if (error_log_file) fclose(error_log_file);
    if (chip) gpiod_chip_close(chip);
    exit(0);
}

int calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = CRC8_INITIAL;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    signal(SIGINT, handle_sigint);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        log_error("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        log_error("Failed to open log file");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    error_log_file = fopen(ERROR_LOG_FILE, "a");
    if (!error_log_file) {
        log_error("Failed to open error log file");
        fclose(log_file);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    uint8_t command[1] = {MEASUREMENT_COMMAND};
    uint8_t response[3];

    while (1) {
        int ret = gpiod_chip_i2c_write(chip, I2C_ADDRESS, command, sizeof(command));
        if (ret < 0) {
            log_error("I2C write failed");
            continue;
        }

        usleep(MEASUREMENT_DELAY * 1000);

        ret = gpiod_chip_i2c_read(chip, I2C_ADDRESS, response, sizeof(response));
        if (ret < 0) {
            log_error("I2C read failed");
            continue;
        }

        uint8_t crc = calculate_crc8(response, 2);
        if (crc != response[2]) {
            log_error("CRC mismatch");
            continue;
        }

        double temperature = (response[0] << 8) | response[1];
        temperature = temperature * 0.01;

        log_temperature(temperature);
    }

    fclose(log_file);
    fclose(error_log_file);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

