#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define SHT40_I2C_ADDRESS 0x44
#define SHT40_MEAS_HIGH_REP 0x2400
#define SHT40_CRC_POLYNOMIAL 0x31
#define SHT40_CRC_INITIAL 0xFF

int i2c_fd = -1;
FILE *log_file = NULL;

void close_resources() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

void handle_sigint(int sig) {
    close_resources();
    exit(0);
}

uint8_t calculate_crc(uint8_t *data, size_t length) {
    uint8_t crc = SHT40_CRC_INITIAL;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SHT40_CRC_POLYNOMIAL;
            } else {
                crc = crc << 1;
            }
        }
    }
    return crc;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
