#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SENSOR_ADDRESS 0x28
#define MEASURE_CMD 0x00
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL 0xFF

volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = CRC8_INITIAL;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int fd;
    FILE *log_file;
    uint8_t buffer[6];
    uint16_t pressure_raw, temperature_raw;
    float pressure, temperature;
    struct timespec ts;

    // Open I2C device
    if ((fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(fd, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return EXIT_FAILURE;
    }

    // Open log file
    if ((log_file = fopen("airflow_data.txt", "a")) == NULL) {
        perror("Failed to open log file");
        close(fd);
        return EXIT_FAILURE;
    }

    // Register signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    while (running) {
        // Start measurement
        if (write(fd, &MEASURE_CMD, 1) != 1) {
            perror("Failed to send measurement command");
            break;
        }

        // Wait for measurement to complete (at least 1 ms)
        usleep(1000);

        // Read 6 bytes from sensor
        if (read(fd, buffer, 6) != 6) {
            perror("Failed to read from sensor");
            break;
        }

        // Validate CRC8 for pressure and temperature
        uint8_t crc8_pressure = calculate_crc8(buffer, 4);
        uint8_t crc8_temperature = calculate_crc8(buffer + 4, 2);
        if (crc8_pressure != buffer[4] || crc8_temperature != buffer[5]) {
            fprintf(stderr, "CRC8 check failed\n");
            continue;
        }

        // Convert raw data to pressure and temperature
        pressure_raw = (buffer[0] << 8) | buffer[1];
        temperature_raw = (buffer[3] << 8) | buffer[4];
        pressure = (pressure_raw * 0.01) - 50000;
        temperature = (temperature_raw * 0.01) - 40;

        // Get current timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("Failed to get current time");
            break;
        }

        // Write data to log file
        fprintf(log_file, "%ld.%09ld,%f,%f\n", ts.tv_sec, ts.tv_nsec, pressure, temperature);
        fflush(log_file);
    }

    // Clean up resources
    fclose(log_file);
    close(fd);

    return EXIT_SUCCESS;
}

