#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x40
#define FAN_PIN 18
#define TEMP_HYSTERESIS 1.0
#define TEMP_THRESHOLD_ON 28.0
#define TEMP_THRESHOLD_OFF 27.0
#define BUFFER_SIZE 60
#define RETRY_COUNT 3

struct Reading {
    time_t timestamp;
    float temperature;
};

struct Reading buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_full = 0;
struct gpiod_chip *chip = NULL;
struct gpiod_line *fan_line = NULL;

void handle_sigint(int sig) {
    if (fan_line) {
        gpiod_line_set_value(fan_line, 0);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

int read_temperature() {
    int retries = RETRY_COUNT;
    uint8_t cmd[1] = {0xF3}; // Command to read temperature
    uint8_t data[2];
    int ret;

    while (retries--) {
        ret = gpiod_chip_i2c_xfer(chip, I2C_ADDRESS, cmd, 1, data, 2);
        if (ret == 2) {
            break;
        }
        usleep(10000); // Wait 10ms before retrying
    }

    if (ret != 2) {
        return -1;
    }

    // Convert 14-bit temperature value to Celsius
    int16_t temp_raw = (data[0] << 8) | data[1];
    float temperature = -46.85 + 175.72 * (temp_raw / 65536.0);
    return temperature;
}

void update_fan_state(float temperature) {
    static float last_temperature = 0.0;
    if (temperature > TEMP_THRESHOLD_ON && temperature >= last_temperature + TEMP_HYSTERESIS) {
        gpiod_line_set_value(fan_line, 1);
    } else if (temperature < TEMP_THRESHOLD_OFF && temperature <= last_temperature - TEMP_HYSTERESIS) {
        gpiod_line_set_value(fan_line, 0);
    }
    last_temperature = temperature;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    fan_line = gpiod_chip_get_line(chip, FAN_PIN);
    if (!fan_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    int ret = gpiod_line_request_output(fan_line, "fan_control", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        return 1;
    }

    while (1) {
        float temperature = read_temperature();
        if (temperature == -1) {
            printf("Sensor absent or communication error\n");
            sleep(2);
            continue;
        }

        time_t now = time(NULL);
        buffer[buffer_index].timestamp = now;
        buffer[buffer_index].temperature = temperature;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        buffer_full = buffer_index == 0;

        printf("Timestamp: %s, Temperature: %.2f°C\n", ctime(&now), temperature);

        update_fan_state(temperature);

        sleep(2);
    }

    return 0;
}

