static void handle_sigint(int sig) {
    if (sig == SIGINT) {
        if (i2c_fd >= 0) {
            if (write(i2c_fd, (const uint8_t *)&SCD40_STOP_CONTINUOUS_MEASUREMENT, 2) != 2) {
                perror("Failed to stop continuous measurement");
            }
            close(i2c_fd);
        }
        if (chip) {
            gpiod_chip_close(chip);
        }
        if (log_file) {
            fclose(log_file);
        }
        exit(EXIT_SUCCESS);
    }
}

static uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = SCD40_CRC8_INIT;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SCD40_CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

