#define SCD40_CRC8_POLYNOMIAL 0x31
#define SCD40_CRC8_INIT 0xFF

struct sensor_data {
    uint16_t co2_ppm;
    int16_t temperature;
    uint16_t humidity;
};

static int i2c_fd;
static struct gpiod_chip *chip;
static FILE *log_file;

static void handle_sigint(int sig) {
    if (sig == SIGINT) {
        if (i2c_fd >= 0) {
            if (write(i2c_fd, (const uint8_t *)&SCD40_STOP_CONTINUOUS_MEASUREMENT, 2) != 2) {
                perror("Failed to stop continuous measurement");
            }
            close(i2c_fd);
        }
        if (chip) {
            gpiod_chip_close(chip);
        }
        if (log_file) {
            fclose(log_file);
        }
        exit(EXIT_SUCCESS);
    }
}

static uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = SCD40_CRC8_INIT;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SCD40_CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int read_sensor_data(struct sensor_data *data) {
    uint8_t buffer[9];
    if (read(i2c_fd, buffer, sizeof(buffer)) != sizeof(buffer)) {
        perror("Failed to read sensor data");
        return -1;
    }

    if (buffer[8] != calculate_crc8(buffer, 8)) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    data->co2_ppm = (buffer[0] << 8) | buffer[1];
    data->temperature = (buffer[3] << 8) | buffer[4];
    data->humidity = (buffer[6] << 8) | buffer[7];

    return 0;
}

