    nanosleep((const struct timespec[]){{1, 0}}, NULL);

    while (1) {
        // Wait for data ready flag
        if (read(i2c_fd, &ts.tv_sec, sizeof(ts.tv_sec)) != sizeof(ts.tv_sec)) {
            perror("Failed to read timestamp");
            continue;
