#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <gpiod.h>

#define SCD40_I2C_BUS 1
#define SCD40_I2C_ADDRESS 0x61
#define SCD40_MEASURE_CONTINUOUSLY 0x2166
#define SCD40_READ_MEASUREMENT 0xEC05
#define SCD40_STOP_MEASUREMENT 0x2164
#define SCD40_CRC8_POLYNOMIAL 0x31
#define BUFFER_SIZE 20
#define LED_PIN 17

struct Reading {
    uint16_t co2;
    float temperature;
    float humidity;
};

struct CircularBuffer {
    struct Reading buffer[BUFFER_SIZE];
    int head;
    int count;
};

struct CircularBuffer cb;
struct gpiod_chip *chip;
struct gpiod_line *led_line;

void init_sensor() {
    int ret;
    uint8_t cmd[2] = {SCD40_MEASURE_CONTINUOUSLY, 0x00};
    ret = gpiod_line_request_output(led_line, "co2_led", 0);
    if (ret < 0) {
        perror("Failed to request LED line");
        exit(EXIT_FAILURE);
    }
    ret = gpiod_chip_write_i2c(chip, SCD40_I2C_ADDRESS, cmd, sizeof(cmd));
    if (ret < 0) {
        perror("Failed to start measurement");
        exit(EXIT_FAILURE);
    }
}

void read_sensor(struct Reading *reading) {
    int ret;
    uint8_t cmd[2] = {SCD40_READ_MEASUREMENT, 0x00};
    uint8_t data[9];
    ret = gpiod_chip_write_i2c(chip, SCD40_I2C_ADDRESS, cmd, sizeof(cmd));
    if (ret < 0) {
        perror("Failed to read measurement");
        return;
    }
    ret = gpiod_chip_read_i2c(chip, SCD40_I2C_ADDRESS, data, sizeof(data));
    if (ret < 0) {
        perror("Failed to read measurement data");
        return;
    }
    if (data[0] != 0x00 || data[1] != 0x00) {
        fprintf(stderr, "Invalid data header\n");
        return;
    }
    reading->co2 = (data[2] << 8) | data[3];
    reading->temperature = ((data[4] << 8) | data[5]) / 100.0;
    reading->humidity = ((data[6] << 8) | data[7]) / 100.0;
    if (!validate_crc8(data, 8)) {
        fprintf(stderr, "CRC8 checksum failed\n");
        return;
    }
}

int validate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = 0;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SCD40_CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc == 0;
}

void add_to_buffer(const struct Reading *reading) {
    cb.buffer[cb.head] = *reading;
    cb.head = (cb.head + 1) % BUFFER_SIZE;
    if (cb.count < BUFFER_SIZE) {
        cb.count++;
    }
}

void print_buffer() {
    for (int i = 0; i < cb.count; i++) {
        int index = (cb.head - i + BUFFER_SIZE) % BUFFER_SIZE;
        printf("CO2: %d ppm, Temperature: %.2f C, Humidity: %.2f%%\n",
               cb.buffer[index].co2, cb.buffer[index].temperature, cb.buffer[index].humidity);
    }
}

void handle_sigint(int sig) {
    int ret;
    ret = gpiod_chip_write_i2c(chip, SCD40_I2C_ADDRESS, (uint8_t[]){SCD40_STOP_MEASUREMENT, 0x00}, 2);
    if (ret < 0) {
        perror("Failed to stop measurement");
    }
    ret = gpiod_line_release(led_line);
    if (ret < 0) {
        perror("Failed to release LED line");
    }
    ret = gpiod_chip_close(chip);
    if (ret < 0) {
        perror("Failed to close I2C chip");
    }
    exit(EXIT_SUCCESS);
}

int main() {
    int ret;
    struct Reading reading;

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get LED line");
        exit(EXIT_FAILURE);
    }

    init_sensor();

    while (1) {
        read_sensor(&reading);
        if (reading.co2 > 1000) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }
        add_to_buffer(&reading);
        print_buffer();
        sleep(5);
    }

    return 0;
}

