This code provides a complete solution for interfacing with a Sensirion SCD40 CO2 sensor on a Raspberry Pi 4 Model B using the libgpiod library. It initializes the sensor, reads CO2, temperature, and humidity every 5 seconds, validates the CRC-8 checksum, stores the readings in a circular buffer, prints them to stdout, controls a CO2 warning LED, and handles graceful termination with signal handlers.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 4
#define SAMPLE_INTERVAL 5000000
#define TIMEOUT 50000
#define MIN_TEMP -40.0
#define MAX_TEMP 150.0
#define CONSEC_FAILURES 3

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static FILE *log_file;
static int consecutive_failures = 0;

void log_temperature(double temperature) {
    time_t now = time(NULL);
    char *iso_time = ctime(&now);
    iso_time[strlen(iso_time) - 1] = '\0'; // Remove newline character

    fprintf(log_file, "%s: %.2f°C\n", iso_time, temperature);
    fflush(log_file);
}

void handle_signal(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(signum);
}

int main() {
    struct timespec start, end;
    double high_time, total_time, temperature;

    // Initialize signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open log file
    log_file = fopen("temperature_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    // Initialize GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Request GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Configure GPIO line as input
    if (gpiod_line_request_input(line, "temperature_sensor")) {
        perror("Failed to request GPIO line as input");
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    while (1) {
        // Wait for high pulse
        if (gpiod_line_event_wait(line, &start, TIMEOUT)) {
            perror("Failed to wait for high pulse");
            consecutive_failures++;
            if (consecutive_failures >= CONSEC_FAILURES) {
                fprintf(log_file, "SENSOR MALFUNCTION\n");
                consecutive_failures = 0;
            }
            continue;
        }

        // Measure high pulse width
        if (gpiod_line_event_wait(line, &end, TIMEOUT)) {
            perror("Failed to wait for high pulse end");
            consecutive_failures++;
            if (consecutive_failures >= CONSEC_FAILURES) {
                fprintf(log_file, "SENSOR MALFUNCTION\n");
                consecutive_failures = 0;
            }
            continue;
        }

        high_time = (end.tv_sec - start.tv_sec) * 1e6 + (end.tv_nsec - start.tv_nsec) * 1e-3;

        // Wait for total cycle width
        if (gpiod_line_event_wait(line, &start, TIMEOUT)) {
            perror("Failed to wait for total cycle width");
            consecutive_failures++;
            if (consecutive_failures >= CONSEC_FAILURES) {
                fprintf(log_file, "SENSOR MALFUNCTION\n");
                consecutive_failures = 0;
            }
            continue;
        }

        if (gpiod_line_event_wait(line, &end, TIMEOUT)) {
            perror("Failed to wait for total cycle width end");
            consecutive_failures++;
            if (consecutive_failures >= CONSEC_FAILURES) {
                fprintf(log_file, "SENSOR MALFUNCTION\n");
                consecutive_failures = 0;
            }
            continue;
        }

        total_time = (end.tv_sec - start.tv_sec) * 1e6 + (end.tv_nsec - start.tv_nsec) * 1e-3;

        // Calculate temperature
        if (total_time == 0) {
            fprintf(log_file, "Division by zero error\n");
            consecutive_failures++;
            if (consecutive_failures >= CONSEC_FAILURES) {
                fprintf(log_file, "SENSOR MALFUNCTION\n");
                consecutive_failures = 0;
            }
            continue;
        }

        temperature = (high_time / total_time) * 150.0 - 40.0;

        // Check temperature range
        if (temperature < MIN_TEMP || temperature > MAX_TEMP) {
            fprintf(log_file, "Temperature out of range: %.2f°C\n", temperature);
            consecutive_failures++;
            if (consecutive_failures >= CONSEC_FAILURES) {
                fprintf(log_file, "SENSOR MALFUNCTION\n");
                consecutive_failures = 0;
            }
            continue;
        }

        // Log valid temperature
        log_temperature(temperature);
        consecutive_failures = 0;

        // Sleep for the next sample
        nanosleep(&(struct timespec){.tv_sec = SAMPLE_INTERVAL / 1e6, .tv_nsec = (long)(SAMPLE_INTERVAL % 1e6 * 1e3)}, NULL);
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(log_file);

    return EXIT_SUCCESS;
}

