#define SHT35_I2C_ADDRESS 0x44
#define SHT35_MEAS_HIGH_REP_STRETCH_DISABLE 0x2C06
#define SHT35_CRC8_POLYNOMIAL 0x31
#define SHT35_LOG_INTERVAL 5
#define SHT35_MAX_RETRIES 3
#define SHT35_TEMP_OFFSET 2.0
#define SHT35_HUM_OFFSET 5.0
#define SHT35_TEMP_SCALE 175.72
#define SHT35_TEMP_OFFSET_CONST 42.5
#define SHT35_HUM_SCALE 65536.0
#define SHT35_HUM_OFFSET_CONST 0.0

static struct gpiod_chip *chip;
static int i2c_fd;
static FILE *log_file;
static int running = 1;

void signal_handler(int signum) {
    running = 0;
}

uint8_t crc8(const uint8_t *data, size_t length) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SHT35_CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_sht35(uint16_t *temperature, uint16_t *humidity) {
    uint8_t buffer[6];
    int retries = 0;
    while (retries < SHT35_MAX_RETRIES) {
        if (write(i2c_fd, &SHT35_MEAS_HIGH_REP_STRETCH_DISABLE, 2) != 2) {
            perror("write");
            retries++;
            sleep(1);
            continue;
        }
        usleep(15000);
        if (read(i2c_fd, buffer, 6) != 6) {
            perror("read");
            retries++;
            sleep(1);
            continue;
        }
        if (buffer[2] != crc8(buffer, 2) || buffer[5] != crc8(buffer + 3, 2)) {
            retries++;
            sleep(1);
            continue;
        }
        *temperature = (buffer[0] << 8) | buffer[1];
        *humidity = (buffer[3] << 8) | buffer[4];
        return 0;
    }
    return -1;
}

void log_data(uint16_t temperature, uint16_t humidity) {
    if (log_file == NULL) {
        log_file = fopen("environmental_data.txt", "a");
        if (log_file == NULL) {
            perror("fopen");
            return;
        }
    }
    time_t now = time(NULL);
    struct tm *tm = gmtime(&now);
    fprintf(log_file, "%04d-%02d-%02dT%02d:%02d:%02dZ %.2f %.2f\n",
            tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
            tm->tm_hour, tm->tm_min, tm->tm_sec,
            (temperature * SHT35_TEMP_SCALE / SHT35_TEMP_SCALE_CONST) + SHT35_TEMP_OFFSET,
            (humidity * SHT35_HUM_SCALE / SHT35_HUM_SCALE_CONST) + SHT35_HUM_OFFSET);
    fflush(log_file);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SHT35_I2C_ADDRESS) < 0) {
        perror("ioctl");
        close(i2c_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        uint16_t temperature, humidity;
        if (read_sht35(&temperature, &humidity) == 0) {
            log_data(temperature, humidity);
        } else {
            log_data(0, 0);
        }
        sleep(SHT35_LOG_INTERVAL);
    }

    close(i2c_fd);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

