#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x50
#define SDP810_MEASUREMENT_CMD 0x00
#define SDP810_CRC_POLYNOMIAL 0x31
#define SDP810_CRC_INITIAL 0xFF

struct sdp810_data {
    uint32_t pressure;
    int16_t temperature;
    uint8_t scale_factor;
};

static int i2c_fd = -1;
static FILE *csv_file = NULL;

static void cleanup(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    exit(signum);
}

static uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = SDP810_CRC_INITIAL;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SDP810_CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int read_sdp810_data(struct sdp810_data *data) {
    uint8_t buffer[9];
    if (read(i2c_fd, buffer, sizeof(buffer)) != sizeof(buffer)) {
        perror("Failed to read from I2C device");
        return -1;
    }

    if (buffer[8] != calculate_crc8(buffer, 8)) {
        fprintf(stderr, "CRC error in data\n");
        return -1;
    }

    data->pressure = (buffer[0] << 24) | (buffer[1] << 16) | (buffer[2] << 8) | buffer[3];
    data->temperature = (buffer[4] << 8) | buffer[5];
    data->scale_factor = buffer[6];

    return 0;
}

static void log_data(const struct sdp810_data *data) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    fprintf(csv_file, "%04d-%02d-%02d %02d:%02d:%02d,%u,%d\n",
            tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
            tm->tm_hour, tm->tm_min, tm->tm_sec,
            data->pressure, data->temperature);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct sdp810_data data;

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Initialize I2C
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize CSV file
    csv_file = fopen("airflow.csv", "w");
    if (csv_file == NULL) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    fprintf(csv_file, "Timestamp,Pressure (Pa),Temperature (C)\n");

    // Send measurement command
    if (write(i2c_fd, &SDP810_MEASUREMENT_CMD, 1) != 1) {
        perror("Failed to send measurement command");
        fclose(csv_file);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        // Wait for conversion time
        usleep(45000);

        // Read data
        if (read_sdp810_data(&data) == 0) {
            // Log data
            log_data(&data);
        }

        // Wait for 1 second
        sleep(1);
    }

    return EXIT_SUCCESS;
}

