This code provides a complete solution for interfacing with the Sensirion SDP810-125Pa differential pressure sensor on a Raspberry Pi 3 Model B+ using the libgpiod library. It initializes the I2C bus, sends the measurement command, waits for the conversion time, reads the data, validates the CRCs, converts the raw data to pressure and temperature, logs the data to a CSV file, and handles graceful shutdown on SIGINT or SIGTERM.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define SHT35_I2C_ADDRESS 0x44
#define SHT35_MEAS_HIGH_REP_STRETCH_DISABLE 0x2C06
#define SHT35_CRC8_POLYNOMIAL 0x31
#define SHT35_CRC8_INITIAL 0xFF

struct sht35_data {
    struct gpiod_chip *chip;
    int i2c_fd;
    FILE *csv_file;
};

void sht35_init(struct sht35_data *data) {
    data->chip = gpiod_chip_open_by_name("gpiochip0");
    if (!data->chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(EXIT_FAILURE);
    }

    data->i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (data->i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpiod_chip_close(data->chip);
        exit(EXIT_FAILURE);
    }

    if (ioctl(data->i2c_fd, I2C_SLAVE, SHT35_I2C_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C address\n");
        close(data->i2c_fd);
        gpiod_chip_close(data->chip);
        exit(EXIT_FAILURE);
    }

    data->csv_file = fopen("environment.csv", "a");
    if (!data->csv_file) {
        fprintf(stderr, "Failed to open CSV file\n");
        close(data->i2c_fd);
        gpiod_chip_close(data->chip);
        exit(EXIT_FAILURE);
    }

    if (fseek(data->csv_file, 0, SEEK_END) == 0 && ftell(data->csv_file) == 0) {
        fprintf(data->csv_file, "Timestamp,Temperature,Humidity\n");
    }
}

void sht35_read_temperature_and_humidity(struct sht35_data *data) {
    uint8_t command[2] = {SHT35_MEAS_HIGH_REP_STRETCH_DISABLE >> 8, SHT35_MEAS_HIGH_REP_STRETCH_DISABLE & 0xFF};
    if (write(data->i2c_fd, command, sizeof(command)) != sizeof(command)) {
        fprintf(stderr, "Failed to write to I2C bus\n");
        return;
    }

    usleep(15000);

    uint8_t buffer[6];
    if (read(data->i2c_fd, buffer, sizeof(buffer)) != sizeof(buffer)) {
        fprintf(stderr, "Failed to read from I2C bus\n");
        return;
    }

    uint16_t temperature_raw = (buffer[0] << 8) | buffer[1];
    uint16_t humidity_raw = (buffer[3] << 8) | buffer[4];

    uint8_t crc8_temperature = 0xFF;
    for (int i = 0; i < 2; i++) {
        crc8_temperature ^= buffer[i];
        for (int j = 0; j < 8; j++) {
            if (crc8_temperature & 0x80) {
                crc8_temperature = (crc8_temperature << 1) ^ SHT35_CRC8_POLYNOMIAL;
            } else {
                crc8_temperature = crc8_temperature << 1;
            }
        }
    }

    uint8_t crc8_humidity = 0xFF;
    for (int i = 3; i < 5; i++) {
        crc8_humidity ^= buffer[i];
        for (int j = 0; j < 8; j++) {
            if (crc8_humidity & 0x80) {
                crc8_humidity = (crc8_humidity << 1) ^ SHT35_CRC8_POLYNOMIAL;
            } else {
                crc8_humidity = crc8_humidity << 1;
            }
        }
    }

    if (crc8_temperature != buffer[2] || crc8_humidity != buffer[5]) {
        fprintf(stderr, "CRC validation failed\n");
        return;
    }

    float temperature = -45.0 + 175.0 * temperature_raw / 65535.0;
    float humidity = -6.0 + 125.0 * humidity_raw / 65535.0;

    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", tm);

    fprintf(data->csv_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
}

void sht35_shutdown(struct sht35_data *data) {
    fclose(data->csv_file);
    close(data->i2c_fd);
    gpiod_chip_close(data->chip);
}

void signal_handler(int signum) {
    struct sht35_data data;
    sht35_shutdown(&data);
    exit(EXIT_SUCCESS);
}

int main() {
    struct sht35_data data;
    sht35_init(&data);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        sht35_read_temperature_and_humidity(&data);
        sleep(5);
    }

    return 0;
}

