```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x60
#define SDP810_CMD_CONT_MEAS 0x21
#define SDP810_CONV_TIME 1000000 // 1 second
#define SDP810_DATA_SIZE 9
#define CRC8_POLYNOMIAL 0x31

struct sdp810_data {
    uint8_t pressure_msb;
    uint8_t pressure_lsb;
    uint8_t pressure_crc;
    uint8_t temperature_msb;
    uint8_t temperature_lsb;
    uint8_t temperature_crc;
    uint8_t scale_factor[3];
};

static int i2c_fd = -1;
static FILE *log_file = NULL;

static void handle_sigint(int sig) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

static uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = 0;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int read_sdp810_data(struct sdp810_data *data) {
    uint8_t buffer[SDP810_DATA_SIZE];
    ssize_t bytes_read = read(i2c_fd, buffer, SDP810_DATA_SIZE);
    if (bytes_read != SDP810_DATA_SIZE) {
        perror("Failed to read from I2C device");
        return -1;
    }

    data->pressure_msb = buffer[0];
    data->pressure_lsb = buffer[1];
    data->pressure_crc = buffer[2];
    data->temperature_msb = buffer[3];
    data->temperature_lsb = buffer[4];
    data->temperature_crc = buffer[5];
    memcpy(data->scale_factor, buffer + 6, 3);

    uint8_t expected_crc_pressure = calculate_crc8(buffer, 3);
    uint8_t expected_crc_temperature = calculate_crc8(buffer + 3, 3);

    if (data->pressure_crc != expected_crc_pressure) {
        fprintf(stderr, "CRC error in pressure data\n");
        return -1;
    }

    if (data->temperature_crc != expected_crc_temperature) {
        fprintf(stderr, "CRC error in temperature data\n");
        return -1;
    }

    return 0;
}

static float convert_pressure(uint8_t msb, uint8_t lsb, uint8_t *scale_factor) {
    int32_t pressure_raw = ((int32_t)msb << 16) | ((int32_t)lsb << 8) | (scale_factor[0] & 0x0F);
    return pressure_raw * 0.00001f;
}

static float convert_temperature(uint8_t msb, uint8_t lsb, uint8_t *scale_factor) {
    int32_t temperature_raw = ((int32_t)msb << 16) | ((int32_t)lsb << 8) | (scale_factor[0] >> 4);
    return temperature_raw * 0.01f;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct sdp810_data data;

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    // Initialize GPIO driver
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C device");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        gpiod_chip_close(chip);
        return 1;
    }

    // Initiate continuous measurement
    uint8_t cmd[] = {SDP810_CMD_CONT_MEAS};
    if (write(i2c_fd, cmd, sizeof(cmd)) != sizeof(cmd)) {
        perror("Failed to write command to I2C device");
        close(i2c_fd);
        gpiod_chip_close(chip);
        return 1;
    }

    // Open log file
    log_file = fopen("airflow.dat", "wb");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        gpiod_chip_close(chip);
        return 1;
    }

    while (1) {
        if (read_sdp810_data(&data) == 0) {
            float pressure = convert_pressure(data.pressure_msb, data.pressure_lsb, data.scale_factor);
            float temperature = convert_temperature(data.temperature_msb, data.temperature_lsb, data.scale_factor);

            if (fwrite(&pressure, sizeof(float), 1, log_file) != 1 || fwrite(&temperature, sizeof(float), 1, log_file) != 1) {
                perror("Failed to write to log file");
                break;
            }
        }

        sleep(1);
    }

    fclose(log_file);
    close(i2c_fd);
    gpiod_chip_close(chip);

    return 0;
}
```

This code initializes the GPIO driver, opens the I2C device, sets the I2C address, initiates continuous measurement on the Sensirion SDP810-500Pa sensor, reads the sensor data, validates the CRC, converts the raw data to floating-point values, logs each sample to a binary file, and handles graceful shutdown on SIGINT and SIGTERM.

