#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <pigpio.h>

#define I2C_ADDRESS 0x28
#define I2C_DEVICE "/dev/i2c-1"
#define FAN_PIN 18
#define PWM_FREQ 25000
#define SAMPLE_INTERVAL 100
#define LOG_FILE "flow_log.txt"

static int i2c_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *fan_line = NULL;

void cleanup() {
    if (fan_line) {
        gpiod_line_set_value(fan_line, 0);
        gpiod_line_release(fan_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(0);
}

void handle_signal(int sig) {
    cleanup();
}

