This C program for a Raspberry Pi 3 Model B+ reads the differential pressure from a Honeywell Zephyr HAF Series HAFBLF0100A2AX5 digital airflow sensor over the I2C bus, samples the sensor every 100 ms, computes the corresponding flow rate, and drives a PWM fan connected to GPIO18 (BCM numbering) using hardware PWM at a frequency of 25 kHz. It logs each measurement to a file named `flow_log.txt` in the format "timestamp,pressure_Pa\n". The program includes robust handling of I2C communication failures by logging errors to stderr without crashing, and it cleans up gracefully on receipt of SIGINT or SIGTERM by turning off the fan, closing the I2C handle, flushing and closing the log file, and terminating the driver library.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define LPS33HW_I2C_ADDRESS 0x5C
#define LPS33HW_PRESSURE_REG 0x28
#define LPS33HW_TEMP_REG 0x2A
#define LOG_FILE "environmental_data.txt"

volatile sig_atomic_t stop_flag = 0;

void handle_sigint(int sig) {
    stop_flag = 1;
}

int read_sensor_data(int fd, float *pressure, float *temperature) {
    uint8_t data[6];
    if (gpiod_line_get_value(fd, data) < 0) {
        perror("Failed to read sensor data");
        return -1;
    }

    *pressure = (data[0] << 16) | (data[1] << 8) | data[2];
    *pressure /= 4096.0;

    *temperature = (data[3] << 8) | data[4];
    *temperature /= 100.0;

    return 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int fd;
    FILE *log_file;
    time_t now;
    struct tm *tm_info;
    float pressure, temperature;

    // Initialize libgpiod
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Open I2C line
    line = gpiod_chip_get_line(chip, 2); // Assuming SDA is on GPIO2
    if (!line) {
        perror("Failed to get I2C line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "i2c", 0) < 0) {
        perror("Failed to request I2C line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    while (!stop_flag) {
        // Read sensor data
        if (read_sensor_data(fd, &pressure, &temperature) < 0) {
            time(&now);
            tm_info = localtime_r(&now, NULL);
            fprintf(stderr, "%s, Error reading sensor data\n", asctime(tm_info));
            fprintf(log_file, "%s, Error reading sensor data\n", asctime(tm_info));
            fflush(log_file);
            continue;
        }

        // Get current time
        time(&now);
        tm_info = localtime_r(&now, NULL);

        // Log data
        fprintf(log_file, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n", asctime(tm_info), pressure, temperature);
        fflush(log_file);
    }

    // Clean up
    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

