#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x48
#define LED_PIN 17
#define BUFFER_SIZE 10
#define AVG_TEMP_THRESHOLD 28.0

static struct gpiod_chip *chip;
static struct gpiod_line *led_line;
static float temperature_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static float running_average = 0.0;

void cleanup() {
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

void handle_signal(int sig) {
    cleanup();
    exit(0);
}

float read_temperature() {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1.0;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(fd);
        return -1.0;
    }

    uint8_t data[2];
    if (read(fd, data, 2) != 2) {
        perror("Failed to read temperature data");
        close(fd);
        return -1.0;
    }

    close(fd);

    int16_t raw_temp = (data[0] << 8) | data[1];
    float temperature = (raw_temp / 32.0) - 273.15;
    return temperature;
}

void update_average(float new_temp) {
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    } else {
        running_average -= temperature_buffer[buffer_index];
    }

    running_average += new_temp;
    temperature_buffer[buffer_index] = new_temp;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get LED line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, "temperature_led", 0) < 0) {
        perror("Failed to request LED line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        float temp = read_temperature();
        if (temp >= 0.0) {
            update_average(temp);
            if (running_average > AVG_TEMP_THRESHOLD) {
                gpiod_line_set_value(led_line, 1);
            } else {
                gpiod_line_set_value(led_line, 0);
            }
        }

        sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

