void ventilation_control(int co2) {
    if (co2 < SCD30_CO2_THRESHOLD_LOW) {
        gpiod_line_set_value(ventilation_line, 0); // OFF
    } else if (co2 <= SCD30_CO2_THRESHOLD_HIGH) {
        gpiod_line_set_value(ventilation_line, 1); // LOW
    } else {
        gpiod_line_set_value(ventilation_line, 2); // HIGH
    }
}

