#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SDP32_ADDRESS 0x60
#define SAMPLE_INTERVAL_DEFAULT 1000
#define CRC8_POLYNOMIAL 0x31

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = 0;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main(int argc, char *argv[]) {
    int sample_interval = SAMPLE_INTERVAL_DEFAULT;
    if (argc > 1) {
        sample_interval = atoi(argv[1]);
        if (sample_interval <= 0) {
            fprintf(stderr, "Invalid sample interval: %s\n", argv[1]);
            return 1;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set signal handlers");
        return 1;
    }

    int fd = open(I2C_DEVICE, O_RDWR);
    if (fd == -1) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, SDP32_ADDRESS) == -1) {
        perror("Failed to set I2C address");
        close(fd);
        return 1;
    }

    while (running) {
        uint8_t command[1] = {0x03}; // Start measurement
        if (write(fd, command, sizeof(command)) != sizeof(command)) {
            perror("Failed to start measurement");
            close(fd);
            return 1;
        }

        usleep(100000); // Wait for measurement to complete

        uint8_t data[9];
        if (read(fd, data, sizeof(data)) != sizeof(data)) {
            perror("Failed to read data");
            close(fd);
            return 1;
        }

        uint8_t pressure_crc = calculate_crc8(data, 3);
        uint8_t temperature_crc = calculate_crc8(data + 3, 3);
        uint8_t scale_factor_crc = calculate_crc8(data + 6, 3);

        if (pressure_crc != data[3] || temperature_crc != data[6] || scale_factor_crc != data[9]) {
            fprintf(stderr, "CRC error in data\n");
            close(fd);
            return 1;
        }

        printf("Timestamp: %ld, Pressure: %d.%02d Pa, Temperature: %d.%02d °C, Scale Factor: %d.%02d\n",
               time(NULL), data[0], data[1], data[3], data[4], data[6], data[7]);

        sleep(sample_interval / 1000);
    }

    close(fd);
    return 0;
}

