This C program for a Raspberry Pi 3 Model B+ reads the differential pressure from a Sensirion SDP32 sensor over the I2C bus, prints each reading to the console with a timestamp, and handles I2C failures robustly. It uses the libgpiod library for I2C communication and installs signal handlers for SIGINT and SIGTERM to ensure clean resource release on exit.

code:
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x5D
#define I2C_SDA_PIN 2
#define I2C_SCL_PIN 3
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF

static struct gpiod_chip *chip;
static struct gpiod_line *sda_line, *scl_line;
static int running = 1;

void handle_sigint(int sig) {
    running = 0;
}

uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = CRC8_INITIAL_VALUE;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_sensor_data(uint8_t *data) {
    int ret = gpiod_line_request_output(sda_line, "sdp810_sda", 0);
    if (ret < 0) {
        perror("Failed to request SDA line");
        return ret;
    }

    ret = gpiod_line_request_output(scl_line, "sdp810_scl", 0);
    if (ret < 0) {
        perror("Failed to request SCL line");
        gpiod_line_release(sda_line);
        return ret;
    }

    // Trigger conversion
    gpiod_line_set_value(sda_line, 0);
    gpiod_line_set_value(scl_line, 0);
    usleep(45000);
    gpiod_line_set_value(scl_line, 1);
    usleep(1);
    gpiod_line_set_value(sda_line, 1);
    usleep(1);
    gpiod_line_set_value(scl_line, 0);

    // Read 9 bytes
    for (int i = 0; i < 9; i++) {
        data[i] = 0;
        for (int j = 0; j < 8; j++) {
            gpiod_line_set_value(sda_line, 0);
            usleep(1);
            gpiod_line_set_value(scl_line, 1);
            usleep(1);
            data[i] = (data[i] << 1) | gpiod_line_get_value(sda_line);
            gpiod_line_set_value(scl_line, 0);
            usleep(1);
        }
    }

    gpiod_line_release(sda_line);
    gpiod_line_release(scl_line);

    return 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *sda_line, *scl_line;
    uint8_t data[9];
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request SDA line
    sda_line = gpiod_chip_get_line(chip, I2C_SDA_PIN);
    if (!sda_line) {
        perror("Failed to get SDA line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request SCL line
    scl_line = gpiod_chip_get_line(chip, I2C_SCL_PIN);
    if (!scl_line) {
        perror("Failed to get SCL line");
        gpiod_line_release(sda_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up signal handler
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    while (running) {
        ret = read_sensor_data(data);
        if (ret < 0) {
            perror("Failed to read sensor data");
            continue;
        }

        // Validate CRC
        for (int i = 0; i < 3; i++) {
            uint8_t calculated_crc = calculate_crc8(data + i * 3, 3);
            if (calculated_crc != data[i * 3 + 3]) {
                fprintf(stderr, "CRC mismatch at word %d\n", i);
                continue;
            }
        }

        // Convert and print data
        int32_t pressure = (int32_t)((data[0] << 24) | (data[1] << 16) | (data[2] << 8) | data[3]);
        int32_t temperature = (int32_t)((data[4] << 24) | (data[5] << 16) | (data[6] << 8) | data[7]);
        float pressure_pa = pressure * 0.000125;
        float temperature_c = temperature * 0.01;

        printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure_pa, temperature_c);

        sleep(1);
    }

    // Cleanup
    gpiod_line_release(sda_line);
    gpiod_line_release(scl_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

