#define I2C_BUS "/dev/i2c-1"
#define HDC1000_I2C_ADDR 0x40
#define HDC1000_TEMP_REG 0x00
#define HDC1000_HUMIDITY_REG 0x01
#define HDC1000_CONFIG_REG 0x02
#define HDC1000_CONFIG_VAL 0x1000
#define CONVERSION_DELAY 20000 // 20 ms
#define LOG_INTERVAL 5000000 // 5 seconds

int i2c_fd = -1;

void close_i2c() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

void signal_handler(int signum) {
    fprintf(stderr, "Received signal %d, exiting...\n", signum);
    close_i2c();
    exit(signum);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, HDC1000_I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close_i2c();
        return EXIT_FAILURE;
    }

    uint16_t config_val = HDC1000_CONFIG_VAL;
    if (write(i2c_fd, &config_val, sizeof(config_val)) != sizeof(config_val)) {
        perror("Failed to write configuration to HDC1000");
        close_i2c();
        return EXIT_FAILURE;
    }

    while (1) {
        usleep(CONVERSION_DELAY);

        uint16_t temp_reg = HDC1000_TEMP_REG;
        if (write(i2c_fd, &temp_reg, sizeof(temp_reg)) != sizeof(temp_reg)) {
            perror("Failed to write temperature register address to HDC1000");
            continue;
        }

        uint16_t humidity_reg = HDC1000_HUMIDITY_REG;
        if (write(i2c_fd, &humidity_reg, sizeof(humidity_reg)) != sizeof(humidity_reg)) {
            perror("Failed to write humidity register address to HDC1000");
            continue;
        }

        uint16_t temp_data[2];
        if (read(i2c_fd, temp_data, sizeof(temp_data)) != sizeof(temp_data)) {
            perror("Failed to read temperature data from HDC1000");
            continue;
        }

        uint16_t humidity_data[2];
        if (read(i2c_fd, humidity_data, sizeof(humidity_data)) != sizeof(humidity_data)) {
            perror("Failed to read humidity data from HDC1000");
            continue;
        }

        float temperature = (temp_data[0] << 8 | temp_data[1]) / 65536.0 * 165.0 - 40.0;
        float humidity = (humidity_data[0] << 8 | humidity_data[1]) / 65536.0 * 100.0;

        printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
    }

    close_i2c();
    return EXIT_SUCCESS;
}

