#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define SDA_PIN 2
#define SCL_PIN 3
#define SI7051_ADDRESS 0x40
#define READ_TEMP_CMD 0xF3
#define TIMEOUT 5000

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int read_temperature(struct gpiod_chip *chip, uint8_t address) {
    struct gpiod_line *sda, *scl;
    uint8_t data[3];
    int ret;

    sda = gpiod_chip_get_line(chip, SDA_PIN);
    if (!sda) {
        perror("Failed to get SDA line");
        return -1;
    }

    scl = gpiod_chip_get_line(chip, SCL_PIN);
    if (!scl) {
        perror("Failed to get SCL line");
        gpiod_line_release(sda);
        return -1;
    }

    ret = gpiod_line_request_output(sda, "si7051_sda", 0);
    if (ret < 0) {
        perror("Failed to request SDA line as output");
        gpiod_line_release(sda);
        gpiod_line_release(scl);
        return -1;
    }

    ret = gpiod_line_request_output(scl, "si7051_scl", 0);
    if (ret < 0) {
        perror("Failed to request SCL line as output");
        gpiod_line_release(sda);
        gpiod_line_release(scl);
        return -1;
    }

    // Start condition
    gpiod_line_set_value(sda, 1);
    gpiod_line_set_value(scl, 1);
    usleep(1);
    gpiod_line_set_value(sda, 0);
    usleep(1);
    gpiod_line_set_value(scl, 0);
    usleep(1);

    // Send address
    for (int i = 7; i >= 0; i--) {
        gpiod_line_set_value(sda, (address >> i) & 1);
        usleep(1);
        gpiod_line_set_value(scl, 1);
        usleep(1);
        gpiod_line_set_value(scl, 0);
        usleep(1);
    }

    // Send read command
    for (int i = 7; i >= 0; i--) {
        gpiod_line_set_value(sda, (READ_TEMP_CMD >> i) & 1);
        usleep(1);
        gpiod_line_set_value(scl, 1);
        usleep(1);
        gpiod_line_set_value(scl, 0);
        usleep(1);
    }

    // Stop condition
    gpiod_line_set_value(sda, 0);
    usleep(1);
    gpiod_line_set_value(scl, 1);
    usleep(1);
    gpiod_line_set_value(sda, 1);
    usleep(1);

    // Read temperature data
    for (int i = 0; i < 3; i++) {
        data[i] = 0;
        for (int j = 7; j >= 0; j--) {
            gpiod_line_set_value(sda, 1);
            usleep(1);
            gpiod_line_set_value(scl, 1);
            usleep(1);
            data[i] |= (gpiod_line_get_value(sda) << j);
            gpiod_line_set_value(scl, 0);
            usleep(1);
        }
    }

    // Acknowledge
    gpiod_line_set_value(sda, 0);
    usleep(1);
    gpiod_line_set_value(scl, 1);
    usleep(1);
    gpiod_line_set_value(sda, 1);
    usleep(1);

    gpiod_line_release(sda);
    gpiod_line_release(scl);

    return ((data[0] << 8) | data[1]) * 175.72 / 65536 - 46.85;
}

int main() {
    struct gpiod_chip *chip;
    int ret;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    while (running) {
        int temperature = read_temperature(chip, SI7051_ADDRESS);
        if (temperature >= 0) {
            printf("Temperature: %.2f°C\n", temperature);
        } else {
            printf("Failed to read temperature\n");
        }
        sleep(5);
    }

    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

