#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define I2C_BUS "i2c-1"
#define I2C_ADDRESS 0x5A
#define MLX90833_REG_TA 0x06
#define MLX90833_REG_TOBJ1 0x07

struct gpiod_chip *chip;
struct gpiod_line *line;
int running = 1;

void signal_handler(int signum) {
    running = 0;
}

int read_temperature(struct gpiod_chip *chip, uint8_t reg, float *temperature) {
    uint8_t buffer[2];
    int ret;

    ret = gpiod_chip_i2c_read(chip, I2C_ADDRESS, reg, buffer, sizeof(buffer));
    if (ret != sizeof(buffer)) {
        fprintf(stderr, "Failed to read from sensor: %s\n", gpiod_chip_get_name(chip));
        return -1;
    }

    *temperature = (buffer[0] << 8 | buffer[1]) * 0.02;
    return 0;
}

int main() {
    struct timespec ts;
    float temperature;

    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the I2C chip
    chip = gpiod_chip_open(I2C_BUS);
    if (!chip) {
        fprintf(stderr, "Failed to open I2C chip: %s\n", I2C_BUS);
        return EXIT_FAILURE;
    }

    // Read temperature every 500ms
    while (running) {
        if (read_temperature(chip, MLX90833_REG_TOBJ1, &temperature) == 0) {
            clock_gettime(CLOCK_REALTIME, &ts);
            printf("Timestamp: %ld.%09ld, Temperature: %.2f°C\n", ts.tv_sec, ts.tv_nsec, temperature);
        }
        usleep(500 * 1000);
    }

    // Clean up
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

