#include <libgpiod.h>

#define I2C_CHIP "gpiochip0"
#define I2C_LINE 18
#define I2C_ADDRESS 0x76
#define MEASUREMENT_DELAY 7
#define READ_INTERVAL 5000000

struct i2c_device {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
};

void i2c_close(struct i2c_device *dev) {
    if (dev->line) {
        gpiod_line_release(dev->line);
    }
    if (dev->chip) {
        gpiod_chip_close(dev->chip);
    }
}

void signal_handler(int signum) {
    i2c_close(&dev);
    exit(signum);
}

int i2c_read_temperature_pressure(struct i2c_device *dev, float *temperature, float *pressure) {
    uint8_t buffer[6];
    int ret;

    ret = gpiod_line_set_value(dev->line, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to trigger measurement: %s\n", gpiod_error_text(ret));
        return ret;
    }

    usleep(MEASUREMENT_DELAY * 1000);

    ret = gpiod_line_set_value(dev->line, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to reset measurement: %s\n", gpiod_error_text(ret));
        return ret;
    }

    ret = gpiod_chip_read_i2c(dev->chip, I2C_ADDRESS, buffer, sizeof(buffer));
    if (ret < 0) {
        fprintf(stderr, "Failed to read I2C data: %s\n", gpiod_error_text(ret));
        return ret;
    }

    if (ret != sizeof(buffer)) {
        fprintf(stderr, "Incomplete I2C read: %d bytes read\n", ret);
        return -1;
    }

    *temperature = (buffer[0] * 256 + buffer[1]) / 100.0;
    *pressure = (buffer[2] * 256 * 256 + buffer[3] * 256 + buffer[4]) / 100.0;

    return 0;
}

int main() {
    struct i2c_device dev = {0};
    struct sigaction sa;
    time_t now;
    struct tm *tm_info;
    float temperature, pressure;

    dev.chip = gpiod_chip_open(I2C_CHIP);
    if (!dev.chip) {
        fprintf(stderr, "Failed to open I2C chip: %s\n", gpiod_error_text(errno));
        return EXIT_FAILURE;
    }

    dev.line = gpiod_chip_get_line(dev.chip, I2C_LINE);
    if (!dev.line) {
        fprintf(stderr, "Failed to get I2C line: %s\n", gpiod_error_text(errno));
        i2c_close(&dev);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(dev.line, "barometer_trigger", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request I2C line: %s\n", gpiod_error_text(ret));
        i2c_close(&dev);
        return EXIT_FAILURE;
    }

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (1) {
        if (i2c_read_temperature_pressure(&dev, &temperature, &pressure) == 0) {
            time(&now);
            tm_info = localtime(&now);
            printf("%04d-%02d-%02dT%02d:%02d:%02d - Temperature: %.2f C, Pressure: %.2f Pa\n",
                   tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
                   tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec,
                   temperature, pressure);
        }

        usleep(READ_INTERVAL);
    }

    i2c_close(&dev);
    return EXIT_SUCCESS;
}
