#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define I2C_CHIP "gpiochip0"
#define I2C_LINE 18
#define I2C_ADDRESS 0x50

static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;

void handle_sigint(int sig) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

int main() {
    struct timespec ts;
    uint16_t pressure;
    uint8_t buffer[2];

    // Register signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    // Open GPIO chip
    chip = gpiod_chip_open(I2C_CHIP);
    if (chip == NULL) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Open I2C line
    i2c_fd = gpiod_chip_get_line(chip, I2C_LINE);
    if (i2c_fd == -1) {
        perror("Failed to get I2C line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure I2C line as output
    if (gpiod_line_request_output(i2c_fd, "i2c", 0) < 0) {
        perror("Failed to request I2C line as output");
        close(i2c_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        // Start I2C transaction
        if (gpiod_line_set_value(i2c_fd, 1) < 0) {
            perror("Failed to set I2C line high");
            continue;
        }

        // Send I2C address and command
        if (write(i2c_fd, &I2C_ADDRESS, 1) != 1) {
            perror("Failed to write I2C address");
            continue;
        }

        // Send register address to read pressure
        if (write(i2c_fd, "\x00", 1) != 1) {
            perror("Failed to write register address");
            continue;
        }

        // Start I2C transaction
        if (gpiod_line_set_value(i2c_fd, 0) < 0) {
            perror("Failed to set I2C line low");
            continue;
        }

        // Read pressure data
        if (read(i2c_fd, buffer, 2) != 2) {
            perror("Failed to read pressure data");
            continue;
        }

        // Calculate pressure
        pressure = (buffer[0] << 8) | buffer[1];

        // Get current time
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("Failed to get current time");
            continue;
        }

        // Print timestamp and pressure
        printf("%ld.%09ld: Pressure = %d Pa\n", ts.tv_sec, ts.tv_nsec, pressure);
    }

    // Close I2C line and chip
    close(i2c_fd);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

