#define SENSIRION_MEASURE_CMD 0x21
#define SENSIRION_READ_CMD 0x03
#define SENSIRION_CRC8_POLYNOMIAL 0x31
#define SENSIRION_CRC8_INITIAL 0xFF

static struct gpiod_chip *chip;
static FILE *log_file;

void handle_sigint(int sig) {
    if (log_file) fclose(log_file);
    if (chip) gpiod_chip_close(chip);
    exit(0);
}

uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = SENSIRION_CRC8_INITIAL;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SENSIRION_CRC8_POLYNOMIAL;
            } else {
                crc = crc << 1;
            }
        }
    }
    return crc;
}

