#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define SDP800_ADDRESS 0x28
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL 0xFF

static struct gpiod_chip *chip;
static int log_fd = -1;

static void cleanup(int signum) {
    if (log_fd != -1) {
        close(log_fd);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    exit(signum);
}

static uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = CRC8_INITIAL;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int read_pressure() {
    uint8_t command[1] = {0x00}; // Trigger measurement command
    uint8_t response[3];

    if (gpiod_line_set_value(chip, 0, 1) < 0) {
        perror("Failed to set trigger line high");
        return -1;
    }
    usleep(8000); // Wait at least 8 ms
    if (gpiod_line_set_value(chip, 0, 0) < 0) {
        perror("Failed to set trigger line low");
        return -1;
    }

    if (gpiod_chip_read_i2c(chip, SDP800_ADDRESS, response, sizeof(response)) != sizeof(response)) {
        perror("Failed to read from I2C device");
        return -1;
    }

    uint8_t crc = calculate_crc8(response, 2);
    if (crc != response[2]) {
        fprintf(stderr, "CRC error in response\n");
        return -1;
    }

    int pressure = (response[0] << 8) | response[1];
    return pressure;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    log_fd = open("airflow_log.csv", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd == -1) {
        perror("Failed to open log file");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (access("airflow_log.csv", F_OK) == -1) {
        fprintf(log_fd, "Timestamp,Pressure\n");
    }

    while (1) {
        int pressure = read_pressure();
        if (pressure >= 0) {
            time_t now = time(NULL);
