#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define I2C_BUS "i2c-1"
#define I2C_ADDRESS 0x5A
#define SENSOR_REG 0x00
#define LOG_FILE "pressure_log.csv"

static struct gpiod_chip *chip;
static int i2c_fd;
static FILE *log_file;

void log_pressure(float pressure) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d,%.2f\n",
            tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
            tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec, pressure);
}

void handle_sigint(int sig) {
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }
    exit(0);
}

void handle_sigterm(int sig) {
    handle_sigint(sig);
}

int read_sensor() {
    uint8_t data[2];
    ssize_t bytes_read = gpiod_chip_i2c_read(chip, I2C_ADDRESS, data, sizeof(data));
    if (bytes_read != sizeof(data)) {
        fprintf(stderr, "Failed to read from sensor\n");
        return -1;
    }
    uint16_t raw_pressure = (data[0] << 8) | data[1];
    float pressure_kPa = (raw_pressure * 0.0625) - 50.0;
    return pressure_kPa;
}

int main() {
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    chip = gpiod_chip_open(I2C_BUS);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    i2c_fd = gpiod_chip_i2c_open(chip, I2C_ADDRESS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        close(i2c_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,pressure_kPa\n");
    }

    while (1) {
        float pressure = read_sensor();
        if (pressure >= 200.0 && pressure <= 250.0) {
            log_pressure(pressure);
        } else {
            fprintf(stderr, "Pressure out of safe range: %.2f kPa\n", pressure);
        }
        sleep(1);
    }

    fclose(log_file);
    close(i2c_fd);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

