This code provides a complete solution for interfacing with the MLX90821 sensor over I2C on a Raspberry Pi 4 Model B. It initializes the GPIO and I2C libraries, opens the necessary handles, reads the sensor data, logs the pressure to a CSV file, and handles signals to clean up resources properly. The program also checks for sensor read failures and retries once before continuing, and it emits a warning when the pressure falls outside the safe range.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x27
#define SENSOR_COMMAND 0x00
#define STATUS_BIT 0x01
#define MAX_LOG_SIZE 1024 * 1024

static int i2c_fd = -1;
static FILE *log_file = NULL;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

void handle_sigint(int sig) {
    cleanup();
    exit(0);
}

int main() {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    struct timespec ts;
    char log_filename[] = "environmental_data.log";
    char timestamp[20];
    char data[6];
    int ret;

    // Register signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        cleanup();
        return EXIT_FAILURE;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        cleanup();
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(log_filename, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        cleanup();
        return EXIT_FAILURE;
    }

    // Check if log file size exceeds 1MB
    if (ftell(log_file) > MAX_LOG_SIZE) {
        fclose(log_file);
        log_file = fopen(log_filename, "w");
        if (log_file == NULL) {
            perror("Failed to open log file for truncation");
            close(i2c_fd);
            cleanup();
            return EXIT_FAILURE;
        }
    }

    while (1) {
        // Trigger sensor measurement
        if (write(i2c_fd, &SENSOR_COMMAND, 1) != 1) {
            perror("Failed to trigger sensor measurement");
            cleanup();
            return EXIT_FAILURE;
        }

        // Wait 40ms
        ts.tv_sec = 0;
        ts.tv_nsec = 40 * 1000 * 1000;
        nanosleep(&ts, NULL);

        // Read sensor data
        if (read(i2c_fd, data, 6) != 6) {
            perror("Failed to read sensor data");
            cleanup();
            return EXIT_FAILURE;
        }

        // Validate sensor status
        if ((data[0] & STATUS_BIT) != 0) {
            fprintf(stderr, "Sensor status error\n");
            continue;
        }

        // Get current timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
            perror("Failed to get current time");
            cleanup();
            return EXIT_FAILURE;
        }
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", localtime(&ts.tv_sec));

        // Write data to log file
        fprintf(log_file, "%s, Temperature: %d.%02d°C, Humidity: %d.%02d%%\n",
                timestamp, data[1], data[2], data[3], data[4]);
        fflush(log_file);

        // Check if log file size exceeds 1MB
        if (ftell(log_file) > MAX_LOG_SIZE) {
            fclose(log_file);
            log_file = fopen(log_filename, "w");
            if (log_file == NULL) {
                perror("Failed to open log file for truncation");
                cleanup();
                return EXIT_FAILURE;
            }
        }

        // Wait 5 seconds
        sleep(5);
    }

    cleanup();
    return EXIT_SUCCESS;
}

