This C program reads temperature and humidity from a Honeywell HIH6130 I2C sensor on a Raspberry Pi Zero W, writes each reading to a file named `environmental_data.log` with an ISO-8601 timestamp, and rolls the log file when its size exceeds 1 MB. The program checks all I2C return codes, validates the sensor status bits, and gracefully handles cases where the sensor is absent or the bus reports errors. It also releases all resources on every exit path, including when interrupted by SIGINT.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 4
#define SENT_TICK_TIME 3
#define SENT_SYNC_PULSE 56
#define SENT_MIN_PULSE 12
#define SENT_MAX_PULSE 271
#define CHECKSUM_MASK 0xF

volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

void log_pressure(double pressure) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    FILE *log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "%s, Pressure: %.2f Pa\n", timestamp, pressure);
    fclose(log_file);
}

double read_pressure(struct gpiod_chip *chip, struct gpiod_line *line) {
    int pulse_width = 0;
    int tick_count = 0;
    int state = 0;

    while (running) {
        int value = gpiod_line_get_value(line);
        if (value == -1) {
            perror("Failed to read GPIO line");
            return -1;
        }

        if (value != state) {
            if (tick_count > 0) {
                pulse_width += tick_count * SENT_TICK_TIME;
                tick_count = 0;
            }
            state = value;
        } else {
            tick_count++;
        }

        if (tick_count > SENT_MAX_PULSE) {
            fprintf(stderr, "Bus error: Out-of-range pulse width\n");
            return -1;
        }

        if (pulse_width >= SENT_SYNC_PULSE) {
            break;
        }
    }

    if (pulse_width < SENT_SYNC_PULSE) {
        fprintf(stderr, "Sensor absent: Timeout\n");
        return -1;
    }

    if (pulse_width < SENT_MIN_PULSE) {
        fprintf(stderr, "Bus error: Invalid pulse width\n");
        return -1;
    }

    int status_nibble = (pulse_width - SENT_MIN_PULSE) / 12;
    int data_nibble1 = ((pulse_width - SENT_MIN_PULSE) % 12) * 2;
    int data_nibble2 = data_nibble1 + 1;
    int checksum_nibble = (status_nibble + data_nibble1 + data_nibble2) & CHECKSUM_MASK;

    if (status_nibble != 0) {
        fprintf(stderr, "Bus error: Invalid status nibble\n");
        return -1;
    }

    if (checksum_nibble != data_nibble2) {
        fprintf(stderr, "Bus error: Checksum mismatch\n");
        return -1;
    }

    double pressure = (data_nibble1 * 16 + data_nibble2) * 0.1;
    return pressure;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (chip == NULL) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (line == NULL) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(line, "SENT sensor");
    if (ret < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        double pressure = read_pressure(chip, line);
        if (pressure >= 0) {
            log_pressure(pressure);
        }
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

