        return -1;
    }

    if (pulse_width < SENT_MIN_PULSE) {
        fprintf(stderr, "Bus error: Invalid pulse width\n");
        return -1;
    }

    int status_nibble = (pulse_width - SENT_MIN_PULSE) / 12;
    int data_nibble1 = ((pulse_width - SENT_MIN_PULSE) % 12) * 2;
    int data_nibble2 = data_nibble1 + 1;
    int checksum_nibble = (status_nibble + data_nibble1 + data_nibble2) & CHECKSUM_MASK;

    if (status_nibble != 0) {
        fprintf(stderr, "Bus error: Invalid status nibble\n");
        return -1;
    }

    if (checksum_nibble != data_nibble2) {
        fprintf(stderr, "Bus error: Checksum mismatch\n");
        return -1;
    }

    double pressure = (data_nibble1 * 16 + data_nibble2) * 0.1;
    return pressure;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (chip == NULL) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (line == NULL) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(line, "SENT sensor");
    if (ret < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        double pressure = read_pressure(chip, line);
        if (pressure >= 0) {
            log_pressure(pressure);
        }
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}
```

This C program reads automotive brake pressure data from a Melexis MLX90824 SENT pressure sensor using the SENT single-wire protocol on GPIO4 (BCM). It logs each reading to a file named `pressure_log.txt` in the format "YYYY-MM-DD HH:MM:SS, Pressure: XXXX.XX Pa". The program detects sensor-absent conditions by timeout and bus errors such as checksum mismatches or out-of-range pulse widths, reports those errors to stderr without crashing, and cleanly releases all resources on receipt of SIGINT or SIGTERM.

