static void crc8(const uint8_t *data, size_t length, uint8_t *crc) {
    *crc = SHT40_CRC_INITIAL;
    for (size_t i = 0; i < length; i++) {
        *crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (*crc & 0x80) {
                *crc = (*crc << 1) ^ SHT40_CRC_POLYNOMIAL;
            } else {
                *crc = (*crc << 1);
            }
        }
    }
}

