#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define TMP117_I2C_ADDR 0x48
#define BUFFER_SIZE 100
#define SAMPLE_INTERVAL 5

typedef struct {
    float temperature;
    time_t timestamp;
} TemperatureReading;

TemperatureReading buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_count = 0;
int i2c_fd = -1;
struct gpiod_chip *chip = NULL;

void save_buffer_to_file() {
    FILE *file = fopen("temperature_log.dat", "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    fwrite(buffer, sizeof(TemperatureReading), buffer_count, file);
    fclose(file);
}

void handle_sigint(int sig) {
    save_buffer_to_file();
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

int main() {
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    // Initialize I2C
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, TMP117_I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize GPIO chip (if needed)
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        uint8_t data[2];
        if (read(i2c_fd, data, sizeof(data)) != sizeof(data)) {
            perror("Failed to read from I2C device");
            continue;
        }

        // Convert data to temperature
        float temperature = (data[0] << 8 | data[1]) * 0.0625;

        // Store reading in buffer
        buffer[buffer_index].temperature = temperature;
        buffer[buffer_index].timestamp = time(NULL);
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        buffer_count = (buffer_count + 1) % BUFFER_SIZE;

        // Save buffer to file
        save_buffer_to_file();

        // Wait for next sample
        sleep(SAMPLE_INTERVAL);
    }

    return EXIT_SUCCESS;
}

