#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define SHTC3_I2C_ADDRESS 0x70
#define SHTC3_MEASURE_CMD 0x7866
#define SHTC3_MEASURE_CMD_LEN 2
#define SHTC3_DATA_LEN 6
#define SHTC3_CRC8_POLYNOMIAL 0x31
#define SHTC3_CRC8_INITIAL 0xFF

struct shtc3_data {
    uint16_t temp_raw;
    uint16_t hum_raw;
};

static struct gpiod_chip *chip;
static struct gpiod_line *sda_line;
static struct gpiod_line *scl_line;
static int i2c_fd;
static FILE *log_file;

static uint8_t shtc3_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = SHTC3_CRC8_INITIAL;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SHTC3_CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int shtc3_read_data(struct shtc3_data *data) {
    uint8_t cmd[SHTC3_MEASURE_CMD_LEN] = {SHTC3_MEASURE_CMD >> 8, SHTC3_MEASURE_CMD & 0xFF};
    uint8_t buf[SHTC3_DATA_LEN];

    if (write(i2c_fd, cmd, SHTC3_MEASURE_CMD_LEN) != SHTC3_MEASURE_CMD_LEN) {
        perror("I2C write error");
        return -1;
    }

    usleep(12400); // Wait at least 12.4 ms

    if (read(i2c_fd, buf, SHTC3_DATA_LEN) != SHTC3_DATA_LEN) {
        perror("I2C read error");
        return -1;
    }

    data->temp_raw = (buf[0] << 8) | buf[1];
    data->hum_raw = (buf[3] << 8) | buf[4];

    uint8_t crc_temp = shtc3_crc8(buf, 2);
    uint8_t crc_hum = shtc3_crc8(buf + 3, 2);

    if (crc_temp != buf[2] || crc_hum != buf[5]) {
        fprintf(stderr, "CRC error\n");
        return -1;
    }

    return 0;
}

static void shtc3_log_data(const struct shtc3_data *data) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data->temp_raw * 0.01 - 40.0, data->hum_raw * 0.01);
    fflush(log_file);
}

static void shtc3_cleanup() {
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

static void sigint_handler(int signum) {
    shtc3_cleanup();
    exit(signum);
}

int main() {
    struct shtc3_data data;
    struct sigaction sa;

    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    sda_line = gpiod_chip_get_line(chip, 2);
    if (!sda_line) {
        perror("Failed to get SDA line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    scl_line = gpiod_chip_get_line(chip, 3);
    if (!scl_line) {
        perror("Failed to get SCL line");
        gpiod_line_release(sda_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(sda_line, "shtc3_sda", 0) < 0) {
        perror("Failed to request SDA line");
        gpiod_line_release(sda_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(scl_line, "shtc3_scl", 0) < 0) {
        perror("Failed to request SCL line");
        gpiod_line_release(sda_line);
        gpiod_line_release(scl_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        gpiod_line_release(sda_line);
        gpiod_line_release(scl_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SHTC3_I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        gpiod_line_release(sda_line);
        gpiod_line_release(scl_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_file = fopen("shtc3_environment.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        gpiod_line_release(sda_line);
        gpiod_line_release(scl_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        if (shtc3_read_data(&data) == 0) {
            float temp = data.temp_raw * 0.01 - 40.0;
            float hum = data.hum_raw * 0.01;
            if (temp >= -40.0 && temp <= 125.0 && hum >= 0.0 && hum <= 100.0) {
                printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp, hum);
                shtc3_log_data(&data);
            } else {
                fprintf(stderr, "Out-of-range value\n");
            }
        }
        sleep(5);
    }

    shtc3_cleanup();
    return EXIT_SUCCESS;
}

