#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define I2C_CHIP "gpiochip0"
#define I2C_LINE 1
#define TMP117_ADDRESS 0x48
#define TMP117_TEMP_REG 0x00
#define MAX_RETRIES 3

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static int i2c_fd;

void handle_sigint(int sig) {
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(0);
}

int read_temperature(int i2c_fd) {
    uint8_t buffer[2];
    if (read(i2c_fd, buffer, sizeof(buffer)) != sizeof(buffer)) {
        perror("Failed to read temperature from sensor");
        return -1;
    }
    int16_t raw_temp = (buffer[0] << 8) | buffer[1];
    float temperature = (float)raw_temp * 0.0625;
    return (int)temperature;
}

int main() {
    signal(SIGINT, handle_sigint);

    for (int retry = 0; retry < MAX_RETRIES; retry++) {
        chip = gpiod_chip_open(I2C_CHIP);
        if (!chip) {
            perror("Failed to open GPIO chip");
            continue;
        }

        line = gpiod_chip_get_line(chip, I2C_LINE);
        if (!line) {
            perror("Failed to get GPIO line");
            gpiod_chip_close(chip);
            continue;
        }

        if (gpiod_line_request_output(line, "i2c_bus", 0) < 0) {
            perror("Failed to request GPIO line as output");
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            continue;
        }

        i2c_fd = open("/dev/i2c-1", O_RDWR);
        if (i2c_fd < 0) {
            perror("Failed to open I2C bus");
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            continue;
        }

        if (ioctl(i2c_fd, I2C_SLAVE, TMP117_ADDRESS) < 0) {
            perror("Failed to set I2C slave address");
            close(i2c_fd);
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            continue;
        }

        break;
    }

    if (retry == MAX_RETRIES) {
        fprintf(stderr, "Failed to initialize I2C bus after %d retries\n", MAX_RETRIES);
        return 1;
    }

    FILE *log_file = fopen("temperature_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    while (1) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        int temperature = read_temperature(i2c_fd);
        if (temperature >= 0) {
            fprintf(log_file, "%s, Temperature: %d C\n", timestamp, temperature);
        } else {
            fprintf(log_file, "%s, Temperature: N/A\n", timestamp);
        }

        fflush(log_file);
        sleep(1);
    }

    fclose(log_file);
    close(i2c_fd);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

