#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x40
#define SAMPLE_INTERVAL 1
#define STALE_DATA_THRESHOLD 2

typedef struct {
    int flow;
    int temperature;
} SensorData;

void handle_sigint(int sig) {
    exit(0);
}

void handle_sigterm(int sig) {
    exit(0);
}

int read_sensor_data(struct gpiod_chip *chip, SensorData *data) {
    uint8_t buffer[4];
    int ret = gpiod_chip_i2c_read(chip, I2C_ADDRESS, buffer, sizeof(buffer));
    if (ret != sizeof(buffer)) {
        perror("Failed to read from sensor");
        return -1;
    }

    data->flow = (buffer[0] << 8) | buffer[1];
    data->temperature = (buffer[2] << 4) | (buffer[3] >> 4);

    return 0;
}

int main() {
    struct gpiod_chip *chip;
    FILE *log_file;
    SensorData data;
    int stale_data_count = 0;

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    chip = gpiod_chip_open(I2C_BUS);
    if (!chip) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    log_file = fopen("flow_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        if (stale_data_count < STALE_DATA_THRESHOLD) {
            if (read_sensor_data(chip, &data) == 0) {
                stale_data_count = 0;
            } else {
                stale_data_count++;
            }
        }

        if (stale_data_count >= STALE_DATA_THRESHOLD) {
            fprintf(stderr, "Sensor data stale, attempting re-initialization...\n");
            gpiod_chip_close(chip);
            chip = gpiod_chip_open(I2C_BUS);
            if (!chip) {
                perror("Failed to re-open I2C bus");
                fclose(log_file);
                return EXIT_FAILURE;
            }
            stale_data_count = 0;
        }

        fprintf(log_file, "%ld,%d,%d\n", time(NULL), data.flow, data.temperature);
        fflush(log_file);

        sleep(SAMPLE_INTERVAL);
    }

    fclose(log_file);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

