#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 4
#define DHT11_START_PULSE_US 18000
#define DHT11_RESPONSE_PULSE_US 80
#define DHT11_DATA_BIT_PULSE_US 50
#define DHT11_DATA_0_PULSE_US 26
#define DHT11_DATA_1_PULSE_US 70
#define DHT11_MIN_INTERVAL_S 2
#define DHT11_CHECKSUM_INDEX 40

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int read_dht11(struct gpiod_chip *chip, struct gpiod_line *line, uint8_t *data) {
    struct timespec start, end;
    int i, bit, bit_count = 0;

    // Generate start signal
    gpiod_line_set_value(line, 0);
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (clock_gettime(CLOCK_MONOTONIC, &end) < 0) {
        if (end.tv_sec - start.tv_sec >= 18) {
            fprintf(stderr, "Timeout: Start signal not received\n");
            return -1;
        }
    }
    gpiod_line_set_value(line, 1);

    // Wait for response
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_line_get_value(line) == 0) {
        if (clock_gettime(CLOCK_MONOTONIC, &end) < 0) {
            if (end.tv_sec - start.tv_sec >= 0.08) {
                fprintf(stderr, "Timeout: Response not received\n");
                return -1;
            }
        }
    }

    // Read data bits
    for (i = 0; i < 40; i++) {
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpiod_line_get_value(line) == 0) {
            if (clock_gettime(CLOCK_MONOTONIC, &end) < 0) {
                if (end.tv_sec - start.tv_sec >= 0.05) {
                    fprintf(stderr, "Timeout: Data bit %d not received\n", i);
                    return -1;
                }
            }
        }
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpiod_line_get_value(line) == 1) {
            if (clock_gettime(CLOCK_MONOTONIC, &end) < 0) {
                if (end.tv_sec - start.tv_sec >= 0.07) {
                    fprintf(stderr, "Timeout: Data bit %d not received\n", i);
                    return -1;
                }
            }
        }
        if (clock_gettime(CLOCK_MONOTONIC, &end) < 0) {
            if (end.tv_sec - start.tv_sec >= 0.05) {
                fprintf(stderr, "Timeout: Data bit %d not received\n", i);
                return -1;
            }
        }
        if (end.tv_sec - start.tv_sec >= 0.07) {
            bit = 1;
        } else {
            bit = 0;
        }
        data[bit_count / 8] |= (bit << (7 - (bit_count % 8)));
        bit_count++;
    }

    // Verify checksum
    if (data[0] + data[1] + data[2] + data[3] != data[4]) {
        fprintf(stderr, "Checksum error\n");
        return -1;
    }

    return 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    uint8_t data[5];
    FILE *file;
    struct timespec now;
    char timestamp[20];

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "dht11", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    file = fopen("dht11_readings.txt", "a");
    if (!file) {
        perror("Failed to open file for writing");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        if (read_dht11(chip, line, data) == 0) {
            clock_gettime(CLOCK_MONOTONIC, &now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", gmtime(&now.tv_sec));
            fprintf(file, "%s, Humidity: %d.%d, Temperature: %d.%d\n", timestamp, data[0], data[1], data[2], data[3]);
            fflush(file);
        }
        sleep(DHT11_MIN_INTERVAL_S);
    }

    fclose(file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

