#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define SHT31_I2C_ADDRESS 0x44
#define SHT31_MEASUREMENT_CMD 0x2400
#define SHT31_CRC8_POLYNOMIAL 0x31
#define SHT31_CRC8_INITIAL 0xFF

struct sht31_data {
    struct gpiod_chip *chip;
    struct gpiod_line *sda;
    struct gpiod_line *scl;
    FILE *log_file;
};

void log_error(const char *message) {
    time_t now = time(NULL);
    fprintf(stderr, "%s: %s\n", ctime(&now), message);
}

void log_temperature_humidity(struct sht31_data *data, float temperature, float humidity) {
    time_t now = time(NULL);
    fprintf(data->log_file, "%s,%.2f,%.2f\n", ctime(&now), temperature, humidity);
    fflush(data->log_file);
}

int calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = SHT31_CRC8_INITIAL;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SHT31_CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

