#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x5A
#define SENSOR_READ_INTERVAL 2

struct sensor_data {
    float pressure;
    float temperature;
};

struct sensor_data read_sensor_data(int fd) {
    struct sensor_data data;
    uint8_t buffer[6];

    if (read(fd, buffer, sizeof(buffer)) != sizeof(buffer)) {
        perror("Failed to read from sensor");
        data.pressure = -1.0;
        data.temperature = -1.0;
        return data;
    }

    data.pressure = (buffer[0] << 8 | buffer[1]) * 0.01;
    data.temperature = (buffer[2] << 8 | buffer[3]) * 0.01;

    return data;
}

void log_data(const struct sensor_data data, FILE *log_file) {
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline character

    fprintf(log_file, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n", timestamp, data.pressure, data.temperature);
    fflush(log_file);
}

void cleanup(int fd, FILE *log_file) {
    if (log_file) {
        fclose(log_file);
    }
    if (fd >= 0) {
        close(fd);
    }
}

void handle_signal(int sig) {
    cleanup(-1, NULL);
    exit(0);
}

int main() {
    struct gpiod_chip *chip;
    int fd;
    FILE *log_file;
    struct sensor_data data;

    // Initialize signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open log file
    log_file = fopen("pressure_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    // Open I2C bus
    chip = gpiod_chip_open(I2C_BUS);
    if (!chip) {
        perror("Failed to open I2C bus");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    fd = gpiod_chip_get_fd(chip);
    if (fd < 0) {
        perror("Failed to get I2C file descriptor");
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        data = read_sensor_data(fd);
        if (data.pressure >= 0.0 && data.temperature >= 0.0) {
            log_data(data, log_file);
        } else {
            log_data((struct sensor_data){-1.0, -1.0}, log_file);
        }
        sleep(SENSOR_READ_INTERVAL);
    }

    // Cleanup
    cleanup(fd, log_file);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

