#include <gpiod.h>

#define LM75B_I2C_ADDRESS 0x48
#define LM75B_TEMP_REG 0x00
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 18
#define BUFFER_SIZE 60
#define Hysteresis 2.0

struct {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int buffer[BUFFER_SIZE];
    int head;
    int count;
} state = {0};

void handle_sigint(int sig) {
    if (state.line) {
        gpiod_line_set_value(state.line, 0);
    }
    if (state.chip) {
        gpiod_chip_close(state.chip);
    }
    exit(0);
}

int read_lm75b_temperature() {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, LM75B_I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(fd);
        return -1;
    }

    uint8_t data[2];
    if (read(fd, data, 2) != 2) {
        perror("Failed to read from I2C device");
        close(fd);
        return -1;
    }

    close(fd);

    int temp = (data[0] << 8) | data[1];
    return temp * 0.0625;
}

void update_circular_buffer(int value) {
    state.buffer[state.head] = value;
    state.head = (state.head + 1) % BUFFER_SIZE;
    if (state.count < BUFFER_SIZE) {
        state.count++;
    }
}

double compute_running_average() {
    int sum = 0;
    for (int i = 0; i < state.count; i++) {
        sum += state.buffer[i];
    }
    return (double)sum / state.count;
}

int main() {
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    state.chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!state.chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    state.line = gpiod_chip_get_line(state.chip, GPIO_LINE);
    if (!state.line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(state.chip);
        return 1;
    }

    if (gpiod_line_request_output(state.line, "lm75b_fan_control", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line as output\n");
        gpiod_chip_close(state.chip);
        return 1;
    }

    while (1) {
        int temperature = read_lm75b_temperature();
        if (temperature < 0) {
            continue;
