        update_circular_buffer(temperature);
        double average = compute_running_average();

        if (average > 28.0) {
            gpiod_line_set_value(state.line, 1);
        } else if (average < 26.0) {
            gpiod_line_set_value(state.line, 0);
        }

        sleep(1);
    }

    gpiod_line_release(state.line);
    gpiod_chip_close(state.chip);
    return 0;
}

