#define SDP810_READ_CMD 0x03
#define SDP810_CRC_POLYNOMIAL 0x31
#define SDP810_CRC_INITIAL 0xFF
#define LOG_FILE "airflow.log"

static struct gpiod_chip *chip = NULL;
static FILE *log_file = NULL;
