#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x48
#define LED_PIN 17
#define LED_HIGH_TEMP 28.0
#define LED_LOW_TEMP 27.0
#define Hysteresis 0.5

static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;

void cleanup() {
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

void handle_signal(int signum) {
    cleanup();
    exit(signum);
}

int read_temperature() {
    uint8_t buffer[2];
    if (read(i2c_fd, buffer, sizeof(buffer)) != sizeof(buffer)) {
        perror("Failed to read temperature from STTS2004");
        return -1;
    }
    int16_t raw_temp = (buffer[0] << 8) | buffer[1];
    return (raw_temp * 0.0625);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open I2C device
    if ((i2c_fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Request LED line
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get LED line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Configure LED line as output
    if (gpiod_line_request_output(led_line, "temperature_led", 0) < 0) {
        perror("Failed to request LED line as output");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    double last_led_state = -1.0;
    while (1) {
        int temperature = read_temperature();
        if (temperature < 0) {
            continue;
        }

        double current_led_state = (temperature > LED_HIGH_TEMP) ? 1.0 : 0.0;
        if (current_led_state != last_led_state) {
            if (gpiod_line_set_value(led_line, current_led_state) < 0) {
                perror("Failed to set LED state");
                cleanup();
                return EXIT_FAILURE;
            }
            last_led_state = current_led_state;
        }

        printf("Temperature: %.2f°C\n", temperature);
        sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

