#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define SDP800_ADDRESS 0x60
#define SDP800_MEASURE_CMD 0x00
#define SDP800_READ_DATA_CMD 0x01
#define SDP800_CRC8_POLYNOMIAL 0x31
#define SDP800_CRC8_INIT 0xFF

struct sdp800_data {
    uint16_t pressure;
    int16_t temperature;
    uint32_t scale_factor;
};

static struct gpiod_chip *chip;
static FILE *log_file;

static void cleanup(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(signum);
}

static uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = SDP800_CRC8_INIT;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SDP800_CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int read_sdp800_data(struct sdp800_data *data) {
    int ret;
    uint8_t buffer[9];

    // Start measurement
    ret = gpiod_line_set_value(gpiod_chip_get_line(chip, 0), 1);
    if (ret < 0) {
        perror("Failed to set measurement line");
        return ret;
    }
    usleep(45000); // Wait at least 45 ms

    // Read data
    ret = gpiod_line_set_value(gpiod_chip_get_line(chip, 0), 0);
    if (ret < 0) {
        perror("Failed to reset measurement line");
        return ret;
    }

    ret = gpiod_chip_read(chip, buffer, sizeof(buffer));
    if (ret < 0) {
        perror("Failed to read data from SDP800");
        return ret;
    }

    // Validate CRC
    if (buffer[2] != calculate_crc8(buffer, 2) ||
        buffer[5] != calculate_crc8(buffer + 3, 2)) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Parse data
    data->pressure = (buffer[0] << 8) | buffer[1];
    data->temperature = (buffer[3] << 8) | buffer[4];
    data->scale_factor = (buffer[6] << 16) | (buffer[7] << 8) | buffer[8];

    return 0;
}

int main() {
    struct sdp800_data data;
    struct timespec ts;
    char timestamp[20];

    // Initialize GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Initialize log file
    log_file = fopen("flow_data.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up signal handler
    signal(SIGINT, cleanup);

    while (1) {
        if (read_sdp800_data(&data) < 0) {
            fprintf(stderr, "Failed to read data from SDP800\n");
            continue;
        }

        // Get current timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
            perror("Failed to get current time");
            continue;
        }

        // Format timestamp
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        // Log data
        fprintf(log_file, "%s, Pressure: %d Pa, Temperature: %d C, Scale Factor: %u\n",
                timestamp, data.pressure, data.temperature, data.scale_factor);
        fflush(log_file);

        // Sleep for a while before the next reading
        sleep(1);
    }

    cleanup(0);
    return EXIT_SUCCESS;
}

