#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define HDC1080_I2C_ADDR 0x40
#define HDC1080_TEMP_REG 0x00
#define HDC1080_HUMIDITY_REG 0x01
#define HDC1080_CONFIG_REG 0x02
#define HDC1080_CONFIG_VAL 0x1000

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int read_hdc1080_temperature(int fd) {
    uint16_t temp_raw;
    if (read(fd, &temp_raw, 2) != 2) {
        perror("Failed to read temperature from HDC1080");
        return -1;
    }
    return (temp_raw * 165.0 / 65536.0) - 40;
}

int read_hdc1080_humidity(int fd) {
    uint16_t humidity_raw;
    if (read(fd, &humidity_raw, 2) != 2) {
        perror("Failed to read humidity from HDC1080");
        return -1;
    }
    return (humidity_raw * 100.0 / 65536.0);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int i2c_fd;
    time_t now;
    struct tm *tm_info;
    char timestamp[20];
    char log_entry[100];

    // Initialize signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, HDC1080_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize HDC1080
    uint16_t config_val = HDC1080_CONFIG_VAL;
    if (write(i2c_fd, &config_val, 2) != 2) {
        perror("Failed to initialize HDC1080");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        // Wait for conversion to complete
        usleep(20000);

        // Read temperature and humidity
        int temperature = read_hdc1080_temperature(i2c_fd);
        int humidity = read_hdc1080_humidity(i2c_fd);

        if (temperature != -1 && humidity != -1) {
            // Get current time
            time(&now);
            tm_info = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

            // Format log entry
            snprintf(log_entry, sizeof(log_entry), "%s,%d,%d\n", timestamp, temperature, humidity);

            // Append log entry to file
            FILE *log_file = fopen("enviro_log.txt", "a");
            if (log_file != NULL) {
                fputs(log_entry, log_file);
                fclose(log_file);
            } else {
                perror("Failed to open log file");
            }
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Close I2C bus
    close(i2c_fd);

    return EXIT_SUCCESS;
}

