#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE "/dev/i2c-1"
#define STS40_ADDRESS 0x60
#define STS40_MEASURE_CMD 0x21
#define STS40_DATA_LEN 3
#define CRC8_POLYNOMIAL 0x31

void log_temperature(int fd, FILE *log_file) {
    uint8_t cmd[1] = {STS40_MEASURE_CMD};
    if (write(fd, cmd, 1) != 1) {
        fprintf(stderr, "Failed to send measurement command: %s\n", strerror(errno));
        return;
    }

    usleep(10000); // Wait 10 ms for conversion to complete

    uint8_t data[STS40_DATA_LEN];
    if (read(fd, data, STS40_DATA_LEN) != STS40_DATA_LEN) {
        fprintf(stderr, "Failed to read data: %s\n", strerror(errno));
        return;
    }

    uint16_t temperature_raw = (data[0] << 8) | data[1];
    uint8_t crc8 = data[2];

    uint8_t calculated_crc8 = 0xFF;
    for (int i = 0; i < 2; i++) {
        calculated_crc8 ^= temperature_raw >> (8 * i);
        for (int j = 0; j < 8; j++) {
            if (calculated_crc8 & 0x80) {
                calculated_crc8 = (calculated_crc8 << 1) ^ CRC8_POLYNOMIAL;
            } else {
                calculated_crc8 = calculated_crc8 << 1;
            }
        }
    }

    if (calculated_crc8 != crc8) {
        fprintf(stderr, "CRC mismatch: expected 0x%02X, got 0x%02X\n", crc8, calculated_crc8);
        return;
    }

    double temperature = -45.0 + 175.0 * temperature_raw / 65536.0;

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", tm_info);

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file);
}

void signal_handler(int signum) {
    static int handled = 0;
    if (handled) {
        exit(signum);
    }
    handled = 1;
    printf("Received signal %d, cleaning up...\n", signum);
}

int main() {
    int fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, STS40_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("temperature_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        log_temperature(fd, log_file);
        sleep(5);
    }

    fclose(log_file);
    close(fd);
    return EXIT_SUCCESS;
}

