#define I2C_ADDRESS 0x28
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL 0xFF

struct i2c_device {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    FILE *log_file;
};

void crc8_update(uint8_t *crc, uint8_t data) {
    *crc ^= data;
    for (int i = 0; i < 8; i++) {
        if (*crc & 0x80) {
            *crc = (*crc << 1) ^ CRC8_POLYNOMIAL;
        } else {
            *crc = (*crc << 1);
        }
    }
}

int read_crc8(uint8_t *data, size_t length) {
    uint8_t crc = CRC8_INITIAL;
    for (size_t i = 0; i < length; i++) {
        crc8_update(&crc, data[i]);
    }
    return crc;
}

void log_sample(struct i2c_device *dev, time_t timestamp, int16_t pressure, int8_t temperature, uint32_t scale_factor) {
