void crc8_update(uint8_t *crc, uint8_t data) {
    *crc ^= data;
    for (int i = 0; i < 8; i++) {
        if (*crc & 0x80) {
            *crc = (*crc << 1) ^ CRC8_POLYNOMIAL;
        } else {
            *crc = (*crc << 1);
        }
    }
}

int read_crc8(uint8_t *data, size_t length) {
    uint8_t crc = CRC8_INITIAL;
    for (size_t i = 0; i < length; i++) {
        crc8_update(&crc, data[i]);
    }
    return crc;
}

void log_sample(struct i2c_device *dev, time_t timestamp, int16_t pressure, int8_t temperature, uint32_t scale_factor) {
    fprintf(dev->log_file, "%ld,%d,%d,%u\n", timestamp, pressure, temperature, scale_factor);
    fflush(dev->log_file);
}

void log_error(struct i2c_device *dev, time_t timestamp, const char *message) {
    fprintf(dev->log_file, "%ld,ERROR,%s\n", timestamp, message);
    fflush(dev->log_file);
}

void handle_sigint(int sig) {
    struct i2c_device *dev = (struct i2c_device *)sig;
    if (dev->line) {
        gpiod_line_release(dev->line);
    }
    if (dev->chip) {
        gpiod_chip_close(dev->chip);
    }
    if (dev->log_file) {
        fclose(dev->log_file);
    }
    exit(EXIT_FAILURE);
}

