    struct gpiod_line_request_config config = {
        .consumer = "i2c-sdp810",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
    };
    time_t timestamp;
    uint8_t buffer[9];
    int16_t pressure;
    int8_t temperature;
    uint32_t scale_factor;
    uint8_t crc;

