    dev.chip = gpiod_chip_open(I2C_CHIP);
    if (!dev.chip) {
        perror("Failed to open I2C chip");
        exit(EXIT_FAILURE);
    }

    dev.line = gpiod_chip_get_line(dev.chip, I2C_LINE);
    if (!dev.line) {
        perror("Failed to get I2C line");
        gpiod_chip_close(dev.chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request(dev.line, &config) < 0) {
        perror("Failed to request I2C line");
        gpiod_chip_close(dev.chip);
        exit(EXIT_FAILURE);
    }

    // Initialize log file
    dev.log_file = fopen("hvac_pressure_log.txt", "a");
    if (!dev.log_file) {
        perror("Failed to open log file");
        gpiod_line_release(dev.line);
        gpiod_chip_close(dev.chip);
        exit(EXIT_FAILURE);
    }

    // Register signal handler
    signal(SIGINT, (void (*)(int))handle_sigint);

    while (1) {
        timestamp = time(NULL);

        // Trigger measurement
        if (gpiod_line_set_value(dev.line, 1) < 0) {
            log_error(&dev, timestamp, "Failed to trigger measurement");
            continue;
        }

        // Wait for measurement to complete
        usleep(50000);

        // Read data
        if (gpiod_line_set_value(dev.line, 0) < 0) {
