#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <pthread.h>

#define SCD40_I2C_ADDRESS 0x61
#define SCD40_BUFFER_SIZE 100
#define SCD40_LOG_DIR "/var/log/scd40_data"
#define SCD40_LOG_FILE "scd40_data.csv"
#define SCD40_ERROR_LOG "/var/log/scd40_error.log"
#define SCD40_CRC8_POLYNOMIAL 0x31
#define SCD40_CRC8_INITIAL 0xFF

typedef struct {
    uint16_t co2;
    float temperature;
    float humidity;
    time_t timestamp;
} SCD40Reading;

SCD40Reading buffer[SCD40_BUFFER_SIZE];
int buffer_head = 0;
int buffer_tail = 0;
int buffer_count = 0;
pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;
volatile sig_atomic_t running = 1;

void log_error(const char *message) {
    FILE *log_file = fopen(SCD40_ERROR_LOG, "a");
    if (log_file) {
        time_t now = time(NULL);
        fprintf(log_file, "%s: %s\n", ctime(&now), message);
        fclose(log_file);
    }
}

uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = SCD40_CRC8_INITIAL;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SCD40_CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_scd40(SCD40Reading *reading) {
    int ret;
    uint8_t buffer[6];
    ret = gpiod_i2c_read(SCD40_I2C_ADDRESS, buffer, sizeof(buffer));
    if (ret != sizeof(buffer)) {
        log_error("Failed to read from SCD40 sensor");
        return -1;
    }

    uint8_t crc = calculate_crc8(buffer, 5);
    if (crc != buffer[5]) {
        log_error("CRC check failed for SCD40 sensor");
        return -1;
    }

    reading->co2 = (buffer[0] << 8) | buffer[1];
    reading->temperature = (buffer[2] * 16 + buffer[3] / 100.0) - 45.0;
    reading->humidity = (buffer[4] * 100.0) / 1024.0;
    reading->timestamp = time(NULL);

    return 0;
}

void *logging_thread(void *arg) {
    while (running) {
        sleep(60);
        pthread_mutex_lock(&buffer_mutex);
        while (buffer_count > 0) {
            SCD40Reading reading = buffer[buffer_tail];
            buffer_tail = (buffer_tail + 1) % SCD40_BUFFER_SIZE;
            buffer_count--;

            FILE *log_file = fopen(SCD40_LOG_DIR "/" SCD40_LOG_FILE, "a");
            if (log_file) {
                fprintf(log_file, "%ld,%d,%.2f,%.2f\n", reading.timestamp, reading.co2, reading.temperature, reading.humidity);
                fclose(log_file);
            }
        }
        pthread_mutex_unlock(&buffer_mutex);
    }
    return NULL;
}

void stop_scd40() {
    uint8_t command[2] = {0x21, 0x04};
    gpiod_i2c_write(SCD40_I2C_CHIP, SCD40_I2C_ADDRESS, command, sizeof(command));
}

int main() {
    struct gpiod_chip *chip;
    int ret;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        log_error("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    ret = gpiod_i2c_open(chip, SCD40_I2C_ADDRESS);
    if (ret < 0) {
        log_error("Failed to open I2C device");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    pthread_t log_thread;
    ret = pthread_create(&log_thread, NULL, logging_thread, NULL);
    if (ret != 0) {
        log_error("Failed to create logging thread");
        gpiod_i2c_close(chip);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    signal(SIGINT, (void (*)(int))stop_scd40);

    sleep(1);

    while (running) {
        SCD40Reading reading;
        if (read_scd40(&reading) == 0) {
            pthread_mutex_lock(&buffer_mutex);
            if (buffer_count < SCD40_BUFFER_SIZE) {
                buffer[buffer_head] = reading;
                buffer_head = (buffer_head + 1) % SCD40_BUFFER_SIZE;
                buffer_count++;
            } else {
                log_error("Buffer overflow");
            }
            pthread_mutex_unlock(&buffer_mutex);
        }
        sleep(5);
    }

    stop_scd40();
    pthread_join(log_thread, NULL);

    pthread_mutex_lock(&buffer_mutex);
    while (buffer_count > 0) {
        SCD40Reading reading = buffer[buffer_tail];
        buffer_tail = (buffer_tail + 1) % SCD40_BUFFER_SIZE;
        buffer_count--;

        FILE *log_file = fopen(SCD40_LOG_DIR "/" SCD40_LOG_FILE, "a");
        if (log_file) {
            fprintf(log_file, "%ld,%d,%.2f,%.2f\n", reading.timestamp, reading.co2, reading.temperature, reading.humidity);
            fclose(log_file);
        }
    }
    pthread_mutex_unlock(&buffer_mutex);

    gpiod_i2c_close(chip);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

