#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x28
#define SDP810_TRIGGER 0x00
#define SDP810_READ 0x01
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL 0xFF

struct sdp810_data {
    uint16_t pressure;
    int16_t temperature;
    uint16_t scale_factor;
};

static int i2c_fd = -1;
static FILE *log_file = NULL;

static uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = CRC8_INITIAL;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int read_sdp810_data(struct sdp810_data *data) {
    uint8_t buffer[9];
    if (write(i2c_fd, &SDP810_TRIGGER, 1) != 1) {
        perror("Failed to trigger SDP810");
        return -1;
    }
    usleep(45000);
    if (read(i2c_fd, buffer, 9) != 9) {
        perror("Failed to read SDP810 data");
        return -1;
    }

    uint8_t crc8 = calculate_crc8(buffer, 7);
    if (crc8 != buffer[7]) {
        fprintf(stderr, "CRC8 error in pressure data\n");
        return -1;
    }

    data->pressure = (buffer[0] << 8) | buffer[1];
    data->temperature = (buffer[2] << 8) | buffer[3];
    crc8 = calculate_crc8(buffer + 4, 3);
    if (crc8 != buffer[6]) {
        fprintf(stderr, "CRC8 error in temperature data\n");
        return -1;
    }

    data->scale_factor = (buffer[4] << 8) | buffer[5];
    crc8 = calculate_crc8(buffer + 7, 1);
    if (crc8 != buffer[8]) {
        fprintf(stderr, "CRC8 error in scale factor data\n");
        return -1;
    }

    return 0;
}

static void log_data(const struct sdp810_data *data) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d,%d,%d\n",
            tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
            tm->tm_hour, tm->tm_min, tm->tm_sec,
            data->pressure, data->temperature);
}

static void sigint_handler(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(signum);
}

int main() {
    struct sdp810_data data;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;

    signal(SIGINT, sigint_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("sdp810_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize GPIO for I2C
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (chip == NULL) {
        perror("Failed to open GPIO chip");
        fclose(log_file);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, 3);
    if (line == NULL) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        fclose(log_file);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "i2c_scl", 0) < 0) {
        perror("Failed to request GPIO line for SCL");
        gpiod_chip_close(chip);
        fclose(log_file);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "i2c_sda", 0) < 0) {
        perror("Failed to request GPIO line for SDA");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        fclose(log_file);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        if (read_sdp810_data(&data) == 0) {
            log_data(&data);
        }
        sleep(1);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(log_file);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

