    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d,%d,%d\n",
            tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
            tm->tm_hour, tm->tm_min, tm->tm_sec,
            data->pressure, data->temperature);
}

static void sigint_handler(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(signum);
}

int main() {
    struct sdp810_data data;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;

    signal(SIGINT, sigint_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("sdp810_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize GPIO for I2C
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (chip == NULL) {
        perror("Failed to open GPIO chip");
        fclose(log_file);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, 3);
    if (line == NULL) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        fclose(log_file);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "i2c_scl", 0) < 0) {
        perror("Failed to request GPIO line for SCL");
        gpiod_chip_close(chip);
        fclose(log_file);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "i2c_sda", 0) < 0) {
        perror("Failed to request GPIO line for SDA");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        fclose(log_file);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        if (read_sdp810_data(&data) == 0) {
            log_data(&data);
        }
        sleep(1);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(log_file);
    close(i2c_fd);

    return EXIT_SUCCESS;
}
