        now = time(NULL);
        tm_info = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", tm_info);

        // Print the reading to stdout
        printf("%s Pressure: %d Temperature: %d\n", timestamp, buffer[0], buffer[1]);

        // Write the reading to the file
        fprintf(file, "%s Pressure: %d Temperature: %d\n", timestamp, buffer[0], buffer[1]);
        fflush(file);
    }

    // Close the file
    fclose(file);

    // Release the I2C line
    gpiod_line_release(line);

    // Close the I2C chip
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

