#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x76
#define I2C_READ_SIZE 6
#define LED_PIN 17
#define LED_ON_TIME 500000
#define LED_OFF_TIME 500000
#define LOW_PRESSURE_THRESHOLD 95000
#define NORMAL_Blink_RATE 1000000
#define LOW_PRESSURE_Blink_RATE 100000

static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;

void i2c_close() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

void gpio_release() {
    if (led_line) {
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

void sigint_handler(int signum) {
    i2c_close();
    gpio_release();
    exit(signum);
}

uint16_t read_sensor_data(uint8_t *buffer, size_t size) {
    if (write(i2c_fd, &I2C_ADDRESS, 1) != 1) {
        perror("Failed to write I2C address");
        return 0;
    }
    if (read(i2c_fd, buffer, size) != size) {
        perror("Failed to read from I2C sensor");
        return 0;
    }
    return 1;
}

uint16_t calculate_crc(uint8_t *data, size_t length) {
    uint16_t crc = 0xFFFF;
    for (size_t i = 0; i < length; i++) {
        crc ^= (uint16_t)data[i] << 8;
        for (int j = 0; j < 8; j++) {
            if (crc & 0x8000) {
                crc = (crc << 1) ^ 0x1021;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

void blink_led(uint32_t on_time, uint32_t off_time) {
    if (gpiod_line_set_value(led_line, 1) < 0) {
        perror("Failed to set LED line value");
        return;
    }
    usleep(on_time);
    if (gpiod_line_set_value(led_line, 0) < 0) {
        perror("Failed to set LED line value");
        return;
    }
    usleep(off_time);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to set SIGINT handler");
        return EXIT_FAILURE;
    }

    if ((i2c_fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        i2c_close();
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        i2c_close();
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        i2c_close();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, "pressure_sensor_led", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        i2c_close();
        return EXIT_FAILURE;
    }

    uint8_t buffer[I2C_READ_SIZE];
    uint16_t pressure, temperature, crc;
    int low_pressure = 0;

    while (1) {
        if (!read_sensor_data(buffer, I2C_READ_SIZE)) {
            continue;
        }

        pressure = (buffer[0] << 8) | buffer[1];
        temperature = (buffer[2] << 8) | buffer[3];
        crc = (buffer[4] << 8) | buffer[5];

        if (calculate_crc(buffer, 4) != crc) {
            fprintf(stderr, "CRC mismatch\n");
            continue;
        }

        if (pressure < LOW_PRESSURE_THRESHOLD) {
            low_pressure = 1;
        } else {
            low_pressure = 0;
        }

        blink_led(low_pressure ? LOW_PRESSURE_Blink_RATE : NORMAL_Blink_RATE, low_pressure ? LOW_PRESSURE_Blink_RATE : NORMAL_Blink_RATE);

        usleep(1000000);
    }

    gpio_release();
    i2c_close();
    return EXIT_SUCCESS;
}

