#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <sys/ioctl.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x5A
#define FAN_PIN 18
#define Hysteresis 2
#define RetryCount 3
#define RetryDelay 10

static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *fan_line = NULL;

void log_temperature(double ambient, double object) {
    FILE *log_file = fopen("temperature_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    fprintf(log_file, "%s, Ambient: %.2f°C, Object: %.2f°C\n", ctime(&now), ambient, object);
    fclose(log_file);
}

double read_temperature(int i2c_fd, uint8_t reg) {
    uint8_t data[2];
    for (int i = 0; i < RetryCount; i++) {
        if (read(i2c_fd, data, 2) == 2) {
            return (data[0] << 8) | data[1];
        }
        usleep(RetryDelay * 1000);
    }
    return -1;
}

void control_fan(double object_temp) {
    if (object_temp > 30) {
        gpiod_line_set_value(fan_line, 1);
    } else if (object_temp < 28) {
        gpiod_line_set_value(fan_line, 0);
    }
}

void handle_signal(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (fan_line != NULL) {
        gpiod_line_set_value(fan_line, 0);
        gpiod_line_release(fan_line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    exit(signum);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize I2C
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    fan_line = gpiod_chip_get_line(chip, FAN_PIN);
    if (fan_line == NULL) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(fan_line, "fan_control", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(fan_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        double ambient_temp = read_temperature(i2c_fd, 0x06) * 0.02;
        double object_temp = read_temperature(i2c_fd, 0x07) * 0.02;

        if (ambient_temp >= 0 && object_temp >= 0) {
            log_temperature(ambient_temp, object_temp);
            control_fan(object_temp);
        }

        sleep(2);
    }

    return EXIT_SUCCESS;
}

