#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x44
#define MEASUREMENT_CONFIG_REG 0x00
#define MAX_RETRIES 5
#define TIMEOUT_MS 500
#define READ_INTERVAL 5

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

int read_temperature_and_humidity(struct gpiod_chip *chip, int i2c_fd) {
    uint8_t config[2];
    uint8_t data[4];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        // Start measurement
        config[0] = MEASUREMENT_CONFIG_REG;
        config[1] = 0x00; // Start temperature and humidity measurement
        if (write(i2c_fd, config, 2) != 2) {
            perror("Failed to start measurement");
            return -1;
        }

        // Wait for measurement to complete
        struct timespec start, end;
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (1) {
            if (read(i2c_fd, config, 1) != 1) {
                perror("Failed to read measurement config");
                return -1;
            }
            if (!(config[0] & 0x01)) {
                break;
            }
            clock_gettime(CLOCK_MONOTONIC, &end);
            if ((end.tv_sec - start.tv_sec) * 1000 + (end.tv_nsec - start.tv_nsec) / 1000000 > TIMEOUT_MS) {
                fprintf(stderr, "Measurement timeout\n");
                return -1;
            }
            usleep(10000); // 10 ms delay
        }

        // Read temperature and humidity data
        if (read(i2c_fd, data, 4) != 4) {
            perror("Failed to read temperature and humidity data");
            return -1;
        }

        // Calculate temperature and humidity
        float temperature = (data[0] << 8 | data[1]) / 65536.0 * 165.0 - 40.0;
        float humidity = (data[2] << 8 | data[3]) / 65536.0 * 100.0;

        printf("Temperature: %.2f°C, Humidity: %.2f%%\n", temperature, humidity);

        return 0;
    }

    fprintf(stderr, "Failed to read temperature and humidity after %d retries\n", MAX_RETRIES);
    return -1;
}

int main() {
    struct gpiod_chip *chip;
    int i2c_fd;
    int ret;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C bus
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (!stop_flag) {
        ret = read_temperature_and_humidity(chip, i2c_fd);
        if (ret < 0) {
            // Retry on error
            sleep(1);
        } else {
            sleep(READ_INTERVAL);
        }
    }

    // Clean shutdown
    close(i2c_fd);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

