```c
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x28
#define SDP800_MEASURE_CMD 0x21
#define SDP800_READ_CMD 0x03
#define SDP800_CRC8_POLYNOMIAL 0x31
#define SDP800_CRC8_INITIAL 0xFF

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

void cleanup(int signum) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(signum);
}

uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = SDP800_CRC8_INITIAL;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SDP800_CRC8_POLYNOMIAL;
            } else {
                crc = crc << 1;
            }
        }
    }
    return crc;
}

int main() {
    signal(SIGINT, cleanup);

    // Open I2C bus
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open I2C chip");
        return EXIT_FAILURE;
    }

    // Request I2C line
    line = gpiod_chip_get_line(chip, 2); // Assuming I2C line 2 is used for I2C communication
    if (!line) {
        perror("Failed to get I2C line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request exclusive access to the line
    if (gpiod_line_request_output(line, "i2c", 0) < 0) {
        perror("Failed to request I2C line output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        // Send measure command
        if (gpiod_line_set_value(line, 1) < 0) {
            perror("Failed to set I2C line high");
            cleanup(EXIT_FAILURE);
        }
        usleep(45000); // Wait for 45 ms
        if (gpiod_line_set_value(line, 0) < 0) {
            perror("Failed to set I2C line low");
            cleanup(EXIT_FAILURE);
