#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <libgpiod/spi.h>

#define SPI_CHIP 0
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 500000
#define GPIO_PIN 17
#define LOG_FILE "reflow_log.csv"
#define PROFILE_FILE "profile.txt"
#define SAMPLE_RATE 1
#define SAMPLE_INTERVAL 1000000

struct pid_controller {
    double Kp, Ki, Kd;
    double setpoint;
    double integral;
    double prev_error;
};

struct pid_controller pid;

void signal_handler(int signum) {
    printf("Received signal %d, exiting...\n", signum);
    exit(EXIT_SUCCESS);
}

double read_temperature(int chip, int cs) {
    uint8_t tx[2] = {0x00, 0x00};
    uint8_t rx[2];
    int ret;

    ret = gpiod_spi_transfer(chip, cs, tx, 2, rx, 2, SAMPLE_INTERVAL);
    if (ret < 0) {
        perror("gpiod_spi_transfer");
        return -1;
    }

    uint16_t temp_raw = (rx[0] << 8) | rx[1];
    if (temp_raw & 0x4) {
        return -1; // Thermocouple open circuit
    }

    return (temp_raw >> 3) * 0.25;
}

void update_pid(double measured_temp) {
    double error = pid.setpoint - measured_temp;
    pid.integral += error * SAMPLE_RATE;
    double derivative = (error - pid.prev_error) / SAMPLE_RATE;

    double output = pid.Kp * error + pid.Ki * pid.integral + pid.Kd * derivative;
    pid.prev_error = error;

    if (output < 0) output = 0;
    if (output > 1) output = 1;

    // Assuming a PWM frequency of 100 Hz
    int duty_cycle = (int)(output * 100);
    gpiod_line_set_value(pid.ssr_line, duty_cycle);
}

void load_profile(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        char *token = strtok(line, ",");
        if (token) {
            int time_seconds = atoi(token);
            token = strtok(NULL, ",");
            if (token) {
                double target_temp_celsius = atof(token);
                printf("Profile: %d seconds, %f Celsius\n", time_seconds, target_temp_celsius);
                pid.setpoint = target_temp_celsius;
                sleep(time_seconds);
            }
        }
    }

    fclose(file);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *ssr_line;
    int ret;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        exit(EXIT_FAILURE);
    }

    ssr_line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!ssr_line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(ssr_line, "reflow_oven_ssr");
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    pid.Kp = 2.0;
    pid.Ki = 0.5;
    pid.Kd = 1.0;
    pid.integral = 0;
    pid.prev_error = 0;

    FILE *log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("fopen");
        gpiod_line_release(ssr_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    load_profile(PROFILE_FILE);

    while (1) {
        double measured_temp = read_temperature(SPI_CHIP, 0);
        if (measured_temp >= 0) {
            fprintf(log_file, "%f,%f\n", (double)time(NULL), measured_temp);
            update_pid(measured_temp);
        } else {
            fprintf(stderr, "Sensor absent or bus error\n");
        }

        sleep(SAMPLE_RATE);
    }

    fclose(log_file);
    gpiod_line_release(ssr_line);
    gpiod_chip_close(chip);

    return 0;
}

