#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define W1_BUS "/sys/bus/w1/devices/"
#define DS18B20_FAMILY "28"
#define RELAY_PIN 17
#define PWM_PIN 18
#define PWM_FREQ 1000
#define PWM_RANGE 100
#define LOG_INTERVAL 5

static struct gpiod_chip *chip;
static struct gpiod_line *relay_line, *pwm_line;
static FILE *log_file;

static void cleanup() {
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
        gpiod_line_release(relay_line);
    }
    if (pwm_line) {
        gpiod_line_set_value(pwm_line, 0);
        gpiod_line_release(pwm_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

static void signal_handler(int signum) {
    cleanup();
    exit(signum);
}

static int read_temperature(const char *device_path) {
    FILE *file = fopen(device_path, "r");
    if (!file) {
        perror("Failed to open sensor file");
        return -1;
    }

    char line[256];
    if (!fgets(line, sizeof(line), file)) {
        perror("Failed to read sensor data");
        fclose(file);
        return -1;
    }

    fclose(file);

    char *crc_start = strchr(line, ' ');
    if (!crc_start) {
        fprintf(stderr, "Invalid sensor data format\n");
        return -1;
    }

    crc_start++;
    char *end = strchr(crc_start, ' ');
    if (!end) {
        fprintf(stderr, "Invalid sensor data format\n");
        return -1;
    }

    *end = '\0';
    int temperature = atoi(crc_start);
    return temperature;
}

static void log_data(double temperature, double setpoint, double pid_output, int pwm_duty) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%d\n", timestamp, temperature, setpoint, pid_output, pwm_duty);
    fflush(log_file);
}

int main(int argc, char *argv[]) {
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <setpoint> <Kp> <Ki> <Kd>\n", argv[0]);
        return 1;
    }

    double setpoint = atof(argv[1]);
    double Kp = atof(argv[2]);
    double Ki = atof(argv[3]);
    double Kd = atof(argv[4]);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        perror("Failed to get relay line");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(relay_line, "greenhouse_relay", 0)) {
        perror("Failed to request relay line");
        cleanup();
        return 1;
    }

    pwm_line = gpiod_chip_get_line(chip, PWM_PIN);
    if (!pwm_line) {
        perror("Failed to get PWM line");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(pwm_line, "greenhouse_pwm", 0)) {
        perror("Failed to request PWM line");
        cleanup();
        return 1;
    }

    log_file = fopen("greenhouse.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    double integral = 0.0;
    double last_error = 0.0;
    double pwm_duty = 0.0;

    while (1) {
        char device_path[256];
        snprintf(device_path, sizeof(device_path), "%s28*/w1_slave", W1_BUS);
        DIR *dir = opendir(device_path);
        if (!dir) {
            perror("Failed to open 1-wire bus directory");
            cleanup();
            return 1;
        }

        struct dirent *entry;
        while ((entry = readdir(dir)) != NULL) {
            if (strncmp(entry->d_name, DS18B20_FAMILY, 2) == 0) {
                char sensor_path[256];
                snprintf(sensor_path, sizeof(sensor_path), "%s%s/w1_slave", W1_BUS, entry->d_name);
                int temperature = read_temperature(sensor_path);
                if (temperature != -1) {
                    double error = setpoint - temperature;
                    integral += error;
                    double derivative = error - last_error;
                    double pid_output = Kp * error + Ki * integral + Kd * derivative;
                    pwm_duty = (pid_output > 0) ? fmin(pid_output, PWM_RANGE) : 0;
                    gpiod_line_set_value(pwm_line, (int)pwm_duty);
                    gpiod_line_set_value(relay_line, (pwm_duty > 0) ? 1 : 0);
                    last_error = error;
                    log_data(temperature, setpoint, pid_output, (int)pwm_duty);
                    break;
                }
            }
        }

        closedir(dir);
        sleep(LOG_INTERVAL);
    }

    cleanup();
    return 0;
}

