This C program for a Raspberry Pi 3 Model B+ implements a PID-controlled greenhouse heater using a DS18B20 temperature sensor and a 12V heater driven through a relay and hardware PWM. The program reads the sensor periodically, validates the CRC of each DS18B20 reading, computes the PID output, sets the appropriate PWM duty cycle and relay state, and logs every 5 seconds to a file named `greenhouse.log`. The program installs SIGINT/SIGTERM handlers to cleanly release resources on any exit path.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define I2C_DEVICE "/dev/i2c-1"
#define AHT20_ADDRESS 0x38
#define AHT20_MEASURE_CMD 0x33
#define AHT20_STATUS_CMD 0x71
#define AHT20_STATUS_BUSY 0x08
#define AHT20_STATUS_CALIBRATED 0x80
#define AHT20_DATA_LENGTH 6
#define DEHUMIDIFIER_PIN 17
#define POLL_INTERVAL 5
#define RETRY_COUNT 3
#define RETRY_DELAY 10
#define DEHUMIDIFIER_ACTIVE_HIGH 1

static struct gpiod_chip *chip;
static struct gpiod_line *dehumidifier_line;

static void handle_sigint(int sig) {
    gpiod_line_release(dehumidifier_line);
    gpiod_chip_close(chip);
    exit(0);
}

static void handle_sigterm(int sig) {
    gpiod_line_release(dehumidifier_line);
    gpiod_chip_close(chip);
    exit(0);
}

static int read_aht20_humidity() {
    uint8_t cmd[1] = {AHT20_MEASURE_CMD};
    uint8_t status[1];
    uint8_t data[AHT20_DATA_LENGTH];
    int retries = RETRY_COUNT;
    int ret;

    while (retries--) {
        ret = gpiod_line_write(dehumidifier_line, DEHUMIDIFIER_ACTIVE_HIGH);
        if (ret < 0) {
            perror("Failed to activate dehumidifier");
            return -1;
        }

        ret = i2c_smbus_write_byte_data(i2c_fd, AHT20_ADDRESS, AHT20_MEASURE_CMD);
        if (ret < 0) {
            perror("Failed to trigger measurement");
            usleep(RETRY_DELAY * 1000);
            continue;
        }

        usleep(80 * 1000);

        ret = i2c_smbus_read_byte_data(i2c_fd, AHT20_ADDRESS, AHT20_STATUS_CMD);
        if (ret < 0) {
            perror("Failed to read status");
            usleep(RETRY_DELAY * 1000);
            continue;
        }

        status[0] = ret;
        if (status[0] & AHT20_STATUS_BUSY) {
            usleep(RETRY_DELAY * 1000);
            continue;
        }

        if (!(status[0] & AHT20_STATUS_CALIBRATED)) {
            fprintf(stderr, "Sensor not calibrated\n");
            return -1;
        }

        ret = i2c_smbus_read_i2c_block_data(i2c_fd, AHT20_ADDRESS, AHT20_DATA_LENGTH, data);
        if (ret < 0) {
            perror("Failed to read data");
            usleep(RETRY_DELAY * 1000);
            continue;
        }

        uint32_t humidity_raw = (data[1] << 16) | (data[2] << 8) | data[3];
        float humidity = (humidity_raw * 100.0) / 0x0000FFFF;
        return humidity;
    }

    fprintf(stderr, "Failed to read humidity after %d retries\n", RETRY_COUNT);
    return -1;
}

int main() {
    int i2c_fd;
    struct timespec ts;
    time_t now;
    char timestamp[20];
    float humidity;

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    dehumidifier_line = gpiod_chip_get_line(chip, DEHUMIDIFIER_PIN);
    if (!dehumidifier_line) {
        perror("Failed to get dehumidifier line");
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(dehumidifier_line, "dehumidifier", DEHUMIDIFIER_ACTIVE_HIGH);
    if (ret < 0) {
        perror("Failed to request dehumidifier line");
        gpiod_chip_close(chip);
        return 1;
    }

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        gpiod_line_release(dehumidifier_line);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDRESS);
    if (ret < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        gpiod_line_release(dehumidifier_line);
        gpiod_chip_close(chip);
        return 1;
    }

    while (1) {
        humidity = read_aht20_humidity();
        if (humidity >= 0) {
            time(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
            printf("%s: Humidity: %.2f%%\n", timestamp, humidity);

            if (humidity > 60) {
                gpiod_line_write(dehumidifier_line, DEHUMIDIFIER_ACTIVE_HIGH);
            } else if (humidity < 55) {
                gpiod_line_write(dehumidifier_line, 0);
            }
        }

        nanosleep(&ts, NULL);
    }

    close(i2c_fd);
    gpiod_line_release(dehumidifier_line);
    gpiod_chip_close(chip);
    return 0;
}

