#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define I2C_BUS "i2c-1"
#define BMP280_I2C_ADDR 0x76
#define BMP280_CHIP_ID_REG 0xD0
#define BMP280_CHIP_ID 0x58
#define BMP280_MEASUREMENT_REG 0xF4
#define BMP280_CONFIG_REG 0xF5
#define BMP280_DATA_REG 0xFA
#define BMP280_DATA_LEN 6
#define BMP280_CONVERSION_TIME 10
#define SAMPLE_INTERVAL 2
#define MIN_PRESSURE 980.0
#define MAX_PRESSURE 1020.0
#define LOG_FILE "pressure_log.txt"

static struct gpiod_chip *chip = NULL;
static int i2c_fd = -1;

void signal_handler(int signum) {
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(signum);
}

int read_bmp280_chip_id(int fd) {
    uint8_t chip_id;
    if (read(fd, &chip_id, 1) != 1) {
        perror("Failed to read chip ID");
        return -1;
    }
    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "Invalid chip ID: 0x%02X\n", chip_id);
        return -1;
    }
    return 0;
}

int read_bmp280_data(int fd, uint8_t *data, size_t len) {
    if (read(fd, data, len) != len) {
        perror("Failed to read BMP280 data");
        return -1;
    }
    return 0;
}

int write_bmp280_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buffer[2] = {reg, value};
    if (write(fd, buffer, 2) != 2) {
        perror("Failed to write BMP280 register");
        return -1;
    }
    return 0;
}

int bmp280_init(int fd) {
    if (read_bmp280_chip_id(fd) < 0) {
        return -1;
    }
    if (write_bmp280_register(fd, BMP280_CONFIG_REG, 0) < 0) {
        return -1;
    }
    if (write_bmp280_register(fd, BMP280_MEASUREMENT_REG, 0x27) < 0) {
        return -1;
    }
    return 0;
}

int bmp280_read_pressure(int fd, float *pressure) {
    uint8_t data[BMP280_DATA_LEN];
    if (read_bmp280_data(fd, data, BMP280_DATA_LEN) < 0) {
        return -1;
    }
    int32_t adc_p = (data[0] << 16) | (data[1] << 8) | data[2];
    *pressure = (adc_p / 4096.0) * 100.0;
    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set SIGTERM handler");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(I2C_BUS);
    if (!chip) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    i2c_fd = gpiod_chip_get_i2c_fd(chip);
    if (i2c_fd < 0) {
        perror("Failed to get I2C file descriptor");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        for (int retry = 0; retry < 3; retry++) {
            if (bmp280_init(i2c_fd) == 0) {
                break;
            }
            if (retry == 2) {
                fprintf(stderr, "Failed to initialize BMP280 after 3 retries\n");
                fclose(log_file);
                close(i2c_fd);
                gpiod_chip_close(chip);
                return EXIT_FAILURE;
            }
            sleep(1);
        }

        float pressure;
        if (bmp280_read_pressure(i2c_fd, &pressure) < 0) {
            fprintf(stderr, "Failed to read pressure\n");
            continue;
        }

        if (pressure < MIN_PRESSURE || pressure > MAX_PRESSURE) {
            time_t now = time(NULL);
            fprintf(log_file, "%s: %.2f hPa\n", ctime(&now), pressure);
            fflush(log_file);
        }

        sleep(SAMPLE_INTERVAL);
    }

    fclose(log_file);
    close(i2c_fd);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

