#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>

#define I2C_BUS "/dev/i2c-1"
#define TMP117_ADDR 0x48
#define AHT20_ADDR 0x38
#define PIR_PIN 17
#define PIR_CHIP "gpiochip4"
#define LOG_DIR "/var/log/sensors"
#define LOG_FILE "sensor_data.csv"

static struct gpiod_chip *chip;
static int i2c_fd;

void log_data(double temp, double humidity, int motion) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char filename[256];
    char buffer[256];
    snprintf(filename, sizeof(filename), "%s/%04d-%02d-%02d.csv", LOG_DIR, tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday);
    FILE *file = fopen(filename, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }
    if (tm_info->tm_hour == 0 && tm_info->tm_min == 0 && tm_info->tm_sec == 0) {
        fprintf(file, "Timestamp,Temperature(C),Humidity(%%),MotionDetected\n");
    }
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(file, "%s,%.2f,%.2f,%d\n", buffer, temp, humidity, motion);
    fclose(file);
}

int read_tmp117() {
    uint8_t buffer[2];
    if (read(i2c_fd, buffer, 2) != 2) {
        perror("Failed to read TMP117");
        return -1;
    }
    int16_t raw = (buffer[0] << 8) | buffer[1];
    return (raw >> 4) * 0.0625;
}

int read_aht20() {
    uint8_t buffer[6];
    if (write(i2c_fd, "\x71\x80\x00\x00\x00\x00", 6) != 6) {
        perror("Failed to send AHT20 command");
        return -1;
    }
    usleep(100000);
    if (read(i2c_fd, buffer, 6) != 6) {
        perror("Failed to read AHT20");
        return -1;
    }
    uint32_t raw = (buffer[3] << 16) | (buffer[4] << 8) | buffer[5];
    return (raw >> 4) * 0.000061;
}

int read_pir() {
    struct gpiod_line *line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!line) {
        perror("Failed to get PIR line");
        return -1;
    }
    int value = gpiod_line_get_value(line);
    gpiod_line_release(line);
    return value;
}

void handle_sigint(int sig) {
    close(i2c_fd);
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    if (mkdir(LOG_DIR, 0755) != 0 && errno != EEXIST) {
        perror("Failed to create log directory");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, TMP117_ADDR) < 0) {
        perror("Failed to set TMP117 address");
        close(i2c_fd);
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        perror("Failed to set AHT20 address");
        close(i2c_fd);
        return 1;
    }

    chip = gpiod_chip_open_by_name(PIR_CHIP);
    if (!chip) {
        perror("Failed to open PIR chip");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        double temp = read_tmp117();
        double humidity = read_aht20();
        int motion = read_pir();

        if (temp == -1 || humidity == -1 || motion == -1) {
            fprintf(stderr, "Sensor read failed, continuing...\n");
        } else {
            log_data(temp, humidity, motion);
        }

        sleep(1);
    }

    close(i2c_fd);
    gpiod_chip_close(chip);
    return 0;
}

