#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

struct gpiod_chip *chip;
struct gpiod_line *rain_sensor_line;
struct gpiod_line *motor_ena_line;
struct gpiod_line *motor_in1_line;
struct gpiod_line *motor_in2_line;

void log_event(const char *message) {
    time_t now = time(NULL);
    char *time_str = ctime(&now);
    time_str[strlen(time_str) - 1] = '\0'; // Remove newline character
    printf("[%s] %s\n", time_str, message);
}

void stop_motor() {
    gpiod_line_set_value(motor_in1_line, 0);
    gpiod_line_set_value(motor_in2_line, 0);
    gpiod_line_set_value(motor_ena_line, 0);
    log_event("Motor stopped");
}

void signal_handler(int signum) {
    log_event("Program terminated by signal");
    stop_motor();
    gpiod_line_release(motor_ena_line);
    gpiod_line_release(motor_in1_line);
    gpiod_line_release(motor_in2_line);
    gpiod_line_release(rain_sensor_line);
    gpiod_chip_close(chip);
    exit(signum);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    rain_sensor_line = gpiod_chip_get_line(chip, RAIN_SENSOR_PIN);
    if (!rain_sensor_line) {
        perror("Failed to get rain sensor line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    motor_ena_line = gpiod_chip_get_line(chip, MOTOR_ENA_PIN);
    if (!motor_ena_line) {
        perror("Failed to get motor ENA line");
        gpiod_line_release(rain_sensor_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    motor_in1_line = gpiod_chip_get_line(chip, MOTOR_IN1_PIN);
    if (!motor_in1_line) {
        perror("Failed to get motor IN1 line");
        gpiod_line_release(motor_ena_line);
        gpiod_line_release(rain_sensor_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    motor_in2_line = gpiod_chip_get_line(chip, MOTOR_IN2_PIN);
    if (!motor_in2_line) {
        perror("Failed to get motor IN2 line");
        gpiod_line_release(motor_in1_line);
        gpiod_line_release(motor_ena_line);
        gpiod_line_release(rain_sensor_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(rain_sensor_line, "rain_sensor") < 0) {
        perror("Failed to request rain sensor line as input");
        gpiod_line_release(motor_in2_line);
        gpiod_line_release(motor_in1_line);
        gpiod_line_release(motor_ena_line);
        gpiod_line_release(rain_sensor_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(motor_ena_line, "motor_ena", 0) < 0) {
        perror("Failed to request motor ENA line as output");
        gpiod_line_release(motor_in2_line);
        gpiod_line_release(motor_in1_line);
        gpiod_line_release(motor_ena_line);
        gpiod_line_release(rain_sensor_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(motor_in1_line, "motor_in1", 0) < 0) {
        perror("Failed to request motor IN1 line as output");
        gpiod_line_release(motor_in2_line);
        gpiod_line_release(motor_in1_line);
        gpiod_line_release(motor_ena_line);
        gpiod_line_release(rain_sensor_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(motor_in2_line, "motor_in2", 0) < 0) {
        perror("Failed to request motor IN2 line as output");
        gpiod_line_release(motor_in2_line);
        gpiod_line_release(motor_in1_line);
        gpiod_line_release(motor_ena_line);
        gpiod_line_release(rain_sensor_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        int rain_detected = gpiod_line_get_value(rain_sensor_line);
        if (rain_detected == 0) {
            log_event("Rain detected");
            gpiod_line_set_value(motor_in1_line, 1);
            gpiod_line_set_value(motor_in2_line, 0);
            gpiod_line_set_value(motor_ena_line, 1);
            log_event("Motor started");
            sleep(5);
            stop_motor();
        }
        sleep(2);
    }

    gpiod_line_release(motor_in2_line);
    gpiod_line_release(motor_in1_line);
    gpiod_line_release(motor_ena_line);
    gpiod_line_release(rain_sensor_line);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

