#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define RED_PIN 17
#define GREEN_PIN 22
#define BLUE_PIN 27
#define PWM_PERIOD_NS 10000000  // 10ms period
#define SAMPLE_INTERVAL_MS 500

struct gpiod_chip *chip;
struct gpiod_line *red_line, *green_line, *blue_line;
int running = 1;

void signal_handler(int signum) {
    running = 0;
}

void init_pwm() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(1);
    }

    red_line = gpiod_chip_get_line(chip, RED_PIN);
    if (!red_line) {
        fprintf(stderr, "Failed to get GPIO line for red\n");
        gpiod_chip_close(chip);
        exit(1);
    }

    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    if (!green_line) {
        fprintf(stderr, "Failed to get GPIO line for green\n");
        gpiod_line_release(red_line);
        gpiod_chip_close(chip);
        exit(1);
    }

    blue_line = gpiod_chip_get_line(chip, BLUE_PIN);
    if (!blue_line) {
        fprintf(stderr, "Failed to get GPIO line for blue\n");
        gpiod_line_release(green_line);
        gpiod_line_release(red_line);
        gpiod_chip_close(chip);
        exit(1);
    }

    if (gpiod_line_request_output(red_line, "red_pwm", 0) < 0) {
        fprintf(stderr, "Failed to request output for red line\n");
        gpiod_line_release(blue_line);
        gpiod_line_release(green_line);
        gpiod_line_release(red_line);
        gpiod_chip_close(chip);
        exit(1);
    }

    if (gpiod_line_request_output(green_line, "green_pwm", 0) < 0) {
        fprintf(stderr, "Failed to request output for green line\n");
        gpiod_line_release(blue_line);
        gpiod_line_release(green_line);
        gpiod_line_release(red_line);
        gpiod_chip_close(chip);
        exit(1);
    }

    if (gpiod_line_request_output(blue_line, "blue_pwm", 0) < 0) {
        fprintf(stderr, "Failed to request output for blue line\n");
        gpiod_line_release(blue_line);
        gpiod_line_release(green_line);
        gpiod_line_release(red_line);
        gpiod_chip_close(chip);
        exit(1);
    }

    if (gpiod_line_set_config(red_line, GPIOD_LINE_CONFIG_OUTPUT, PWM_PERIOD_NS, 0) < 0) {
        fprintf(stderr, "Failed to set configuration for red line\n");
        gpiod_line_release(blue_line);
        gpiod_line_release(green_line);
        gpiod_line_release(red_line);
        gpiod_chip_close(chip);
        exit(1);
    }

    if (gpiod_line_set_config(green_line, GPIOD_LINE_CONFIG_OUTPUT, PWM_PERIOD_NS, 0) < 0) {
        fprintf(stderr, "Failed to set configuration for green line\n");
        gpiod_line_release(blue_line);
        gpiod_line_release(green_line);
        gpiod_line_release(red_line);
        gpiod_chip_close(chip);
        exit(1);
    }

    if (gpiod_line_set_config(blue_line, GPIOD_LINE_CONFIG_OUTPUT, PWM_PERIOD_NS, 0) < 0) {
        fprintf(stderr, "Failed to set configuration for blue line\n");
        gpiod_line_release(blue_line);
        gpiod_line_release(green_line);
        gpiod_line_release(red_line);
        gpiod_chip_close(chip);
        exit(1);
    }
}

void set_pwm(int red, int green, int blue) {
    gpiod_line_set_value(red_line, red);
    gpiod_line_set_value(green_line, green);
    gpiod_line_set_value(blue_line, blue);
}

void read_cpu_load() {
    static unsigned long prev_user = 0, prev_nice = 0, prev_sys = 0, prev_idle = 0;
    FILE *fp;
    char line[256];
    unsigned long user, nice, sys, idle, total;

    fp = fopen("/proc/stat", "r");
    if (!fp) {
        perror("Failed to open /proc/stat");
        return;
    }

    if (fgets(line, sizeof(line), fp) == NULL) {
        perror("Failed to read /proc/stat");
        fclose(fp);
