}

int read_bmp280_temperature() {
    uint8_t data[3];
    if (gpiod_line_get_value(sda_line) != 0 || gpiod_line_get_value(scl_line) != 0) {
        return -1;
    }
    if (gpiod_line_request_output(sda_line, "sda", 0) < 0 || gpiod_line_request_output(scl_line, "scl", 0) < 0) {
        return -1;
    }
    // I2C start condition
    gpiod_line_set_value(sda_line, 0);
    gpiod_line_set_value(scl_line, 1);
    gpiod_line_set_value(sda_line, 1);
    gpiod_line_set_value(scl_line, 0);
    // Send BMP280 address with read bit
    for (int i = 7; i >= 0; i--) {
        gpiod_line_set_value(sda_line, (BMP280_I2C_ADDR << 1) & (1 << i) ? 1 : 0);
        gpiod_line_set_value(scl_line, 1);
        gpiod_line_set_value(scl_line, 0);
    }
    // Check ACK
    gpiod_line_set_value(sda_line, 1);
    gpiod_line_set_value(scl_line, 1);
    int ack = gpiod_line_get_value(sda_line);
    gpiod_line_set_value(scl_line, 0);
    if (ack != 0) {
        return -1;
    }
    // Send register address
    for (int i = 7; i >= 0; i--) {
        gpiod_line_set_value(sda_line, (BMP280_REG_TEMP_MSB << i) & 0x80 ? 1 : 0);
        gpiod_line_set_value(scl_line, 1);
        gpiod_line_set_value(scl_line, 0);
    }
    // Check ACK
    gpiod_line_set_value(sda_line, 1);
    gpiod_line_set_value(scl_line, 1);
    ack = gpiod_line_get_value(sda_line);
    gpiod_line_set_value(scl_line, 0);
    if (ack != 0) {
        return -1;
    }
    // I2C repeated start condition
    gpiod_line_set_value(sda_line, 0);
    gpiod_line_set_value(scl_line, 1);
    gpiod_line_set_value(sda_line, 1);
    gpiod_line_set_value(scl_line, 0);
    // Send BMP280 address with read bit
    for (int i = 7; i >= 0; i--) {
        gpiod_line_set_value(sda_line, (BMP280_I2C_ADDR << 1) | 1 & (1 << i) ? 1 : 0);
        gpiod_line_set_value(scl_line, 1);
        gpiod_line_set_value(scl_line, 0);
    }
    // Check ACK
    gpiod_line_set_value(sda_line, 1);
    gpiod_line_set_value(scl_line, 1);
    ack = gpiod_line_get_value(sda_line);
    gpiod_line_set_value(scl_line, 0);
    if (ack != 0) {
        return -1;
    }
    // Read temperature data
    for (int i = 0; i < 3; i++) {
        for (int j = 7; j >= 0; j--) {
            gpiod_line_set_value(sda_line, 1);
            gpiod_line_set_value(scl_line, 1);
            data[i] = (data[i] << 1) | gpiod_line_get_value(sda_line);
            gpiod_line_set_value(scl_line, 0);
        }
        gpiod_line_set_value(sda_line, 1);
        gpiod_line_set_value(scl_line, 1);
        gpiod_line_set_value(sda_line, 0);
        gpiod_line_set_value(scl_line, 0);
    }
    // I2C stop condition
    gpiod_line_set_value(sda_line, 0);
    gpiod_line_set_value(scl_line, 1);
    gpiod_line_set_value(sda_line, 1);
    gpiod_line_set_value(scl_line, 0);
    gpiod_line_release(sda_line);
    gpiod_line_release(scl_line);
    return (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
}

