int main() {
    struct sockaddr_in server_addr;
    char json_buffer[JSON_BUFFER_SIZE];

    // Initialize GPIO
    chip = gpiod_chip_open(I2C_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }
    sda_line = gpiod_chip_get_line(chip, I2C_LINE_SDA);
    if (!sda_line) {
        perror("Failed to get SDA line");
        gpiod_chip_close(chip);
        return 1;
    }
    scl_line = gpiod_chip_get_line(chip, I2C_LINE_SCL);
    if (!scl_line) {
        perror("Failed to get SCL line");
        gpiod_line_release(sda_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Initialize UDP socket
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        perror("Failed to create UDP socket");
        gpiod_line_release(sda_line);
        gpiod_line_release(scl_line);
        gpiod_chip_close(chip);
        return 1;
    }
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(UDP_PORT);
    if (inet_pton(AF_INET, UDP_IP, &server_addr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(udp_socket);
        gpiod_line_release(sda_line);
        gpiod_line_release(scl_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    // Initialize BMP280
    uint8_t config_data = BMP280_STANDBY_TIME_1000MS | BMP280_FILTER_COEFF_16;
    uint8_t ctrl_meas_data = BMP280_MODE_NORMAL | BMP280_SPI_ENABLE;
    if (gpiod_line_get_value(sda_line) != 0 || gpiod_line_get_value(scl_line) != 0) {
        perror("Failed to initialize BMP280");
        close(udp_socket);
        gpiod_line_release(sda_line);
        gpiod_line_release(scl_line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(sda_line, "sda", 0) < 0 || gpiod_line_request_output(scl_line, "scl", 0) < 0) {
        perror("Failed to initialize BMP280");
        close(udp_socket);
        gpiod_line_release(sda_line);
        gpiod_line_release(scl_line);
        gpiod_chip_close(chip);
        return 1;
    }
    // I2C start condition
    gpiod_line_set_value(sda_line, 0);
    gpiod_line_set_value(scl_line, 1);
    gpiod_line_set_value(sda_line, 1);
    gpiod_line_set_value(scl_line, 0);
    // Send BMP280 address with write bit
    for (int i = 7; i >= 0; i--) {
        gpiod_line_set_value(sda_line, (BMP280_I2C_ADDR << 1) & (1 << i) ? 1 : 0);
        gpiod_line_set_value(scl_line, 1);
        gpiod_line_set_value(scl_line, 0);
    }
    // Check ACK
    gpiod_line_set_value(sda_line, 1);
    gpiod_line_set_value(scl_line, 1);
    int ack = gpiod_line_get_value(sda_line);
    gpiod_line_set_value(scl_line, 0);
    if (ack != 0) {
        perror("Failed to initialize BMP280");
        close(udp_socket);
        gpiod_line_release(sda_line);
        gpiod_line_release(scl_line);
        gpiod_chip_close(chip);
        return 1;
    }
    // Send register address
    for (int i = 7; i >= 0; i--) {
        gpiod_line_set_value(sda_line, (BMP280_REG_CONFIG << i) & 0x80 ? 1 : 0);
        gpiod_line_set_value(scl_line, 1);
        gpiod_line_set_value(scl_line, 0);
    }
    // Check ACK
    gpiod_line_set_value(sda_line, 1);
    gpiod_line_set_value(scl_line, 1);
    ack = gpiod_line_get_value(sda_line);
    gpiod_line_set_value(scl_line, 0);
    if (ack != 0) {
        perror("Failed to initialize BMP280");
        close(udp_socket);
        gpiod_line_release(sda_line);
        gpiod_line_release(scl_line);
        gpiod_chip_close(chip);
        return 1;
    }
    // Write config data
    for (int i = 7; i >= 0; i--) {
        gpiod_line_set_value(sda_line, (config_data << i) & 0x80 ? 1 : 0);
        gpiod_line_set_value(scl_line, 1);
        gpiod_line_set_value(scl_line, 0);
    }
    // I2C stop condition
    gpiod_line_set_value(sda_line, 0);
    gpiod_line_set_value(scl_line, 1);
    gpiod_line_set_value(sda_line, 1);
    gpiod_line_set_value(scl_line, 0);
    gpiod_line_release(sda_line);
    gpiod_line_release(scl_line);

    // Send register address
    for (int i = 7; i >= 0; i--) {
        gpiod_line_set_value(sda_line, (BMP280_REG_CTRL_MEAS << i) & 0x80 ? 1 : 0);
        gpiod_line_set_value(scl_line, 1);
        gpiod_line_set_value(scl_line, 0);
    }
    // Check ACK
    gpiod_line_set_value(sda_line, 1);
    gpiod_line_set_value(scl_line, 1);
    ack = gpiod_line_get_value(sda_line);
    gpiod_line_set_value(scl_line, 0);
    if (ack != 0) {
        perror("Failed to initialize BMP280");
        close(udp_socket);
        gpiod_line_release(sda_line);
        gpiod_line_release(scl_line);
        gpiod_chip_close(chip);
        return 1;
    }
    // Write ctrl_meas data
    for (int i = 7; i >= 0; i--) {
        gpiod_line_set_value(sda_line, (ctrl_meas_data << i) & 0x80 ? 1 : 0);
        gpiod_line_set_value(scl_line, 1);
        gpiod_line_set_value(scl_line, 0);
    }
    // I2C stop condition
    gpiod_line_set_value(sda_line, 0);
    gpiod_line_set_value(scl_line, 1);
    gpiod_line_set_value(sda_line, 1);
    gpiod_line_set_value(scl_line, 0);
    gpiod_line_release(sda_line);
    gpiod_line_release(scl_line);

    // Main loop
    while (1) {
        int temperature = read_bmp280_temperature();
        int pressure = read_bmp280_pressure();
        if (temperature < 0 || pressure < 0) {
            perror("Failed to read BMP280");
            continue;
        }
        snprintf(json_buffer, JSON_BUFFER_SIZE, "{\"temperature\":%.2f,\"pressure\":%.2f}", temperature * BMP280_TEMP_SCALE, pressure * BMP280_PRESS_SCALE);
        if (sendto(udp_socket, json_buffer, strlen(json_buffer), 0, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
            perror("Failed to send UDP packet");
        }
        sleep(5);
    }

    // Clean up
    close(udp_socket);
    gpiod_line_release(sda_line);
    gpiod_line_release(scl_line);
    gpiod_chip_close(chip);

    return 0;
