            duty_cycle = 0;
        } else if (temperature < 40.0) {
            duty_cycle = (uint8_t)((temperature - 25.0) / 15.0 * 50.0);
        } else if (temperature < 60.0) {
            duty_cycle = (uint8_t)((temperature - 40.0) / 20.0 * 150.0) + 50;
        } else {
            duty_cycle = 255;
        }

        update_fan(duty_cycle);

        buffer[buffer_index].timestamp = time(NULL);
        buffer[buffer_index].temperature = temperature;
        buffer[buffer_index].duty_cycle = duty_cycle;

        if (buffer_full) {
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        } else {
            buffer_full = 1;
        }

        sleep(1);
    }

    gpiod_line_release(fan_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

