#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <unistd.h>

#define I2C_BUS "/dev/i2c-1"
#define BMP180_ADDRESS 0x77
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 2
#define OSS 3

struct bmp180_calib {
    uint16_t ac1, ac2, ac3;
    uint16_t ac4, ac5, ac6;
    int16_t b1, b2, mb, mc, md;
};

struct bmp180_calib calib;

int i2c_fd;
FILE *log_file;
struct gpiod_chip *chip;
struct gpiod_line *line;

void read_bmp180_calib() {
    uint8_t data[22];
    if (read(i2c_fd, data, sizeof(data)) != sizeof(data)) {
        perror("Failed to read BMP180 calibration data");
        exit(EXIT_FAILURE);
    }

    calib.ac1 = (data[0] << 8) | data[1];
    calib.ac2 = (data[2] << 8) | data[3];
    calib.ac3 = (data[4] << 8) | data[5];
    calib.ac4 = (data[6] << 8) | data[7];
    calib.ac5 = (data[8] << 8) | data[9];
    calib.ac6 = (data[10] << 8) | data[11];
    calib.b1 = (data[12] << 8) | data[13];
    calib.b2 = (data[14] << 8) | data[15];
    calib.mb = (data[16] << 8) | data[17];
    calib.mc = (data[18] << 8) | data[19];
    calib.md = (data[20] << 8) | data[21];
}

int read_bmp180_temperature() {
    uint8_t data[3];
    if (write(i2c_fd, "\xF4\x2E", 2) != 2) {
        perror("Failed to send temperature measurement command");
        return -1;
    }
    usleep(5000);

    if (read(i2c_fd, data, sizeof(data)) != sizeof(data)) {
        perror("Failed to read temperature data");
        return -1;
    }

    int32_t ut = ((int16_t)data[0] << 8) | data[1];
    ut <<= 8;
    ut |= data[2] >> 4;

    int32_t x1 = ((ut - calib.ac6) * calib.ac5) >> 15;
    int32_t x2 = (calib.mc << 11) / (x1 + calib.md);
    int32_t b5 = x1 + x2;

    return (b5 + 8) >> 4;
}

int read_bmp180_pressure() {
    uint8_t data[3];
    if (write(i2c_fd, "\xF4\x34", 2) != 2) {
        perror("Failed to send pressure measurement command");
        return -1;
    }
    usleep(5000);

    if (read(i2c_fd, data, sizeof(data)) != sizeof(data)) {
        perror("Failed to read pressure data");
        return -1;
    }

    int32_t up = ((int16_t)data[0] << 16) | ((int16_t)data[1] << 8) | (data[2] >> 4);

    int32_t b6 = b5 - 4000;
    int32_t x1 = (calib.b2 * (b6 * b6 >> 12)) >> 11;
    int32_t x2 = calib.ac2 * b6 >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((calib.ac1 * 4 + x3) << OSS) + 2) >> 2;

    x1 = (calib.ac3 * b6 >> 13);
    x2 = (calib.b1 * ((b6 * b6 >> 12) >> 16)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    int32_t b4 = (calib.ac4 * (uint32_t)(x3 + 32768)) >> 15;
    int32_t b7 = ((uint32_t)up - b3) * (50000 >> OSS);

    if (b7 < 0x80000000) {
        return (b7 << 1) / b4;
    } else {
        return (b7 / b4) << 1;
    }
}

void log_data(int temperature, int pressure) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d,%d,%d\n",
            tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
            tm->tm_hour, tm->tm_min, tm->tm_sec, temperature, pressure);
    fflush(log_file);
}

void gpio_callback(struct gpiod_line_event *event) {
    static int logging = 0;
    logging = !logging;
    if (logging) {
        log_data(read_bmp180_temperature(), read_bmp180_pressure());
    }
}

void signal_handler(int sig) {
    if (sig == SIGINT) {
        if (i2c_fd >= 0) {
            close(i2c_fd);
        }
        if (log_file) {
            fclose(log_file);
        }
        if (chip) {
            gpiod_chip_close(chip);
        }
        exit(EXIT_SUCCESS);
    }
}

int main() {
    signal(SIGINT, signal_handler);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BMP180_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    read_bmp180_calib();

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_interrupts(line, "gpio2_interrupt", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP, gpio_callback) < 0) {
        perror("Failed to request GPIO interrupt");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen("altitude_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        sleep(1);
    }

    return EXIT_SUCCESS;
}

