#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <libgpiod/spi.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define CE_PIN 8
#define SPI_SPEED 1000000
#define RTD_MODE 0x00
#define BIAS_ENABLE 0x01
#define FAULT_STATUS_REG 0x02
#define RTD_DATA_REG 0x04
#define RTD_A 3.9083e-3
#define RTD_B -5.775e-7
#define RTD_C 2.1792e-12

static struct gpiod_chip *chip;
static struct gpiod_line *ce_line;
static FILE *log_file;

void log_temperature(double temperature) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d,%.2f\n",
            tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
            tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec, temperature);
    fflush(log_file);
}

void handle_sigint(int sig) {
    if (log_file) fclose(log_file);
    if (ce_line) gpiod_line_release(ce_line);
    if (chip) gpiod_chip_close(chip);
    exit(0);
}

int main() {
    struct gpiod_line_request req;
    uint8_t tx[4] = {RTD_DATA_REG, 0, 0, 0};
    uint8_t rx[4];
    double resistance, temperature;

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    ce_line = gpiod_chip_get_line(chip, CE_PIN);
    if (!ce_line) {
        perror("Failed to get CE line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(ce_line, "RTD_CE", 0) < 0) {
        perror("Failed to request CE line as output");
        gpiod_line_release(ce_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_file = fopen("rtd_log.csv", "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(ce_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        gpiod_line_set_value(ce_line, 1);
        if (gpiod_spi_transfer(chip, SPI_SPEED, RTD_MODE | BIAS_ENABLE, tx, 4, rx, 4) < 0) {
            perror("SPI transfer failed");
        } else {
            uint16_t rtd_value = (rx[1] << 8) | rx[2];
            resistance = 32768.0 * (rtd_value / 65536.0);
            temperature = RTD_A + RTD_B * resistance + RTD_C * resistance * resistance * resistance;
            log_temperature(temperature);
        }
        gpiod_line_set_value(ce_line, 0);
        sleep(5);
    }

    fclose(log_file);
    gpiod_line_release(ce_line);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

