#include <libgpiod.h>

#define BME280_I2C_ADDRESS 0x76
#define BME280_CHIP_ID 0x60
#define BME280_LOG_FILE "bme280_log.csv"

struct bme280_data {
    int temperature;
    int humidity;
    int pressure;
};

static int i2c_fd;
static struct gpiod_chip *chip;

void cleanup() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(EXIT_SUCCESS);
}

void handle_signal(int sig) {
    cleanup();
}

int read_bme280(struct bme280_data *data) {
    uint8_t buffer[8];
    if (read(i2c_fd, buffer, 8) != 8) {
        perror("Failed to read from BME280");
        return -1;
    }

    data->temperature = (buffer[3] << 12) | (buffer[4] << 4) | (buffer[5] >> 4);
    data->humidity = (buffer[6] << 8) | buffer[7];
    data->pressure = (buffer[0] << 12) | (buffer[1] << 4) | (buffer[2] >> 4);

    return 0;
}

int main() {
    struct bme280_data data;
    struct timespec ts;
    char timestamp[20];
    FILE *log_file;

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BME280_I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize BME280
    uint8_t chip_id;
    if (read(i2c_fd, &chip_id, 1) != 1) {
        perror("Failed to read chip ID from BME280");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (chip_id != BME280_CHIP_ID) {
        fprintf(stderr, "Invalid BME280 chip ID: 0x%02X\n", chip_id);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(BME280_LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

