#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x77
#define GPIO_ALERT 24
#define BUFFER_SIZE 120
#define SAMPLE_INTERVAL 50
#define MAX_DEVIATION 5.0

typedef struct {
    time_t timestamp;
    float pressure;
} Reading;

Reading buffer[BUFFER_SIZE];
int buffer_head = 0;
int buffer_count = 0;

struct gpiod_chip *chip;
struct gpiod_line *alert_line;
int i2c_handle;

void cleanup() {
    if (alert_line) {
        gpiod_line_release(alert_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_handle >= 0) {
        i2c_close(i2c_handle);
    }
    gpioTerminate();
}

void handle_sigint(int sig) {
    cleanup();
    exit(0);
}

float calculate_average() {
    if (buffer_count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < buffer_count; i++) {
        sum += buffer[(buffer_head + i) % BUFFER_SIZE].pressure;
    }
    return sum / buffer_count;
}

int read_pressure(float *pressure) {
    uint8_t cmd = 0x76;
    if (i2c_write_byte_data(i2c_handle, I2C_ADDRESS, cmd) < 0) {
        fprintf(stderr, "Failed to write to BMP180\n");
        return -1;
    }
    usleep(50000);

    uint8_t data[3];
    if (i2c_read_i2c_block_data(i2c_handle, I2C_ADDRESS, data, 3) != 3) {
        fprintf(stderr, "Failed to read from BMP180\n");
        return -1;
    }

    *pressure = (data[0] << 16) | (data[1] << 8) | data[2];
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (pigpio_start(NULL, NULL) < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        gpioTerminate();
        return 1;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        gpioTerminate();
        return 1;
    }

    alert_line = gpiod_chip_get_line(chip, GPIO_ALERT);
    if (!alert_line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    if (gpiod_line_request_output(alert_line, "alert", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line as output\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    i2c_handle = i2c_open(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        float pressure;
        if (read_pressure(&pressure) < 0) {
            continue;
        }

        time_t now = time(NULL);
        buffer[buffer_head].timestamp = now;
        buffer[buffer_head].pressure = pressure;
        buffer_head = (buffer_head + 1) % BUFFER_SIZE;
        if (buffer_count < BUFFER_SIZE) {
            buffer_count++;
        }

        float average = calculate_average();
        if (fabs(pressure - average) > MAX_DEVIATION) {
            gpiod_line_set_value(alert_line, 1);
            fprintf(stderr, "Alert: Pressure deviation from average detected\n");
        } else {
            gpiod_line_set_value(alert_line, 0);
        }

        usleep(SAMPLE_INTERVAL * 1000);
    }

    cleanup();
    return 0;
}

