#include <unistd.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define BMP180_I2C_ADDR 0x77
#define BMP180_CHIP_ID_REG 0xD0
#define BMP180_CHIP_ID 0x55
#define BMP180_TEMP_MEAS_REG 0xF4
#define BMP180_TEMP_MEAS_CMD 0x2E
#define BMP180_DATA_REG 0xF6
#define BMP180_DATA_LEN 3
#define BMP180_LOG_FILE "bmp180_log.txt"

static struct gpiod_chip *chip;
static FILE *log_file;

void handle_signal(int sig) {
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    struct gpiod_line *line;
    uint8_t chip_id;
    uint8_t data[BMP180_DATA_LEN];
    int ret;

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open I2C bus
    chip = gpiod_chip_open_by_name("gpiochip1");
    if (!chip) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(BMP180_LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Validate chip ID
    ret = gpiod_chip_read_byte(chip, BMP180_I2C_ADDR, &chip_id);
    if (ret < 0) {
        perror("Failed to read chip ID");
        fclose(log_file);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (chip_id != BMP180_CHIP_ID) {
        fprintf(stderr, "Invalid chip ID: 0x%02X\n", chip_id);
        fclose(log_file);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up hardware timer interrupt
    line = gpiod_chip_get_line(chip, 17); // Example GPIO pin for timer interrupt
    if (!line) {
        perror("Failed to get GPIO line");
        fclose(log_file);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request_output(line, "bmp180_timer", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        fclose(log_file);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Trigger temperature measurement
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("Failed to trigger temperature measurement");
            continue;
        }
        usleep(500000); // Wait for 500 ms
        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("Failed to trigger temperature measurement");
            continue;
        }

        // Read temperature and pressure
        ret = gpiod_chip_read_bytes(chip, BMP180_I2C_ADDR, data, BMP180_DATA_LEN);
        if (ret < 0) {
            perror("Failed to read temperature and pressure data");
            continue;
        }

        // Convert data to temperature and pressure
        int16_t ut = (data[0] << 8) | data[1];
        int32_t up = ((int32_t)data[2] << 16) | ((int32_t)data[3] << 8) | data[4];

        // Log results
        fprintf(log_file, "Temperature: %.2f C, Pressure: %d Pa\n", ut, up);
        fflush(log_file);
    }

    // Clean up
    fclose(log_file);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

