#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define THERMAL_ZONE_PATH "/sys/class/thermal/thermal_zone0/temp"
#define PWM_PIN 18
#define PWM_FREQ 25000
#define PWM_RANGE 255
#define MIN_TEMP 40000
#define MAX_TEMP 70000
#define LOG_INTERVAL 5

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static FILE *log_file;

void log_temperature(int temperature, int duty_cycle) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(log_file, "%s, %d°C, %d%%\n", asctime(tm_info), temperature / 1000, duty_cycle);
    fflush(log_file);
}

void set_pwm_duty_cycle(int duty_cycle) {
    if (gpiod_line_set_value(line, duty_cycle) < 0) {
        perror("Failed to set PWM duty cycle");
    }
}

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        if (log_file) {
            fclose(log_file);
        }
        if (line) {
            gpiod_line_release(line);
        }
        if (chip) {
            gpiod_chip_close(chip);
        }
        exit(signum);
    }
}

int main() {
    int temperature, duty_cycle;
    char temp_str[20];
    struct timespec ts;

    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen("fan_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    // Initialize GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Request GPIO line
    line = gpiod_chip_get_line(chip, PWM_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Configure GPIO line as output
    if (gpiod_line_request_output(line, "fan_control", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Set PWM frequency
    if (gpiod_line_set_edge_detection(line, GPIOD_LINE_EDGE_NONE) < 0) {
        perror("Failed to set edge detection");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Read temperature
        if (read(open(THERMAL_ZONE_PATH, O_RDONLY), temp_str, sizeof(temp_str) - 1) < 0) {
            perror("Failed to read temperature");
            continue;
        }
        temp_str[sizeof(temp_str) - 1] = '\0';
        temperature = atoi(temp_str);

        // Map temperature to duty cycle
        if (temperature < MIN_TEMP) {
            duty_cycle = 0;
        } else if (temperature > MAX_TEMP) {
            duty_cycle = PWM_RANGE;
        } else {
            duty_cycle = (temperature - MIN_TEMP) * PWM_RANGE / (MAX_TEMP - MIN_TEMP);
        }

