    calib_data.dig_P6 = (buf[17] << 8) | buf[16];
    calib_data.dig_P7 = (buf[19] << 8) | buf[18];
    calib_data.dig_P8 = (buf[21] << 8) | buf[20];
    calib_data.dig_P9 = (buf[23] << 8) | buf[22];
}

