static struct gpiod_line *led_line = NULL;
static pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;
static float temperature_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static float running_average = 0.0;

static void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    if (led_line != NULL) {
        gpiod_line_release(led_line);
    }
    pthread_mutex_destroy(&buffer_mutex);
}

static void handle_sigint(int sig) {
    cleanup();
    exit(0);
}

static int read_temperature() {
    uint8_t data[2];
    if (read(i2c_fd, data, sizeof(data)) != sizeof(data)) {
        perror("Failed to read temperature from sensor");
        return -1;
    }
    int16_t raw_temp = (data[0] << 8) | data[1];
    float temperature = (float)raw_temp / 256.0;
    return temperature;
}

static void update_led(float temperature) {
    if (temperature > THRESHOLD_TEMP) {
        gpiod_line_set_value(led_line, 1);
    } else {
        gpiod_line_set_value(led_line, 0);
    }
}

static void update_buffer(float temperature) {
    pthread_mutex_lock(&buffer_mutex);
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    running_average = 0.0;
    for (int i = 0; i < buffer_count; i++) {
        running_average += temperature_buffer[i];
    }
    running_average /= buffer_count;
    pthread_mutex_unlock(&buffer_mutex);
}

static void *sensor_thread(void *arg) {
    while (1) {
        float temperature = read_temperature();
        if (temperature != -1) {
            update_buffer(temperature);
            update_led(temperature);
        }
        sleep(1);
    }
    return NULL;
}

int main() {
    signal(SIGINT, handle_sigint);

    // Initialize I2C
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C bus");
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return 1;
    }

    // Initialize GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (chip == NULL) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (led_line == NULL) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }
    if (gpiod_line_request_output(led_line, "temperature_alert", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    // Start sensor thread
    pthread_t thread;
    if (pthread_create(&thread, NULL, sensor_thread, NULL) != 0) {
        perror("Failed to create sensor thread");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    // Wait for thread to finish (should never happen)
    pthread_join(thread, NULL);

    cleanup();
    return 0;
}
