code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define BMP180_ADDRESS 0x77
#define BMP180_CHIP_ID 0x55
#define BMP180_CALIBRATION_DATA_SIZE 22
#define BMP180_TEMP_REG 0xFA
#define BMP180_PRESSURE_REG 0xF4
#define BMP180_TEMP_CONVERSION_TIME 5
#define BMP180_PRESSURE_CONVERSION_TIME 8
#define BMP180_OVERSAMPLING 3
#define BMP180_TEMP_SCALE 10
#define BMP180_PRESSURE_SCALE 100
#define BMP180_TEMP_THRESHOLD 3000
#define BMP180_PRESSURE_THRESHOLD 95000

static int i2c_fd = -1;
static FILE *log_file = NULL;

static void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

static void handle_signal(int sig) {
    cleanup();
    exit(EXIT_SUCCESS);
}

static int read_i2c(int fd, uint8_t reg, uint8_t *data, size_t size) {
    uint8_t buf[1] = {reg};
    if (write(fd, buf, 1) != 1) {
        perror("write");
        return -1;
    }
    if (read(fd, data, size) != size) {
        perror("read");
        return -1;
    }
    return 0;
}

static int write_i2c(int fd, uint8_t reg, uint8_t data) {
    uint8_t buf[2] = {reg, data};
    if (write(fd, buf, 2) != 2) {
        perror("write");
        return -1;
    }
    return 0;
}

static int read_bmp180_calibration(int fd, int16_t *calibration) {
    uint8_t data[BMP180_CALIBRATION_DATA_SIZE];
    if (read_i2c(fd, 0xAA, data, BMP180_CALIBRATION_DATA_SIZE) != 0) {
        return -1;
    }
    for (int i = 0; i < BMP180_CALIBRATION_DATA_SIZE; i += 2) {
        calibration[i / 2] = (data[i] << 8) | data[i + 1];
    }
    return 0;
}

static int read_bmp180_temperature(int fd, int16_t *temperature) {
    if (write_i2c(fd, BMP180_PRESSURE_REG, 0xF4 | (BMP180_OVERSAMPLING << 6)) != 0) {
        return -1;
    }
    usleep(BMP180_TEMP_CONVERSION_TIME * 1000);
    uint8_t data[2];
    if (read_i2c(fd, BMP180_TEMP_REG, data, 2) != 0) {
        return -1;
    }
    *temperature = (data[0] << 8) | data[1];
    return 0;
}

static int read_bmp180_pressure(int fd, int32_t *pressure) {
    if (write_i2c(fd, BMP180_PRESSURE_REG, 0xF4 | (BMP180_OVERSAMPLING << 6)) != 0) {
        return -1;
    }
    usleep(BMP180_PRESSURE_CONVERSION_TIME * 1000);
    uint8_t data[3];
    if (read_i2c(fd, BMP180_PRESSURE_REG, data, 3) != 0) {
        return -1;
    }
    *pressure = (data[0] << 16) | (data[1] << 8) | data[2];
    return 0;
}

static int bmp180_calculate_temperature(int16_t ut, int16_t *calibration) {
    int32_t x1 = ((int32_t)ut - calibration[0]) * calibration[1] >> 15;
    int32_t x2 = calibration[2] >> 11;
    int32_t x3 = x1 + x2;
    int32_t t = x3 + 8 >> 4;
    return t;
}

static int bmp180_calculate_pressure(int32_t up, int32_t ut, int16_t *calibration) {
    int32_t x1 = ((int32_t)ut - calibration[0]) * calibration[1] >> 15;
    int32_t x2 = calibration[2] >> 11;
    int32_t x3 = x1 + x2;
    int32_t b5 = x3 + 8 >> 4;
    int32_t x6 = b5 >> 2;
    int32_t x7 = calibration[4] * (x6 * x6) >> 12;
    int32_t x8 = calibration[5] * x6 >> 11;
    int32_t x9 = (x7 + x8) >> 11;
    int32_t x10 = calibration[6] * b5 >> 13;
    int32_t x11 = x10 + 32768;
    int32_t x12 = x11 >> 15;
    int32_t x13 = up - x12;
    int32_t x14 = x13 * calibration[3] >> 15;
    int32_t p = x14 + x11;
    return p;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd == -1) {
        perror("open");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BMP180_ADDRESS) != 0) {
        perror("ioctl");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t chip_id;
    if (read_i2c(i2c_fd, 0xD0, &chip_id, 1) != 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (chip_id != BMP180_CHIP_ID) {
        fprintf(stderr, "BMP180 not found\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    int16_t calibration[BMP180_CALIBRATION_DATA_SIZE / 2];
    if (read_bmp180_calibration(i2c_fd, calibration) != 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen("breach_log.txt", "a");
    if (log_file == NULL) {
        perror("fopen");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        int16_t ut;
        if (read_bmp180_temperature(i2c_fd, &ut) != 0) {
            continue;
        }
        int32_t up;
        if (read_bmp180_pressure(i2c_fd, &up) != 0) {
            continue;
        }

        int32_t temperature = bmp180_calculate_temperature(ut, calibration);
        int32_t pressure = bmp180_calculate_pressure(up, ut, calibration);

        if (temperature > BMP180_TEMP_THRESHOLD || pressure < BMP180_PRESSURE_THRESHOLD) {
            time_t now = time(NULL);
            char *timestamp = ctime(&now);
            timestamp[strlen(timestamp) - 1] = '\0';
