#define BMP180_TEMP_REG 0xFA
#define BMP180_PRESS_REG 0xF4
#define BMP180_TEMP_CONVERSION_TIME 5
#define BMP180_PRESS_CONVERSION_TIME 8
#define BUFFER_SIZE 60
#define FAN_PIN 18
#define SAMPLE_INTERVAL 500

volatile int running = 1;
struct gpiod_chip *chip;
struct gpiod_line *fan_line;
uint16_t calibration_table[BMP180_CALIB_TABLE_SIZE];
uint16_t buffer[BUFFER_SIZE];
int buffer_index = 0;

void handle_sigint(int sig) {
    running = 0;
}

void read_calibration_table(int fd) {
    uint8_t reg = 0xAA;
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write calibration table register");
        exit(EXIT_FAILURE);
    }
    if (read(fd, calibration_table, BMP180_CALIB_TABLE_SIZE * sizeof(uint16_t)) != BMP180_CALIB_TABLE_SIZE * sizeof(uint16_t)) {
        perror("Failed to read calibration table");
        exit(EXIT_FAILURE);
    }
}

void sample_sensor(int fd) {
    uint8_t reg = BMP180_TEMP_REG;
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write temperature register");
        return;
    }
    gpioDelay(5000); // Wait for temperature conversion

    uint8_t data[2];
    if (read(fd, data, 2) != 2) {
        perror("Failed to read temperature data");
        return;
    }
    int16_t ut = (data[0] << 8) | data[1];

    reg = BMP180_PRESS_REG;
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write pressure register");
        return;
    }
    gpioDelay(8000); // Wait for pressure conversion

    if (read(fd, data, 3) != 3) {
        perror("Failed to read pressure data");
        return;
    }
    uint16_t up = (data[0] << 16) | (data[1] << 8) | data[2];

    // BMP180 formulas for OSS=0
    int32_t x1 = ((int32_t)ut - (int32_t)calibration_table[0]) * (int32_t)calibration_table[1];
    int32_t x2 = ((int32_t)calibration_table[2] * ((int32_t)ut - (int32_t)calibration_table[0])) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b5 = (x3 + 8192) >> 14;
    int32_t temperature = (b5 * 2) - 4000;

    x1 = ((int32_t)calibration_table[4] * ((temperature >> 3) - (int32_t)32000)) >> 11;
    x2 = ((int32_t)calibration_table[5] * ((temperature >> 2) - (int32_t)2000)) >> 11;
    int32_t x3 = ((x1 + x2) + 2) >> 2;
    int32_t pressure = ((uint32_t)up - x3) * (3125);
    if (pressure < 0x80000000) {
        pressure >>= 1;
    } else {
        pressure >>= 2;
    }
    x1 = ((int32_t)calibration_table[6] * (pressure >> 13)) >> 11;
    x2 = ((int32_t)calibration_table[7] * (pressure >> 17)) >> 11;
    pressure = ((pressure + x1 + x2) >> 4);

    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    printf("%04d-%02d-%02d %02d:%02d:%02d Temperature: %.2f°C Pressure: %.2f hPa\n",
           tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
           tm->tm_hour, tm->tm_min, tm->tm_sec,
           temperature / 100.0, pressure / 100.0);

    if (temperature > 3000) {
        gpiod_line_set_value(fan_line, 1);
    } else {
        gpiod_line_set_value(fan_line, 0);
    }

    buffer[buffer_index] = pressure;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

int main() {
    int fd = i2c_open(1, BMP180_I2C_ADDR, 0);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    read_calibration_table(fd);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        i2c_close(fd);
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        gpioTerminate();
        i2c_close(fd);
        return EXIT_FAILURE;
    }

    fan_line = gpiod_chip_get_line(chip, FAN_PIN);
    if (!fan_line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        i2c_close(fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(fan_line, "fan_control", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line as output\n");
        gpiod_chip_close(chip);
        gpioTerminate();
        i2c_close(fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    while (running) {
        sample_sensor(fd);
        gpioDelay(SAMPLE_INTERVAL * 1000);
    }

    gpiod_line_set_value(fan_line, 0);
    gpiod_line_release(fan_line);
    gpiod_chip_close(chip);
    gpioTerminate();
    i2c_close(fd);

    return EXIT_SUCCESS;
}

