    double setpoint;
    double integral;
    double prev_error;
};

struct pi_controller controller = {
    .Kp = 1.0,
    .Ki = 0.1,
    .Kd = 0.01,
    .setpoint = TARGET_TEMPERATURE,
    .integral = 0.0,
    .prev_error = 0.0
};

struct gpiod_chip *chip;
struct gpiod_line *heater_line;
int spi_fd;
FILE *log_file;

void log_temperature(double temperature, int duty_cycle) {
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline character

    fprintf(log_file, "%s,%.2f,%d\n", timestamp, temperature, duty_cycle);
    fflush(log_file);
}

void handle_sigint(int sig) {
