    exit(0);
}

void handle_sigterm(int sig) {
    printf("Received SIGTERM, shutting down gracefully...\n");
    gpiod_line_set_value(heater_line, 0);
    gpiod_chip_close(chip);
    fclose(log_file);
    exit(0);
}

int read_max31855_temperature(int spi_fd) {
    uint8_t tx[4] = {0x00, 0x00, 0x00, 0x00};
    uint8_t rx[4];
    int ret;

    ret = gpiod_chip_get_value(chip, SPI_CHIP_SELECT, &tx[0]);
    if (ret < 0) {
        perror("Failed to set chip select");
        return -1;
    }

    ret = gpiod_chip_get_value(chip, SPI_CHIP_SELECT, &tx[1]);
    if (ret < 0) {
        perror("Failed to set chip select");
        return -1;
    }

    ret = gpiod_chip_get_value(chip, SPI_CHIP_SELECT, &tx[2]);
    if (ret < 0) {
        perror("Failed to set chip select");
        return -1;
    }

    ret = gpiod_chip_get_value(chip, SPI_CHIP_SELECT, &tx[3]);
    if (ret < 0) {
        perror("Failed to set chip select");
        return -1;
    }

    ret = gpiod_chip_get_value(chip, SPI_CHIP_SELECT, &rx[0]);
    if (ret < 0) {
        perror("Failed to set chip select");
        return -1;
    }

    ret = gpiod_chip_get_value(chip, SPI_CHIP_SELECT, &rx[1]);
    if (ret < 0) {
        perror("Failed to set chip select");
        return -1;
    }

    ret = gpiod_chip_get_value(chip, SPI_CHIP_SELECT, &rx[2]);
    if (ret < 0) {
        perror("Failed to set chip select");
        return -1;
    }

    ret = gpiod_chip_get_value(chip, SPI_CHIP_SELECT, &rx[3]);
    if (ret < 0) {
        perror("Failed to set chip select");
        return -1;
    }

    int fault = (rx[0] & 0x08) >> 3;
    if (fault) {
        fprintf(stderr, "MAX31855 fault detected: %d\n", fault);
        return -1;
    }

    int temp = (rx[0] << 16) | (rx[1] << 8) | rx[2];
    double temperature = (temp >> 4) * 0.25;

    return (int)temperature;
}

int main() {
    int ret;
    double current_temperature;
    int duty_cycle = 0;

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    heater_line = gpiod_chip_get_line(chip, HEATER_PIN);
    if (!heater_line) {
        perror("Failed to get heater line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(heater_line, "heater", 0);
    if (ret < 0) {
        perror("Failed to request heater line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    spi_fd = gpiod_chip_get_fd(chip);
    if (spi_fd < 0) {
        perror("Failed to get SPI file descriptor");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        current_temperature = read_max31855_temperature(spi_fd);
        if (current_temperature < 0) {
            duty_cycle = 0;
        } else {
            double error = controller.setpoint - current_temperature;
            controller.integral += error;
            double derivative = error - controller.prev_error;
            double output = controller.Kp * error + controller.Ki * controller.integral + controller.Kd * derivative;
            duty_cycle = (int)(output * MAX_DUTY_CYCLE / 100.0);
            if (duty_cycle > MAX_DUTY_CYCLE) {
                duty_cycle = MAX_DUTY_CYCLE;
            } else if (duty_cycle < 0) {
                duty_cycle = 0;
            }
            controller.prev_error = error;
        }

        gpiod_line_set_value(heater_line, duty_cycle);
        log_temperature(current_temperature, duty_cycle);
        sleep(1);
    }

    gpiod_line_set_value(heater_line, 0);
    gpiod_chip_close(chip);
    fclose(log_file);
    return EXIT_SUCCESS;
}

