#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_RED 17
#define GPIO_GREEN 18
#define GPIO_BLUE 27
#define PWM_FREQ 1000
#define PWM_RANGE 255
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define UPDATE_INTERVAL 500000

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *red_line, *green_line, *blue_line;
    FILE *temp_file;
    char temp_str[16];
    int temp_millidegrees;
    int red_duty, green_duty, blue_duty;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request GPIO lines
    red_line = gpiod_chip_get_line(chip, GPIO_RED);
    if (!red_line) {
        perror("Failed to get GPIO line for Red");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    green_line = gpiod_chip_get_line(chip, GPIO_GREEN);
    if (!green_line) {
        perror("Failed to get GPIO line for Green");
        gpiod_line_release(red_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    blue_line = gpiod_chip_get_line(chip, GPIO_BLUE);
    if (!blue_line) {
        perror("Failed to get GPIO line for Blue");
        gpiod_line_release(red_line);
        gpiod_line_release(green_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set lines as output
    if (gpiod_line_request_output(red_line, "red_pwm", 255) < 0) {
        perror("Failed to request output for Red");
        gpiod_line_release(red_line);
        gpiod_line_release(green_line);
        gpiod_line_release(blue_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(green_line, "green_pwm", 255) < 0) {
        perror("Failed to request output for Green");
        gpiod_line_release(red_line);
        gpiod_line_release(green_line);
        gpiod_line_release(blue_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(blue_line, "blue_pwm", 255) < 0) {
        perror("Failed to request output for Blue");
        gpiod_line_release(red_line);
        gpiod_line_release(green_line);
        gpiod_line_release(blue_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open temperature file
    temp_file = fopen(TEMP_FILE, "r");
    if (!temp_file) {
        perror("Failed to open temperature file");
        gpiod_line_release(red_line);
        gpiod_line_release(green_line);
        gpiod_line_release(blue_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!stop_flag) {
        // Read temperature
        if (fgets(temp_str, sizeof(temp_str), temp_file) == NULL) {
            if (ferror(temp_file)) {
                perror("Failed to read temperature file");
            }
            clearerr(temp_file);
            continue;
        }
        temp_millidegrees = atoi(temp_str);

        // Determine LED color
        if (temp_millidegrees < 40000) {
            red_duty = 255;
            green_duty = 255;
            blue_duty = 0;
        } else if (temp_millidegrees < 60000) {
            red_duty = 255;
            green_duty = 0;
            blue_duty = 0;
        } else {
            red_duty = 0;
            green_duty = 255;
            blue_duty = 0;
        }

        // Set PWM values
        if (gpiod_line_set_value(red_line, 255 - red_duty) < 0) {
            perror("Failed to set Red PWM value");
            stop_flag = 1;
        }
        if (gpiod_line_set_value(green_line, 255 - green_duty) < 0) {
            perror("Failed to set Green PWM value");
            stop_flag = 1;
        }
        if (gpiod_line_set_value(blue_line, 255 - blue_duty) < 0) {
            perror("Failed to set Blue PWM value");
            stop_flag = 1;
        }

        // Print temperature and PWM values
        printf("Temperature: %d m°C, Red: %d, Green: %d, Blue: %d\n",
               temp_millidegrees, red_duty, green_duty, blue_duty);

        // Wait for next update
        usleep(UPDATE_INTERVAL);
    }

    // Clean up
    fclose(temp_file);
    gpiod_line_release(red_line);
    gpiod_line_release(green_line);
    gpiod_line_release(blue_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

