#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <curl/curl.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 4
#define DHT22_START_SIGNAL_US 1000
#define DHT22_RESPONSE_BITS 40
#define DHT22_CHECKSUM_BITS 8
#define DHT22_RETRY_COUNT 3
#define API_URL "http://yourserver.com/api/humidity"

typedef struct {
    char *data;
    size_t size;
} MemoryStruct;

static size_t WriteMemoryCallback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    MemoryStruct *mem = (MemoryStruct *)userp;

    char *ptr = realloc(mem->data, mem->size + realsize + 1);
    if(ptr == NULL) {
        // out of memory!
        printf("not enough memory (realloc returned NULL)\n");
        return 0;
    }

    mem->data = ptr;
    memcpy(&(mem->data[mem->size]), contents, realsize);
    mem->size += realsize;
    mem->data[mem->size] = 0;

    return realsize;
}

static int read_dht22(struct gpiod_chip *chip, int line_num, unsigned char *data, size_t data_size) {
    struct gpiod_line *line;
    int ret;

    line = gpiod_chip_get_line(chip, line_num);
    if (!line) {
        perror("Failed to get GPIO line");
        return -1;
    }

    ret = gpiod_line_request_output(line, "dht22", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(line);
        return -1;
    }

    // Start signal
    ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        perror("Failed to set GPIO line to low");
        gpiod_line_release(line);
        return -1;
    }
    usleep(DHT22_START_SIGNAL_US);
    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        perror("Failed to set GPIO line to high");
        gpiod_line_release(line);
        return -1;
    }

    // Wait for response
    usleep(100);

    ret = gpiod_line_request_input(line, "dht22");
    if (ret < 0) {
        perror("Failed to request GPIO line as input");
        gpiod_line_release(line);
        return -1;
    }

    // Read response
    for (size_t i = 0; i < data_size; i++) {
        data[i] = 0;
        for (int j = 0; j < 8; j++) {
            usleep(50);
            int value = gpiod_line_get_value(line);
            if (value < 0) {
                perror("Failed to read GPIO line value");
                gpiod_line_release(line);
                return -1;
            }
            data[i] = (data[i] << 1) | value;
        }
    }

    gpiod_line_release(line);
    return 0;
}

static int validate_dht22_response(unsigned char *data) {
    unsigned char checksum = 0;
    for (int i = 0; i < DHT22_CHECKSUM_BITS; i++) {
        checksum += data[i];
    }
    return checksum == data[DHT22_CHECKSUM_BITS];
}

static void post_data_to_api(const char *data) {
    CURL *curl;
    CURLcode res;
    MemoryStruct chunk;

    chunk.size = 0;
    chunk.data = malloc(1);  // will be grown as needed by the realloc above
    if(chunk.data == NULL) {
        fprintf(stderr, "Could not allocate memory for chunk data\n");
        return;
    }

    curl_global_init(CURL_GLOBAL_ALL);
    curl = curl_easy_init();
    if(curl) {
        curl_easy_setopt(curl, CURLOPT_URL, API_URL);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, data);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteMemoryCallback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, (void *)&chunk);

        res = curl_easy_perform(curl);
        if(res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }

        curl_easy_cleanup(curl);
    }

    free(chunk.data);
    curl_global_cleanup();
}

static void handle_sigint(int sig) {
    exit(0);
}

int main() {
    struct gpiod_chip *chip;
    unsigned char data[DHT22_RESPONSE_BITS / 8];
    int retry_count = 0;
    int ret;

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    while (retry_count < DHT22_RETRY_COUNT) {
        ret = read_dht22(chip, GPIO_LINE, data, sizeof(data));
        if (ret < 0) {
            retry_count++;
            continue;
        }

        if (validate_dht22_response(data)) {
            char json[256];
            snprintf(json, sizeof(json), "{\"humidity\": %d, \"temperature\": %d}", data[0], data[2]);
            post_data_to_api(json);
            break;
        } else {
            retry_count++;
        }
    }

    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

