#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <gpiod.h>
#include <sys/time.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x77
#define BMP180_CHIP_ID 0x55
#define BMP180_OVERSAMPLING 3
#define BMP180_CONVERSION_DELAY 26
#define BUTTON_PIN 4
#define DEBOUNCE_TIME 200000
#define LOG_FILE "pressure_log.txt"

static int i2c_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *button_line;
static int logging_enabled = 0;

static int read_i2c(uint8_t reg, uint8_t *data, size_t len) {
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Failed to write to I2C");
        return -1;
    }
    if (read(i2c_fd, data, len) != len) {
        perror("Failed to read from I2C");
        return -1;
    }
    return 0;
}

static int write_i2c(uint8_t reg, uint8_t *data, size_t len) {
    uint8_t buffer[len + 1];
    buffer[0] = reg;
    memcpy(buffer + 1, data, len);
    if (write(i2c_fd, buffer, len + 1) != len + 1) {
        perror("Failed to write to I2C");
        return -1;
    }
    return 0;
}

static int read_bmp180_chip_id(uint8_t *chip_id) {
    if (read_i2c(0xD0, chip_id, 1) != 0) {
        return -1;
    }
    return 0;
}

static int read_bmp180_calibration_data(int16_t *calibration_data) {
    uint8_t data[22];
    if (read_i2c(0xAA, data, 22) != 0) {
        return -1;
    }
    calibration_data[0] = (data[0] << 8) | data[1];
    calibration_data[1] = (data[2] << 8) | data[3];
    calibration_data[2] = (data[4] << 8) | data[5];
    calibration_data[3] = (data[6] << 8) | data[7];
    calibration_data[4] = (data[8] << 8) | data[9];
    calibration_data[5] = (data[10] << 8) | data[11];
    calibration_data[6] = (data[12] << 8) | data[13];
    calibration_data[7] = (data[14] << 8) | data[15];
    calibration_data[8] = (data[16] << 8) | data[17];
    calibration_data[9] = (data[18] << 8) | data[19];
    calibration_data[10] = (data[20] << 8) | data[21];
    return 0;
}

static int bmp180_read_temperature(int16_t *temperature) {
    uint8_t data[3];
    if (write_i2c(0xF4, (uint8_t[]){0xF4, 0x2E}, 2) != 0) {
        return -1;
    }
    usleep(BMP180_CONVERSION_DELAY * 1000);
    if (read_i2c(0xF6, data, 3) != 0) {
        return -1;
    }
    *temperature = (data[0] << 16) | (data[1] << 8) | data[2];
    return 0;
}

static int bmp180_read_pressure(int32_t *pressure) {
    uint8_t data[3];
    if (write_i2c(0xF4, (uint8_t[]){0xF4, 0x34 + (BMP180_OVERSAMPLING << 6)}, 2) != 0) {
        return -1;
    }
    usleep(BMP180_CONVERSION_DELAY * 1000);
    if (read_i2c(0xF6, data, 3) != 0) {
        return -1;
    }
    *pressure = (data[0] << 16) | (data[1] << 8) | data[2];
    return 0;
}

static int bmp180_compensate_temperature(int16_t temperature, int16_t *compensated_temperature) {
    int32_t UT, X1, X2, B5;
    UT = temperature;
    X1 = ((UT - calibration_data[0]) * calibration_data[1]) >> 15;
    X2 = (calibration_data[2] << 11) / (X1 + calibration_data[3]);
    B5 = X1 + X2;
    *compensated_temperature = (B5 + 8) >> 4;
    return 0;
}

static int bmp180_compensate_pressure(int32_t pressure, int32_t compensated_temperature, int32_t *compensated_pressure) {
    int32_t B6, B7, X1, X2, X3, B3, p;
    B6 = B5 - 4000;
    X1 = (calibration_data[4] * (B6 * B6) >> 12) >> 11;
    X2 = calibration_data[5] * B6 >> 11;
    X3 = X1 + X2;
    B3 = ((calibration_data[6] << 2) + X3) >> 2;
    B4 = (calibration_data[1] * 16384) + ((X3 * calibration_data[2]) >> 11);
    B7 = (pressure - B3) * (50000 >> BMP180_OVERSAMPLING);
    if (B7 < 0x80000000) {
        p = (B7 << 1) / B4;
    } else {
        p = (B7 / B4) << 1;
    }
    X1 = (p >> 8) * (p >> 8);
    X1 = (X1 * 3038) >> 16;
    X2 = (-7357 * p) >> 16;
    p = p + (X1 + X2 + 3791) >> 4;
    *compensated_pressure = p;
    return 0;
}

static void button_interrupt_handler(void *user_data) {
    static struct timeval last_interrupt_time;
    struct timeval current_time;
    gettimeofday(&current_time, NULL);
    if (current_time.tv_sec - last_interrupt_time.tv_sec > 0 || (current_time.tv_sec == last_interrupt_time.tv_sec && current_time.tv_usec - last_interrupt_time.tv_usec > DEBOUNCE_TIME)) {
        logging_enabled = !logging_enabled;
        if (logging_enabled) {
            printf("Logging enabled\n");
        } else {
            printf("Logging disabled\n");
        }
        last_interrupt_time = current_time;
    }
}

static void signal_handler(int signum) {
    if (signum == SIGINT) {
        if (i2c_fd >= 0) {
            close(i2c_fd);
        }
        if (chip != NULL) {
            gpiod_chip_close(chip);
        }
        exit(0);
    }
}

int main() {
    int16_t chip_id, calibration_data[11];
    int32_t temperature, pressure, compensated_temperature, compensated_pressure;
    struct timeval start_time, current_time;
    double elapsed_time;

    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return 1;
    }

    if (read_bmp180_chip_id(&chip_id) != 0) {
        fprintf(stderr, "Failed to read BMP180 chip ID\n");
        close(i2c_fd);
        return 1;
    }

    if (chip_id != BMP180_CHIP_ID) {
        fprintf(stderr, "Invalid BMP180 chip ID\n");
        close(i2c_fd);
        return 1;
    }

    if (read_bmp180_calibration_data(calibration_data) != 0) {
        fprintf(stderr, "Failed to read BMP180 calibration data\n");
        close(i2c_fd);
        return 1;
    }

    if ((chip = gpiod_chip_open("/dev/gpiochip0")) == NULL) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    if ((button_line = gpiod_chip_get_line(chip, BUTTON_PIN)) == NULL) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    if (gpiod_line_request_input(button_line, "button_interrupt_handler") != 0) {
        perror("Failed to request GPIO line input");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    if (gpiod_line_request_interrupt(button_line, GPIO_LINE_REQUEST_FLAG_EDGE_FALLING, button_interrupt_handler, NULL) != 0) {
        perror("Failed to request GPIO line interrupt");
        gpiod_line_release(button_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    signal(SIGINT, signal_handler);

    gettimeofday(&start_time, NULL);

    while (1) {
        if (logging_enabled) {
            if (bmp180_read_temperature(&temperature) != 0) {
                fprintf(stderr, "Failed to read BMP180 temperature\n");
                continue;
            }
            if (bmp180_read_pressure(&pressure) != 0) {
                fprintf(stderr, "Failed to read BMP180 pressure\n");
                continue;
            }
            if (bmp180_compensate_temperature(temperature, &compensated_temperature) != 0) {
                fprintf(stderr, "Failed to compensate BMP180 temperature\n");
                continue;
            }
            if (bmp180_compensate_pressure(pressure, compensated_temperature, &compensated_pressure) != 0) {
                fprintf(stderr, "Failed to compensate BMP180 pressure\n");
                continue;
            }
            gettimeofday(&current_time, NULL);
            elapsed_time = (current_time.tv_sec - start_time.tv_sec) + (current_time.tv_usec - start_time.tv_usec) / 1000000.0;
            if (elapsed_time >= 2.0) {
                start_time = current_time;
                FILE *log_file = fopen(LOG_FILE, "a");
                if (log_file == NULL) {
                    perror("Failed to open log file");
                    continue;
                }
                fprintf(log_file, "%.6f %.2f\n", elapsed_time, compensated_pressure / 100.0);
                fclose(log_file);
            }
        } else {
            printf("Logging disabled\n");
        }
        usleep(100000);
    }

    gpiod_line_release(button_line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return 0;
}

