#define DHT22_START_SIGNAL_US 1000
#define DHT22_RESPONSE_TIME_US 20
#define DHT22_RESPONSE_TIMEOUT_US 1000000
#define DHT22_BIT_DURATION_US 50
#define DHT22_RETRY_COUNT 3
#define DHT22_BACKOFF_US 2000000
#define DEFAULT_URL "http://your-the-library’s-API-call.com/api/humidity"
#define JSON_FORMAT "{\"humidity\":%.2f}"

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

size_t write_callback(void *ptr, size_t size, size_t nmemb, void *userdata) {
    return size * nmemb;
}

int read_dht22(struct gpiod_chip *chip, struct gpiod_line *line, float *humidity) {
    int ret;
    uint64_t start_time, end_time, duration;
    uint8_t data[5] = {0};
    uint8_t bit_count = 0;
    uint8_t bit = 0;
    uint8_t parity = 0;

    // Start signal
    ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to set GPIO line to low: %s", strerror(-ret));
        return -1;
    }
    usleep(DHT22_START_SIGNAL_US);
    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to set GPIO line to high: %s", strerror(-ret));
        return -1;
    }
    usleep(DHT22_RESPONSE_TIME_US);

    // Wait for response
    start_time = gpiod_line_get_timestamp_ns(line);
    while (1) {
        ret = gpiod_line_get_value(line);
        if (ret < 0) {
            syslog(LOG_ERR, "Failed to get GPIO line value: %s", strerror(-ret));
            return -1;
        }
        if (ret == 0) {
            break;
        }
        usleep(1);
        if (gpiod_line_get_timestamp_ns(line) - start_time > DHT22_RESPONSE_TIMEOUT_US) {
            syslog(LOG_ERR, "DHT22 response timeout");
            return -1;
        }
    }

    // Read data
    for (int i = 0; i < 40; i++) {
        start_time = gpiod_line_get_timestamp_ns(line);
        while (1) {
            ret = gpiod_line_get_value(line);
            if (ret < 0) {
                syslog(LOG_ERR, "Failed to get GPIO line value: %s", strerror(-ret));
                return -1;
            }
            if (ret != bit) {
                break;
            }
            usleep(1);
            if (gpiod_line_get_timestamp_ns(line) - start_time > DHT22_BIT_DURATION_US) {
                syslog(LOG_ERR, "DHT22 bit duration timeout");
                return -1;
            }
        }
        bit = !bit;
        if (i % 8 == 0) {
            parity = 0;
        }
        data[i / 8] <<= 1;
        data[i / 8] |= bit;
        parity ^= bit;
    }

    // Check checksum
    if (data[0] + data[1] + data[2] + data[3] != data[4]) {
        syslog(LOG_ERR, "DHT22 checksum error");
        return -1;
    }

    // Convert to humidity
    *humidity = (data[0] * 256 + data[1]) / 10.0;
    return 0;
}

