    CURL *curl;
    CURLcode res;
    char json[64];
    snprintf(json, sizeof(json), JSON_FORMAT, humidity);

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, (long)strlen(json));
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, curl_slist_append(NULL, "Content-Type: application/json"));
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);

        for (int i = 0; i < 3; i++) {
            res = curl_easy_perform(curl);
            if (res == CURLE_OK) {
                long http_code;
                curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
                if (http_code >= 200 && http_code < 300) {
                    break;
                }
            }
            sleep(1);
        }

        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();
    return (res == CURLE_OK);
}

int main(int argc, char *argv[]) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    float humidity;
    const char *url = DEFAULT_URL;

    // Parse command-line options
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-s") == 0 && i + 1 < argc) {
            url = argv[++i];
        }
    }

    // Initialize syslog
    openlog("dht22_sensor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize GPIO
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %s", strerror(errno));
        return EXIT_FAILURE;
    }
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        syslog(LOG_ERR, "Failed to get GPIO line: %s", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request_output(line, "dht22_sensor", 0);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to request GPIO line: %s", strerror(-ret));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!stop_flag) {
        for (int i = 0; i < DHT22_RETRY_COUNT; i++) {
            ret = read_dht22(chip, line, &humidity);
            if (ret == 0) {
                if (post_json(url, humidity)) {
                    syslog(LOG_INFO, "Successfully posted humidity: %.2f", humidity);
                    break;
                } else {
                    syslog(LOG_ERR, "Failed to post humidity, retrying...");
                }
            } else {
                syslog(LOG_ERR, "Failed to read DHT22, retrying...");
            }
            usleep(DHT22_BACKOFF_US);
        }
        sleep(10);
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    closelog();

    return EXIT_SUCCESS;
}

