        perror("Failed to open cur_state file for writing");
        return;
    }
    fprintf(file, "%d\n", state);
    fclose(file);
}

void log_fan_state_change(int state) {
    FILE *log_file = fopen(FAN_LOG_PATH, "a");
    if (!log_file) {
        perror("Failed to open fan log file for writing");
        return;
    }
    time_t now = time(NULL);
    fprintf(log_file, "%s: Fan state changed to %d\n", ctime(&now), state);
    fclose(log_file);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    int max_state = read_max_state(MAX_STATE_PATH);
    if (max_state < 0) {
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int current_state = -1;
    while (!stop_flag) {
        int temperature = read_temperature(CPU_TEMP_PATH);
        if (temperature < 0) {
            sleep(5);
            continue;
        }

        int new_state;
        if (temperature < 45) {
            new_state = 0;
        } else if (temperature < 55) {
            new_state = 1;
        } else if (temperature < 65) {
            new_state = 2;
        } else {
            new_state = 3;
        }

        if (new_state != current_state && new_state <= max_state) {
            write_fan_state(new_state);
            log_fan_state_change(new_state);
            current_state = new_state;
        }

        sleep(5);
    }

    write_fan_state(0);
    log_fan_state_change(0);

    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}
