#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>
#include <libgpiod/spi.h>

#define HEATER_PIN 18
#define SPI_CHIP 0
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 500000
#define TARGET_TEMP 50.0
#define PWM_FREQ 1000
#define PWM_RANGE 100
#define SAMPLE_INTERVAL 1000000
#define LOG_FILE "heater_log.txt"

static struct gpiod_chip *chip;
static struct gpiod_line *heater_line;
static struct gpiod_spi_chip *spi_chip;
static FILE *log_file;
static volatile sig_atomic_t running = 1;

static void signal_handler(int signum) {
    running = 0;
}

static float read_temperature() {
    uint8_t buffer[4];
    int ret = gpiod_spi_transfer(spi_chip, buffer, 4);
    if (ret < 0) {
        perror("Failed to read from SPI");
        return -1.0;
    }

    uint32_t thermocouple_data = (buffer[0] << 24) | (buffer[1] << 16) | (buffer[2] << 8) | buffer[3];
    uint8_t fault_bits = thermocouple_data & 0x00000007;

    if (fault_bits != 0) {
        fprintf(stderr, "MAX31855 fault detected: 0x%02X\n", fault_bits);
        return -1.0;
    }

    uint32_t thermocouple_value = (thermocouple_data >> 4) & 0x3FFF;
    float temperature = (thermocouple_value * 0.25) - 200.0;

    if (temperature < 0.0 || temperature > 100.0) {
        fprintf(stderr, "Temperature out of range: %.2f°C\n", temperature);
        return -1.0;
    }

    return temperature;
}

static void control_heater(float temperature, float *integral, float *last_error) {
    static float Kp = 1.0, Ki = 0.1, Kd = 0.01;
    float error = TARGET_TEMP - temperature;
    *integral += error;
    float derivative = error - *last_error;
    float output = Kp * error + Ki * *integral + Kd * derivative;

    if (output < 0.0) {
        output = 0.0;
    } else if (output > PWM_RANGE) {
        output = PWM_RANGE;
    }

    int duty_cycle = (int)output;
    gpiod_line_set_value(heater_line, duty_cycle);
    *last_error = error;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    heater_line = gpiod_chip_get_line(chip, HEATER_PIN);
    if (!heater_line) {
        perror("Failed to get heater line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int ret = gpiod_line_request_output(heater_line, "heater", 0);
    if (ret < 0) {
        perror("Failed to request heater line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    spi_chip = gpiod_spi_chip_open_by_name("spi0");
    if (!spi_chip) {
        perror("Failed to open SPI chip");
        gpiod_line_release(heater_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_spi_chip_close(spi_chip);
        gpiod_line_release(heater_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    float integral = 0.0, last_error = 0.0;

    while (running) {
        float temperature = read_temperature();
        if (temperature >= 0.0) {
            control_heater(temperature, &integral, &last_error);
            fprintf(log_file, "%.2f, %d, %.2f\n", temperature, (int)gpiod_line_get_value(heater_line), temperature);
            fflush(log_file);
        }

        usleep(SAMPLE_INTERVAL);
    }

    gpiod_line_set_value(heater_line, 0);
    fclose(log_file);
    gpiod_spi_chip_close(spi_chip);
    gpiod_line_release(heater_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

