    log_file = fopen("cooling_log.csv", "w");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp, Temperature (°C), Duty Cycle (%)\n");

    // Set up signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        // Read CPU temperature (this is a placeholder, replace with actual temperature reading)
        temperature = 50.0; // Example temperature

        // Map temperature to duty cycle
        duty_cycle = map_temp_to_duty(temperature);

        // Set PWM duty cycle
        if (gpiod_line_set_value(line, duty_cycle / 100)) {
            perror("Failed to set PWM duty cycle");
            cleanup(EXIT_FAILURE);
        }

        // Get current time
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("Failed to get current time");
            cleanup(EXIT_FAILURE);
        }

        // Format timestamp
        tm = localtime(&ts.tv_sec);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

        // Log reading
        fprintf(log_file, "%s, %.2f, %.2f\n", timestamp, temperature, duty_cycle);

        // Flush log file
        fflush(log_file);

        // Sleep for 5 seconds
        sleep(5);
    }

    return EXIT_SUCCESS;
}

