#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define SLF3S_ADDRESS 0x60
#define SF06_ADDRESS 0x70
#define MAX_RETRIES 3
#define CRC8_POLYNOMIAL 0x07

struct sensor_data {
    uint16_t flow;
    uint8_t crc;
};

static struct gpiod_chip *chip;
static int i2c_fd;

void handle_sigint(int sig) {
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(0);
}

uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = 0;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_sensor(int address, struct sensor_data *data) {
    uint8_t buffer[3];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_smbus_read_i2c_block_data(i2c_fd, address, 3, buffer) == 3) {
            data->flow = (buffer[0] << 8) | buffer[1];
            data->crc = buffer[2];
            if (data->crc == calculate_crc8(buffer, 2)) {
                return 0;
            }
        }
        retries++;
    }
    return -1;
}

int main() {
    struct sensor_data sensor1, sensor2;
    struct tm *tm_info;
    char timestamp[20];
    char log_entry[100];

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SF06_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        if (read_sensor(SLF3S_ADDRESS, &sensor1) == 0) {
            if (read_sensor(SLF3S_ADDRESS, &sensor2) == 0) {
                time_t now = time(NULL);
                tm_info = localtime(&now);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
                snprintf(log_entry, sizeof(log_entry), "%s,%d,%d\n", timestamp, sensor1.flow, sensor2.flow);
                if (fputs(log_entry, stdout) < 0) {
                    perror("Failed to write to stdout");
                }
                if (fputs(log_entry, fopen("flow_log.txt", "a")) < 0) {
                    perror("Failed to write to log file");
                }
            }
        }
        sleep(1);
    }

    close(i2c_fd);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

