static void cleanup(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (line_a) {
        gpiod_line_release(line_a);
    }
    if (line_b) {
        gpiod_line_release(line_b);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(signum);
}

static void log_position(double position) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d: %.2f\n",
            tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
            tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec, position);
    fflush(log_file);
}

int main() {
    struct gpiod_line_request_config config = {
        .consumer = "encoder_monitor",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
        .default_val = 0,
        .flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP,
    };

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line_a = gpiod_chip_get_line(chip, GPIO_LINE_A);
    if (!line_a) {
        perror("Failed to get GPIO line A");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line_b = gpiod_chip_get_line(chip, GPIO_LINE_B);
    if (!line_b) {
        perror("Failed to get GPIO line B");
        gpiod_line_release(line_a);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(line_a, &config) < 0) {
        perror("Failed to request GPIO line A");
        gpiod_line_release(line_b);
        gpiod_line_release(line_a);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(line_b, &config) < 0) {
        perror("Failed to request GPIO line B");
        gpiod_line_release(line_a);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(line_b);
        gpiod_line_release(line_a);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int state = 0;
    double position = 0.0;

    while (1) {
        int value_a = gpiod_line_get_value(line_a);
        int value_b = gpiod_line_get_value(line_b);

        if (value_a == 0 && value_b == 0) {
            state = 0;
        } else if (value_a == 0 && value_b == 1) {
            state = 1;
        } else if (value_a == 1 && value_b == 1) {
            state = 2;
        } else if (value_a == 1 && value_b == 0) {
            state = 3;
        }

        switch (state) {
            case 0:
                break;
            case 1:
                position += 1.0 / PULSES_PER_REV * 360.0;
                break;
            case 2:
                position -= 1.0 / PULSES_PER_REV * 360.0;
                break;
            case 3:
                position += 1.0 / PULSES_PER_REV * 360.0;
                break;
        }

        if (position < 0.0) {
            position += 360.0;
        } else if (position >= 360.0) {
            position -= 360.0;
        }

        log_position(position);
    }

    return EXIT_SUCCESS;
}

