This C program uses the `libgpiod` library to interact with the GPIO pins on a Raspberry Pi 4 Model B. It monitors a magnetic rotary encoder connected to GPIO17 and GPIO18, implementing a 2-bit quadrature state machine to resolve 360 pulses per revolution into a normalized angular position ranging from 0.00 to 360.00 degrees. The program logs each timestamped position change to a file named `encoder_log.txt`. It handles errors for GPIO initialization and file I/O operations, and ensures that all resources are cleanly released when the program receives a SIGINT or SIGTERM signal.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x50
#define LED_PIN 17
#define IR_THRESHOLD 2000
#define SAMPLE_INTERVAL 100

static struct gpiod_chip *chip;
static struct gpiod_line *led_line;
static FILE *log_file;

void cleanup() {
    if (log_file) {
        fclose(log_file);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(EXIT_SUCCESS);
}

void handle_signal(int signum) {
    cleanup();
}

int main() {
    struct timespec ts;
    struct tm *tm_info;
    uint8_t buffer[3];
    int ret;

    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open I2C bus
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Open LED GPIO line
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get LED GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(led_line, "ir_led", 0);
    if (ret < 0) {
        perror("Failed to request LED GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("adpd144ri_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Write CSV header
    fprintf(log_file, "timestamp,red,ir\n");

    while (1) {
        // Read sensor data
        ret = gpiod_i2c_read(chip, I2C_ADDRESS, buffer, sizeof(buffer));
        if (ret < 0) {
            perror("Failed to read from I2C sensor");
            cleanup();
        }

        // Parse sensor data
        uint16_t red = (buffer[0] << 8) | buffer[1];
        uint16_t ir = (buffer[2] << 8) | buffer[3];

        // Log data
        clock_gettime(CLOCK_REALTIME, &ts);
        tm_info = localtime(&ts.tv_sec);
        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d.%09ld,%u,%u\n",
                tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
                tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec, ts.tv_nsec,
                red, ir);

        // Activate LED if IR value exceeds threshold
        if (ir > IR_THRESHOLD) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }

        // Sleep for the specified interval
        usleep(SAMPLE_INTERVAL * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

