#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 18
#define LOG_FILE "rpm_log.txt"

static int pulse_count = 0;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static int sensor_detected = 1;

static void *gpio_thread(void *arg) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_event event;
    int ret;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return NULL;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return NULL;
    }

    ret = gpiod_line_request_input(line, "rpm_sensor");
    if (ret < 0) {
        perror("Failed to request GPIO line as input");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return NULL;
    }

    while (sensor_detected) {
        ret = gpiod_line_event_wait(line, 1000000); // 1 second
        if (ret < 0) {
            perror("Failed to wait for GPIO event");
            break;
        }

        ret = gpiod_line_event_read(line, &event);
        if (ret < 0) {
            perror("Failed to read GPIO event");
            break;
        }

        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            pthread_mutex_lock(&mutex);
            pulse_count++;
            pthread_mutex_unlock(&mutex);
        }
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return NULL;
}

static void signal_handler(int signum) {
    sensor_detected = 0;
}

int main() {
    pthread_t gpio_tid;
    FILE *log_file;
    time_t now;
    struct tm *tm_info;
    char timestamp[20];
    int ret;

    ret = pthread_create(&gpio_tid, NULL, gpio_thread, NULL);
    if (ret != 0) {
        perror("Failed to create GPIO thread");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        pthread_join(gpio_tid, NULL);
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        pthread_mutex_lock(&mutex);
        int current_count = pulse_count;
        pulse_count = 0;
        pthread_mutex_unlock(&mutex);

        if (current_count == 0) {
            fprintf(log_file, "0.00 RPM\n");
        } else {
            time(&now);
            tm_info = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
            fprintf(log_file, "%s %.2f RPM\n", timestamp, (current_count * 60.0));
        }

        fflush(log_file);
        sleep(1);
    }

    fclose(log_file);
    pthread_join(gpio_tid, NULL);
    pthread_mutex_destroy(&mutex);
    return EXIT_SUCCESS;
}

