#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_OUT 17
#define GPIO_GAIN 18
#define SAMPLE_INTERVAL 10  // 10 ms

static struct gpiod_chip *chip;
static struct gpiod_line *out_line;
static struct gpiod_line *gain_line;

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Shutting down...\n");
        if (out_line) gpiod_line_release(out_line);
        if (gain_line) gpiod_line_release(gain_line);
        if (chip) gpiod_chip_close(chip);
        exit(0);
    }
}

int main() {
    struct timespec ts;
    struct tm *tm_info;
    char timestamp[20];
    int last_state = 0, current_state = 0;

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request GPIO lines
    out_line = gpiod_chip_get_line(chip, GPIO_OUT);
    if (!out_line) {
        perror("Failed to get GPIO_OUT line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    gain_line = gpiod_chip_get_line(chip, GPIO_GAIN);
    if (!gain_line) {
        perror("Failed to get GPIO_GAIN line");
        gpiod_line_release(out_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set GPIO_GAIN line to output and set to LOW (60 dB gain)
    if (gpiod_line_request_output(gain_line, "audio_gain", 0) < 0) {
        perror("Failed to request GPIO_GAIN line as output");
        gpiod_line_release(out_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set GPIO_OUT line to input
    if (gpiod_line_request_input(out_line, "audio_out") < 0) {
        perror("Failed to request GPIO_OUT line as input");
        gpiod_line_release(gain_line);
        gpiod_line_release(out_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Print startup message
    printf("Audio peak detector started. Press Ctrl+C to stop.\n");

    while (1) {
        // Read current state of GPIO_OUT
        current_state = gpiod_line_get_value(out_line);
        if (current_state < 0) {
            perror("Failed to read GPIO_OUT line");
            handle_signal(SIGINT);  // Trigger cleanup and exit
            break;
        }

        // Check for rising edge
        if (current_state && !last_state) {
            // Get current time
            if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
                tm_info = localtime(&ts);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
                // Log the event
                printf("%s 1\n", timestamp);
                FILE *log_file = fopen("audio_log.txt", "a");
                if (log_file) {
                    fprintf(log_file, "%s 1\n", timestamp);
                    fclose(log_file);
                } else {
                    perror("Failed to open audio_log.txt for writing");
                }
            }
        }

        last_state = current_state;
        usleep(SAMPLE_INTERVAL * 1000);  // Sleep for 10 ms
    }

    // Clean up
    gpiod_line_release(gain_line);
    gpiod_line_release(out_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

