#define SLF3S4000B_CMD 0x00
#define SLF3S4000B_CRC_POLYNOMIAL 0x07
#define SLF3S4000B_CRC_INITIAL 0xFF

static struct gpiod_chip *chip;
static FILE *log_file;

void handle_sigint(int sig) {
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }
    exit(0);
}

uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = SLF3S4000B_CRC_INITIAL;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SLF3S4000B_CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    struct timespec ts;
    struct tm tm;
    uint8_t buffer[3];
    uint16_t raw_value;
    uint8_t crc;

    // Initialize GPIO driver
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("flow_log.csv", "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Register signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    while (1) {
        // Read from I2C sensor
        if (gpiod_chip_get_value(chip, 0) != 0) {
            fprintf(stderr, "I2C read failed\n");
            continue;
        }

        // Write command to sensor
        if (gpiod_chip_get_value(chip, 1) != 0) {
            fprintf(stderr, "I2C write failed\n");
            continue;
        }

        // Read three bytes from sensor
        if (gpiod_chip_get_value(chip, 2) != 0) {
            fprintf(stderr, "I2C read failed\n");
            continue;
        }

        // Parse raw value and CRC
        raw_value = (buffer[0] << 8) | buffer[1];
        crc = buffer[2];

        // Calculate expected CRC
        uint8_t expected_crc = calculate_crc8((uint8_t *)&raw_value, 2);

        // Validate CRC
        if (crc != expected_crc) {
            fprintf(stderr, "CRC validation failed\n");
            continue;
        }

        // Convert raw value to flow rate (example conversion, adjust as needed)
        double flow_rate = (double)raw_value * 0.01; // Example conversion factor

        // Get current time
        clock_gettime(CLOCK_REALTIME, &ts);
        localtime_r(&ts.tv_sec, &tm);

        // Log measurement
        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d,%f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, flow_rate);
        fflush(log_file);
    }

    // Clean up
    fclose(log_file);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

