#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define POLL_INTERVAL_MS 100
#define INTRUSION_TIMEOUT_S 5

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static int running = 1;

static void cleanup(void) {
    if (line) {
        gpiod_line_release(line);
        line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static void handle_signal(int sig) {
    running = 0;
}

int main(void) {
    struct timespec start_time, current_time;
    int last_state = 0;
    int current_state = 0;

    // Register signal handlers
    if (signal(SIGINT, handle_signal) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, handle_signal) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    // Request GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        cleanup();
        return EXIT_FAILURE;
    }

    // Configure GPIO line as input
    if (gpiod_line_request_input(line, "ttp223_tamper")) {
        perror("gpiod_line_request_input");
        cleanup();
        return EXIT_FAILURE;
    }

    // Initialize start time
    if (clock_gettime(CLOCK_MONOTONIC, &start_time) == -1) {
        perror("clock_gettime");
        cleanup();
        return EXIT_FAILURE;
    }

    while (running) {
        // Read current state of the GPIO line
        current_state = gpiod_line_get_value(line);
        if (current_state == -1) {
            perror("gpiod_line_get_value");
            cleanup();
            return EXIT_FAILURE;
        }

        // Check if the state has changed
        if (current_state != last_state) {
            if (current_state == 1) {
                // Touch detected, start timer
                start_time = current_time;
            } else {
                // Release detected, reset timer
                start_time = current_time;
            }
        }

        // Check if the touch has been held for more than 5 seconds
        if (current_state == 1) {
            if (clock_gettime(CLOCK_MONOTONIC, &current_time) == -1) {
                perror("clock_gettime");
                cleanup();
                return EXIT_FAILURE;
            }
            if (current_time.tv_sec - start_time.tv_sec > INTRUSION_TIMEOUT_S) {
                printf("Intrusion alert!\n");
                // Reset timer
                start_time = current_time;
            }
        }

        // Update last state
        last_state = current_state;

        // Sleep for the specified interval
        usleep(POLL_INTERVAL_MS * 1000);
    }

    // Cleanup on exit
    cleanup();
    return EXIT_SUCCESS;
}

