#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <alsa/asoundlib.h>
#include <gpiod.h>

#define I2S_DEVICE "/dev/snd/pcmC0D0c"
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define SAMPLE_RATE 44100
#define FRAMES_PER_PERIOD 1024
#define BUFFER_SIZE (FRAMES_PER_PERIOD * 4) // 16-bit PCM samples

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    int err;
    snd_pcm_t *handle;
    snd_pcm_hw_params_t *params;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    FILE *file;

    // Open ALSA device
    if ((err = snd_pcm_open(&handle, I2S_DEVICE, SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        fprintf(stderr, "Cannot open PCM device %s (%s)\n", I2S_DEVICE, snd_strerror(err));
        return EXIT_FAILURE;
    }

    // Allocate hardware parameters object
    snd_pcm_hw_params_alloca(&params);

    // Fill it in with default values
    if ((err = snd_pcm_hw_params_any(handle, params)) < 0) {
        fprintf(stderr, "Cannot initialize hardware parameters (%s)\n", snd_strerror(err));
        snd_pcm_close(handle);
        return EXIT_FAILURE;
    }

    // Set the desired hardware parameters
    if ((err = snd_pcm_hw_params_set_access(handle, params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0) {
        fprintf(stderr, "Cannot set access type (%s)\n", snd_strerror(err));
        snd_pcm_close(handle);
        return EXIT_FAILURE;
    }

    if ((err = snd_pcm_hw_params_set_format(handle, params, SND_PCM_FORMAT_S16_LE)) < 0) {
        fprintf(stderr, "Cannot set sample format (%s)\n", snd_strerror(err));
        snd_pcm_close(handle);
        return EXIT_FAILURE;
    }

    if ((err = snd_pcm_hw_params_set_rate_near(handle, params, &SAMPLE_RATE, 0)) < 0) {
        fprintf(stderr, "Cannot set sample rate (%s)\n", snd_strerror(err));
        snd_pcm_close(handle);
        return EXIT_FAILURE;
    }

    if ((err = snd_pcm_hw_params_set_channels(handle, params, 2)) < 0) {
        fprintf(stderr, "Cannot set channel count (%s)\n", snd_strerror(err));
        snd_pcm_close(handle);
        return EXIT_FAILURE;
    }

    if ((err = snd_pcm_hw_params(handle, params)) < 0) {
        fprintf(stderr, "Cannot set hardware parameters (%s)\n", snd_strerror(err));
        snd_pcm_close(handle);
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    if ((chip = gpiod_chip_open_by_name(GPIO_CHIP)) == NULL) {
        fprintf(stderr, "Failed to open GPIO chip %s\n", GPIO_CHIP);
        snd_pcm_close(handle);
        return EXIT_FAILURE;
    }

    // Request GPIO line
    if ((line = gpiod_chip_get_line(chip, GPIO_LINE)) == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d\n", GPIO_LINE);
        gpiod_chip_close(chip);
        snd_pcm_close(handle);
        return EXIT_FAILURE;
    }

    // Configure GPIO line as output
    if ((err = gpiod_line_request_output(line, "channel_select")) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output (%s)\n", GPIO_LINE, gpiod_error_text(err));
        gpiod_chip_close(chip);
        snd_pcm_close(handle);
        return EXIT_FAILURE;
    }

    // Open output file
    if ((file = fopen("audio_capture.pcm", "wb")) == NULL) {
        perror("Failed to open output file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        snd_pcm_close(handle);
        return EXIT_FAILURE;
    }

    // Set GPIO line to select left channel
    if ((err = gpiod_line_set_value(line, 0)) < 0) {
        fprintf(stderr, "Failed to set GPIO line %d to 0 (%s)\n", GPIO_LINE, gpiod_error_text(err));
        fclose(file);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        snd_pcm_close(handle);
        return EXIT_FAILURE;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Start capturing audio
    char buffer[BUFFER_SIZE];
    while (running) {
        if ((err = snd_pcm_readi(handle, buffer, FRAMES_PER_PERIOD)) != FRAMES_PER_PERIOD) {
            fprintf(stderr, "Read error: %s\n", snd_strerror(err));
            break;
        }
        if (fwrite(buffer, 1, BUFFER_SIZE, file) != BUFFER_SIZE) {
            perror("Write error");
            break;
        }
    }

    // Clean up
    fclose(file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    snd_pcm_close(handle);

    return EXIT_SUCCESS;
}

