    }

    // Request GPIO line
    if ((line = gpiod_chip_get_line(chip, GPIO_LINE)) == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d\n", GPIO_LINE);
        gpiod_chip_close(chip);
        snd_pcm_close(handle);
        return EXIT_FAILURE;
    }

    // Configure GPIO line as output
    if ((err = gpiod_line_request_output(line, "channel_select")) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output (%s)\n", GPIO_LINE, gpiod_error_text(err));
        gpiod_chip_close(chip);
        snd_pcm_close(handle);
        return EXIT_FAILURE;
    }

    // Open output file
    if ((file = fopen("audio_capture.pcm", "wb")) == NULL) {
        perror("Failed to open output file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        snd_pcm_close(handle);
        return EXIT_FAILURE;
    }

    // Set GPIO line to select left channel
    if ((err = gpiod_line_set_value(line, 0)) < 0) {
        fprintf(stderr, "Failed to set GPIO line %d to 0 (%s)\n", GPIO_LINE, gpiod_error_text(err));
        fclose(file);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        snd_pcm_close(handle);
        return EXIT_FAILURE;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Start capturing audio
    char buffer[BUFFER_SIZE];
    while (running) {
        if ((err = snd_pcm_readi(handle, buffer, FRAMES_PER_PERIOD)) != FRAMES_PER_PERIOD) {
            fprintf(stderr, "Read error: %s\n", snd_strerror(err));
            break;
        }
        if (fwrite(buffer, 1, BUFFER_SIZE, file) != BUFFER_SIZE) {
            perror("Write error");
            break;
        }
    }

    // Clean up
    fclose(file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    snd_pcm_close(handle);

    return EXIT_SUCCESS;
}
