#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_DO 4
#define GPIO_PWM 18
#define PWM_FREQ 100
#define DEBOUNCE_TIME 50
#define LOG_FILE "flame_log.txt"

static struct gpiod_chip *chip;
static struct gpiod_line *do_line, *pwm_line;
static FILE *log_file;
static int running = 1;

void log_event(const char *event) {
    time_t now = time(NULL);
    char *iso_time = ctime(&now);
    iso_time[strlen(iso_time) - 1] = '\0'; // Remove newline
    fprintf(log_file, "%s: %s\n", iso_time, event);
    fflush(log_file);
}

void handle_signal(int sig) {
    running = 0;
}

int main() {
    struct gpiod_line_request_config config;
    struct timespec ts;
    int do_state = -1, last_do_state = -1;

    // Initialize libgpiod
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request GPIO4 for input
    memset(&config, 0, sizeof(config));
    config.consumer = "flame_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    do_line = gpiod_chip_get_line(chip, GPIO_DO);
    if (!do_line) {
        perror("Failed to get GPIO4 line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request(do_line, &config)) {
        perror("Failed to request GPIO4 line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO18 for output
    memset(&config, 0, sizeof(config));
    config.consumer = "cooling_fan";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    pwm_line = gpiod_chip_get_line(chip, GPIO_PWM);
    if (!pwm_line) {
        perror("Failed to get GPIO18 line");
        gpiod_line_release(do_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request(pwm_line, &config)) {
        perror("Failed to request GPIO18 line");
        gpiod_line_release(do_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(pwm_line);
        gpiod_line_release(do_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Log system start
    log_event("System start");

    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (running) {
        // Read GPIO4 state
        if (gpiod_line_get_value(do_line, &do_state)) {
            perror("Failed to read GPIO4 state");
            continue;
        }

        // Apply software debounce
        if (do_state != last_do_state) {
            usleep(DEBOUNCE_TIME * 1000);
            if (gpiod_line_get_value(do_line, &do_state)) {
                perror("Failed to read GPIO4 state after debounce");
                continue;
            }
        }

        // Check for flame detection
        if (do_state == 0) {
            if (last_do_state == 1) {
                log_event("Flame detected");
                gpiod_line_set_value(pwm_line, 1);
            }
        } else {
            if (last_do_state == 0) {
                log_event("Flame end");
                gpiod_line_set_value(pwm_line, 0);
            }
        }

        last_do_state = do_state;
        usleep(50 * 1000); // Wait 50 ms
    }

    // Log program shutdown
    log_event("Program shutdown");

    // Clean up
    gpiod_line_set_value(pwm_line, 0);
    gpiod_line_release(pwm_line);
    gpiod_line_release(do_line);
    gpiod_chip_close(chip);
    fclose(log_file);

    return EXIT_SUCCESS;
}

