#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 20
#define LOG_FILE "flame_log.txt"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        if (log_file) {
            fclose(log_file);
        }
        if (line) {
            gpiod_line_release(line);
        }
        if (chip) {
            gpiod_chip_close(chip);
        }
        exit(EXIT_SUCCESS);
    }
}

int main() {
    struct timespec ts;
    int current_state = -1;
    int new_state;

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure the GPIO line as input
    if (gpiod_line_request_input(line, "flame_sensor")) {
        perror("Failed to request GPIO line as input");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        // Read the current state of the GPIO line
        new_state = gpiod_line_get_value(line);
        if (new_state == -1) {
            perror("Failed to read GPIO line value");
            break;
        }

        // Check for state change
        if (new_state != current_state) {
            // Get the current time
            if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
                perror("Failed to get current time");
                break;
            }

            // Format the ISO 8601 UTC timestamp
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", gmtime(&ts.tv_sec));

            // Write the timestamp and new state to the log file
            fprintf(log_file, "%s: %s\n", timestamp, new_state ? "Flame Detected" : "Flame Cleared");
            fflush(log_file);

            // Update the current state
            current_state = new_state;
        }

        // Sleep for 100 ms
        usleep(100 * 1000);
    }

    // Clean up resources
    if (log_file) {
        fclose(log_file);
    }
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

