#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x44
#define OPT3001_CONFIG 0x01
#define OPT3001_RESULT 0x00
#define OPT3001_CONV_TIME 100  // 100 ms

#define FILENAME "light_data.txt"

static struct gpiod_chip *chip = NULL;
static FILE *file = NULL;

void handle_sigint(int sig) {
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (file) {
        fclose(file);
    }
    exit(0);
}

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

int read_lux(struct gpiod_chip *chip, int addr) {
    uint8_t config[2] = {OPT3001_CONFIG, 0x10};  // Continuous conversion, automatic full-scale range
    uint8_t result[2];
    int ret;

    ret = gpiod_chip_i2c_write(chip, addr, config, sizeof(config));
    if (ret < 0) {
        log_error("Failed to write to OPT3001");
        return -1;
    }

    ret = gpiod_chip_i2c_read(chip, addr, result, sizeof(result));
    if (ret < 0) {
        log_error("Failed to read from OPT3001");
        return -1;
    }

    uint16_t lux_raw = (result[0] << 8) | result[1];
    double lux = lux_raw * 0.045 * 0.001;  // Conversion factor from raw to lux

    return (int)(lux * 1000);  // Return lux value in millilux
}

int main() {
    struct timespec ts;
    char timestamp[20];
    int lux;

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        log_error("Failed to open GPIO chip");
        return 1;
    }

    file = fopen(FILENAME, "a");
    if (!file) {
        log_error("Failed to open file");
        gpiod_chip_close(chip);
        return 1;
    }

    while (1) {
        lux = read_lux(chip, I2C_ADDR);
        if (lux >= 0) {
            clock_gettime(CLOCK_REALTIME, &ts);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", &ts);
            fprintf(file, "%s,%d\n", timestamp, lux);
            fflush(file);
        }

        usleep(OPT3001_CONV_TIME * 1000);
    }

    fclose(file);
    gpiod_chip_close(chip);
    return 0;
}

