This C program interfaces with a Texas Instruments OPT3001 Ambient Light Sensor on I2C bus 1 of a Raspberry Pi Zero W. It configures the sensor for continuous conversion mode with automatic full-scale range, reads lux values approximately every 100 ms conversion time, and appends each reading to a file named `light_data.txt` prefixed with an ISO-8601 timestamp. The program robustly handles I2C transaction failures and sensor-absent conditions by retrying or logging errors without crashing. It performs a clean shutdown on receipt of SIGINT or SIGTERM by releasing the I2C bus handle, any driver resources, and closing all open file handles on every exit path.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define LOG_INTERVAL 1

volatile sig_atomic_t stop_flag = 0;

void sigint_handler(int signum) {
    stop_flag = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct timespec ts;
    char timestamp[20];
    int value;

    // Install SIGINT handler
    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        perror("Failed to install SIGINT handler");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure line as input with pull-up
    if (gpiod_line_request_input(line, "flame_detect") < 0) {
        perror("Failed to request GPIO line as input");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!stop_flag) {
        // Read line value
        value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("Failed to read GPIO line value");
            continue;
        }

        // Get current time
        if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
            perror("Failed to get current time");
            continue;
        }

        // Format timestamp
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        // Log status
        printf("%s Flame Detected: %s\n", timestamp, value == 0 ? "YES" : "NO");

        // Sleep for the specified interval
        sleep(LOG_INTERVAL);
    }

    // Cleanup
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

