This C program reads the states of three GPIO pins (GPIO17, GPIO18, GPIO27) connected to a Keywish KY-033 3-Way Tracing Sensor on a Raspberry Pi Zero W. It polls each pin every 50 ms, prints the current states to the console, and handles SIGINT and SIGTERM to perform a graceful shutdown. The program uses the libgpiod library for GPIO operations and checks the return value of every library API call, printing an error message to stderr and exiting with a non-zero status on any failure.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINES "2,3,4,5,6,7,8,9"
#define POLL_INTERVAL_MS 100

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[8] = {NULL};
static int running = 1;

void handle_sigint(int sig) {
    running = 0;
}

int main() {
    struct timespec ts;
    int ret;

    // Register signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Request the GPIO lines
    for (int i = 0; i < 8; i++) {
        lines[i] = gpiod_chip_get_line(chip, i + 2);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %d: %s\n", i + 2, strerror(errno));
            goto cleanup;
        }
        ret = gpiod_line_request_input(lines[i], "touch_sensor");
        if (ret < 0) {
            fprintf(stderr, "Failed to request input on line %d: %s\n", i + 2, strerror(errno));
            goto cleanup;
        }
    }

    // Poll and log the state of each channel
    while (running) {
        for (int i = 0; i < 8; i++) {
            ret = gpiod_line_get_value(lines[i]);
            if (ret < 0) {
                fprintf(stderr, "Failed to read line %d: %s\n", i + 2, strerror(errno));
                goto cleanup;
            }
            printf("%ld.%03ld: Channel %d: %d\n", time(NULL), ts.tv_nsec / 1000000, i + 1, ret);
        }
        usleep(POLL_INTERVAL_MS * 1000);
    }

cleanup:
    // Release resources
    for (int i = 0; i < 8; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

