#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_OFFSETS {2, 3, 4, 5, 6, 17, 27, 22}
#define SAMPLE_INTERVAL_US 100000

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[8];
    struct gpiod_line_request req;
    int ret;

    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request lines
    memset(&req, 0, sizeof(req));
    req.consumer = "TTP226";
    req.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    req.flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN;

    for (int i = 0; i < 8; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_OFFSETS[i]);
        if (!lines[i]) {
            perror("Failed to get GPIO line");
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        ret = gpiod_line_request_bulk(&req, lines, 1);
        if (ret < 0) {
            perror("Failed to request GPIO line");
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    // Main loop
    while (running) {
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = SAMPLE_INTERVAL_US * 1000;

        for (int i = 0; i < 8; i++) {
            int value = gpiod_line_get_value(lines[i]);
            if (value < 0) {
                perror("Failed to read GPIO line");
                running = 0;
                break;
            }
            printf("%c%d", value ? '+' : '-', i + 1);
        }
        printf("\n");

        nanosleep(&ts, NULL);
    }

    // Release resources
    for (int i = 0; i < 8; i++) {
        gpiod_line_release_bulk(lines, 1);
    }
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

