This C program for a Raspberry Pi 3 Model B+ reads a TTP226 8-channel digital touch sensor connected on the GPIO bus. It configures the eight sensor output pins OUT1-OUT8 as Broadcom GPIO 2-9 inputs with pull-down resistors, initializes the libgpiod library, and enters a loop that calls the library's API function with a 100 ms sampling interval. It prints the state of each channel to the console and handles SIGINT and SIGTERM signals to exit cleanly.

code:
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 5
#define INTERVAL 500000 // 500ms in microseconds

static struct gpiod_chip *chip;
static struct gpiod_line *line1, *line2;

void cleanup(int signum) {
    if (line1) {
        gpiod_line_release(line1);
    }
    if (line2) {
        gpiod_line_release(line2);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    struct gpiod_line_request_config config = {
        .consumer = "hall_effect",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
    };

    // Initialize libgpiod
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request GPIO lines
    line1 = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (!line1) {
        perror("Failed to get GPIO line 1");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line2 = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (!line2) {
        perror("Failed to get GPIO line 2");
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request lines as input
    if (gpiod_line_request(line1, &config)) {
        perror("Failed to request GPIO line 1");
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(line2, &config)) {
        perror("Failed to request GPIO line 2");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Register signal handler for SIGINT
    if (signal(SIGINT, cleanup) == SIG_ERR) {
        perror("Failed to register signal handler");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        int value1 = gpiod_line_get_value(line1);
        int value2 = gpiod_line_get_value(line2);

        if (value1 == -1 || value2 == -1) {
            perror("Failed to read GPIO line value");
            cleanup(0);
        }

        printf("Sensor 1: %s, Sensor 2: %s\n", value1 ? "LOW" : "HIGH", value2 ? "LOW" : "HIGH");

        usleep(INTERVAL);
    }

    return EXIT_SUCCESS;
}

