#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 7

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static int tilt_state = -1;

static void handle_sigint(int sig) {
    if (gpiod_line_release(line) < 0) {
        perror("Failed to release GPIO line");
    }
    if (gpiod_chip_close(chip) < 0) {
        perror("Failed to close GPIO chip");
    }
    exit(EXIT_FAILURE);
}

static void log_tilt_state(int new_state) {
    if (new_state != tilt_state) {
        tilt_state = new_state;
        printf("%s\n", new_state ? "Not Tilted" : "Tilted");
        fflush(stdout);
    }
}

int main(void) {
    struct gpiod_line_request req = {
        .consumer = "tilt_sensor",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
        .default_val = 1,
        .flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP,
    };

    printf("Starting Tilt Sensor Monitor...\n");

    if (signal(SIGINT, handle_sigint) == SIG_ERR) {
        perror("Failed to set SIGINT handler");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(line, &req) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("Failed to read GPIO line");
            handle_sigint(0);
        } else {
            log_tilt_state(value);
        }
        usleep(100 * 1000); // 100 ms
    }

    return EXIT_SUCCESS;
}

