#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x60
#define UV_INDEX_REG 0x20
#define ALS_VISIBLE_REG 0x21
#define CSV_FILE "uv_als_log.csv"

static struct gpiod_chip *chip;
static FILE *log_file;

void cleanup() {
    if (log_file) {
        fclose(log_file);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(EXIT_FAILURE);
}

void handle_signal(int sig) {
    cleanup();
}

int main() {
    struct gpiod_line *line;
    struct timespec ts;
    uint8_t data[2];
    char timestamp[20];
    char log_entry[100];

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open I2C bus
    chip = gpiod_chip_open_by_number(I2C_BUS);
    if (!chip) {
        perror("Failed to open I2C bus");
        cleanup();
    }

    // Open log file
    log_file = fopen(CSV_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
    }

    // Write header to log file
    fprintf(log_file, "timestamp,uv_index,als_visible\n");

    while (1) {
        // Read UV index
        if (gpiod_chip_i2c_read(chip, I2C_ADDR, UV_INDEX_REG, data, 2) != 2) {
            fprintf(stderr, "Failed to read UV index\n");
            cleanup();
        }

        // Read visible ambient light
        if (gpiod_chip_i2c_read(chip, I2C_ADDR, ALS_VISIBLE_REG, data, 2) != 2) {
            fprintf(stderr, "Failed to read visible ambient light\n");
            cleanup();
        }

        // Get current timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("Failed to get current time");
            cleanup();
        }

        // Format timestamp
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        // Format log entry
        snprintf(log_entry, sizeof(log_entry), "%s,%d,%d\n", timestamp, data[0], data[1]);

        // Print log entry to console
        printf("%s", log_entry);

        // Write log entry to file
        if (fputs(log_entry, log_file) == EOF) {
            perror("Failed to write to log file");
            cleanup();
        }

        // Flush log file buffer
        fflush(log_file);

        // Sleep for 1 second
        sleep(1);
    }

    return 0;
}

