This C program interfaces with a Silicon Labs Si1145 UV Index and Ambient Light sensor on I2C bus 1, samples the sensor once every second, and on each sample prints the UV index and visible ambient light reading to the console while also appending a line to a CSV file named `uv_als_log.csv` containing the timestamp, uv_index, and als_visible columns. The program handles any I2C communication errors gracefully, detects and reports a missing sensor or bus errors robustly, and ensures that all resources such as the I2C file descriptor and the log file are cleanly released on every exit path, including proper handling of SIGINT and SIGTERM signals.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SLF3S_ADDRESS 0x60
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define ALARM_PIN 17
#define START_COMMAND 0x01
#define MEASUREMENT_INTERVAL 1000000 // 1 second in microseconds
#define ALARM_INTERVAL 100000 // 100 ms in microseconds
#define MIN_FLOW_RATE 0.5 // 0.5 ml/min
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF

volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

int calculate_crc(uint8_t *data, size_t length) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc = crc << 1;
            }
        }
    }
    return crc;
}

int read_flow_rate(int fd) {
    uint8_t buffer[3];
    if (read(fd, buffer, sizeof(buffer)) != sizeof(buffer)) {
        perror("Failed to read from I2C device");
        return -1;
    }
    uint8_t crc = calculate_crc(buffer, 2);
    if (crc != buffer[2]) {
        fprintf(stderr, "CRC error in I2C read\n");
        return -1;
    }
    return (buffer[0] << 8) | buffer[1];
}

void log_flow_rate(double flow_rate) {
    FILE *log_file = fopen("flow_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }
    fprintf(log_file, "%.2f ml/min\n", flow_rate);
    fclose(log_file);
}

int main() {
    int i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SLF3S_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open(GPIO_CHIP);
    if (chip == NULL) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (line == NULL) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "flow_alarm", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    while (running) {
        if (write(i2c_fd, &START_COMMAND, 1) != 1) {
            perror("Failed to send start command to sensor");
        } else {
            usleep(ALARM_INTERVAL);
            int flow_rate1 = read_flow_rate(i2c_fd);
            int flow_rate2 = read_flow_rate(i2c_fd);

            double average_flow_rate = 0.0;
            int valid_readings = 0;

            if (flow_rate1 >= 0) {
                average_flow_rate += flow_rate1;
                valid_readings++;
            }
            if (flow_rate2 >= 0) {
                average_flow_rate += flow_rate2;
                valid_readings++;
            }

            if (valid_readings > 0) {
                average_flow_rate /= valid_readings;
                log_flow_rate(average_flow_rate);

                if (average_flow_rate < MIN_FLOW_RATE) {
                    gpiod_line_set_value(line, 1);
                } else {
                    gpiod_line_set_value(line, 0);
                }
            }
        }

        sleep(1);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

