#define BUFFER_SIZE 100
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 4

struct detection {
    time_t timestamp;
    int detected;
};

struct detection buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_full = 0;

void handle_sigint(int sig) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_release(line);
    if (ret < 0) {
        fprintf(stderr, "Failed to release GPIO line\n");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_chip_close(chip);

    printf("Buffer contents:\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        struct detection *entry = &buffer[(buffer_index + i) % BUFFER_SIZE];
        printf("%ld: %s\n", entry->timestamp, entry->detected ? "Detected" : "Not Detected");
    }

    exit(EXIT_SUCCESS);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;
    struct timespec ts;
    struct detection current_detection;

