            fprintf(stderr, "Failed to read GPIO line value\n");
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        current_detection.timestamp = ts.tv_sec;

        buffer[buffer_index] = current_detection;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        if (buffer_index == 0) {
            buffer_full = 1;
        }

        if (current_detection.detected) {
            printf("Obstacle detected\n");
        }

        nanosleep(&(struct timespec){.tv_sec = 0, .tv_nsec = 50000000}, NULL);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
