#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x53
#define SDA_PIN 2
#define SCL_PIN 3
#define SAMPLE_INTERVAL 500000
#define TIMEOUT 1000000

static int i2c_fd = -1;
static FILE *csv_fd = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *sda_line = NULL;
static struct gpiod_line *scl_line = NULL;

void cleanup() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (csv_fd) {
        fclose(csv_fd);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

void handle_signal(int signum) {
    cleanup();
    exit(signum);
}

int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buffer[2] = {reg, value};
    if (write(fd, buffer, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

int i2c_read_byte(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write failed");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

int main() {
    struct timespec start, now;
    uint8_t x, y, z;
    char timestamp[20];

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize GPIO
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    sda_line = gpiod_chip_get_line(chip, SDA_PIN);
    if (!sda_line) {
        perror("Failed to get SDA line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    scl_line = gpiod_chip_get_line(chip, SCL_PIN);
    if (!scl_line) {
        perror("Failed to get SCL line");
        gpiod_line_release(sda_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(sda_line, "sda", 0) < 0) {
        perror("Failed to request SDA line");
        gpiod_line_release(sda_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(scl_line, "scl", 0) < 0) {
        perror("Failed to request SCL line");
        gpiod_line_release(sda_line);
        gpiod_line_release(scl_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initialize I2C
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        cleanup();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        cleanup();
        return EXIT_FAILURE;
    }

    // Switch sensor to appropriate mode
    if (i2c_write_byte(i2c_fd, 0x00, 0x01) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    // Wait for sensor to become active
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &now);
        if (now.tv_sec - start.tv_sec > 1) {
            fprintf(stderr, "Sensor did not become active within 1 second\n");
            cleanup();
            return EXIT_FAILURE;
        }
        if (i2c_read_byte(i2c_fd, 0x01, &x) == 0) {
            break;
        }
        usleep(10000);
    }

    // Open CSV file
    csv_fd = fopen("fan_health.csv", "a");
    if (!csv_fd) {
        perror("Failed to open CSV file");
        cleanup();
        return EXIT_FAILURE;
    }

    // Write header row if file is newly created
    if (fseek(csv_fd, 0, SEEK_END) == 0 && ftell(csv_fd) == 0) {
        fprintf(csv_fd, "Timestamp,X,Y,Z\n");
    }

    // Poll acceleration registers every 500ms
    while (1) {
        if (i2c_read_byte(i2c_fd, 0x02, &x) < 0) {
            continue;
        }
        if (i2c_read_byte(i2c_fd, 0x03, &y) < 0) {
            continue;
        }
        if (i2c_read_byte(i2c_fd, 0x04, &z) < 0) {
            continue;
        }

        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", tm);

        fprintf(csv_fd, "%s,%d,%d,%d\n", timestamp, x, y, z);
        fflush(csv_fd);

        usleep(SAMPLE_INTERVAL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

