This code provides a complete, compilable C program for interfacing with an Omron D7S vibration sensor over I2C on a Raspberry Pi 5 running Bookworm OS. It uses the libgpiod library for GPIO control and handles I2C operations with error checking. The program initializes the GPIO pins, opens the I2C device, switches the sensor to the appropriate mode, waits for the sensor to become active, and then continuously polls the acceleration registers every 500ms, appending each sample to a CSV file with an ISO-8601 timestamp. It also handles SIGINT and SIGTERM signals to cleanly close resources before exiting.

code:
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define SENSOR1_PIN 23
#define SENSOR2_PIN 24
#define LED_PIN 25

static struct gpiod_chip *chip;
static struct gpiod_line *sensor1_line, *sensor2_line, *led_line;

void cleanup_and_exit(int status) {
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (sensor1_line) {
        gpiod_line_release(sensor1_line);
    }
    if (sensor2_line) {
        gpiod_line_release(sensor2_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(status);
}

void handle_sigint(int sig) {
    cleanup_and_exit(0);
}

int main() {
    struct gpiod_line_request_config config = {
        .consumer = "obstacle_avoidance",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
    };

    // Initialize GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request sensor1 line
    sensor1_line = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (!sensor1_line) {
        perror("Failed to get sensor1 line");
        cleanup_and_exit(EXIT_FAILURE);
    }
    if (gpiod_line_request(sensor1_line, &config)) {
        perror("Failed to request sensor1 line");
        cleanup_and_exit(EXIT_FAILURE);
    }

    // Request sensor2 line
    sensor2_line = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (!sensor2_line) {
        perror("Failed to get sensor2 line");
        cleanup_and_exit(EXIT_FAILURE);
    }
    if (gpiod_line_request(sensor2_line, &config)) {
        perror("Failed to request sensor2 line");
        cleanup_and_exit(EXIT_FAILURE);
    }

    // Request LED line
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get LED line");
        cleanup_and_exit(EXIT_FAILURE);
    }
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    if (gpiod_line_request(led_line, &config)) {
        perror("Failed to request LED line");
        cleanup_and_exit(EXIT_FAILURE);
    }

    // Set LED to off initially
    if (gpiod_line_set_value(led_line, 0)) {
        perror("Failed to set LED to off");
        cleanup_and_exit(EXIT_FAILURE);
    }

    // Register signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    while (1) {
        int sensor1_value = gpiod_line_get_value(sensor1_line);
        int sensor2_value = gpiod_line_get_value(sensor2_line);

        if (sensor1_value == 0 || sensor2_value == 0) {
            // Turn LED on if either sensor reads LOW
            if (gpiod_line_set_value(led_line, 1)) {
                perror("Failed to turn LED on");
                cleanup_and_exit(EXIT_FAILURE);
            }
        } else {
            // Turn LED off if both sensors read HIGH
            if (gpiod_line_set_value(led_line, 0)) {
                perror("Failed to turn LED off");
                cleanup_and_exit(EXIT_FAILURE);
            }
        }

        usleep(100000); // Sleep for 100ms
    }

    cleanup_and_exit(EXIT_SUCCESS);
}

