#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define SENSOR1_PIN 17
#define SENSOR2_PIN 18
#define STALL_DURATION 2
#define LOG_FILE "stall_log.txt"

static struct gpiod_chip *chip;
static struct gpiod_line *line1, *line2;
static FILE *log_file = NULL;

void handle_signal(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (line1) {
        gpiod_line_release(line1);
    }
    if (line2) {
        gpiod_line_release(line2);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(signum);
}

int main() {
    struct timespec start_time, current_time;
    int sensor1_state = 1, sensor2_state = 1;
    int stall_count = 0;

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request GPIO lines
    line1 = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (!line1) {
        perror("Failed to get GPIO line 1");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line2 = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (!line2) {
        perror("Failed to get GPIO line 2");
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure GPIO lines as input
    if (gpiod_line_request_input(line1, "sensor1") < 0) {
        perror("Failed to request input for GPIO line 1");
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line2, "sensor2") < 0) {
        perror("Failed to request input for GPIO line 2");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        // Read sensor states
        sensor1_state = gpiod_line_get_value(line1);
        sensor2_state = gpiod_line_get_value(line2);

        if (sensor1_state == 0 && sensor2_state == 0) {
            if (stall_count == 0) {
                clock_gettime(CLOCK_REALTIME, &start_time);
            }
            stall_count++;
        } else {
            if (stall_count >= 2) {
                clock_gettime(CLOCK_REALTIME, &current_time);
                if (current_time.tv_sec - start_time.tv_sec >= STALL_DURATION) {
                    char timestamp[20];
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&start_time.tv_sec));
                    fprintf(log_file, "%s - Stall detected\n", timestamp);
                    fflush(log_file);
                }
            }
            stall_count = 0;
        }

        // Sleep for a short period to avoid high CPU usage
        usleep(100000);
    }

    // Clean up
    fclose(log_file);
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

