#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x1E
#define TMAG5170_REG_CONFIG 0x00
#define TMAG5170_REG_DATA_X 0x01
#define TMAG5170_REG_DATA_Y 0x03
#define TMAG5170_REG_DATA_Z 0x05
#define TMAG5170_CONFIG_CONTINUOUS 0x00
#define TMAG5170_CONFIG_RANGE_50MT 0x04
#define TMAG5170_CONFIG_ENABLE_ALL_AXES 0x07

struct tmag5170 {
    struct gpiod_chip *chip;
    int fd;
    FILE *csv_file;
};

void tmag5170_init(struct tmag5170 *tmag) {
    tmag->chip = gpiod_chip_open_by_name("gpiochip0");
    if (!tmag->chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    tmag->fd = gpiod_chip_get_i2c_fd(tmag->chip);
    if (tmag->fd < 0) {
        perror("Failed to get I2C file descriptor");
        gpiod_chip_close(tmag->chip);
        exit(EXIT_FAILURE);
    }

    tmag->csv_file = fopen("magnetic_log.csv", "a");
    if (!tmag->csv_file) {
        perror("Failed to open CSV file");
        gpiod_chip_close(tmag->chip);
        exit(EXIT_FAILURE);
    }

    if (fseek(tmag->csv_file, 0, SEEK_END) != 0 || ftell(tmag->csv_file) == 0) {
        fprintf(tmag->csv_file, "Timestamp,X,Y,Z\n");
    }
}

void tmag5170_cleanup(struct tmag5170 *tmag) {
    fclose(tmag->csv_file);
    gpiod_chip_close(tmag->chip);
}

void tmag5170_write_config(struct tmag5170 *tmag) {
    uint8_t config = TMAG5170_CONFIG_CONTINUOUS | TMAG5170_CONFIG_RANGE_50MT | TMAG5170_CONFIG_ENABLE_ALL_AXES;
    if (write(tmag->fd, &config, 1) != 1) {
        perror("Failed to write configuration to TMAG5170");
    }
}

void tmag5170_read_data(struct tmag5170 *tmag, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];
    if (read(tmag->fd, data, 6) != 6) {
        perror("Failed to read data from TMAG5170");
        return;
    }

    *x = (data[1] << 8) | data[0];
    *y = (data[3] << 8) | data[2];
    *z = (data[5] << 8) | data[4];
}

void signal_handler(int signum) {
    struct tmag5170 tmag;
    tmag5170_cleanup(&tmag);
    exit(signum);
}

int main() {
    struct tmag5170 tmag;
    tmag5170_init(&tmag);
    tmag5170_write_config(&tmag);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        int16_t x, y, z;
        tmag5170_read_data(&tmag, &x, &y, &z);

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

        fprintf(tmag.csv_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
        fflush(tmag.csv_file);

        usleep(100000);
    }

    return 0;
}

