#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 23
#define LOG_FILE "flood_log.txt"
#define REINIT_DELAY 60

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static int reinit_timer = 0;

void log_event(const char *message) {
    FILE *log = fopen(LOG_FILE, "a");
    if (log == NULL) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
    fprintf(log, "%s ALERT: %s\n", timestamp, message);
    fclose(log);
}

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        if (line) {
            gpiod_line_release(line);
        }
        if (chip) {
            gpiod_chip_close(chip);
        }
        exit(0);
    }
}

void reinit_sensor() {
    if (reinit_timer > 0) {
        return;
    }
    reinit_timer = 1;
    sleep(REINIT_DELAY);
    reinit_timer = 0;
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        log_event("Failed to open GPIO chip");
        return;
    }
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        log_event("Failed to get GPIO line");
        gpiod_chip_close(chip);
        chip = NULL;
        return;
    }
    if (gpiod_line_request_input(line, "water_level_sensor")) {
        log_event("Failed to request GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        chip = NULL;
        line = NULL;
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        log_event("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        log_event("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line, "water_level_sensor")) {
        log_event("Failed to request GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            log_event("Failed to read GPIO line");
            reinit_sensor();
            continue;
        }
        if (value == 1) {
            log_event("Water detected");
        }
        sleep(2);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

