#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define SENSOR_PIN 4
#define PULL_UP_RESISTOR GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP
#define PULSE_WINDOW 1000000 // 1 second in microseconds
#define LOG_FILE "rpm_log.txt"

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static int pulse_count = 0;
static int running = 1;

void log_rpm(int rpm) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

