#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_A 17
#define GPIO_B 27
#define LOG_FILE "rotation_log.txt"

struct sensor_state {
    int a;
    int b;
    int prev_a;
    int prev_b;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    FILE *log_file;
    int running;
};

static void *sensor_thread(void *arg) {
    struct sensor_state *state = arg;
    struct gpiod_chip *chip;
    struct gpiod_line *line_a, *line_b;
    struct gpiod_line_event event;
    int ret;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return NULL;
    }

    line_a = gpiod_chip_get_line(chip, GPIO_A);
    if (!line_a) {
        perror("Failed to get GPIO line A");
        gpiod_chip_close(chip);
        return NULL;
    }

    line_b = gpiod_chip_get_line(chip, GPIO_B);
    if (!line_b) {
        perror("Failed to get GPIO line B");
        gpiod_line_release(line_a);
        gpiod_chip_close(chip);
        return NULL;
    }

    ret = gpiod_line_request_input(line_a, "sensor_a");
    if (ret < 0) {
        perror("Failed to request input for GPIO line A");
        gpiod_line_release(line_a);
        gpiod_chip_close(chip);
        return NULL;
    }

    ret = gpiod_line_request_input(line_b, "sensor_b");
    if (ret < 0) {
        perror("Failed to request input for GPIO line B");
        gpiod_line_release(line_a);
        gpiod_line_release(line_b);
        gpiod_chip_close(chip);
        return NULL;
    }

    ret = gpiod_line_request_event(line_a, GPIOD_LINE_REQUEST_EVENT_BOTH_EDGES);
    if (ret < 0) {
        perror("Failed to request event for GPIO line A");
        gpiod_line_release(line_a);
        gpiod_line_release(line_b);
        gpiod_chip_close(chip);
        return NULL;
    }

    ret = gpiod_line_request_event(line_b, GPIOD_LINE_REQUEST_EVENT_BOTH_EDGES);
    if (ret < 0) {
        perror("Failed to request event for GPIO line B");
        gpiod_line_release(line_a);
        gpiod_line_release(line_b);
        gpiod_chip_close(chip);
        return NULL;
    }

    while (state->running) {
        ret = gpiod_line_event_wait(line_a, NULL);
        if (ret < 0) {
            perror("Failed to wait for event on GPIO line A");
            continue;
        }

        ret = gpiod_line_event_read(line_a, &event);
        if (ret < 0) {
            perror("Failed to read event from GPIO line A");
            continue;
        }

        ret = gpiod_line_event_wait(line_b, NULL);
        if (ret < 0) {
            perror("Failed to wait for event on GPIO line B");
            continue;
        }

        ret = gpiod_line_event_read(line_b, &event);
        if (ret < 0) {
            perror("Failed to read event from GPIO line B");
            continue;
        }

        pthread_mutex_lock(&state->mutex);
        state->a = gpiod_line_get_value(line_a);
        state->b = gpiod_line_get_value(line_b);
        pthread_mutex_unlock(&state->mutex);

        pthread_cond_signal(&state->cond);
    }

    gpiod_line_release(line_a);
    gpiod_line_release(line_b);
    gpiod_chip_close(chip);
    return NULL;
}

static void signal_handler(int signum) {
    struct sensor_state *state = (struct sensor_state *)pthread_getspecific(sensor_state_key);
    if (state) {
        state->running = 0;
    }
}

int main() {
    struct sensor_state state = {0};
    pthread_t thread;
    struct timespec ts;
    char timestamp[20];
    int ret;

    state.log_file = fopen(LOG_FILE, "a");
    if (!state.log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    ret = pthread_mutex_init(&state.mutex, NULL);
    if (ret != 0) {
        perror("Failed to initialize mutex");
        fclose(state.log_file);
        return EXIT_FAILURE;
    }

    ret = pthread_cond_init(&state.cond, NULL);
    if (ret != 0) {
        perror("Failed to initialize condition variable");
        pthread_mutex_destroy(&state.mutex);
        fclose(state.log_file);
        return EXIT_FAILURE;
    }

    state.running = 1;

    ret = pthread_create(&thread, NULL, sensor_thread, &state);
    if (ret != 0) {
        perror("Failed to create sensor thread");
        pthread_cond_destroy(&state.cond);
        pthread_mutex_destroy(&state.mutex);
        fclose(state.log_file);
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (state.running) {
        pthread_mutex_lock(&state.mutex);
        while (!state.a && !state.b) {
            pthread_cond_wait(&state.cond, &state.mutex);
        }
        pthread_mutex_unlock(&state.mutex);

        pthread_mutex_lock(&state.mutex);
        if (state.a != state.prev_a || state.b != state.prev_b) {
            state.prev_a = state.a;
            state.prev_b = state.b;
            pthread_mutex_unlock(&state.mutex);

            clock_gettime(CLOCK_REALTIME, &ts);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
            fprintf(state.log_file, "%s.%03ld %s\n", timestamp, ts.tv_nsec / 1000000, state.a ? "CW" : "CCW");
            fflush(state.log_file);
        } else {
            pthread_mutex_unlock(&state.mutex);
        }
    }

    pthread_join(thread, NULL);
    pthread_cond_destroy(&state.cond);
    pthread_mutex_destroy(&state.mutex);
    fclose(state.log_file);

    return EXIT_SUCCESS;
}

