#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_SENSOR_LINE 23
#define GPIO_LED_LINE 18
#define POLL_INTERVAL 50

static struct gpiod_chip *chip;
static struct gpiod_line *sensor_line;
static struct gpiod_line *led_line;
static int running = 1;

void log_message(const char *message) {
    syslog(LOG_INFO, "%s", message);
}

void log_error(const char *message) {
    syslog(LOG_ERR, "%s", message);
}

void signal_handler(int signum) {
    running = 0;
}

void cleanup() {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    closelog();
}

int main() {
    struct gpiod_line_request_config sensor_config = {
        .consumer = "touch_sensor",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
    };
    struct gpiod_line_request_config led_config = {
        .consumer = "led",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT,
    };

    openlog("touch_led", LOG_PID | LOG_CONS, LOG_USER);

    log_message("Starting touch_led program");

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        log_error("Failed to open GPIO chip");
        goto cleanup;
    }

    sensor_line = gpiod_chip_get_line(chip, GPIO_SENSOR_LINE);
    if (!sensor_line) {
        log_error("Failed to get sensor line");
        goto cleanup;
    }

    if (gpiod_line_request(sensor_line, &sensor_config)) {
        log_error("Failed to request sensor line");
        goto cleanup;
    }

    led_line = gpiod_chip_get_line(chip, GPIO_LED_LINE);
    if (!led_line) {
        log_error("Failed to get LED line");
        goto cleanup;
    }

    if (gpiod_line_request(led_line, &led_config)) {
        log_error("Failed to request LED line");
        goto cleanup;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        int value = gpiod_line_get_value(sensor_line);
        if (value < 0) {
            log_error("Failed to read sensor line");
            goto cleanup;
        }

        if (value) {
            log_message("Touch detected");
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }

        usleep(POLL_INTERVAL * 1000);
    }

cleanup:
    cleanup();
    log_message("Exiting touch_led program");
    closelog();
    return 0;
}

