        log_error("Failed to request sensor line");
        goto cleanup;
    }

    led_line = gpiod_chip_get_line(chip, GPIO_LED_LINE);
    if (!led_line) {
        log_error("Failed to get LED line");
        goto cleanup;
    }

    if (gpiod_line_request(led_line, &led_config)) {
        log_error("Failed to request LED line");
        goto cleanup;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        int value = gpiod_line_get_value(sensor_line);
        if (value < 0) {
            log_error("Failed to read sensor line");
            goto cleanup;
        }

        if (value) {
            log_message("Touch detected");
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }

        usleep(POLL_INTERVAL * 1000);
    }

cleanup:
    cleanup();
    log_message("Exiting touch_led program");
    closelog();
    return 0;
}
