#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define TOUCH_SENSOR_CHIP "gpiochip0"
#define TOUCH_SENSOR_LINE 17
#define LED_CHIP "gpiochip0"
#define LED_LINE 18
#define DEBOUNCE_TIME 50

static struct gpiod_chip *touch_chip = NULL;
static struct gpiod_chip *led_chip = NULL;
static struct gpiod_line *touch_line = NULL;
static struct gpiod_line *led_line = NULL;

void handle_signal(int signum) {
    if (touch_chip) {
        gpiod_chip_close(touch_chip);
    }
    if (led_chip) {
        gpiod_chip_close(led_chip);
    }
    exit(signum);
}

int main() {
    struct gpiod_line_request_config config;

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open GPIO chips
    touch_chip = gpiod_chip_open_by_name(TOUCH_SENSOR_CHIP);
    if (!touch_chip) {
        fprintf(stderr, "Failed to open GPIO chip for touch sensor\n");
        return EXIT_FAILURE;
    }

    led_chip = gpiod_chip_open_by_name(LED_CHIP);
    if (!led_chip) {
        fprintf(stderr, "Failed to open GPIO chip for LED\n");
        gpiod_chip_close(touch_chip);
        return EXIT_FAILURE;
    }

