    if (!touch_line) {
        fprintf(stderr, "Failed to get touch sensor line\n");
        gpiod_chip_close(touch_chip);
        gpiod_chip_close(led_chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(touch_line, &config)) {
        fprintf(stderr, "Failed to request touch sensor line\n");
        gpiod_line_release(touch_line);
        gpiod_chip_close(touch_chip);
        gpiod_chip_close(led_chip);
        return EXIT_FAILURE;
    }

    // Request LED line
    gpiod_line_request_config_init(&config);
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    config.consumer = "led";
    config.default_val = 0;

    led_line = gpiod_chip_get_line(led_chip, LED_LINE);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line\n");
        gpiod_line_release(touch_line);
        gpiod_chip_close(touch_chip);
        gpiod_chip_close(led_chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(led_line, &config)) {
        fprintf(stderr, "Failed to request LED line\n");
        gpiod_line_release(touch_line);
        gpiod_chip_close(touch_chip);
        gpiod_chip_close(led_chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        int ret = gpiod_line_event_wait(touch_line, 1000);
        if (ret < 0) {
            fprintf(stderr, "Failed to wait for touch sensor event\n");
            break;
        }

        struct gpiod_line_event event;
        ret = gpiod_line_event_read(touch_line, &event);
        if (ret < 0) {
            fprintf(stderr, "Failed to read touch sensor event\n");
            break;
        }

        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            usleep(DEBOUNCE_TIME * 1000);
            int value = gpiod_line_get_value(touch_line);
            if (value < 0) {
                fprintf(stderr, "Failed to read touch sensor value\n");
                break;
            }

            if (value == 1) {
                gpiod_line_set_value(led_line, 1);
            } else {
                gpiod_line_set_value(led_line, 0);
            }
        }
    }

    // Cleanup
    gpiod_line_release(touch_line);
    gpiod_chip_close(touch_chip);
    gpiod_line_release(led_line);
    gpiod_chip_close(led_chip);

    return EXIT_SUCCESS;
}

