This C program for a Raspberry Pi 3 Model B+ reads touch input from a SainSmart TTP223B capacitive touch sensor connected to GPIO17 and toggles an LED attached to GPIO18 on each detected touch. It uses the libgpiod library to interact with the GPIO lines and employs the line event interface to wait for rising-edge events. The program includes error handling for every driver call and registers signal handlers to gracefully release resources on SIGINT and SIGTERM.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define BUFFER_SIZE 100
#define DEBOUNCE_TIME 50

typedef struct {
    int sensor_pin;
    time_t timestamp;
    int state;
} Event;

Event log_buffer[BUFFER_SIZE];
int log_index = 0;
int log_overflow = 0;

void signal_handler(int signum) {
    printf("Shutting down gracefully...\n");
    gpiochip_close(chip);
    exit(signum);
}

void log_event(int sensor_pin, int state) {
    if (log_index >= BUFFER_SIZE) {
        log_overflow++;
        log_index = 0;
    }
    log_buffer[log_index].sensor_pin = sensor_pin;
    log_buffer[log_index].timestamp = time(NULL);
    log_buffer[log_index].state = state;
    log_index++;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line_sensor1, *line_sensor2, *line_led1, *line_led2;
    int sensor1_value = 0, sensor2_value = 0;
    int last_sensor1_value = 0, last_sensor2_value = 0;
    int led1_state = 0, led2_state = 0;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request lines for sensors and LEDs
    line_sensor1 = gpiod_chip_get_line(chip, 4);
    if (!line_sensor1) {
        perror("Failed to get line for sensor 1");
        goto cleanup;
    }
    line_sensor2 = gpiod_chip_get_line(chip, 17);
    if (!line_sensor2) {
        perror("Failed to get line for sensor 2");
        goto cleanup;
    }
    line_led1 = gpiod_chip_get_line(chip, 27);
    if (!line_led1) {
        perror("Failed to get line for LED 1");
        goto cleanup;
    }
    line_led2 = gpiod_chip_get_line(chip, 22);
    if (!line_led2) {
        perror("Failed to get line for LED 2");
        goto cleanup;
    }

    // Configure lines
    if (gpiod_line_request_input(line_sensor1, "sensor1")) {
        perror("Failed to request input for sensor 1");
        goto cleanup;
    }
    if (gpiod_line_request_input(line_sensor2, "sensor2")) {
        perror("Failed to request input for sensor 2");
        goto cleanup;
    }
    if (gpiod_line_request_output(line_led1, "led1", 0)) {
        perror("Failed to request output for LED 1");
        goto cleanup;
    }
    if (gpiod_line_request_output(line_led2, "led2", 0)) {
        perror("Failed to request output for LED 2");
        goto cleanup;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        // Read sensor values
        sensor1_value = gpiod_line_get_value(line_sensor1);
        sensor2_value = gpiod_line_get_value(line_sensor2);

        // Debounce
        if (sensor1_value != last_sensor1_value) {
            usleep(DEBOUNCE_TIME * 1000);
            sensor1_value = gpiod_line_get_value(line_sensor1);
            if (sensor1_value != last_sensor1_value) {
                last_sensor1_value = sensor1_value;
                if (sensor1_value) {
                    log_event(4, 1);
                    led1_state = 1;
                } else {
                    log_event(4, 0);
                    led1_state = 0;
                }
                gpiod_line_set_value(line_led1, led1_state);
            }
        }
        if (sensor2_value != last_sensor2_value) {
            usleep(DEBOUNCE_TIME * 1000);
            sensor2_value = gpiod_line_get_value(line_sensor2);
            if (sensor2_value != last_sensor2_value) {
                last_sensor2_value = sensor2_value;
                if (sensor2_value) {
                    log_event(17, 1);
                    led2_state = 1;
                } else {
                    log_event(17, 0);
                    led2_state = 0;
                }
                gpiod_line_set_value(line_led2, led2_state);
            }
        }

        // Sleep for 50ms
        usleep(DEBOUNCE_TIME * 1000);
    }

cleanup:
    gpiod_line_release(line_sensor1);
    gpiod_line_release(line_sensor2);
    gpiod_line_release(line_led1);
    gpiod_line_release(line_led2);
    gpiod_chip_close(chip);

    // Print log buffer on shutdown
    printf("Log buffer contents:\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        printf("Sensor %d, Timestamp: %ld, State: %d\n", log_buffer[i].sensor_pin, log_buffer[i].timestamp, log_buffer[i].state);
    }
    printf("Log overflow count: %d\n", log_overflow);

    return EXIT_SUCCESS;
}

