        .flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP,
    };

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request the line
    if (gpiod_line_request(line, &config)) {
        perror("Failed to request GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int last_state = -1;
    while (1) {
        int state = gpiod_line_get_value(line);
        if (state == -1) {
            perror("Failed to read GPIO line");
            break;
        }

        if (state != last_state) {
            if (state == 0) {
                log_event("Rain Detected");
            } else {
                log_event("No Rain");
            }
            last_state = state;
        }

        usleep(500 * 1000); // Sleep for 500 ms
    }

    // Cleanup
    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}
