#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE1 17
#define GPIO_LINE2 18
#define DEBOUNCE_TIME 5000000  // 5 ms in nanoseconds
#define SAMPLE_INTERVAL 100000000  // 100 ms in nanoseconds

static struct gpiod_chip *chip;
static struct gpiod_line *line1, *line2;
static FILE *log_file;
static int running = 1;

void cleanup() {
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip) gpiod_chip_close(chip);
    if (log_file) fclose(log_file);
    running = 0;
}

void signal_handler(int sig) {
    cleanup();
    exit(0);
}

int main() {
    struct timespec last_time, current_time, sample_time;
    int sensor1_state = 0, sensor2_state = 0, last_sensor1_state = 0, last_sensor2_state = 0;
    int transitions = 0;

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open log file
    log_file = fopen("shaft_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Request GPIO lines
    line1 = gpiod_chip_get_line(chip, GPIO_LINE1);
    if (!line1) {
        perror("Failed to get GPIO line 1");
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_LINE2);
    if (!line2) {
        perror("Failed to get GPIO line 2");
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Configure GPIO lines
    if (gpiod_line_request_input(line1, "shaft_sensor1")) {
        perror("Failed to request input for GPIO line 1");
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line2, "shaft_sensor2")) {
        perror("Failed to request input for GPIO line 2");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Initialize last time
    if (clock_gettime(CLOCK_MONOTONIC, &last_time) == -1) {
        perror("Failed to get initial time");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    while (running) {
        // Read sensor states
        sensor1_state = gpiod_line_get_value(line1);
        sensor2_state = gpiod_line_get_value(line2);

        // Check for state changes
        if (sensor1_state != last_sensor1_state || sensor2_state != last_sensor2_state) {
            // Apply debounce
            if (clock_gettime(CLOCK_MONOTONIC, &current_time) == -1) {
                perror("Failed to get current time");
                cleanup();
                return EXIT_FAILURE;
            }

            if (current_time.tv_sec - last_time.tv_sec > 0 || 
                (current_time.tv_sec == last_time.tv_sec && current_time.tv_nsec - last_time.tv_nsec > DEBOUNCE_TIME)) {
                // Log transition
                if (clock_gettime(CLOCK_MONOTONIC, &current_time) == -1) {
                    perror("Failed to get current time");
                    cleanup();
                    return EXIT_FAILURE;
                }

                fprintf(log_file, "%ld,%ld,%d,%d\n", current_time.tv_sec, current_time.tv_nsec, sensor1_state, sensor2_state);
                fflush(log_file);

                // Update last state and transition count
                last_sensor1_state = sensor1_state;
                last_sensor2_state = sensor2_state;
                transitions++;
            }
        }

        // Check for sample interval
        if (clock_gettime(CLOCK_MONOTONIC, &current_time) == -1) {
            perror("Failed to get current time");
            cleanup();
            return EXIT_FAILURE;
        }

        if (current_time.tv_sec - sample_time.tv_sec > 0 || 
            (current_time.tv_sec == sample_time.tv_sec && current_time.tv_nsec - sample_time.tv_nsec > SAMPLE_INTERVAL)) {
            // Calculate RPM
            int rpm = (transitions * 60) / 2;  // Each transition represents a full rotation
            printf("RPM: %d\n", rpm);

            // Reset transition count and sample time
            transitions = 0;
            sample_time = current_time;
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

