int si1182_init(struct si1182 *sensor) {
    sensor->chip = gpiod_chip_open_by_name("gpiochip0");
    if (!sensor->chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    sensor->line = gpiod_chip_get_line(sensor->chip, 17); // Assuming SDA is connected to GPIO 17
    if (!sensor->line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(sensor->chip);
        return -1;
    }

    if (gpiod_line_request_output(sensor->line, "si1182", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(sensor->chip);
        return -1;
    }

    return 0;
}

