#define ALARM_PIN 27
#define LOG_FILE "bridge_integrity.log"
#define THRESHOLD_SECONDS 2
#define POLL_INTERVAL_MS 100

static struct gpiod_chip *chip;
static struct gpiod_line *sensor1, *sensor2, *alarm;
static FILE *log_file;
static int alarm_active = 0;

void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file);
}

void activate_alarm() {
    if (!alarm_active) {
        gpiod_line_set_value(alarm, 1);
        alarm_active = 1;
    }
}

void deactivate_alarm() {
    if (alarm_active) {
        gpiod_line_set_value(alarm, 0);
        alarm_active = 0;
    }
}

void cleanup() {
    if (log_file) {
        fclose(log_file);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    deactivate_alarm();
}

void handle_signal(int sig) {
    cleanup();
    exit(0);
}

int main() {
    struct gpiod_line_request_config config = {
        .consumer = "bridge_monitor",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
        .default_val = 0,
        .flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN,
    };

    // Initialize GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request sensor lines
    sensor1 = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (!sensor1) {
        perror("Failed to get sensor1 line");
        cleanup();
        return EXIT_FAILURE;
    }

    sensor2 = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (!sensor2) {
        perror("Failed to get sensor2 line");
        cleanup();
        return EXIT_FAILURE;
    }

    // Request alarm line
    alarm = gpiod_chip_get_line(chip, ALARM_PIN);
    if (!alarm) {
        perror("Failed to get alarm line");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(sensor1, &config) < 0) {
        perror("Failed to request sensor1 line");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(sensor2, &config) < 0) {
        perror("Failed to request sensor2 line");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(alarm, &config) < 0) {
        perror("Failed to request alarm line");
        cleanup();
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int sensor1_prev = 0, sensor2_prev = 0;
    time_t start_time = 0;

    while (1) {
        int sensor1_val = gpiod_line_get_value(sensor1);
        int sensor2_val = gpiod_line_get_value(sensor2);

        if (sensor1_val == 1 && sensor2_val == 1) {
            if (start_time == 0) {
                start_time = time(NULL);
                log_event("Tilt-start");
            }
        } else {
            if (start_time != 0) {
                time_t end_time = time(NULL);
                if (end_time - start_time > THRESHOLD_SECONDS) {
                    log_event("Threshold-exceeded");
                }
                log_event("Tilt-end");
                start_time = 0;
            }
        }

        if (sensor1_val == 1 || sensor2_val == 1) {
            if (start_time == 0) {
                start_time = time(NULL);
            }
        } else {
            if (start_time != 0) {
                time_t end_time = time(NULL);
                if (end_time - start_time > THRESHOLD_SECONDS) {
                    activate_alarm();
                }
                start_time = 0;
            }
        }

        if (sensor1_val != sensor1_prev || sensor2_val != sensor2_prev) {
            sensor1_prev = sensor1_val;
            sensor2_prev = sensor2_val;
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
