#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x0E
#define SDA_PIN 2
#define SCL_PIN 3
#define ALERT_PIN 17
#define THRESHOLD 500
#define RETRY_COUNT 3
#define POLL_INTERVAL 100

struct gpiod_chip *chip;
struct gpiod_line *alert_line;
FILE *log_file;

void log_event(int peak_value) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", tm_info);

    fprintf(log_file, "%s, Peak Value: %d\n", timestamp, peak_value);
    fflush(log_file);
}

void handle_signal(int sig) {
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (alert_line) {
        gpiod_line_release(alert_line);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    struct gpiod_line_request_config config;
    struct i2c_msg msgs[2];
    uint8_t buf[6];
    int ret, i, peak_value;

    // Initialize GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request alert line
    config.consumer = "seismic_alert";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    config.flags = 0;
    config.default_val = 0;
    alert_line = gpiod_chip_get_line(chip, ALERT_PIN);
    if (!alert_line) {
        perror("Failed to get alert line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request(alert_line, &config);
    if (ret < 0) {
        perror("Failed to request alert line");
        gpiod_line_release(alert_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initialize log file
    log_file = fopen("seismic_events.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(alert_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Register signal handler
    signal(SIGINT, handle_signal);

    // Initialize I2C sensor
    msgs[0].addr = I2C_ADDRESS;
    msgs[0].flags = 0;
    msgs[0].len = 1;
    msgs[0].buf = (uint8_t[]){0x01}; // CTRL1 register address
    msgs[1].addr = I2C_ADDRESS;
    msgs[1].flags = I2C_M_RD;
    msgs[1].len = 1;
    msgs[1].buf = buf;

    for (i = 0; i < RETRY_COUNT; i++) {
        ret = i2c_transfer(I2C_BUS, msgs, 2);
        if (ret == 2) {
            buf[0] &= ~(1 << 5); // Clear power-down bit
            msgs[0].len = 2;
            msgs[0].buf = (uint8_t[]){0x01, buf[0]};
            ret = i2c_transfer(I2C_BUS, msgs, 1);
            if (ret == 1) {
                break;
            }
        }
        usleep(100000); // Wait 100ms before retry
    }

    if (i == RETRY_COUNT) {
        fprintf(stderr, "Failed to initialize sensor\n");
        gpiod_line_release(alert_line);
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        for (i = 0; i < RETRY_COUNT; i++) {
            ret = i2c_transfer(I2C_BUS, msgs, 2);
            if (ret == 2) {
                peak_value = (buf[0] << 8) | buf[1];
                if (peak_value > THRESHOLD) {
                    log_event(peak_value);
                    gpiod_line_set_value(alert_line, 1);
                    usleep(100000); // 1 second
                    gpiod_line_set_value(alert_line, 0);
                }
                break;
            }
            usleep(100000); // Wait 100ms before retry
        }

        if (i == RETRY_COUNT) {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        usleep(POLL_INTERVAL * 1000); // Wait 100ms
    }

    return EXIT_SUCCESS;
}

