#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LEDS {4, 17, 27, 22}
#define GPIO_LED 18
#define POLL_INTERVAL 50

static struct gpiod_chip *chip;
static struct gpiod_line *lines[4];
static struct gpiod_line *led_line;

static void cleanup(int signum) {
    for (int i = 0; i < 4; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(signum);
}

int main() {
    struct gpiod_line_request_config config = {
        .consumer = "obstacle-detector",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
    };

    // Register signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request GPIO lines for sensors
    for (int i = 0; i < 4; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_LEDS[i]);
        if (!lines[i]) {
            perror("Failed to get GPIO line");
            cleanup(EXIT_FAILURE);
        }
        if (gpiod_line_request(lines[i], &config)) {
            perror("Failed to request GPIO line");
            cleanup(EXIT_FAILURE);
        }
    }

    // Request GPIO line for LED
    led_line = gpiod_chip_get_line(chip, GPIO_LED);
    if (!led_line) {
        perror("Failed to get GPIO line");
        cleanup(EXIT_FAILURE);
    }
    if (gpiod_line_request(led_line, &config)) {
        perror("Failed to request GPIO line");
        cleanup(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        int values[4];
        for (int i = 0; i < 4; i++) {
            if (gpiod_line_get_value(lines[i], &values[i])) {
                perror("Failed to read GPIO line");
                cleanup(EXIT_FAILURE);
            }
        }

        int any_detected = 0;
        for (int i = 0; i < 4; i++) {
            if (values[i] == 0) {
                any_detected = 1;
                break;
            }
        }

        if (gpiod_line_set_value(led_line, any_detected)) {
            perror("Failed to set GPIO line");
            cleanup(EXIT_FAILURE);
        }

        usleep(POLL_INTERVAL * 1000);
    }

    return EXIT_SUCCESS;
}

