#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <libgpiod.h>

#define NUM_SENSORS 5
#define GPIO_PINS {2, 3, 4, 17, 27}
#define DEBOUNCE_TIME 50
#define LOG_FILE "/var/log/flame_events.log"

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

void log_event(const char *sensor_id, int pin, const char *message) {
    time_t now = time(NULL);
    char *iso_time = ctime(&now);
    iso_time[strlen(iso_time) - 1] = '\0'; // Remove newline

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        return;
    }

    if (flock(fileno(log_file), LOCK_EX) != 0) {
        syslog(LOG_ERR, "Failed to lock log file: %s", strerror(errno));
        fclose(log_file);
        return;
    }

    fprintf(log_file, "%s - Sensor ID: %s (GPIO %d) - %s\n", iso_time, sensor_id, pin, message);
    fflush(log_file);
    flock(fileno(log_file), LOCK_UN);
    fclose(log_file);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[NUM_SENSORS];
    char *sensor_ids[NUM_SENSORS] = {"S1", "S2", "S3", "S4", "S5"};

    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Flame monitor started");

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_PINS[i]);
        if (lines[i] == NULL) {
            syslog(LOG_ERR, "Failed to get line %d: %s", GPIO_PINS[i], strerror(errno));
            gpiod_chip_close(chip);
            closelog();
            return EXIT_FAILURE;
        }

        if (gpiod_line_request_input(lines[i], "flame_monitor") != 0) {
            syslog(LOG_ERR, "Failed to request input on line %d: %s", GPIO_PINS[i], strerror(errno));
            gpiod_chip_close(chip);
            closelog();
            return EXIT_FAILURE;
        }
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!stop_flag) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int value = gpiod_line_get_value(lines[i]);
            if (value == -1) {
                syslog(LOG_ERR, "Failed to read line %d: %s", GPIO_PINS[i], strerror(errno));
                continue;
            }

            if (value == 0) {
                struct timespec start, end;
                clock_gettime(CLOCK_MONOTONIC, &start);

                while (1) {
                    clock_gettime(CLOCK_MONOTONIC, &end);
                    if ((end.tv_sec - start.tv_sec) * 1000 + (end.tv_nsec - start.tv_nsec) / 1000000 >= DEBOUNCE_TIME) {
                        break;
                    }

                    value = gpiod_line_get_value(lines[i]);
                    if (value == -1) {
                        syslog(LOG_ERR, "Failed to read line %d during debounce: %s", GPIO_PINS[i], strerror(errno));
                        break;
                    }
                }

                if (value == 0) {
                    log_event(sensor_ids[i], GPIO_PINS[i], "Flame Detected");
                }
            }
        }

        sleep(1);
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        gpiod_line_release(lines[i]);
    }

    gpiod_chip_close(chip);
    closelog();

    return EXIT_SUCCESS;
}

