#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINES "5,6,13,19,26,12,16,20"
#define POLL_INTERVAL 50

static struct gpiod_chip *chip;
static struct gpiod_line_bulk lines;
static int running = 1;

void handle_sigint(int sig) {
    running = 0;
}

void log_event(int index, int pin, int state) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    printf("%s - Sensor %d (BCM GPIO %d) %s\n", timestamp, index, pin, state ? "Touched" : "Released");
}

int main() {
    struct gpiod_line_request_config config = {
        .consumer = "TTP226",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
    };

    // Initialize GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request lines
    if (gpiod_chip_get_lines(chip, GPIO_LINES, &lines) < 0) {
        perror("Failed to get GPIO lines");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request lines with configuration
    if (gpiod_line_request_bulk(&lines, &config) < 0) {
        perror("Failed to request GPIO lines");
        gpiod_line_release_bulk(&lines);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up signal handler for graceful shutdown
    signal(SIGINT, handle_sigint);

    int old_states[8] = {0};
    while (running) {
        for (int i = 0; i < 8; i++) {
            int state = gpiod_line_get_value(gpiod_line_bulk_get(&lines, i));
            if (state < 0) {
                perror("Failed to read GPIO line");
                gpiod_line_release_bulk(&lines);
                gpiod_chip_close(chip);
                return EXIT_FAILURE;
            }

            if (state != old_states[i]) {
                log_event(i, 5 + i, state);
                old_states[i] = state;
            }
        }

        usleep(POLL_INTERVAL * 1000);
    }

    // Clean up
    gpiod_line_release_bulk(&lines);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

