#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define PWM_PIN 18
#define PWM_FREQ 1000
#define PWM_RANGE 1000

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;
    FILE *log_file = fopen("grow_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    // Initialize libgpiod
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Request GPIO line for PWM
    line = gpiod_chip_get_line(chip, PWM_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line, "grow_light", PWM_RANGE);
    if (ret < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Set up PWM
    gpioSetMode(PWM_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_PIN, PWM_FREQ);
    gpioSetPWMrange(PWM_PIN, PWM_RANGE);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    struct timespec ts;
    while (running) {
        // Read lux from sensor
        uint16_t lux = 0;
        ret = i2cReadReg16(I2C_BUS, I2C_ADDR, 0x04, &lux);
        if (ret < 0) {
            fprintf(stderr, "Failed to read lux from sensor\n");
            lux = 0; // Default to 0 lux if read fails
        }

        // Map lux to PWM duty cycle
        uint16_t duty_cycle = 0;
        if (lux < 100) {
            duty_cycle = PWM_RANGE;
        } else if (lux < 500) {
            duty_cycle = PWM_RANGE * 3 / 4;
        } else if (lux < 1000) {
            duty_cycle = PWM_RANGE / 2;
        } else {
            duty_cycle = PWM_RANGE / 4;
        }

        // Set PWM duty cycle
        gpioSetPWMrange(PWM_PIN, PWM_RANGE);
        gpioSetPWMDutyCycle(PWM_PIN, duty_cycle);

        // Log the reading
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
        fprintf(log_file, "%s, %u, %u, %d\n", timestamp, lux, duty_cycle, ret);
        fflush(log_file);

        // Sleep for 1 second
        ts.tv_sec = 1;
        ts.tv_nsec = 0;
        nanosleep(&ts, NULL);
    }

    // Clean up
    gpioSetPWMDutyCycle(PWM_PIN, 0);
    gpioTerminate();
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(log_file);

    return EXIT_SUCCESS;
}

