#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_INPUT_PINS 2, 3, 4, 5, 6, 7, 8, 9
#define GPIO_OUTPUT_PIN 17
#define DEBOUNCE_TIME 50
#define LOG_FILE "touch_log.txt"

static struct gpiod_chip *chip;
static struct gpiod_line *output_line;
static struct gpiod_line *input_lines[8];
static int input_states[8];
static int led_state = 0;

void log_event(int channel) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char buffer[80];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(stderr, "%s - Channel %d Touched\n", buffer, channel);
}

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        if (led_state) {
            gpiod_line_set_value(output_line, 0);
        }
        for (int i = 0; i < 8; i++) {
            gpiod_line_release(input_lines[i]);
        }
        gpiod_line_release(output_line);
        gpiod_chip_close(chip);
        exit(signum);
    }
}

int main() {
    // Initialize signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Initialize output line
    output_line = gpiod_chip_get_line(chip, GPIO_OUTPUT_PIN);
    if (!output_line) {
