#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define SENSOR_PIN 4
#define ALERT_PIN 17
#define LOG_FILE "fire_events.log"
#define POLL_INTERVAL 500000 // 500 ms in microseconds

struct gpiod_chip *chip;
struct gpiod_line *sensor_line, *alert_line;
FILE *log_file;

void cleanup(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (alert_line) {
        gpiod_line_release(alert_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(signum);
}

int main() {
    struct timespec ts;
    char timestamp[20];
    int sensor_value;

    // Initialize signal handler
    signal(SIGINT, cleanup);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Request sensor line
    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor_line) {
        perror("Failed to get sensor line");
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Request alert line
    alert_line = gpiod_chip_get_line(chip, ALERT_PIN);
    if (!alert_line) {
        perror("Failed to get alert line");
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Configure sensor line as input
    if (gpiod_line_request_input(sensor_line, "flame_sensor")) {
        perror("Failed to request sensor line as input");
        gpiod_line_release(alert_line);
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Configure alert line as output
    if (gpiod_line_request_output(alert_line, "alert_output", 0)) {
        perror("Failed to request alert line as output");
        gpiod_line_release(alert_line);
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    while (1) {
        // Read sensor value
        sensor_value = gpiod_line_get_value(sensor_line);
        if (sensor_value < 0) {
            perror("Failed to read sensor value");
            continue;
        }

        // Get current timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("Failed to get current time");
            continue;
        }
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        // Log sensor reading
        fprintf(log_file, "%s.%06ld: Sensor value: %d\n", timestamp, ts.tv_nsec / 1000, sensor_value);
        fflush(log_file);

        // Check for flame
        if (sensor_value == 0) {
            // Set alert pin HIGH
            if (gpiod_line_set_value(alert_line, 1)) {
                perror("Failed to set alert pin HIGH");
                continue;
            }

            // Log alert event
            fprintf(log_file, "%s.%06ld: Flame detected\n", timestamp, ts.tv_nsec / 1000);
            fflush(log_file);

            // Wait for 1 second
            usleep(1000000);

            // Set alert pin LOW
            if (gpiod_line_set_value(alert_line, 0)) {
                perror("Failed to set alert pin LOW");
                continue;
            }

            // Log alert reset
            fprintf(log_file, "%s.%06ld: Alert reset\n", timestamp, ts.tv_nsec / 1000);
            fflush(log_file);
        }

        // Wait for next poll
        usleep(POLL_INTERVAL);
    }

    // Cleanup on normal termination
    cleanup(0);

    return EXIT_SUCCESS;
}

