#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x60
#define SLF3S_CMD 0x00
#define SLF3S_FLOW_MASK 0xFFFF
#define SLF3S_CRC_POLY 0x07
#define SLF3S_CRC_INIT 0xFF

#define CSV_HEADER "Timestamp,Flow Rate (ml/min),Status\n"

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = SLF3S_CRC_INIT;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SLF3S_CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *sda, *scl;
    int ret;

    // Initialize GPIO lines for I2C
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    sda = gpiod_chip_get_line(chip, 2);
    if (!sda) {
        perror("Failed to get SDA line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    scl = gpiod_chip_get_line(chip, 3);
    if (!scl) {
        perror("Failed to get SCL line");
        gpiod_line_release(sda);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(sda, "i2c_sda", 0);
    if (ret < 0) {
        perror("Failed to request SDA line as output");
        gpiod_line_release(scl);
        gpiod_line_release(sda);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(scl, "i2c_scl", 0);
    if (ret < 0) {
        perror("Failed to request SCL line as output");
        gpiod_line_release(sda);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initialize I2C
    ret = gpiod_line_set_value(sda, 1);
    if (ret < 0) {
        perror("Failed to set SDA line high");
        gpiod_line_release(scl);
        gpiod_line_release(sda);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
