#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <stdbool.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LEFT 17
#define GPIO_MIDDLE 27
#define GPIO_RIGHT 22
#define SAMPLE_INTERVAL 50  // in milliseconds
#define LOG_FILE "path_log.csv"

static struct gpiod_chip *chip;
static struct gpiod_line *left_line, *middle_line, *right_line;
static FILE *log_file;

static void cleanup_and_exit(int sig) {
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (left_line) {
        gpiod_line_release(left_line);
    }
    if (middle_line) {
        gpiod_line_release(middle_line);
    }
    if (right_line) {
        gpiod_line_release(right_line);
    }
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    struct timespec ts;
    struct tm *tm;
    char timestamp[20];
    int left_value, middle_value, right_value;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request GPIO lines
    left_line = gpiod_chip_get_line(chip, GPIO_LEFT);
    if (!left_line) {
        perror("Failed to get left GPIO line");
        goto cleanup;
    }
    middle_line = gpiod_chip_get_line(chip, GPIO_MIDDLE);
    if (!middle_line) {
        perror("Failed to get middle GPIO line");
        goto cleanup;
    }
    right_line = gpiod_chip_get_line(chip, GPIO_RIGHT);
    if (!right_line) {
        perror("Failed to get right GPIO line");
        goto cleanup;
    }

    // Set GPIO lines as input
    if (gpiod_line_request_input(left_line, "left_sensor") < 0) {
        perror("Failed to request left GPIO line as input");
        goto cleanup;
    }
    if (gpiod_line_request_input(middle_line, "middle_sensor") < 0) {
        perror("Failed to request middle GPIO line as input");
        goto cleanup;
    }
    if (gpiod_line_request_input(right_line, "right_sensor") < 0) {
        perror("Failed to request right GPIO line as input");
        goto cleanup;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        goto cleanup;
    }
    fprintf(log_file, "timestamp,left,middle,right\n");

    // Set up signal handler for SIGINT
    signal(SIGINT, cleanup_and_exit);

    while (true) {
        // Read sensor values
        left_value = gpiod_line_get_value(left_line);
        if (left_value < 0) {
            perror("Failed to read left sensor value");
            goto cleanup;
        }
        middle_value = gpiod_line_get_value(middle_line);
        if (middle_value < 0) {
            perror("Failed to read middle sensor value");
            goto cleanup;
        }
        right_value = gpiod_line_get_value(right_line);
        if (right_value < 0) {
            perror("Failed to read right sensor value");
            goto cleanup;
        }

        // Get current timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
            perror("Failed to get current timestamp");
            goto cleanup;
        }
        tm = localtime(&ts.tv_sec);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);

        // Write to log file
        fprintf(log_file, "%s,%d,%d,%d\n", timestamp, left_value, middle_value, right_value);
        fflush(log_file);

        // Sleep for the specified interval
        usleep(SAMPLE_INTERVAL * 1000);
    }

cleanup:
    cleanup_and_exit(0);
    return EXIT_FAILURE;
}

