This C program continuously polls three KY-033 Obstacle Avoidance Sensors connected to a Raspberry Pi 3 Model B+ via the GPIO bus. It samples each sensor every 50 milliseconds and writes each timestamped reading to a CSV file named `path_log.csv`. The program uses the `libgpiod` library for GPIO operations and handles errors appropriately. It also includes a signal handler for `SIGINT` to ensure clean resource release on program termination.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 4
#define EVENT_FILE "flame_events.txt"

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static FILE *event_file;

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, cleaning up...\n", signum);
        if (line) {
            gpiod_line_release(line);
        }
        if (chip) {
            gpiod_chip_close(chip);
        }
        if (event_file) {
            fclose(event_file);
        }
        exit(signum);
    }
}

int main() {
    struct timespec ts;
    char timestamp[20];
    char event_message[100];

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure the line as input with a pull-up resistor
    if (gpiod_line_request_input(line, "flame_sensor") < 0) {
        perror("Failed to request input on GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open the event file for appending
    event_file = fopen(EVENT_FILE, "a");
    if (!event_file) {
        perror("Failed to open event file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Flame sensor monitoring started...\n");

    while (1) {
        // Wait for a falling edge
        if (gpiod_line_event_wait(line, &ts) < 0) {
            perror("Failed to wait for line event");
            break;
        }

        // Read the line event
        struct gpiod_line_event event;
        if (gpiod_line_event_read(line, &event) < 0) {
            perror("Failed to read line event");
            break;
        }

        // Check if it's a falling edge
        if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            // Get the current timestamp
            if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
                perror("Failed to get current time");
                break;
            }

            // Format the timestamp
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

            // Log the event
            printf("%s: Flame detected\n", timestamp);
            snprintf(event_message, sizeof(event_message), "%s: Flame detected\n", timestamp);
            if (fwrite(event_message, 1, strlen(event_message), event_file) != strlen(event_message)) {
                perror("Failed to write to event file");
                break;
            }
            fflush(event_file);
        }
    }

    // Clean up resources
    fclose(event_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

