    if (gpiod_line_request_input(line, "flame_sensor") < 0) {
        perror("Failed to request input on GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open the event file for appending
    event_file = fopen(EVENT_FILE, "a");
    if (!event_file) {
        perror("Failed to open event file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Flame sensor monitoring started...\n");

    while (1) {
        // Wait for a falling edge
        if (gpiod_line_event_wait(line, &ts) < 0) {
            perror("Failed to wait for line event");
            break;
        }

        // Read the line event
        struct gpiod_line_event event;
        if (gpiod_line_event_read(line, &event) < 0) {
            perror("Failed to read line event");
            break;
        }

        // Check if it's a falling edge
        if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            // Get the current timestamp
            if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
                perror("Failed to get current time");
                break;
            }

            // Format the timestamp
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

            // Log the event
            printf("%s: Flame detected\n", timestamp);
            snprintf(event_message, sizeof(event_message), "%s: Flame detected\n", timestamp);
            if (fwrite(event_message, 1, strlen(event_message), event_file) != strlen(event_message)) {
                perror("Failed to write to event file");
                break;
            }
            fflush(event_file);
        }
    }

    // Clean up resources
    fclose(event_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}
