        fclose(log_file);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request(led_line, &config)) {
        perror("Failed to request LED line");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        fclose(log_file);
        exit(EXIT_FAILURE);
    }

    // Request touch line
    touch_line = gpiod_chip_get_line(chip, GPIO_TOUCH);
    if (!touch_line) {
        perror("Failed to get touch line");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        fclose(log_file);
        exit(EXIT_FAILURE);
    }

    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    config.default_val = 0;
    if (gpiod_line_request(touch_line, &config)) {
        perror("Failed to request touch line");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        fclose(log_file);
        exit(EXIT_FAILURE);
    }

    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int led_state = 0;
    while (1) {
        struct gpiod_line_event event;
        int ret = gpiod_line_event_wait(touch_line, 1000000); // 1 second timeout
        if (ret < 0) {
            perror("Failed to wait for line event");
            continue;
        }

        if (ret == 0) {
            // Timeout, no event
            continue;
        }

        ret = gpiod_line_event_read(touch_line, &event);
        if (ret < 0) {
            perror("Failed to read line event");
            continue;
        }

        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            led_state = !led_state;
            gpiod_line_set_value(led_line, led_state);
            log_event(led_state);
        }
    }

    // This point should never be reached
    return 0;
}

