        perror("Failed to request sensor GPIO line as input");
        gpiod_line_release(sensor_line);
        gpiod_chip_close(sensor_chip);
        gpiod_chip_close(buzzer_chip);
        fclose(log_file);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0)) {
