        gpiod_line_release(sensor_line);
        gpiod_chip_close(sensor_chip);
        gpiod_chip_close(buzzer_chip);
        fclose(log_file);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        int sensor_state = gpiod_line_get_value(sensor_line);
        if (sensor_state == 0) { // Flame detected
            log_event("FLAME DETECTED");
            gpiod_line_set_value(buzzer_line, 1);
            usleep(2000000); // 2 seconds
            gpiod_line_set_value(buzzer_line, 0);
        }
        usleep(500000); // 500 milliseconds
    }

    // Clean up
    gpiod_line_release(sensor_line);
    gpiod_chip_close(sensor_chip);
    gpiod_chip_close(buzzer_chip);
    fclose(log_file);

    return 0;
}

