#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_TOUCH 4
#define GPIO_LED 17
#define DEBOUNCE_TIME 200
#define LOG_FILE "touch_log.txt"

static struct gpiod_chip *chip;
static struct gpiod_line *touch_line;
static struct gpiod_line *led_line;
static FILE *log_file;

static void cleanup(int signum) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
    }
    if (log_file) {
        fclose(log_file);
    }
    if (touch_line) {
        gpiod_line_release(touch_line);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(signum ? signum : 0);
}

static void log_timestamp(const char *message) {
    time_t now = time(NULL);
    struct tm *tm_info = gmtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);
    fprintf(log_file, "%s: %s\n", timestamp, message);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    touch_line = gpiod_chip_get_line(chip, GPIO_TOUCH);
    if (!touch_line) {
        fprintf(stderr, "Failed to get touch line\n");
        cleanup(1);
        return 1;
    }

    if (gpiod_line_request_input(touch_line, "touch_sensor")) {
        fprintf(stderr, "Failed to request input for touch line\n");
        cleanup(1);
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, GPIO_LED);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line\n");
        cleanup(1);
        return 1;
    }

    if (gpiod_line_request_output(led_line, "led", 0)) {
        fprintf(stderr, "Failed to request output for LED line\n");
        cleanup(1);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup(1);
        return 1;
    }

    int last_state = 0;
    int current_state;
    unsigned long last_change_time = 0;

    while (1) {
        current_state = gpiod_line_get_value(touch_line);
        if (current_state != last_state) {
            last_change_time = time(NULL);
        }

        if (current_state == 1 && time(NULL) - last_change_time > DEBOUNCE_TIME) {
            if (last_state == 0) {
                gpiod_line_set_value(led_line, !gpiod_line_get_value(led_line));
                log_timestamp("LED toggled");
            }
            last_state = 1;
        } else if (current_state == 0) {
            last_state = 0;
        }

        usleep(10000);
    }

    cleanup(0);
    return 0;
}

