#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PINS {4, 17, 27}
#define POLL_INTERVAL 100  // 100 ms
#define LOG_FILE "magnet_log.txt"

struct sensor {
    struct gpiod_line *line;
    int last_state;
};

void log_state_change(struct sensor *sensor, int new_state) {
    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", tm_info);

    fprintf(log, "%s Sensor %d: %s\n", timestamp, sensor - sensors + 1, new_state ? "Magnet Removed" : "Magnet Present");
    fclose(log);
}

void handle_signal(int signum) {
    for (int i = 0; i < 3; i++) {
        gpiod_line_release(sensors[i].line);
    }
    exit(signum);
}

int main() {
    struct gpiod_chip *chip;
    struct sensor sensors[3];
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Configure GPIO pins
    for (int i = 0; i < 3; i++) {
        sensors[i].line = gpiod_chip_get_line(chip, GPIO_PINS[i]);
        if (!sensors[i].line) {
            perror("Failed to get GPIO line");
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        ret = gpiod_line_request_input(sensors[i].line, "magnet_sensor");
        if (ret < 0) {
            perror("Failed to request input on GPIO line");
            gpiod_line_release(sensors[i].line);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        ret = gpiod_line_set_debounce(sensors[i].line, 100000);  // 100 ms
        if (ret < 0) {
            perror("Failed to set debounce on GPIO line");
            gpiod_line_release(sensors[i].line);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        ret = gpiod_line_request_bias_pull_up(sensors[i].line, "magnet_sensor");
        if (ret < 0) {
            perror("Failed to request pull-up on GPIO line");
            gpiod_line_release(sensors[i].line);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        sensors[i].last_state = gpiod_line_get_value(sensors[i].line);
        if (sensors[i].last_state < 0) {
            perror("Failed to read initial state of GPIO line");
            gpiod_line_release(sensors[i].line);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Main loop
    while (1) {
        for (int i = 0; i < 3; i++) {
            int new_state = gpiod_line_get_value(sensors[i].line);
            if (new_state < 0) {
                fprintf(stderr, "Failed to read state of GPIO line %d\n", GPIO_PINS[i]);
                continue;
            }

            if (new_state != sensors[i].last_state) {
                log_state_change(&sensors[i], new_state);
                sensors[i].last_state = new_state;
            }
        }

        usleep(POLL_INTERVAL * 1000);
    }

    // Clean up
    for (int i = 0; i < 3; i++) {
        gpiod_line_release(sensors[i].line);
    }
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

