void signal_handler(int sig) {
    struct i2c_device *dev = (struct i2c_device *)gpiod_chip_get_user_data(gpiod_chip_get_line(dev->chip, 0)->chip);
    if (dev->log_file) {
        fclose(dev->log_file);
    }
    if (dev->chip) {
        gpiod_chip_close(dev->chip);
    }
    exit(EXIT_FAILURE);
}

