#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_OUT_BASE 17
#define GPIO_OUT_COUNT 8
#define GPIO_IN_BASE 5
#define GPIO_IN_COUNT 8
#define POLL_INTERVAL 10
#define STABILIZATION_DELAY 200

struct gpio_chip *chip;
struct gpiod_line *out_lines[GPIO_OUT_COUNT];
struct gpiod_line *in_lines[GPIO_IN_COUNT];
FILE *log_file;

void log_event(int channel, int counter) {
    time_t now = time(NULL);
    struct tm *tm = gmtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(log_file, "%s, Channel: %d, Counter: %d\n", timestamp, channel, counter);
    fflush(log_file);
}

void handle_signal(int signum) {
    for (int i = 0; i < GPIO_OUT_COUNT; i++) {
        gpiod_line_set_value(out_lines[i], 0);
    }
    gpiod_chip_close(chip);
    if (log_file) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    for (int i = 0; i < GPIO_OUT_COUNT; i++) {
        out_lines[i] = gpiod_chip_get_line(chip, GPIO_OUT_BASE + i);
        if (!out_lines[i]) {
            fprintf(stderr, "Failed to get output line %d: %s\n", GPIO_OUT_BASE + i, strerror(errno));
            gpiod_chip_close(chip);
            return 1;
        }
        if (gpiod_line_request_output(out_lines[i], "touch_counter", 0)) {
            fprintf(stderr, "Failed to request output line %d: %s\n", GPIO_OUT_BASE + i, strerror(errno));
            gpiod_chip_close(chip);
            return 1;
        }
    }

    for (int i = 0; i < GPIO_IN_COUNT; i++) {
        in_lines[i] = gpiod_chip_get_line(chip, GPIO_IN_BASE + i);
        if (!in_lines[i]) {
            fprintf(stderr, "Failed to get input line %d: %s\n", GPIO_IN_BASE + i, strerror(errno));
            for (int j = 0; j < i; j++) {
                gpiod_line_release(out_lines[j]);
            }
            gpiod_chip_close(chip);
            return 1;
        }
        if (gpiod_line_request_input(in_lines[i], "touch_counter")) {
            fprintf(stderr, "Failed to request input line %d: %s\n", GPIO_IN_BASE + i, strerror(errno));
            for (int j = 0; j <= i; j++) {
                gpiod_line_release(out_lines[j]);
            }
            gpiod_chip_close(chip);
            return 1;
        }
    }

    if (log_file = fopen("touch_log.txt", "a")) {
        fprintf(log_file, "Starting touch_counter at %ld\n", time(NULL));
    } else {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
    }

    usleep(STABILIZATION_DELAY * 1000);

    int counter = 0;
    while (1) {
        for (int i = 0; i < GPIO_IN_COUNT; i++) {
            int value = gpiod_line_get_value(in_lines[i]);
            if (value == -1) {
                fprintf(stderr, "Failed to read input line %d: %s\n", GPIO_IN_BASE + i, strerror(errno));
                continue;
            }
            if (value == 1) {
                counter = (counter + 1) % 256;
                for (int j = 0; j < GPIO_OUT_COUNT; j++) {
                    gpiod_line_set_value(out_lines[j], (counter >> j) & 1);
                }
                log_event(i + 1, counter);
                printf("Touch on channel %d | Counter: %d\n", i + 1, counter);
            }
        }
        usleep(POLL_INTERVAL * 1000);
    }

    for (int i = 0; i < GPIO_OUT_COUNT; i++) {
        gpiod_line_release(out_lines[i]);
    }
    for (int i = 0; i < GPIO_IN_COUNT; i++) {
        gpiod_line_release(in_lines[i]);
    }
    gpiod_chip_close(chip);
    if (log_file) {
        fclose(log_file);
    }

    return 0;
}

