#define GPIO_CHIP "gpiochip0"
#define GPIO_LINES 4
#define GPIO_OFFSETS {17, 18, 27, 22}
#define POLL_INTERVAL 100  // 100 ms

struct gpio_line *lines[GPIO_LINES];
FILE *csv_file = NULL;

void handle_signal(int signum) {
    for (int i = 0; i < GPIO_LINES; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (csv_file) {
        fclose(csv_file);
    }
    exit(signum);
}

int main() {
    struct gpiod_chip *chip;
    struct timespec ts;
    char timestamp[20];
    int values[GPIO_LINES];

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request GPIO lines
    for (int i = 0; i < GPIO_LINES; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_OFFSETS[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d\n", GPIO_OFFSETS[i]);
            continue;
        }
        if (gpiod_line_request_input(lines[i], "tracking_sensor")) {
            fprintf(stderr, "Failed to request input for GPIO line %d\n", GPIO_OFFSETS[i]);
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
            continue;
        }
    }

    // Open CSV file
    csv_file = fopen("tracking_log.csv", "a");
    if (!csv_file) {
        fprintf(stderr, "Failed to open CSV file\n");
        for (int i = 0; i < GPIO_LINES; i++) {
            if (lines[i]) {
                gpiod_line_release(lines[i]);
            }
        }
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Write header if file is empty
    if (fseek(csv_file, 0, SEEK_END) == 0 && ftell(csv_file) == 0) {
        fprintf(csv_file, "timestamp,sensor1,sensor2,sensor3,sensor4\n");
    }

    // Main loop
    while (1) {
        for (int i = 0; i < GPIO_LINES; i++) {
            if (gpiod_line_get_value(lines[i], &values[i])) {
                fprintf(stderr, "Failed to read GPIO line %d\n", GPIO_OFFSETS[i]);
                values[i] = -1;  // Indicate error
            }
        }

        // Get current timestamp
        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        // Write to CSV file
        fprintf(csv_file, "%s,%d,%d,%d,%d\n", timestamp, values[0], values[1], values[2], values[3]);
        fflush(csv_file);

        // Sleep for the specified interval
        usleep(POLL_INTERVAL * 1000);
    }

    // Clean up
    for (int i = 0; i < GPIO_LINES; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    fclose(csv_file);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

