#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE1 17
#define GPIO_LINE2 18
#define DEBOUNCE_TIME 50
#define POLL_INTERVAL 100

struct gpiod_chip *chip;
struct gpiod_line *line1, *line2;
FILE *log_file;

void log_event(int sensor, int state) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, Sensor %d tilted\n",
            tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
            tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec, sensor);
    fflush(log_file);
}

void handle_signal(int sig) {
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(sig);
}

int main() {
    int state1 = 1, state2 = 1;
    int last_state1 = 1, last_state2 = 1;
    int debounce_count1 = 0, debounce_count2 = 0;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request the lines
    line1 = gpiod_chip_get_line(chip, GPIO_LINE1);
    if (!line1) {
        fprintf(stderr, "Failed to get line %d\n", GPIO_LINE1);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_LINE2);
    if (!line2) {
        fprintf(stderr, "Failed to get line %d\n", GPIO_LINE2);
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure the lines as inputs with active-low pull-up
    if (gpiod_line_request_input_flags(line1, "tilt_sensor_1", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP)) {
        fprintf(stderr, "Failed to request input for line %d\n", GPIO_LINE1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input_flags(line2, "tilt_sensor_2", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP)) {
        fprintf(stderr, "Failed to request input for line %d\n", GPIO_LINE2);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open the log file
    log_file = fopen("/var/log/tilt_events.log", "a");
