#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define MIC_PIN 4
#define LED_PIN 17
#define SAMPLE_PERIOD_US 125
#define LED_DURATION_MS 100

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *mic_line, *led_line;
    struct timespec start, end;
    int ret;

    // Initialize signal handler
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request GPIO lines
    mic_line = gpiod_chip_get_line(chip, MIC_PIN);
    if (!mic_line) {
        perror("Failed to get microphone line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get LED line");
        gpiod_line_release(mic_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure GPIO lines
    ret = gpiod_line_request_input(mic_line, "mic_input");
    if (ret < 0) {
        perror("Failed to request microphone line as input");
        gpiod_line_release(led_line);
        gpiod_line_release(mic_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(led_line, "led_output", 0);
    if (ret < 0) {
        perror("Failed to request LED line as output");
        gpiod_line_release(mic_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!stop_flag) {
        ret = gpiod_line_get_value(mic_line);
        if (ret < 0) {
            perror("Failed to read microphone line");
            continue;
        }

        if (ret == 1) {
            // Sound peak detected
            clock_gettime(CLOCK_MONOTONIC, &start);
            while (1) {
                ret = gpiod_line_get_value(mic_line);
                if (ret < 0) {
                    perror("Failed to read microphone line");
                    break;
                }

                if (ret == 0) {
                    clock_gettime(CLOCK_MONOTONIC, &end);
                    if ((end.tv_sec - start.tv_sec) * 1000 + (end.tv_nsec - start.tv_nsec) / 1000000 >= LED_DURATION_MS) {
                        break;
                    }
                }
            }

            // Print timestamp
            printf("Sound peak detected at %ld.%03ld ms\n", (long)start.tv_sec, (long)(start.tv_nsec / 1000000));

            // Turn on LED
            ret = gpiod_line_set_value(led_line, 1);
            if (ret < 0) {
                perror("Failed to turn on LED");
            }

            // Turn off LED after duration
            usleep(LED_DURATION_MS * 1000);
            ret = gpiod_line_set_value(led_line, 0);
            if (ret < 0) {
                perror("Failed to turn off LED");
            }
        }

        // Sleep for the sample period
        usleep(SAMPLE_PERIOD_US);
    }

    // Cleanup
    gpiod_line_release(led_line);
    gpiod_line_release(mic_line);
    gpiod_chip_close(chip);

    printf("Program terminated\n");
    return EXIT_SUCCESS;
}

