#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define LEFT_SENSOR_PIN 17
#define CENTER_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN 22
#define GPIO_CHIP "gpiochip0"

static struct gpiod_chip *chip;
static struct gpiod_line *left_sensor, *center_sensor, *right_sensor;
static volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

void cleanup() {
    if (left_sensor) gpiod_line_release(left_sensor);
    if (center_sensor) gpiod_line_release(center_sensor);
    if (right_sensor) gpiod_line_release(right_sensor);
    if (chip) gpiod_chip_close(chip);
}

int main() {
    struct gpiod_line_request_config config = {
        .consumer = "ir_sensor_reader",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
        .flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP,
    };

    // Register signal handlers
    if (signal(SIGINT, handle_sigint) == SIG_ERR) {
        perror("Failed to set SIGINT handler");
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, handle_sigint) == SIG_ERR) {
        perror("Failed to set SIGTERM handler");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request left sensor line
    left_sensor = gpiod_chip_get_line(chip, LEFT_SENSOR_PIN);
    if (!left_sensor) {
        perror("Failed to get left sensor line");
        cleanup();
        return EXIT_FAILURE;
