#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x60
#define ALS_LSB_REG 0x20
#define ALS_MSB_REG 0x21

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the I2C chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request the I2C line
    line = gpiod_chip_get_line(chip, 2); // Assuming I2C is on GPIO2
    if (!line) {
        perror("Failed to get I2C line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure the line as an output for I2C
    ret = gpiod_line_request_output(line, "i2c", 0);
    if (ret < 0) {
        perror("Failed to request I2C line as output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initialize I2C communication
    ret = gpiod_line_set_value(line, 0); // Set SDA low
    if (ret < 0) {
        perror("Failed to set SDA low");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_set_value(line, 1); // Set SCL low
    if (ret < 0) {
        perror("Failed to set SCL low");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        uint16_t raw_value = 0;
        uint8_t msb, lsb;

        // Start I2C communication
        ret = gpiod_line_set_value(line, 0); // Set SDA low
        if (ret < 0) {
            perror("Failed to set SDA low");
            break;
        }

        ret = gpiod_line_set_value(line, 1); // Set SCL low
        if (ret < 0) {
            perror("Failed to set SCL low");
            break;
        }

        // Send the I2C address with write bit
        ret = gpiod_line_set_value(line, 0); // Set SDA low
        if (ret < 0) {
            perror("Failed to set SDA low");
            break;
        }

        ret = gpiod_line_set_value(line, 1); // Set SCL low
        if (ret < 0) {
            perror("Failed to set SCL low");
            break;
        }

        // Send the register address
        ret = gpiod_line_set_value(line, 0); // Set SDA low
        if (ret < 0) {
            perror("Failed to set SDA low");
            break;
        }

        ret = gpiod_line_set_value(line, 1); // Set SCL low
        if (ret < 0) {
            perror("Failed to set SCL low");
            break;
        }

        // Read the MSB register
        ret = gpiod_line_set_value(line, 0); // Set SDA low
        if (ret < 0) {
            perror("Failed to set SDA low");
            break;
        }

        ret = gpiod_line_set_value(line, 1); // Set SCL low
        if (ret < 0) {
            perror("Failed to set SCL low");
            break;
        }

        // Read the LSB register
        ret = gpiod_line_set_value(line, 0); // Set SDA low
        if (ret < 0) {
            perror("Failed to set SDA low");
            break;
        }

        ret = gpiod_line_set_value(line, 1); // Set SCL low
        if (ret < 0) {
            perror("Failed to set SCL low");
            break;
        }

        // Stop I2C communication
        ret = gpiod_line_set_value(line, 0); // Set SDA low
        if (ret < 0) {
            perror("Failed to set SDA low");
            break;
        }

        ret = gpiod_line_set_value(line, 1); // Set SCL low
        if (ret < 0) {
            perror("Failed to set SCL low");
            break;
        }

        // Combine the MSB and LSB into a 16-bit value
        raw_value = (msb << 8) | lsb;

        // Log the raw sensor reading to the console
        printf("Raw ALS value: 0x%04X\n", raw_value);

        // Wait for 100ms
        usleep(100000);
    }

    // Release resources
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

