    for (int i = 0; i < 8; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    struct timespec ts;
    struct tm *tm;
    char buffer[20];

    // Register signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", gpiod_strerror(errno));
        return EXIT_FAILURE;
    }

    // Request GPIO lines
    struct gpiod_line_request_config config = {
        .consumer = "touch_poll",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
    };
    for (int i = 0; i < 8; i++) {
        lines[i] = gpiod_chip_get_line(chip, i);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %d: %s\n", i, gpiod_strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpiod_line_request(lines[i], &config)) {
            fprintf(stderr, "Failed to request line %d: %s\n", i, gpiod_strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
    }

    while (running) {
        for (int i = 0; i < 8; i++) {
            int value = gpiod_line_get_value(lines[i]);
            if (value < 0) {
                fprintf(stderr, "Failed to read line %d: %s\n", i, gpiod_strerror(errno));
                cleanup();
                return EXIT_FAILURE;
            }
            printf("%c%d", i == 0 ? '[' : ' ', value);
        }
        printf("]\n");

        // Get monotonic time
        if (clock_gettime(CLOCK_MONOTONIC, &ts) == -1) {
            fprintf(stderr, "Failed to get monotonic time: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }

        // Format time
        tm = localtime(&ts.tv_sec);
        strftime(buffer, sizeof(buffer), "%T", tm);
        printf("[%.*fs] ", (int)strlen(buffer), ts.tv_sec + ts.tv_nsec / 1e9);

        // Sleep for the specified interval
        usleep(POLL_INTERVAL_MS * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}
