#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define TCS34725_ADDRESS 0x29
#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ENABLE_PON 0x01
#define TCS34725_ENABLE_AEN 0x02
#define TCS34725_ATIME 0x01
#define TCS34725_CDATAL 0x14
#define TCS34725_RDATAL 0x16
#define TCS34725_GDATAL 0x18
#define TCS34725_BDATAL 0x1A
#define TCS34725_CONTROL 0x0F
#define TCS34725_CONTROL_GAIN 0x03
#define LED_PIN "gpiochip0"
#define LED_LINE "17"

static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *led_line = NULL;

void init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void init_gpio() {
    gpio_chip = gpiod_chip_open_by_name(LED_PIN);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    led_line = gpiod_chip_get_line(gpio_chip, LED_LINE);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(led_line, "color_sensor_led", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(gpio_chip);
        exit(EXIT_FAILURE);
    }
}

void init_sensor() {
    uint8_t buf[2];

    // Power on the sensor
    buf[0] = TCS34725_ENABLE;
    buf[1] = TCS34725_ENABLE_PON;
    if (write(i2c_fd, buf, 2) != 2) {
        perror("Failed to power on sensor");
        exit(EXIT_FAILURE);
    }

    // Enable RGBC
    buf[0] = TCS34725_ENABLE;
    buf[1] = TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN;
    if (write(i2c_fd, buf, 2) != 2) {
        perror("Failed to enable RGBC");
        exit(EXIT_FAILURE);
    }

    // Set integration time to 154 ms
    buf[0] = TCS34725_ATIME;
    buf[1] = 0x00; // 154 ms
    if (write(i2c_fd, buf, 2) != 2) {
        perror("Failed to set integration time");
        exit(EXIT_FAILURE);
    }

    // Set gain to 1x
    buf[0] = TCS34725_CONTROL;
    buf[1] = 0x00;
    if (write(i2c_fd, buf, 2) != 2) {
        perror("Failed to set gain");
        exit(EXIT_FAILURE);
    }
}

void read_sensor_data(uint16_t *red, uint16_t *green, uint16_t *blue, uint16_t *clear) {
    uint8_t buf[8];

    if (read(i2c_fd, buf, 8) != 8) {
        perror("Failed to read sensor data");
        init_sensor();
    }

    *red = (buf[1] << 8) | buf[0];
    *green = (buf[3] << 8) | buf[2];
    *blue = (buf[5] << 8) | buf[4];
    *clear = (buf[7] << 8) | buf[6];
}

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        cleanup();
        exit(EXIT_SUCCESS);
    }
}

void cleanup() {
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

int main() {
    uint16_t red, green, blue, clear;
    uint16_t threshold = 200;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_i2c();
    init_gpio();
    init_sensor();

    while (1) {
        read_sensor_data(&red, &green, &blue, &clear);
        printf("Red: %u, Green: %u, Blue: %u, Clear: %u\n", red, green, blue, clear);

        if (red > threshold) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }

        usleep(200000);
    }

    cleanup();
    return 0;
}

