#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <pigpio.h>

#define BH1750_I2C_ADDRESS 0x23
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define BH1750_MS_DELAY 180
#define LED_PIN 18
#define LED_COUNT 10
#define PWM_FREQ 800000
#define PWM_RANGE 255

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    // Initialize libgpiod
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request GPIO line for LED output
    line = gpiod_chip_get_line(chip, LED_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line, "led_output", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up PWM for WS2812B
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(LED_PIN, PWM_FREQ);
    gpioSetPWMrange(LED_PIN, PWM_RANGE);

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!stop_flag) {
        uint16_t lux;
        uint8_t data[2];

        // Initialize I2C communication
        int fd = open("/dev/i2c-1", O_RDWR);
        if (fd < 0) {
            perror("Failed to open I2C bus");
            continue;
        }

        // Select the BH1750 sensor
        if (ioctl(fd, I2C_SLAVE, BH1750_I2C_ADDRESS) < 0) {
            perror("Failed to select I2C device");
            close(fd);
            continue;
        }

        // Send measurement command
        if (write(fd, &BH1750_CONTINUOUS_HIGH_RES_MODE, 1) != 1) {
            perror("Failed to send measurement command");
            close(fd);
            continue;
        }

        // Wait for measurement to complete
        usleep(BH1750_MS_DELAY * 1000);

        // Read the lux value
        if (read(fd, data, 2) != 2) {
            perror("Failed to read lux value");
            close(fd);
            continue;
        }

        // Convert to lux
        lux = (data[0] << 8) | data[1];
        lux /= 1.2;

        // Map lux to logarithmic brightness level
        uint8_t brightness = (lux > 0) ? (uint8_t)(log(lux) * 10) : 0;

        // Set LED brightness
        gpioSetPWMrange(LED_PIN, PWM_RANGE);
        gpioSetPWMfrequency(LED_PIN, PWM_FREQ);
        gpioWrite(LED_PIN, 1);
        gpioDelay(100);
        gpioWrite(LED_PIN, 0);
        gpioDelay(100);
        gpioSetPWMrange(LED_PIN, brightness);
        gpioSetPWMfrequency(LED_PIN, PWM_FREQ);
