    buffer[1] = (data >> 16) & 0xFF;
    buffer[2] = (data >> 8) & 0xFF;
    buffer[3] = data & 0xFF;
    if (gpioWriteSPI(APA102_SPI_CHANNEL, buffer, 4) != 4) {
        perror("gpioWriteSPI");
        exit(EXIT_FAILURE);
    }
}

