        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_output(line, "i2c_scl", 0) < 0) {
        perror("gpiod_line_request_output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Initialize I2C
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("open");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_I2C_ADDRESS) < 0) {
        perror("ioctl");
        close(i2c_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
