        fprintf(stderr, "gpioSetSPIClockDivider: %s\n", gpioGetErrStr(spi_fd));
        gpioTerminate();
        close(i2c_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    while (!stop_flag) {
        // Start measurement
        if (write(i2c_fd, &BH1750_CONTINUOUS_HIGH_RES_MODE, 1) != 1) {
            perror("write");
            stop_flag = 1;
        }

        // Wait for measurement to complete
        usleep(120 * 1000);

        // Read measurement result
        uint8_t result[BH1750_RESULT_SIZE];
        if (read(i2c_fd, result, BH1750_RESULT_SIZE) != BH1750_RESULT_SIZE) {
            perror("read");
            stop_flag = 1;
        }

        // Convert result to lux
        lux = (result[0] << 8) | result[1];
        lux = lux / 1.2;

        // Calculate brightness
        brightness = (uint32_t)(lux * 0xFF / 1000);

        // Construct LED frame
        led_frame = APA102_START_FRAME;
        for (int i = 0; i < 16; i++) {
            led_frame |= (brightness << (i * APA102_LED_FRAME_SIZE));
        }
        led_frame |= APA102_END_FRAME;

        // Write LED frame to SPI
        write_spi(led_frame);
    }

    // Turn off all LEDs
    write_spi(APA102_START_FRAME | APA102_END_FRAME);

    // Clean up
    gpioTerminate();
    close(i2c_fd);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

