This code initializes the I2C and SPI buses, sets up the BH1750 sensor, and continuously reads the ambient light level. It then scales the brightness of an APA102 LED strip proportionally to the measured illumination. The program handles errors, ensures graceful shutdown on SIGINT, and releases all resources on exit.

code:
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>
#include <pigpio.h>

#define I2C_BUS 1
#define BH1750_ADDR1 0x23
#define BH1750_ADDR2 0x5C
#define BH1750_CONT_HRES_MODE 0x10
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define LED_COUNT 16
#define LED_PIN 10
#define LED_CLK_PIN 11
#define FADE_TIME 500
#define LOOP_DELAY 100

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

void init_i2c(int bus, int *i2c_fd) {
    *i2c_fd = i2c_open(bus, 0, 0);
    if (*i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }
}

void init_spi(int *spi_fd) {
    *spi_fd = spi_open(SPI_CHANNEL, SPI_SPEED, 0);
    if (*spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }
}

void close_i2c(int *i2c_fd) {
    if (*i2c_fd >= 0) {
        i2c_close(*i2c_fd);
        *i2c_fd = -1;
    }
}

void close_spi(int *spi_fd) {
    if (*spi_fd >= 0) {
        spi_close(*spi_fd);
        *spi_fd = -1;
    }
}

void write_spi(int spi_fd, uint8_t *data, size_t length) {
    if (spi_write(spi_fd, data, length) < 0) {
        perror("Failed to write to SPI device");
        exit(EXIT_FAILURE);
    }
}

void set_led_brightness(int spi_fd, uint8_t brightness) {
    uint8_t led_data[LED_COUNT * 3];
    for (int i = 0; i < LED_COUNT; i++) {
        led_data[i * 3] = 0x00; // Blue
        led_data[i * 3 + 1] = 0x00; // Green
        led_data[i * 3 + 2] = brightness; // Red
    }
    write_spi(spi_fd, led_data, sizeof(led_data));
}

void fade_brightness(int spi_fd, uint8_t start, uint8_t end, int duration) {
    int steps = duration / 10;
    for (int i = 0; i <= steps; i++) {
        uint8_t brightness = start + (end - start) * i / steps;
        set_led_brightness(spi_fd, brightness);
        usleep(10000);
    }
}

int read_bh1750(int i2c_fd, int addr) {
    if (i2c_write_byte_data(i2c_fd, addr, BH1750_CONT_HRES_MODE) < 0) {
        return -1;
    }
    usleep(180000);
    uint8_t data[2];
    if (i2c_read_i2c_block_data(i2c_fd, addr, data, 2) < 0) {
        return -1;
    }
    return (data[0] << 8) | data[1];
}

int main() {
    signal(SIGINT, sigint_handler);

    int i2c_fd1 = -1, i2c_fd2 = -1;
    int spi_fd = -1;

    init_i2c(I2C_BUS, &i2c_fd1);
    init_i2c(I2C_BUS, &i2c_fd2);
    init_spi(&spi_fd);

    uint8_t avg_light = 0;
    int sensor_count = 0;

    while (running) {
        int light1 = read_bh1750(i2c_fd1, BH1750_ADDR1);
        int light2 = read_bh1750(i2c_fd2, BH1750_ADDR2);

        if (light1 >= 0) {
            avg_light += light1;
            sensor_count++;
        }
        if (light2 >= 0) {
            avg_light += light2;
            sensor_count++;
        }

        if (sensor_count > 0) {
            avg_light /= sensor_count;
        }

        uint8_t target_brightness = (avg_light * 255) / 65535;
        fade_brightness(spi_fd, 0, target_brightness, FADE_TIME);

        usleep(LOOP_DELAY * 1000);
    }

    fade_brightness(spi_fd, 0, 0, FADE_TIME);
    set_led_brightness(spi_fd, 0);

    close_i2c(&i2c_fd1);
    close_i2c(&i2c_fd2);
    close_spi(&spi_fd);

    pigpio_stop();

    return 0;
}

