#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <gpiod.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x29
#define LED_PIN 18
#define LED_COUNT 1
#define GAMMA_TABLE_SIZE 256
#define RETRY_COUNT 3
#define RETRY_DELAY 100000
#define LOOP_DELAY 200000

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static int i2c_fd;

static void gamma_correct(int lux, int *brightness) {
    static int gamma_table[GAMMA_TABLE_SIZE];
    static int initialized = 0;

    if (!initialized) {
        for (int i = 0; i < GAMMA_TABLE_SIZE; i++) {
            gamma_table[i] = (int)(pow(i / 255.0, 2.2) * 255);
        }
        initialized = 1;
    }

    *brightness = gamma_table[lux];
}

static void bitbang_ws2812(int brightness) {
    for (int i = 0; i < LED_COUNT; i++) {
        for (int j = 7; j >= 0; j--) {
            int bit = (brightness >> j) & 1;
            gpiod_line_set_value(line, bit);
            usleep(100); // 125ns high, 375ns low for 0, 375ns high, 125ns low for 1
            gpiod_line_set_value(line, 0);
            usleep(100);
        }
    }
}

static int read_lux() {
    uint8_t buffer[2];
    int retries = RETRY_COUNT;

    while (retries--) {
        if (read(i2c_fd, buffer, 2) == 2) {
            return (buffer[0] << 8) | buffer[1];
        }
        usleep(RETRY_DELAY);
    }

    return -1;
}

static void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        if (line) {
            gpiod_line_set_value(line, 0);
            gpiod_line_release(line);
        }
        if (chip) {
            gpiod_chip_close(chip);
        }
        if (i2c_fd >= 0) {
            close(i2c_fd);
        }
        exit(signum == SIGINT ? 0 : 1);
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if ((i2c_fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    line = gpiod_chip_get_line(chip, LED_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    if (gpiod_line_request_output(line, "ws2812")) {
        perror("Failed to request GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    while (1) {
        int lux = read_lux();
        if (lux < 0) {
            fprintf(stderr, "Failed to read lux value\n");
        } else {
            int brightness;
            gamma_correct(lux, &brightness);
            bitbang_ws2812(brightness);
            printf("Lux: %d, Brightness: %d\n", lux, brightness);
        }
        usleep(LOOP_DELAY);
    }

    return 0;
}

