#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define FLAME_SENSOR_LINE "gpiochip0:0"
#define BUZZER_LINE "gpiochip0:17"
#define LED_LINE "gpiochip0:18"

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18

#define SELF_TEST_ITERATIONS 5
#define SELF_TEST_INTERVAL 100000
#define SELF_TEST_BLINK_INTERVAL 500000
#define ERROR_BLINK_INTERVAL 100000
#define BUZZER_PATTERN {200000, 200000, 600000, 200000}
#define BUZZER_PATTERN_LENGTH 4
#define BUZZER_PATTERN_REPEAT 3

#define LOG_FILE "flame_sensor.log"

struct gpio_chip *chip;
struct gpio_line *flame_sensor_line;
struct gpio_line *buzzer_line;
struct gpio_line *led_line;

void log_event(const char *event) {
    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    fprintf(log, "%s: %s\n", ctime(&now), event);
    fclose(log);
}

void signal_handler(int sig) {
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

void blink_led(int interval, int count) {
    for (int i = 0; i < count; i++) {
        gpiod_line_set_value(led_line, 1);
        usleep(interval);
        gpiod_line_set_value(led_line, 0);
        usleep(interval);
    }
}

void buzzer_pattern(int *pattern, int length, int repeat) {
    for (int i = 0; i < repeat; i++) {
        for (int j = 0; j < length; j++) {
            gpiod_line_set_value(buzzer_line, 1);
            usleep(pattern[j]);
            gpiod_line_set_value(buzzer_line, 0);
            usleep(pattern[j]);
        }
    }
}

int main() {
    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    flame_sensor_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!flame_sensor_line) {
        perror("Failed to get flame sensor line");
        gpiod_chip_close(chip);
        return 1;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        perror("Failed to get buzzer line");
        gpiod_line_release(flame_sensor_line);
        gpiod_chip_close(chip);
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get LED line");
        gpiod_line_release(buzzer_line);
        gpiod_line_release(flame_sensor_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(flame_sensor_line, "flame_sensor", 0) < 0) {
        perror("Failed to request flame sensor line");
        gpiod_line_release(led_line);
        gpiod_line_release(buzzer_line);
        gpiod_line_release(flame_sensor_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        perror("Failed to request buzzer line");
        gpiod_line_release(flame_sensor_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        perror("Failed to request LED line");
        gpiod_line_release(buzzer_line);
        gpiod_line_release(flame_sensor_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Self-test
    blink_led(SELF_TEST_BLINK_INTERVAL, 2);
    int flame_detected = 1;
    for (int i = 0; i < SELF_TEST_ITERATIONS; i++) {
        usleep(SELF_TEST_INTERVAL);
        int value = gpiod_line_get_value(flame_sensor_line);
        if (value == 1) {
            flame_detected = 0;
            break;
        }
    }
    if (!flame_detected) {
        blink_led(ERROR_BLINK_INTERVAL, 5);
        buzzer_pattern(BUZZER_PATTERN, BUZZER_PATTERN_LENGTH, BUZZER_PATTERN_REPEAT);
        gpiod_line_release(led_line);
        gpiod_line_release(buzzer_line);
        gpiod_line_release(flame_sensor_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        int value = gpiod_line_get_value(flame_sensor_line);
        if (value == 0) {
            log_event("Flame detected");
            gpiod_line_set_value(buzzer_line, 1);
            gpiod_line_set_value(led_line, 1);
            while (gpiod_line_get_value(flame_sensor_line) == 0) {
                usleep(50000);
            }
            log_event("Flame cleared");
            gpiod_line_set_value(buzzer_line, 0);
            gpiod_line_set_value(led_line, 0);
        }
        usleep(50000);
    }

    gpiod_line_release(led_line);
    gpiod_line_release(buzzer_line);
    gpiod_line_release(flame_sensor_line);
    gpiod_chip_close(chip);

    return 0;
}

