#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_DEVICE "/dev/i2c-1"
#define BH1750_ADDRESS 0x23
#define BUFFER_SIZE 60
#define LED_PIN "17"
#define LED_CONSUMER "light_sensor_led"

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int read_bh1750(int fd) {
    uint8_t data[2];
    if (read(fd, data, sizeof(data)) != sizeof(data)) {
        perror("Failed to read from BH1750");
        return -1;
    }
    return (data[0] << 8) | data[1];
}

void blink_led(struct gpiod_chip *chip, int lux) {
    int frequency = 0.5 + (lux - 0) * (5 - 0.5) / 1000;
    if (frequency <= 0) frequency = 0.5;
    if (frequency > 5) frequency = 5;

    struct gpiod_line *line = gpiod_chip_get_line(chip, 17);
    if (!line) {
        perror("Failed to get GPIO line");
        return;
    }

    if (gpiod_line_request_output(line, LED_CONSUMER, 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(line);
        return;
    }

    while (running) {
        gpiod_line_set_value(line, 1);
        usleep((int)(1000000 / (2 * frequency)));
        gpiod_line_set_value(line, 0);
        usleep((int)(1000000 / (2 * frequency)));
    }

    gpiod_line_release(line);
}

int main() {
    int i2c_fd;
    struct gpiod_chip *chip;
    uint16_t buffer[BUFFER_SIZE];
    int head = 0, tail = 0;
    int sum = 0;

    if ((i2c_fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if ((chip = gpiod_chip_open_by_name("gpiochip0")) == NULL) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    while (running) {
        int lux = read_bh1750(i2c_fd);
        if (lux >= 0) {
            buffer[head] = lux;
            sum += lux;
            head = (head + 1) % BUFFER_SIZE;
            if (head == tail) {
                tail = (tail + 1) % BUFFER_SIZE;
                sum -= buffer[tail];
            }
        }

        int average = sum / (head - tail + BUFFER_SIZE) % BUFFER_SIZE;
        blink_led(chip, average);

        sleep(1);
    }

    gpiod_chip_close(chip);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

