    if ((chip = gpiod_chip_open_by_name("gpiochip0")) == NULL) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    while (running) {
        int lux = read_bh1750(i2c_fd);
        if (lux >= 0) {
            buffer[head] = lux;
            sum += lux;
            head = (head + 1) % BUFFER_SIZE;
            if (head == tail) {
                tail = (tail + 1) % BUFFER_SIZE;
                sum -= buffer[tail];
            }
        }

        int average = sum / (head - tail + BUFFER_SIZE) % BUFFER_SIZE;
        blink_led(chip, average);

        sleep(1);
    }

    gpiod_chip_close(chip);
    close(i2c_fd);

    return EXIT_SUCCESS;
}
