#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <libgpiod.h>

#define LED_LINE "17"
#define BUTTON_LINE "18"
#define GPIO_CHIP "gpiochip0"
#define BLINK_PERIOD 2000000 // 2 seconds in microseconds
#define BLINK_ON_TIME 1000000 // 1 second in microseconds
#define BLINK_OFF_TIME 1000000 // 1 second in microseconds

static struct gpiod_chip *chip;
static struct gpiod_line *led_line;
static struct gpiod_line *button_line;
static int running = 1;

void handle_sigint(int sig) {
    running = 0;
}

void blink_led() {
    while (running) {
        gpiod_line_set_value(led_line, 1);
        gpiod_line_event_wait(button_line, BLINK_ON_TIME);
        gpiod_line_set_value(led_line, 0);
        gpiod_line_event_wait(button_line, BLINK_OFF_TIME);
    }
}

int main() {
    struct gpiod_line_request_config led_req_config = {
        .consumer = "blink_led",
        .request_type = GPIOD_LINE_REQUEST_OUTPUT,
        .default_val = 0,
    };

    struct gpiod_line_request_config button_req_config = {
        .consumer = "button_event",
        .request_type = GPIOD_LINE_REQUEST_INPUT,
        .default_val = 1,
        .flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP,
    };

    struct gpiod_line_event event;

    // Register signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    // Open GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request LED line
    led_line = gpiod_chip_get_line(chip, atoi(LED_LINE));
    if (!led_line) {
        perror("Failed to get LED line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(led_line, &led_req_config)) {
        perror("Failed to request LED line");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request button line
    button_line = gpiod_chip_get_line(chip, atoi(BUTTON_LINE));
    if (!button_line) {
        perror("Failed to get button line");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(button_line, &button_req_config)) {
        perror("Failed to request button line");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Start blinking LED
    blink_led();

    // Wait for button event
    while (running) {
        if (gpiod_line_event_wait(button_line, -1)) {
            if (gpiod_line_event_read(button_line, &event)) {
                if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
                    printf("Button pressed!\n");
                    running = 0;
                }
            }
        }
    }

    // Turn LED off
    gpiod_line_set_value(led_line, 0);

    // Release resources
    gpiod_line_release(led_line);
    gpiod_line_release(button_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

