#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <libgpiod.h>

#define LED_LINE "24"
#define BUTTON_LINE "22"
#define GPIO_CHIP "gpiochip0"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;
static struct gpiod_line *button_line = NULL;

void cleanup(int signum) {
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (button_line) {
        gpiod_line_release(button_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(signum);
}

int main() {
    int ret;

    // Register signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", gpiod_strerror(errno));
        return EXIT_FAILURE;
    }

    // Get LED line
    led_line = gpiod_chip_get_line(chip, LED_LINE);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line: %s\n", gpiod_strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request LED line as output
    ret = gpiod_line_request_output(led_line, "led_output", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request LED line as output: %s\n", gpiod_strerror(errno));
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Get button line
    button_line = gpiod_chip_get_line(chip, BUTTON_LINE);
    if (!button_line) {
        fprintf(stderr, "Failed to get button line: %s\n", gpiod_strerror(errno));
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request button line as input with pull-down
    ret = gpiod_line_request_input(led_line, "button_input", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN);
    if (ret < 0) {
        fprintf(stderr, "Failed to request button line as input: %s\n", gpiod_strerror(errno));
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        int button_state = gpiod_line_get_value(button_line);
        if (button_state < 0) {
            fprintf(stderr, "Failed to read button state: %s\n", gpiod_strerror(errno));
            continue;
        }

        if (button_state == 0) {
            // Button is pressed
            while (1) {
                ret = gpiod_line_set_value(led_line, 1);
                if (ret < 0) {
                    fprintf(stderr, "Failed to turn LED on: %s\n", gpiod_strerror(errno));
                }
                usleep(500 * 1000);

                ret = gpiod_line_set_value(led_line, 0);
                if (ret < 0) {
                    fprintf(stderr, "Failed to turn LED off: %s\n", gpiod_strerror(errno));
                }
                usleep(500 * 1000);

                button_state = gpiod_line_get_value(button_line);
                if (button_state < 0) {
                    fprintf(stderr, "Failed to read button state: %s\n", gpiod_strerror(errno));
                    break;
                }

                if (button_state == 1) {
                    // Button is released
                    break;
                }
            }
        }
    }

    // Cleanup
    cleanup(0);

    return EXIT_SUCCESS;
}
