#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_RED 24
#define GPIO_GREEN 23
#define GPIO_BLUE 18
#define PWM_PERIOD_NS 10000000  // 10 ms period
#define PWM_DUTY_NS 100000      // 100 us duty cycle
#define PWM_CHANGE_INTERVAL_NS 100000000  // 100 ms

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *red_line, *green_line, *blue_line;
    struct timespec start, now, elapsed;
    int red_duty, green_duty, blue_duty;
    int red_intensity, green_intensity, blue_intensity;
    int ret;

    // Initialize GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request GPIO lines
    red_line = gpiod_chip_get_line(chip, GPIO_RED);
    if (!red_line) {
        perror("Failed to get GPIO line for red");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    green_line = gpiod_chip_get_line(chip, GPIO_GREEN);
    if (!green_line) {
        perror("Failed to get GPIO line for green");
        gpiod_line_release(red_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    blue_line = gpiod_chip_get_line(chip, GPIO_BLUE);
    if (!blue_line) {
        perror("Failed to get GPIO line for blue");
        gpiod_line_release(green_line);
        gpiod_line_release(red_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set GPIO lines as output
    ret = gpiod_line_request_output(red_line, "rgb_led_red", 0);
    if (ret < 0) {
        perror("Failed to request output for red line");
        gpiod_line_release(blue_line);
        gpiod_line_release(green_line);
        gpiod_line_release(red_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(green_line, "rgb_led_green", 0);
    if (ret < 0) {
        perror("Failed to request output for green line");
        gpiod_line_release(blue_line);
        gpiod_line_release(green_line);
        gpiod_line_release(red_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(blue_line, "rgb_led_blue", 0);
    if (ret < 0) {
        perror("Failed to request output for blue line");
        gpiod_line_release(blue_line);
        gpiod_line_release(green_line);
        gpiod_line_release(red_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Seed random number generator
    srand(time(NULL));

    // Set up signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        // Generate random intensities
        red_intensity = rand() % 101;
        green_intensity = rand() % 101;
        blue_intensity = rand() % 101;

        // Calculate duty cycles
        red_duty = (red_intensity * PWM_DUTY_NS) / 100;
        green_duty = (green_intensity * PWM_DUTY_NS) / 100;
        blue_duty = (blue_intensity * PWM_DUTY_NS) / 100;

        // Set red line
        ret = gpiod_line_set_value(red_line, red_duty > 0);
        if (ret < 0) {
            perror("Failed to set red line value");
            break;
        }

        // Set green line
        ret = gpiod_line_set_value(green_line, green_duty > 0);
        if (ret < 0) {
            perror("Failed to set green line value");
            break;
        }

        // Set blue line
        ret = gpiod_line_set_value(blue_line, blue_duty > 0);
        if (ret < 0) {
            perror("Failed to set blue line value");
            break;
        }

        // Wait for the next PWM period
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (1) {
            clock_gettime(CLOCK_MONOTONIC, &now);
            elapsed.tv_sec = now.tv_sec - start.tv_sec;
            elapsed.tv_nsec = now.tv_nsec - start.tv_nsec;
            if (elapsed.tv_sec > 0 || elapsed.tv_nsec >= PWM_PERIOD_NS) {
                break;
            }
        }
    }

    // Clean up
    gpiod_line_release(blue_line);
    gpiod_line_release(green_line);
    gpiod_line_release(red_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

