#define GPIO_PIN 17
#define GPIO_CHIP "gpiochip0"
#define I2C_DEVICE "/dev/i2c-1"
#define LOG_FILE "impact_log.txt"
#define DEFAULT_THRESHOLD 2.0
#define SAMPLE_RATE 10
#define SAMPLE_INTERVAL (1000 / SAMPLE_RATE)

static int i2c_fd;
static struct gpiod_chip *gpio_chip;
static struct gpiod_line *gpio_line;
static FILE *log_file;

static void cleanup() {
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

static void handle_sigint(int signum) {
    cleanup();
    exit(0);
}

static int read_accelerometer(float *x, float *y, float *z) {
    uint8_t buffer[6];
    if (read(i2c_fd, buffer, sizeof(buffer)) != sizeof(buffer)) {
        perror("Failed to read accelerometer data");
        return -1;
    }
    *x = (int16_t)((buffer[1] << 8) | buffer[0]) / 1000.0;
    *y = (int16_t)((buffer[3] << 8) | buffer[2]) / 1000.0;
    *z = (int16_t)((buffer[5] << 8) | buffer[4]) / 1000.0;
    return 0;
}

static void log_impact(float x, float y, float z) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d: X=%.2f, Y=%.2f, Z=%.2f\n",
            tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
            tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec,
            x, y, z);
    fflush(log_file);
}

int main(int argc, char *argv[]) {
    float threshold = DEFAULT_THRESHOLD;
    int opt;
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    if ((i2c_fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LSM303DLHC_I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return 1;
    }

    if ((gpio_chip = gpiod_chip_open(GPIO_CHIP)) == NULL) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    if ((gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN)) == NULL) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    if (gpiod_line_request_output(gpio_line, "impact_interrupt", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        perror("Failed to open log file");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    while (1) {
        float x, y, z;
        if (read_accelerometer(&x, &y, &z) < 0) {
            continue;
        }
        float magnitude = sqrt(x * x + y * y + z * z);
        if (magnitude > threshold) {
            gpiod_line_set_value(gpio_line, 1);
            usleep(50000);
            gpiod_line_set_value(gpio_line, 0);
            log_impact(x, y, z);
        }
        usleep(SAMPLE_INTERVAL * 1000);
    }

    cleanup();
    return 0;
}

