#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <gpiod.h>
#include <time.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x50
#define ALS_LSB_REG 0x00
#define ALS_MSB_REG 0x01
#define RED_REG 0x02
#define GREEN_REG 0x03
#define BLUE_REG 0x04
#define LED_PIN 18
#define PWM_FREQ 1000
#define PWM_RANGE 255
#define SAMPLE_INTERVAL 500
#define RETRY_DELAY 100

static struct gpiod_chip *chip;
static struct gpiod_line *led_line;
static FILE *csv_file;

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        if (csv_file) {
            fclose(csv_file);
        }
        if (led_line) {
            gpiod_line_set_value(led_line, 0);
        }
        if (chip) {
            gpiod_chip_close(chip);
        }
        exit(signum);
    }
}

int read_sensor_data(uint16_t *als, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t data[5];
    int ret;

    ret = gpiod_chip_i2c_read(chip, I2C_ADDR, data, sizeof(data));
    if (ret < 0) {
        fprintf(stderr, "Failed to read from sensor: %s\n", strerror(errno));
        return -1;
    }

    *als = (data[1] << 8) | data[0];
    *red = data[2];
    *green = data[3];
    *blue = data[4];

    return 0;
}

int main() {
    struct timespec ts;
    uint16_t als, red, green, blue;
    int ret;

    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open I2C chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Initialize LED
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(led_line, "led", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request LED line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initialize PWM
    ret = gpiod_line_request_output(led_line, "pwm", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request PWM line: %s\n", strerror(errno));
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initialize CSV file
    csv_file = fopen("color_log.csv", "w");
    if (!csv_file) {
        fprintf(stderr, "Failed to open CSV file: %s\n", strerror(errno));
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    fprintf(csv_file, "Timestamp,ALS,Red,Green,Blue\n");

    while (1) {
        // Read sensor data
        ret = read_sensor_data(&als, &red, &green, &blue);
        if (ret < 0) {
            usleep(RETRY_DELAY * 1000);
            continue;
        }

        // Get current timestamp
        clock_gettime(CLOCK_REALTIME, &ts);

        // Log data to CSV
        fprintf(csv_file, "%ld.%09ld,%u,%u,%u,%u\n", ts.tv_sec, ts.tv_nsec, als, red, green, blue);
        fflush(csv_file);

        // Update LED brightness
        uint8_t brightness = (als * PWM_RANGE) / 65535;
        gpiod_line_set_value(led_line, brightness);

        // Sleep for the specified interval
        usleep(SAMPLE_INTERVAL * 1000);
    }

    // Clean up
    fclose(csv_file);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

