This C program for a Raspberry Pi Zero W reads ambient light and color data from an Analog Devices ADPD188BI optical sensor on I2C bus 1, samples the sensor every 500 ms, combines the ALS LSB and MSB into a 16-bit unsigned value, and logs each timestamped reading of ALS, red, green, and blue channels to a CSV file named `color_log.csv` with a header row. The program also controls an LED connected to GPIO18 (BCM) using hardware PWM so that brighter ambient light increases the LED brightness. It handles any I2C errors such as failed writes, reads, or a missing sensor by writing an error message to stderr and retrying after a 100 ms delay. The program implements signal handling for `SIGINT` and `SIGTERM` to perform a graceful shutdown that closes the I2C handle, turns off the LED, and closes the CSV file.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define FXOS8700CQ_I2C_ADDR 0x1E
#define FXOS8700CQ_WHO_AM_I 0x0D
#define FXOS8700CQ_CTRL_REG1 0x2A
#define FXOS8700CQ_CTRL_REG2 0x2B
#define FXOS8700CQ_M_CTRL_REG1 0x5B
#define FXOS8700CQ_OUT_X_MSB 0x31
#define FXOS8700CQ_OUT_X_LSB 0x32
#define FXOS8700CQ_OUT_Y_MSB 0x33
#define FXOS8700CQ_OUT_Y_LSB 0x34
#define FXOS8700CQ_OUT_Z_MSB 0x35
#define FXOS8700CQ_OUT_Z_LSB 0x36
#define FXOS8700CQ_MAG_DATA_READY 0x01
#define FXOS8700CQ_ACCEL_DATA_READY 0x02
#define FXOS8700CQ_MAG_RANGE_1_3 0x00
#define FXOS8700CQ_MAG_RANGE_2_9 0x01
#define FXOS8700CQ_MAG_RANGE_4_5 0x02
#define FXOS8700CQ_MAG_RANGE_9_0 0x03
#define FXOS8700CQ_ACCEL_RANGE_2 0x00
#define FXOS8700CQ_ACCEL_RANGE_4 0x01
#define FXOS8700CQ_ACCEL_RANGE_8 0x02
#define FXOS8700CQ_ACCEL_RANGE_16 0x03
#define FXOS8700CQ_ODR_200 0x0F
#define IMPACT_THRESHOLD 2.0

static struct gpiod_chip *chip;
static int i2c_fd;

void handle_sigint(int sig) {
    gpiod_chip_close(chip);
    close(i2c_fd);
    exit(0);
}

int read_i2c(int addr, uint8_t reg, uint8_t *data, size_t len) {
    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write error\n");
        return -1;
    }
    if (read(i2c_fd, data, len) != len) {
        fprintf(stderr, "I2C read error\n");
        return -1;
    }
    return 0;
}

int write_i2c(int addr, uint8_t reg, uint8_t *data, size_t len) {
    uint8_t buffer[len + 1];
    buffer[0] = reg;
    memcpy(buffer + 1, data, len);
    if (write(i2c_fd, buffer, len + 1) != len + 1) {
        fprintf(stderr, "I2C write error\n");
        return -1;
    }
    return 0;
}

int main() {
    struct timespec ts;
    struct tm tm;
    char timestamp[20];
    uint8_t whoami, data[6];
    int16_t x, y, z;
    float magnitude;

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, FXOS8700CQ_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Register signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    // Verify WHO_AM_I
    if (read_i2c(FXOS8700CQ_I2C_ADDR, FXOS8700CQ_WHO_AM_I, &whoami, 1) < 0) {
        close(i2c_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (whoami != 0xC7) {
        fprintf(stderr, "WHO_AM_I mismatch: 0x%02X\n", whoami);
        close(i2c_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Place device in standby
    if (write_i2c(FXOS8700CQ_I2C_ADDR, FXOS8700CQ_CTRL_REG1, (uint8_t[]){0x00}, 1) < 0) {
        close(i2c_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure sensor for ±2g range and 200Hz ODR
    if (write_i2c(FXOS8700CQ_I2C_ADDR, FXOS8700CQ_CTRL_REG1, (uint8_t[]){0x0F}, 1) < 0) {
        close(i2c_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Activate device
    if (write_i2c(FXOS8700CQ_I2C_ADDR, FXOS8700CQ_CTRL_REG1, (uint8_t[]){0x0F}, 1) < 0) {
        close(i2c_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        // Read acceleration data
        if (read_i2c(FXOS8700CQ_I2C_ADDR, FXOS8700CQ_OUT_X_MSB, data, 6) < 0) {
            continue;
        }
        x = (data[0] << 8) | data[1];
        y = (data[2] << 8) | data[3];
        z = (data[4] << 8) | data[5];

        // Calculate magnitude
        magnitude = sqrt(x * x + y * y + z * z) / 32768.0 * 2.0;

        // Check for impact
        if (magnitude > IMPACT_THRESHOLD) {
            // Get current timestamp
            if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
                perror("Failed to get current time");
                continue;
            }
            localtime_r(&ts.tv_sec, &tm);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

            // Append to impact_log.txt
            FILE *log_file = fopen("impact_log.txt", "a");
            if (log_file) {
                fprintf(log_file, "%s,%d,%d,%d,%.3f\n", timestamp, x, y, z, magnitude);
                fclose(log_file);
            } else {
                perror("Failed to open impact_log.txt");
            }
        }

        // Sleep for 50ms
        usleep(50000);
    }

    close(i2c_fd);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

