#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define GYRO_ADDR 0x68
#define WHO_AM_I 0xD1
#define SAMPLES 100
#define THRESHOLD 50
#define LOG_FILE "gyro_log.txt"
#define SAMPLE_PERIOD 50000  // 50 ms

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    int i2c_fd, log_fd;
    uint8_t data[2];
    int16_t gyro_x, gyro_y, gyro_z;
    int16_t offset_x = 0, offset_y = 0, offset_z = 0;
    struct timespec ts;
    char timestamp[20];

    // Open I2C bus
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, GYRO_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Verify sensor presence
    data[0] = WHO_AM_I;
    if (read(i2c_fd, data, 1) != 1 || data[0] != 0xD1) {
        fprintf(stderr, "Sensor not found\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Calibrate gyroscope
    for (int i = 0; i < SAMPLES; i++) {
        if (read(i2c_fd, data, 6) != 6) {
            perror("Failed to read gyroscope data");
            close(i2c_fd);
            return EXIT_FAILURE;
        }
        gyro_x += (int16_t)(data[1] << 8 | data[0]);
        gyro_y += (int16_t)(data[3] << 8 | data[2]);
        gyro_z += (int16_t)(data[5] << 8 | data[4]);
        usleep(SAMPLE_PERIOD);
    }
    offset_x = gyro_x / SAMPLES;
    offset_y = gyro_y / SAMPLES;
    offset_z = gyro_z / SAMPLES;

    // Open log file
    if ((log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644)) < 0) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        if (read(i2c_fd, data, 6) != 6) {
            perror("Failed to read gyroscope data");
            break;
        }
        gyro_x = (int16_t)(data[1] << 8 | data[0]) - offset_x;
        gyro_y = (int16_t)(data[3] << 8 | data[2]) - offset_y;
        gyro_z = (int16_t)(data[5] << 8 | data[4]) - offset_z;

        if (abs(gyro_x) > THRESHOLD || abs(gyro_y) > THRESHOLD || abs(gyro_z) > THRESHOLD) {
            fprintf(stderr, "Alert: Gyroscope values exceed threshold\n");
            fprintf(log_fd, "Alert: Gyroscope values exceed threshold\n");
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", localtime(&ts.tv_sec));
        fprintf(log_fd, "%s.%03ld X: %d Y: %d Z: %d\n", timestamp, ts.tv_nsec / 1000000, gyro_x, gyro_y, gyro_z);

        usleep(SAMPLE_PERIOD);
    }

    // Clean up
    close(i2c_fd);
    close(log_fd);
    return EXIT_SUCCESS;
}

