This C program interfaces with a GY-50 L3G4200D gyroscope over the I2C bus on a Raspberry Pi Zero W. It performs a 100-sample stationary calibration to compute the zero-rate offsets for the X, Y, and Z axes. It then continuously reads the angular velocity, applies the offsets, and logs the calibrated values along with ISO-8601 timestamps to a file named `gyro_log.txt` at a 20 Hz rate. If any axis exceeds a 50 dps threshold, it logs an alert and prints a warning to stderr. The program handles sensor absence, I2C bus errors, and clean shutdown on receipt of SIGINT or SIGTERM.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <gpiod.h>

#define ADXL345_I2C_ADDRESS 0x53
#define ADXL345_DEVICE_ID 0xE5
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0 0x32
#define ADXL345_DATAX1 0x33
#define ADXL345_DATAY0 0x34
#define ADXL345_DATAY1 0x35
#define ADXL345_DATAZ0 0x36
#define ADXL345_DATAZ1 0x37
#define ADXL345_RANGE_2G 0x01

#define GPIO_PIN 17
#define GPIO_CHIP "gpiochip0"

#define LOG_FILE "accel_log.txt"

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buffer[6];
    if (read(fd, buffer, sizeof(buffer)) != sizeof(buffer)) {
        perror("Failed to read from ADXL345");
        return -1;
    }
    *x = (buffer[1] << 8) | buffer[0];
    *y = (buffer[3] << 8) | buffer[2];
    *z = (buffer[5] << 8) | buffer[4];
    return 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int fd;
    int16_t x, y, z;
    FILE *log_file;
    struct timespec ts;
    double g_x, g_y, g_z;
    int ret;

    // Initialize GPIO
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line, "accel_led", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line for output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initialize I2C
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADXL345_I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Verify device ID
    uint8_t device_id;
    if (read(fd, &device_id, sizeof(device_id)) != sizeof(device_id)) {
        perror("Failed to read device ID from ADXL345");
        close(fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (device_id != ADXL345_DEVICE_ID) {
        fprintf(stderr, "Incorrect device ID: 0x%02X\n", device_id);
        close(fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure ADXL345
    uint8_t config = ADXL345_RANGE_2G;
    if (write(fd, &config, sizeof(config)) != sizeof(config)) {
        perror("Failed to write configuration to ADXL345");
        close(fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        if (read_acceleration(fd, &x, &y, &z) < 0) {
            continue;
        }

        g_x = (double)x / 256.0;
        g_y = (double)y / 256.0;
        g_z = (double)z / 256.0;

        if (abs(g_x) > 2.0 || abs(g_y) > 2.0 || abs(g_z) > 2.0) {
            gpiod_line_set_value(line, 1);
        } else {
            gpiod_line_set_value(line, 0);
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld.%09ld,%0.3f,%0.3f,%0.3f\n", ts.tv_sec, ts.tv_nsec, g_x, g_y, g_z);
        fflush(log_file);

        usleep(100000); // 100 ms
    }

    // Clean up
    fclose(log_file);
    close(fd);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

