#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDR1 0x50
#define I2C_ADDR2 0x51
#define SAMPLE_INTERVAL 10000  // 10 ms in microseconds
#define SAMPLE_SIZE 2  // 16-bit signed audio samples

struct i2c_device {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
};

struct i2c_device i2c_dev1, i2c_dev2;
FILE *log_file;

void signal_handler(int signum) {
    if (signum == SIGINT) {
        if (log_file) {
            fclose(log_file);
        }
        if (i2c_dev1.line) {
            gpiod_line_release(i2c_dev1.line);
        }
        if (i2c_dev2.line) {
            gpiod_line_release(i2c_dev2.line);
        }
        if (i2c_dev1.chip) {
            gpiod_chip_close(i2c_dev1.chip);
        }
        if (i2c_dev2.chip) {
            gpiod_chip_close(i2c_dev2.chip);
        }
        exit(0);
    }
}

int i2c_read_samples(struct i2c_device *dev, int16_t *samples, size_t count) {
    int ret;
    struct i2c_msg msg;
    struct i2c_rdwr_ioctl_data msgs;

    msg.addr = dev->line->offset;
    msg.flags = 0;
    msg.len = count * sizeof(int16_t);
    msg.buf = (unsigned char *)samples;

    msgs.nmsgs = 1;
    msgs.msgs = &msg;

    ret = ioctl(dev->chip->fd, I2C_RDWR, &msgs);
    if (ret < 0) {
        perror("I2C_RDWR");
        return -1;
    }

    return 0;
}

int main() {
    struct timespec start, end;
    int16_t samples1[SAMPLE_SIZE], samples2[SAMPLE_SIZE];
    int ret;

    // Initialize signal handler
    signal(SIGINT, signal_handler);

    // Open log file
    log_file = fopen("audio_log.dat", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    // Initialize I2C devices
    i2c_dev1.chip = gpiod_chip_open_by_name("gpiochip0");
    if (!i2c_dev1.chip) {
        perror("Failed to open I2C chip 1");
        goto cleanup;
    }

    i2c_dev2.chip = gpiod_chip_open_by_name("gpiochip0");
    if (!i2c_dev2.chip) {
        perror("Failed to open I2C chip 2");
        goto cleanup;
    }

    i2c_dev1.line = gpiod_chip_get_line(i2c_dev1.chip, I2C_ADDR1);
    if (!i2c_dev1.line) {
        perror("Failed to get I2C line 1");
        goto cleanup;
    }

    i2c_dev2.line = gpiod_chip_get_line(i2c_dev2.chip, I2C_ADDR2);
    if (!i2c_dev2.line) {
        perror("Failed to get I2C line 2");
        goto cleanup;
    }

    ret = gpiod_line_request_input(i2c_dev1.line, "audio_log");
    if (ret < 0) {
        perror("Failed to request input for I2C line 1");
        goto cleanup;
    }

    ret = gpiod_line_request_input(i2c_dev2.line, "audio_log");
    if (ret < 0) {
        perror("Failed to request input for I2C line 2");
        goto cleanup;
    }

    // Main loop
    while (1) {
        clock_gettime(CLOCK_REALTIME, &start);

        ret = i2c_read_samples(&i2c_dev1, samples1, SAMPLE_SIZE);
        if (ret < 0) {
            fprintf(stderr, "Failed to read samples from sensor 1\n");
            continue;
        }

        ret = i2c_read_samples(&i2c_dev2, samples2, SAMPLE_SIZE);
        if (ret < 0) {
            fprintf(stderr, "Failed to read samples from sensor 2\n");
            continue;
        }

        clock_gettime(CLOCK_REALTIME, &end);

        int64_t tdoa = (end.tv_sec - start.tv_sec) * 1000000000LL + (end.tv_nsec - start.tv_nsec);

        fprintf(log_file, "%ld,%ld,%d,%d,%lld\n", start.tv_sec, start.tv_nsec, samples1[0], samples2[0], tdoa);
        fflush(log_file);

        usleep(SAMPLE_INTERVAL);
    }

cleanup:
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_dev1.line) {
        gpiod_line_release(i2c_dev1.line);
    }
    if (i2c_dev2.line) {
        gpiod_line_release(i2c_dev2.line);
    }
    if (i2c_dev1.chip) {
        gpiod_chip_close(i2c_dev1.chip);
    }
    if (i2c_dev2.chip) {
        gpiod_chip_close(i2c_dev2.chip);
    }

    return EXIT_FAILURE;
}

