#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <time.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 3
#define SPI_SPEED 1000000
#define SPI_BITS_PER_WORD 16
#define REGISTER_GYRO_X 0x00
#define REGISTER_GYRO_Y 0x02
#define REGISTER_GYRO_Z 0x04
#define REGISTER_ACCEL_X 0x06
#define REGISTER_ACCEL_Y 0x08
#define REGISTER_ACCEL_Z 0x0A
#define GYRO_SENSITIVITY 0.005
#define ACCEL_SENSITIVITY 0.00025
#define STALL_TIME_US 40
#define SAMPLE_INTERVAL_MS 100
#define HEADER "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n"

volatile sig_atomic_t running = 1;

void cleanup() {
    running = 0;
}

void signal_handler(int signum) {
    cleanup();
}

int read_register(int fd, uint8_t reg, uint16_t *value) {
    uint8_t tx[2] = {0x00, reg};
    uint8_t rx[2];
    ssize_t ret;

    ret = gpiod_spi_xfer(fd, tx, 2, rx, 2, STALL_TIME_US);
    if (ret < 0) {
        fprintf(stderr, "gpiod_spi_xfer failed: %s\n", strerror(-ret));
        return -1;
    }

    *value = (rx[0] << 8) | rx[1];
    return 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int fd;
    FILE *csv_file;
    uint16_t gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;
    struct timespec ts;
    char timestamp[20];

    // Initialize SPI
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, 8);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    fd = gpiod_line_request_output(line, "imu_spi", 0);
    if (fd < 0) {
        fprintf(stderr, "Failed to request GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initialize CSV file
    csv_file = fopen("imu_data.csv", "w");
    if (!csv_file) {
        fprintf(stderr, "Failed to open CSV file\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    fprintf(csv_file, HEADER);

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    atexit(cleanup);

    while (running) {
        if (read_register(fd, REGISTER_GYRO_X, &gyro_x) < 0) continue;
        if (read_register(fd, REGISTER_GYRO_Y, &gyro_y) < 0) continue;
        if (read_register(fd, REGISTER_GYRO_Z, &gyro_z) < 0) continue;
        if (read_register(fd, REGISTER_ACCEL_X, &accel_x) < 0) continue;
        if (read_register(fd, REGISTER_ACCEL_Y, &accel_y) < 0) continue;
        if (read_register(fd, REGISTER_ACCEL_Z, &accel_z) < 0) continue;

        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.%03ld", &ts);

        fprintf(csv_file, "%s,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f\n",
                timestamp, gyro_x * GYRO_SENSITIVITY,
                gyro_y * GYRO_SENSITIVITY, gyro_z * GYRO_SENSITIVITY,
                accel_x * ACCEL_SENSITIVITY, accel_y * ACCEL_SENSITIVITY,
                accel_z * ACCEL_SENSITIVITY);

        fflush(csv_file);

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    fclose(csv_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

