        if (read_register(fd, REGISTER_GYRO_Z, &gyro_z) < 0) continue;
        if (read_register(fd, REGISTER_ACCEL_X, &accel_x) < 0) continue;
        if (read_register(fd, REGISTER_ACCEL_Y, &accel_y) < 0) continue;
        if (read_register(fd, REGISTER_ACCEL_Z, &accel_z) < 0) continue;

