#include <unistd.h>
#include <libgpiod.h>

#define SPI_CHANNEL 0
#define SPI_CE0_PIN 8
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define GYRO_SCALE 0.05
#define ACCEL_SCALE 0.00025
#define READ_COMMAND_BIT 0x8000
#define DUMMY_VALUE 0x0000
#define STALL_TIME_US 40
#define READ_INTERVAL_MS 100

static struct gpiod_chip *chip;
static struct gpiod_line *ce0_line;
static int running = 1;

void handle_sigint(int sig) {
    running = 0;
}

int main() {
    struct gpiod_line_request req;
    uint16_t gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;
    uint16_t read_command;
    uint16_t dummy_value;
    uint16_t data[2];
    int ret;

    // Initialize GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request CE0 line
    ret = gpiod_line_request_output(chip, "ce0", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
    if (ret < 0) {
        perror("Failed to request CE0 line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    ce0_line = gpiod_chip_get_line(chip, SPI_CE0_PIN);
    if (!ce0_line) {
        perror("Failed to get CE0 line");
        gpiod_line_release(ce0_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up signal handler for Ctrl-C
    signal(SIGINT, handle_sigint);

    while (running) {
        // Set CE0 low
        ret = gpiod_line_set_value(ce0_line, 0);
        if (ret < 0) {
            perror("Failed to set CE0 low");
            break;
        }

        // Prepare read command
        read_command = 0x0000 | READ_COMMAND_BIT;

        // Send read command
        ret = gpiod_line_request_bulk(chip, &req, 1, "read_command", GPIOD_LINE_REQUEST_DIRECTION_INPUT);
        if (ret < 0) {
            perror("Failed to request read command line");
            break;
        }
        ret = gpiod_line_set_value_bulk(&req, 1);
        if (ret < 0) {
            perror("Failed to set read command line");
            gpiod_line_release_bulk(&req);
            break;
        }
        usleep(STALL_TIME_US);

        // Send dummy value to clock out data
        ret = gpiod_line_request_bulk(chip, &req, 1, "dummy_value", GPIOD_LINE_REQUEST_DIRECTION_INPUT);
        if (ret < 0) {
            perror("Failed to request dummy value line");
            gpiod_line_release_bulk(&req);
            break;
        }
        ret = gpiod_line_set_value_bulk(&req, 1);
        if (ret < 0) {
            perror("Failed to set dummy value line");
            gpiod_line_release_bulk(&req);
            break;
        }
        usleep(STALL_TIME_US);

        // Read data
        ret = gpiod_line_request_bulk(chip, &req, 2, "data", GPIOD_LINE_REQUEST_DIRECTION_INPUT);
        if (ret < 0) {
            perror("Failed to request data lines");
            gpiod_line_release_bulk(&req);
            break;
        }
        ret = gpiod_line_set_value_bulk(&req, 2);
        if (ret < 0) {
            perror("Failed to set data lines");
            gpiod_line_release_bulk(&req);
            break;
        }
        ret = gpiod_line_get_value_bulk(&req, data, 2);
        if (ret < 0) {
            perror("Failed to read data");
            gpiod_line_release_bulk(&req);
            break;
        }

        // Convert data to values
        gyro_x = (data[0] << 8) | (data[1] & 0xFF);
        gyro_y = (data[2] << 8) | (data[3] & 0xFF);
        gyro_z = (data[4] << 8) | (data[5] & 0xFF);
        accel_x = (data[6] << 8) | (data[7] & 0xFF);
        accel_y = (data[8] << 8) | (data[9] & 0xFF);
        accel_z = (data[10] << 8) | (data[11] & 0xFF);

        // Scale values
        gyro_x *= GYRO_SCALE;
        gyro_y *= GYRO_SCALE;
        gyro_z *= GYRO_SCALE;
        accel_x *= ACCEL_SCALE;
        accel_y *= ACCEL_SCALE;
        accel_z *= ACCEL_SCALE;

        // Print values
        printf("Gyro: X=%.2f, Y=%.2f, Z=%.2f\n", gyro_x, gyro_y, gyro_z);
        printf("Accel: X=%.4f, Y=%.4f, Z=%.4f\n", accel_x, accel_y, accel_z);

        // Wait for next read
        usleep(READ_INTERVAL_MS * 1000);
    }

    // Clean up
    gpiod_line_release(ce0_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}
```

This code initializes the GPIO chip and requests the CE0 line for SPI communication. It sets up a signal handler for Ctrl-C to cleanly exit the program. The main loop reads the gyroscope and accelerometer data from the ADIS16448 IMU using the two-cycle protocol, scales the data, and prints it to the console. The program handles errors during initialization, SPI communication, and data reading, and ensures that resources are released on exit.

