            perror("Failed to read accelerometer ZOUT");
            continue;
        }
        if (i2c_read_retry(i2c_fd, MPU6886_GYRO_XOUT_H, gyro_xout, 2) < 0) {
            perror("Failed to read gyroscope XOUT");
            continue;
        }
        if (i2c_read_retry(i2c_fd, MPU6886_GYRO_YOUT_H, gyro_yout, 2) < 0) {
            perror("Failed to read gyroscope YOUT");
            continue;
        }
        if (i2c_read_retry(i2c_fd, MPU6886_GYRO_ZOUT_H, gyro_zout, 2) < 0) {
            perror("Failed to read gyroscope ZOUT");
            continue;
        }

        accel_x = (accel_xout[0] << 8) | accel_xout[1];
        accel_y = (accel_yout[0] << 8) | accel_yout[1];
        accel_z = (accel_zout[0] << 8) | accel_zout[1];
        gyro_x = (gyro_xout[0] << 8) | gyro_xout[1];
        gyro_y = (gyro_yout[0] << 8) | gyro_yout[1];
        gyro_z = (gyro_zout[0] << 8) | gyro_zout[1];

        printf("Accel: X=%d, Y=%d, Z=%d\n", accel_x, accel_y, accel_z);
        printf("Gyro: X=%d, Y=%d, Z=%d\n", gyro_x, gyro_y, gyro_z);

        usleep(50000); // 50ms
    }

    // Close I2C bus
    close(i2c_fd);

    return EXIT_SUCCESS;
}

