#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x53
#define ADXL345_DEVICE_ID 0xE5
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATA_X0 0x32
#define ADXL345_DATA_Y0 0x34
#define ADXL345_DATA_Z0 0x36
#define LED_GPIO 17
#define LED_CONSUMER "accelerometer_led"
#define THRESHOLD 256 * 2.5
#define LOG_FILE "impact_log.txt"

static struct gpiod_chip *chip;
static struct gpiod_line *led_line;
static FILE *log_file;

void cleanup() {
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

void handle_sigint(int sig) {
    cleanup();
    exit(0);
}

int read_i2c(int fd, uint8_t reg, uint8_t *data, size_t len) {
    uint8_t buf[len + 1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        perror("write");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("read");
        return -1;
    }
    return 0;
}

int write_i2c(int fd, uint8_t reg, uint8_t *data, size_t len) {
    uint8_t buf[len + 1];
    buf[0] = reg;
    memcpy(buf + 1, data, len);
    if (write(fd, buf, len + 1) != len + 1) {
        perror("write");
        return -1;
    }
    return 0;
}

int main() {
    struct gpiod_line_request req = {
        .consumer = LED_CONSUMER,
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT,
        .default_val = 0,
    };
    struct timespec ts = {0, 10 * 1000 * 1000}; // 10 ms
    uint8_t device_id, data_format, x0, y0, z0;
    int fd, ret;

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        perror("gpiod_chip_get_line");
        cleanup();
        return 1;
    }

    ret = gpiod_line_request(led_line, &req);
    if (ret < 0) {
        perror("gpiod_line_request");
        cleanup();
        return 1;
    }

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open");
        cleanup();
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("ioctl");
        close(fd);
        cleanup();
        return 1;
    }

    if (read_i2c(fd, ADXL345_DEVICE_ID, &device_id, 1) < 0) {
        cleanup();
        return 1;
    }

    if (device_id != ADXL345_DEVICE_ID) {
        fprintf(stderr, "Device ID mismatch: 0x%02X\n", device_id);
        cleanup();
        return 1;
    }

    if (write_i2c(fd, ADXL345_DATA_FORMAT, &data_format, 1) < 0) {
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        cleanup();
        return 1;
    }

    while (1) {
        if (read_i2c(fd, ADXL345_DATA_X0, &x0, 1) < 0 ||
            read_i2c(fd, ADXL345_DATA_Y0, &y0, 1) < 0 ||
            read_i2c(fd, ADXL345_DATA_Z0, &z0, 1) < 0) {
            cleanup();
            return 1;
        }

        int16_t x = (x0 | (y0 << 8));
        int16_t y = (y0 | (z0 << 8));
        int16_t z = (z0 | (x0 << 8));

        double magnitude = sqrt(x * x + y * y + z * z);

        if (magnitude > THRESHOLD) {
            gpiod_line_set_value(led_line, 1);
            usleep(500 * 1000);
            gpiod_line_set_value(led_line, 0);

            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d.%03ld: X=%d, Y=%d, Z=%d, Magnitude=%.2f\n",
                    tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
                    tm->tm_hour, tm->tm_min, tm->tm_sec, (long) (now % 1) * 1000,
                    x, y, z, magnitude);
            fflush(log_file);
        }

        nanosleep(&ts, NULL);
    }

    cleanup();
    return 0;
}

