        int16_t z = (z0 | (x0 << 8));

        double magnitude = sqrt(x * x + y * y + z * z);

        if (magnitude > THRESHOLD) {
            gpiod_line_set_value(led_line, 1);
            usleep(500 * 1000);
            gpiod_line_set_value(led_line, 0);

            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d.%03ld: X=%d, Y=%d, Z=%d, Magnitude=%.2f\n",
                    tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
                    tm->tm_hour, tm->tm_min, tm->tm_sec, (long) (now % 1) * 1000,
                    x, y, z, magnitude);
            fflush(log_file);
        }

        nanosleep(&ts, NULL);
    }

    cleanup();
    return 0;
}
