#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <sys/ioctl.h>

#define I2C_BUS "/dev/i2c-1"
#define MMA8451Q_I2C_ADDR 0x1D
#define MMA8451Q_ID_REG 0x0D
#define MMA8451Q_ID_VAL 0x2A
#define MMA8451Q_DATAX0_REG 0x01
#define MMA8451Q_DATAX1_REG 0x02
#define MMA8451Q_DATAY0_REG 0x03
#define MMA8451Q_DATAY1_REG 0x04
#define MMA8451Q_DATAZ0_REG 0x05
#define MMA8451Q_DATAZ1_REG 0x06
#define MMA8451Q_CTRL_REG1 0x2A
#define MMA8451Q_CTRL_REG1_ACTIVE 0x01
#define MMA8451Q_CTRL_REG1_ODR_100HZ 0x05
#define LED_PIN 17
#define THRESHOLD 2048
#define LOG_FILE "impact_log.txt"

static int i2c_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *led_line;
static FILE *log_file;

void cleanup() {
    if (log_file) {
        fclose(log_file);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

void handle_signal(int sig) {
    cleanup();
    exit(0);
}

int read_mma8451q_acceleration(int *x, int *y, int *z) {
    uint8_t data[6];
    if (read(i2c_fd, data, sizeof(data)) != sizeof(data)) {
        perror("Failed to read from MMA8451Q");
        return -1;
    }
    *x = (data[1] << 8) | data[0];
    *y = (data[3] << 8) | data[2];
    *z = (data[5] << 8) | data[4];
    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MMA8451Q_I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t id;
    if (read(i2c_fd, &id, sizeof(id)) != sizeof(id)) {
        perror("Failed to read from MMA8451Q ID register");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (id != MMA8451Q_ID_VAL) {
        fprintf(stderr, "MMA8451Q ID mismatch: 0x%02X, expected 0x%02X\n", id, MMA8451Q_ID_VAL);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_library_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, "accel_led", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t ctrl_reg1 = MMA8451Q_CTRL_REG1_ACTIVE | MMA8451Q_CTRL_REG1_ODR_100HZ;
    if (write(i2c_fd, &ctrl_reg1, sizeof(ctrl_reg1)) != sizeof(ctrl_reg1)) {
        perror("Failed to write to MMA8451Q CTRL_REG1");
        fclose(log_file);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        int x, y, z;
        if (read_mma8451q_acceleration(&x, &y, &z) < 0) {
            continue;
        }

        int magnitude = sqrt(x * x + y * y + z * z);
        if (magnitude > THRESHOLD) {
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            fprintf(log_file, "%ld.%09ld: Acceleration: X=%d, Y=%d, Z=%d, Magnitude=%d\n",
                    ts.tv_sec, ts.tv_nsec, x, y, z, magnitude);
            fflush(log_file);

            gpiod_line_set_value(led_line, 1);
            usleep(500 * 1000);
            gpiod_line_set_value(led_line, 0);
        }

        usleep(100 * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

