#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define I2C_DEVICE "/dev/i2c-1"
#define TMAG5273_ADDRESS 0x1E
#define SAMPLE_INTERVAL 1
#define CSV_HEADER "Timestamp, X, Y, Z\n"

int i2c_fd;
FILE *csv_fd;

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        if (csv_fd) {
            fclose(csv_fd);
        }
        if (i2c_fd) {
            close(i2c_fd);
        }
        exit(signum);
    }
}

int read_tmag5273(float *x, float *y, float *z) {
    uint8_t buffer[6];
    if (read(i2c_fd, buffer, sizeof(buffer)) != sizeof(buffer)) {
        perror("Failed to read from TMAG5273");
        return -1;
    }

    *x = (buffer[0] << 8 | buffer[1]) / 1000.0;
    *y = (buffer[2] << 8 | buffer[3]) / 1000.0;
    *z = (buffer[4] << 8 | buffer[5]) / 1000.0;

    return 0;
}

int main() {
    struct timespec ts;
    char timestamp[20];

    // Open I2C device
    if ((i2c_fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, TMAG5273_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open CSV file
    csv_fd = fopen("magnetic_field_log.csv", "a");
    if (!csv_fd) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Write header if file is empty
    if (fseek(csv_fd, 0, SEEK_END) == 0 && ftell(csv_fd) == 0) {
        fputs(CSV_HEADER, csv_fd);
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        // Get current time
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("Failed to get current time");
            continue;
        }

        // Format timestamp
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        // Read magnetic field data
        float x, y, z;
        if (read_tmag5273(&x, &y, &z) == 0) {
            // Write data to CSV file
            fprintf(csv_fd, "%s, %.3f, %.3f, %.3f\n", timestamp, x, y, z);
            fflush(csv_fd);
        }

        // Sleep for the specified interval
        sleep(SAMPLE_INTERVAL);
    }

    // Clean up
    fclose(csv_fd);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

