#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <sys/ioctl.h>

#define ADXL345_I2C_ADDR 0x53
#define ADXL345_DEVICE "/dev/i2c-1"
#define ADXL345_INT1_PIN 17
#define ADXL345_STANDBY_REG 0x2D
#define ADXL345_DATA_FORMAT_REG 0x31
#define ADXL345_DATAX0_REG 0x32
#define ADXL345_DEVICE_ID 0xE5

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    int i2c_fd, gpio_fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct timespec ts;
    FILE *log_file;

    // Open I2C device
    if ((i2c_fd = open(ADXL345_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    if ((chip = gpiod_chip_open_by_name("gpiochip0")) == NULL) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Request GPIO line
    if ((line = gpiod_chip_get_line(chip, ADXL345_INT1_PIN)) == NULL) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Configure GPIO line as input
    if (gpiod_line_request_input(line, "adxl345_int1") < 0) {
        perror("Failed to request GPIO line as input");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    if ((log_file = fopen("freefall_log.csv", "w")) == NULL) {
        perror("Failed to open log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,X,Y,Z\n");

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Place sensor in standby mode
    uint8_t standby_reg = 0x08;
    if (write(i2c_fd, &standby_reg, 1) != 1) {
        perror("Failed to write to ADXL345 standby register");
        goto cleanup;
    }

    // Enable free-fall interrupt
    uint8_t data_format_reg = 0x0B;
    if (write(i2c_fd, &data_format_reg, 1) != 1) {
        perror("Failed to write to ADXL345 data format register");
        goto cleanup;
    }

    // Main loop
    while (running) {
        if (gpiod_line_event_wait(line, 1000000) < 0) {
            perror("Failed to wait for GPIO event");
            continue;
        }

        struct gpiod_line_event event;
        if (gpiod_line_event_read(line, &event) < 0) {
            perror("Failed to read GPIO event");
            continue;
        }

        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            // Capture timestamp
            if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
                perror("Failed to get current time");
                continue;
            }

            // Read acceleration data
            uint8_t data[6];
            if (read(i2c_fd, data, 6) != 6) {
                perror("Failed to read acceleration data");
                continue;
            }

            int16_t x = (data[1] << 8) | data[0];
            int16_t y = (data[3] << 8) | data[2];
            int16_t z = (data[5] << 8) | data[4];

            // Write data to log file
            fprintf(log_file, "%ld.%03ld,%d,%d,%d\n", ts.tv_sec, ts.tv_nsec / 1000000, x, y, z);
            fflush(log_file);
        }
    }

cleanup:
    // Clean up
    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

