#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <libgpiod/spi.h>

#define SPI_CHANNEL 0
#define SPI_CE0_PIN 8
#define SPI_MODE 3
#define SPI_SPEED 1000000
#define WHO_AM_I_REG 0x00
#define WHO_AM_I_VALUE 0x16
#define ANGULAR_RATE_REG 0x10
#define ANGULAR_RATE_SCALE 0.0305
#define SAMPLE_INTERVAL 10

static struct gpiod_chip *chip;
static struct gpiod_line *ce0_line;
static FILE *log_file;

void handle_sigint(int sig) {
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    struct gpiod_line_request ce0_req = {
        .consumer = "adis16266",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT,
        .default_val = 0,
    };
    struct gpiod_spi_config spi_config = {
        .channel = SPI_CHANNEL,
        .mode = SPI_MODE,
        .speed = SPI_SPEED,
        .bits_per_word = 16,
    };
    uint16_t tx_buffer[2];
    uint16_t rx_buffer[2];
    struct timespec ts;
    char timestamp[20];

    signal(SIGINT, handle_sigint);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request CE0 line
    ce0_line = gpiod_chip_get_line(chip, SPI_CE0_PIN);
    if (!ce0_line) {
        perror("Failed to get CE0 line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(ce0_line, &ce0_req)) {
        perror("Failed to request CE0 line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "w");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(ce0_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Write CSV header
    fprintf(log_file, "Timestamp,Angular Rate (deg/sec)\n");

    // Verify WHO_AM_I register
    tx_buffer[0] = (WHO_AM_I_REG | 0x80) << 8;
    if (gpiod_spi_xfer(chip, &spi_config, tx_buffer, rx_buffer, 2)) {
        perror("Failed to read WHO_AM_I register");
        fclose(log_file);
        gpiod_line_release(ce0_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (rx_buffer[0] != (WHO_AM_I_VALUE << 8)) {
        fprintf(stderr, "WHO_AM_I register mismatch: expected 0x%04X, got 0x%04X\n", (WHO_AM_I_VALUE << 8), rx_buffer[0]);
        fclose(log_file);
        gpiod_line_release(ce0_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Sample angular rate
    while (1) {
        tx_buffer[0] = (ANGULAR_RATE_REG | 0x80) << 8;
        if (gpiod_spi_xfer(chip, &spi_config, tx_buffer, rx_buffer, 2)) {
            perror("Failed to read angular rate register");
            fclose(log_file);
            gpiod_line_release(ce0_line);
