#define WHO_AM_I_VALUE 0xD7
#define GYRO_SCALE 114.285
#define SAMPLE_INTERVAL 10000  // 10 ms in microseconds

struct gpiod_chip *chip;
struct gpiod_line *line;
FILE *log_file;
int running = 1;

void signal_handler(int sig) {
    running = 0;
}

int init_i2c() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, 2);  // Assuming SDA is on GPIO2
    if (!line) {
        perror("Failed to get SDA line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(line, "i2c") < 0) {
        perror("Failed to request SDA line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

int init_gyro() {
    uint8_t who_am_i;
    int retries = 3;

    while (retries--) {
        if (gpiod_i2c_read_byte(chip, I2C_ADDRESS, &who_am_i) < 0) {
            perror("Failed to read WHO_AM_I register");
            continue;
        }

        if (who_am_i == WHO_AM_I_VALUE) {
            return 0;
        }
    }

    fprintf(stderr, "Gyro WHO_AM_I register does not match expected value\n");
    return -1;
}

void log_data(int16_t x, int16_t y, int16_t z) {
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) == 0) {
        fprintf(log_file, "%ld.%09ld,%d,%d,%d\n", ts.tv_sec, ts.tv_nsec, x, y, z);
    }
}

int main() {
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Failed to set signal handler");
        return EXIT_FAILURE;
    }

    if (init_i2c() < 0) {
        return EXIT_FAILURE;
    }

    if (init_gyro() < 0) {
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_file = fopen("gyro_log.csv", "w");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    fprintf(log_file, "Timestamp,X,Y,Z\n");

    while (running) {
        uint8_t data[6];
        if (gpiod_i2c_read(chip, I2C_ADDRESS, data, sizeof(data)) < 0) {
            perror("Failed to read gyroscope data");
            continue;
        }

        int16_t x = (data[0] << 8) | data[1];
        int16_t y = (data[2] << 8) | data[3];
        int16_t z = (data[4] << 8) | data[5];

        log_data(x / GYRO_SCALE, y / GYRO_SCALE, z / GYRO_SCALE);

        usleep(SAMPLE_INTERVAL);
    }

    fclose(log_file);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

