#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define LOG_FILE "flame_events.log"

volatile sig_atomic_t stop_flag = 0;

void sigint_handler(int signum) {
    stop_flag = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up resistor on GPIO%d\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set SIGINT handler\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    time_t now;
    struct tm *tm_info;
    char time_str[20];

    while (!stop_flag) {
        int level = gpioRead(GPIO_PIN);
        if (level < 0) {
            fprintf(stderr, "Failed to read GPIO%d\n", GPIO_PIN);
        } else {
            time(&now);
            tm_info = localtime(&now);
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
            if (level == 0) {
                fprintf(log_file, "%s – Flame detected: YES\n", time_str);
                fprintf(stdout, "FLAME DETECTED!\n");
            } else {
                fprintf(log_file, "%s – Flame detected: NO\n", time_str);
            }
            fflush(log_file);
        }
        gpioDelay(500 * 1000); // 500 ms
    }

    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

