#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SENSOR_ADDRESS 0x53
#define SAMPLE_INTERVAL 100  // 100 ms
#define CSV_HEADER "Timestamp,X,Y,Z\n"

volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int main() {
    int i2c_fd, csv_fd;
    char buffer[6];
    struct timespec ts;
    char timestamp[20];
    FILE *csv_file;

    // Open I2C device
    if ((i2c_fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open CSV file
    if ((csv_fd = open("vibration_log.csv", O_WRONLY | O_CREAT | O_APPEND, 0644)) < 0) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Write CSV header
    if (write(csv_fd, CSV_HEADER, strlen(CSV_HEADER)) != strlen(CSV_HEADER)) {
        perror("Failed to write CSV header");
        close(i2c_fd);
        close(csv_fd);
        return EXIT_FAILURE;
    }

    // Install SIGINT handler
    signal(SIGINT, sigint_handler);

    csv_file = fdopen(csv_fd, "a");

    while (running) {
        // Read acceleration data
        if (read(i2c_fd, buffer, 6) != 6) {
            if (errno == EIO) {
                fprintf(stderr, "I2C read error, skipping sample\n");
            } else {
                perror("Failed to read from I2C device");
                running = 0;
            }
            continue;
        }

        // Get current timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
            perror("Failed to get current time");
            running = 0;
            continue;
        }

        // Format timestamp as ISO-8601 UTC
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.%03ldZ", &ts);

        // Write sample to CSV file
        fprintf(csv_file, "%s,%d,%d,%d\n", timestamp, (buffer[0] << 8) | buffer[1], (buffer[2] << 8) | buffer[3], (buffer[4] << 8) | buffer[5]);

        // Flush CSV file buffer
        fflush(csv_file);

        // Sleep for the specified interval
        usleep(SAMPLE_INTERVAL * 1000);
    }

    // Close CSV file
    fclose(csv_file);

    // Close I2C device
    close(i2c_fd);

    return EXIT_SUCCESS;
}

