#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define MMA8452Q_I2C_ADDR 0x1D
#define MMA8452Q_WHO_AM_I 0x0D
#define MMA8452Q_CTRL_REG1 0x2A
#define MMA8452Q_DATA_FORMAT 0x0B
#define MMA8452Q_OUT_X_MSB 0x01
#define MMA8452Q_OUT_X_LSB 0x02
#define MMA8452Q_OUT_Y_MSB 0x03
#define MMA8452Q_OUT_Y_LSB 0x04
#define MMA8452Q_OUT_Z_MSB 0x05
#define MMA8452Q_OUT_Z_LSB 0x06
#define MMA8452Q_DATA_RATE_100HZ 0x0B
#define MMA8452Q_DATA_FORMAT_FULL_RES 0x03

int i2c_fd = -1;
FILE *log_file = NULL;

void signal_handler(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(signum);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd == -1) {
        perror("open");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MMA8452Q_I2C_ADDR) == -1) {
        perror("ioctl");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t who_am_i;
    if (read(i2c_fd, &who_am_i, 1) != 1) {
        perror("read WHO_AM_I");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (who_am_i != 0x2A) {
        fprintf(stderr, "Incorrect WHO_AM_I value: 0x%02X\n", who_am_i);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t ctrl_reg1 = 0x00;
    if (read(i2c_fd, &ctrl_reg1, 1) != 1) {
        perror("read CTRL_REG1");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    ctrl_reg1 |= 0x01; // Set STANDBY mode
    if (write(i2c_fd, &ctrl_reg1, 1) != 1) {
        perror("write CTRL_REG1");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t data_format = MMA8452Q_DATA_FORMAT_FULL_RES;
    if (write(i2c_fd, &data_format, 1) != 1) {
        perror("write DATA_FORMAT");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    ctrl_reg1 = MMA8452Q_DATA_RATE_100HZ;
    if (write(i2c_fd, &ctrl_reg1, 1) != 1) {
        perror("write CTRL_REG1");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    ctrl_reg1 |= 0x02; // Set ACTIVE mode
    if (write(i2c_fd, &ctrl_reg1, 1) != 1) {
        perror("write CTRL_REG1");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen("fall_log.txt", "a");
    if (log_file == NULL) {
        perror("fopen");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t data[6];
    while (1) {
        if (read(i2c_fd, data, 6) != 6) {
            perror("read data");
            continue;
        }

        int16_t x = (data[0] << 8) | data[1];
        int16_t y = (data[2] << 8) | data[3];
        int16_t z = (data[4] << 8) | data[5];

        x >>= 4;
        y >>= 4;
        z >>= 4;

        double tilt_x = atan2(x, sqrt(y * y + z * z)) * 180 / M_PI;
        double tilt_y = atan2(y, sqrt(x * x + z * z)) * 180 / M_PI;
        double tilt_z = atan2(z, sqrt(x * x + y * y)) * 180 / M_PI;

        if (fabs(tilt_x) > 45 || fabs(tilt_y) > 45 || fabs(tilt_z) > 45) {
            time_t now = time(NULL);
            char *timestamp = ctime(&now);
            timestamp[strcspn(timestamp, "\n")] = '\0';

            fprintf(log_file, "%s X: %d Y: %d Z: %d\n", timestamp, x, y, z);
            fflush(log_file);
        }

        usleep(10000); // 10 ms loop interval
    }

    fclose(log_file);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

