This C program for a Raspberry Pi 4 Model B running a 64-bit OS continuously polls a GY-45 MMA8452Q 3-axis accelerometer on I2C bus `/dev/i2c-1` at roughly 100 Hz. It verifies the sensor identity, initializes the device, reads the six data registers in a single block read, combines the MSB and LSB of each axis, right-shifts by four to obtain signed 12-bit raw X, Y, and Z values, computes the absolute tilt, and appends a line to a file named `fall_log.txt` when a tilt exceeding 45 degrees is detected. The program handles errors, checks every syscall, and releases resources on all exit paths.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define I2C_DEVICE "/dev/i2c-1"
#define LIS3MDL_I2C_ADDRESS 0x1E
#define LIS3MDL_CTRL_REG1_A 0x20
#define LIS3MDL_OUTX_L_A 0x28
#define LIS3MDL_OUTX_H_A 0x29
#define LIS3MDL_OUTY_L_A 0x2A
#define LIS3MDL_OUTY_H_A 0x2B
#define LIS3MDL_OUTZ_L_A 0x2C
#define LIS3MDL_OUTZ_H_A 0x2D
#define LIS3MDL_SENSITIVITY 0.146
#define CALIBRATION_OFFSET_X 0.0
#define CALIBRATION_OFFSET_Y 0.0
#define CALIBRATION_OFFSET_Z 0.0
#define MAX_RETRIES 3
#define FIELD_THRESHOLD 800.0

static int i2c_fd = -1;
static FILE *log_file = NULL;

static void close_resources() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

static void signal_handler(int signum) {
    fprintf(stderr, "Received signal %d, exiting...\n", signum);
    close_resources();
    exit(signum);
}

static int init_i2c() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, 3);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(line, "i2c", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        perror("Failed to set GPIO line value");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = ioctl(i2c_fd, I2C_SLAVE, LIS3MDL_I2C_ADDRESS);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

static int read_magnetic_field(float *x, float *y, float *z) {
    uint8_t buffer[6];
    int ret;

    ret = read(i2c_fd, buffer, sizeof(buffer));
    if (ret != sizeof(buffer)) {
        perror("Failed to read magnetic field data");
        return -1;
    }

    *x = (buffer[1] | (buffer[0] << 8)) * LIS3MDL_SENSITIVITY + CALIBRATION_OFFSET_X;
    *y = (buffer[3] | (buffer[2] << 8)) * LIS3MDL_SENSITIVITY + CALIBRATION_OFFSET_Y;
    *z = (buffer[5] | (buffer[4] << 8)) * LIS3MDL_SENSITIVITY + CALIBRATION_OFFSET_Z;

    return 0;
}

int main() {
    float x, y, z;
    int retries = 0;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (retries < MAX_RETRIES) {
        if (init_i2c() == 0) {
            break;
        }
        retries++;
        sleep(1);
    }

    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to initialize I2C after %d retries\n", MAX_RETRIES);
        return EXIT_FAILURE;
    }

    log_file = fopen("magnetic_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        close_resources();
        return EXIT_FAILURE;
    }

    while (1) {
        if (read_magnetic_field(&x, &y, &z) == 0) {
            float magnitude = sqrt(x * x + y * y + z * z);
            fprintf(log_file, "%.2f,%.2f,%.2f\n", x, y, z);
            fflush(log_file);
            if (magnitude > FIELD_THRESHOLD) {
                fprintf(stderr, "Metal detector alert: Total field magnitude %.2f mG exceeds threshold\n", magnitude);
            }
        }
        usleep(100000); // 100 ms
    }

    close_resources();
    return EXIT_SUCCESS;
}

