        fclose(log_file);
        log_file = NULL;
    }
}

static void signal_handler(int signum) {
    fprintf(stderr, "Received signal %d, exiting...\n", signum);
    close_resources();
    exit(signum);
}

static int init_i2c() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, 3);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(line, "i2c", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        perror("Failed to set GPIO line value");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = ioctl(i2c_fd, I2C_SLAVE, LIS3MDL_I2C_ADDRESS);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

static int read_magnetic_field(float *x, float *y, float *z) {
    uint8_t buffer[6];
    int ret;

    ret = read(i2c_fd, buffer, sizeof(buffer));
    if (ret != sizeof(buffer)) {
        perror("Failed to read magnetic field data");
        return -1;
    }

    *x = (buffer[1] | (buffer[0] << 8)) * LIS3MDL_SENSITIVITY + CALIBRATION_OFFSET_X;
    *y = (buffer[3] | (buffer[2] << 8)) * LIS3MDL_SENSITIVITY + CALIBRATION_OFFSET_Y;
    *z = (buffer[5] | (buffer[4] << 8)) * LIS3MDL_SENSITIVITY + CALIBRATION_OFFSET_Z;

    return 0;
}

int main() {
    float x, y, z;
    int retries = 0;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (retries < MAX_RETRIES) {
        if (init_i2c() == 0) {
            break;
        }
        retries++;
        sleep(1);
    }

    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to initialize I2C after %d retries\n", MAX_RETRIES);
        return EXIT_FAILURE;
    }

    log_file = fopen("magnetic_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        close_resources();
        return EXIT_FAILURE;
    }

    while (1) {
        if (read_magnetic_field(&x, &y, &z) == 0) {
            float magnitude = sqrt(x * x + y * y + z * z);
            fprintf(log_file, "%.2f,%.2f,%.2f\n", x, y, z);
            fflush(log_file);
            if (magnitude > FIELD_THRESHOLD) {
                fprintf(stderr, "Metal detector alert: Total field magnitude %.2f mG exceeds threshold\n", magnitude);
            }
        }
        usleep(100000); // 100 ms
    }

    close_resources();
    return EXIT_SUCCESS;
}
```

This code provides a complete solution for reading magnetic field data from an Adafruit LIS3MDL magnetometer over I2C on a Raspberry Pi 3 Model B+. It includes error handling, retries for sensor initialization, calibration, and signal handling for graceful shutdown. The magnetic field data is logged to a file and a metal detector alert is printed to stderr when the field magnitude exceeds the specified threshold.

