        free(dev);
        return NULL;
    }

    if (ioctl(dev->fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(dev->fd);
        gpiod_line_release(dev->ce0);
        gpiod_chip_close(dev->chip);
        free(dev);
        return NULL;
    }

    if (ioctl(dev->fd, SPI_IOC_WR_BITS_PER_WORD, (unsigned char *)8) < 0) {
        perror("Failed to set bits per word");
        close(dev->fd);
        gpiod_line_release(dev->ce0);
        gpiod_chip_close(dev->chip);
        free(dev);
        return NULL;
    }

    if (ioctl(dev->fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(dev->fd);
        gpiod_line_release(dev->ce0);
        gpiod_chip_close(dev->chip);
        free(dev);
        return NULL;
    }

    return dev;
}

void spi_close(struct spi_device *dev) {
    if (dev->fd >= 0) {
        close(dev->fd);
    }
    if (dev->ce0) {
        gpiod_line_release(dev->ce0);
    }
    if (dev->chip) {
        gpiod_chip_close(dev->chip);
    }
    free(dev);
}

int spi_transfer(struct spi_device *dev, uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    for (int i = 0; i < ADXL354B_RETRY_COUNT; i++) {
        if (ioctl(dev->fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
            perror("SPI transfer failed");
            return -1;
        }
        if (rx[0] != 0xFF) {
            return 0;
        }
    }
    return -1;
}

void reset_adxl354b(struct spi_device *dev) {
    uint8_t reset_val = 0x00;
    if (spi_transfer(dev, &reset_val, NULL, 1) < 0) {
        perror("Failed to reset ADXL354B");
    }
    usleep(1000);
    reset_val = 0x08;
    if (spi_transfer(dev, &reset_val, NULL, 1) < 0) {
        perror("Failed to reset ADXL354B");
    }
}

void power_down_adxl354b(struct spi_device *dev) {
    uint8_t power_ctl_val = 0x00;
    if (spi_transfer(dev, &power_ctl_val, NULL, 1) < 0) {
        perror("Failed to power down ADXL354B");
    }
}

