        return -1;
    }
    return 0;
}

void read_acceleration_data(struct spi_device *dev, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (spi_transfer(dev, (uint8_t *)&ADXL354B_XDATA_REG, buf, 6) < 0) {
