            perror("Failed to open log file");
            return;
        }
    }
    fprintf(log_file, "%ld.%06ld: X=%d, Y=%d, Z=%d\n", time(NULL), usec(), x, y, z);
    fflush(log_file);
}

void signal_handler(int sig) {
    spi_close(spi_dev);
    if (log_file) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    struct spi_device *spi_dev = spi_init("gpiochip0");
    if (!spi_dev) {
        return EXIT_FAILURE;
    }

    reset_adxl354b(spi_dev);
    power_down_adxl354b(spi_dev);
    if (verify_sensor_presence(spi_dev) < 0) {
        spi_close(spi_dev);
        return EXIT_FAILURE;
    }
    power_up_adxl354b(spi_dev);

    signal(SIGINT, signal_handler);
