        int16_t x, y, z;
        read_acceleration_data(spi_dev, &x, &y, &z);
        log_acceleration_data(x, y, z);
        usleep(ADXL354B_LOG_INTERVAL);
    }

    spi_close(spi_dev);
    return EXIT_SUCCESS;
}

