#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 8
#define SPI_SPEED 1000000
#define SPI_MODE 3
#define SPI_READ_ADDR 0x8000
#define SPI_READ_DUMMY 0x0000
#define SAMPLE_RATE 100
#define SAMPLE_INTERVAL 10000  // 10 ms in microseconds

struct spi_device {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int fd;
};

struct spi_device spi;

void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("Received SIGINT, shutting down gracefully...\n");
        if (spi.line) {
            gpiod_line_release(spi.line);
        }
        if (spi.chip) {
            gpiod_chip_close(spi.chip);
        }
        if (spi.fd >= 0) {
            close(spi.fd);
        }
        exit(0);
    }
}

int spi_init() {
    spi.chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!spi.chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    spi.line = gpiod_chip_get_line(spi.chip, GPIO_LINE);
    if (!spi.line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(spi.chip);
        return -1;
    }

    int ret = gpiod_line_request_output(spi.line, "spi_ce0", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(spi.chip);
        return -1;
    }

    spi.fd = open(SPI_DEVICE, O_RDWR);
    if (spi.fd < 0) {
        perror("Failed to open SPI device");
        gpiod_line_release(spi.line);
        gpiod_chip_close(spi.chip);
        return -1;
    }

    ret = ioctl(spi.fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        close(spi.fd);
        gpiod_line_release(spi.line);
        gpiod_chip_close(spi.chip);
        return -1;
    }

    ret = ioctl(spi.fd, SPI_IOC_WR_BITS_PER_WORD, (unsigned char)16);
    if (ret < 0) {
        perror("Failed to set bits per word");
        close(spi.fd);
        gpiod_line_release(spi.line);
        gpiod_chip_close(spi.chip);
        return -1;
    }

    ret = ioctl(spi.fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret < 0) {
        perror("Failed to set SPI speed");
        close(spi.fd);
        gpiod_line_release(spi.line);
        gpiod_chip_close(spi.chip);
        return -1;
    }

    return 0;
}

int spi_read(uint16_t *data) {
    uint16_t tx[2] = {SPI_READ_ADDR, SPI_READ_DUMMY};
    uint16_t rx[2];

    if (write(spi.fd, tx, sizeof(tx)) != sizeof(tx)) {
        perror("Failed to write to SPI device");
        return -1;
    }

    if (read(spi.fd, rx, sizeof(rx)) != sizeof(rx)) {
        perror("Failed to read from SPI device");
        return -1;
    }

    *data = rx[1];
    return 0;
}

int main() {
    FILE *log_file = fopen("imu_log.csv", "w");
    if (!log_file) {
        perror("Failed to open log file");
        return -1;
    }

    fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");

    if (spi_init() < 0) {
        fclose(log_file);
        return -1;
    }

    signal(SIGINT, signal_handler);

    struct timespec ts;
    while (1) {
        if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
            perror("Failed to get current time");
            continue;
        }

        uint16_t gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;

        if (spi_read(&gyro_x) < 0) {
            continue;
        }
        if (spi_read(&gyro_y) < 0) {
            continue;
        }
        if (spi_read(&gyro_z) < 0) {
            continue;
        }
        if (spi_read(&accel_x) < 0) {
            continue;
        }
        if (spi_read(&accel_y) < 0) {
            continue;
        }
        if (spi_read(&accel_z) < 0) {
            continue;
        }

        double gyro_x_scaled = gyro_x * 0.05;
        double gyro_y_scaled = gyro_y * 0.05;
        double gyro_z_scaled = gyro_z * 0.05;
        double accel_x_scaled = accel_x * 0.0025;
        double accel_y_scaled = accel_y * 0.0025;
