#include <string.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip4"
#define GPIO_LINE 17
#define POLL_INTERVAL 1

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static int running = 1;

void sigint_handler(int signum) {
    running = 0;
}

void log_message(const char *message) {
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline character
    printf("[%s] %s\n", timestamp, message);
}

int main() {
    struct gpiod_line_request_config config = {
        .consumer = "ir_sensor",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
    };

    // Install SIGINT handler
    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        perror("Failed to install SIGINT handler");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(line, &config) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_message("IR sensor initialized");

    while (running) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("Failed to read GPIO line value");
            break;
        }

        if (value == 0) {
            log_message("Self-parking sequence started");
            // Simulate self-parking sequence
            sleep(2);
            log_message("Self-parking sequence completed");
        }

        sleep(POLL_INTERVAL);
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    log_message("Program terminated");

    return EXIT_SUCCESS;
}

