#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE1 17
#define GPIO_LINE2 27
#define POLL_INTERVAL_MS 100

static struct gpiod_chip *chip;
static struct gpiod_line *line1;
static struct gpiod_line *line2;

void cleanup(int signum) {
    if (line1) {
        gpiod_line_release(line1);
    }
    if (line2) {
        gpiod_line_release(line2);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    printf("Cleanup complete.\n");
    exit(signum);
}

int main() {
    struct timespec ts;
    int ret;

    // Register signal handler for cleanup
    signal(SIGINT, cleanup);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request GPIO lines
    line1 = gpiod_chip_get_line(chip, GPIO_LINE1);
    if (!line1) {
        perror("Failed to get GPIO line 1");
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_LINE2);
    if (!line2) {
        perror("Failed to get GPIO line 2");
        goto cleanup;
    }

    // Configure GPIO lines as input
    ret = gpiod_line_request_input(line1, "ir_sensor_1");
    if (ret < 0) {
        perror("Failed to request input for GPIO line 1");
        goto cleanup;
    }

    ret = gpiod_line_request_input(line2, "ir_sensor_2");
    if (ret < 0) {
        perror("Failed to request input for GPIO line 2");
        goto cleanup;
    }

    while (1) {
        // Read both lines in a single bulk-read API call
        ret = gpiod_line_get_value_bulk(line1, line2, &ts);
        if (ret < 0) {
            perror("Failed to read GPIO lines");
            goto cleanup;
        }

        // Interpret the active-low output
        int sensor1_status = gpiod_line_get_value(line1);
        int sensor2_status = gpiod_line_get_value(line2);

        // Log the detection status with a timestamp
        printf("Timestamp: %ld.%09ld, Sensor 1: %d, Sensor 2: %d\n",
               ts.tv_sec, ts.tv_nsec, sensor1_status, sensor2_status);

        // Sleep for the specified interval
        usleep(POLL_INTERVAL_MS * 1000);
    }

cleanup:
    cleanup(0);
    return EXIT_FAILURE;
}

