#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_3
#define SPI_SPEED 1000000
#define SPI_BITS_PER_WORD 8
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 8
#define READ_INTERVAL 100000 // 100 ms in microseconds

struct spi_device {
    int fd;
    struct spi_ioc_transfer tr;
};

struct gpio_line {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
};

static volatile sig_atomic_t running = 1;

static void sigint_handler(int signum) {
    running = 0;
}

static int spi_open(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }
    return fd;
}

static int spi_setup(int fd) {
    struct spi_ioc_transfer tr = {0};
    struct spi_ioc_message msg = {0};

    tr.tx_buf = (unsigned long)malloc(3);
    tr.rx_buf = (unsigned long)malloc(3);
    tr.len = 3;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = SPI_BITS_PER_WORD;
    tr.delay_usecs = 0;
    tr.cs_change = 0;

    msg.msgs = &tr;
    msg.len = 1;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &msg) < 0) {
        perror("Failed to set SPI parameters");
        free((void *)tr.tx_buf);
        free((void *)tr.rx_buf);
        close(fd);
        return -1;
    }

    return fd;
}

static int gpio_open(const char *chip, int line) {
    struct gpiod_chip *chip_handle;
    struct gpiod_line *line_handle;

    chip_handle = gpiod_chip_open_by_name(chip);
    if (!chip_handle) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    line_handle = gpiod_chip_get_line(chip_handle, line);
    if (!line_handle) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip_handle);
        return -1;
    }

    return 0;
}

static void spi_close(int fd, struct spi_device *spi) {
    free((void *)spi->tr.tx_buf);
    free((void *)spi->tr.rx_buf);
    close(fd);
}

static void gpio_close(struct gpio_line *gpio) {
    gpiod_line_release(gpio->line);
    gpiod_chip_close(gpio->chip);
}

static int read_gyroscope(struct spi_device *spi) {
    uint8_t tx_buf[3] = {0x80, 0x00, 0x00};
    uint8_t rx_buf[3] = {0};

    spi->tr.tx_buf = (unsigned long)tx_buf;
    spi->tr.rx_buf = (unsigned long)rx_buf;

    if (ioctl(spi->fd, SPI_IOC_MESSAGE(1), &spi->tr) < 0) {
        perror("Failed to read from SPI device");
        return -1;
    }

    int16_t x = (rx_buf[1] << 8) | rx_buf[2];
    int16_t y = (rx_buf[1] << 8) | rx_buf[2];
    int16_t z = (rx_buf[1] << 8) | rx_buf[2];

    printf("X: %.2f deg/sec, Y: %.2f deg/sec, Z: %.2f deg/sec\n",
           x * 0.02, y * 0.02, z * 0.02);

    return 0;
}

int main() {
    struct spi_device spi = {0};
    struct gpio_line gpio = {0};
    int ret;

    signal(SIGINT, sigint_handler);

    spi.fd = spi_open(SPI_DEVICE);
    if (spi.fd < 0) {
        goto cleanup;
    }

    if (spi_setup(spi.fd) < 0) {
        goto cleanup;
    }

    if (gpio_open(GPIO_CHIP, GPIO_LINE) < 0) {
        goto cleanup;
    }

    while (running) {
        if (read_gyroscope(&spi) < 0) {
            goto cleanup;
        }
        usleep(READ_INTERVAL);
    }

cleanup:
    spi_close(spi.fd, &spi);
    gpio_close(&gpio);

    return 0;
}

