        // Read accelerometer data
        if (i2c_read_bytes(fd, LSM6DSR_OUTX_L_XL, accel, 6) < 0) {
            gpiod_chip_close(i2c_dev.chip);
            close(fd);
            return EXIT_FAILURE;
        }

        // Read gyroscope data
        if (i2c_read_bytes(fd, LSM6DSR_OUTX_L_G, gyro, 6) < 0) {
            gpiod_chip_close(i2c_dev.chip);
            close(fd);
            return EXIT_FAILURE;
        }

        // Print data
        printf("%d %d %d %d %d %d\n",
               (int16_t)((accel[1] << 8) | accel[0]),
               (int16_t)((accel[3] << 8) | accel[2]),
               (int16_t)((accel[5] << 8) | accel[4]),
               (int16_t)((gyro[1] << 8) | gyro[0]),
               (int16_t)((gyro[3] << 8) | gyro[2]),
               (int16_t)((gyro[5] << 8) | gyro[4]));

        // Sleep for 100ms
        usleep(100 * 1000);
    }

    // Cleanup
    gpiod_chip_close(i2c_dev.chip);
    close(fd);
    return EXIT_SUCCESS;
