#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1E
#define FXOS8700_CHIP_ID 0xC7
#define FXOS8700_CTRL_REG1 0x2A
#define FXOS8700_CTRL_REG2 0x2B
#define FXOS8700_M_CTRL_REG1 0x5B
#define FXOS8700_M_CTRL_REG2 0x5C
#define FXOS8700_STATUS 0x00
#define FXOS8700_OUT_X_MSB 0x01
#define FXOS8700_OUT_X_LSB 0x02
#define FXOS8700_OUT_Y_MSB 0x03
#define FXOS8700_OUT_Y_LSB 0x04
#define FXOS8700_OUT_Z_MSB 0x05
#define FXOS8700_OUT_Z_LSB 0x06
#define FXOS8700_OUT_X_MSB_M 0x07
#define FXOS8700_OUT_X_LSB_M 0x08
#define FXOS8700_OUT_Y_MSB_M 0x09
#define FXOS8700_OUT_Y_LSB_M 0x0A
#define FXOS8700_OUT_Z_MSB_M 0x0B
#define FXOS8700_OUT_Z_LSB_M 0x0C

struct i2c_device {
    struct gpiod_chip *chip;
    struct gpiod_line *sda;
    struct gpiod_line *scl;
    int fd;
};

static volatile sig_atomic_t stop_flag = 0;

static void signal_handler(int signum) {
    stop_flag = 1;
}

static int i2c_open(struct i2c_device *dev, const char *chip_name, int bus) {
    dev->chip = gpiod_chip_open_by_name(chip_name);
    if (!dev->chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    dev->sda = gpiod_chip_get_line(dev->chip, 2);
    if (!dev->sda) {
        perror("Failed to get SDA line");
        gpiod_chip_close(dev->chip);
        return -1;
    }

    dev->scl = gpiod_chip_get_line(dev->chip, 3);
    if (!dev->scl) {
        perror("Failed to get SCL line");
        gpiod_line_release(dev->sda);
        gpiod_chip_close(dev->chip);
        return -1;
    }

    dev->fd = open("/dev/i2c-1", O_RDWR);
    if (dev->fd < 0) {
        perror("Failed to open I2C bus");
        gpiod_line_release(dev->sda);
        gpiod_line_release(dev->scl);
        gpiod_chip_close(dev->chip);
        return -1;
    }

    if (ioctl(dev->fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(dev->fd);
        gpiod_line_release(dev->sda);
        gpiod_line_release(dev->scl);
        gpiod_chip_close(dev->chip);
        return -1;
    }

    return 0;
}

static void i2c_close(struct i2c_device *dev) {
    close(dev->fd);
    gpiod_line_release(dev->sda);
    gpiod_line_release(dev->scl);
    gpiod_chip_close(dev->chip);
}

static int i2c_read(struct i2c_device *dev, uint8_t reg, uint8_t *buf, size_t len) {
    uint8_t cmd[1] = {reg};
    if (write(dev->fd, cmd, 1) != 1) {
        perror("Failed to write I2C command");
        return -1;
    }

    if (read(dev->fd, buf, len) != len) {
        perror("Failed to read I2C data");
        return -1;
    }

    return 0;
}

static int fxos8700_init(struct i2c_device *dev) {
    uint8_t chip_id;
    if (i2c_read(dev, FXOS8700_CHIP_ID, &chip_id, 1) < 0) {
        return -1;
    }

    if (chip_id != FXOS8700_CHIP_ID) {
        fprintf(stderr, "FXOS8700 chip ID mismatch: 0x%02X\n", chip_id);
        return -1;
    }

    uint8_t ctrl_reg1 = 0x01; // Active, normal mode
    uint8_t ctrl_reg2 = 0x00; // Normal mode
    uint8_t m_ctrl_reg1 = 0x01; // Active, normal mode
    uint8_t m_ctrl_reg2 = 0x00; // Normal mode

    if (i2c_write(dev, FXOS8700_CTRL_REG1, &ctrl_reg1, 1) < 0) {
        return -1;
    }

    if (i2c_write(dev, FXOS8700_CTRL_REG2, &ctrl_reg2, 1) < 0) {
        return -1;
    }

    if (i2c_write(dev, FXOS8700_M_CTRL_REG1, &m_ctrl_reg1, 1) < 0) {
        return -1;
    }

    if (i2c_write(dev, FXOS8700_M_CTRL_REG2, &m_ctrl_reg2, 1) < 0) {
        return -1;
    }

    return 0;
}

static int fxos8700_read_data(struct i2c_device *dev, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *mag_x, int16_t *mag_y, int16_t *mag_z) {
    uint8_t data[12];
    if (i2c_read(dev, FXOS8700_OUT_X_MSB, data, 12) < 0) {
        return -1;
    }

    *accel_x = (data[1] << 8) | data[0];
    *accel_y = (data[3] << 8) | data[2];
    *accel_z = (data[5] << 8) | data[4];
    *mag_x = (data[7] << 8) | data[6];
    *mag_y = (data[9] << 8) | data[8];
    *mag_z = (data[11] << 8) | data[10];

    return 0;
}

int main() {
    struct i2c_device dev;
    if (i2c_open(&dev, "gpiochip0", I2C_BUS) < 0) {
        return EXIT_FAILURE;
    }

    if (fxos8700_init(&dev) < 0) {
        i2c_close(&dev);
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!stop_flag) {
        int16_t accel_x, accel_y, accel_z, mag_x, mag_y, mag_z;
        if (fxos8700_read_data(&dev, &accel_x, &accel_y, &accel_z, &mag_x, &mag_y, &mag_z) < 0) {
            fprintf(stderr, "Failed to read FXOS8700 data\n");
            continue;
        }

        printf("Accel: X=%d, Y=%d, Z=%d\n", accel_x, accel_y, accel_z);
        printf("Mag: X=%d, Y=%d, Z=%d\n", mag_x, mag_y, mag_z);

        usleep(100000); // 100 ms
    }

    i2c_close(&dev);
    return EXIT_SUCCESS;
}

