    if (i2c_write(dev, FXOS8700_CTRL_REG2, &ctrl_reg2, 1) < 0) {
        return -1;
    }

    if (i2c_write(dev, FXOS8700_M_CTRL_REG1, &m_ctrl_reg1, 1) < 0) {
        return -1;
    }

    if (i2c_write(dev, FXOS8700_M_CTRL_REG2, &m_ctrl_reg2, 1) < 0) {
        return -1;
    }

    return 0;
}

static int fxos8700_read_data(struct i2c_device *dev, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *mag_x, int16_t *mag_y, int16_t *mag_z) {
    uint8_t data[12];
    if (i2c_read(dev, FXOS8700_OUT_X_MSB, data, 12) < 0) {
        return -1;
    }

    *accel_x = (data[1] << 8) | data[0];
    *accel_y = (data[3] << 8) | data[2];
    *accel_z = (data[5] << 8) | data[4];
    *mag_x = (data[7] << 8) | data[6];
    *mag_y = (data[9] << 8) | data[8];
    *mag_z = (data[11] << 8) | data[10];

    return 0;
}

int main() {
    struct i2c_device dev;
    if (i2c_open(&dev, "gpiochip0", I2C_BUS) < 0) {
        return EXIT_FAILURE;
    }

    if (fxos8700_init(&dev) < 0) {
        i2c_close(&dev);
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!stop_flag) {
        int16_t accel_x, accel_y, accel_z, mag_x, mag_y, mag_z;
        if (fxos8700_read_data(&dev, &accel_x, &accel_y, &accel_z, &mag_x, &mag_y, &mag_z) < 0) {
            fprintf(stderr, "Failed to read FXOS8700 data\n");
            continue;
        }

        printf("Accel: X=%d, Y=%d, Z=%d\n", accel_x, accel_y, accel_z);
        printf("Mag: X=%d, Y=%d, Z=%d\n", mag_x, mag_y, mag_z);

        usleep(100000); // 100 ms
    }

    i2c_close(&dev);
    return EXIT_SUCCESS;
}
