#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define ADXL345_ADDRESS 0x53
#define TILT_THRESHOLD 30.0
#define SAMPLE_INTERVAL 100  // 100 ms

static struct gpiod_chip *chip;
static struct gpiod_line *log_line;
static int log_fd;

void log_tilt_event() {
    char timestamp[20];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    if (write(log_fd, timestamp, strlen(timestamp)) != strlen(timestamp)) {
        perror("Failed to write timestamp to log file");
    }
    if (write(log_fd, "\n", 1) != 1) {
        perror("Failed to write newline to log file");
    }
}

void handle_sigint(int sig) {
    if (log_fd != -1) {
        close(log_fd);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

int main() {
    struct i2c_msg msgs[2];
    struct i2c_rdwr_ioctl_data msgset;
    uint8_t buf[6];
    float x, y, z, tilt_angle;
    int ret;

    // Open I2C bus
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return EXIT_FAILURE;
    }

    // Initialize ADXL345
    uint8_t init_data[] = {0x2D, 0x08};  // Power control: Measure mode
    if (write(fd, init_data, sizeof(init_data)) != sizeof(init_data)) {
        perror("Failed to initialize ADXL345");
        close(fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_fd = open("/var/log/tilt_events.log", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        close(fd);
        return EXIT_FAILURE;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, handle_sigint);

    while (1) {
        // Read acceleration data
        msgs[0].addr = ADXL345_ADDRESS;
        msgs[0].flags = 0;
        msgs[0].len = 2;
        msgs[0].buf = (unsigned char *)buf;

        msgs[1].addr = ADXL345_ADDRESS;
        msgs[1].flags = I2C_M_RD;
        msgs[1].len = 4;
        msgs[1].buf = (unsigned char *)(buf + 2);

        msgset.nmsgs = 2;
        msgset.msgs = msgs;

        ret = ioctl(fd, I2C_RDWR, &msgset);
        if (ret < 0) {
            perror("Failed to read from ADXL345");
            continue;
        }

        // Convert raw data to g's
        x = (buf[2] | (buf[3] << 8)) / 256.0;
        y = (buf[4] | (buf[5] << 8)) / 256.0;
        z = 0.0;  // Z-axis is not used for tilt calculation

        // Calculate tilt angle
        tilt_angle = atan2(x, y) * 180.0 / M_PI;

        // Check for tilt
        if (fabs(tilt_angle) > TILT_THRESHOLD) {
            log_tilt_event();
        }

        // Sleep for 100 ms
        usleep(SAMPLE_INTERVAL * 1000);
    }

    // Clean up
    close(log_fd);
    close(fd);
    return EXIT_SUCCESS;
}

