#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define WINDOW_SIZE 5000
#define SAMPLE_INTERVAL 1

volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

void handle_sigterm(int sig) {
    running = 0;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return 1;
    }

    char *endptr;
    long threshold = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0' || threshold <= 0) {
        fprintf(stderr, "Error: Invalid threshold value\n");
        return 1;
    }

    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct timespec ts;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_input(line, "sound_sensor_monitor")) {
        perror("Failed to request GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    while (running) {
        int high_count = 0;
        for (int i = 0; i < WINDOW_SIZE; i++) {
            int value = gpiod_line_get_value(line);
            if (value < 0) {
                perror("Failed to read GPIO line");
                break;
            }
            if (value == 1) {
                high_count++;
            }
            nanosleep(&ts, NULL);
        }

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        if (high_count > threshold) {
            printf("%s: ALERT\n", timestamp);
        } else {
            printf("%s: %d high readings\n", timestamp, high_count);
        }

        sleep(1);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

