#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE_A 17
#define GPIO_LINE_B 27
#define CODE_LENGTH 6
#define LOG_FILE "access_log.txt"

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

void generate_code(char *code) {
    srand(time(NULL));
    snprintf(code, CODE_LENGTH + 1, "%06d", rand() % 900000 + 100000);
}

void log_access(const char *code) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d,%s\n",
            tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
            tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec, code);

    fclose(log_file);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line_a, *line_b;
    char code[CODE_LENGTH + 1];
    char input[CODE_LENGTH + 1];
    int ret;

    // Initialize signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Get GPIO lines
    line_a = gpiod_chip_get_line(chip, GPIO_LINE_A);
    if (!line_a) {
        perror("Failed to get GPIO line A");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line_b = gpiod_chip_get_line(chip, GPIO_LINE_B);
    if (!line_b) {
        perror("Failed to get GPIO line B");
        gpiod_line_release(line_a);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO lines as output
    ret = gpiod_line_request_output(line_a, "door_access", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line A as output");
        gpiod_line_release(line_b);
        gpiod_line_release(line_a);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line_b, "door_access", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line B as output");
        gpiod_line_release(line_a);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!stop_flag) {
        generate_code(code);
        printf("Security code: %s\n", code);

        while (1) {
            printf("Enter code: ");
            if (fgets(input, sizeof(input), stdin) == NULL) {
                perror("Failed to read input");
                continue;
            }

            if (strlen(input) < CODE_LENGTH + 1) {
                printf("Invalid input, please enter a six-digit code.\n");
                continue;
            }

            input[CODE_LENGTH] = '\0';
            if (strcmp(input, code) == 0) {
                printf("Access granted.\n");
                log_access(code);
                break;
            } else {
                printf("Access denied.\n");
            }
        }

        // Lock the doors
        gpiod_line_set_value(line_a, 0);
        gpiod_line_set_value(line_b, 0);
        sleep(5);
    }

    // Clean up
    gpiod_line_set_value(line_a, 0);
    gpiod_line_set_value(line_b, 0);
    gpiod_line_release(line_a);
    gpiod_line_release(line_b);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

