    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (pwm_fd >= 0) {
        close(pwm_fd);
    }
    if (tcp_fd >= 0) {
        close(tcp_fd);
    }
    if (signal(SIGINT, NULL) == SIG_ERR) {
        perror("Failed to reset SIGINT handler");
    }
    if (signal(SIGTERM, NULL) == SIG_ERR) {
        perror("Failed to reset SIGTERM handler");
    }
}

void handle_sigint(int sig) {
    cleanup();
    exit(0);
}

void handle_sigterm(int sig) {
    cleanup();
    exit(0);
}

int main() {
    struct sockaddr_in server_addr, client_addr;
    socklen_t client_len = sizeof(client_addr);
    char buffer[BUFFER_SIZE];
    FILE *log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, PWM_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "theremin", PWM_DUTY) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Initialize PWM
    pwm_fd = open("/dev/pwmchip0", O_WRONLY);
    if (pwm_fd < 0) {
        perror("Failed to open PWM device");
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (write(pwm_fd, "export 18", 10) < 0) {
        perror("Failed to export PWM pin");
        close(pwm_fd);
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (write(pwm_fd, "period 1000000", 15) < 0) {
        perror("Failed to set PWM period");
        close(pwm_fd);
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (write(pwm_fd, "duty_cycle 500000", 16) < 0) {
        perror("Failed to set PWM duty cycle");
        close(pwm_fd);
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Initialize TCP server
    tcp_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (tcp_fd < 0) {
        perror("Failed to create TCP socket");
        close(pwm_fd);
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(TCP_PORT);

    if (bind(tcp_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Failed to bind TCP socket");
        close(tcp_fd);
        close(pwm_fd);
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (listen(tcp_fd, 5) < 0) {
        perror("Failed to listen on TCP socket");
        close(tcp_fd);
        close(pwm_fd);
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Set up signal handlers
    if (signal(SIGINT, handle_sigint) == SIG_ERR) {
        perror("Failed to set SIGINT handler");
        close(tcp_fd);
        close(pwm_fd);
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (signal(SIGTERM, handle_sigterm) == SIG_ERR) {
        perror("Failed to set SIGTERM handler");
        close(tcp_fd);
        close(pwm_fd);
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    while (1) {
        int client_fd = accept(tcp_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd < 0) {
            perror("Failed to accept TCP connection");
            continue;
        }

        if (read(client_fd, buffer, BUFFER_SIZE) < 0) {
            perror("Failed to read from TCP connection");
            close(client_fd);
            continue;
        }

        if (strncmp(buffer, "MOTION_DETECTED:MySecretKey", 26) != 0) {
            close(client_fd);
            continue;
        }

        // Play PWM tone
        for (int i = 0; i < 500; i++) {
            int touch_value = gpiod_line_get_value(line);
            if (touch_value < 0) {
                perror("Failed to read touch value");
                close(client_fd);
                continue;
            }

            int frequency = 1000 + touch_value * 10; // Example frequency calculation
            if (write(pwm_fd, "duty_cycle ", 11) < 0) {
                perror("Failed to set PWM duty cycle");
                close(client_fd);
                continue;
            }

            char duty_cycle_str[12];
            snprintf(duty_cycle_str, sizeof(duty_cycle_str), "%d", frequency);
            if (write(pwm_fd, duty_cycle_str, strlen(duty_cycle_str)) < 0) {
                perror("Failed to set PWM duty cycle");
                close(client_fd);
                continue;
            }

            fprintf(log_file, "Frequency: %d Hz\n", frequency);
            fflush(log_file);

            usleep(20000); // 20 ms
        }

        close(client_fd);
    }

    cleanup();
    fclose(log_file);
    return EXIT_SUCCESS;
}
