    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize PWM
    if (gpiod_line_set_value(led_line, 0) < 0) {
        perror("Failed to set LED to off");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        int z_axis;
        if (read_magnetometer(&z_axis) == 0) {
            int brightness = (z_axis + 2000) * PWM_RANGE / 4000;  // Scale to 0-255
            if (brightness < 0) brightness = 0;
            if (brightness > PWM_RANGE) brightness = PWM_RANGE;
            if (gpiod_line_set_value(led_line, brightness) < 0) {
                perror("Failed to set LED brightness");
            }
        }
        usleep(SAMPLE_INTERVAL);
    }

    // Clean up
    gpiod_line_set_value(led_line, 0);
    gpiod_chip_close(chip);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

