#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define LSM303D_I2C_ADDR 0x19
#define LSM303D_WHO_AM_I 0x0F
#define LSM303D_CTRL_REG1_A 0x20
#define LSM303D_CTRL_REG4_A 0x23
#define LSM303D_OUT_X_L_A 0x28
#define LSM303D_INT1_CFG 0x30
#define LSM303D_INT1_SRC 0x31
#define LSM303D_INT1_THS 0x32
#define LSM303D_INT1_DURATION 0x33
#define LSM303D_SENSITIVITY 0.061
#define BUFFER_SIZE 64
#define SAMPLE_SIZE 6
#define INT1_PIN 23

struct circular_buffer {
    int head;
    int tail;
    int count;
    int buffer[BUFFER_SIZE][SAMPLE_SIZE];
};

struct circular_buffer cb;

void init_i2c(const char *chip_name, int *fd) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open_by_name(chip_name);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, INT1_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_input(line, "lsm303d_mon");
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line as input\n");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    *fd = gpiod_chip_get_fd(chip);
    if (*fd < 0) {
        fprintf(stderr, "Failed to get file descriptor for GPIO chip\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
}

void init_lsm303d(int fd) {
    uint8_t who_am_i;
    uint8_t ctrl_reg1 = 0x57; // 100 Hz, normal mode, all axes enabled
    uint8_t ctrl_reg4 = 0x88; // ±2g, 100 Hz, normal mode, all axes enabled
    uint8_t int1_cfg = 0x01; // INT1 on X high
    uint8_t int1_ths = 0x7D; // 2000 mg threshold
    uint8_t int1_duration = 0x00; // Immediate trigger

    if (read(fd, &who_am_i, 1) != 1 || who_am_i != 0x33) {
        fprintf(stderr, "Failed to verify LSM303D device identity\n");
        exit(EXIT_FAILURE);
    }

    if (write(fd, &ctrl_reg1, 1) != 1) {
        fprintf(stderr, "Failed to set LSM303D control register 1\n");
        exit(EXIT_FAILURE);
    }

    if (write(fd, &ctrl_reg4, 1) != 1) {
        fprintf(stderr, "Failed to set LSM303D control register 4\n");
        exit(EXIT_FAILURE);
    }

    if (write(fd, &int1_cfg, 1) != 1) {
        fprintf(stderr, "Failed to set LSM303D INT1 configuration\n");
        exit(EXIT_FAILURE);
    }

    if (write(fd, &int1_ths, 1) != 1) {
        fprintf(stderr, "Failed to set LSM303D INT1 threshold\n");
        exit(EXIT_FAILURE);
    }

    if (write(fd, &int1_duration, 1) != 1) {
        fprintf(stderr, "Failed to set LSM303D INT1 duration\n");
        exit(EXIT_FAILURE);
    }
}

void read_lsm303d(int fd) {
    uint8_t data[6];
    int16_t accel[3];
    int ret;

    ret = read(fd, data, sizeof(data));
    if (ret != sizeof(data)) {
        if (ret < 0) {
            perror("Failed to read from LSM303D");
        } else {
            fprintf(stderr, "Incomplete read from LSM303D\n");
        }
        return;
    }

    accel[0] = (data[1] << 8) | data[0];
    accel[1] = (data[3] << 8) | data[2];
    accel[2] = (data[5] << 8) | data[4];

    cb.buffer[cb.head][0] = accel[0] * LSM303D_SENSITIVITY;
    cb.buffer[cb.head][1] = accel[1] * LSM303D_SENSITIVITY;
    cb.buffer[cb.head][2] = accel[2] * LSM303D_SENSITIVITY;
    cb.buffer[cb.head][3] = time(NULL);
    cb.buffer[cb.head][4] = data[0];
    cb.buffer[cb.head][5] = data[1];

    cb.head = (cb.head + 1) % BUFFER_SIZE;
    if (cb.count < BUFFER_SIZE) {
        cb.count++;
    }
}

void dump_buffer() {
    time_t now = time(NULL);
    printf("Timestamp: %ld\n", now);
    for (int i = 0; i < 10; i++) {
        printf("Sample %d: %f, %f, %f\n", i, cb.buffer[(cb.tail + i) % BUFFER_SIZE][0],
               cb.buffer[(cb.tail + i) % BUFFER_SIZE][1],
               cb.buffer[(cb.tail + i) % BUFFER_SIZE][2]);
    }
}

void disable_lsm303d(int fd) {
    uint8_t ctrl_reg1 = 0x00; // Disable all axes
    if (write(fd, &ctrl_reg1, 1) != 1) {
        fprintf(stderr, "Failed to disable LSM303D\n");
    }
}

void signal_handler(int sig) {
    disable_lsm303d(cb.fd);
    close(cb.fd);
    exit(EXIT_SUCCESS);
}

int main() {
    int fd;
    struct sigaction sa;

    memset(&cb, 0, sizeof(cb));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to set signal handler");
        exit(EXIT_FAILURE);
    }

    init_i2c("gpiochip0", &fd);
    init_lsm303d(fd);

    while (1) {
        if (gpiod_line_get_value(cb.line) == 1) {
            dump_buffer();
        }
        read_lsm303d(fd);
        usleep(10000); // 10 ms
    }

    return 0;
}

