#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE1 17
#define GPIO_LINE2 27

static struct gpiod_chip *chip;
static struct gpiod_line *line1, *line2;

void cleanup(int signum) {
    if (gpiod_line_set_value(line1, 0) < 0) {
        perror("Failed to set GPIO17 LOW");
    }
    if (gpiod_line_set_value(line2, 0) < 0) {
        perror("Failed to set GPIO27 LOW");
    }
    if (line1) {
        gpiod_line_release(line1);
    }
    if (line2) {
        gpiod_line_release(line2);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(signum);
}

int main() {
    struct timespec delay = {0, 500000000}; // 500ms

    // Initialize GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request GPIO lines
    line1 = gpiod_chip_get_line(chip, GPIO_LINE1);
    if (!line1) {
        perror("Failed to get GPIO17 line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    line2 = gpiod_chip_get_line(chip, GPIO_LINE2);
    if (!line2) {
        perror("Failed to get GPIO27 line");
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set lines to output mode
    if (gpiod_line_request_output(line1, "solenoid1", 0) < 0) {
        perror("Failed to request GPIO17 as output");
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(line2, "solenoid2", 0) < 0) {
        perror("Failed to request GPIO27 as output");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set both lines LOW
    if (gpiod_line_set_value(line1, 0) < 0) {
        perror("Failed to set GPIO17 LOW");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_set_value(line2, 0) < 0) {
        perror("Failed to set GPIO27 LOW");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Install signal handler
    if (signal(SIGINT, cleanup) == SIG_ERR) {
        perror("Failed to install SIGINT handler");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, cleanup) == SIG_ERR) {
        perror("Failed to install SIGTERM handler");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        if (gpiod_line_set_value(line1, 1) < 0) {
            perror("Failed to set GPIO17 HIGH");
        }
        if (gpiod_line_set_value(line2, 0) < 0) {
            perror("Failed to set GPIO27 LOW");
        }
        if (nanosleep(&delay, NULL) < 0) {
            perror("Failed to sleep");
        }

        if (gpiod_line_set_value(line1, 0) < 0) {
            perror("Failed to set GPIO17 LOW");
        }
        if (gpiod_line_set_value(line2, 1) < 0) {
            perror("Failed to set GPIO27 HIGH");
        }
        if (nanosleep(&delay, NULL) < 0) {
            perror("Failed to sleep");
        }
    }

    return EXIT_SUCCESS;
}

