#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <libgpiod.h>

#define PIR_PIN "4"
#define RELAY_PIN "17"
#define POLL_INTERVAL 50
#define FAILSAFE_TIMEOUT 10
#define RELAY_DURATION 1

static struct gpiod_chip *chip;
static struct gpiod_line *pir_line, *relay_line;
static int running = 1;

void handle_signal(int sig) {
    running = 0;
}

void log_event(const char *message, int priority) {
    syslog(priority, "%s", message);
}

void activate_relay() {
    int ret = gpiod_line_set_value(relay_line, 1);
    if (ret < 0) {
        log_event("Failed to activate relay", LOG_ERR);
    } else {
        log_event("Relay activated", LOG_INFO);
    }
}

void deactivate_relay() {
    int ret = gpiod_line_set_value(relay_line, 0);
    if (ret < 0) {
        log_event("Failed to deactivate relay", LOG_ERR);
    } else {
        log_event("Relay deactivated", LOG_INFO);
    }
}

void failsafe() {
    deactivate_relay();
    log_event("Potential malfunction detected, triggering failsafe", LOG_WARNING);
    log_event("System shutdown initiated", LOG_WARNING);
    // Trigger system shutdown
    system("sudo shutdown -h now");
}

int main() {
    struct timespec poll_interval = {0, POLL_INTERVAL * 1000 * 1000};
    time_t last_motion_time = 0;
    int motion_detected = 0;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        log_event("Failed to open GPIO chip", LOG_ERR);
        return EXIT_FAILURE;
    }

    // Request the PIR and relay lines
    pir_line = gpiod_chip_get_line(chip, atoi(PIR_PIN));
    if (!pir_line) {
        log_event("Failed to get PIR line", LOG_ERR);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    relay_line = gpiod_chip_get_line(chip, atoi(RELAY_PIN));
    if (!relay_line) {
        log_event("Failed to get relay line", LOG_ERR);
        gpiod_line_release(pir_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure the PIR line as input
    int ret = gpiod_line_request_input(pir_line, "pir_sensor");
    if (ret < 0) {
        log_event("Failed to request PIR line as input", LOG_ERR);
        gpiod_line_release(pir_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure the relay line as output
    ret = gpiod_line_request_output(relay_line, "relay", 0);
    if (ret < 0) {
        log_event("Failed to request relay line as output", LOG_ERR);
        gpiod_line_release(pir_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the system log
    openlog("pir_sensor_monitor", LOG_PID | LOG_CONS, LOG_USER);

    while (running) {
        int value = gpiod_line_get_value(pir_line);
        if (value < 0) {
            log_event("Failed to read PIR line", LOG_ERR);
            continue;
        }

        if (value == 1) {
            if (!motion_detected) {
                log_event("Motion detected", LOG_INFO);
                motion_detected = 1;
                last_motion_time = time(NULL);
                activate_relay();
            } else {
                time_t current_time = time(NULL);
                if (current_time - last_motion_time > FAILSAFE_TIMEOUT) {
                    failsafe();
                    break;
                }
            }
        } else {
            if (motion_detected) {
                log_event("Motion ended", LOG_INFO);
                motion_detected = 0;
                deactivate_relay();
            }
        }

        nanosleep(&poll_interval, NULL);
    }

    // Clean up
    deactivate_relay();
    gpiod_line_release(pir_line);
    gpiod_line_release(relay_line);
    gpiod_chip_close(chip);
    closelog();

    return EXIT_SUCCESS;
}

