    {NULL, NULL, RELAY1_PIN},
    {NULL, NULL, RELAY2_PIN},
    {NULL, NULL, RELAY3_PIN},
    {NULL, NULL, RELAY4_PIN}
};

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

void init_relay(struct relay *relay, const char *chip_name) {
    relay->chip = gpiod_chip_open_by_name(chip_name);
    if (!relay->chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %s", chip_name);
        exit(EXIT_FAILURE);
    }

    relay->line = gpiod_chip_get_line(relay->chip, relay->pin);
    if (!relay->line) {
        syslog(LOG_ERR, "Failed to get line for pin %d", relay->pin);
        gpiod_chip_close(relay->chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(relay->line, "irrigation_system", RELAY_OFF) < 0) {
        syslog(LOG_ERR, "Failed to request output for pin %d", relay->pin);
        gpiod_line_release(relay->line);
        gpiod_chip_close(relay->chip);
        exit(EXIT_FAILURE);
    }
}

void deactivate_relay(struct relay *relay) {
    if (gpiod_line_set_value(relay->line, RELAY_OFF) < 0) {
        syslog(LOG_ERR, "Failed to deactivate relay on pin %d", relay->pin);
    }
}

void activate_relay(struct relay *relay) {
    if (gpiod_line_set_value(relay->line, RELAY_ON) < 0) {
        syslog(LOG_ERR, "Failed to activate relay on pin %d", relay->pin);
    }
}

void cleanup_relay(struct relay *relay) {
    deactivate_relay(relay);
    gpiod_line_release(relay->line);
    gpiod_chip_close(relay->chip);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to set SIGINT handler");
        exit(EXIT_FAILURE);
    }

    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to set SIGTERM handler");
        exit(EXIT_FAILURE);
    }

    openlog("irrigation_system", LOG_PID, LOG_USER);

    for (int i = 0; i < 4; i++) {
        init_relay(&relays[i], "gpiochip0");
    }

    int current_relay = 0;
    while (!stop_flag) {
        activate_relay(&relays[current_relay]);
        syslog(LOG_INFO, "Activating relay %d", current_relay + 1);
        sleep(CYCLE_TIME);

        deactivate_relay(&relays[current_relay]);
        syslog(LOG_INFO, "Deactivating relay %d", current_relay + 1);
        sleep(PAUSE_TIME);

        current_relay = (current_relay + 1) % 4;
    }

    for (int i = 0; i < 4; i++) {
        cleanup_relay(&relays[i]);
    }

    closelog();
    return 0;
}
