#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <libgpiod.h>

#define I2C_DEVICE "/dev/i2c-1"
#define MPU6050_ADDRESS 0x68
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_ACCEL_YOUT_H 0x3D
#define MPU6050_ACCEL_ZOUT_H 0x3F
#define BUFFER_SIZE 100
#define SAMPLE_RATE 100

struct AccelerationData {
    int16_t x;
    int16_t y;
    int16_t z;
};

struct AccelerationBuffer {
    struct AccelerationData buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
};

struct AccelerationBuffer accel_buffer;
int i2c_fd;
struct gpiod_chip *chip;
struct gpiod_line *line;

void i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t data[2] = {reg, value};
    if (write(fd, data, 2) != 2) {
        perror("Failed to write to I2C device");
        exit(EXIT_FAILURE);
    }
}

uint8_t i2c_read_byte(int fd, uint8_t reg) {
    uint8_t data[1] = {reg};
    if (write(fd, data, 1) != 1) {
        perror("Failed to write to I2C device");
        exit(EXIT_FAILURE);
    }
    if (read(fd, data, 1) != 1) {
        perror("Failed to read from I2C device");
        exit(EXIT_FAILURE);
    }
    return data[0];
}

void read_acceleration_data(struct AccelerationData *data) {
    uint8_t xh = i2c_read_byte(i2c_fd, MPU6050_ACCEL_XOUT_H);
    uint8_t xl = i2c_read_byte(i2c_fd, MPU6050_ACCEL_XOUT_L);
    uint8_t yh = i2c_read_byte(i2c_fd, MPU6050_ACCEL_YOUT_H);
    uint8_t yl = i2c_read_byte(i2c_fd, MPU6050_ACCEL_YOUT_L);
    uint8_t zh = i2c_read_byte(i2c_fd, MPU6050_ACCEL_ZOUT_H);
    uint8_t zl = i2c_read_byte(i2c_fd, MPU6050_ACCEL_ZOUT_L);

    data->x = (int16_t)((xh << 8) | xl);
    data->y = (int16_t)((yh << 8) | yl);
    data->z = (int16_t)((zh << 8) | zl);
}

void timer_handler(int signum) {
    static struct AccelerationData data;
    read_acceleration_data(&data);

    if (accel_buffer.count < BUFFER_SIZE) {
        accel_buffer.buffer[accel_buffer.head] = data;
        accel_buffer.head = (accel_buffer.head + 1) % BUFFER_SIZE;
        accel_buffer.count++;
    } else {
        accel_buffer.tail = (accel_buffer.tail + 1) % BUFFER_SIZE;
        accel_buffer.buffer[accel_buffer.head] = data;
        accel_buffer.head = (accel_buffer.head + 1) % BUFFER_SIZE;
    }
}

void cleanup() {
    if (accel_buffer.count > 0) {
        struct AccelerationData latest = accel_buffer.buffer[accel_buffer.tail];
        FILE *file = fopen("/sys/kernel/mpu6050_accel/latest", "w");
        if (file) {
            fprintf(file, "%d %d %d\n", latest.x, latest.y, latest.z);
            fclose(file);
        }
    }

    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    if (chip) {
        gpiod_chip_close(chip);
    }

    if (line) {
        gpiod_line_release(line);
    }

    exit(EXIT_SUCCESS);
}

int main() {
    struct sigaction sa;
    struct itimerval timer;

    // Initialize I2C
    if ((i2c_fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Initialize MPU6050
    i2c_write_byte(i2c_fd, 0x6B, 0x00); // Wake up

    // Initialize GPIO for signal handling
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, 17); // Example GPIO line for signal handling
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(line, "accel_timer", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Set up signal handler
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = &cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set SIGINT handler");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set SIGTERM handler");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Set up timer
    memset(&timer, 0, sizeof(timer));
    timer.it_value.tv_sec = 0;
    timer.it_value.tv_usec = 1000000 / SAMPLE_RATE;
    timer.it_interval.tv_sec = 0;
    timer.it_interval.tv_usec = 1000000 / SAMPLE_RATE;

    if (setitimer(ITIMER_REAL, &timer, NULL) < 0) {
        perror("Failed to set timer");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        pause();
    }

    return 0;
}

