This code provides a complete implementation of a Raspberry Pi program that samples acceleration data from an MPU6050 sensor on the I2C bus, stores the data in a circular buffer, and makes the most recent sample available through a driver library interface. The program uses the `libgpiod` library for GPIO operations and handles signals to clean up resources on exit.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define RELAY1_PIN 18
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

#define INTERVAL1 2
#define INTERVAL2 3
#define INTERVAL3 5
#define INTERVAL4 7

static struct gpiod_chip *chip;
static struct gpiod_line *line1, *line2, *line3, *line4;

void cleanup_and_exit(int status) {
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (line3) gpiod_line_release(line3);
    if (line4) gpiod_line_release(line4);
    if (chip) gpiod_chip_close(chip);
    exit(status);
}

void handle_signal(int signum) {
    cleanup_and_exit(EXIT_FAILURE);
}

int main() {
    struct timespec now, next1, next2, next3, next4;
    int ret;

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        cleanup_and_exit(EXIT_FAILURE);
    }

    // Request GPIO lines
    line1 = gpiod_chip_get_line(chip, RELAY1_PIN);
    if (!line1) {
        perror("Failed to get GPIO line 1");
        cleanup_and_exit(EXIT_FAILURE);
    }

    line2 = gpiod_chip_get_line(chip, RELAY2_PIN);
    if (!line2) {
        perror("Failed to get GPIO line 2");
        cleanup_and_exit(EXIT_FAILURE);
    }

    line3 = gpiod_chip_get_line(chip, RELAY3_PIN);
    if (!line3) {
        perror("Failed to get GPIO line 3");
        cleanup_and_exit(EXIT_FAILURE);
    }

    line4 = gpiod_chip_get_line(chip, RELAY4_PIN);
    if (!line4) {
        perror("Failed to get GPIO line 4");
        cleanup_and_exit(EXIT_FAILURE);
    }

    // Configure lines as output
    ret = gpiod_line_request_output(line1, "relay1", 0);
    if (ret < 0) {
        perror("Failed to request output for GPIO line 1");
        cleanup_and_exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(line2, "relay2", 0);
    if (ret < 0) {
        perror("Failed to request output for GPIO line 2");
        cleanup_and_exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(line3, "relay3", 0);
    if (ret < 0) {
        perror("Failed to request output for GPIO line 3");
        cleanup_and_exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(line4, "relay4", 0);
    if (ret < 0) {
        perror("Failed to request output for GPIO line 4");
        cleanup_and_exit(EXIT_FAILURE);
    }

    // Initialize next toggle times
    clock_gettime(CLOCK_MONOTONIC, &now);
    next1.tv_sec = now.tv_sec + INTERVAL1;
    next2.tv_sec = now.tv_sec + INTERVAL2;
    next3.tv_sec = now.tv_sec + INTERVAL3;
    next4.tv_sec = now.tv_sec + INTERVAL4;

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &now);

        if (now.tv_sec >= next1.tv_sec) {
            gpiod_line_set_value(line1, !gpiod_line_get_value(line1));
            next1.tv_sec += INTERVAL1;
        }

        if (now.tv_sec >= next2.tv_sec) {
            gpiod_line_set_value(line2, !gpiod_line_get_value(line2));
            next2.tv_sec += INTERVAL2;
        }

        if (now.tv_sec >= next3.tv_sec) {
            gpiod_line_set_value(line3, !gpiod_line_get_value(line3));
            next3.tv_sec += INTERVAL3;
        }

        if (now.tv_sec >= next4.tv_sec) {
            gpiod_line_set_value(line4, !gpiod_line_get_value(line4));
            next4.tv_sec += INTERVAL4;
        }

        // Sleep for a short period to reduce CPU usage
        usleep(100000);
    }

    cleanup_and_exit(EXIT_SUCCESS);
}

