#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_OUT 17
#define GPIO_RELAY 27
#define POLL_INTERVAL 100
#define RELAY_DURATION 3

static struct gpiod_chip *chip;
static struct gpiod_line *out_line;
static struct gpiod_line *relay_line;
static FILE *log_file;

static void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        if (relay_line) {
            gpiod_line_set_value(relay_line, 0);
        }
        if (chip) {
            gpiod_chip_close(chip);
        }
        if (log_file) {
            fclose(log_file);
        }
        exit(EXIT_SUCCESS);
    }
}

static int init_gpio() {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    out_line = gpiod_chip_get_line(chip, GPIO_OUT);
    if (!out_line) {
        perror("Failed to get GPIO_OUT line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_input(out_line, "sound_sensor") < 0) {
        perror("Failed to request GPIO_OUT line as input");
        gpiod_line_release(out_line);
        gpiod_chip_close(chip);
        return -1;
    }

    relay_line = gpiod_chip_get_line(chip, GPIO_RELAY);
    if (!relay_line) {
        perror("Failed to get GPIO_RELAY line");
        gpiod_line_release(out_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(relay_line, "relay", 0) < 0) {
        perror("Failed to request GPIO_RELAY line as output");
        gpiod_line_release(out_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

static void log_event() {
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline character

    if (log_file) {
        fprintf(log_file, "%s\n", timestamp);
        fflush(log_file);
    }
}

int main() {
    if (signal(SIGINT, handle_signal) == SIG_ERR) {
        perror("Failed to set SIGINT handler");
        return EXIT_FAILURE;
    }

    if (signal(SIGTERM, handle_signal) == SIG_ERR) {
        perror("Failed to set SIGTERM handler");
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen("alarm_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(out_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int last_state = 0;
    int current_state = 0;

    while (1) {
        current_state = gpiod_line_get_value(out_line);
        if (current_state && !last_state) {
            log_event();
            gpiod_line_set_value(relay_line, 1);
            usleep(RELAY_DURATION * 1000000);
            gpiod_line_set_value(relay_line, 0);
        }
        last_state = current_state;
        usleep(POLL_INTERVAL * 1000);
    }

    fclose(log_file);
    gpiod_line_release(out_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

