#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>

#define I2C_DEVICE "/dev/i2c-1"
#define MPU6050_ADDRESS 0x68
#define MPU6050_GYRO_CONFIG 0x1B
#define MPU6050_GYRO_XOUT_H 0x43
#define BUFFER_SIZE 100

typedef struct {
    int16_t x, y, z;
} GyroData;

typedef struct {
    GyroData buffer[BUFFER_SIZE];
    int head, tail;
} CircularBuffer;

CircularBuffer gyroBuffer;
int i2cFd = -1;
volatile sig_atomic_t running = 1;

void signalHandler(int signum) {
    running = 0;
}

void initI2C() {
    i2cFd = open(I2C_DEVICE, O_RDWR);
    if (i2cFd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2cFd, I2C_SLAVE, MPU6050_ADDRESS) < 0) {
        perror("Failed to select MPU6050 I2C address");
        close(i2cFd);
        exit(EXIT_FAILURE);
    }

    uint8_t gyroConfig = 0x10; // Set to +/- 2000 degrees/s
    if (write(i2cFd, &gyroConfig, sizeof(gyroConfig)) != sizeof(gyroConfig)) {
        perror("Failed to write to MPU6050");
        close(i2cFd);
        exit(EXIT_FAILURE);
    }
}

void readGyroData(GyroData *data) {
    uint8_t buffer[6];
    if (read(i2cFd, buffer, sizeof(buffer)) != sizeof(buffer)) {
        perror("Failed to read from MPU6050");
        exit(EXIT_FAILURE);
    }

    data->x = (int16_t)(buffer[0] << 8 | buffer[1]);
    data->y = (int16_t)(buffer[2] << 8 | buffer[3]);
    data->z = (int16_t)(buffer[4] << 8 | buffer[5]);
}

void addToBuffer(GyroData data) {
    gyroBuffer.buffer[gyroBuffer.head] = data;
    gyroBuffer.head = (gyroBuffer.head + 1) % BUFFER_SIZE;
    if (gyroBuffer.head == gyroBuffer.tail) {
        gyroBuffer.tail = (gyroBuffer.tail + 1) % BUFFER_SIZE;
    }
}

void checkGyroData() {
    GyroData data;
    readGyroData(&data);
    double magnitude = sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
    if (magnitude > 50.0) {
        printf("High angular velocity detected: %.2f degrees/second\n", magnitude);
    }
    addToBuffer(data);
}

void cleanup() {
    if (i2cFd >= 0) {
        close(i2cFd);
    }
}

int main() {
    signal(SIGINT, signalHandler);

    initI2C();

    gyroBuffer.head = 0;
    gyroBuffer.tail = 0;

    while (running) {
        checkGyroData();
        usleep(10000); // 10 ms delay
    }

    cleanup();
    return 0;
}

