#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <libgpiod/error.h>

#define UART_DEVICE "/dev/serial0"
#define UART_BAUDRATE 9600
#define UART_TXD_PIN 14
#define UART_RXD_PIN 15
#define CO2_LOG_FILE "co2_log.json"
#define CO2_ERROR_LOG_FILE "co2_error.log"
#define COMMAND_SEQUENCE "\xFF\x01\x86\x00\x00\x00\x00\x00\x79"
#define RESPONSE_SIZE 9
#define TIMEOUT_SEC 1
#define SAMPLE_INTERVAL_SEC 5

static struct gpiod_chip *chip;
static struct gpiod_line *txd_line;
static struct gpiod_line *rxd_line;
static FILE *co2_log;
static FILE *co2_error_log;

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        if (co2_log) fclose(co2_log);
        if (co2_error_log) fclose(co2_error_log);
        if (txd_line) gpiod_line_release(txd_line);
        if (rxd_line) gpiod_line_release(rxd_line);
        if (chip) gpiod_chip_close(chip);
        exit(0);
    }
}

int read_co2_sensor() {
    uint8_t command[9] = COMMAND_SEQUENCE;
    uint8_t response[RESPONSE_SIZE];
    ssize_t bytes_read;
    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);

    if (gpiod_line_set_value(txd_line, 0) < 0) {
        perror("Failed to set TXD line to 0");
        return -1;
    }

    if (write(gpiod_line_get_fd(txd_line), command, sizeof(command)) != sizeof(command)) {
        perror("Failed to send command to sensor");
        return -1;
    }

    if (gpiod_line_set_value(txd_line, 1) < 0) {
        perror("Failed to set TXD line to 1");
        return -1;
    }

    clock_gettime(CLOCK_MONOTONIC, &end);
    if (end.tv_sec - start.tv_sec > TIMEOUT_SEC) {
        fprintf(stderr, "Timeout waiting for sensor response\n");
        return -1;
    }

    bytes_read = read(gpiod_line_get_fd(rxd_line), response, sizeof(response));
    if (bytes_read != sizeof(response)) {
        fprintf(stderr, "Failed to read response from sensor, read %zd bytes\n", bytes_read);
        return -1;
    }

    uint16_t ppm = (response[2] << 8) | response[3];
    uint8_t checksum = response[0] + response[1] + response[2] + response[3] + response[4] + response[5] + response[6];
    if (checksum != response[7]) {
        fprintf(stderr, "Checksum mismatch, expected 0x%02X, got 0x%02X\n", checksum, response[7]);
        return -1;
    }

    return ppm;
}

void log_co2_reading(uint64_t timestamp, uint16_t ppm) {
    fprintf(co2_log, "{\"timestamp\": %llu, \"ppm\": %u, \"error\": 0}\n", timestamp, ppm);
    fflush(co2_log);
    printf("{\"timestamp\": %llu, \"ppm\": %u, \"error\": 0}\n", timestamp, ppm);
}

void log_error(const char *message) {
    fprintf(co2_error_log, "%s\n", message);
    fflush(co2_error_log);
}

int main() {
    struct timespec now;
    uint64_t timestamp;
    int ppm;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    txd_line = gpiod_chip_get_line(chip, UART_TXD_PIN);
    if (!txd_line) {
        perror("Failed to get TXD line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(txd_line, "co2_monitor_tx", 0) < 0) {
        perror("Failed to request TXD line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    rxd_line = gpiod_chip_get_line(chip, UART_RXD_PIN);
    if (!rxd_line) {
        perror("Failed to get RXD line");
        gpiod_line_release(txd_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(rxd_line, "co2_monitor_rx") < 0) {
        perror("Failed to request RXD line");
        gpiod_line_release(txd_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    co2_log = fopen(CO2_LOG_FILE, "a");
    if (!co2_log) {
        perror("Failed to open CO2 log file");
        gpiod_line_release(txd_line);
        gpiod_line_release(rxd_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    co2_error_log = fopen(CO2_ERROR_LOG_FILE, "a");
    if (!co2_error_log) {
        perror("Failed to open CO2 error log file");
        fclose(co2_log);
        gpiod_line_release(txd_line);
        gpiod_line_release(rxd_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &now);
        timestamp = (now.tv_sec * 1000000ULL) + (now.tv_nsec / 1000ULL);

        ppm = read_co2_sensor();
        if (ppm >= 0) {
            log_co2_reading(timestamp, ppm);
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    return EXIT_SUCCESS;
}

