#define HMC5883L_SCALE_1_9 0x20
#define HMC5883L_SCALE_2_5 0x40
#define HMC5883L_SCALE_4_0 0x60
#define HMC5883L_SCALE_4_7 0x80
#define HMC5883L_SCALE_5_6 0xA0
#define HMC5883L_SCALE_8_1 0xC0
#define HMC5883L_SCALE_12_2 0xE0
#define HMC5883L_GPIO17 "gpiochip0"
