}

int read_hmc5883l_heading() {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(fd);
        return -1;
    }

    uint8_t config_a = HMC5883L_SCALE_1_3 | HMC5883L_MODE_CONTINUOUS;
    if (write(fd, &config_a, 1) != 1) {
        perror("Failed to write config A");
        close(fd);
        return -1;
    }

    uint8_t config_b = HMC5883L_MODE_NORMAL;
    if (write(fd, &config_b, 1) != 1) {
        perror("Failed to write config B");
        close(fd);
        return -1;
    }

    uint8_t mode = HMC5883L_MODE_NORMAL;
    if (write(fd, &mode, 1) != 1) {
        perror("Failed to write mode");
        close(fd);
        return -1;
    }

    uint8_t data[6];
    if (read(fd, data, 6) != 6) {
        perror("Failed to read data");
        close(fd);
        return -1;
    }

    close(fd);

    int16_t x = (data[0] << 8) | data[1];
    int16_t y = (data[2] << 8) | data[3];
    int16_t z = (data[4] << 8) | data[5];

    double heading = atan2(y, x) * 180.0 / M_PI;
    if (heading < 0) {
        heading += 360.0;
    }

    return (int)heading;
}

void add_to_buffer(int heading) {
    buffer[buffer_index] = heading;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_index == 0) {
        buffer_full = 1;
    }
}

double calculate_average_heading() {
    int sum = 0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += buffer[i];
    }
    return (double)sum / BUFFER_SIZE;
}

int main() {
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    chip = gpiod_chip_open_by_name(HMC5883L_GPIO17);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    line = gpiod_chip_get_line(chip, HMC5883L_GPIO17_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(line, "heading_indicator", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        return 1;
    }

    while (1) {
        int heading = read_hmc5883l_heading();
        if (heading >= 0) {
            add_to_buffer(heading);
            double average_heading = calculate_average_heading();
            int deviation = (int)fabs(average_heading - TARGET_HEADING);
            if (deviation > DEVIATION_THRESHOLD) {
                gpiod_line_set_value(line, 1);
            } else {
                gpiod_line_set_value(line, 0);
            }
        }

        usleep(SAMPLE_INTERVAL);
    }

    cleanup();
    return 0;
}

