#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <gpiod.h>

#define I2C_BUS 1
#define BH1750_ADDRESS 0x23
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define RED_RELAY_PIN 17
#define GREEN_RELAY_PIN 27
#define BLUE_RELAY_PIN 22
#define LOG_FILE "lighting_log.txt"

static struct gpiod_chip *chip;
static struct gpiod_line *red_line, *green_line, *blue_line;
static int i2c_fd;

void cleanup() {
    if (red_line) gpiod_line_release(red_line);
    if (green_line) gpiod_line_release(green_line);
    if (blue_line) gpiod_line_release(blue_line);
    if (chip) gpiod_chip_close(chip);
    if (i2c_fd >= 0) close(i2c_fd);
    if (unlink(LOG_FILE) != 0) perror("unlink");
}

void signal_handler(int sig) {
    cleanup();
    exit(EXIT_FAILURE);
}

int main() {
    struct timespec ts;
    struct tm *tm_info;
    char timestamp[20];
    uint16_t lux;
    int ret;

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Request GPIO lines
    red_line = gpiod_chip_get_line(chip, RED_RELAY_PIN);
    if (!red_line) {
        perror("Failed to get RED relay line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    green_line = gpiod_chip_get_line(chip, GREEN_RELAY_PIN);
    if (!green_line) {
        perror("Failed to get GREEN relay line");
        gpiod_line_release(red_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    blue_line = gpiod_chip_get_line(chip, BLUE_RELAY_PIN);
    if (!blue_line) {
        perror("Failed to get BLUE relay line");
        gpiod_line_release(red_line);
        gpiod_line_release(green_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Set GPIO lines as output
    ret = gpiod_line_request_output(red_line, "red_relay", 0);
    if (ret < 0) {
        perror("Failed to request RED relay line as output");
        gpiod_line_release(red_line);
        gpiod_line_release(green_line);
        gpiod_line_release(blue_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(green_line, "green_relay", 0);
    if (ret < 0) {
        perror("Failed to request GREEN relay line as output");
        gpiod_line_release(red_line);
        gpiod_line_release(green_line);
        gpiod_line_release(blue_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(blue_line, "blue_relay", 0);
    if (ret < 0) {
        perror("Failed to request BLUE relay line as output");
        gpiod_line_release(red_line);
        gpiod_line_release(green_line);
        gpiod_line_release(blue_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(red_line);
        gpiod_line_release(green_line);
        gpiod_line_release(blue_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Start continuous measurement
    if (write(i2c_fd, &BH1750_CONTINUOUS_HIGH_RES_MODE, 1) != 1) {
        perror("Failed to start continuous measurement");
        fclose(log_file);
        gpiod_line_release(red_line);
        gpiod_line_release(green_line);
        gpiod_line_release(blue_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        // Wait for measurement to complete
        usleep(120000);

        // Read lux value
        if (read(i2c_fd, &lux, 2) != 2) {
            perror("Failed to read lux value");
            continue;
        }

        lux = (lux >> 8) | (lux << 8); // Swap bytes

        // Determine relay states
        int red_state = lux < 50;
        int green_state = lux >= 50 && lux <= 150;
        int blue_state = lux > 150 && lux <= 300;

        // Set relay states
        gpiod_line_set_value(red_line, red_state);
        gpiod_line_set_value(green_line, green_state);
        gpiod_line_set_value(blue_line, blue_state);

        // Get current timestamp
        clock_gettime(CLOCK_REALTIME, &ts);
        tm_info = localtime(&ts.tv_sec);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        // Log data
        fprintf(log_file, "%s, %u, %d, %d, %d\n", timestamp, lux, red_state, green_state, blue_state);
        fflush(log_file);
    }

    // Clean up
    fclose(log_file);
    cleanup();

    return EXIT_SUCCESS;
}

