        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(red_line);
        gpiod_line_release(green_line);
        gpiod_line_release(blue_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Start continuous measurement
    if (write(i2c_fd, &BH1750_CONTINUOUS_HIGH_RES_MODE, 1) != 1) {
        perror("Failed to start continuous measurement");
        fclose(log_file);
        gpiod_line_release(red_line);
        gpiod_line_release(green_line);
        gpiod_line_release(blue_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        // Wait for measurement to complete
        usleep(120000);

        // Read lux value
        if (read(i2c_fd, &lux, 2) != 2) {
            perror("Failed to read lux value");
            continue;
        }

        lux = (lux >> 8) | (lux << 8); // Swap bytes

        // Determine relay states
        int red_state = lux < 50;
        int green_state = lux >= 50 && lux <= 150;
        int blue_state = lux > 150 && lux <= 300;

        // Set relay states
        gpiod_line_set_value(red_line, red_state);
        gpiod_line_set_value(green_line, green_state);
        gpiod_line_set_value(blue_line, blue_state);

        // Get current timestamp
        clock_gettime(CLOCK_REALTIME, &ts);
        tm_info = localtime(&ts.tv_sec);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        // Log data
        fprintf(log_file, "%s, %u, %d, %d, %d\n", timestamp, lux, red_state, green_state, blue_state);
        fflush(log_file);
    }

    // Clean up
    fclose(log_file);
    cleanup();

    return EXIT_SUCCESS;
}
