        gpiod_line_request_output(motor_a_in2, "motor_a_in2", 0) < 0 ||
        gpiod_line_request_output(motor_b_in3, "motor_b_in3", 0) < 0 ||
        gpiod_line_request_output(motor_b_in4, "motor_b_in4", 0) < 0 ||
        gpiod_line_request_output(motor_a_pwm, "motor_a_pwm", 0) < 0 ||
        gpiod_line_request_output(motor_b_pwm, "motor_b_pwm", 0) < 0) {
        perror("Failed to request GPIO lines");
        gpiod_chip_close(chip);
        return 1;
    }

