        perror("Failed to set PWM duty cycle to 0");
        gpiod_chip_close(chip);
        return 1;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        int speed_a = (distance_a < 50) ? (distance_a * MAX_SPEED / 50) : (MAX_SPEED - (distance_a - 50) * MAX_SPEED / 50);
        int speed_b = (distance_b < 50) ? (distance_b * MAX_SPEED / 50) : (MAX_SPEED - (distance_b - 50) * MAX_SPEED / 50);

        if (set_motor_direction(motor_a_in1, motor_a_in2, 1) < 0 || set_motor_direction(motor_b_in3, motor_b_in4, 1) < 0 ||
            set_pwm_duty(motor_a_pwm, speed_a) < 0 || set_pwm_duty(motor_b_pwm, speed_b) < 0) {
            cleanup(1);
        }

        usleep(CONTROL_LOOP_INTERVAL * 1000);
    }

    cleanup(0);
    return 0;
}

