#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define STEPPER_PINS {17, 18, 27, 22}
#define LOCK_BUTTON 24
#define UNLOCK_BUTTON 23
#define STEPS_PER_REV 512
#define STEP_DELAY 2000

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

void init_gpio(struct gpiod_chip *chip, int *pins, int num_pins) {
    for (int i = 0; i < num_pins; i++) {
        struct gpiod_line *line = gpiod_chip_get_line(chip, pins[i]);
        if (!line) {
            perror("Failed to get GPIO line");
            exit(EXIT_FAILURE);
        }
        if (gpiod_line_request_output(line, "stepper", 0)) {
            perror("Failed to request GPIO line as output");
            exit(EXIT_FAILURE);
        }
    }
}

void init_buttons(struct gpiod_chip *chip, int pin) {
    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("Failed to get GPIO line");
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_input(line, "button", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP)) {
        perror("Failed to request GPIO line as input with pull-up");
        exit(EXIT_FAILURE);
    }
}

void step_motor(struct gpiod_chip *chip, int *pins, int steps, int direction) {
    int step_sequence[4][4] = {
        {1, 0, 0, 0},
        {1, 1, 0, 0},
        {0, 1, 0, 0},
        {0, 1, 1, 0}
    };
    for (int i = 0; i < steps; i++) {
        for (int j = 0; j < 4; j++) {
            for (int k = 0; k < 4; k++) {
                gpiod_line_set_value(gpiod_chip_get_line(chip, pins[k]), step_sequence[j][k]);
            }
            usleep(STEP_DELAY);
        }
    }
}

int main() {
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    init_gpio(chip, STEPPER_PINS, 4);
    init_buttons(chip, LOCK_BUTTON);
    init_buttons(chip, UNLOCK_BUTTON);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        if (gpiod_line_get_value(gpiod_chip_get_line(chip, LOCK_BUTTON)) == 0) {
            printf("Locking door...\n");
            step_motor(chip, STEPPER_PINS, STEPS_PER_REV, 1);
            while (gpiod_line_get_value(gpiod_chip_get_line(chip, LOCK_BUTTON)) == 0) {
                usleep(10000);
            }
        }
        if (gpiod_line_get_value(gpiod_chip_get_line(chip, UNLOCK_BUTTON)) == 0) {
            printf("Unlocking door...\n");
            step_motor(chip, STEPPER_PINS, STEPS_PER_REV, -1);
            while (gpiod_line_get_value(gpiod_chip_get_line(chip, UNLOCK_BUTTON)) == 0) {
                usleep(10000);
            }
        }
    }

    printf("Program exiting...\n");
    for (int i = 0; i < 4; i++) {
        gpiod_line_set_value(gpiod_chip_get_line(chip, STEPPER_PINS[i]), 0);
    }

    gpiod_chip_close(chip);
    return 0;
}

