#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define SCHEDULE_FILE "lighting_schedule.txt"
#define GPIO_PINS {4, 17, 27, 22}
#define PWM_FREQ 100
#define FADE_DURATION 1800
#define NUM_LAMPS 4

struct Lamp {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int pin;
    int state;
    int target_state;
    int duty_cycle;
    int fade_start;
    int fade_end;
};

void signal_handler(int signum) {
    static int handled = 0;
    if (handled) {
        exit(EXIT_FAILURE);
    }
    handled = 1;
    for (int i = 0; i < NUM_LAMPS; i++) {
        struct Lamp *lamp = &lamps[i];
        if (lamp->line) {
            gpiod_line_set_value(lamp->line, 0);
        }
    }
    for (int i = 0; i < NUM_LAMPS; i++) {
        struct Lamp *lamp = &lamps[i];
        if (lamp->chip) {
            gpiod_chip_close(lamp->chip);
        }
    }
    exit(EXIT_SUCCESS);
}

void init_lamps(struct Lamp *lamps) {
    for (int i = 0; i < NUM_LAMPS; i++) {
        struct Lamp *lamp = &lamps[i];
        lamp->chip = gpiod_chip_open_by_name("gpiochip0");
        if (!lamp->chip) {
            perror("Failed to open GPIO chip");
            exit(EXIT_FAILURE);
        }
        lamp->line = gpiod_chip_get_line(lamp->chip, GPIO_PINS[i]);
        if (!lamp->line) {
            perror("Failed to get GPIO line");
            gpiod_chip_close(lamp->chip);
            exit(EXIT_FAILURE);
        }
        if (gpiod_line_request_output(lamp->line, "smart_home_lighting", 0) < 0) {
            perror("Failed to request GPIO line as output");
            gpiod_chip_close(lamp->chip);
            exit(EXIT_FAILURE);
        }
        lamp->pin = GPIO_PINS[i];
        lamp->state = 0;
        lamp->target_state = 0;
        lamp->duty_cycle = 0;
        lamp->fade_start = 0;
        lamp->fade_end = 0;
    }
}

void read_schedule(struct Lamp *lamps) {
    FILE *file = fopen(SCHEDULE_FILE, "r");
    if (!file) {
        perror("Failed to open schedule file");
        return;
    }
    char line[256];
    while (fgets(line, sizeof(line), file)) {
        char *token = strtok(line, ":");
        if (!token) continue;
        int hour = atoi(token);
        token = strtok(NULL, ":");
        if (!token) continue;
        int minute = atoi(token);
        token = strtok(NULL, ":");
        if (!token) continue;
        int second = atoi(token);
        token = strtok(NULL, ",");
        if (!token) continue;
        int relay_number = atoi(token);
        if (relay_number < 0 || relay_number >= NUM_LAMPS) continue;
        token = strtok(NULL, ",");
        if (!token) continue;
        int on_off = atoi(token);
        if (on_off != 0 && on_off != 1) continue;
