#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18
#define MIN_MEASUREMENT_INTERVAL 60000  // 60 ms
#define MIN_FREQUENCY 200  // 200 Hz
#define MAX_FREQUENCY 2000  // 2000 Hz

static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static struct gpiod_line *buzzer_line;
static int last_measurement_time = 0;

void cleanup() {
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

void signal_handler(int sig) {
    cleanup();
}

int main() {
    struct gpiod_line_request_config trigger_config = {
        .consumer = "theremin_trigger",
        .request_type = GPIOD_LINE_REQUEST_OUTPUT,
        .default_val = 0,
    };
    struct gpiod_line_request_config echo_config = {
        .consumer = "theremin_echo",
        .request_type = GPIOD_LINE_REQUEST_INPUT,
    };
    struct gpiod_line_request_config buzzer_config = {
        .consumer = "theremin_buzzer",
        .request_type = GPIOD_LINE_REQUEST_OUTPUT,
        .default_val = 0,
    };
    struct timespec start, end;
    long long duration;
    int distance, frequency;

    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Failed to get trigger line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Failed to get echo line");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        perror("Failed to get buzzer line");
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(trigger_line, &trigger_config) < 0) {
        perror("Failed to request trigger line");
        gpiod_line_release(buzzer_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(echo_line, &echo_config) < 0) {
        perror("Failed to request echo line");
        gpiod_line_release(trigger_line);
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(buzzer_line, &buzzer_config) < 0) {
        perror("Failed to request buzzer line");
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        if (clock_gettime(CLOCK_MONOTONIC, &start) < 0) {
            perror("Failed to get start time");
            cleanup();
        }

        gpiod_line_set_value(trigger_line, 1);
        usleep(10);
        gpiod_line_set_value(trigger_line, 0);

        if (clock_gettime(CLOCK_MONOTONIC, &end) < 0) {
            perror("Failed to get end time");
            cleanup();
        }

        duration = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
        distance = duration / 58;  // Speed of sound is approximately 340 m/s, so 170 us per cm

        if (distance < 0 || distance > 400) {
            fprintf(stderr, "Invalid distance reading: %d\n", distance);
            continue;
        }

        frequency = 20000 / distance;  // Map distance to frequency

        if (frequency < MIN_FREQUENCY || frequency > MAX_FREQUENCY) {
            frequency = frequency < MIN_FREQUENCY ? MIN_FREQUENCY : MAX_FREQUENCY;
        }

        if (clock_gettime(CLOCK_MONOTONIC, &start) < 0) {
            perror("Failed to get start time for PWM");
            cleanup();
        }

        gpiod_line_set_value(buzzer_line, 1);
        usleep(1000000 / (2 * frequency));
        gpiod_line_set_value(buzzer_line, 0);
        usleep(1000000 / (2 * frequency));

        if (clock_gettime(CLOCK_MONOTONIC, &end) < 0) {
            perror("Failed to get end time for PWM");
            cleanup();
        }

        duration = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;

        if (duration < MIN_MEASUREMENT_INTERVAL) {
            usleep(MIN_MEASUREMENT_INTERVAL - duration);
        }

        last_measurement_time = duration;
    }

    cleanup();
    return EXIT_SUCCESS;
}

