#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define LED_CHIP "gpiochip0"
#define LED_RED 17
#define LED_GREEN 22
#define LED_BLUE 27
#define PWM_FREQ 1000

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void set_pwm(struct gpiod_chip *chip, int line_num, double value) {
    struct gpiod_line *line;
    struct gpiod_line_request req = {
        .consumer = "rgb_led",
        .type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT,
        .default_val = 0,
    };

    line = gpiod_chip_get_line(chip, line_num);
    if (!line) {
        perror("Failed to get GPIO line");
        return;
    }

    if (gpiod_request_line(line, &req)) {
        perror("Failed to request GPIO line");
        gpiod_line_release(line);
        return;
    }

    int duty_cycle = (int)(value * 255);
    if (gpiod_line_set_value(line, duty_cycle)) {
        perror("Failed to set GPIO line value");
    }

    gpiod_line_release(line);
}

int main() {
    struct gpiod_chip *chip;
    struct sigaction sa;

    // Initialize signal handler
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to set signal handler");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open(LED_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Set up PWM for each LED
    set_pwm(chip, LED_RED, 0.0);
    set_pwm(chip, LED_GREEN, 0.0);
    set_pwm(chip, LED_BLUE, 0.0);

    // Generate smooth color transition
    while (running) {
        for (double t = 0; t < 2 * M_PI; t += 0.01) {
            double red = sin(t) * 0.5 + 0.5;
            double green = sin(t + 2 * M_PI / 3) * 0.5 + 0.5;
            double blue = sin(t + 4 * M_PI / 3) * 0.5 + 0.5;

            set_pwm(chip, LED_RED, red);
            set_pwm(chip, LED_GREEN, green);
            set_pwm(chip, LED_BLUE, blue);

            usleep(1000);
        }
    }

    // Turn off the LED
    set_pwm(chip, LED_RED, 0.0);
    set_pwm(chip, LED_GREEN, 0.0);
    set_pwm(chip, LED_BLUE, 0.0);

    // Release resources
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

