#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE "/dev/i2c-1"
#define MPU6050_ADDRESS 0x68
#define MPU6050_GYRO_CONFIG 0x1B
#define MPU6050_GYRO_XOUT_H 0x43
#define SAMPLE_INTERVAL 100000  // 100 ms in microseconds

int i2c_fd;
FILE *log_file;

void close_resources() {
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

void handle_sigint(int sig) {
    close_resources();
    exit(0);
}

int read_mpu6050_gyro(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buffer[6];
    if (read(i2c_fd, buffer, sizeof(buffer)) != sizeof(buffer)) {
        perror("Failed to read from MPU6050");
        return -1;
    }
    *x = (buffer[0] << 8) | buffer[1];
    *y = (buffer[2] << 8) | buffer[3];
    *z = (buffer[4] << 8) | buffer[5];
    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set signal handler");
        return 1;
    }

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return 1;
    }

    uint8_t config = 0x10;  // +/- 2000 degrees/s
    if (write(i2c_fd, &MPU6050_GYRO_CONFIG, 1) != 1 || write(i2c_fd, &config, 1) != 1) {
        perror("Failed to configure MPU6050");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen("gyro_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        int16_t x, y, z;
        if (read_mpu6050_gyro(&x, &y, &z) == 0) {
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d.%06ld %d %d %d\n",
                    tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
                    tm->tm_hour, tm->tm_min, tm->tm_sec, (long)microtime(NULL) % 1000000,
                    x / 131.0, y / 131.0, z / 131.0);
            fflush(log_file);
        }
        usleep(SAMPLE_INTERVAL);
    }

    close_resources();
    return 0;
}

double microtime() {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    return tv.tv_sec + tv.tv_usec / 1000000.0;
}

