#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define LOG_FILE "vibration_events.log"
#define WINDOW_SIZE 5
#define THRESHOLD 3
#define DEFAULT_TIMEOUT 1000

volatile sig_atomic_t stop_flag = 0;

void log_event(int value) {
    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    char *iso_time = ctime(&now);
    iso_time[strlen(iso_time) - 1] = '\0'; // Remove newline

    fprintf(log, "%s %d\n", iso_time, value);
    fflush(log);
    fsync(fileno(log));
    fclose(log);
}

void print_alert() {
    time_t now = time(NULL);
    char *iso_time = ctime(&now);
    iso_time[strlen(iso_time) - 1] = '\0'; // Remove newline

    printf("EARTHQUAKE ALERT at %s\n", iso_time);
}

void signal_handler(int signum) {
    stop_flag = 1;
}

int main(int argc, char *argv[]) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_request_config config;
    int timeout = DEFAULT_TIMEOUT;
    int events[WINDOW_SIZE];
    int event_count = 0;
    int high_count = 0;

    if (argc > 1) {
        timeout = atoi(argv[1]);
        if (timeout <= 0) {
            fprintf(stderr, "Invalid timeout value. Using default %d ms.\n", DEFAULT_TIMEOUT);
            timeout = DEFAULT_TIMEOUT;
        }
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    memset(&config, 0, sizeof(config));
    config.consumer = "vibration_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    config.flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP;

    if (gpiod_line_request(line, &config)) {
        perror("Failed to request GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (!stop_flag) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("Failed to read GPIO line value");
            continue;
        }

        log_event(value);

        events[event_count % WINDOW_SIZE] = value;
        event_count = (event_count + 1) % WINDOW_SIZE;

        if (value == 1) {
            high_count++;
        } else {
            high_count = 0;
        }

        if (high_count >= THRESHOLD) {
            print_alert();
        }

        if (gpiod_line_event_wait(line, timeout * 1000)) {
            struct gpiod_line_event event;
            if (gpiod_line_event_read(line, &event)) {
                perror("Failed to read GPIO line event");
                continue;
            }
        }
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

