#define LSM303DLHC_OUT_X_H_M 0x29
#define LSM303DLHC_OUT_Y_L_M 0x2A
#define LSM303DLHC_OUT_Y_H_M 0x2B
#define LSM303DLHC_OUT_Z_L_M 0x2C
#define LSM303DLHC_OUT_Z_H_M 0x2D

#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20

#define NUM_DIRS 8
const char *directions[NUM_DIRS] = {"N", "NE", "E", "SE", "S", "SW", "W", "NW"};

struct i2c_device {
    struct gpiod_chip *chip;
    struct gpiod_line *sda;
    struct gpiod_line *scl;
    int fd;
};

struct i2c_device i2c_dev;

void close_resources() {
    if (i2c_dev.fd >= 0) {
        close(i2c_dev.fd);
    }
    if (i2c_dev.sda) {
        gpiod_line_release(i2c_dev.sda);
    }
    if (i2c_dev.scl) {
        gpiod_line_release(i2c_dev.scl);
    }
    if (i2c_dev.chip) {
        gpiod_chip_close(i2c_dev.chip);
    }
}

void signal_handler(int signum) {
    close_resources();
    exit(signum);
}

int i2c_read_byte(int fd, uint8_t reg) {
    uint8_t data;
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write failed");
        return -1;
    }
    if (read(fd, &data, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return data;
}

int i2c_read_int(int fd, uint8_t reg) {
    int16_t data;
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write failed");
        return -1;
    }
    if (read(fd, &data, 2) != 2) {
        perror("I2C read failed");
        return -1;
    }
    return data;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *sda, *scl;
    int fd;
    FILE *log_file = NULL;
    char *log_filename = "mag_log.csv";
    char *header = "Timestamp, Calibrated X, Calibrated Y, Calibrated Z, Heading\n";
    time_t now;
    struct tm *tm_info;
    int16_t x, y, z;
    int heading;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    sda = gpiod_chip_get_line(chip, 2);
    if (!sda) {
        perror("Failed to get SDA line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    scl = gpiod_chip_get_line(chip, 3);
    if (!scl) {
        perror("Failed to get SCL line");
        gpiod_line_release(sda);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(sda, "sda", 0) < 0) {
        perror("Failed to request SDA line");
        gpiod_line_release(sda);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(scl, "scl", 0) < 0) {
        perror("Failed to request SCL line");
        gpiod_line_release(sda);
        gpiod_line_release(scl);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        close_resources();
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, LSM303DLHC_I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close_resources();
        return EXIT_FAILURE;
    }

    if (access(log_filename, F_OK) == -1) {
        log_file = fopen(log_filename, "w");
        if (!log_file) {
            perror("Failed to open log file for writing");
            close_resources();
            return EXIT_FAILURE;
        }
        fprintf(log_file, "%s", header);
    } else {
        log_file = fopen(log_filename, "a");
        if (!log_file) {
            perror("Failed to open log file for appending");
            close_resources();
            return EXIT_FAILURE;
        }
    }

    while (1) {
        x = i2c_read_int(fd, LSM303DLHC_OUT_X_L_M);
        y = i2c_read_int(fd, LSM303DLHC_OUT_Y_L_M);
        z = i2c_read_int(fd, LSM303DLHC_OUT_Z_L_M);

        if (x == -1 || y == -1 || z == -1) {
            fprintf(stderr, "I2C read failed, skipping sample\n");
            continue;
        }

        x += X_OFFSET;
        y += Y_OFFSET;
        z += Z_OFFSET;

        heading = (int)(atan2(y, x) * 180 / M_PI + 360) % 360;

        now = time(NULL);
        tm_info = localtime(&now);
        fprintf(log_file, "%ld,%d,%d,%d,%d\n", now, x, y, z, heading);
        fprintf(stdout, "Heading: %s %d\n", directions[heading / 45], heading);

        fflush(log_file);
        sleep(1);
    }

    close_resources();
    return EXIT_SUCCESS;
}

