#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define RELAY_PIN 17
#define TOUCH_PIN 4
#define DEBOUNCE_TIME 200
#define LOG_FILE "relay_log.json"

static struct gpiod_chip *chip;
static struct gpiod_line *relay_line;
static struct gpiod_line *touch_line;
static int last_touch_time = 0;

void log_state_change(int state) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    char *iso_time = ctime(&now);
    iso_time[strlen(iso_time) - 1] = '\0'; // Remove newline

    fprintf(log_file, "{\"timestamp\":\"%s\",\"relay_state\":\"%s\"}\n", iso_time, state ? "ON" : "OFF");
    fclose(log_file);
}

void handle_sigint(int sig) {
    gpiod_line_set_value(relay_line, 0);
    log_state_change(0);
    gpiod_chip_close(chip);
    exit(0);
}

void touch_interrupt_handler(void *user_data) {
    int current_time = time(NULL);
    if (current_time - last_touch_time > DEBOUNCE_TIME) {
        int touch_state = gpiod_line_get_value(touch_line);
        if (touch_state == 0) {
            int relay_state = gpiod_line_get_value(relay_line);
            gpiod_line_set_value(relay_line, !relay_state);
            log_state_change(!relay_state);
        }
        last_touch_time = current_time;
    }
}

int main() {
    signal(SIGINT, handle_sigint);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        perror("Failed to get relay line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(relay_line, "relay_control", 0) < 0) {
        perror("Failed to request relay line as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    touch_line = gpiod_chip_get_line(chip, TOUCH_PIN);
    if (!touch_line) {
        perror("Failed to get touch line");
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(touch_line, "touch_sensor") < 0) {
        perror("Failed to request touch line as input");
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_rising_edge_events(touch_line, "touch_event") < 0) {
        perror("Failed to request rising edge events on touch line");
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    gpiod_line_event_wait(touch_line, NULL);
    gpiod_line_event_read(touch_line, NULL);

    while (1) {
        gpiod_line_event_wait(touch_line, NULL);
        gpiod_line_event_read(touch_line, NULL);
    }

    gpiod_line_release(relay_line);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

