#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define RELAY_COUNT 4
#define RELAY_PINS[17, 23, 24, 25]
#define MIN_MOISTURE 30
#define RELAY_DURATION 5
#define GAP_DURATION 1
#define LOG_FILE "irrigation_log.txt"

static struct gpiod_chip *chip;
static struct gpiod_line *lines[RELAY_COUNT];
static FILE *log_file;

void log_event(int relay, int moisture) {
    char timestamp[20];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", tm_info);

    fprintf(log_file, "%s, Relay %d, Moisture %d\n", timestamp, relay, moisture);
    fflush(log_file);
}

void activate_relay(int relay) {
    if (gpiod_line_set_value(lines[relay], 0) < 0) {
        perror("Failed to set relay line value");
    }
}

void deactivate_relay(int relay) {
    if (gpiod_line_set_value(lines[relay], 1) < 0) {
        perror("Failed to set relay line value");
    }
}

void handle_signal(int signum) {
    for (int i = 0; i < RELAY_COUNT; i++) {
        deactivate_relay(i);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(signum);
}

int main() {
    srand(time(NULL));
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    for (int i = 0; i < RELAY_COUNT; i++) {
