#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define VALVE_PIN 17
#define NOZZLE_PIN 18
#define SOIL_MOISTURE_VALUES {20, 40, 60, 80, 100}
#define PULSE_WIDTHS {500, 1000, 1500, 2000, 2500}
#define VALVE_OPEN_PULSE 1500
#define VALVE_CLOSE_PULSE 500
#define SPRAY_TIME 5
#define CYCLE_TIME 2
#define RETRY_COUNT 3
#define BACKOFF_MS 100

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

int set_servo_pulse(struct gpiod_chip *chip, unsigned int pin, unsigned int pulse_width) {
    struct gpiod_line *line;
    int ret;

    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("Failed to get GPIO line");
        return -1;
    }

    ret = gpiod_line_request_output(line, "servo", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(line);
        return -1;
    }

    ret = gpiod_line_set_value(line, pulse_width / 1000);
    if (ret < 0) {
        perror("Failed to set GPIO line value");
        gpiod_line_release(line);
        return -1;
    }

    gpiod_line_release(line);
    return 0;
}

int main() {
    struct gpiod_chip *chip;
    int ret, i, j;
    unsigned int moisture_value;
    unsigned int pulse_width;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!stop_flag) {
        for (i = 0; i < sizeof(SOIL_MOISTURE_VALUES) / sizeof(SOIL_MOISTURE_VALUES[0]); i++) {
            moisture_value = SOIL_MOISTURE_VALUES[i];

            if (moisture_value < 50) {
                for (j = 0; j < RETRY_COUNT; j++) {
                    ret = set_servo_pulse(chip, VALVE_PIN, VALVE_OPEN_PULSE);
                    if (ret == 0) {
                        break;
                    }
                    usleep(BACKOFF_MS * 1000);
                }

                if (ret != 0) {
                    fprintf(stderr, "Failed to open valve, aborting cycle\n");
                    continue;
                }

                for (j = 0; j < sizeof(PULSE_WIDTHS) / sizeof(PULSE_WIDTHS[0]); j++) {
                    pulse_width = PULSE_WIDTHS[j];
                    for (int k = 0; k < RETRY_COUNT; k++) {
                        ret = set_servo_pulse(chip, NOZZLE_PIN, pulse_width);
                        if (ret == 0) {
                            break;
                        }
                        usleep(BACKOFF_MS * 1000);
                    }

                    if (ret != 0) {
                        fprintf(stderr, "Failed to set nozzle position, continuing to next angle\n");
                        continue;
                    }

                    sleep(CYCLE_TIME);
                }

                for (j = 0; j < RETRY_COUNT; j++) {
                    ret = set_servo_pulse(chip, VALVE_PIN, VALVE_CLOSE_PULSE);
                    if (ret == 0) {
                        break;
                    }
                    usleep(BACKOFF_MS * 1000);
                }

                if (ret != 0) {
                    fprintf(stderr, "Failed to close valve, critical warning\n");
                }

                sleep(SPRAY_TIME);
            } else {
                printf("Soil moisture is sufficient, skipping watering cycle\n");
            }

            sleep(1);
        }
    }

    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

