#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define SAMPLE_RATE 10
#define SAMPLE_INTERVAL (1000000 / SAMPLE_RATE)

#define XGyro_REG 0x43
#define YGyro_REG 0x45
#define ZGyro_REG 0x47

static int i2c_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *sda_line, *scl_line;

void cleanup(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (sda_line) {
        gpiod_line_release(sda_line);
    }
    if (scl_line) {
        gpiod_line_release(scl_line);
    }
    exit(signum);
}

int read_mpu6050_gyro(int reg, int16_t *value) {
    uint8_t buf[2];
    if (read(i2c_fd, buf, 2) != 2) {
        perror("Failed to read from MPU6050");
        return -1;
    }
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

int main() {
    struct timespec ts;
    FILE *log_file = fopen("gyro_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    // Set up signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Initialize I2C
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        fclose(log_file);
        return EXIT_FAILURE;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Initialize GPIO for I2C
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        fclose(log_file);
        return EXIT_FAILURE;
    }
    sda_line = gpiod_chip_get_line(chip, 2);
    if (!sda_line) {
        perror("Failed to get SDA line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        fclose(log_file);
        return EXIT_FAILURE;
    }
    scl_line = gpiod_chip_get_line(chip, 3);
    if (!scl_line) {
        perror("Failed to get SCL line");
        gpiod_line_release(sda_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        fclose(log_file);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(sda_line, "i2c_sda", 0) < 0) {
        perror("Failed to request SDA line");
        gpiod_line_release(sda_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        fclose(log_file);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(scl_line, "i2c_scl", 0) < 0) {
        perror("Failed to request SCL line");
        gpiod_line_release(sda_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    while (1) {
        int16_t x, y, z;
        if (read_mpu6050_gyro(XGyro_REG, &x) < 0) {
            fprintf(stderr, "Failed to read X gyro value\n");
            continue;
        }
        if (read_mpu6050_gyro(YGyro_REG, &y) < 0) {
            fprintf(stderr, "Failed to read Y gyro value\n");
            continue;
        }
        if (read_mpu6050_gyro(ZGyro_REG, &z) < 0) {
            fprintf(stderr, "Failed to read Z gyro value\n");
            continue;
        }

        if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
            perror("Failed to get current time");
            continue;
        }

        fprintf(log_file, "%ld.%09ld,%d,%d,%d\n", ts.tv_sec, ts.tv_nsec, x, y, z);
        fflush(log_file);

        usleep(SAMPLE_INTERVAL);
    }

    fclose(log_file);
    return EXIT_SUCCESS;
}

