#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define LOCK_BUTTON 24
#define UNLOCK_BUTTON 23
#define MOTOR_IN1 4
#define MOTOR_IN2 17
#define MOTOR_IN3 27
#define MOTOR_IN4 22
#define STEPS 512
#define STEP_DELAY 3

static struct gpiod_chip *chip;
static struct gpiod_line *lock_button, *unlock_button, *motor_in1, *motor_in2, *motor_in3, *motor_in4;

void cleanup() {
    if (motor_in1) gpiod_line_release(motor_in1);
    if (motor_in2) gpiod_line_release(motor_in2);
    if (motor_in3) gpiod_line_release(motor_in3);
    if (motor_in4) gpiod_line_release(motor_in4);
    if (lock_button) gpiod_line_release(lock_button);
    if (unlock_button) gpiod_line_release(unlock_button);
    if (chip) gpiod_chip_close(chip);
}

void handle_sigint(int sig) {
    cleanup();
    exit(0);
}

void step_motor(int direction) {
    for (int i = 0; i < STEPS; i++) {
        if (direction == 1) {
            gpiod_line_set_value(motor_in1, 1);
            gpiod_line_set_value(motor_in2, 0);
            gpiod_line_set_value(motor_in3, 0);
            gpiod_line_set_value(motor_in4, 0);
            usleep(STEP_DELAY * 1000);
            gpiod_line_set_value(motor_in1, 0);
            gpiod_line_set_value(motor_in2, 1);
            gpiod_line_set_value(motor_in3, 0);
            gpiod_line_set_value(motor_in4, 0);
            usleep(STEP_DELAY * 1000);
            gpiod_line_set_value(motor_in1, 0);
            gpiod_line_set_value(motor_in2, 0);
            gpiod_line_set_value(motor_in3, 1);
            gpiod_line_set_value(motor_in4, 0);
            usleep(STEP_DELAY * 1000);
            gpiod_line_set_value(motor_in1, 0);
            gpiod_line_set_value(motor_in2, 0);
            gpiod_line_set_value(motor_in3, 0);
            gpiod_line_set_value(motor_in4, 1);
            usleep(STEP_DELAY * 1000);
        } else {
            gpiod_line_set_value(motor_in1, 0);
            gpiod_line_set_value(motor_in2, 0);
            gpiod_line_set_value(motor_in3, 0);
