#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define TRIGGER_LINE "gpiochip0:line17"
#define ECHO_LINE "gpiochip0:line18"
#define LOG_FILE "distance_log.txt"
#define TRIGGER_PULSE_US 10
#define TIMEOUT_MS 50
#define MIN_PAUSE_MS 60
#define SAMPLE_INTERVAL_S 1

static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static FILE *log_file;

void cleanup(int signum) {
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(signum);
}

int main() {
    struct timespec start, end;
    long long duration_ns;
    double distance_cm;

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    // Register signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Request trigger line as output
    trigger_line = gpiod_chip_get_line(chip, 17);
    if (!trigger_line) {
        perror("Failed to get trigger line");
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(trigger_line, "trigger", 0) < 0) {
        perror("Failed to request trigger line as output");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Request echo line as input
    echo_line = gpiod_chip_get_line(chip, 18);
    if (!echo_line) {
        perror("Failed to get echo line");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_input(echo_line, "echo") < 0) {
        perror("Failed to request echo line as input");
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    while (1) {
        // Generate trigger pulse
        if (gpiod_line_set_value(trigger_line, 1) < 0) {
            fprintf(stderr, "Failed to set trigger line high\n");
            fprintf(log_file, "-1\n");
            fflush(log_file);
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }
        usleep(TRIGGER_PULSE_US);
        if (gpiod_line_set_value(trigger_line, 0) < 0) {
            fprintf(stderr, "Failed to set trigger line low\n");
            fprintf(log_file, "-1\n");
            fflush(log_file);
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        // Wait for rising edge
        if (gpiod_line_event_wait(echo_line, &start, TIMEOUT_MS * 1000) < 0) {
            fprintf(stderr, "Timeout waiting for rising edge\n");
            fprintf(log_file, "-1\n");
            fflush(log_file);
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }
        if (gpiod_line_event_read(echo_line, &start) < 0) {
            fprintf(stderr, "Failed to read rising edge event\n");
            fprintf(log_file, "-1\n");
            fflush(log_file);
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        // Wait for falling edge
        if (gpiod_line_event_wait(echo_line, &end, TIMEOUT_MS * 1000) < 0) {
            fprintf(stderr, "Timeout waiting for falling edge\n");
            fprintf(log_file, "-1\n");
            fflush(log_file);
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }
        if (gpiod_line_event_read(echo_line, &end) < 0) {
            fprintf(stderr, "Failed to read falling edge event\n");
            fprintf(log_file, "-1\n");
            fflush(log_file);
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        // Calculate duration
        duration_ns = (end.tv_sec - start.tv_sec) * 1000000000LL + (end.tv_nsec - start.tv_nsec);
        distance_cm = (duration_ns * 0.034 / 2) / 10000;

        // Log distance
        fprintf(log_file, "%.2f\n", distance_cm);
        fflush(log_file);

        // Pause
        usleep(MIN_PAUSE_MS * 1000);
    }

    return EXIT_SUCCESS;
}

