#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <sys/ioctl.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x29
#define RELAY_PIN 18
#define RELAY_HIGH 1
#define RELAY_LOW 0
#define POLL_INTERVAL 100  // 100 ms
#define MAX_DISTANCE 50  // 50 cm

static struct gpiod_chip *chip;
static struct gpiod_line *relay_line;
static int i2c_fd;

void cleanup() {
    if (relay_line) {
        gpiod_line_set_value(relay_line, RELAY_LOW);
        gpiod_line_release(relay_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

void signal_handler(int sig) {
    cleanup();
    exit(0);
}

int read_distance() {
    uint8_t buffer[3];
    if (read(i2c_fd, buffer, sizeof(buffer)) != sizeof(buffer)) {
        perror("Failed to read from I2C device");
        return -1;
    }
    uint16_t distance = (buffer[1] << 8) | buffer[0];
    return distance;
}

int main() {
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(relay_line, "distance_sensor_relay", RELAY_LOW) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        int distance = read_distance();
        if (distance >= 0) {
            printf("Distance: %d cm\n", distance);
            if (distance <= MAX_DISTANCE) {
                gpiod_line_set_value(relay_line, RELAY_HIGH);
            } else {
                gpiod_line_set_value(relay_line, RELAY_LOW);
            }
        }
        usleep(POLL_INTERVAL * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

