This C program for a Raspberry Pi 4 Model B continuously reads distance from a VL53L1X time-of-flight sensor attached to I2C bus 1 using the documented default address. It polls the sensor every 100 ms, prints the current distance to stdout, and drives a relay connected to GPIO18 (BCM) based on the distance. The program handles errors, logs them to stderr, and ensures clean resource release on receipt of SIGINT.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define I2C_DEVICE "/dev/i2c-1"
#define MPU6050_ADDRESS 0x68
#define MPU6050_GYRO_XOUT_H 0x43
#define MPU6050_GYRO_YOUT_H 0x45
#define MPU6050_GYRO_ZOUT_H 0x47

static struct gpiod_chip *chip;
static struct gpiod_line *sda_line;
static struct gpiod_line *scl_line;

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, cleaning up...\n", signum);
        if (sda_line) gpiod_line_release(sda_line);
        if (scl_line) gpiod_line_release(scl_line);
        if (chip) gpiod_chip_close(chip);
        exit(signum);
    }
}

int i2c_read_byte(int fd, uint8_t reg) {
    uint8_t data;
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write failed");
        return -1;
    }
    if (read(fd, &data, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return data;
}

int i2c_read_word(int fd, uint8_t reg) {
    uint8_t data[2];
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write failed");
        return -1;
    }
    if (read(fd, data, 2) != 2) {
        perror("I2C read failed");
        return -1;
    }
    return (data[0] << 8) | data[1];
}

int main() {
    int fd;
    uint8_t reg;
    int gyro_x, gyro_y, gyro_z;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    if ((fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set SDA and SCL lines
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(fd);
        return EXIT_FAILURE;
    }

    sda_line = gpiod_chip_get_line(chip, 2);
    if (!sda_line) {
        perror("Failed to get SDA line");
        gpiod_chip_close(chip);
        close(fd);
        return EXIT_FAILURE;
    }

    scl_line = gpiod_chip_get_line(chip, 3);
    if (!scl_line) {
        perror("Failed to get SCL line");
        gpiod_line_release(sda_line);
        gpiod_chip_close(chip);
        close(fd);
        return EXIT_FAILURE;
    }

    // Configure SDA and SCL lines as output
    if (gpiod_line_request_output(sda_line, "mpu6050_sda", 0) < 0) {
        perror("Failed to request SDA line");
        gpiod_line_release(sda_line);
        gpiod_chip_close(chip);
        close(fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(scl_line, "mpu6050_scl", 0) < 0) {
        perror("Failed to request SCL line");
        gpiod_line_release(sda_line);
        gpiod_chip_close(chip);
        close(fd);
        return EXIT_FAILURE;
    }

    // Initialize MPU6050
    reg = 0x6B; // PWR_MGMT_1
    if (i2c_write_byte(fd, reg, 0) < 0) {
        perror("Failed to initialize MPU6050");
        gpiod_line_release(sda_line);
        gpiod_line_release(scl_line);
        gpiod_chip_close(chip);
        close(fd);
        return EXIT_FAILURE;
    }

    while (1) {
        // Read gyroscope data
        gyro_x = i2c_read_word(fd, MPU6050_GYRO_XOUT_H);
        gyro_y = i2c_read_word(fd, MPU6050_GYRO_YOUT_H);
        gyro_z = i2c_read_word(fd, MPU6050_GYRO_ZOUT_H);

        if (gyro_x < 0 || gyro_y < 0 || gyro_z < 0) {
            fprintf(stderr, "Failed to read gyroscope data\n");
            continue;
        }

        // Print gyroscope data
        printf("Gyro X: %d, Gyro Y: %d, Gyro Z: %d\n", gyro_x, gyro_y, gyro_z);

        // Sleep for a short period
        usleep(100000); // 100 ms
    }

    // Clean up
    gpiod_line_release(sda_line);
    gpiod_line_release(scl_line);
    gpiod_chip_close(chip);
    close(fd);

    return EXIT_SUCCESS;
}

