#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINES "17,18,27,22"
#define RELAY_DURATION 5
#define CYCLE_DURATION 86400
#define LOG_FILE "watering_log.txt"

static struct gpiod_chip *chip;
static struct gpiod_line *lines[4];
static FILE *log_file;

void log_time(const char *prefix) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(log_file, "%s %04d-%02d-%02d %02d:%02d:%02d\n", prefix, tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday, tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec);
    fflush(log_file);
}

void signal_handler(int signum) {
    for (int i = 0; i < 4; i++) {
        gpiod_line_set_value(lines[i], 1);
    }
    gpiod_chip_close(chip);
    if (log_file) {
        fclose(log_file);
    }
    exit(signum);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    const char *line_names[] = {"17", "18", "27", "22"};
    for (int i = 0; i < 4; i++) {
        lines[i] = gpiod_chip_get_line(chip, atoi(line_names[i]));
        if (!lines[i]) {
            perror("Failed to get GPIO line");
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
        if (gpiod_line_request_output(lines[i], "watering", 1) < 0) {
            perror("Failed to request GPIO line as output");
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        for (int i = 0; i < 4; i++) {
            gpiod_line_release(lines[i]);
        }
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_time("Starting watering cycle");

    while (1) {
        for (int i = 0; i < 4; i++) {
            gpiod_line_set_value(lines[i], 0);
            log_time("Watering relay");
            sleep(RELAY_DURATION);
            gpiod_line_set_value(lines[i], 1);
        }
        sleep(CYCLE_DURATION);
    }

    return EXIT_SUCCESS;
}

