This program will open the GPIO chip, request the specified lines as outputs with active-low semantics, set them to HIGH (inactive) at startup, and then enter a main loop that activates each relay in turn for exactly 5 seconds, repeating the sequence once every 24 hours. It logs the start time of each full cycle to a file named `watering_log.txt` in the format "YYYY-MM-DD HH:MM:SS". The program also installs a SIGINT/SIGTERM handler that releases all GPIO lines, closes the chip, and exits cleanly.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PINS {17, 18, 27, 22}
#define PWM_PERIOD_NS 1000000  // 1 kHz
#define DUTY_CYCLE_MAX 255
#define DURATION_SECONDS 1800  // 30 minutes

static struct gpiod_chip *chip;
static struct gpiod_line *lines[4];
static struct gpiod_line_request req;
static int running = 1;

void log_event(const char *message) {
    FILE *log_file = fopen("smart_lighting.log", "a");
    if (log_file) {
        time_t now = time(NULL);
        fprintf(log_file, "%s: %s\n", ctime(&now), message);
        fclose(log_file);
    }
}

void signal_handler(int signum) {
    running = 0;
}

int setup_gpio() {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        log_event("Failed to open GPIO chip");
        return -1;
    }

    for (int i = 0; i < 4; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_PINS[i]);
        if (!lines[i]) {
            log_event("Failed to get GPIO line");
            return -1;
        }

        if (gpiod_line_request_output(lines[i], "smart_lighting", 0)) {
            log_event("Failed to request GPIO line as output");
            return -1;
        }
    }

    return 0;
}

int setup_pwm() {
    if (gpiod_line_request_bulk(chip, GPIO_PINS, "smart_lighting", &req, GPIOD_LINE_REQUEST_DIRECTION_OUTPUT)) {
        log_event("Failed to request GPIO lines for PWM");
        return -1;
    }

    for (int i = 0; i < 4; i++) {
        if (gpiod_line_set_value(lines[i], 0)) {
            log_event("Failed to set initial value for GPIO line");
            return -1;
        }
    }

    return 0;
}

void cleanup() {
    for (int i = 0; i < 4; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }

    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    if (setup_gpio() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (setup_pwm() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    for (int duty_cycle = 0; duty_cycle <= DUTY_CYCLE_MAX && running; duty_cycle++) {
        for (int i = 0; i < 4; i++) {
            if (gpiod_line_set_value(lines[i], duty_cycle)) {
                log_event("Failed to set PWM duty cycle");
                running = 0;
            }
        }
        usleep(PWM_PERIOD_NS / DUTY_CYCLE_MAX);
    }

    cleanup();
    return EXIT_SUCCESS;
}

