        for (int i = 0; i < 4; i++) {
            if (gpiod_line_set_value(lines[i], duty_cycle)) {
                log_event("Failed to set PWM duty cycle");
                running = 0;
            }
        }
        usleep(PWM_PERIOD_NS / DUTY_CYCLE_MAX);
    }

    cleanup();
    return EXIT_SUCCESS;
}
