    if (ret < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_chip_close(chip);
}

void init_buffer() {
    memset(&buffer, 0, sizeof(buffer));
}

void add_to_buffer(int16_t x, int16_t y, int16_t z) {
    if (buffer.count < BUFFER_SIZE) {
        buffer.data[buffer.head][0] = x;
        buffer.data[buffer.head][1] = y;
        buffer.data[buffer.head][2] = z;
        buffer.head = (buffer.head + 1) % BUFFER_SIZE;
        buffer.count++;
    } else {
        buffer.head = (buffer.head + 1) % BUFFER_SIZE;
        buffer.data[buffer.head][0] = x;
        buffer.data[buffer.head][1] = y;
        buffer.data[buffer.head][2] = z;
    }
}

