#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>
#include <gpiod.h>
#include <spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE_OFFSET 8
#define GPIO_LINE_NAME "CS0"
#define LOG_FILE "gyro_log.txt"
#define READ_INTERVAL 10000000  // 10 ms in nanoseconds
#define MAX_RETRIES 3

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int read_mpu9250(struct spidev *spi, uint8_t *buffer, size_t length) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (spidev_transfer(spi, buffer, length) == 0) {
            return 0;
        }
        retries++;
        usleep(1000);  // Wait 1 ms before retrying
    }
    return -1;
}

int main() {
    struct spidev *spi;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    FILE *log_file;
    uint8_t buffer[6];
    struct timespec ts;
    char timestamp[64];
    int ret;

    // Initialize SPI
    spi = spidev_open(SPI_DEVICE, SPI_SPEED, SPI_MODE, SPI_BITS_PER_WORD);
