#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x68
#define LED_PIN 21
#define SAMPLE_INTERVAL 100000  // 100 ms in microseconds
#define THRESHOLD 45.0

static int i2c_handle = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;

void cleanup() {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_handle >= 0) {
        close(i2c_handle);
    }
    gpioTerminate();
}

void signal_handler(int signum) {
    cleanup();
    exit(signum);
}

int read_mpu6050(float *accel_x, float *accel_y, float *accel_z, float *gyro_x, float *gyro_y, float *gyro_z) {
    uint8_t buffer[14];
    if (read(i2c_handle, buffer, sizeof(buffer)) != sizeof(buffer)) {
        perror("Failed to read from MPU-6050");
        return -1;
    }

    *accel_x = (buffer[0] << 8 | buffer[1]) / 16384.0;
    *accel_y = (buffer[2] << 8 | buffer[3]) / 16384.0;
    *accel_z = (buffer[4] << 8 | buffer[5]) / 16384.0;
    *gyro_x = (buffer[8] << 8 | buffer[9]) / 16384.0;
    *gyro_y = (buffer[10] << 8 | buffer[11]) / 16384.0;
    *gyro_z = (buffer[12] << 8 | buffer[13]) / 16384.0;

    return 0;
}

float calculate_roll(float accel_x, float accel_y, float accel_z) {
    return atan2(accel_y, sqrt(accel_x * accel_x + accel_z * accel_z)) * 180.0 / M_PI;
}

float calculate_pitch(float accel_x, float accel_y, float accel_z) {
    return atan2(-accel_x, sqrt(accel_y * accel_y + accel_z * accel_z)) * 180.0 / M_PI;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to set signal handler\n");
        gpioTerminate();
        return 1;
    }

    i2c_handle = open("/dev/i2c-1", O_RDWR);
    if (i2c_handle < 0) {
        perror("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_handle, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_handle);
        gpioTerminate();
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        close(i2c_handle);
        gpioTerminate();
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        close(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpiod_line_request_output(led_line, "tilt_led", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line as output\n");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_handle);
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen("tilt_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (1) {
        float accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
        if (read_mpu6050(&accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) < 0) {
            continue;
        }

        float roll = calculate_roll(accel_x, accel_y, accel_z);
        float pitch = calculate_pitch(accel_x, accel_y, accel_z);

        printf("Roll: %.2f, Pitch: %.2f\n", roll, pitch);

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
                tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
                tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec,
                roll, pitch);

        if (fabs(roll) > THRESHOLD || fabs(pitch) > THRESHOLD) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }

        usleep(SAMPLE_INTERVAL);
    }

    fclose(log_file);
    cleanup();
    return 0;
}

