        close(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (1) {
        float accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
        if (read_mpu6050(&accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) < 0) {
            continue;
        }

        float roll = calculate_roll(accel_x, accel_y, accel_z);
        float pitch = calculate_pitch(accel_x, accel_y, accel_z);

        printf("Roll: %.2f, Pitch: %.2f\n", roll, pitch);

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
                tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
                tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec,
                roll, pitch);

        if (fabs(roll) > THRESHOLD || fabs(pitch) > THRESHOLD) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }

        usleep(SAMPLE_INTERVAL);
    }

    fclose(log_file);
    cleanup();
    return 0;
}
