#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SI1145_ADDRESS 0x29
#define LED_PIN 17
#define MAX_RETRIES 3
#define RETRY_DELAY 10
#define READ_INTERVAL 100

int i2c_fd = -1;
FILE *log_file = NULL;
int led_fd = -1;

void close_resources() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (led_fd != -1) {
        close(led_fd);
    }
}

void handle_signal(int signum) {
    close_resources();
    exit(signum);
}

int read_si1145(uint8_t reg, uint8_t *value) {
    uint8_t buf[2];
    buf[0] = reg;
    if (write(i2c_fd, buf, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }
    if (read(i2c_fd, buf, 1) != 1) {
        perror("Failed to read from I2C device");
        return -1;
    }
    *value = buf[0];
    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set signal handler");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI1145_ADDRESS) == -1) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    led_fd = open("/sys/class/gpio/gpio17/value", O_WRONLY);
    if (led_fd == -1) {
        perror("Failed to open LED GPIO");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        close(led_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        uint8_t ambient_light, proximity;
        int retries = 0;

        while (retries < MAX_RETRIES) {
            if (read_si1145(0x20, &ambient_light) == 0 && read_si1145(0x21, &proximity) == 0) {
                break;
            }
            retries++;
            usleep(RETRY_DELAY * 1000);
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read from SI1145 after %d retries\n", MAX_RETRIES);
            continue;
        }

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s,AmbientLight:%04X,Proximity:%04X\n", timestamp, ambient_light, proximity);
        fflush(log_file);

        if (proximity > 100) {
            write(led_fd, "1", 1);
        } else {
            write(led_fd, "0", 1);
        }
    }

    close_resources();
    return EXIT_SUCCESS;
}

