#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>
#include <libgpiod/spi.h>

#define SPI_CHANNEL 0
#define SPI_CE_PIN 8
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SAMPLE_RATE 100
#define DELAY_MS 10
#define MAX_RETRIES 3

struct spi_device *spi_dev = NULL;
FILE *csv_file = NULL;
struct gpiod_chip *chip = NULL;

void signal_handler(int signum) {
    if (signum == SIGINT) {
        if (spi_dev) {
            gpiod_spi_close(spi_dev);
        }
        if (csv_file) {
            fclose(csv_file);
        }
        if (chip) {
            gpiod_chip_close(chip);
        }
        exit(EXIT_SUCCESS);
    }
}

uint16_t read_register(uint8_t reg_addr) {
    uint8_t tx_buf[2] = {reg_addr | 0x80, 0x00};
    uint8_t rx_buf[2];
    int ret;

    ret = gpiod_spi_xfer(spi_dev, tx_buf, rx_buf, 2);
    if (ret < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(-ret));
        return 0;
    }

    return (rx_buf[1] << 8) | rx_buf[0];
}

int main() {
    struct timespec ts;
    uint16_t x_rate, y_rate;
    int retries = 0;

    signal(SIGINT, signal_handler);

    while (retries < MAX_RETRIES) {
        chip = gpiod_chip_open_by_name("gpiochip0");
        if (!chip) {
            fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
            retries++;
            continue;
        }

        spi_dev = gpiod_spi_open(chip, SPI_CHANNEL, SPI_CE_PIN, SPI_SPEED, SPI_MODE);
        if (!spi_dev) {
            fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
            gpiod_chip_close(chip);
            retries++;
            continue;
        }

        csv_file = fopen("gyro_data.csv", "w");
        if (!csv_file) {
            fprintf(stderr, "Failed to open CSV file: %s\n", strerror(errno));
            gpiod_spi_close(spi_dev);
            gpiod_chip_close(chip);
            retries++;
            continue;
        }

        fprintf(csv_file, "Timestamp,RawXRate,RawYRate\n");

        while (1) {
            clock_gettime(CLOCK_REALTIME, &ts);
            x_rate = read_register(0x00);
            y_rate = read_register(0x02);

            if (x_rate == 0 && y_rate == 0) {
                fprintf(stderr, "Failed to read register values\n");
                break;
            }

            fprintf(csv_file, "%ld.%06ld,%d,%d\n", ts.tv_sec, ts.tv_nsec / 1000, x_rate, y_rate);
            fflush(csv_file);

            usleep(DELAY_MS * 1000);
        }

        fclose(csv_file);
        gpiod_spi_close(spi_dev);
        gpiod_chip_close(chip);

        retries++;
    }

    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to initialize SPI interface after %d retries\n", MAX_RETRIES);
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}

