#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define SENSOR1_PIN 23
#define SENSOR2_PIN 24
#define ALERT_PIN 17
#define LOG_FILE "seismic_events.txt"
#define MIN_DURATION 500
#define ALERT_DURATION 2000

struct gpiod_chip *chip;
struct gpiod_line *sensor1_line, *sensor2_line, *alert_line;
FILE *log_file;

void log_event(const char *message) {
    time_t now = time(NULL);
    char *iso_time = ctime(&now);
    iso_time[strlen(iso_time) - 1] = '\0'; // Remove newline character
    fprintf(log_file, "%s - %s\n", iso_time, message);
    fflush(log_file);
}

void alert_handler(void *user_data) {
    static int sensor1_state = 0, sensor2_state = 0;
    static clock_t start_time = 0;

    int current_sensor1_state = gpiod_line_get_value(sensor1_line);
    int current_sensor2_state = gpiod_line_get_value(sensor2_line);

    if (current_sensor1_state == 1 && current_sensor2_state == 1) {
        if (start_time == 0) {
            start_time = clock();
        } else {
            clock_t current_time = clock();
            if (current_time - start_time >= MIN_DURATION * 1000) {
                gpiod_line_set_value(alert_line, 1);
                log_event("Seismic event detected!");
                clock_t alert_start_time = clock();
                while (clock() - alert_start_time < ALERT_DURATION * 1000) {
                    // Wait for the alert duration
                }
                gpiod_line_set_value(alert_line, 0);
                start_time = 0;
            }
        }
    } else {
        start_time = 0;
    }
}

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        if (log_file) fclose(log_file);
        if (alert_line) gpiod_line_set_value(alert_line, 0);
        if (chip) gpiod_chip_close(chip);
        exit(signum);
    }
}

int main() {
    struct gpiod_request_config config = {
        .consumer = "seismic_monitor",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
        .default_val = 0,
        .flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN,
    };

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    sensor1_line = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (!sensor1_line) {
        perror("Failed to get sensor1 line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    sensor2_line = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (!sensor2_line) {
        perror("Failed to get sensor2 line");
        gpiod_line_release(sensor1_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    alert_line = gpiod_chip_get_line(chip, ALERT_PIN);
    if (!alert_line) {
        perror("Failed to get alert line");
        gpiod_line_release(sensor1_line);
        gpiod_line_release(sensor2_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(sensor1_line, &config) < 0) {
        perror("Failed to request sensor1 line");
        gpiod_line_release(sensor2_line);
        gpiod_line_release(sensor1_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(sensor2_line, &config) < 0) {
