#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LAMPS {17, 18, 27}
#define PWM_FREQ 100
#define PWM_RANGE 255

volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

void handle_sigterm(int sig) {
    running = 0;
}

void init_pwm(struct gpiod_chip *chip, int pin, int freq, int range) {
    struct gpiod_line *line;
    struct gpiod_line_request req = {
        .consumer = "sunset_simulator",
        .type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT,
        .default_val = 0,
        .flags = 0,
    };

    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("Failed to get GPIO line");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request(line, &req)) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_set_config(line, GPIOD_LINE_CONFIG_OUTPUT, freq, range)) {
        perror("Failed to set GPIO line configuration");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
}

void fade_lamp(struct gpiod_chip *chip, int pin, int duration) {
    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("Failed to get GPIO line");
        return;
    }

    for (int duty_cycle = PWM_RANGE; duty_cycle >= 0; duty_cycle--) {
        if (!running) {
            break;
        }
        gpiod_line_set_value(line, duty_cycle);
        usleep((duration * 1000000) / PWM_RANGE);
    }

    gpiod_line_set_value(line, 0);
    gpiod_line_release(line);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <duration>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int duration;
    if (sscanf(argv[1], "%d", &duration) != 1 || duration < 1 || duration > 3600) {
        fprintf(stderr, "Invalid duration: %s\n", argv[1]);
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    printf("Starting sunset simulator for %d seconds...\n", duration);

    for (int i = 0; i < 3; i++) {
        init_pwm(chip, GPIO_LAMPS[i], PWM_FREQ, PWM_RANGE);
        fade_lamp(chip, GPIO_LAMPS[i], duration);
    }

    printf("Sunset simulation completed.\n");

    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

