#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINES {17, 22, 23, 24}
#define RED 0
#define YELLOW 1
#define GREEN 2

struct gpio_line *lines[4];
struct gpiod_chip *chip;

void cleanup(int signum) {
    for (int i = 0; i < 4; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(signum);
}

void set_traffic_light(int state) {
    static int previous_state = -1;
    if (previous_state != state) {
        printf("Traffic light state: %s\n", state == RED ? "Red" : state == YELLOW ? "Yellow" : "Green");
        previous_state = state;
    }
}

int main() {
    struct gpiod_line_request_config config = {
        .consumer = "traffic_light",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT,
    };

    // Register signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request GPIO lines
    for (int i = 0; i < 4; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_LINES[i]);
        if (!lines[i]) {
            perror("Failed to get GPIO line");
            cleanup(EXIT_FAILURE);
        }
        if (gpiod_line_request(lines[i], &config)) {
            perror("Failed to request GPIO line");
            cleanup(EXIT_FAILURE);
        }
        gpiod_line_set_value(lines[i], 1); // Initial state: all relays off
    }

    while (1) {
        // Red light
        set_traffic_light(RED);
        gpiod_line_set_value(lines[RED], 0);
        sleep(10);
        gpiod_line_set_value(lines[RED], 1);

        // Red + Yellow light
        set_traffic_light(YELLOW);
        gpiod_line_set_value(lines[YELLOW], 0);
        sleep(2);
        gpiod_line_set_value(lines[YELLOW], 1);

        // Green light
        set_traffic_light(GREEN);
        gpiod_line_set_value(lines[GREEN], 0);
        sleep(10);
        gpiod_line_set_value(lines[GREEN], 1);

        // Yellow light
        set_traffic_light(YELLOW);
        gpiod_line_set_value(lines[YELLOW], 0);
        sleep(3);
        gpiod_line_set_value(lines[YELLOW], 1);
    }

    cleanup(EXIT_SUCCESS);
    return EXIT_SUCCESS;
}

