#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <unistd.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x5A
#define RELAY_PIN 17
#define DEBOUNCE_TIME 100
#define READ_INTERVAL 10

struct gpiod_chip *chip;
struct gpiod_line *relay_line;
int i2c_fd;
FILE *log_file;

void log_error(const char *message) {
    time_t now = time(NULL);
    fprintf(log_file, "%s: %s\n", ctime(&now), message);
    fflush(log_file);
}

void cleanup() {
    if (relay_line) {
        gpiod_line_release(relay_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(EXIT_FAILURE);
}

void handle_signal(int signum) {
    log_error("Received signal, cleaning up...");
    cleanup();
}

int read_mpr121() {
    uint8_t data[3];
    if (read(i2c_fd, data, sizeof(data)) != sizeof(data)) {
        log_error("Failed to read from MPR121");
        return -1;
    }
    return (data[0] & 0x01) != 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_file = fopen("touch_relay.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C bus");
        cleanup();
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        log_error("Failed to set I2C address");
        cleanup();
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        log_error("Failed to open GPIO chip");
        cleanup();
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        log_error("Failed to get GPIO line");
        cleanup();
    }

    if (gpiod_line_request_output(relay_line, "touch_relay", 0) < 0) {
        log_error("Failed to request GPIO line as output");
        cleanup();
    }

    int last_state = 0;
    while (1) {
        int current_state = read_mpr121();
        if (current_state != last_state) {
            if (current_state) {
                gpiod_line_set_value(relay_line, 1);
            } else {
                gpiod_line_set_value(relay_line, 0);
            }
            last_state = current_state;
        }
        usleep(READ_INTERVAL * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

