    exit(EXIT_FAILURE);
}

void handle_signal(int signum) {
    log_error("Received signal, cleaning up...");
    cleanup();
}

int read_mpr121() {
    uint8_t data[3];
    if (read(i2c_fd, data, sizeof(data)) != sizeof(data)) {
        log_error("Failed to read from MPR121");
        return -1;
    }
    return (data[0] & 0x01) != 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_file = fopen("touch_relay.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C bus");
        cleanup();
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        log_error("Failed to set I2C address");
        cleanup();
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        log_error("Failed to open GPIO chip");
        cleanup();
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        log_error("Failed to get GPIO line");
        cleanup();
    }

    if (gpiod_line_request_output(relay_line, "touch_relay", 0) < 0) {
        log_error("Failed to request GPIO line as output");
        cleanup();
    }

    int last_state = 0;
    while (1) {
        int current_state = read_mpr121();
        if (current_state != last_state) {
            if (current_state) {
                gpiod_line_set_value(relay_line, 1);
            } else {
                gpiod_line_set_value(relay_line, 0);
            }
            last_state = current_state;
        }
        usleep(READ_INTERVAL * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}
```

This C program initializes the MPR121 capacitive touch controller on I2C bus 1, reads the touch status every 10 ms, debounces touch events with a 100 ms delay, and toggles a 5 V relay connected to GPIO17 (BCM) each time electrode 0 is touched. It logs all I2C, GPIO, and configuration errors with timestamps to a file named `touch_relay.log`. The program handles SIGINT and SIGTERM signals to cleanly close the I2C interface, release the GPIO pin, and close the log file.

