#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define SOLENOID1_PIN 17
#define SOLENOID2_PIN 27
#define DISPENSE_INTERVAL 1000
#define HALF_INTERVAL (DISPENSE_INTERVAL / 2)

struct gpiod_chip *chip;
struct gpiod_line *solenoid1, *solenoid2;
FILE *log_file;

void log_event(int solenoid1_state, int solenoid2_state, int duration) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, Solenoid1: %d, Solenoid2: %d, Duration: %dms\n",
            tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
            tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec,
            solenoid1_state, solenoid2_state, duration);
    fflush(log_file);
}

void sigint_handler(int signum) {
    if (signum == SIGINT) {
        if (solenoid1) gpiod_line_set_value(solenoid1, 0);
        if (solenoid2) gpiod_line_set_value(solenoid2, 0);
        if (chip) gpiod_chip_close(chip);
        if (log_file) fclose(log_file);
        exit(0);
    }
}

int init_driver() {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return -1;
    }

    solenoid1 = gpiod_chip_get_line(chip, SOLENOID1_PIN);
    if (!solenoid1) {
        fprintf(stderr, "Failed to get GPIO line for solenoid 1\n");
        gpiod_chip_close(chip);
        return -1;
    }

    solenoid2 = gpiod_chip_get_line(chip, SOLENOID2_PIN);
    if (!solenoid2) {
        fprintf(stderr, "Failed to get GPIO line for solenoid 2\n");
        gpiod_line_release(solenoid1);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(solenoid1, "solenoid1", 0) < 0) {
        fprintf(stderr, "Failed to request output for solenoid 1\n");
        gpiod_line_release(solenoid2);
        gpiod_line_release(solenoid1);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(solenoid2, "solenoid2", 0) < 0) {
        fprintf(stderr, "Failed to request output for solenoid 2\n");
        gpiod_line_release(solenoid2);
        gpiod_line_release(solenoid1);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

int main() {
    if (init_driver() != 0) {
        return 1;
    }

    log_file = fopen("dispense_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_line_release(solenoid2);
        gpiod_line_release(solenoid1);
        gpiod_chip_close(chip);
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        gpiod_line_set_value(solenoid1, 1);
        gpiod_line_set_value(solenoid2, 0);
        log_event(1, 0, HALF_INTERVAL);
        gpiod_line_set_value(solenoid1, 0);
        gpiod_line_set_value(solenoid2, 1);
        log_event(0, 1, HALF_INTERVAL);
        gpiod_line_set_value(solenoid1, 0);
        gpiod_line_set_value(solenoid2, 0);
        log_event(0, 0, DISPENSE_INTERVAL);
        sleep(5);
    }

    fclose(log_file);
    gpiod_line_release(solenoid2);
    gpiod_line_release(solenoid1);
    gpiod_chip_close(chip);
    return 0;
}

