#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23
#define ENA 24
#define ENB 25
#define PWM_FREQ 1000
#define PWM_RANGE 255
#define PID_KP 0.1
#define PID_KI 0.01
#define PID_KD 0.05
#define PID_SAMPLE_TIME 50
#define OBSTACLE_DISTANCE 20.0
#define LOG_FILE "balance_log.txt"

struct pid_controller {
    float kp, ki, kd;
    float setpoint;
    float prev_error;
    float integral;
};

struct motor {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[4];
    int enable_pin;
};

void init_motor(struct motor *motor, const char *chip_name, int enable_pin) {
    motor->chip = gpiod_chip_open_by_name(chip_name);
    if (!motor->chip) {
        perror("Failed to open GPIO chip");
        exit(1);
    }
    motor->enable_pin = enable_pin;
    for (int i = 0; i < 4; i++) {
        motor->lines[i] = gpiod_chip_get_line(motor->chip, MOTOR_A_FORWARD + i);
        if (!motor->lines[i]) {
            perror("Failed to get GPIO line");
            exit(1);
        }
        gpiod_line_request_output(motor->lines[i], "motor", 0);
    }
    gpiod_line_request_output(motor->chip, "enable", enable_pin, 0);
}

void set_motor_speed(struct motor *motor, int speed) {
    if (speed < -PWM_RANGE) speed = -PWM_RANGE;
    if (speed > PWM_RANGE) speed = PWM_RANGE;
    gpiod_line_set_value(motor->lines[0], speed > 0);
    gpiod_line_set_value(motor->lines[1], speed < 0);
    gpiod_line_set_value(motor->lines[2], speed > 0);
    gpiod_line_set_value(motor->lines[3], speed < 0);
    gpiod_line_set_value(motor->chip, "enable", 1);
}

void init_pid(struct pid_controller *pid, float kp, float ki, float kd, float setpoint) {
    pid->kp = kp;
    pid->ki = ki;
    pid->kd = kd;
    pid->setpoint = setpoint;
    pid->prev_error = 0;
    pid->integral = 0;
}

float pid_compute(struct pid_controller *pid, float measured_value, int sample_time) {
    float error = pid->setpoint - measured_value;
    pid->integral += error * sample_time / 1000.0;
    float derivative = (error - pid->prev_error) * 1000.0 / sample_time;
    float output = pid->kp * error + pid->ki * pid->integral + pid->kd * derivative;
    pid->prev_error = error;
    return output;
}

void log_data(FILE *log_file, time_t timestamp, float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", ctime(&timestamp), tilt_error, distance, motor_a_speed, motor_b_speed);
}

void handle_sigint(int sig) {
    exit(0);
}

int main() {
    struct motor motor_a, motor_b;
    struct pid_controller pid;
    FILE *log_file;
    time_t timestamp;
    float tilt_error, distance, motor_a_speed, motor_b_speed;
    int obstacle_avoidance = 0;

    init_motor(&motor_a, "gpiochip0", ENA);
    init_motor(&motor_b, "gpiochip0", ENB);
    init_pid(&pid, PID_KP, PID_KI, PID_KD, 0.0);

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(motor_a.lines[0]);
        gpiod_line_release(motor_a.lines[1]);
        gpiod_line_release(motor_a.lines[2]);
        gpiod_line_release(motor_a.lines[3]);
        gpiod_line_release(motor_b.lines[0]);
        gpiod_line_release(motor_b.lines[1]);
        gpiod_line_release(motor_b.lines[2]);
        gpiod_line_release(motor_b.lines[3]);
        gpiod_chip_close(motor_a.chip);
        gpiod_chip_close(motor_b.chip);
        exit(1);
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        timestamp = time(NULL);
        tilt_error = (float)(rand() % 201) - 100.0; // Random float between -10.0 and 10.0
        distance = (float)(rand() % 40001) / 100.0; // Random float between 2.0 and 400.0 cm

        if (distance < OBSTACLE_DISTANCE) {
            obstacle_avoidance = 1;
            motor_a_speed = -PWM_RANGE / 2;
            motor_b_speed = -PWM_RANGE / 2;
        } else {
            obstacle_avoidance = 0;
            motor_a_speed = (int)pid_compute(&pid, tilt_error, PID_SAMPLE_TIME);
            motor_b_speed = (int)pid_compute(&pid, tilt_error, PID_SAMPLE_TIME);
        }

        set_motor_speed(&motor_a, motor_a_speed);
        set_motor_speed(&motor_b, motor_b_speed);

        log_data(log_file, timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);

        usleep(PID_SAMPLE_TIME * 1000);
    }

    fclose(log_file);
    gpiod_line_release(motor_a.lines[0]);
    gpiod_line_release(motor_a.lines[1]);
    gpiod_line_release(motor_a.lines[2]);
    gpiod_line_release(motor_a.lines[3]);
