#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define SENSOR_CHIP "gpiochip0"
#define SENSOR_LINE 4
#define RELAY_CHIP "gpiochip0"
#define RELAY_LINE 17
#define DEBOUNCE_DELAY 50

static struct gpiod_chip *sensor_chip = NULL;
static struct gpiod_chip *relay_chip = NULL;
static struct gpiod_line *sensor_line = NULL;
static struct gpiod_line *relay_line = NULL;

void cleanup(int signum) {
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (sensor_chip) {
        gpiod_chip_close(sensor_chip);
    }
    if (relay_line) {
        gpiod_line_release(relay_line);
    }
    if (relay_chip) {
        gpiod_chip_close(relay_chip);
    }
    printf("Cleanup complete. Exiting.\n");
    exit(signum);
}

int main() {
    int ret;

    // Register signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Open GPIO chips
    sensor_chip = gpiod_chip_open_by_name(SENSOR_CHIP);
    if (!sensor_chip) {
        perror("Failed to open sensor GPIO chip");
        return EXIT_FAILURE;
    }

    relay_chip = gpiod_chip_open_by_name(RELAY_CHIP);
    if (!relay_chip) {
        perror("Failed to open relay GPIO chip");
        gpiod_chip_close(sensor_chip);
        return EXIT_FAILURE;
    }

    // Request sensor line
    sensor_line = gpiod_chip_get_line(sensor_chip, SENSOR_LINE);
    if (!sensor_line) {
        perror("Failed to get sensor line");
        gpiod_chip_close(sensor_chip);
        gpiod_chip_close(relay_chip);
        return EXIT_FAILURE;
    }

    // Request relay line
    relay_line = gpiod_chip_get_line(relay_chip, RELAY_LINE);
    if (!relay_line) {
        perror("Failed to get relay line");
        gpiod_line_release(sensor_line);
        gpiod_chip_close(sensor_chip);
        gpiod_chip_close(relay_chip);
        return EXIT_FAILURE;
    }

    // Configure sensor line as input with pull-down
    ret = gpiod_line_request_input(sensor_line, "touch_sensor");
    if (ret < 0) {
        perror("Failed to request sensor line as input");
        gpiod_line_release(sensor_line);
        gpiod_chip_close(sensor_chip);
        gpiod_chip_close(relay_chip);
        return EXIT_FAILURE;
    }

    // Configure relay line as output with initial state off
    ret = gpiod_line_request_output(relay_line, "relay", 0);
    if (ret < 0) {
        perror("Failed to request relay line as output");
        gpiod_line_release(sensor_line);
        gpiod_chip_close(sensor_chip);
        gpiod_chip_close(relay_chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        int sensor_value;

        // Read sensor value
        sensor_value = gpiod_line_get_value(sensor_line);
        if (sensor_value < 0) {
            perror("Failed to read sensor value");
            continue;
        }

        // Check for touch
        if (sensor_value == 1) {
            // Toggle relay
            int relay_state = gpiod_line_get_value(relay_line);
            if (relay_state < 0) {
                perror("Failed to read relay state");
                continue;
            }
            gpiod_line_set_value(relay_line, !relay_state);

            // Apply debounce delay
            usleep(DEBOUNCE_DELAY * 1000);
        }

        // Sleep for a short period to reduce CPU usage
        usleep(10000);
    }

    // Cleanup (should never reach here)
    cleanup(0);
    return EXIT_SUCCESS;
}

