#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <alsa/asoundlib.h>
#include <gpiod.h>
#include <math.h>
#include <unistd.h>

#define ALSA_AVAILABLE
#define LED_PIN_RED 17
#define LED_PIN_GREEN 18
#define LED_PIN_BLUE 27
#define LED_PERIOD_NS 10000000  // 10 ms
#define BUFFER_SIZE 1024
#define SAMPLE_RATE 8000
#define SAMPLE_SIZE 2
#define MONO 1
#define SINE_WAVE_FREQ 1000
#define SINE_WAVE_AMPLITUDE 32767

static int running = 1;
static snd_pcm_t *pcm_handle = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *red_line = NULL, *green_line = NULL, *blue_line = NULL;

static void cleanup() {
    if (red_line) gpiod_line_release(red_line);
    if (green_line) gpiod_line_release(green_line);
    if (blue_line) gpiod_line_release(blue_line);
    if (chip) gpiod_chip_close(chip);
    if (pcm_handle) snd_pcm_close(pcm_handle);
}

static void signal_handler(int signum) {
    running = 0;
}

static void init_leds() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(EXIT_FAILURE);
    }

    red_line = gpiod_chip_get_line(chip, LED_PIN_RED);
    if (!red_line) {
        fprintf(stderr, "Failed to get GPIO line for red LED\n");
        exit(EXIT_FAILURE);
    }

    green_line = gpiod_chip_get_line(chip, LED_PIN_GREEN);
    if (!green_line) {
        fprintf(stderr, "Failed to get GPIO line for green LED\n");
        exit(EXIT_FAILURE);
    }

    blue_line = gpiod_chip_get_line(chip, LED_PIN_BLUE);
    if (!blue_line) {
        fprintf(stderr, "Failed to get GPIO line for blue LED\n");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(red_line, "red_led", 0) < 0) {
        fprintf(stderr, "Failed to request output for red LED\n");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(green_line, "green_led", 0) < 0) {
        fprintf(stderr, "Failed to request output for green LED\n");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(blue_line, "blue_led", 0) < 0) {
        fprintf(stderr, "Failed to request output for blue LED\n");
        exit(EXIT_FAILURE);
    }
}

static void init_audio() {
#ifdef ALSA_AVAILABLE
    int err;
    snd_pcm_hw_params_t *hw_params;

    pcm_handle = snd_pcm_open(NULL, "default", SND_PCM_STREAM_CAPTURE, 0);
    if (pcm_handle == NULL) {
        fprintf(stderr, "Failed to open PCM device\n");
        exit(EXIT_FAILURE);
    }

    hw_params = snd_pcm_hw_params_malloc();
    if (hw_params == NULL) {
        fprintf(stderr, "Failed to allocate hardware parameters\n");
        exit(EXIT_FAILURE);
    }

    snd_pcm_hw_params_any(pcm_handle, hw_params);
    snd_pcm_hw_params_set_access(pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED);
    snd_pcm_hw_params_set_format(pcm_handle, hw_params, SND_PCM_FORMAT_S16_LE);
    snd_pcm_hw_params_set_rate_near(pcm_handle, hw_params, &SAMPLE_RATE, 0);
    snd_pcm_hw_params_set_channels(pcm_handle, hw_params, MONO);
    snd_pcm_hw_params_set_period_size_near(pcm_handle, hw_params, &BUFFER_SIZE, 0);

    err = snd_pcm_hw_params(pcm_handle, hw_params);
    if (err < 0) {
        fprintf(stderr, "Failed to set hardware parameters: %s\n", snd_strerror(err));
        exit(EXIT_FAILURE);
    }

    snd_pcm_hw_params_free(hw_params);
#endif
}

static void set_led_color(int red, int green, int blue) {
    gpiod_line_set_value(red_line, red);
    gpiod_line_set_value(green_line, green);
    gpiod_line_set_value(blue_line, blue);
}

static void process_audio() {
    char buffer[BUFFER_SIZE * SAMPLE_SIZE];
    int err, frames_read;
    double rms, scale = 1.0;

    if (argc > 1) {
        scale = atof(argv[1]);
        if (scale <= 0) {
            fprintf(stderr, "Invalid scale value: %s\n", argv[1]);
            exit(EXIT_FAILURE);
        }
    }

    while (running) {
#ifdef ALSA_AVAILABLE
        frames_read = snd_pcm_readi(pcm_handle, buffer, BUFFER_SIZE);
        if (frames_read < 0) {
            if (frames_read == -EPIPE) {
                snd_pcm_prepare(pcm_handle);
            } else if (frames_read == -ESTRPIPE) {
                snd_pcm_resume(pcm_handle);
            } else {
                fprintf(stderr, "Failed to read audio: %s\n", snd_strerror(frames_read));
                exit(EXIT_FAILURE);
            }
        }
#endif

        rms = 0.0;
        for (int i = 0; i < frames_read * MONO; i++) {
            int sample = (buffer[i * SAMPLE_SIZE] << 8) | buffer[i * SAMPLE_SIZE + 1];
            rms += sample * sample;
        }
        rms = sqrt(rms / (frames_read * MONO));

        int red = (int)(scale * rms * 255);
        int green = (int)(scale * rms * 255);
        int blue = (int)(scale * rms * 255);

        set_led_color(red, green, blue);

        usleep(LED_PERIOD_NS);
    }
}

int main(int argc, char *argv[]) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    init_leds();
    init_audio();

    printf("Mood light started\n");

    process_audio();

    cleanup();
    printf("Mood light stopped\n");

    return 0;
}

