    snd_pcm_hw_params_set_period_size_near(pcm_handle, hw_params, &BUFFER_SIZE, 0);

    err = snd_pcm_hw_params(pcm_handle, hw_params);
    if (err < 0) {
        fprintf(stderr, "Failed to set hardware parameters: %s\n", snd_strerror(err));
        exit(EXIT_FAILURE);
    }

    snd_pcm_hw_params_free(hw_params);
#endif
}

static void set_led_color(int red, int green, int blue) {
    gpiod_line_set_value(red_line, red);
    gpiod_line_set_value(green_line, green);
    gpiod_line_set_value(blue_line, blue);
}

static void process_audio() {
    char buffer[BUFFER_SIZE * SAMPLE_SIZE];
    int err, frames_read;
    double rms, scale = 1.0;

    if (argc > 1) {
        scale = atof(argv[1]);
        if (scale <= 0) {
            fprintf(stderr, "Invalid scale value: %s\n", argv[1]);
            exit(EXIT_FAILURE);
        }
    }

    while (running) {
#ifdef ALSA_AVAILABLE
        frames_read = snd_pcm_readi(pcm_handle, buffer, BUFFER_SIZE);
        if (frames_read < 0) {
            if (frames_read == -EPIPE) {
                snd_pcm_prepare(pcm_handle);
            } else if (frames_read == -ESTRPIPE) {
                snd_pcm_resume(pcm_handle);
            } else {
                fprintf(stderr, "Failed to read audio: %s\n", snd_strerror(frames_read));
                exit(EXIT_FAILURE);
            }
        }
#endif

        rms = 0.0;
        for (int i = 0; i < frames_read * MONO; i++) {
            int sample = (buffer[i * SAMPLE_SIZE] << 8) | buffer[i * SAMPLE_SIZE + 1];
            rms += sample * sample;
        }
        rms = sqrt(rms / (frames_read * MONO));

        int red = (int)(scale * rms * 255);
        int green = (int)(scale * rms * 255);
        int blue = (int)(scale * rms * 255);

        set_led_color(red, green, blue);

        usleep(LED_PERIOD_NS);
    }
}

int main(int argc, char *argv[]) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    init_leds();
    init_audio();

    printf("Mood light started\n");

    process_audio();

    cleanup();
    printf("Mood light stopped\n");

    return 0;
}
