        value = (i < steps / 2) ? i * 2 : (steps - i) * 2;
        set_relay(chip, line, value);
        clock_gettime(CLOCK_MONOTONIC, &now);
        if (timespec_diff(&now, &start) >= step) {
            break;
        }
    }

    set_relay(chip, line, 0);
}

int main() {
    struct gpiod_chip *chip1, *chip2, *chip3, *chip4;
    int ret;

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    chip1 = gpiod_chip_open_by_name(RELAY1_CHIP);
    if (!chip1) {
        fprintf(stderr, "Failed to open GPIO chip %s\n", RELAY1_CHIP);
        return EXIT_FAILURE;
    }

    chip2 = gpiod_chip_open_by_name(RELAY2_CHIP);
    if (!chip2) {
        fprintf(stderr, "Failed to open GPIO chip %s\n", RELAY2_CHIP);
        gpiod_chip_close(chip1);
        return EXIT_FAILURE;
    }

    chip3 = gpiod_chip_open_by_name(RELAY3_CHIP);
    if (!chip3) {
        fprintf(stderr, "Failed to open GPIO chip %s\n", RELAY3_CHIP);
        gpiod_chip_close(chip1);
        gpiod_chip_close(chip2);
        return EXIT_FAILURE;
    }

    chip4 = gpiod_chip_open_by_name(RELAY4_CHIP);
    if (!chip4) {
        fprintf(stderr, "Failed to open GPIO chip %s\n", RELAY4_CHIP);
        gpiod_chip_close(chip1);
        gpiod_chip_close(chip2);
        gpiod_chip_close(chip3);
        return EXIT_FAILURE;
    }

    while (running) {
        pwm_relay(chip1, RELAY1_LINE, SUNRISE_DURATION, PWM_STEPS);
        pwm_relay(chip2, RELAY2_LINE, SUNRISE_DURATION, PWM_STEPS);
        pwm_relay(chip3, RELAY3_LINE, SUNRISE_DURATION, PWM_STEPS);
        pwm_relay(chip4, RELAY4_LINE, SUNRISE_DURATION, PWM_STEPS);

        sleep(DAYTIME_DURATION);

        pwm_relay(chip1, RELAY1_LINE, SUNSET_DURATION, PWM_STEPS);
        pwm_relay(chip2, RELAY2_LINE, SUNSET_DURATION, PWM_STEPS);
        pwm_relay(chip3, RELAY3_LINE, SUNSET_DURATION, PWM_STEPS);
        pwm_relay(chip4, RELAY4_LINE, SUNSET_DURATION, PWM_STEPS);

        sleep(NIGHTTIME_DURATION);
    }

    set_relay(chip1, RELAY1_LINE, 0);
    set_relay(chip2, RELAY2_LINE, 0);
    set_relay(chip3, RELAY3_LINE, 0);
    set_relay(chip4, RELAY4_LINE, 0);

    gpiod_chip_close(chip1);
    gpiod_chip_close(chip2);
    gpiod_chip_close(chip3);
    gpiod_chip_close(chip4);

    return EXIT_SUCCESS;
}
