#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x68
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_GYRO_XOUT_H 0x43
#define MPU6050_GYRO_CONFIG 0x1B
#define MPU6050_FS_250 0x00
#define MPU6050_FS_500 0x08
#define MPU6050_FS_1000 0x10
#define MPU6050_FS_2000 0x18

struct i2c_device {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int fd;
};

struct i2c_device i2c_dev;

void i2c_init(void) {
    const char *chip_name = "gpiochip0";
    i2c_dev.chip = gpiod_chip_open_by_name(chip_name);
    if (!i2c_dev.chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    i2c_dev.line = gpiod_chip_get_line(i2c_dev.chip, 2); // SDA
    if (!i2c_dev.line) {
        perror("Failed to get SDA line");
        gpiod_chip_close(i2c_dev.chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(i2c_dev.line, "i2c_sda", 0) < 0) {
        perror("Failed to request SDA line");
        gpiod_chip_close(i2c_dev.chip);
        exit(EXIT_FAILURE);
    }

    i2c_dev.line = gpiod_chip_get_line(i2c_dev.chip, 3); // SCL
    if (!i2c_dev.line) {
        perror("Failed to get SCL line");
        gpiod_line_release(i2c_dev.line);
        gpiod_chip_close(i2c_dev.chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(i2c_dev.line, "i2c_scl", 0) < 0) {
        perror("Failed to request SCL line");
        gpiod_line_release(i2c_dev.line);
        gpiod_chip_close(i2c_dev.chip);
        exit(EXIT_FAILURE);
    }

    i2c_dev.fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_dev.fd < 0) {
        perror("Failed to open I2C bus");
        gpiod_line_release(i2c_dev.line);
        gpiod_chip_close(i2c_dev.chip);
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_dev.fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_dev.fd);
        gpiod_line_release(i2c_dev.line);
        gpiod_chip_close(i2c_dev.chip);
        exit(EXIT_FAILURE);
    }

    uint8_t power_mgmt_1 = 0;
    if (write(i2c_dev.fd, &power_mgmt_1, 1) != 1) {
        perror("Failed to write to MPU6050");
        close(i2c_dev.fd);
        gpiod_line_release(i2c_dev.line);
        gpiod_chip_close(i2c_dev.chip);
        exit(EXIT_FAILURE);
    }

    uint8_t gyro_config = MPU6050_FS_250;
    if (write(i2c_dev.fd, &gyro_config, 1) != 1) {
        perror("Failed to write to MPU6050");
        close(i2c_dev.fd);
        gpiod_line_release(i2c_dev.line);
        gpiod_chip_close(i2c_dev.chip);
        exit(EXIT_FAILURE);
    }
}

void i2c_read_gyro(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buffer[6];
    if (read(i2c_dev.fd, buffer, 6) != 6) {
        perror("Failed to read from MPU6050");
        return;
    }

    *x = (buffer[0] << 8) | buffer[1];
    *y = (buffer[2] << 8) | buffer[3];
    *z = (buffer[4] << 8) | buffer[5];
}

void log_gyro_data(int16_t x, int16_t y, int16_t z) {
    FILE *log_file = fopen("gyro_log.csv", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fclose(log_file);
}

void signal_handler(int sig) {
    close(i2c_dev.fd);
    gpiod_line_release(i2c_dev.line);
    gpiod_chip_close(i2c_dev.chip);
    exit(EXIT_SUCCESS);
}

int main(void) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_init();

    FILE *log_file = fopen("gyro_log.csv", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_dev.fd);
        gpiod_line_release(i2c_dev.line);
        gpiod_chip_close(i2c_dev.chip);
        exit(EXIT_FAILURE);
    }

    fprintf(log_file, "Timestamp,X_degps,Y_degps,Z_degps\n");
    fclose(log_file);

    int16_t x, y, z;
    while (1) {
        i2c_read_gyro(&x, &y, &z);
        log_gyro_data(x, y, z);
        usleep(10000); // 10 ms
    }

    return 0;
}

