#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22
#define LOG_FILE "irrigation_log.txt"

struct gpiod_chip *chip;
struct gpiod_line *relay1, *relay2, *relay3, *relay4;
FILE *log_file;

void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("Received SIGINT, shutting down...\n");
        gpiod_line_set_value(relay1, 1);
        gpiod_line_set_value(relay2, 1);
        gpiod_line_set_value(relay3, 1);
        gpiod_line_set_value(relay4, 1);
        fclose(log_file);
        gpiod_chip_close(chip);
        exit(0);
    }
}

int main() {
    srand(time(NULL));
    signal(SIGINT, signal_handler);

    // Initialize libgpiod
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request GPIO lines
    relay1 = gpiod_chip_get_line(chip, RELAY1_PIN);
    relay2 = gpiod_chip_get_line(chip, RELAY2_PIN);
    relay3 = gpiod_chip_get_line(chip, RELAY3_PIN);
    relay4 = gpiod_chip_get_line(chip, RELAY4_PIN);

    if (!relay1 || !relay2 || !relay3 || !relay4) {
        perror("Failed to get GPIO lines");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set lines as output
    if (gpiod_line_request_output(relay1, "relay1", 1) < 0 ||
        gpiod_line_request_output(relay2, "relay2", 1) < 0 ||
        gpiod_line_request_output(relay3, "relay3", 1) < 0 ||
        gpiod_line_request_output(relay4, "relay4", 1) < 0) {
        perror("Failed to request GPIO lines as output");
        gpiod_line_release(relay1);
        gpiod_line_release(relay2);
        gpiod_line_release(relay3);
        gpiod_line_release(relay4);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(relay1);
        gpiod_line_release(relay2);
        gpiod_line_release(relay3);
        gpiod_line_release(relay4);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        int moisture = rand() % 100;
