#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <sys/ioctl.h>

#define ADXL345_I2C_ADDRESS 0x53
#define ADXL345_DATAX0 0x32
#define ADXL345_DATAX1 0x33
#define ADXL345_DATAY0 0x34
#define ADXL345_DATAY1 0x35
#define ADXL345_DATAZ0 0x36
#define ADXL345_DATAZ1 0x37
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_POWER_CTL_MEASURE 0x08

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 27

#define FREEFALL_THRESHOLD 0.2
#define FREEFALL_DURATION 0.5
#define ALARM_DURATION 5

struct i2c_device {
    int fd;
};

struct gpio_device {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
};

void i2c_init(struct i2c_device *i2c, const char *device_path) {
    i2c->fd = open(device_path, O_RDWR);
    if (i2c->fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c->fd, I2C_SLAVE, ADXL345_I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c->fd);
        exit(EXIT_FAILURE);
    }
}

void i2c_read(struct i2c_device *i2c, uint8_t reg, uint8_t *data, size_t len) {
    if (write(i2c->fd, &reg, 1) != 1) {
        perror("Failed to write I2C register");
        return;
    }

    if (read(i2c->fd, data, len) != len) {
        perror("Failed to read I2C data");
    }
}

void gpio_init(struct gpio_device *gpio, const char *chip_name, int line_num) {
    gpio->chip = gpiod_chip_open_by_name(chip_name);
    if (!gpio->chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    gpio->line = gpiod_chip_get_line(gpio->chip, line_num);
    if (!gpio->line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio->chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(gpio->line, "alarm", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(gpio->chip);
        exit(EXIT_FAILURE);
    }
}

void gpio_set(struct gpio_device *gpio, int value) {
    if (gpiod_line_set_value(gpio->line, value) < 0) {
        perror("Failed to set GPIO line value");
    }
}

void gpio_cleanup(struct gpio_device *gpio) {
    gpiod_line_release(gpio->line);
    gpiod_chip_close(gpio->chip);
}

void log_freefall(const struct timespec *timestamp, float x, float y, float z) {
    FILE *log_file = fopen("freefall.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "%ld-%02ld-%02ld %02ld:%02ld:%02ld.%09ld,%f,%f,%f\n",
            timestamp->tv_sec, timestamp->tv_nsec / 1000000000,
            timestamp->tv_nsec / 1000000 % 1000,
            timestamp->tv_nsec / 100000 % 1000,
            timestamp->tv_nsec / 1000 % 1000,
            timestamp->tv_nsec % 1000,
            x, y, z);
    fclose(log_file);
}

void handle_sigint(int sig) {
    struct i2c_device i2c = {0};
    struct gpio_device gpio = {0};

    i2c_init(&i2c, "/dev/i2c-1");
    gpio_init(&gpio, GPIO_CHIP, GPIO_LINE);

    gpio_set(&gpio, 0);
    gpio_cleanup(&gpio);
    close(i2c.fd);

    exit(EXIT_SUCCESS);
}

int main() {
    struct i2c_device i2c = {0};
    struct gpio_device gpio = {0};
    struct timespec start_time, current_time;
    int freefall_count = 0;

    signal(SIGINT, handle_sigint);

    i2c_init(&i2c, "/dev/i2c-1");
    gpio_init(&gpio, GPIO_CHIP, GPIO_LINE);

    while (1) {
        uint8_t data[6];
        i2c_read(&i2c, ADXL345_DATAX0, data, sizeof(data));

        int16_t x = (data[1] << 8) | data[0];
        int16_t y = (data[3] << 8) | data[2];
        int16_t z = (data[5] << 8) | data[4];

        float x_g = x / 256.0f;
        float y_g = y / 256.0f;
        float z_g = z / 256.0f;

        if (fabs(x_g) < FREEFALL_THRESHOLD && fabs(y_g) < FREEFALL_THRESHOLD && fabs(z_g) < FREEFALL_THRESHOLD) {
            if (freefall_count == 0) {
                clock_gettime(CLOCK_REALTIME, &start_time);
            }
            freefall_count++;
        } else {
            freefall_count = 0;
        }

        if (freefall_count >= FREEFALL_DURATION * 2) {
            clock_gettime(CLOCK_REALTIME, &current_time);
            if (current_time.tv_sec - start_time.tv_sec >= FREEFALL_DURATION) {
                gpio_set(&gpio, 1);
                log_freefall(&start_time, x_g, y_g, z_g);
                sleep(ALARM_DURATION);
                gpio_set(&gpio, 0);
                freefall_count = 0;
            }
        }

        usleep(100000);
    }

    gpio_cleanup(&gpio);
    close(i2c.fd);

    return 0;
}

