This code provides a complete solution for reading acceleration data from an ADXL345 accelerometer on a Raspberry Pi 3 Model B+ using the libgpiod library for GPIO control and handling I2C communication. It includes error checking, logging, and a signal handler to cleanly exit the program.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define TRIG_PIN 4
#define ECHO_PIN 18
#define MAX_PULSE_WIDTH_NS 23200000
#define TIMEOUT_NS 100000000
#define TICK_WRAP_NS 26843545600ULL

struct {
    struct gpiod_chip *chip;
    struct gpiod_line *trig_line;
    struct gpiod_line *echo_line;
    FILE *log_file;
    int running;
    pthread_mutex_t mutex;
    uint64_t last_trigger_ns;
} state = {0};

void log_distance(uint64_t timestamp_ns, uint64_t pulse_width_ns) {
    if (pulse_width_ns > MAX_PULSE_WIDTH_NS) {
        return;
    }
    double distance_cm = (pulse_width_ns * 0.034) / 2.0;
    fprintf(state.log_file, "%llu,%f\n", timestamp_ns, distance_cm);
    fflush(state.log_file);
}

void handle_echo_rising(void *user_data) {
    uint64_t timestamp_ns = state.last_trigger_ns;
    uint64_t pulse_width_ns = 0;
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC_RAW, &ts);
    uint64_t current_ns = (uint64_t)ts.tv_sec * 1000000000ULL + ts.tv_nsec;
    pulse_width_ns = current_ns - timestamp_ns;
    pthread_mutex_lock(&state.mutex);
    log_distance(timestamp_ns, pulse_width_ns);
    pthread_mutex_unlock(&state.mutex);
}

void handle_echo_falling(void *user_data) {
    // No action needed for falling edge
}

void handle_sigint(int sig) {
    state.running = 0;
}

int main() {
    state.running = 1;
    pthread_mutex_init(&state.mutex, NULL);

    // Initialize GPIO library
    state.chip = gpiod_chip_open_by_name("gpiochip0");
    if (!state.chip) {
        perror("Failed to open GPIO chip");
        goto cleanup;
    }

    // Request TRIG line
    state.trig_line = gpiod_chip_get_line(state.chip, TRIG_PIN);
    if (!state.trig_line) {
        perror("Failed to get TRIG line");
        goto cleanup;
    }

    // Request ECHO line
    state.echo_line = gpiod_chip_get_line(state.chip, ECHO_PIN);
    if (!state.echo_line) {
        perror("Failed to get ECHO line");
        goto cleanup;
    }

    // Set TRIG line as output
    if (gpiod_line_request_output(state.trig_line, "trig", 0) < 0) {
        perror("Failed to request TRIG line as output");
        goto cleanup;
    }

    // Set ECHO line as input
    if (gpiod_line_request_input(state.echo_line, "echo") < 0) {
        perror("Failed to request ECHO line as input");
        goto cleanup;
    }

    // Open log file
    state.log_file = fopen("distance_log.txt", "a");
    if (!state.log_file) {
        perror("Failed to open log file");
        goto cleanup;
    }

    // Set up ECHO line interrupts
    if (gpiod_line_request_rising_edge_events(state.echo_line, "echo_rising") < 0) {
        perror("Failed to request rising edge events on ECHO line");
        goto cleanup;
    }
    if (gpiod_line_request_falling_edge_events(state.echo_line, "echo_falling") < 0) {
        perror("Failed to request falling edge events on ECHO line");
        goto cleanup;
    }

    // Install SIGINT handler
    signal(SIGINT, handle_sigint);

    while (state.running) {
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC_RAW, &ts);
        uint64_t current_ns = (uint64_t)ts.tv_sec * 1000000000ULL + ts.tv_nsec;
        if (current_ns - state.last_trigger_ns > 200000000) {
            state.last_trigger_ns = current_ns;
            gpiod_line_set_value(state.trig_line, 1);
            usleep(10);
            gpiod_line_set_value(state.trig_line, 0);
        }

        struct gpiod_line_event event;
        if (gpiod_line_event_wait(state.echo_line, &ts, 1) > 0) {
            if (gpiod_line_event_read(state.echo_line, &event) > 0) {
                if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
                    state.last_trigger_ns = event.timestamp.tv_sec * 1000000000ULL + event.timestamp.tv_nsec;
                }
            }
        }
    }

cleanup:
    if (state.log_file) {
        fclose(state.log_file);
    }
    if (state.trig_line) {
        gpiod_line_release(state.trig_line);
    }
    if (state.echo_line) {
        gpiod_line_release(state.echo_line);
    }
    if (state.chip) {
        gpiod_chip_close(state.chip);
    }
    pthread_mutex_destroy(&state.mutex);
    return 0;
}

