#include <gpiod.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <sys/ioctl.h>

#define I2C_BUS "/dev/i2c-1"
#define LIS3DH_ADDR 0x18
#define LIS3DH_CTRL_REG1 0x20
#define LIS3DH_OUT_X_L 0x28
#define LIS3DH_OUT_X_H 0x29
#define LIS3DH_OUT_Y_L 0x2A
#define LIS3DH_OUT_Y_H 0x2B
#define LIS3DH_OUT_Z_L 0x2C
#define LIS3DH_OUT_Z_H 0x2D
#define LIS3DH_FS_2G 0x00
#define LIS3DH_FS_4G 0x10
#define LIS3DH_FS_8G 0x20
#define LIS3DH_FS_16G 0x30
#define LIS3DH_ODR_100Hz 0x27

#define BUZZER_PIN 17
#define G 9.81
#define FREE_FALL_THRESHOLD 0.2 * G
#define IMPACT_THRESHOLD 1.5 * G

static int i2c_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *buzzer_line;
static volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int read_lis3dh_acceleration() {
    uint8_t data[6];
    int retries = 3;

    while (retries--) {
        if (read(i2c_fd, data, sizeof(data)) == sizeof(data)) {
            int16_t x = (data[1] << 8) | data[0];
            int16_t y = (data[3] << 8) | data[2];
            int16_t z = (data[5] << 8) | data[4];
            return (x * x + y * y + z * z) / 16384;
        }
    }

    return -1;
}

void init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LIS3DH_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    uint8_t ctrl_reg1 = LIS3DH_CTRL_REG1 | LIS3DH_FS_2G | LIS3DH_ODR_100Hz;
    if (write(i2c_fd, &ctrl_reg1, 1) != 1) {
        perror("Failed to write to LIS3DH control register");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void init_buzzer() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(buzzer_line, "accelerometer_buzzer", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
}

void cleanup() {
    if (buzzer_line) {
        gpiod_line_release(buzzer_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

int main(int argc, char *argv[]) {
    double free_fall_threshold = FREE_FALL_THRESHOLD;
    double impact_threshold = IMPACT_THRESHOLD;

    if (argc > 1) {
        free_fall_threshold = atof(argv[1]);
    }
    if (argc > 2) {
        impact_threshold = atof(argv[2]);
    }

    signal(SIGINT, signal_handler);

    init_i2c();
    init_buzzer();

    while (running) {
        int acceleration = read_lis3dh_acceleration();
        if (acceleration < 0) {
            fprintf(stderr, "Failed to read acceleration from LIS3DH\n");
            continue;
        }

        double magnitude = sqrt(acceleration) / 1024.0;

        if (magnitude < free_fall_threshold) {
            printf("Free-fall detected\n");
        } else if (magnitude > impact_threshold) {
            printf("Impact detected\n");
            gpiod_line_set_value(buzzer_line, 1);
            usleep(1000000);
            gpiod_line_set_value(buzzer_line, 0);
        }
    }

    cleanup();
    return 0;
}

