#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define MOTOR1_IN1 4
#define MOTOR1_IN2 17
#define MOTOR1_IN3 27
#define MOTOR1_IN4 22
#define MOTOR2_IN1 5
#define MOTOR2_IN2 6
#define MOTOR2_IN3 13
#define MOTOR2_IN4 19
#define STEPS_PER_REV 2048
#define GEAR_RATIO 64
#define STEP_DELAY_US 1000

struct motor {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[4];
};

void motor_init(struct motor *m, const char *chip_name, int in1, int in2, int in3, int in4) {
    m->chip = gpiod_chip_open_by_name(chip_name);
    if (!m->chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    m->lines[0] = gpiod_chip_get_line(m->chip, in1);
    if (!m->lines[0]) {
        perror("Failed to get IN1 line");
        gpiod_chip_close(m->chip);
        exit(EXIT_FAILURE);
    }

    m->lines[1] = gpiod_chip_get_line(m->chip, in2);
    if (!m->lines[1]) {
        perror("Failed to get IN2 line");
        gpiod_line_release(m->lines[0]);
        gpiod_chip_close(m->chip);
        exit(EXIT_FAILURE);
    }

    m->lines[2] = gpiod_chip_get_line(m->chip, in3);
    if (!m->lines[2]) {
        perror("Failed to get IN3 line");
        gpiod_line_release(m->lines[1]);
        gpiod_line_release(m->lines[0]);
        gpiod_chip_close(m->chip);
        exit(EXIT_FAILURE);
    }

    m->lines[3] = gpiod_chip_get_line(m->chip, in4);
    if (!m->lines[3]) {
        perror("Failed to get IN4 line");
        gpiod_line_release(m->lines[2]);
        gpiod_line_release(m->lines[1]);
        gpiod_line_release(m->lines[0]);
        gpiod_chip_close(m->chip);
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < 4; i++) {
        if (gpiod_line_request_output(m->lines[i], "stepper_motor", 0) < 0) {
            perror("Failed to request output for line");
            for (int j = 0; j <= i; j++) {
                gpiod_line_release(m->lines[j]);
            }
            gpiod_chip_close(m->chip);
            exit(EXIT_FAILURE);
        }
    }
}

void motor_step(struct motor *m, int step) {
    for (int i = 0; i < 4; i++) {
        gpiod_line_set_value(m->lines[i], (step >> i) & 1);
    }
    usleep(STEP_DELAY_US);
}

void motor_stop(struct motor *m) {
    for (int i = 0; i < 4; i++) {
        gpiod_line_set_value(m->lines[i], 0);
    }
}

void motor_release(struct motor *m) {
    for (int i = 0; i < 4; i++) {
        gpiod_line_release(m->lines[i]);
    }
    gpiod_chip_close(m->chip);
}

void sigint_handler(int signum) {
    printf("Received SIGINT, stopping motors and exiting...\n");
    motor_stop(&motor1);
    motor_stop(&motor2);
    motor_release(&motor1);
    motor_release(&motor2);
    exit(EXIT_SUCCESS);
}

int main() {
    struct motor motor1, motor2;
    int steps_per_mm = (STEPS_PER_REV * GEAR_RATIO) / 25.4;
    int steps_per_side = 50 * steps_per_mm;

    signal(SIGINT, sigint_handler);

    motor_init(&motor1, "gpiochip0", MOTOR1_IN1, MOTOR1_IN2, MOTOR1_IN3, MOTOR1_IN4);
    motor_init(&motor2, "gpiochip0", MOTOR2_IN1, MOTOR2_IN2, MOTOR2_IN3, MOTOR2_IN4);

    for (int i = 0; i < steps_per_side; i++) {
        motor_step(&motor1, i);
        motor_step(&motor2, i);
    }

    for (int i = steps_per_side - 1; i >= 0; i--) {
        motor_step(&motor1, i);
        motor_step(&motor2, i);
    }

    for (int i = 0; i < steps_per_side; i++) {
        motor_step(&motor1, i);
        motor_step(&motor2, steps_per_side - 1 - i);
    }

    for (int i = steps_per_side - 1; i >= 0; i--) {
        motor_step(&motor1, i);
        motor_step(&motor2, steps_per_side - 1 - i);
    }

    motor_stop(&motor1);
    motor_stop(&motor2);
    motor_release(&motor1);
    motor_release(&motor2);

    return 0;
}

