#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define LIS3DH_I2C_ADDRESS 0x18
#define LIS3DH_CTRL_REG1 0x20
#define LIS3DH_CTRL_REG4 0x23
#define LIS3DH_OUT_X_L 0x28
#define LIS3DH_OUT_X_H 0x29
#define LIS3DH_OUT_Y_L 0x2A
#define LIS3DH_OUT_Y_H 0x2B
#define LIS3DH_OUT_Z_L 0x2C
#define LIS3DH_OUT_Z_H 0x2D

#define LIS3DH_RANGE_2G 0x00
#define LIS3DH_ODR_100HZ 0x10
#define LIS3DH_HR_12BIT 0x80

#define DEFAULT_THRESHOLD 2.0
#define LOG_FILE "/var/log/high_acceleration.log"

static struct gpiod_chip *chip = NULL;
static int i2c_fd = -1;

void log_acceleration(double x, double y, double z) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    fprintf(log_file, "%s: X=%.2f, Y=%.2f, Z=%.2f\n", ctime(&now), x, y, z);
    fclose(log_file);
}

void shutdown_system() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    system("sudo shutdown -h now");
    exit(0);
}

void sigint_handler(int signum) {
    shutdown_system();
}

int read_acceleration(double *x, double *y, double *z) {
    uint8_t data[6];
    if (read(i2c_fd, data, sizeof(data)) != sizeof(data)) {
        perror("Failed to read from I2C device");
        return 0;
    }
    *x = (data[1] << 8 | data[0]) / 32768.0 * 2.0;
    *y = (data[3] << 8 | data[2]) / 32768.0 * 2.0;
    *z = (data[5] << 8 | data[4]) / 32768.0 * 2.0;
    return 1;
}

int main(int argc, char *argv[]) {
    int opt;
    uint8_t i2c_address = LIS3DH_I2C_ADDRESS;
    double threshold = DEFAULT_THRESHOLD;

    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
