#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x30
#define RELAY_PIN 17
#define FIELD_THRESHOLD 5000  // 5.0 mT in millitesla
#define POLL_ATTEMPTS 50
#define SAMPLE_INTERVAL 100  // 100 ms

static struct gpiod_chip *chip;
static struct gpiod_line *relay_line;
static int i2c_fd;

void log_event(const char *message) {
    time_t now = time(NULL);
    char *iso_time = ctime(&now);
    iso_time[strlen(iso_time) - 1] = '\0';  // Remove newline
    fprintf(stderr, "%s: %s\n", iso_time, message);
}

void log_error(const char *message) {
    log_event(message);
    exit(EXIT_FAILURE);
}

void log_error_i2c(const char *message) {
    log_event(message);
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(EXIT_FAILURE);
}

void log_error_gpio(const char *message) {
    log_event(message);
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(EXIT_FAILURE);
}

void handle_sigint(int sig) {
    log_event("SIGINT received, shutting down...");
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(EXIT_SUCCESS);
}

int read_field_strength(int i2c_fd) {
    uint8_t buffer[2];
    if (read(i2c_fd, buffer, sizeof(buffer)) != sizeof(buffer)) {
        log_error_i2c("Failed to read from I2C device");
    }
    return (buffer[0] << 8) | buffer[1];
}

int main() {
    signal(SIGINT, handle_sigint);

    // Initialize I2C
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C device");
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        log_error_i2c("Failed to set I2C address");
    }

    // Initialize GPIO
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        log_error_gpio("Failed to open GPIO chip");
    }
    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        log_error_gpio("Failed to get GPIO line");
    }
    if (gpiod_line_request_output(relay_line, "relay", 0) < 0) {
        log_error_gpio("Failed to request GPIO line as output");
    }

    FILE *events_file = fopen("magnetic_events.txt", "a");
    if (!events_file) {
        log_error("Failed to open events file");
    }

    while (1) {
        int field_strength = read_field_strength(i2c_fd);
        int relay_state = field_strength > FIELD_THRESHOLD;

        if (relay_state) {
            if (gpiod_line_set_value(relay_line, 1) < 0) {
                log_error_gpio("Failed to set relay line high");
            }
        } else {
            if (gpiod_line_set_value(relay_line, 0) < 0) {
                log_error_gpio("Failed to set relay line low");
            }
        }

        time_t now = time(NULL);
        char *iso_time = ctime(&now);
        iso_time[strlen(iso_time) - 1] = '\0';  // Remove newline

        fprintf(events_file, "%s: Field strength: %d mT, Relay: %s\n", iso_time, field_strength, relay_state ? "ON" : "OFF");
        fflush(events_file);

        usleep(SAMPLE_INTERVAL * 1000);
    }

    fclose(events_file);
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

