#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 18
#define TCP_PORT 5000
#define LOG_FILE "relay_log.txt"

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static int server_fd, new_socket;
static FILE *log_file;

void log_event(const char *event) {
    time_t now = time(NULL);
    fprintf(log_file, "%s: %s\n", ctime(&now), event);
    fflush(log_file);
}

void handle_signal(int signum) {
    log_event("Shutting down gracefully");
    gpiod_line_set_value(line, 0);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(new_socket);
    close(server_fd);
    fclose(log_file);
    exit(signum);
}

void setup_signal_handlers() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

int main() {
    struct sockaddr_in address;
    int addrlen = sizeof(address);
    char buffer[1024] = {0};

    // Initialize GPIO
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "relay_control", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initialize TCP server
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("Failed to create socket");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(TCP_PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("Failed to bind");
        close(server_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (listen(server_fd, 3) < 0) {
        perror("Failed to listen");
        close(server_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(server_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    setup_signal_handlers();

    log_event("Server started");

    while (1) {
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("Failed to accept");
            continue;
        }

        int valread = read(new_socket, buffer, 1024);
        if (valread < 0) {
            perror("Failed to read from socket");
            close(new_socket);
            continue;
        }

        buffer[valread] = '\0';
        char *command = strtok(buffer, " \n");
        if (command) {
            if (strcasecmp(command, "ON") == 0) {
                gpiod_line_set_value(line, 1);
                log_event("Relay ON");
            } else if (strcasecmp(command, "OFF") == 0) {
                gpiod_line_set_value(line, 0);
                log_event("Relay OFF");
            } else {
                log_event("Invalid command");
            }
        }

        close(new_socket);
    }

    return EXIT_SUCCESS;
}

