This C program for a Raspberry Pi 4 Model B uses the GPIO bus with BCM numbering to control a KY-019 relay module connected to GPIO 18. It listens on TCP port 5000 for case-insensitive commands "ON" and "OFF", invoking the library's API call to switch the relay and logging every activation, deactivation, and any invalid-command event with a timestamp to a file named `relay_log.txt`. The implementation includes comprehensive error handling for all socket operations and GPIO initialization, and it installs SIGINT and SIGTERM handlers that gracefully shut down the library's API call, close the sockets and the log file, turn off the relay, and terminate the driver library.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDR_1 0x60
#define I2C_ADDR_2 0x61
#define GPIO_PIN 18
#define POLYNOMIAL 0x07
#define INITIAL_VALUE 0xFF
#define CRC_LENGTH 1
#define READ_LENGTH 3
#define RELAY_ON 1
#define RELAY_OFF 0
#define LOG_FILE "flow_log.txt"
#define POLL_INTERVAL 100000 // 100 ms in microseconds

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static int i2c_fd_1, i2c_fd_2;

void cleanup() {
    if (line) {
        gpiod_line_release(line);
        line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd_1 >= 0) {
        close(i2c_fd_1);
        i2c_fd_1 = -1;
    }
    if (i2c_fd_2 >= 0) {
        close(i2c_fd_2);
        i2c_fd_2 = -1;
    }
    printf("Cleanup complete.\n");
}

void handle_sigint(int sig) {
    cleanup();
    exit(0);
}

uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = INITIAL_VALUE;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_sensor(int fd, uint8_t *buffer) {
    ssize_t bytes_read = read(fd, buffer, READ_LENGTH);
    if (bytes_read < READ_LENGTH) {
        fprintf(stderr, "Failed to read from sensor: %zd bytes read\n", bytes_read);
        return -1;
    }
    uint8_t crc = calculate_crc8(buffer, READ_LENGTH - CRC_LENGTH);
    if (crc != buffer[READ_LENGTH - CRC_LENGTH]) {
        fprintf(stderr, "CRC check failed for sensor\n");
        return -1;
    }
    return 0;
}

int main() {
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    // Initialize GPIO
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(line, "flow_sensor_relay", RELAY_OFF) < 0) {
        perror("Failed to request GPIO line as output");
        cleanup();
        return EXIT_FAILURE;
    }

    // Initialize I2C
    i2c_fd_1 = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd_1 < 0) {
        perror("Failed to open I2C bus 1");
        cleanup();
        return EXIT_FAILURE;
    }
    if (ioctl(i2c_fd_1, I2C_SLAVE, I2C_ADDR_1) < 0) {
        perror("Failed to set I2C address for sensor 1");
        cleanup();
        return EXIT_FAILURE;
    }
    i2c_fd_2 = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd_2 < 0) {
        perror("Failed to open I2C bus 1");
        cleanup();
        return EXIT_FAILURE;
    }
    if (ioctl(i2c_fd_2, I2C_SLAVE, I2C_ADDR_2) < 0) {
        perror("Failed to set I2C address for sensor 2");
        cleanup();
        return EXIT_FAILURE;
    }

    uint8_t start_measurement[] = {0x00, 0x01};
    if (write(i2c_fd_1, start_measurement, sizeof(start_measurement)) != sizeof(start_measurement)) {
        perror("Failed to start measurement on sensor 1");
        cleanup();
        return EXIT_FAILURE;
    }
    if (write(i2c_fd_2, start_measurement, sizeof(start_measurement)) != sizeof(start_measurement)) {
        perror("Failed to start measurement on sensor 2");
        cleanup();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        uint8_t buffer_1[READ_LENGTH], buffer_2[READ_LENGTH];
        if (read_sensor(i2c_fd_1, buffer_1) < 0 || read_sensor(i2c_fd_2, buffer_2) < 0) {
            continue;
        }

        uint16_t flow_rate_1 = (buffer_1[0] << 8) | buffer_1[1];
        uint16_t flow_rate_2 = (buffer_2[0] << 8) | buffer_2[1];

        if (flow_rate_1 < 5000 || flow_rate_2 < 5000) {
            gpiod_line_set_value(line, RELAY_ON);
        } else {
            gpiod_line_set_value(line, RELAY_OFF);
        }

        fprintf(log_file, "%lu,%u,%u\n", (unsigned long)time(NULL), flow_rate_1, flow_rate_2);
        fflush(log_file);

        usleep(POLL_INTERVAL);
    }

    fclose(log_file);
    cleanup();
    return EXIT_SUCCESS;
}

