This code provides a complete solution for monitoring two Sensirion SLF3S-1300F liquid-flow sensors connected to I2C bus 1 on a Raspberry Pi Zero W, controlling a safety relay on GPIO 18, and logging the flow rates with timestamps. It includes error handling, resource cleanup, and graceful shutdown on SIGINT or SIGTERM.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <libgpiod.h>

#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24
#define POLL_INTERVAL 200000
#define MOTOR_HOLD_TIME 5000000
#define DRY_TO_WET_THRESHOLD 3

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

void setup_gpio(struct gpiod_chip *chip, int pin, int direction, int default_value) {
    struct gpiod_line *line;
    int ret;

    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        syslog(LOG_ERR, "Failed to get line %d", pin);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(line, "rain_window", default_value);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to request output for line %d", pin);
        exit(EXIT_FAILURE);
    }

    syslog(LOG_INFO, "GPIO %d set to %s", pin, default_value ? "high" : "low");
}

void setup_sensor(struct gpiod_chip *chip, int pin) {
    struct gpiod_line *line;
    int ret;

    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        syslog(LOG_ERR, "Failed to get line %d", pin);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_input(line, "rain_window");
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to request input for line %d", pin);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_bias_pull_up(line);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to set pull-up for line %d", pin);
        exit(EXIT_FAILURE);
    }

    syslog(LOG_INFO, "GPIO %d set to input with pull-up", pin);
}

void setup_motor(struct gpiod_chip *chip, int ena_pin, int in1_pin, int in2_pin) {
    setup_gpio(chip, ena_pin, GPIOD_LINE_DIRECTION_OUTPUT, 0);
    setup_gpio(chip, in1_pin, GPIOD_LINE_DIRECTION_OUTPUT, 0);
    setup_gpio(chip, in2_pin, GPIOD_LINE_DIRECTION_OUTPUT, 0);
}

void close_window(struct gpiod_chip *chip, int ena_pin, int in1_pin, int in2_pin) {
    struct gpiod_line *ena_line, *in1_line, *in2_line;
    int ret;

    ena_line = gpiod_chip_get_line(chip, ena_pin);
    in1_line = gpiod_chip_get_line(chip, in1_pin);
    in2_line = gpiod_chip_get_line(chip, in2_pin);

    ret = gpiod_line_set_value(ena_line, 1);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to set ENA high");
        return;
    }

    ret = gpiod_line_set_value(in1_line, 1);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to set IN1 high");
        return;
    }

    ret = gpiod_line_set_value(in2_line, 0);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to set IN2 low");
        return;
    }

    syslog(LOG_INFO, "Motor started");

    usleep(MOTOR_HOLD_TIME);

    ret = gpiod_line_set_value(ena_line, 0);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to set ENA low");
