#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22
#define PULSE_WIDTH_LOCK 2000
#define PULSE_WIDTH_UNLOCK 1000
#define DEBOUNCE_DELAY 200000 // 200ms in microseconds

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *servo_line, *lock_button_line, *unlock_button_line;
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request servo line
    servo_line = gpiod_chip_get_line(chip, SERVO_PIN);
    if (!servo_line) {
        perror("Failed to get servo line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request lock button line
    lock_button_line = gpiod_chip_get_line(chip, LOCK_BUTTON_PIN);
    if (!lock_button_line) {
        perror("Failed to get lock button line");
        gpiod_line_release(servo_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request unlock button line
    unlock_button_line = gpiod_chip_get_line(chip, UNLOCK_BUTTON_PIN);
    if (!unlock_button_line) {
        perror("Failed to get unlock button line");
        gpiod_line_release(servo_line);
        gpiod_line_release(lock_button_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set servo line as output
    ret = gpiod_line_request_output(servo_line, "servo", 0);
    if (ret < 0) {
        perror("Failed to request servo line as output");
        gpiod_line_release(unlock_button_line);
        gpiod_line_release(lock_button_line);
        gpiod_line_release(servo_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set lock button line as input with pull-up
    ret = gpiod_line_request_input(lock_button_line, "lock_button", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret < 0) {
        perror("Failed to request lock button line as input");
        gpiod_line_release(servo_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set unlock button line as input with pull-up
    ret = gpiod_line_request_input(unlock_button_line, "unlock_button", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret < 0) {
        perror("Failed to request unlock button line as input");
        gpiod_line_release(servo_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        int lock_button_state = gpiod_line_get_value(lock_button_line);
        int unlock_button_state = gpiod_line_get_value(unlock_button_line);

        if (lock_button_state == 0) {
            usleep(DEBOUNCE_DELAY);
            if (gpiod_line_get_value(lock_button_line) == 0) {
                ret = gpiod_line_set_value(servo_line, 1);
                if (ret < 0) {
                    perror("Failed to set servo line for lock");
                    running = 0;
                } else {
                    printf("Locking...\n");
                    ret = gpiod_line_set_value(servo_line, 0);
                    if (ret < 0) {
                        perror("Failed to set servo line for lock release");
                        running = 0;
                    }
                }
            }
        }

        if (unlock_button_state == 0) {
            usleep(DEBOUNCE_DELAY);
            if (gpiod_line_get_value(unlock_button_line) == 0) {
                ret = gpiod_line_set_value(servo_line, 1);
                if (ret < 0) {
                    perror("Failed to set servo line for unlock");
                    running = 0;
                } else {
                    printf("Unlocking...\n");
                    ret = gpiod_line_set_value(servo_line, 0);
                    if (ret < 0) {
                        perror("Failed to set servo line for unlock release");
                        running = 0;
                    }
                }
            }
        }

        usleep(1000); // Sleep for 1ms to keep CPU usage low
    }

    // Stop servo
    gpiod_line_set_value(servo_line, 0);

    // Final call to servo line
    ret = gpiod_line_set_value(servo_line, 0);
    if (ret < 0) {
        perror("Failed to set servo line for final release");
    }

    // Release lines and close chip
    gpiod_line_release(servo_line);
    gpiod_line_release(unlock_button_line);
    gpiod_line_release(lock_button_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

