This code sets up the GPIO pins for controlling a hobby servo and two momentary push-buttons on a Raspberry Pi using the `libgpiod` library. It polls the buttons in a tight loop, implements debouncing, and drives the servo based on the button presses. The program also handles SIGINT and SIGTERM signals to gracefully stop the servo and release resources.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define PIR_PIN 4
#define LED_PIN 17
#define POLL_INTERVAL 100
#define LED_DURATION 60
#define LOG_FILE "security_log.txt"

static struct gpiod_chip *chip;
static struct gpiod_line *pir_line, *led_line;
static FILE *log_file;

void log_event(const char *event, int duration) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    if (log_file) {
        if (duration == -1) {
            fprintf(log_file, "%s: %s\n", timestamp, event);
        } else {
            fprintf(log_file, "%s: %s for %d seconds\n", timestamp, event, duration);
        }
        fflush(log_file);
    }
}

void turn_off_led() {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
    }
}

void signal_handler(int signum) {
    turn_off_led();
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    struct gpiod_line_request_config config = {
        .consumer = "motion_sensor",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
    };

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        perror("Failed to get PIR line");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request(pir_line, &config) < 0) {
        perror("Failed to request PIR line");
        gpiod_chip_close(chip);
        return 1;
    }

    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    config.flags = GPIOD_LINE_REQUEST_FLAG_ACTIVE_HIGH;

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get LED line");
        gpiod_line_release(pir_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request(led_line, &config) < 0) {
        perror("Failed to request LED line");
        gpiod_line_release(pir_line);
        gpiod_chip_close(chip);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        turn_off_led();
        gpiod_line_release(pir_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int last_state = 0;
    int led_on = 0;
    time_t led_on_time = 0;

    while (1) {
        int state = gpiod_line_get_value(pir_line);
        if (state != last_state) {
            if (state == 1) {
                log_event("Motion detected", -1);
                turn_off_led();
                led_on = 1;
                led_on_time = time(NULL);
            } else {
                if (led_on) {
                    int duration = (int)(time(NULL) - led_on_time);
                    log_event("Motion ended", duration);
                    turn_off_led();
                    led_on = 0;
                }
            }
            last_state = state;
        }

        if (led_on) {
            gpiod_line_set_value(led_line, 1);
            if (time(NULL) - led_on_time >= LED_DURATION) {
                turn_off_led();
                led_on = 0;
            }
        }

        usleep(POLL_INTERVAL * 1000);
    }

    turn_off_led();
    gpiod_line_release(pir_line);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    fclose(log_file);

    return 0;
}

