        return 1;
    }

    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    config.flags = GPIOD_LINE_REQUEST_FLAG_ACTIVE_HIGH;

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get LED line");
        gpiod_line_release(pir_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request(led_line, &config) < 0) {
        perror("Failed to request LED line");
        gpiod_line_release(pir_line);
        gpiod_chip_close(chip);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        turn_off_led();
        gpiod_line_release(pir_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int last_state = 0;
    int led_on = 0;
    time_t led_on_time = 0;

    while (1) {
        int state = gpiod_line_get_value(pir_line);
        if (state != last_state) {
            if (state == 1) {
                log_event("Motion detected", -1);
                turn_off_led();
                led_on = 1;
                led_on_time = time(NULL);
            } else {
                if (led_on) {
                    int duration = (int)(time(NULL) - led_on_time);
                    log_event("Motion ended", duration);
                    turn_off_led();
                    led_on = 0;
                }
            }
            last_state = state;
        }

        if (led_on) {
            gpiod_line_set_value(led_line, 1);
            if (time(NULL) - led_on_time >= LED_DURATION) {
                turn_off_led();
                led_on = 0;
            }
        }

        usleep(POLL_INTERVAL * 1000);
    }

    turn_off_led();
    gpiod_line_release(pir_line);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    fclose(log_file);

    return 0;
}
