#define GPIO_CHIP "gpiochip0"
#define SERVO_PIN 17
#define PIR_PIN 4
#define PWM_FREQ 50
#define PWM_PERIOD (1000000 / PWM_FREQ)
#define PULSE_WIDTH_MIN (1 * PWM_PERIOD / 1000)
#define PULSE_WIDTH_MAX (2 * PWM_PERIOD / 1000)
#define SOCKET_PORT 5000
#define LOG_FILE "security.log"

static struct gpiod_chip *chip;
static int socket_fd;
static FILE *log_file;

void log_message(const char *format, ...) {
    va_list args;
    va_start(args, format);
    vfprintf(log_file, format, args);
    va_end(args);
    fflush(log_file);
    vsyslog(LOG_USER, format, args);
    va_end(args);
}

void handle_signal(int signum) {
    log_message("Received signal %d, shutting down gracefully...\n", signum);
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (socket_fd >= 0) {
        close(socket_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(signum == SIGINT ? 0 : 1);
}

void set_servo_angle(int angle) {
    if (angle < 0 || angle > 180) {
        log_message("Invalid angle: %d\n", angle);
        return;
    }
    int pulse_width = PULSE_WIDTH_MIN + (angle * (PULSE_WIDTH_MAX - PULSE_WIDTH_MIN)) / 180;
    struct gpiod_line_request req = {
        .consumer = "servo",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT,
        .default_val = 0,
    };
    struct gpiod_line *line = gpiod_chip_get_line(chip, SERVO_PIN);
    if (!line) {
        log_message("Failed to get GPIO line %d\n", SERVO_PIN);
        return;
    }
    if (gpiod_line_request(line, &req)) {
        log_message("Failed to request GPIO line %d\n", SERVO_PIN);
        gpiod_line_release(line);
        return;
    }
    gpiod_line_set_value(line, 1);
    usleep(pulse_width);
    gpiod_line_set_value(line, 0);
    gpiod_line_release(line);
}

void handle_client(int client_fd) {
    char buffer[256];
    ssize_t bytes_read;
    while ((bytes_read = read(client_fd, buffer, sizeof(buffer) - 1)) > 0) {
        buffer[bytes_read] = '\0';
        char *command = strtok(buffer, " ");
        if (command) {
            if (strcmp(command, "PIR") == 0) {
                int pir_value = gpiod_line_get_value(gpiod_chip_get_line(chip, PIR_PIN));
                char response[16];
                snprintf(response, sizeof(response), "PIR:%d\n", pir_value);
                write(client_fd, response, strlen(response));
            } else if (strncmp(command, "set_servo_angle", 15) == 0) {
                char *angle_str = strtok(NULL, " ");
                if (angle_str) {
                    int angle = atoi(angle_str);
                    set_servo_angle(angle);
                }
            }
        }
    }
    close(client_fd);
}

int main() {
    openlog("servo_control", LOG_PID | LOG_CONS, LOG_USER);
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        log_message("Failed to open log file %s\n", LOG_FILE);
        closelog();
        return 1;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        log_message("Failed to open GPIO chip %s\n", GPIO_CHIP);
        fclose(log_file);
        closelog();
        return 1;
    }

    struct gpiod_line_request req = {
        .consumer = "pir",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
    };
    struct gpiod_line *pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        log_message("Failed to get GPIO line %d\n", PIR_PIN);
        gpiod_chip_close(chip);
        fclose(log_file);
        closelog();
        return 1;
    }
    if (gpiod_line_request(pir_line, &req)) {
        log_message("Failed to request GPIO line %d\n", PIR_PIN);
        gpiod_line_release(pir_line);
        gpiod_chip_close(chip);
        fclose(log_file);
        closelog();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        log_message("Failed to create socket\n");
        gpiod_line_release(pir_line);
        gpiod_chip_close(chip);
        fclose(log_file);
        closelog();
        return 1;
    }

    struct sockaddr_in server_addr = {
        .sin_family = AF_INET,
        .sin_addr.s_addr = INADDR_ANY,
        .sin_port = htons(SOCKET_PORT),
    };
    if (bind(server_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        log_message("Failed to bind socket\n");
        close(server_fd);
        gpiod_line_release(pir_line);
        gpiod_chip_close(chip);
        fclose(log_file);
        closelog();
        return 1;
    }

    if (listen(server_fd, 5) < 0) {
        log_message("Failed to listen on socket\n");
        close(server_fd);
        gpiod_line_release(pir_line);
        gpiod_chip_close(chip);
        fclose(log_file);
        closelog();
        return 1;
    }

    log_message("Server started, listening on port %d\n", SOCKET_PORT);

    while (1) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd < 0) {
            log_message("Failed to accept connection\n");
            continue;
        }
        handle_client(client_fd);
    }

    close(server_fd);
    gpiod_line_release(pir_line);
    gpiod_chip_close(chip);
    fclose(log_file);
    closelog();
    return 0;
}
```

This C program for a Raspberry Pi 5 uses the libgpiod library to control a servo motor on BCM GPIO17 and read a PIR sensor on BCM GPIO4. It listens for TCP connections on port 5000 and accepts commands of the form "set_servo_angle <angle>" where <angle> is 0-180. The program generates a software PWM signal at 50 Hz with a 1-2 ms pulse width to position the servo and responds to the command "PIR" by sending back "PIR:0" or "PIR:1" over the socket. All events, commands, and errors are logged to both syslog (LOG_USER facility) and a file named security.log with ISO 8601 timestamps. The program checks the result of every driver library call, socket syscall, and file I/O operation and logs errors if GPIO initialization fails. It handles SIGINT and SIGTERM to perform a graceful shutdown that releases all driver resources, closes the socket, and the log file.

