#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define BH1750_I2C_ADDRESS 0x23
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define GROW_LIGHT_RELAY_PIN 23
#define LOG_FILE "grow_log.txt"
#define RETRY_DELAY 1000

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *relay_line;
    int i2c_fd;
    uint16_t lux;
    FILE *log_file;
    char timestamp[20];
    time_t now;

    // Set up signal handler for graceful exit
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Request relay line
    relay_line = gpiod_chip_get_line(chip, GROW_LIGHT_RELAY_PIN);
    if (!relay_line) {
        perror("Failed to get relay line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Configure relay line as output
    if (gpiod_line_request_output(relay_line, "grow_light_relay", 0) < 0) {
        perror("Failed to request relay line as output");
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Start continuous measurement mode
    if (write(i2c_fd, &BH1750_CONTINUOUS_HIGH_RES_MODE, 1) != 1) {
        perror("Failed to start continuous measurement mode");
        fclose(log_file);
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        // Wait for measurement to complete
        usleep(120000);

        // Read lux value
        if (read(i2c_fd, &lux, 2) != 2) {
            perror("Failed to read lux value");
            continue;
        }

        // Convert lux value
        lux = (lux >> 8) | ((lux & 0xFF) << 8);
        lux /= 1.2;

        // Get current timestamp
        time(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        // Log timestamp and lux value
        fprintf(log_file, "%s: %.2f lux\n", timestamp, lux);
        fflush(log_file);

        // Control grow light relay
        if (lux < 150) {
            if (gpiod_line_set_value(relay_line, 1) < 0) {
                perror("Failed to activate grow light relay");
            }
        } else {
            if (gpiod_line_set_value(relay_line, 0) < 0) {
                perror("Failed to deactivate grow light relay");
            }
        }

        // Wait for next sample
        sleep(2);
    }

    // Clean up
    fclose(log_file);
    gpiod_line_release(relay_line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

