#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <libgpiod.h>

#define HX711_DOUT_PIN 23
#define HX711_SCK_PIN 24
#define SOLENOID_PIN 25
#define DEFAULT_THRESHOLD 1000
#define DEFAULT_SCALE 1.0
#define DEFAULT_DURATION 200
#define TARE_READINGS 10
#define MEASUREMENT_READINGS 5
#define MAX_RETRIES 3
#define TIMEOUT_US 1000000

static struct gpiod_chip *chip;
static struct gpiod_line *dout_line, *sck_line, *solenoid_line;
static int threshold = DEFAULT_THRESHOLD;
static double scale = DEFAULT_SCALE;
static int duration = DEFAULT_DURATION;
static int running = 1;

static void handle_signal(int sig) {
    running = 0;
}

static int read_hx711() {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        int ret = gpiod_line_get_value(dout_line);
        if (ret < 0) {
            syslog(LOG_ERR, "Failed to get DOUT value: %s", gpiod_error_str(ret));
            retries++;
            continue;
        }
        if (ret == 0) {
            break;
        }
        usleep(100000);
        retries++;
    }
    if (retries == MAX_RETRIES) {
        syslog(LOG_ERR, "DOUT did not go LOW within 1 second");
        return -1;
    }

    uint32_t value = 0;
    for (int i = 0; i < 24; i++) {
        ret = gpiod_line_get_value(sck_line);
        if (ret < 0) {
            syslog(LOG_ERR, "Failed to get SCK value: %s", gpiod_error_str(ret));
            return -1;
        }
        usleep(10);
        ret = gpiod_line_get_value(dout_line);
        if (ret < 0) {
            syslog(LOG_ERR, "Failed to get DOUT value: %s", gpiod_error_str(ret));
            return -1;
        }
        value = (value << 1) | ret;
        ret = gpiod_line_set_value(sck_line, 0);
        if (ret < 0) {
            syslog(LOG_ERR, "Failed to set SCK value: %s", gpiod_error_str(ret));
            return -1;
        }
        usleep(10);
    }

    ret = gpiod_line_set_value(sck_line, 1);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to set SCK value: %s", gpiod_error_str(ret));
        return -1;
    }
    usleep(10);

    return value;
}

static void tare_hx711() {
    int sum = 0;
    for (int i = 0; i < TARE_READINGS; i++) {
        int value = read_hx711();
        if (value < 0) {
            syslog(LOG_ERR, "Failed to read HX711 during tare");
            return;
        }
        sum += value;
    }
    threshold = sum / TARE_READINGS;
    syslog(LOG_INFO, "Tare complete, threshold set to %d", threshold);
}

static void measure_and_lock() {
    int sum = 0;
    for (int i = 0; i < MEASUREMENT_READINGS; i++) {
        int value = read_hx711();
        if (value < 0) {
            syslog(LOG_ERR, "Failed to read HX711 during measurement");
            return;
        }
        sum += value;
    }
    int weight = (sum / MEASUREMENT_READINGS) * scale;
    if (weight > threshold) {
        int ret = gpiod_line_set_value(solenoid_line, 1);
        if (ret < 0) {
            syslog(LOG_ERR, "Failed to set solenoid line: %s", gpiod_error_str(ret));
            return;
        }
        usleep(duration * 1000);
        ret = gpiod_line_set_value(solenoid_line, 0);
        if (ret < 0) {
            syslog(LOG_ERR, "Failed to set solenoid line: %s", gpiod_error_str(ret));
            return;
        }
        syslog(LOG_INFO, "Weight exceeded threshold, solenoid locked for %d ms", duration);
    }
}

int main(int argc, char *argv[]) {
    openlog("hx711_lock", LOG_PID | LOG_CONS, LOG_USER);

    struct gpiod_request_config config = {
        .consumer = "hx711_lock",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
    };

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        closelog();
        return EXIT_FAILURE;
    }

    dout_line = gpiod_chip_get_line(chip, HX711_DOUT_PIN);
    if (!dout_line) {
        syslog(LOG_ERR, "Failed to get DOUT line");
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    sck_line = gpiod_chip_get_line(chip, HX711_SCK_PIN);
    if (!sck_line) {
        syslog(LOG_ERR, "Failed to get SCK line");
        gpiod_line_release(dout_line);
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    solenoid_line = gpiod_chip_get_line(chip, SOLENOID_PIN);
    if (!solenoid_line) {
        syslog(LOG_ERR, "Failed to get solenoid line");
        gpiod_line_release(dout_line);
        gpiod_line_release(sck_line);
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    int ret = gpiod_line_request(dout_line, &config);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to request DOUT line: %s", gpiod_error_str(ret));
        gpiod_line_release(solenoid_line);
        gpiod_line_release(dout_line);
        gpiod_line_release(sck_line);
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request(sck_line, &config);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to request SCK line: %s", gpiod_error_str(ret));
        gpiod_line_release(dout_line);
        gpiod_line_release(sck_line);
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request(solenoid_line, &config);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to request solenoid line: %s", gpiod_error_str(ret));
        gpiod_line_release(dout_line);
        gpiod_line_release(sck_line);
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    tare_hx711();

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (running) {
        measure_and_lock();
        usleep(500 * 1000);
    }

    gpiod_line_set_value(solenoid_line, 0);
    gpiod_line_release(dout_line);
    gpiod_line_release(sck_line);
    gpiod_line_release(solenoid_line);
    gpiod_chip_close(chip);
    closelog();

    return EXIT_SUCCESS;
}

