#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <libgpiod.h>
#include <mosquitto.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/lights/control"
#define MQTT_CLIENT_ID "relay_controller_1"
#define KEEP_ALIVE 60
#define RECONNECT_DELAY 5

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static struct mosquitto *mosq;
static int running = 1;

static void signal_handler(int signum) {
    running = 0;
}

static void gpio_init() {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %s", gpiod_strerror(errno));
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        syslog(LOG_ERR, "Failed to get GPIO line: %s", gpiod_strerror(errno));
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(line, "relay_controller", 0) < 0) {
        syslog(LOG_ERR, "Failed to request GPIO line as output: %s", gpiod_strerror(errno));
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
}

static void mqtt_init() {
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create MQTT client");
        exit(EXIT_FAILURE);
    }

    if (mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, KEEP_ALIVE) != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker");
        mosquitto_destroy(mosq);
        exit(EXIT_FAILURE);
    }

    if (mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0) != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to subscribe to MQTT topic");
        mosquitto_destroy(mosq);
        exit(EXIT_FAILURE);
    }
}

static void gpio_cleanup() {
    if (line) {
        gpiod_line_release(line);
        gpiod_chip_close(chip);
    }
}

static void mqtt_cleanup() {
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
    }
}

static void on_connect(struct mosquitto *mosq, void *userdata, int rc) {
    if (rc == 0) {
        syslog(LOG_INFO, "Connected to MQTT broker");
    } else {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %d", rc);
    }
}

static void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *msg) {
    if (msg->payloadlen == 0) {
        syslog(LOG_ERR, "Received empty payload");
        return;
    }

    if (msg->payloadlen == 3 && !strncmp((char *)msg->payload, "ON", 3)) {
        gpiod_line_set_value(line, 1);
        syslog(LOG_INFO, "Relay ON");
    } else if (msg->payloadlen == 4 && !strncmp((char *)msg->payload, "OFF", 4)) {
        gpiod_line_set_value(line, 0);
        syslog(LOG_INFO, "Relay OFF");
    } else {
        syslog(LOG_ERR, "Received invalid payload: %.*s", (int)msg->payloadlen, (char *)msg->payload);
    }
}

static void on_disconnect(struct mosquitto *mosq, void *userdata, int rc) {
    if (rc == 0) {
        syslog(LOG_INFO, "Disconnected from MQTT broker");
    } else {
        syslog(LOG_ERR, "Unexpected disconnection from MQTT broker: %d", rc);
    }
}

int main(int argc, char *argv[]) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    openlog("mqtt_relay", LOG_PID, LOG_USER);

    gpio_init();
    mqtt_init();

    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_message_callback_set(mosq, on_message);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);

    while (running) {
        if (mosquitto_loop(mosq, -1, 1) != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "MQTT loop error");
            sleep(RECONNECT_DELAY);
        }
    }

    gpiod_line_set_value(line, 0);
    gpio_cleanup();
    mqtt_cleanup();
    closelog();

    return 0;
}

