#define PWM_DUTY_MIN_NS 500000   // 500 µs pulse width in nanoseconds
#define PWM_DUTY_MAX_NS 2500000  // 2500 µs pulse width in nanoseconds

#define SERVO1_DUTY_NS 1000000  // 1000 µs pulse width for Servo 1
#define SERVO2_DUTY_NS 1500000  // 1500 µs pulse width for Servo 2
#define SERVO3_DUTY_NS 2000000  // 2000 µs pulse width for Servo 3
#define SERVO4_DUTY_NS 500000   // 500 µs pulse width for Servo 4
#define SERVO5_DUTY_NS 2500000  // 2500 µs pulse width for Servo 5

#define SERVO_HOLD_TIME 3  // Hold each position for 3 seconds

void set_servo_duty(struct gpiod_chip *chip, int pin, long long duty_ns) {
    struct gpiod_line *line;
    struct gpiod_line_request req = {
        .consumer = "servo",
        .type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT,
        .default_val = 0,
    };

    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("Failed to get GPIO line");
        return;
    }

    if (gpiod_request_line(line, &req)) {
        perror("Failed to request GPIO line");
        gpiod_line_release(line);
        return;
    }

    gpiod_line_set_value(line, 1);
    gpiod_line_set_config(line, GPIOD_LINE_CONFIG_OUTPUT, duty_ns, PWM_PERIOD_NS);
    gpiod_line_release(line);
}

int main() {
    struct gpiod_chip *chip;
    const char *chip_name = "gpiochip0";

    chip = gpiod_chip_open_by_name(chip_name);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    set_servo_duty(chip, SERVO1_PIN, SERVO1_DUTY_NS);
    sleep(SERVO_HOLD_TIME);

    set_servo_duty(chip, SERVO2_PIN, SERVO2_DUTY_NS);
    sleep(SERVO_HOLD_TIME);

    set_servo_duty(chip, SERVO3_PIN, SERVO3_DUTY_NS);
