#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define MOTOR_A_PWM 17
#define MOTOR_A_DIR 18
#define MOTOR_B_PWM 22
#define MOTOR_B_DIR 23
#define ENCODER_A_A 4
#define ENCODER_A_B 5
#define ENCODER_B_A 6
#define ENCODER_B_B 12
#define PWM_FREQ 10000
#define TicksPerRev 64
#define TargetRPM 50
#define ControlInterval 100000 // 100 ms in microseconds
#define StallTimeout 2000000 // 2 seconds in microseconds
#define PWM_RANGE 255

volatile int encoderA_ticks = 0;
volatile int encoderB_ticks = 0;
int running = 1;

void signal_handler(int sig) {
    running = 0;
}

void encoderA_isr(void *user_data) {
    int current_state = gpiod_line_get_value(user_data);
    static int last_state = 0;
    static int last_phaseA = 0;

    if (current_state != last_state) {
        int phaseA = gpiod_line_get_value(ENCODER_A_A);
        int phaseB = gpiod_line_get_value(ENCODER_A_B);

        if (phaseA != last_phaseA) {
            if (phaseB == last_state) {
                encoderA_ticks++;
            } else {
                encoderA_ticks--;
            }
        }

        last_phaseA = phaseA;
    }

    last_state = current_state;
}

void encoderB_isr(void *user_data) {
    int current_state = gpiod_line_get_value(user_data);
    static int last_state = 0;
    static int last_phaseA = 0;

    if (current_state != last_state) {
        int phaseA = gpiod_line_get_value(ENCODER_B_A);
        int phaseB = gpiod_line_get_value(ENCODER_B_B);

        if (phaseA != last_phaseA) {
            if (phaseB == last_state) {
                encoderB_ticks++;
            } else {
                encoderB_ticks--;
            }
        }

        last_phaseA = phaseA;
    }

    last_state = current_state;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *motorA_pwm, *motorA_dir, *motorB_pwm, *motorB_dir;
    struct gpiod_line *encoderA_a, *encoderA_b, *encoderB_a, *encoderB_b;
    struct gpiod_line_request_config config;
    struct gpiod_line_request_config config_isr;
    struct gpiod_line_event event;
    struct timespec last_time, now;
    int pwm_duty_cycle_a = 0, pwm_duty_cycle_b = 0;
    int last_encoderA_ticks = 0, last_encoderB_ticks = 0;
    int stall_count_a = 0, stall_count_b = 0;

    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    motorA_pwm = gpiod_chip_get_line(chip, MOTOR_A_PWM);
    if (!motorA_pwm) {
        perror("Failed to get Motor A PWM line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    motorA_dir = gpiod_chip_get_line(chip, MOTOR_A_DIR);
    if (!motorA_dir) {
        perror("Failed to get Motor A direction line");
        gpiod_line_release(motorA_pwm);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    motorB_pwm = gpiod_chip_get_line(chip, MOTOR_B_PWM);
    if (!motorB_pwm) {
        perror("Failed to get Motor B PWM line");
        gpiod_line_release(motorA_dir);
        gpiod_line_release(motorA_pwm);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    motorB_dir = gpiod_chip_get_line(chip, MOTOR_B_DIR);
    if (!motorB_dir) {
        perror("Failed to get Motor B direction line");
        gpiod_line_release(motorB_pwm);
        gpiod_line_release(motorA_dir);
        gpiod_line_release(motorA_pwm);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

