        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }
    if (gpiod_line_request_output(relay_line, "chicken_coop_relay", 0) < 0) {
        log_event("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    int current_lux = 0;
    int last_log_lux = 0;
    int last_log_relay_state = 0;

    while (1) {
        // Poll sensor every 5 seconds
        sleep(5);

        // Wait at least 180ms after issuing the mode command
        usleep(180 * 1000);

        // Read sensor data
        current_lux = read_bh1750_lux();
        if (current_lux < 0) {
            continue;
        }

        // Check if relay state needs to be changed
        int new_relay_state = last_relay_state;
        if (current_lux < DUSK_LUX - Hysteresis) {
            new_relay_state = 1;
        } else if (current_lux > DAWN_LUX + Hysteresis) {
            new_relay_state = 0;
        }

        if (new_relay_state != last_relay_state) {
            gpiod_line_set_value(relay_line, new_relay_state);
            last_relay_state = new_relay_state;
        }

