#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define RELAY_PIN 17
#define TOUCH_PIN 4
#define DEBOUNCE_DELAY 50
#define LOOP_DELAY 10

static struct gpiod_chip *chip;
static struct gpiod_line *relay_line;
static struct gpiod_line *touch_line;

void log_state_change(int state) {
    time_t now = time(NULL);
    char *iso_time = ctime(&now);
    iso_time[strlen(iso_time) - 1] = '\0'; // Remove newline
    printf("%s - Relay state: %s\n", iso_time, state ? "ON" : "OFF");
}

void sigint_handler(int signum) {
    if (signum == SIGINT) {
        gpiod_line_set_value(relay_line, 0);
        gpiod_chip_close(chip);
        printf("Exiting...\n");
        exit(0);
    }
}

int main() {
    struct gpiod_line_request_config config = {
        .consumer = "touch-relay",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
    };

    // Initialize GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request relay line
    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        perror("Failed to get relay line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(relay_line, &config)) {
        perror("Failed to request relay line");
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request touch line
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    touch_line = gpiod_chip_get_line(chip, TOUCH_PIN);
    if (!touch_line) {
        perror("Failed to get touch line");
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(touch_line, &config)) {
        perror("Failed to request touch line");
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up SIGINT handler
    signal(SIGINT, sigint_handler);

    int relay_state = 0;
    int last_touch_state = 0;
    int touch_count = 0;

    while (1) {
        int current_touch_state = gpiod_line_get_value(touch_line);
        if (current_touch_state == -1) {
            perror("Failed to read touch line");
            break;
        }

        if (current_touch_state != last_touch_state) {
            if (current_touch_state == 1) {
                touch_count++;
                if (touch_count >= 2) {
                    usleep(DEBOUNCE_DELAY * 1000);
                    if (gpiod_line_get_value(touch_line) == 1) {
                        relay_state = !relay_state;
                        gpiod_line_set_value(relay_line, relay_state);
                        log_state_change(relay_state);
                    }
                    touch_count = 0;
                }
            } else {
                touch_count = 0;
            }
        }

        last_touch_state = current_touch_state;
        usleep(LOOP_DELAY * 1000);
    }

    gpiod_line_release(relay_line);
    gpiod_line_release(touch_line);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

