#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <libgpiod.h>

#define FLOW_SENSOR_PIN 17
#define SOLENOID_PIN 27
#define DEBOUNCE_TIMEOUT 1000000 // 1 second in microseconds
#define LITERS_PER_PULSE 0.001 // 1 pulse = 1 milliliter
#define MIN_FLOW_LPM 4.5
#define MAX_FLOW_LPM 5.0
#define Hysteresis 0.5

struct {
    struct gpiod_chip *chip;
    struct gpiod_line *flow_sensor;
    struct gpiod_line *solenoid;
    FILE *log_file;
    pthread_mutex_t mutex;
    int pulse_count;
    int last_state;
} state = {0};

void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(state.log_file, "%s: %s\n", asctime(tm_info), message);
    fflush(state.log_file);
}

void *flow_sensor_thread(void *arg) {
    struct timespec last_debounce_time = {0};
    while (1) {
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);
        if (timespec_diff(&now, &last_debounce_time) >= DEBOUNCE_TIMEOUT) {
            int value = gpiod_line_get_value(state.flow_sensor);
            if (value != state.last_state) {
                if (value == 1) {
                    pthread_mutex_lock(&state.mutex);
                    state.pulse_count++;
                    pthread_mutex_unlock(&state.mutex);
                }
                state.last_state = value;
                last_debounce_time = now;
            }
        }
        nanosleep((struct timespec){1, 0}, NULL);
    }
    return NULL;
}

void handle_signal(int sig) {
    log_event("Signal received, shutting down...");
    gpiod_line_set_value(state.solenoid, 1);
    fclose(state.log_file);
    pthread_mutex_destroy(&state.mutex);
    gpiod_chip_close(state.chip);
    exit(0);
}

int main() {
    state.chip = gpiod_chip_open_by_name("gpiochip0");
    if (!state.chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    state.flow_sensor = gpiod_chip_get_line(state.chip, FLOW_SENSOR_PIN);
    if (!state.flow_sensor) {
        perror("Failed to get flow sensor line");
        gpiod_chip_close(state.chip);
        return 1;
    }

    state.solenoid = gpiod_chip_get_line(state.chip, SOLENOID_PIN);
    if (!state.solenoid) {
        perror("Failed to get solenoid line");
        gpiod_line_release(state.flow_sensor);
        gpiod_chip_close(state.chip);
        return 1;
    }

    if (gpiod_line_request_input(state.flow_sensor, "flow_sensor") < 0) {
        perror("Failed to request flow sensor line as input");
        gpiod_line_release(state.solenoid);
        gpiod_line_release(state.flow_sensor);
        gpiod_chip_close(state.chip);
        return 1;
    }

    if (gpiod_line_request_output(state.solenoid, "solenoid", 1) < 0) {
        perror("Failed to request solenoid line as output");
        gpiod_line_release(state.solenoid);
        gpiod_line_release(state.flow_sensor);
        gpiod_chip_close(state.chip);
        return 1;
    }

    state.log_file = fopen("water_flow.log", "a");
    if (!state.log_file) {
        perror("Failed to open log file");
        gpiod_line_release(state.solenoid);
        gpiod_line_release(state.flow_sensor);
        gpiod_chip_close(state.chip);
        return 1;
    }

    pthread_mutex_init(&state.mutex, NULL);

    pthread_t flow_sensor_tid;
    if (pthread_create(&flow_sensor_tid, NULL, flow_sensor_thread, NULL) != 0) {
        perror("Failed to create flow sensor thread");
        fclose(state.log_file);
        pthread_mutex_destroy(&state.mutex);
        gpiod_line_release(state.solenoid);
        gpiod_line_release(state.flow_sensor);
        gpiod_chip_close(state.chip);
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        pthread_mutex_lock(&state.mutex);
        int pulse_count = state.pulse_count;
        state.pulse_count = 0;
        pthread_mutex_unlock(&state.mutex);

        double flow_rate = (pulse_count * LITERS_PER_PULSE) * 60;
        if (flow_rate > MAX_FLOW_LPM) {
            gpiod_line_set_value(state.solenoid, 0);
        } else if (flow_rate < MIN_FLOW_LPM - Hysteresis) {
            gpiod_line_set_value(state.solenoid, 1);
        }

        log_event(f"Flow rate: %.2f LPM, Solenoid: %s", flow_rate, gpiod_line_get_value(state.solenoid) ? "OPEN" : "CLOSED");
        sleep(1);
    }

    pthread_join(flow_sensor_tid, NULL);
    fclose(state.log_file);
    pthread_mutex_destroy(&state.mutex);
    gpiod_line_release(state.solenoid);
    gpiod_line_release(state.flow_sensor);
    gpiod_chip_close(state.chip);
    return 0;
}

