    if (gpiod_line_request_output(state.solenoid, "solenoid", 1) < 0) {
        perror("Failed to request solenoid line as output");
        gpiod_line_release(state.solenoid);
        gpiod_line_release(state.flow_sensor);
        gpiod_chip_close(state.chip);
        return 1;
    }

    state.log_file = fopen("water_flow.log", "a");
    if (!state.log_file) {
        perror("Failed to open log file");
        gpiod_line_release(state.solenoid);
        gpiod_line_release(state.flow_sensor);
        gpiod_chip_close(state.chip);
        return 1;
    }

    pthread_mutex_init(&state.mutex, NULL);

    pthread_t flow_sensor_tid;
    if (pthread_create(&flow_sensor_tid, NULL, flow_sensor_thread, NULL) != 0) {
        perror("Failed to create flow sensor thread");
        fclose(state.log_file);
        pthread_mutex_destroy(&state.mutex);
        gpiod_line_release(state.solenoid);
        gpiod_line_release(state.flow_sensor);
        gpiod_chip_close(state.chip);
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        pthread_mutex_lock(&state.mutex);
        int pulse_count = state.pulse_count;
        state.pulse_count = 0;
        pthread_mutex_unlock(&state.mutex);

        double flow_rate = (pulse_count * LITERS_PER_PULSE) * 60;
        if (flow_rate > MAX_FLOW_LPM) {
            gpiod_line_set_value(state.solenoid, 0);
        } else if (flow_rate < MIN_FLOW_LPM - Hysteresis) {
            gpiod_line_set_value(state.solenoid, 1);
        }

        log_event(f"Flow rate: %.2f LPM, Solenoid: %s", flow_rate, gpiod_line_get_value(state.solenoid) ? "OPEN" : "CLOSED");
        sleep(1);
    }

    pthread_join(flow_sensor_tid, NULL);
    fclose(state.log_file);
    pthread_mutex_destroy(&state.mutex);
    gpiod_line_release(state.solenoid);
    gpiod_line_release(state.flow_sensor);
    gpiod_chip_close(state.chip);
    return 0;
}
