int read_config(struct Config *config) {
    FILE *file = fopen(CONFIG_FILE, "r");
    if (!file) {
        printf("Failed to open config file: %s\n", strerror(errno));
        return -1;
    }

    char line[BUFFER_SIZE];
    while (fgets(line, BUFFER_SIZE, file)) {
        if (sscanf(line, "calibration_factor=%lf", &config->calibration_factor) == 1) {
            fclose(file);
            return 0;
        }
    }

    fclose(file);
    printf("Failed to parse config file, using default calibration factor\n");
    config->calibration_factor = 1.0;
    return 0;
}

int init_hx711(struct HX711 *hx711) {
    hx711->chip = gpiod_chip_open_by_name("gpiochip0");
    if (!hx711->chip) {
        printf("Failed to open GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    hx711->data = gpiod_chip_get_line(hx711->chip, GPIO_HX711_DATA);
    if (!hx711->data) {
        printf("Failed to get GPIO line for data: %s\n", strerror(errno));
        gpiod_chip_close(hx711->chip);
        return -1;
    }

    if (gpiod_line_request_input(hx711->data, "hx711_data")) {
        printf("Failed to request input for data line: %s\n", strerror(errno));
        gpiod_chip_close(hx711->chip);
        return -1;
    }

    hx711->sck = gpiod_chip_get_line(hx711->chip, GPIO_HX711_SCK);
    if (!hx711->sck) {
        printf("Failed to get GPIO line for SCK: %s\n", strerror(errno));
        gpiod_line_release(hx711->data);
        gpiod_chip_close(hx711->chip);
        return -1;
    }

    if (gpiod_line_request_output(hx711->sck, "hx711_sck", 0)) {
        printf("Failed to request output for SCK line: %s\n", strerror(errno));
        gpiod_line_release(hx711->data);
        gpiod_chip_close(hx711->chip);
        return -1;
    }

    return 0;
}

int init_servo(struct Servo *servo) {
    servo->chip = gpiod_chip_open_by_name("gpiochip0");
    if (!servo->chip) {
        printf("Failed to open GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    servo->line = gpiod_chip_get_line(servo->chip, GPIO_SERVO);
    if (!servo->line) {
        printf("Failed to get GPIO line for servo: %s\n", strerror(errno));
        gpiod_chip_close(servo->chip);
        return -1;
    }

    if (gpiod_line_request_output(servo->line, "servo", 0)) {
        printf("Failed to request output for servo line: %s\n", strerror(errno));
        gpiod_chip_close(servo->chip);
        return -1;
    }

    return 0;
}

int read_hx711(struct HX711 *hx711, int timeout) {
    int count = 0;
    while (gpiod_line_get_value(hx711->data) == 1) {
        if (count++ > timeout) {
            printf("HX711 communication timeout\n");
            return -1;
        }
        usleep(1);
    }

    int value = 0;
    for (int i = 0; i < 24; i++) {
        gpiod_line_set_value(hx711->sck, 1);
        usleep(1);
        value = (value << 1) | gpiod_line_get_value(hx711->data);
        gpiod_line_set_value(hx711->sck, 0);
        usleep(1);
    }

    gpiod_line_set_value(hx711->sck, 1);
    usleep(1);
    gpiod_line_set_value(hx711->sck, 0);
    usleep(1);

    return value;
}

void dispense(struct Servo *servo, int pulse_width) {
    gpiod_line_set_value(servo->line, 1);
    usleep(pulse_width);
    gpiod_line_set_value(servo->line, 0);
}

void log_event(struct DispensingEvent *event) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        printf("Failed to open log file: %s\n", strerror(errno));
        return;
    }

    fprintf(file, "{\"timestamp\": \"%ld\", \"target_weight\": %.2f, \"actual_weight\": %.2f, \"error_message\": \"%s\"}\n",
            event->timestamp, event->target_weight, event->actual_weight, event->error_message);
    fclose(file);
}

int main() {
    struct Config config;
    struct HX711 hx711;
    struct Servo servo;
    struct DispensingEvent event;

    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        printf("Failed to set signal handlers\n");
        return 1;
    }

    if (read_config(&config) != 0) {
        return 1;
    }

    if (init_hx711(&hx711) != 0) {
        return 1;
    }

    if (init_servo(&servo) != 0) {
        gpiod_line_release(hx711.data);
        gpiod_chip_close(hx711.chip);
        return 1;
    }

    int server_fd, new_socket;
    struct sockaddr_in address;
    int addrlen = sizeof(address);
    char buffer[BUFFER_SIZE] = {0};

    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        printf("Failed to create socket: %s\n", strerror(errno));
        gpiod_line_release(hx711.data);
        gpiod_chip_close(hx711.chip);
        gpiod_line_release(servo.line);
        gpiod_chip_close(servo.chip);
        return 1;
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        printf("Failed to bind socket: %s\n", strerror(errno));
        close(server_fd);
        gpiod_line_release(hx711.data);
        gpiod_chip_close(hx711.chip);
        gpiod_line_release(servo.line);
        gpiod_chip_close(servo.chip);
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        printf("Failed to listen on socket: %s\n", strerror(errno));
        close(server_fd);
        gpiod_line_release(hx711.data);
        gpiod_chip_close(hx711.chip);
        gpiod_line_release(servo.line);
        gpiod_chip_close(servo.chip);
        return 1;
    }

    while (1) {
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            printf("Failed to accept connection: %s\n", strerror(errno));
            continue;
        }

        int target_weight;
        if (read(new_socket, buffer, BUFFER_SIZE) <= 0) {
            printf("Failed to read from socket: %s\n", strerror(errno));
            close(new_socket);
            continue;
        }

        target_weight = atoi(buffer);

        event.timestamp = time(NULL);
        event.target_weight = target_weight;
        event.error_message[0] = '\0';

        dispense(&servo, 1500); // 1500 µs pulse width for 1 gram
        usleep(1000000); // Wait for 1 second

        int value = read_hx711(&hx711, 1000);
        if (value < 0) {
            strcpy(event.error_message, "HX711 communication error");
        } else {
            double actual_weight = value * config.calibration_factor;
            event.actual_weight = actual_weight;
        }

        char response[BUFFER_SIZE];
        snprintf(response, BUFFER_SIZE, "{\"actual_weight\": %.2f}", event.actual_weight);
        send(new_socket, response, strlen(response), 0);

        log_event(&event);

        close(new_socket);
    }

    close(server_fd);
    gpiod_line_release(hx711.data);
    gpiod_chip_close(hx711.chip);
    gpiod_line_release(servo.line);
    gpiod_chip_close(servo.chip);

    return 0;
}

