#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define RELAY_PIN 17
#define TOUCH_PIN 4
#define DEBOUNCE_TIME 50

static struct gpiod_chip *chip;
static struct gpiod_line *relay_line;
static struct gpiod_line *touch_line;
static int debounce_interval = DEBOUNCE_TIME;

void log_state(int state) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    printf("%04d-%02d-%02d %02d:%02d:%02d Relay: %s\n",
           tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
           tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec,
           state ? "ON" : "OFF");
}

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        if (relay_line) {
            gpiod_line_set_value(relay_line, 0);
        }
        if (chip) {
            gpiod_chip_close(chip);
        }
        exit(signum);
    }
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "d:")) != -1) {
        switch (opt) {
            case 'd':
                debounce_interval = atoi(optarg);
                if (debounce_interval <= 0) {
                    fprintf(stderr, "Invalid debounce interval: %s\n", optarg);
                    return EXIT_FAILURE;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-d <milliseconds>]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        perror("Failed to get relay line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(relay_line, "relay_control", 0) < 0) {
        perror("Failed to request relay line as output");
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    touch_line = gpiod_chip_get_line(chip, TOUCH_PIN);
    if (!touch_line) {
        perror("Failed to get touch line");
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(touch_line, "touch_sensor") < 0) {
        perror("Failed to request touch line as input");
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int last_state = 0;
    while (1) {
        int current_state = gpiod_line_get_value(touch_line);
        if (current_state != last_state) {
            usleep(debounce_interval * 1000);
            current_state = gpiod_line_get_value(touch_line);
            if (current_state != last_state) {
                last_state = current_state;
                gpiod_line_set_value(relay_line, current_state);
                log_state(current_state);
            }
        }
        usleep(1000);
    }

    gpiod_line_release(relay_line);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

