           tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec,
           state ? "ON" : "OFF");
}

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        if (relay_line) {
            gpiod_line_set_value(relay_line, 0);
        }
        if (chip) {
            gpiod_chip_close(chip);
        }
        exit(signum);
    }
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "d:")) != -1) {
        switch (opt) {
            case 'd':
                debounce_interval = atoi(optarg);
                if (debounce_interval <= 0) {
                    fprintf(stderr, "Invalid debounce interval: %s\n", optarg);
                    return EXIT_FAILURE;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-d <milliseconds>]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        perror("Failed to get relay line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(relay_line, "relay_control", 0) < 0) {
        perror("Failed to request relay line as output");
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    touch_line = gpiod_chip_get_line(chip, TOUCH_PIN);
    if (!touch_line) {
        perror("Failed to get touch line");
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(touch_line, "touch_sensor") < 0) {
        perror("Failed to request touch line as input");
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int last_state = 0;
    while (1) {
        int current_state = gpiod_line_get_value(touch_line);
        if (current_state != last_state) {
            usleep(debounce_interval * 1000);
            current_state = gpiod_line_get_value(touch_line);
            if (current_state != last_state) {
                last_state = current_state;
                gpiod_line_set_value(relay_line, current_state);
                log_state(current_state);
            }
        }
        usleep(1000);
    }

    gpiod_line_release(relay_line);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}
```

This C program for a Raspberry Pi 3 Model B+ monitors a TTP223 capacitive touch sensor on GPIO 4 (BCM) and toggles a 5V relay on GPIO 17 (BCM) each time a valid rising edge (LOW to HIGH) is detected. It uses a stable-level, polling-based debounce of 50ms by default but allows the interval to be overridden with an optional command-line argument `-d <milliseconds>`. The program logs every relay state change to the console with a timestamp in the format "YYYY-MM-DD HH:MM:SS Relay: ON" or "YYYY-MM-DD HH:MM:SS Relay: OFF". It includes robust error handling for every driver library call and installs SIGINT and SIGTERM handlers that turn the relay OFF, release the driver library resources, and exit cleanly.

