#include <signal.h>
#include <termios.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 18
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define PULSE_WIDTH_90_DEG 1500
#define SERVO_FREQ 50
#define SERVO_PERIOD (1000000 / SERVO_FREQ)
#define STEP_ANGLE 10

static struct termios original_termios;
static struct gpiod_chip *chip;
static struct gpiod_line *line;
static int running = 1;

void restore_termios(void) {
    if (tcsetattr(STDIN_FILENO, TCSANOW, &original_termios) != 0) {
        perror("tcsetattr");
    }
}

void handle_sigint(int sig) {
    running = 0;
}

void set_servo_angle(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;

    int pulse_width = PULSE_WIDTH_90_DEG + (angle - 90) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) / 180;
    if (pulse_width < MIN_PULSE_WIDTH) pulse_width = MIN_PULSE_WIDTH;
    if (pulse_width > MAX_PULSE_WIDTH) pulse_width = MAX_PULSE_WIDTH;

    int ret = gpiod_line_set_value(line, pulse_width);
    if (ret < 0) {
        fprintf(stderr, "Failed to set pulse width: %s\n", gpiod_error_str(ret));
        exit(EXIT_FAILURE);
    }
}

int main(void) {
    struct gpiod_line_request_config config = {
        .consumer = "servo_control",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT,
        .default_val = PULSE_WIDTH_90_DEG,
    };

    // Initialize GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int ret = gpiod_line_request(line, &config);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line: %s\n", gpiod_error_str(ret));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up terminal for raw input
    if (tcgetattr(STDIN_FILENO, &original_termios) != 0) {
        perror("tcgetattr");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    struct termios new_termios = original_termios;
    new_termios.c_lflag &= ~(ICANON | ECHO);
    if (tcsetattr(STDIN_FILENO, TCSANOW, &new_termios) != 0) {
        perror("tcsetattr");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    int angle = 90;
    set_servo_angle(angle);
    printf("Current angle: %d°\n", angle);

    while (running) {
        char ch;
        if (read(STDIN_FILENO, &ch, 1) == 1) {
            if (ch == '+') {
                angle += STEP_ANGLE;
            } else if (ch == '-') {
                angle -= STEP_ANGLE;
            } else if (ch == 'q') {
                running = 0;
            }
            set_servo_angle(angle);
            printf("Current angle: %d°\n", angle);
        }
    }

    // Clean up
    restore_termios();
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

