#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define DEBOUNCE_US 2000
#define LOG_INTERVAL_S 5

volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

void log_rpm(double rpm) {
    FILE *log_file = fopen("motor_rpm.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) == -1) {
        perror("Failed to get monotonic time");
        fclose(log_file);
        return;
    }

    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", gmtime(&ts.tv_sec));

    fprintf(log_file, "%s,%0.2f\n", timestamp, rpm);
    fflush(log_file);
    fclose(log_file);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_request req = {
        .consumer = "motor_rpm_monitor",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
        .flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP,
    };

    if ((chip = gpiod_chip_open_by_name(GPIO_CHIP)) == NULL) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    if ((line = gpiod_chip_get_line(chip, GPIO_LINE)) == NULL) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(line, &req) == -1) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    struct timespec last_log_time = {0};
    unsigned int pulse_count = 0;
    struct timespec last_pulse_time = {0};

    while (running) {
        struct gpiod_line_event event;
        if (gpiod_line_event_wait(line, &event, NULL) == -1) {
            perror("Failed to wait for line event");
            break;
        }

        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            struct timespec now;
            if (clock_gettime(CLOCK_MONOTONIC, &now) == -1) {
                perror("Failed to get monotonic time");
                break;
            }

            if (timespec_diff(&now, &last_pulse_time) < DEBOUNCE_US) {
                continue;
            }

            last_pulse_time = now;
            pulse_count++;
        }

        if (timespec_diff(&now, &last_log_time) >= LOG_INTERVAL_S) {
            double rpm = (double)pulse_count * 60 / LOG_INTERVAL_S;
            log_rpm(rpm);
            printf("Current RPM: %.2f\n", rpm);
            last_log_time = now;
            pulse_count = 0;
        }
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

int timespec_diff(struct timespec *a, struct timespec *b) {
    return (a->tv_sec - b->tv_sec) * 1000000 + (a->tv_nsec - b->tv_nsec) / 1000;
}

