#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY_PIN 17
#define TOUCH_PIN 4
#define DEBOUNCE_TIME 50
#define LONG_PRESS_TIME 10

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioSetMode(TOUCH_PIN, PI_INPUT);

    gpioSetPullUpDown(TOUCH_PIN, PI_PUD_UP);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int last_state = 0;
    unsigned long last_change_time = 0;
    int relay_state = 0;

    while (!stop_flag) {
        int current_state = gpioRead(TOUCH_PIN);

        if (current_state != last_state) {
            last_change_time = gpioTick();
        }

        if (gpioTick() - last_change_time > DEBOUNCE_TIME) {
            if (current_state == 0) {
                if (last_state == 1) {
                    relay_state = !relay_state;
                    gpioWrite(RELAY_PIN, relay_state);
                }
            } else {
                if (gpioTick() - last_change_time > LONG_PRESS_TIME * 1000) {
                    relay_state = 0;
                    gpioWrite(RELAY_PIN, relay_state);
                }
            }
            last_state = current_state;
        }

        usleep(50000);
    }

    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

