    if (!flow_sensor_line) {
        perror("Failed to get flow sensor line");
        gpiod_line_release(valve_enable_line);
        gpiod_line_release(valve_pwm_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(valve_pwm_line, "valve_pwm", 0) < 0) {
        perror("Failed to request valve PWM line");
        gpiod_line_release(valve_enable_line);
        gpiod_line_release(valve_pwm_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(valve_enable_line, "valve_enable", 1) < 0) {
        perror("Failed to request valve enable line");
        gpiod_line_release(valve_pwm_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_input(flow_sensor_line, "flow_sensor") < 0) {
        perror("Failed to request flow sensor line");
        gpiod_line_release(valve_enable_line);
        gpiod_line_release(valve_pwm_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_set_direction_input(flow_sensor_line) < 0) {
        perror("Failed to set flow sensor line direction");
        gpiod_line_release(valve_enable_line);
        gpiod_line_release(valve_pwm_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_event(flow_sensor_line, "flow_sensor_event", GPIOD_LINE_REQUEST_EVENT_RISING_EDGE) < 0) {
        perror("Failed to request flow sensor event");
        gpiod_line_release(valve_enable_line);
        gpiod_line_release(valve_pwm_line);
        gpiod_chip_close(chip);
        return 1;
    }

