    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(valve_enable_line);
        gpiod_line_release(valve_pwm_line);
        gpiod_chip_close(chip);
        return 1;
    }

    struct timespec sample_interval = {0, SAMPLE_INTERVAL * 1000 * 1000};
    struct timespec next_sample_time = {0, 0};
    clock_gettime(CLOCK_MONOTONIC, &next_sample_time);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        if (clock_gettime(CLOCK_MONOTONIC, &next_sample_time) < 0) {
            perror("Failed to get current time");
            break;
        }

        if (next_sample_time.tv_sec > 0 || next_sample_time.tv_nsec > 0) {
            if (nanosleep(&sample_interval, NULL) < 0) {
                perror("Failed to sleep");
                break;
            }
        }

        if (clock_gettime(CLOCK_MONOTONIC, &next_sample_time) < 0) {
            perror("Failed to get current time");
            break;
        }

        next_sample_time.tv_sec += sample_interval.tv_sec;
        next_sample_time.tv_nsec += sample_interval.tv_nsec;

        if (next_sample_time.tv_nsec >= 1000 * 1000 * 1000) {
            next_sample_time.tv_sec++;
            next_sample_time.tv_nsec -= 1000 * 1000 * 1000;
        }

        if (gpiod_line_event_wait(flow_sensor_line, &next_sample_time) < 0) {
            perror("Failed to wait for flow sensor event");
            break;
        }

        struct gpiod_line_event event;
        if (gpiod_line_event_read(flow_sensor_line, &event) < 0) {
            perror("Failed to read flow sensor event");
            break;
        }

        flow_count++;
    }

    if (log_file) {
        fclose(log_file);
    }

    gpiod_line_release(valve_enable_line);
    gpiod_line_release(valve_pwm_line);
    gpiod_chip_close(chip);

    return 0;
