#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pthread.h>
#include <libgpiod.h>

#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20
#define ENCODER1_A 5
#define ENCODER1_B 6
#define ENCODER2_A 26
#define ENCODER2_B 19
#define PID_SAMPLE_TIME 100
#define PWM_FREQ 100
#define TARGET_SPEED 60

struct motor {
    struct gpiod_chip *chip;
    struct gpiod_line *ena;
    struct gpiod_line *in1;
    struct gpiod_line *in2;
    struct gpiod_line *encoder_a;
    struct gpiod_line *encoder_b;
    pthread_t thread;
    int encoder_count;
    int direction;
    double pid_p;
    double pid_i;
    double pid_d;
    double pid_output;
    double last_error;
    double integral;
    double last_time;
};

struct motor motors[2];

void *encoder_thread(void *arg) {
    struct motor *motor = (struct motor *)arg;
    struct gpiod_line_event event;
    int ret;

    while (1) {
        ret = gpiod_line_event_wait(motor->encoder_a, 1000);
        if (ret < 0) {
            perror("gpiod_line_event_wait");
            break;
        }

        ret = gpiod_line_event_read(motor->encoder_a, &event);
        if (ret < 0) {
            perror("gpiod_line_event_read");
            break;
        }

        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            if (gpiod_line_get_value(motor->encoder_b) == 0) {
                motor->encoder_count++;
                motor->direction = 1;
            } else {
                motor->encoder_count--;
                motor->direction = -1;
            }
        } else if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            if (gpiod_line_get_value(motor->encoder_b) == 1) {
                motor->encoder_count++;
                motor->direction = 1;
            } else {
                motor->encoder_count--;
                motor->direction = -1;
            }
        }
    }

    return NULL;
}

void pid_control(struct motor *motor) {
    double current_time = (double)clock() / CLOCKS_PER_SEC;
    double dt = current_time - motor->last_time;
    double error = (TARGET_SPEED - motor->encoder_count * 60.0 / dt) * motor->direction;

    motor->integral += error * dt;
    double derivative = (error - motor->last_error) / dt;

    motor->pid_output = motor->pid_p * error + motor->pid_i * motor->integral + motor->pid_d * derivative;

    if (motor->pid_output > 100) {
        motor->pid_output = 100;
    } else if (motor->pid_output < -100) {
        motor->pid_output = -100;
    }

    int duty_cycle = (int)motor->pid_output;
    gpiod_line_set_value(motor->ena, duty_cycle);

    motor->last_error = error;
    motor->last_time = current_time;
}

void signal_handler(int signum) {
    for (int i = 0; i < 2; i++) {
        gpiod_line_set_value(motors[i].ena, 0);
        gpiod_line_release(motors[i].ena);
        gpiod_line_release(motors[i].in1);
        gpiod_line_release(motors[i].in2);
        gpiod_line_release(motors[i].encoder_a);
        gpiod_line_release(motors[i].encoder_b);
        gpiod_chip_close(motors[i].chip);
    }

    for (int i = 0; i < 2; i++) {
        pthread_join(motors[i].thread, NULL);
    }

    fclose(motors[0].log_file);
    fclose(motors[1].log_file);

    exit(signum);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    for (int i = 0; i < 2; i++) {
        motors[i].chip = gpiod_chip_open_by_name("gpiochip0");
        if (!motors[i].chip) {
            perror("gpiod_chip_open_by_name");
            return EXIT_FAILURE;
        }

        motors[i].ena = gpiod_chip_get_line(motors[i].chip, MOTOR1_ENA + i * 11);
        if (!motors[i].ena) {
            perror("gpiod_chip_get_line");
            gpiod_chip_close(motors[i].chip);
            return EXIT_FAILURE;
        }

        ret = gpiod_line_request_output(motors[i].ena, "motor_ena", 0);
        if (ret < 0) {
            perror("gpiod_line_request_output");
            gpiod_line_release(motors[i].ena);
            gpiod_chip_close(motors[i].chip);
            return EXIT_FAILURE;
        }

        motors[i].in1 = gpiod_chip_get_line(motors[i].chip, MOTOR1_IN1 + i * 11);
        if (!motors[i].in1) {
            perror("gpiod_chip_get_line");
            gpiod_line_release(motors[i].ena);
            gpiod_chip_close(motors[i].chip);
            return EXIT_FAILURE;
        }

        ret = gpiod_line_request_output(motors[i].in1, "motor_in1", 0);
        if (ret < 0) {
            perror("gpiod_line_request_output");
            gpiod_line_release(motors[i].in1);
            gpiod_line_release(motors[i].ena);
            gpiod_chip_close(motors[i].chip);
            return EXIT_FAILURE;
        }

        motors[i].in2 = gpiod_chip_get_line(motors[i].chip, MOTOR1_IN2 + i * 11);
        if (!motors[i].in2) {
            perror("gpiod_chip_get_line");
            gpiod_line_release(motors[i].in1);
            gpiod_line_release(motors[i].ena);
            gpiod_chip_close(motors[i].chip);
            return EXIT_FAILURE;
        }

        ret = gpiod_line_request_output(motors[i].in2, "motor_in2", 0);
        if (ret < 0) {
            perror("gpiod_line_request_output");
            gpiod_line_release(motors[i].in2);
            gpiod_line_release(motors[i].in1);
            gpiod_line_release(motors[i].ena);
            gpiod_chip_close(motors[i].chip);
            return EXIT_FAILURE;
        }

        motors[i].encoder_a = gpiod_chip_get_line(motors[i].chip, ENCODER1_A + i * 11);
        if (!motors[i].encoder_a) {
            perror("gpiod_chip_get_line");
            gpiod_line_release(motors[i].in2);
            gpiod_line_release(motors[i].in1);
            gpiod_line_release(motors[i].ena);
            gpiod_chip_close(motors[i].chip);
            return EXIT_FAILURE;
        }

        ret = gpiod_line_request_input(motors[i].encoder_a, "encoder_a");
        if (ret < 0) {
            perror("gpiod_line_request_input");
            gpiod_line_release(motors[i].encoder_a);
            gpiod_line_release(motors[i].in2);
            gpiod_line_release(motors[i].in1);
            gpiod_line_release(motors[i].ena);
            gpiod_chip_close(motors[i].chip);
            return EXIT_FAILURE;
        }

        motors[i].encoder_b = gpiod_chip_get_line(motors[i].chip, ENCODER1_B + i * 11);
        if (!motors[i].encoder_b) {
            perror("gpiod_chip_get_line");
            gpiod_line_release(motors[i].encoder_a);
            gpiod_line_release(motors[i].in2);
            gpiod_line_release(motors[i].in1);
            gpiod_line_release(motors[i].ena);
            gpiod_chip_close(motors[i].chip);
            return EXIT_FAILURE;
        }

        ret = gpiod_line_request_input(motors[i].encoder_b, "encoder_b");
        if (ret < 0) {
            perror("gpiod_line_request_input");
            gpiod_line_release(motors[i].encoder_b);
            gpiod_line_release(motors[i].encoder_a);
            gpiod_line_release(motors[i].in2);
            gpiod_line_release(motors[i].in1);
            gpiod_line_release(motors[i].ena);
            gpiod_chip_close(motors[i].chip);
            return EXIT_FAILURE;
        }

        motors[i].encoder_count = 0;
        motors[i].direction = 1;
        motors[i].pid_p = 1.0;
        motors[i].pid_i = 0.1;
        motors[i].pid_d = 0.01;
        motors[i].pid_output = 0.0;
        motors[i].last_error = 0.0;
        motors[i].integral = 0.0;
        motors[i].last_time = (double)clock() / CLOCKS_PER_SEC;

        motors[i].log_file = fopen("motor_log.csv", "a");
        if (!motors[i].log_file) {
            perror("fopen");
            gpiod_line_release(motors[i].encoder_b);
            gpiod_line_release(motors[i].encoder_a);
            gpiod_line_release(motors[i].in2);
            gpiod_line_release(motors[i].in1);
            gpiod_line_release(motors[i].ena);
            gpiod_chip_close(motors[i].chip);
            return EXIT_FAILURE;
        }

        if (i == 0) {
            fprintf(motors[i].log_file, "Time, Motor1 Speed, Motor1 P, Motor1 I, Motor1 D, Motor1 Output\n");
        } else {
            fprintf(motors[i].log_file, "Time, Motor2 Speed, Motor2 P, Motor2 I, Motor2 D, Motor2 Output\n");
        }

        ret = pthread_create(&motors[i].thread, NULL, encoder_thread, &motors[i]);
        if (ret != 0) {
            perror("pthread_create");
            fclose(motors[i].log_file);
            gpiod_line_release(motors[i].encoder_b);
            gpiod_line_release(motors[i].encoder_a);
            gpiod_line_release(motors[i].in2);
            gpiod_line_release(motors[i].in1);
            gpiod_line_release(motors[i].ena);
            gpiod_chip_close(motors[i].chip);
            return EXIT_FAILURE;
        }
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        for (int i = 0; i < 2; i++) {
            pid_control(&motors[i]);
            double current_time = (double)clock() / CLOCKS_PER_SEC;
            fprintf(motors[i].log_file, "%f, %d, %f, %f, %f, %f\n", current_time, motors[i].encoder_count * 60.0 / PID_SAMPLE_TIME, motors[i].pid_p, motors[i].pid_i, motors[i].pid_d, motors[i].pid_output);
            fflush(motors[i].log_file);
        }
        usleep(PID_SAMPLE_TIME * 1000);
    }

    return EXIT_SUCCESS;
}

