        motors[i].pid_output = 0.0;
        motors[i].last_error = 0.0;
        motors[i].integral = 0.0;
        motors[i].last_time = (double)clock() / CLOCKS_PER_SEC;

        motors[i].log_file = fopen("motor_log.csv", "a");
        if (!motors[i].log_file) {
            perror("fopen");
            gpiod_line_release(motors[i].encoder_b);
            gpiod_line_release(motors[i].encoder_a);
            gpiod_line_release(motors[i].in2);
            gpiod_line_release(motors[i].in1);
            gpiod_line_release(motors[i].ena);
            gpiod_chip_close(motors[i].chip);
            return EXIT_FAILURE;
        }

        if (i == 0) {
            fprintf(motors[i].log_file, "Time, Motor1 Speed, Motor1 P, Motor1 I, Motor1 D, Motor1 Output\n");
        } else {
            fprintf(motors[i].log_file, "Time, Motor2 Speed, Motor2 P, Motor2 I, Motor2 D, Motor2 Output\n");
        }

        ret = pthread_create(&motors[i].thread, NULL, encoder_thread, &motors[i]);
        if (ret != 0) {
            perror("pthread_create");
            fclose(motors[i].log_file);
            gpiod_line_release(motors[i].encoder_b);
            gpiod_line_release(motors[i].encoder_a);
            gpiod_line_release(motors[i].in2);
            gpiod_line_release(motors[i].in1);
            gpiod_line_release(motors[i].ena);
            gpiod_chip_close(motors[i].chip);
            return EXIT_FAILURE;
        }
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        for (int i = 0; i < 2; i++) {
            pid_control(&motors[i]);
            double current_time = (double)clock() / CLOCKS_PER_SEC;
            fprintf(motors[i].log_file, "%f, %d, %f, %f, %f, %f\n", current_time, motors[i].encoder_count * 60.0 / PID_SAMPLE_TIME, motors[i].pid_p, motors[i].pid_i, motors[i].pid_d, motors[i].pid_output);
            fflush(motors[i].log_file);
        }
        usleep(PID_SAMPLE_TIME * 1000);
    }

    return EXIT_SUCCESS;
}
