#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <gpiod.h>

#define MPR121_I2C_ADDRESS 0x5A
#define MPR121_SOFT_RESET 0x80
#define MPR121_CONFIG 0x5E
#define MPR121_TOUCH_THRESHOLD 0x20
#define MPR121_RELEASE_THRESHOLD 0x2B
#define MPR121_ELECTRODE_COUNT 12
#define GPIO_PIN 17
#define LOG_FILE "relay_log.txt"

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static int log_fd;

void handle_sigint(int sig) {
    if (line) {
        gpiod_line_set_value(line, 0);
    }
    if (log_fd != -1) {
        close(log_fd);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

int main() {
    struct timespec ts;
    uint8_t touch_status;
    uint8_t electrode_status[MPR121_ELECTRODE_COUNT];
    int i;

    // Initialize GPIO
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "relay_control", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initialize I2C
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MPR121_I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // MPR121 initialization sequence
    uint8_t reset_cmd = MPR121_SOFT_RESET;
    if (write(fd, &reset_cmd, 1) != 1) {
        perror("Failed to send soft reset command");
        close(fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    usleep(100000); // Wait for reset to complete

    uint8_t config_cmd = 0x00;
    if (write(fd, &config_cmd, 1) != 1) {
        perror("Failed to send configuration command");
        close(fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    for (i = 0; i < MPR121_ELECTRODE_COUNT; i++) {
        uint8_t touch_threshold = MPR121_TOUCH_THRESHOLD;
        if (write(fd, &touch_threshold, 1) != 1) {
            perror("Failed to send touch threshold command");
            close(fd);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        uint8_t release_threshold = MPR121_RELEASE_THRESHOLD;
        if (write(fd, &release_threshold, 1) != 1) {
            perror("Failed to send release threshold command");
            close(fd);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    uint8_t run_mode_cmd = 0x80;
    if (write(fd, &run_mode_cmd, 1) != 1) {
        perror("Failed to send run mode command");
        close(fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open log file
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        close(fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up signal handler
    signal(SIGINT, handle_sigint);

    while (1) {
        // Read touch status
        if (read(fd, &touch_status, 1) != 1) {
            perror("Failed to read touch status");
            close(fd);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        // Check each electrode
        for (i = 0; i < MPR121_ELECTRODE_COUNT; i++) {
            electrode_status[i] = (touch_status >> i) & 0x01;
        }

        // Determine relay state
        int relay_state = 0;
        for (i = 0; i < MPR121_ELECTRODE_COUNT; i++) {
            if (electrode_status[i]) {
                relay_state = 1;
                break;
            }
        }

        // Set relay state
        if (gpiod_line_set_value(line, relay_state) < 0) {
            perror("Failed to set relay state");
            close(fd);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        // Log relay state change
        if (relay_state) {
            clock_gettime(CLOCK_REALTIME, &ts);
            fprintf(log_fd, "Relay ON at %ld.%09ld\n", ts.tv_sec, ts.tv_nsec);
        } else {
            clock_gettime(CLOCK_REALTIME, &ts);
            fprintf(log_fd, "Relay OFF at %ld.%09ld\n", ts.tv_sec, ts.tv_nsec);
        }

        // Wait 50 ms
        usleep(50000);
    }

    // Clean up
    close(fd);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

