#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define RELAY1_LINE 17
#define RELAY2_LINE 18
#define LOG_FILE "valve_log.txt"
#define VALVE1_DURATION 500
#define VALVE2_DURATION 1000
#define PAUSE1_DURATION 5000
#define PAUSE2_DURATION 10000

struct gpiod_chip *chip;
struct gpiod_line *relay1, *relay2;
FILE *log_file;

void log_event(const char *valve, int duration) {
    time_t now = time(NULL);
    char *iso_time = ctime(&now);
    iso_time[strlen(iso_time) - 1] = '\0'; // Remove newline character
    fprintf(log_file, "%s: %s activated for %d ms\n", iso_time, valve, duration);
    fflush(log_file);
}

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        if (relay1) gpiod_line_release(relay1);
        if (relay2) gpiod_line_release(relay2);
        if (chip) gpiod_chip_close(chip);
        if (log_file) fclose(log_file);
        printf("Exiting...\n");
        exit(signum);
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    relay1 = gpiod_chip_get_line(chip, RELAY1_LINE);
    if (!relay1) {
        perror("Failed to get line for relay 1");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    relay2 = gpiod_chip_get_line(chip, RELAY2_LINE);
    if (!relay2) {
        perror("Failed to get line for relay 2");
        gpiod_line_release(relay1);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(relay1, "valve1", 0) < 0) {
        perror("Failed to request output for relay 1");
        gpiod_line_release(relay2);
        gpiod_line_release(relay1);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(relay2, "valve2", 0) < 0) {
        perror("Failed to request output for relay 2");
        gpiod_line_release(relay2);
        gpiod_line_release(relay1);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(relay2);
        gpiod_line_release(relay1);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        gpiod_line_set_value(relay1, 1);
        log_event("Valve 1", VALVE1_DURATION);
        usleep(VALVE1_DURATION * 1000);
        gpiod_line_set_value(relay1, 0);
        usleep(PAUSE1_DURATION * 1000);

        gpiod_line_set_value(relay2, 1);
        log_event("Valve 2", VALVE2_DURATION);
        usleep(VALVE2_DURATION * 1000);
        gpiod_line_set_value(relay2, 0);
        usleep(PAUSE2_DURATION * 1000);
    }

    return EXIT_SUCCESS;
}

