This C program for a Raspberry Pi 4 Model B uses the `libgpiod` library to control two Adafruit Solenoid Valves through relay modules connected to GPIO pins 17 and 18. The program logs each activation event with an ISO 8601 timestamp to a file named `valve_log.txt`. It includes robust error handling for GPIO chip initialization failures, line request failures, and file I/O errors. The program also installs signal handlers for `SIGINT` and `SIGTERM` to ensure clean release of all GPIO lines and closure of the log file on exit. The schedule repeats indefinitely until interrupted.

code:
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x5A
#define RELAY_PIN 17
#define SDA_PIN 2
#define SCL_PIN 3
#define STABILIZATION_DELAY 100
#define LOOP_DELAY 100

static struct gpiod_chip *chip;
static struct gpiod_line *relay_line;
static int i2c_fd;

void handle_sigint(int sig) {
    printf("Received signal %d, shutting down...\n", sig);
    if (relay_line) {
        gpiod_line_release(relay_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(0);
}

int main() {
    struct gpiod_line_request_config relay_config = {
        .consumer = "relay",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT,
        .default_val = 0,
    };

    struct i2c_msg msgs[2];
    uint8_t buf[2];

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    // Initialize I2C
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        perror("Failed to get relay line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(relay_line, &relay_config) < 0) {
        perror("Failed to request relay line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize MPR121
    buf[0] = 0x5E;
    buf[1] = 0x00; // Stop mode
    if (write(i2c_fd, buf, 2) != 2) {
        perror("Failed to write to MPR121");
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    buf[0] = 0x2B;
    buf[1] = 0x00; // Touch threshold
    if (write(i2c_fd, buf, 2) != 2) {
        perror("Failed to write to MPR121");
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    buf[0] = 0x2D;
    buf[1] = 0x00; // Release threshold
    if (write(i2c_fd, buf, 2) != 2) {
        perror("Failed to write to MPR121");
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
