#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define PIR_SENSOR_PIN 17
#define RELAY_PIN 18
#define POLL_INTERVAL_MS 50
#define UNLOCK_DURATION_MS 500
#define RATE_LIMIT_SECONDS 2

static struct gpiod_chip *chip;
static struct gpiod_line *pir_sensor;
static struct gpiod_line *relay;
static FILE *log_file;
static int rate_limit_active = 0;
static time_t last_unlock_time;

void log_event(const char *event) {
    if (log_file) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        fprintf(log_file, "%s: %s\n", asctime(tm_info), event);
        fflush(log_file);
    }
}

void handle_signal(int sig) {
    if (sig == SIGINT) {
        log_event("Program terminated by user");
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    struct timespec poll_interval = {0, POLL_INTERVAL_MS * 1000 * 1000};
    struct timespec unlock_duration = {0, UNLOCK_DURATION_MS * 1000 * 1000};
    struct timespec rate_limit_duration = {RATE_LIMIT_SECONDS, 0};

    // Initialize GPIO library
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Request PIR sensor line
    pir_sensor = gpiod_chip_get_line(chip, PIR_SENSOR_PIN);
    if (!pir_sensor) {
        fprintf(stderr, "Failed to get PIR sensor line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Configure PIR sensor line as input with pull-down
    if (gpiod_line_request_input(pir_sensor, "pir_sensor") < 0) {
        fprintf(stderr, "Failed to request PIR sensor line as input\n");
        gpiod_line_release(pir_sensor);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request relay line
    relay = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay) {
        fprintf(stderr, "Failed to get relay line\n");
        gpiod_line_release(pir_sensor);
        gpiod_chip_close(chip);
        return 1;
    }

    // Configure relay line as output
    if (gpiod_line_request_output(relay, "relay", 0) < 0) {
        fprintf(stderr, "Failed to request relay line as output\n");
        gpiod_line_release(pir_sensor);
        gpiod_chip_close(chip);
        return 1;
    }

    // Open log file
    log_file = fopen("door_events.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_line_release(relay);
        gpiod_line_release(pir_sensor);
        gpiod_chip_close(chip);
        return 1;
    }

    // Register signal handler
    signal(SIGINT, handle_signal);

    log_event("Program started");

    while (1) {
        int pir_state = gpiod_line_get_value(pir_sensor);
        if (pir_state == 1) {
            if (!rate_limit_active) {
                log_event("Motion detected");
                gpiod_line_set_value(relay, 1);
                log_event("Door unlocked");
                nanosleep(&unlock_duration, NULL);
                gpiod_line_set_value(relay, 0);
                log_event("Door locked");
                last_unlock_time = time(NULL);
                rate_limit_active = 1;
            }
        } else {
            if (rate_limit_active && time(NULL) - last_unlock_time >= rate_limit_duration.tv_sec) {
                rate_limit_active = 0;
            }
        }

        nanosleep(&poll_interval, NULL);
    }

    // Clean up
    log_event("Program terminated");
    fclose(log_file);
    gpiod_line_release(relay);
    gpiod_line_release(pir_sensor);
    gpiod_chip_close(chip);

    return 0;
}

