This C program for a Raspberry Pi 5 monitors an HC-SR501 PIR sensor on GPIO 17 (BCM numbering) and controls an electric door strike relay on GPIO 18 (BCM) using the libgpiod library. The program uses a single-threaded, non-blocking polling loop with a 50 ms interval to detect a rising edge from 0 to 1. On each motion detection, the program activates the relay for exactly 500 ms to momentarily unlock the door strike, then enforces rate limiting by ignoring any further motion events for 2 seconds after each unlock. The program writes millisecond-precision timestamps to a file named `door_events.log` for every motion detected, door unlocked, and rate-limited event. If the driver library fails to initialize, the program prints a clear error message and exits with status 1. On normal termination or receipt of SIGINT, the program cleans up by closing the log file, terminating the driver library, and ensuring the relay is set to off.

code:
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27
#define MIN_STEPS 5
#define MAX_STEPS 15
#define MIN_DUTY 0
#define MAX_DUTY 255
#define MIN_DURATION 50
#define MAX_DURATION 200

volatile sig_atomic_t shutdown_flag = 0;

void signal_handler(int signum) {
    if (signum == SIGINT) {
        shutdown_flag = 1;
    }
}

void generate_random_pattern(int *steps, int *duty1, int *duty2, int *duration) {
    for (int i = 0; i < steps; i++) {
        duty1[i] = rand() % (MAX_DUTY - MIN_DUTY + 1) + MIN_DUTY;
        duty2[i] = rand() % (MAX_DUTY - MIN_DUTY + 1) + MIN_DUTY;
        duration[i] = rand() % (MAX_DURATION - MIN_DURATION + 1) + MIN_DURATION;
    }
}

void play_pattern(struct gpiod_chip *chip, int *steps, int *duty1, int *duty2, int *duration) {
    struct gpiod_line *line1 = gpiod_chip_get_line(chip, MOTOR1_PIN);
    struct gpiod_line *line2 = gpiod_chip_get_line(chip, MOTOR2_PIN);

    if (!line1 || !line2) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        return;
    }

    if (gpiod_line_request_output(line1, "motor1", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line for motor1\n");
        gpiod_line_release(line1);
        return;
    }

    if (gpiod_line_request_output(line2, "motor2", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line for motor2\n");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        return;
    }

    for (int i = 0; i < steps; i++) {
        if (gpiod_line_set_value(line1, duty1[i]) < 0) {
            fprintf(stderr, "Failed to set duty cycle for motor1\n");
        }

        if (gpiod_line_set_value(line2, duty2[i]) < 0) {
            fprintf(stderr, "Failed to set duty cycle for motor2\n");
        }

        usleep(duration[i] * 1000);
    }

    gpiod_line_release(line1);
    gpiod_line_release(line2);
}

int main() {
    struct gpiod_chip *chip;
    int steps, *duty1, *duty2, *duration;

    srand(time(NULL));

    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    duty1 = malloc(MAX_STEPS * sizeof(int));
    duty2 = malloc(MAX_STEPS * sizeof(int));
    duration = malloc(MAX_STEPS * sizeof(int));

    if (!duty1 || !duty2 || !duration) {
        fprintf(stderr, "Memory allocation failed\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (!shutdown_flag) {
        steps = rand() % (MAX_STEPS - MIN_STEPS + 1) + MIN_STEPS;
        generate_random_pattern(steps, duty1, duty2, duration);
        play_pattern(chip, steps, duty1, duty2, duration);
    }

    free(duty1);
    free(duty2);
    free(duration);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

