#include <signal.h>
#include <libgpiod.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "weight_log.txt"
#define TIMEOUT 500000 // 0.5 seconds in microseconds
#define STARTUP_CALIBRATION_COUNT 100
#define THRESHOLD 10000 // 10 kg in grams

static struct gpiod_chip *chip;
static struct gpiod_line *hx711_data, *hx711_clock, *solenoid;
static FILE *log_file = NULL;
static double scale_factor = 1.0, offset = 0.0;

static void cleanup() {
    if (hx711_data) gpiod_line_release(hx711_data);
    if (hx711_clock) gpiod_line_release(hx711_clock);
    if (solenoid) gpiod_line_release(solenoid);
    if (chip) gpiod_chip_close(chip);
    if (log_file) fclose(log_file);
}

static void handle_sigint(int sig) {
    cleanup();
    exit(0);
}

static int hx711_read() {
    int data = 0;
    int bit = 0;
    int timeout = TIMEOUT;

    gpiod_line_set_value(hx711_clock, 0);
    gpiod_line_set_value(hx711_clock, 1);

    while (timeout > 0) {
        if (gpiod_line_get_value(hx711_data) == 1) {
            data |= (1 << bit);
        }
        gpiod_line_set_value(hx711_clock, 0);
        gpiod_line_set_value(hx711_clock, 1);
        bit++;
        timeout -= 1000; // 1 microsecond
    }

    if (timeout <= 0) {
        return -1; // Timeout
    }

    return data;
}

static double hx711_get_value() {
    int data = hx711_read();
    if (data == -1) {
        return -1.0; // Timeout
    }

    // HX711 returns a 24-bit value, but we only use 23 bits
    data = (data & 0x7FFFFF) ^ 0x800000;
    return (double)data * scale_factor + offset;
}

static void startup_calibration() {
    double sum = 0.0;
    for (int i = 0; i < STARTUP_CALIBRATION_COUNT; i++) {
        double value = hx711_get_value();
        if (value != -1.0) {
            sum += value;
        }
    }
    offset = sum / STARTUP_CALIBRATION_COUNT;
}

static void load_calibration() {
    FILE *file = fopen(CALIBRATION_FILE, "r");
    if (file) {
        if (fscanf(file, "%lf %lf", &scale_factor, &offset) != 2) {
            fclose(file);
            scale_factor = 1.0;
            offset = 0.0;
        } else {
            fclose(file);
        }
    } else {
        scale_factor = 1.0;
        offset = 0.0;
    }
}

static void save_calibration() {
    FILE *file = fopen(CALIBRATION_FILE, "w");
    if (file) {
        fprintf(file, "%.6f %.6f\n", scale_factor, offset);
        fclose(file);
    }
}

int main() {
    signal(SIGINT, handle_sigint);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    hx711_data = gpiod_chip_get_line(chip, HX711_DATA_PIN);
    if (!hx711_data) {
        perror("Failed to get HX711 data line");
        cleanup();
        return 1;
    }

    hx711_clock = gpiod_chip_get_line(chip, HX711_CLOCK_PIN);
    if (!hx711_clock) {
        perror("Failed to get HX711 clock line");
        cleanup();
        return 1;
    }

    solenoid = gpiod_chip_get_line(chip, SOLENOID_PIN);
    if (!solenoid) {
        perror("Failed to get solenoid line");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_input(hx711_data, "hx711_data") < 0) {
        perror("Failed to request HX711 data line");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(hx711_clock, "hx711_clock", 0) < 0) {
        perror("Failed to request HX711 clock line");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(solenoid, "solenoid", 0) < 0) {
        perror("Failed to request solenoid line");
        cleanup();
        return 1;
    }

    load_calibration();
    startup_calibration();

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    while (1) {
        double value = hx711_get_value();
        if (value != -1.0) {
            time_t now = time(NULL);
            fprintf(log_file, "%s %.6f\n", ctime(&now), value);
            fflush(log_file);

            if (value > THRESHOLD) {
                gpiod_line_set_value(solenoid, 1);
            } else {
                gpiod_line_set_value(solenoid, 0);
            }
        }
        usleep(500000); // 500 ms
    }

    cleanup();
    return 0;
}

