#define CLOSE_DURATION 5

static struct gpiod_chip *chip;
static struct gpiod_line *sensor_line, *motor_in1_line, *motor_in2_line, *motor_pwm_line;
static int motor_running = 0;

void log_event(const char *event) {
    char timestamp[20];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    syslog(LOG_INFO, "%s: %s", timestamp, event);
}

void close_window() {
    if (motor_running) {
        return;
    }
    motor_running = 1;
    log_event("Closing window");

    gpiod_line_set_value(motor_in1_line, 1);
    gpiod_line_set_value(motor_in2_line, 0);
    gpiod_line_set_value(motor_pwm_line, PWM_DUTY_CYCLE);

    usleep(CLOSE_DURATION * 1000000);

    gpiod_line_set_value(motor_in1_line, 0);
    gpiod_line_set_value(motor_in2_line, 0);
    gpiod_line_set_value(motor_pwm_line, 0);

    motor_running = 0;
    log_event("Window closed");
}

