    if (sig == SIGINT || sig == SIGTERM) {
        if (motor_running) {
            close_window();
        }
        gpiod_line_release(sensor_line);
        gpiod_line_release(motor_in1_line);
        gpiod_line_release(motor_in2_line);
        gpiod_line_release(motor_pwm_line);
        gpiod_chip_close(chip);
        closelog();
        exit(0);
    }
}

