    for (int i = 0; i < DEBOUNCE_COUNT; i++) {
        int value = gpiod_line_get_value(sensor_line);
        if (value == 0) {
            count++;
        }
        usleep(DEBOUNCE_INTERVAL * 1000);
    }
    return count >= DEBOUNCE_COUNT / 2;
}

