#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27
#define CALIBRATION_FILE "calibration.txt"
#define SECURITY_LOG "security.log"
#define TIMEOUT_US 100000
#define THRESHOLD_KG 5.0
#define LOCK_DURATION_S 5

static struct gpiod_chip *chip;
static struct gpiod_line *data_line, *clock_line, *solenoid_line;
static FILE *calibration_file, *security_log;
static int calibration_factor = 0;

void init_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    data_line = gpiod_chip_get_line(chip, HX711_DATA_PIN);
    if (!data_line) {
        perror("Failed to get data line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(data_line, "hx711_data")) {
        perror("Failed to request data line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    clock_line = gpiod_chip_get_line(chip, HX711_CLOCK_PIN);
    if (!clock_line) {
        perror("Failed to get clock line");
        gpiod_line_release(data_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(clock_line, "hx711_clock", 0)) {
        perror("Failed to request clock line");
        gpiod_line_release(data_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    solenoid_line = gpiod_chip_get_line(chip, SOLENOID_PIN);
    if (!solenoid_line) {
        perror("Failed to get solenoid line");
        gpiod_line_release(clock_line);
        gpiod_line_release(data_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(solenoid_line, "solenoid", 0)) {
        perror("Failed to request solenoid line");
        gpiod_line_release(clock_line);
        gpiod_line_release(data_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
}

void read_calibration() {
    calibration_file = fopen(CALIBRATION_FILE, "r");
    if (calibration_file) {
        if (fscanf(calibration_file, "%d", &calibration_factor) != 1) {
            perror("Failed to read calibration factor");
            fclose(calibration_file);
            calibration_file = NULL;
        } else {
            fclose(calibration_file);
        }
    }
}

void write_calibration(int factor) {
    calibration_file = fopen(CALIBRATION_FILE, "w");
    if (calibration_file) {
        fprintf(calibration_file, "%d", factor);
        fclose(calibration_file);
    } else {
        perror("Failed to write calibration factor");
    }
}

int read_hx711() {
    int value = 0;
    for (int i = 0; i < 24; i++) {
        gpiod_line_set_value(clock_line, 1);
        usleep(1);
        value = (value << 1) | gpiod_line_get_value(data_line);
        gpiod_line_set_value(clock_line, 0);
        usleep(1);
    }
    return value;
}

void lock_solenoid() {
    gpiod_line_set_value(solenoid_line, 1);
    usleep(LOCK_DURATION_S * 1000000);
    gpiod_line_set_value(solenoid_line, 0);
}

void log_event(double weight) {
    security_log = fopen(SECURITY_LOG, "a");
    if (security_log) {
        time_t now = time(NULL);
        fprintf(security_log, "%s: %.2f kg\n", ctime(&now), weight);
        fclose(security_log);
    } else {
        perror("Failed to open security log");
    }
}

void handle_sigint(int sig) {
    if (solenoid_line) {
        gpiod_line_set_value(solenoid_line, 0);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (calibration_file) {
        fclose(calibration_file);
    }
    if (security_log) {
        fclose(security_log);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, handle_sigint);

    init_gpio();
    read_calibration();

    if (!calibration_factor) {
        printf("Please place a known weight on the scale...\n");
        int known_weight = read_hx711();
        printf("Known weight read: %d\n", known_weight);
        printf("Please place the scale on a known weight...\n");
        int scale_weight = read_hx711();
        printf("Scale weight read: %d\n", scale_weight);
        calibration_factor = known_weight / scale_weight;
        write_calibration(calibration_factor);
    }

    while (1) {
        int raw_value = read_hx711();
        double weight = (double)raw_value * calibration_factor / 1000000.0;

        if (weight > THRESHOLD_KG) {
            lock_solenoid();
            log_event(weight);
        }

        usleep(10000);
    }

    return 0;
}

