#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define SENSOR_LINE "gpiochip0:line16"
#define RELAY_LINE "gpiochip0:line20"
#define LOG_FILE "relay_events.log"

static struct gpiod_chip *chip;
static struct gpiod_line *sensor_line, *relay_line;
static FILE *log_file;

void log_event(const char *state) {
    time_t now = time(NULL);
    char *iso_time = ctime(&now);
    iso_time[strlen(iso_time) - 1] = '\0'; // Remove newline character

    fprintf(log_file, "%s - Relay state: %s\n", iso_time, state);
    fflush(log_file);
}

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        if (log_file) fclose(log_file);
        if (sensor_line) gpiod_line_release(sensor_line);
        if (relay_line) gpiod_line_release(relay_line);
        if (chip) gpiod_chip_close(chip);
        exit(0);
    }
}

int main() {
    struct gpiod_line_request_config config = {
        .consumer = "ir_sensor_relay",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
    };

    // Initialize signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request sensor line
    sensor_line = gpiod_chip_get_line(chip, 16);
    if (!sensor_line) {
        perror("Failed to get sensor line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(sensor_line, &config)) {
        perror("Failed to request sensor line");
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request relay line
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    relay_line = gpiod_chip_get_line(chip, 20);
    if (!relay_line) {
        perror("Failed to get relay line");
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(relay_line, &config)) {
        perror("Failed to request relay line");
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(sensor_line);
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initial state
    int last_state = 0;
    int current_state;

    while (1) {
        current_state = gpiod_line_get_value(sensor_line);
        if (current_state == -1) {
            perror("Failed to read sensor line");
            continue;
        }

        if (current_state != last_state) {
            last_state = current_state;
            if (last_state == 0) {
                // Obstacle detected, toggle relay
                int relay_state = gpiod_line_get_value(relay_line);
                if (relay_state == -1) {
                    perror("Failed to read relay line");
                    continue;
                }

                if (relay_state == 0) {
                    gpiod_line_set_value(relay_line, 1);
                    log_event("ON");
                } else {
                    gpiod_line_set_value(relay_line, 0);
                    log_event("OFF");
                }
            }
        }

        // Sleep for a short period to avoid high CPU usage
        usleep(100000); // 100ms
    }

    // Clean up
    fclose(log_file);
    gpiod_line_release(sensor_line);
    gpiod_line_release(relay_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

