    if (!pir_sensor) {
        perror("Failed to get PIR sensor line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    buzzer = gpiod_chip_get_line(chip, BUZZER_LINE);
    if (!buzzer) {
        perror("Failed to get buzzer line");
        gpiod_line_release(pir_sensor);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int ret = gpiod_line_request_input(pir_sensor, "pir_sensor");
    if (ret < 0) {
        perror("Failed to request PIR sensor line as input");
        gpiod_line_release(buzzer);
        gpiod_line_release(pir_sensor);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(buzzer, "buzzer", 0);
    if (ret < 0) {
        perror("Failed to request buzzer line as output");
        gpiod_line_release(pir_sensor);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(buzzer);
        gpiod_line_release(pir_sensor);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        int value = gpiod_line_get_value(pir_sensor);
        if (value < 0) {
            perror("Failed to get PIR sensor value");
            continue;
        }

        if (value == 1) {
            log_motion();
            buzzer_on();
            usleep(2000000); // 2 seconds
            buzzer_off();
        }

        usleep(100000); // 100 milliseconds
    }

    return EXIT_SUCCESS;
}

