#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 18
#define CONFIG_FILE "watering.conf"
#define MIN_DURATION 1
#define MAX_DURATION 3600

volatile sig_atomic_t stop_flag = 0;

void sigint_handler(int signum) {
    stop_flag = 1;
}

int read_duration_from_config(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open configuration file");
        return -1;
    }

    char line[256];
    if (!fgets(line, sizeof(line), file)) {
        perror("Failed to read line from configuration file");
        fclose(file);
        return -1;
    }

    fclose(file);

    char *duration_str = strchr(line, '=');
    if (!duration_str) {
        fprintf(stderr, "Malformed configuration line\n");
        return -1;
    }

    duration_str++;
    char *endptr;
    long duration = strtol(duration_str, &endptr, 10);
    if (*endptr != '\n' || duration < MIN_DURATION || duration > MAX_DURATION) {
        fprintf(stderr, "Invalid duration value: %ld\n", duration);
        return -1;
    }

    return (int)duration;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int duration;

    // Install signal handlers
    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        perror("Failed to install SIGINT handler");
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, sigint_handler) == SIG_ERR) {
        perror("Failed to install SIGTERM handler");
        return EXIT_FAILURE;
    }

    // Read duration from configuration file
    duration = read_duration_from_config(CONFIG_FILE);
    if (duration < 0) {
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure GPIO line as output with active-low = 0 and default low value
    struct gpiod_line_request_config config = {
        .consumer = "watering_system",
        .request_type = GPIOD_LINE_REQUEST_OUTPUT,
        .default_val = 0,
    };
    if (gpiod_line_request(line, &config)) {
        perror("Failed to request GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Print status message
    printf("Watering for %d seconds...\n", duration);

    // Activate the valve by setting the line high
    if (gpiod_line_set_value(line, 1)) {
        perror("Failed to set GPIO line high");
        goto cleanup;
    }

    // Wait the configured duration using a signal-safe interruptible sleep
    while (duration > 0 && !stop_flag) {
        sleep(1);
        duration--;
    }

    // Set the line low
    if (gpiod_line_set_value(line, 0)) {
        perror("Failed to set GPIO line low");
        goto cleanup;
    }

    // Print status message
    printf("Watering completed.\n");

cleanup:
    // Release GPIO line
    gpiod_line_release(line);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

