#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define RELAY_PIN 23
#define MIN_LUX 150
#define MEASUREMENT_DELAY 180

static int i2c_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *relay_line;
static FILE *log_file;

void log_event(const char *message) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    fprintf(log_file, "%ld.%03ld: %s\n", ts.tv_sec, ts.tv_nsec / 1000000, message);
    fflush(log_file);
}

void handle_sigint(int sig) {
    log_event("SIGINT received, shutting down...");
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(0);
}

int read_bh1750_lux() {
    uint8_t data[2];
    if (read(i2c_fd, data, 2) != 2) {
        log_event("Failed to read from BH1750 sensor");
        return -1;
    }
    return (data[0] << 8) | data[1];
}

int main() {
    signal(SIGINT, handle_sigint);

    // Open I2C bus
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Request relay line
    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        perror("Failed to get relay line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Configure relay line as output
    if (gpiod_line_request_output(relay_line, "grow_lamp", 0) < 0) {
        perror("Failed to request relay line as output");
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("grow_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_event("Program started");

    while (1) {
        int lux = read_bh1750_lux();
        if (lux >= 0) {
            log_event(gpiod_line_get_value(relay_line) ? "Lux: %d, Relay: ON" : "Lux: %d, Relay: OFF", lux);
            if (lux < MIN_LUX) {
                gpiod_line_set_value(relay_line, 1);
                log_event("Lux below threshold, turning on relay");
            } else {
                gpiod_line_set_value(relay_line, 0);
                log_event("Lux above threshold, turning off relay");
            }
        }
        usleep(MEASUREMENT_DELAY * 1000);
    }

    // This line should never be reached
    return EXIT_SUCCESS;
}

