#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define LOCK_BUTTON 21
#define UNLOCK_BUTTON 22
#define SERVO_PIN 18
#define DEBOUNCE_TIME 100
#define SERVO_MIN_PULSE 500
#define SERVO_MAX_PULSE 2500
#define SERVO_LOCK_PULSE 1000
#define SERVO_UNLOCK_PULSE 2000

struct gpiod_chip *chip;
struct gpiod_line *lock_button, *unlock_button, *servo;

void cleanup() {
    if (servo) {
        gpiod_line_release(servo);
    }
    if (lock_button) {
        gpiod_line_release(lock_button);
    }
    if (unlock_button) {
        gpiod_line_release(unlock_button);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    printf("Resources released.\n");
    exit(0);
}

void signal_handler(int sig) {
    cleanup();
}

int debounce(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    usleep(DEBOUNCE_TIME * 1000);
    return gpiod_line_get_value(line) == value;
}

int main() {
    struct gpiod_request_config config = {
        .consumer = "door_lock",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
    };

