#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <zmq.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE_SOUND 17
#define GPIO_LINE_ALARM 27
#define ZMQ_ADDRESS "tcp://*:5555"
#define ZMQ_TOPIC "SOUND_ALERTS"
#define ALARM_DURATION 1000000 // 1 second in microseconds

static struct gpiod_chip *chip;
static struct gpiod_line *line_sound;
static struct gpiod_line *line_alarm;
static zmq_context_t *context;
static zmq_socket_t *socket;

void cleanup() {
    if (line_sound) {
        gpiod_line_release(line_sound);
    }
    if (line_alarm) {
        gpiod_line_release(line_alarm);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (socket) {
        zmq_close(socket);
    }
    if (context) {
        zmq_ctx_destroy(context);
    }
    exit(0);
}

void signal_handler(int signum) {
    cleanup();
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <mode> (sound_sensor|alarm_node)\n", argv[0]);
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    line_sound = gpiod_chip_get_line(chip, GPIO_LINE_SOUND);
    if (!line_sound) {
        perror("Failed to get GPIO line for sound sensor");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_input(line_sound, "sound_sensor") < 0) {
        perror("Failed to request input for sound sensor");
        cleanup();
        return 1;
    }

    if (strcmp(argv[1], "sound_sensor") == 0) {
        while (1) {
            int value = gpiod_line_get_value(line_sound);
            if (value == 0) {
                zmq_msg_t msg;
                zmq_msg_init(&msg);
                zmq_msg_setstr(&msg, ZMQ_TOPIC);
                if (zmq_send(socket, &msg, 0) < 0) {
                    perror("Failed to send message");
                }
                zmq_msg_close(&msg);
            }
            usleep(10000); // 10 ms
        }
    } else if (strcmp(argv[1], "alarm_node") == 0) {
        context = zmq_ctx_new();
        if (!context) {
            perror("Failed to create ZeroMQ context");
            cleanup();
            return 1;
        }

        socket = zmq_socket(context, ZMQ_SUB);
        if (!socket) {
            perror("Failed to create ZeroMQ socket");
            cleanup();
            return 1;
        }

        if (zmq_bind(socket, ZMQ_ADDRESS) < 0) {
            perror("Failed to bind ZeroMQ socket");
            cleanup();
            return 1;
        }

        zmq_setsockopt(socket, ZMQ_SUBSCRIBE, ZMQ_TOPIC, strlen(ZMQ_TOPIC));

        while (1) {
            zmq_msg_t msg;
            zmq_msg_init(&msg);
            if (zmq_recv(socket, &msg, 0) < 0) {
                perror("Failed to receive message");
                zmq_msg_close(&msg);
                cleanup();
                return 1;
            }
            gpiod_line_set_value(line_alarm, 1);
            usleep(ALARM_DURATION);
            gpiod_line_set_value(line_alarm, 0);
            zmq_msg_close(&msg);
        }
    } else {
        fprintf(stderr, "Invalid mode: %s\n", argv[1]);
        return 1;
    }

    cleanup();
    return 0;
}

