#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <libgpiod.h>
#include <mosquitto.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define PULSE_BUFFER_SIZE 1000
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "ir/decoded"

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static int pulse_buffer[PULSE_BUFFER_SIZE];
static int pulse_count = 0;
static int running = 1;
static struct mosquitto *mosq;

static void signal_handler(int signum) {
    running = 0;
}

static void pulse_callback(void *user_data, struct gpiod_line_event *event) {
    if (event->event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
        // Ignore rising edge
    } else if (event->event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
        if (pulse_count < PULSE_BUFFER_SIZE) {
            pulse_buffer[pulse_count++] = event->timestamp.tv_nsec / 1000;
        } else {
            syslog(LOG_ERR, "Pulse buffer overflow");
        }
    }
}

static int decode_nec_command(int *pulse_buffer, int pulse_count) {
    if (pulse_count < 68) {
        syslog(LOG_ERR, "Invalid NEC frame length");
        return -1;
    }

    int address = 0, inverted_address = 0, command = 0, inverted_command = 0;
    int i = 1; // Skip initial mark

    // Decode address
    for (int j = 0; j < 8; j++) {
        address <<= 1;
        if (pulse_buffer[i++] > 1690) {
            address |= 1;
        }
    }

    // Decode inverted address
    for (int j = 0; j < 8; j++) {
        inverted_address <<= 1;
        if (pulse_buffer[i++] > 1690) {
            inverted_address |= 1;
        }
    }

    // Decode command
    for (int j = 0; j < 8; j++) {
        command <<= 1;
        if (pulse_buffer[i++] > 1690) {
            command |= 1;
        }
    }

    // Decode inverted command
    for (int j = 0; j < 8; j++) {
        inverted_command <<= 1;
        if (pulse_buffer[i++] > 1690) {
            inverted_command |= 1;
        }
    }

    // Verify checksum
    if (address != inverted_address || command != inverted_command) {
        syslog(LOG_ERR, "Checksum error");
        return -1;
    }

    return command;
}

static void publish_mqtt_command(int command) {
    char json[100];
    snprintf(json, sizeof(json), "{\"command\": %d}", command);
    mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(json), json, 0, 0);
}

int main(int argc, char *argv[]) {
    struct gpiod_line_request_config config = {
        .consumer = "ir_receiver",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
        .default_val = 0,
        .flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP,
    };

    struct mosquitto_lib_init_options opts = {
        .compatibility = MOSQ_OPT_COMPAT_DEFAULT,
        .mosquitto_version = 0,
    };

    if (mosquitto_lib_init(&opts) != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to initialize MQTT library");
        return EXIT_FAILURE;
    }

    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create MQTT client");
        mosquitto_lib_cleanup();
        return EXIT_FAILURE;
    }

    if (mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60) != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker");
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
