        syslog(LOG_ERR, "Failed to get GPIO line");
        gpiod_chip_close(chip);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(line, &config) != 0) {
        syslog(LOG_ERR, "Failed to request GPIO line");
        gpiod_chip_close(chip);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return EXIT_FAILURE;
    }

    gpiod_line_request_bulk(chip, &config, 1, NULL);

    gpiod_line_event_request(line, "ir_receiver", GPIOD_LINE_EVENT_BOTH_EDGES);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        struct gpiod_line_event event;
        if (gpiod_line_event_wait(line, NULL, &event) == 0) {
            pulse_callback(NULL, &event);
        }

        if (pulse_count >= 68) {
