#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <libgpiod.h>

#define I2C_DEVICE "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define BH1750_CMD_START_CONT_HIGH_RES 0x10
#define BH1750_CMD_MEAS_TIME 180
#define UDP_MULTICAST_PORT 5005
#define UDP_MULTICAST_GROUP "239.255.255.250"

volatile sig_atomic_t terminate = 0;

void signal_handler(int signum) {
    terminate = 1;
}

int read_bh1750(int fd, uint8_t addr) {
    uint8_t cmd = BH1750_CMD_START_CONT_HIGH_RES;
    if (write(fd, &cmd, 1) != 1) {
        perror("write");
        return -1;
    }
    usleep(BH1750_CMD_MEAS_TIME * 1000);
    uint8_t data[2];
    if (read(fd, data, 2) != 2) {
        perror("read");
        return -1;
    }
    return (data[0] << 8) | data[1];
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int i2c_fd, udp_fd;
    struct sockaddr_in udp_addr;
    char buffer[256];
    ssize_t bytes_sent;

    // Initialize GPIO for I2C
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, 2); // SDA
    if (!line) {
        perror("gpiod_chip_get_line SDA");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "i2c_sda", 0) < 0) {
        perror("gpiod_line_request_output SDA");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, 3); // SCL
    if (!line) {
        perror("gpiod_chip_get_line SCL");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "i2c_scl", 0) < 0) {
        perror("gpiod_line_request_output SCL");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initialize I2C
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initialize UDP
    udp_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_fd < 0) {
        perror("socket");
        close(i2c_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    memset(&udp_addr, 0, sizeof(udp_addr));
    udp_addr.sin_family = AF_INET;
    udp_addr.sin_port = htons(UDP_MULTICAST_PORT);
    if (inet_pton(AF_INET, UDP_MULTICAST_GROUP, &udp_addr.sin_addr) <= 0) {
        perror("inet_pton");
        close(udp_fd);
        close(i2c_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        double lux_values[4] = {0.0};
        for (int i = 0; i < 4; i++) {
            if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR + i) < 0) {
                perror("ioctl");
                lux_values[i] = NAN;
            } else {
                int lux = read_bh1750(i2c_fd, BH1750_ADDR + i);
                if (lux < 0) {
                    lux_values[i] = NAN;
                } else {
                    lux_values[i] = lux / 1.2;
                }
            }
        }

        snprintf(buffer, sizeof(buffer), "1,%.1f;2,%.1f;3,%.1f;4,%.1f", lux_values[0], lux_values[1], lux_values[2], lux_values[3]);
        bytes_sent = sendto(udp_fd, buffer, strlen(buffer), 0, (struct sockaddr *)&udp_addr, sizeof(udp_addr));
        if (bytes_sent < 0) {
            perror("sendto");
        }

        sleep(1);
    }

    // Clean up
    close(udp_fd);
    close(i2c_fd);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

