#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDRESS 0x28
#define MAX_RETRIES 3
#define RETRY_DELAY 100000 // 100 ms

FILE *log_file = NULL;
int i2c_fd = -1;

void log_flow_rate(uint16_t flow_rate) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d: %u SLPM\n",
            tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
            tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec, flow_rate);
    fflush(log_file);
}

int read_sensor_data(uint16_t *flow_rate) {
    uint8_t buffer[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (write(i2c_fd, NULL, 0) < 0) {
            perror("I2C write");
            if (errno == EAGAIN) {
                retries++;
                usleep(RETRY_DELAY);
                continue;
            }
            return -1;
        }

        if (read(i2c_fd, buffer, sizeof(buffer)) != sizeof(buffer)) {
            perror("I2C read");
            if (errno == EAGAIN) {
                retries++;
                usleep(RETRY_DELAY);
                continue;
            }
            return -1;
        }

        *flow_rate = (buffer[0] << 8) | buffer[1];
        return 0;
    }

    return -1;
}

void handle_sigint(int sig) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen("airflow_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        uint16_t flow_rate;
        if (read_sensor_data(&flow_rate) == 0) {
            flow_rate &= 0x3FFF; // Mask the 14-bit flow value
            log_flow_rate(flow_rate);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
        sleep(1);
    }

    // This point should never be reached
    close(i2c_fd);
    fclose(log_file);
    return EXIT_SUCCESS;
}

