#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <gpiod.h>

#define I2C_DEVICE "/dev/i2c-1"
#define AS7341_I2C_ADDRESS 0x49
#define AS7341_ID_REG 0x00
#define AS7341_ID_VALUE 0x10
#define AS7341_ENABLE_REG 0x01
#define AS7341_SP_EN_BIT 0x01
#define AS7341_CFG6_REG 0x06
#define AS7341_SMUX_MASK 0x0F
#define AS7341_F1_REG 0x10
#define AS7341_F8_REG 0x17
#define AS7341_CLEAR_REG 0x18
#define AS7341_NIR_REG 0x19
#define AS7341_LOG_FILE "spectral_log.csv"

#define CHECK_I2C_RESULT(result, msg) if (result < 0) { perror(msg); exit(EXIT_FAILURE); }

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *pon_line;
    int i2c_fd, log_fd;
    uint8_t id, enable, cfg6, f1, f2, f3, f4, f5, f6, f7, f8, clear, nir;
    double lux;
    char timestamp[20], log_entry[100];

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    CHECK_I2C_RESULT(i2c_fd, "Failed to open I2C device");

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, AS7341_I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Open log file
    log_fd = open(AS7341_LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Register signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Initialize GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        close(log_fd);
        exit(EXIT_FAILURE);
    }

    // Get PON line
    pon_line = gpiod_chip_get_line(chip, 17); // Assuming PON is connected to GPIO17
    if (!pon_line) {
        perror("Failed to get PON line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        close(log_fd);
        exit(EXIT_FAILURE);
    }

    // Request PON line as output
    if (gpiod_line_request_output(pon_line, "pon", 0) < 0) {
        perror("Failed to request PON line as output");
        gpiod_chip_close(chip);
        close(i2c_fd);
        close(log_fd);
        exit(EXIT_FAILURE);
    }

    // Verify sensor ID
    if (read(i2c_fd, &id, 1) != 1 || id != AS7341_ID_VALUE) {
        fprintf(stderr, "Sensor ID mismatch\n");
        gpiod_line_release(pon_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        close(log_fd);
        exit(EXIT_FAILURE);
    }

    // Power on sensor
    if (gpiod_line_set_value(pon_line, 1) < 0) {
        perror("Failed to power on sensor");
        gpiod_line_release(pon_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        close(log_fd);
        exit(EXIT_FAILURE);
    }

    // Configure SMUX
    cfg6 = 0x00; // Example configuration, adjust as needed
    if (write(i2c_fd, &cfg6, 1) != 1) {
        perror("Failed to write to CFG6 register");
        gpiod_line_release(pon_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        close(log_fd);
        exit(EXIT_FAILURE);
    }

    // Enable spectral measurement
    enable = AS7341_SP_EN_BIT;
    if (write(i2c_fd, &enable, 1) != 1) {
        perror("Failed to write to ENABLE register");
        gpiod_line_release(pon_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        close(log_fd);
        exit(EXIT_FAILURE);
    }

    while (running) {
        // Read spectral channels
        if (read(i2c_fd, &f1, 1) != 1 || read(i2c_fd, &f2, 1) != 1 || read(i2c_fd, &f3, 1) != 1 ||
            read(i2c_fd, &f4, 1) != 1 || read(i2c_fd, &f5, 1) != 1 || read(i2c_fd, &f6, 1) != 1 ||
            read(i2c_fd, &f7, 1) != 1 || read(i2c_fd, &f8, 1) != 1 || read(i2c_fd, &clear, 1) != 1 ||
            read(i2c_fd, &nir, 1) != 1) {
            perror("Failed to read spectral channels");
            continue;
        }

        // Compute lux (simplified approximation)
        lux = (f1 + f2 + f3 + f4 + f5 + f6 + f7 + f8 + clear + nir) / 10.0;

        // Get timestamp
        if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(NULL)) == 0) {
            perror("Failed to get timestamp");
            continue;
        }

        // Format log entry
        snprintf(log_entry, sizeof(log_entry), "%s,%f,%d,%d,%d,%d,%d,%d,%d,%d,%d\n",
                 timestamp, lux, f1, f2, f3, f4, f5, f6, f7, f8, clear, nir);

        // Write log entry
        if (write(log_fd, log_entry, strlen(log_entry)) != strlen(log_entry)) {
            perror("Failed to write to log file");
        }

        // Sleep for 5 seconds
        sleep(5);
    }

    // Clean up
    gpiod_line_release(pon_line);
    gpiod_chip_close(chip);
    close(i2c_fd);
    close(log_fd);

    return 0;
