This code provides a complete solution for reading spectral and lux data from an Adafruit AS7341 sensor on a Raspberry Pi 3 Model B+ using the libgpiod library. It includes error handling, resource management, and a signal handler for graceful termination.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define DEFAULT_I2C_ADDRESS 0x53
#define DEFAULT_INTERVAL 1
#define DEFAULT_FILENAME "seismic_data.csv"
#define I2C_DEVICE "/dev/i2c-1"
#define MAX_RETRIES 3
#define BACKOFF_MS 10

struct {
    int i2c_address;
    int interval;
    char *filename;
    int i2c_fd;
    FILE *csv_file;
    FILE *error_file;
} config = {
    .i2c_address = DEFAULT_I2C_ADDRESS,
    .interval = DEFAULT_INTERVAL,
    .filename = DEFAULT_FILENAME,
};

void handle_sigint(int sig) {
    close(config.i2c_fd);
    fclose(config.csv_file);
    fclose(config.error_file);
    exit(0);
}

void handle_sigterm(int sig) {
    close(config.i2c_fd);
    fclose(config.csv_file);
    fclose(config.error_file);
    exit(0);
}

int read_sensor_data(int fd, int address, uint8_t *data, size_t len) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (write(fd, &address, 1) != 1) {
            perror("write");
            retries++;
            usleep(BACKOFF_MS * 1000);
            continue;
        }
        if (read(fd, data, len) == len) {
            return 0;
        }
        perror("read");
        retries++;
        usleep(BACKOFF_MS * 1000);
    }
    return -1;
}

int main(int argc, char *argv[]) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct timespec ts;
    uint8_t data[6];
    int ret;

    // Parse command-line options
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-a") == 0 && i + 1 < argc) {
            config.i2c_address = strtol(argv[i + 1], NULL, 16);
            i++;
        } else if (strcmp(argv[i], "-i") == 0 && i + 1 < argc) {
            config.interval = atoi(argv[i + 1]);
            i++;
        } else if (strcmp(argv[i], "-f") == 0 && i + 1 < argc) {
            config.filename = argv[i + 1];
            i++;
        }
    }

    // Open I2C device
    if ((config.i2c_fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("open");
        return 1;
    }

    // Set I2C address
    if (ioctl(config.i2c_fd, I2C_SLAVE, config.i2c_address) < 0) {
        perror("ioctl");
        close(config.i2c_fd);
        return 1;
    }

    // Open CSV and error log files
    config.csv_file = fopen(config.filename, "w");
    if (!config.csv_file) {
        perror("fopen");
        close(config.i2c_fd);
        return 1;
    }
    config.error_file = fopen("seismic_error.log", "a");
    if (!config.error_file) {
        perror("fopen");
        fclose(config.csv_file);
        close(config.i2c_fd);
        return 1;
    }

    // Write CSV header
    fprintf(config.csv_file, "timestamp,x_g,y_g,z_g\n");

    // Set up signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    while (1) {
        // Read sensor data
        if (read_sensor_data(config.i2c_fd, 0x00, data, 6) < 0) {
            fprintf(config.error_file, "%ld.%06ld: I2C read error\n", ts.tv_sec, ts.tv_nsec / 1000);
            continue;
        }

        // Convert data to g
        int16_t x = (data[1] << 8) | data[0];
        int16_t y = (data[3] << 8) | data[2];
        int16_t z = (data[5] << 8) | data[4];
        float x_g = x / 32768.0f * 16.0f;
        float y_g = y / 32768.0f * 16.0f;
        float z_g = z / 32768.0f * 16.0f;

        // Get current timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
            perror("clock_gettime");
            continue;
        }

        // Write data to CSV
        fprintf(config.csv_file, "%ld.%06ld,%f,%f,%f\n", ts.tv_sec, ts.tv_nsec / 1000, x_g, y_g, z_g);

        // Flush CSV file
        fflush(config.csv_file);

        // Sleep for the configured interval
        sleep(config.interval);
    }

    // Close files and free resources
    fclose(config.csv_file);
    fclose(config.error_file);
    close(config.i2c_fd);

    return 0;
}

