#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>

#define I2C_DEVICE "/dev/i2c-1"
#define BH1750_ADDRESS 0x23
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define BUFFER_SIZE 2
#define MULTICAST_GROUP "239.255.255.250"
#define PORT 5000
#define TTL 1

int i2c_fd;
int socket_fd;
struct sockaddr_in multicast_addr;

void close_resources() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (socket_fd >= 0) {
        close(socket_fd);
    }
}

void signal_handler(int signum) {
    printf("Received signal %d, exiting...\n", signum);
    close_resources();
    exit(signum);
}

float read_light_sensor() {
    uint8_t buffer[BUFFER_SIZE];
    if (write(i2c_fd, &BH1750_CONTINUOUS_HIGH_RES_MODE, 1) != 1) {
        perror("Failed to write to BH1750");
        return -1.0;
    }
    usleep(100000); // Wait for measurement to complete
    if (read(i2c_fd, buffer, BUFFER_SIZE) != BUFFER_SIZE) {
