        perror("Failed to create socket");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Set socket options
    int optval = TTL;
    if (setsockopt(socket_fd, IPPROTO_IP, IP_MULTICAST_TTL, &optval, sizeof(optval)) < 0) {
        perror("Failed to set TTL");
        close(socket_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Set multicast address
    memset(&multicast_addr, 0, sizeof(multicast_addr));
    multicast_addr.sin_family = AF_INET;
    multicast_addr.sin_port = htons(PORT);
    if (inet_pton(AF_INET, MULTICAST_GROUP, &multicast_addr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(socket_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        float lux = read_light_sensor();
        if (lux >= 0) {
            char buffer[32];
            snprintf(buffer, sizeof(buffer), "%.2f\n", lux);
            if (sendto(socket_fd, buffer, strlen(buffer), 0, (struct sockaddr *)&multicast_addr, sizeof(multicast_addr)) < 0) {
                perror("Failed to send data");
            }
        }
        sleep(1);
    }

    close_resources();
    return EXIT_SUCCESS;
}

