#include <libgpiod.h>

#define UART_DEVICE "/dev/ttyS0"
#define BAUD_RATE 921600
#define MAGIC_WORD "\x00\x00\x00\x00\x00\x00\x00\x00"
#define TLV_HEADER_SIZE 4
#define BUFFER_SIZE 4096
#define CSV_FILE "radar_data.csv"

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int fd;
    FILE *csv_file;
    char buffer[BUFFER_SIZE];
    size_t bytes_read;
    time_t now;
    struct tm *tm_info;
    char timestamp[20];
    uint8_t magic_word[8];
    uint32_t tlv_type, tlv_length;
    uint16_t range, velocity;
    int object_index = 0;

    // Initialize UART
    fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        perror("Failed to open UART device");
        return EXIT_FAILURE;
    }

    struct termios options;
    tcgetattr(fd, &options);
    cfsetispeed(&options, B921600);
    cfsetospeed(&options, B921600);
    options.c_cflag |= (CLOCAL | CREAD);
    options.c_cflag &= ~PARENB;
    options.c_cflag &= ~CSTOPB;
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8;
    options.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    options.c_oflag &= ~OPOST;
    tcsetattr(fd, TCSANOW, &options);

    // Initialize CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        perror("Failed to open CSV file");
        close(fd);
        return EXIT_FAILURE;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        bytes_read = read(fd, buffer, BUFFER_SIZE);
        if (bytes_read == -1) {
            perror("Failed to read from UART");
            continue;
        }

        for (size_t i = 0; i < bytes_read; i++) {
            if (memcmp(buffer + i, MAGIC_WORD, 8) == 0) {
                i += 8;
                if (i + TLV_HEADER_SIZE > bytes_read) {
                    break;
                }

                memcpy(&tlv_type, buffer + i, 4);
                memcpy(&tlv_length, buffer + i + 4, 4);
                i += TLV_HEADER_SIZE;

                if (i + tlv_length > bytes_read) {
                    break;
                }

                if (tlv_type == 0x00000001) { // Assuming this is the range TLV type
                    memcpy(&range, buffer + i, 2);
                    memcpy(&velocity, buffer + i + 2, 2);
                    i += tlv_length;

                    time(&now);
                    tm_info = localtime(&now);
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

                    fprintf(csv_file, "%s,%d,%d,%d\n", timestamp, object_index, range, velocity);
                    fflush(csv_file);
                    object_index++;
                }
            }
        }
    }

    // Cleanup
    fclose(csv_file);
    close(fd);

    return EXIT_SUCCESS;
}

