#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <sys/select.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define TIMEOUT_SECONDS 2
#define INTER_BYTE_TIMEOUT 500000 // 0.5 seconds in microseconds
#define LINE_BUFFER_SIZE 256

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int open_uart(const char *device, speed_t baud_rate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        perror("Failed to open UART device");
        return -1;
    }

    struct termios options;
    if (tcgetattr(fd, &options) == -1) {
        perror("Failed to get UART attributes");
        close(fd);
        return -1;
    }

    cfsetispeed(&options, baud_rate);
    cfsetospeed(&options, baud_rate);
    options.c_cflag |= (CLOCAL | CREAD);
    options.c_cflag &= ~PARENB;
    options.c_cflag &= ~CSTOPB;
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8;
    options.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    options.c_oflag &= ~OPOST;
    options.c_cc[VMIN] = 0;
    options.c_cc[VTIME] = INTER_BYTE_TIMEOUT / 100;

    if (tcsetattr(fd, TCSANOW, &options) == -1) {
        perror("Failed to set UART attributes");
        close(fd);
        return -1;
    }

    return fd;
}

void close_uart(int fd) {
    close(fd);
}

void log_detection(const char *timestamp, float range) {
    printf("Timestamp: %s, Range: %.2f meters\n", timestamp, range);
}

int main() {
    int uart_fd = open_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd == -1) {
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to set SIGINT handler");
        close_uart(uart_fd);
        return EXIT_FAILURE;
    }

    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set SIGTERM handler");
        close_uart(uart_fd);
        return EXIT_FAILURE;
    }

    char line_buffer[LINE_BUFFER_SIZE];
    ssize_t bytes_read;
    fd_set read_fds;
    struct timeval timeout;

    while (running) {
        FD_ZERO(&read_fds);
        FD_SET(uart_fd, &read_fds);
        timeout.tv_sec = TIMEOUT_SECONDS;
        timeout.tv_usec = 0;

        int ret = select(uart_fd + 1, &read_fds, NULL, NULL, &timeout);
        if (ret == -1) {
            perror("Failed to select on UART");
            break;
        } else if (ret == 0) {
            fprintf(stderr, "Timeout: No data received from sensor\n");
            break;
        }

        bytes_read = read(uart_fd, line_buffer, sizeof(line_buffer) - 1);
        if (bytes_read == -1) {
            perror("Failed to read from UART");
            break;
        }

        line_buffer[bytes_read] = '\0';
        char *line = strdup(line_buffer);
        if (line == NULL) {
            perror("Failed to duplicate line buffer");
            break;
        }

        char *timestamp_str, *range_str;
        timestamp_str = strtok(line, ",");
        range_str = strtok(NULL, ",");

        if (timestamp_str != NULL && range_str != NULL) {
            char timestamp[20];
            if (sscanf(timestamp_str, "%ld", (long *)timestamp) == 1) {
                struct tm *tm_struct = localtime((time_t *)&timestamp);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_struct);

                float range;
                if (sscanf(range_str, "%f", &range) == 1) {
                    log_detection(timestamp, range);
                } else {
                    fprintf(stderr, "Invalid range format: %s\n", range_str);
                }
            } else {
                fprintf(stderr, "Invalid timestamp format: %s\n", timestamp_str);
            }
        } else {
            fprintf(stderr, "Invalid line format: %s\n", line);
        }

        free(line);
    }

    close_uart(uart_fd);
    return EXIT_SUCCESS;
}

