#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27
#define UART_DEVICE "/dev/ttyAMA0"
#define BAUD_RATE 115200

static struct gpiod_chip *chip;
static struct gpiod_line *left_sensor, *middle_sensor, *right_sensor;
static int uart_fd;

void cleanup_and_exit(int status) {
    if (left_sensor) gpiod_line_release(left_sensor);
    if (middle_sensor) gpiod_line_release(middle_sensor);
    if (right_sensor) gpiod_line_release(right_sensor);
    if (chip) gpiod_chip_close(chip);
    if (uart_fd >= 0) close(uart_fd);
    exit(status);
}

void signal_handler(int signum) {
    cleanup_and_exit(signum == SIGINT ? 0 : 1);
}

int main() {
    struct timespec ts;
    struct tm *tm_info;
    char timestamp[20];
    char sensor_states[4];
    char emergency_stop[] = "EMERGENCY STOP!\n";

    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        cleanup_and_exit(1);
    }

    // Request and configure left sensor
    left_sensor = gpiod_chip_get_line(chip, LEFT_SENSOR_PIN);
    if (!left_sensor) {
        perror("Failed to get left sensor line");
